(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,56677,e=>{"use strict";e.s(["migrations",0,[{name:"0001_foundation.sql",sql:"-- ============================================================================\n-- 0001 · Foundation: extensions, auth compatibility, roles, enums, helpers\n-- ----------------------------------------------------------------------------\n-- The `auth` schema mirrors the surface Supabase exposes to RLS policies, so\n-- every policy in 0003 is written once and runs unchanged against a hosted\n-- Supabase project, a plain Postgres server, or PGlite in the browser.\n-- ============================================================================\n\n-- No extensions. gen_random_uuid() has been core Postgres since 13, and\n-- case-insensitive columns are handled with lower() unique indexes rather than\n-- text, so this schema runs unchanged on Supabase, a plain server, and the\n-- WASM build that powers the browser demo — none of which share an extension set.\n\ncreate schema if not exists auth;\ncreate schema if not exists app;\n\n-- Claims are set per transaction by the data layer (see lib/db/session.ts).\ncreate or replace function auth.jwt() returns jsonb\n  language sql stable as $$\n  select coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb)\n$$;\n\ncreate or replace function auth.uid() returns uuid\n  language sql stable as $$\n  select nullif(auth.jwt() ->> 'sub', '')::uuid\n$$;\n\ncreate or replace function auth.role() returns text\n  language sql stable as $$\n  select coalesce(auth.jwt() ->> 'role', 'anon')\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Enums. Named types rather than check constraints so the TypeScript layer can\n-- generate unions from them and a bad value fails at the database boundary.\n-- ---------------------------------------------------------------------------\ncreate type app_role          as enum ('owner', 'admin', 'teacher', 'guardian', 'student');\ncreate type staff_status      as enum ('active', 'inactive');\ncreate type term_status       as enum ('draft', 'published', 'archived');\ncreate type class_visibility  as enum ('public', 'unlisted', 'private');\ncreate type session_status    as enum ('scheduled', 'cancelled', 'rescheduled', 'completed');\ncreate type enrolment_status  as enum ('active', 'left', 'cancelled');\ncreate type trial_status      as enum ('requested', 'booked', 'attended', 'missed', 'converted', 'cancelled');\ncreate type waitlist_status   as enum ('waiting', 'offered', 'accepted', 'declined', 'expired', 'withdrawn');\ncreate type attendance_status as enum ('present', 'absent', 'late', 'excused', 'trial');\ncreate type enquiry_stage     as enum ('enquiry', 'trial_requested', 'trial_booked', 'trial_attended',\n                                       'trial_missed', 'follow_up', 'enrolled', 'closed_lost');\ncreate type invoice_status    as enum ('draft', 'issued', 'part_paid', 'paid', 'void', 'refunded');\ncreate type charge_kind       as enum ('tuition', 'term_fee', 'membership', 'exam_fee', 'show_fee',\n                                       'costume', 'workshop', 'private_lesson', 'merchandise', 'other');\ncreate type pricing_model     as enum ('term', 'monthly', 'one_off', 'drop_in');\ncreate type comm_channel      as enum ('in_app', 'email', 'sms', 'push');\ncreate type comm_kind         as enum ('direct', 'class_broadcast', 'studio_announcement');\ncreate type consent_kind      as enum ('photography', 'social_media', 'medical_treatment',\n                                       'data_processing', 'marketing', 'collection_by_other');\n\n-- ---------------------------------------------------------------------------\n-- Shared trigger helpers\n-- ---------------------------------------------------------------------------\ncreate or replace function app.touch_updated_at() returns trigger\n  language plpgsql as $$\nbegin\n  new.updated_at := now();\n  return new;\nend $$;\n\n-- Database roles. `authenticated` is the role every user query runs as; RLS is\n-- what separates them. `service_role` bypasses RLS for migrations and trusted\n-- server jobs only, and is never used from client code.\ndo $$ begin\n  if not exists (select 1 from pg_roles where rolname = 'authenticated') then\n    create role authenticated nologin;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'anon') then\n    create role anon nologin;\n  end if;\n  if not exists (select 1 from pg_roles where rolname = 'service_role') then\n    create role service_role nologin bypassrls;\n  end if;\nend $$;\n\ngrant usage on schema public, auth, app to authenticated, anon, service_role;\n"},{name:"0002_core.sql",sql:"-- ============================================================================\n-- 0002 · Core tables\n-- ----------------------------------------------------------------------------\n-- Conventions\n--   * uuid primary keys, defaulted in the database\n--   * created_at / updated_at on every table; created_by where a human acted\n--   * deleted_at for soft deletion — every RLS policy filters on it, so a\n--     soft-deleted row is invisible rather than merely flagged\n--   * every tenant-scoped table carries studio_id directly. Denormalised on\n--     purpose: RLS on a deep table would otherwise need a multi-join subquery\n--     on every row, which is the usual reason RLS gets abandoned for speed.\n--   * foreign keys state their delete behaviour explicitly. Real-world records\n--     (attendance, invoices) restrict; structural children cascade.\n-- ============================================================================\n\n-- ── Tenancy ────────────────────────────────────────────────────────────────\ncreate table studio (\n  id            uuid primary key default gen_random_uuid(),\n  name          text not null check (length(trim(name)) between 2 and 120),\n  slug          text not null unique check (slug = lower(slug)),\n  timezone      text not null default 'Europe/London',\n  currency      char(3) not null default 'GBP',\n  logo_url      text,\n  brand_hue     smallint default 265 check (brand_hue between 0 and 360),\n  contact_email text,\n  contact_phone text,\n  onboarding_step  smallint not null default 0,\n  onboarded_at  timestamptz,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\n\n-- One row per human. Mirrors auth.users in Supabase; id matches the auth id.\ncreate table user_account (\n  id            uuid primary key,\n  email         text not null,\n  full_name     text not null,\n  avatar_url    text,\n  phone         text,\n  last_seen_at  timestamptz,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\n\n-- The join that makes this multi-tenant. A user may hold roles in several\n-- studios; every policy resolves access through here.\ncreate table membership (\n  id          uuid primary key default gen_random_uuid(),\n  user_id     uuid not null references user_account(id) on delete cascade,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  role        app_role not null,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  unique (user_id, studio_id, role)\n);\n\ncreate table location (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  name        text not null,\n  address_line1 text, address_line2 text, city text, postcode text,\n  notes       text,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate table room (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  location_id uuid not null references location(id) on delete cascade,\n  name        text not null,\n  capacity    smallint check (capacity > 0),\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate table staff_member (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  user_id       uuid references user_account(id) on delete set null,\n  display_name  text not null,\n  email         text,\n  phone         text,\n  bio           text,\n  colour        text,\n  status        staff_status not null default 'active',\n  dbs_checked_on date,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\n\n-- ── People ─────────────────────────────────────────────────────────────────\ncreate table family (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  name          text not null,\n  address_line1 text, address_line2 text, city text, postcode text,\n  notes         text,\n  balance_minor bigint not null default 0,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  created_by    uuid references user_account(id) on delete set null,\n  deleted_at    timestamptz\n);\n\ncreate table guardian (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  family_id     uuid not null references family(id) on delete cascade,\n  user_id       uuid references user_account(id) on delete set null,\n  full_name     text not null,\n  email         text,\n  phone         text,\n  relationship  text,\n  is_primary    boolean not null default false,\n  receives_billing boolean not null default true,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\n\ncreate table student (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  family_id     uuid not null references family(id) on delete restrict,\n  first_name    text not null,\n  last_name     text not null,\n  preferred_name text,\n  date_of_birth date not null,\n  pronouns      text,\n  avatar_url    text,\n  school        text,\n  joined_on     date not null default current_date,\n  left_on       date,\n  notes         text,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  created_by    uuid references user_account(id) on delete set null,\n  deleted_at    timestamptz\n);\n\n-- Held apart from `student` deliberately. Health data is special-category\n-- under UK GDPR; separating it lets RLS grant the roster without the medical\n-- detail, and lets the audit trigger watch one narrow table.\ncreate table medical_record (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  student_id    uuid not null unique references student(id) on delete cascade,\n  allergies     text,\n  conditions    text,\n  medications   text,\n  action_plan   text,          -- what a teacher must do in an emergency\n  requires_alert boolean not null default false,\n  doctor_name   text,\n  doctor_phone  text,\n  updated_by    uuid references user_account(id) on delete set null,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\n\ncreate table emergency_contact (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  full_name   text not null,\n  relationship text,\n  phone       text not null,\n  priority    smallint not null default 1,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate table consent_record (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  kind        consent_kind not null,\n  granted     boolean not null,\n  granted_by  uuid references user_account(id) on delete set null,\n  granted_at  timestamptz not null default now(),\n  expires_at  timestamptz,\n  note        text,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  unique (student_id, kind)\n);\n"},{name:"0003_curriculum.sql",sql:"-- ============================================================================\n-- 0003 · Curriculum and scheduling\n-- ============================================================================\n\ncreate table term (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  name        text not null,\n  starts_on   date not null,\n  ends_on     date not null,\n  status      term_status not null default 'draft',\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  check (ends_on >= starts_on)\n);\n\n-- Half-terms, bank holidays, studio closures. Session generation skips these.\ncreate table term_break (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  term_id     uuid not null references term(id) on delete cascade,\n  name        text not null,\n  starts_on   date not null,\n  ends_on     date not null,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  check (ends_on >= starts_on)\n);\n\ncreate table dance_style (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  name        text not null,\n  colour      text not null default 'violet',\n  sort_order  smallint not null default 0,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate table level (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  name        text not null,\n  sort_order  smallint not null default 0,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate table class (\n  id             uuid primary key default gen_random_uuid(),\n  studio_id      uuid not null references studio(id) on delete cascade,\n  term_id        uuid not null references term(id) on delete restrict,\n  dance_style_id uuid references dance_style(id) on delete set null,\n  level_id       uuid references level(id) on delete set null,\n  location_id    uuid not null references location(id) on delete restrict,\n  room_id        uuid references room(id) on delete set null,\n  teacher_id     uuid references staff_member(id) on delete set null,\n  assistant_id   uuid references staff_member(id) on delete set null,\n  name           text not null,\n  description    text,\n  day_of_week    smallint not null check (day_of_week between 0 and 6),  -- 0 = Sunday\n  start_time     time not null,\n  duration_min   smallint not null check (duration_min between 15 and 300),\n  capacity       smallint not null check (capacity > 0),\n  age_min        smallint check (age_min >= 0),\n  age_max        smallint check (age_max >= 0),\n  price_minor    integer not null default 0 check (price_minor >= 0),\n  pricing        pricing_model not null default 'term',\n  trial_price_minor integer check (trial_price_minor >= 0),\n  trials_enabled boolean not null default true,\n  trial_needs_approval boolean not null default false,\n  waitlist_enabled boolean not null default true,\n  visibility     class_visibility not null default 'public',\n  prerequisites  text,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now(),\n  created_by     uuid references user_account(id) on delete set null,\n  deleted_at     timestamptz,\n  check (age_max is null or age_min is null or age_max >= age_min),\n  check (assistant_id is null or assistant_id <> teacher_id)\n);\n\n-- One row per occurrence. Attendance hangs off the session, not the class, so\n-- a cancelled week or a one-off room change is a fact about that week only.\ncreate table class_session (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  class_id      uuid not null references class(id) on delete cascade,\n  starts_at     timestamptz not null,\n  ends_at       timestamptz not null,\n  status        session_status not null default 'scheduled',\n  -- Per-session overrides. Null means \"inherit from the class\".\n  room_id       uuid references room(id) on delete set null,\n  teacher_id    uuid references staff_member(id) on delete set null,\n  cancel_reason text,\n  notes         text,\n  register_closed_at timestamptz,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz,\n  check (ends_at > starts_at)\n);\n"},{name:"0004_enrolment.sql",sql:"-- ============================================================================\n-- 0004 · Enrolment, trials, waitlists, attendance\n-- ----------------------------------------------------------------------------\n-- Schema decision: the enquiry funnel lives in its own table rather than as\n-- extra values on enrolment.status. A person at \"enquiry\" or \"trial booked\"\n-- has no place in a class, and modelling them as enrolments would corrupt\n-- every capacity count, waitlist calculation and register in the system.\n-- `enquiry` also has to exist before a Family does, which an enrolment cannot.\n-- ============================================================================\n\ncreate table enrolment (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  class_id     uuid not null references class(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  status       enrolment_status not null default 'active',\n  started_on   date not null default current_date,\n  ended_on     date,\n  price_minor  integer check (price_minor >= 0),   -- null = inherit class price\n  note         text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  created_by   uuid references user_account(id) on delete set null,\n  deleted_at   timestamptz\n);\n\n-- A student may hold only one live place in a class at a time. Partial index\n-- so a student who left can be re-enrolled later without tripping over history.\ncreate unique index enrolment_one_active_place\n  on enrolment (class_id, student_id)\n  where status = 'active' and deleted_at is null;\n\ncreate table trial (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  class_id     uuid not null references class(id) on delete cascade,\n  session_id   uuid references class_session(id) on delete set null,\n  student_id   uuid references student(id) on delete cascade,\n  enquiry_id   uuid,                                  -- fk added after enquiry\n  status       trial_status not null default 'requested',\n  price_minor  integer check (price_minor >= 0),\n  attended_at  timestamptz,\n  outcome_note text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  created_by   uuid references user_account(id) on delete set null,\n  deleted_at   timestamptz,\n  check (student_id is not null or enquiry_id is not null)\n);\n\ncreate table waitlist_entry (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  class_id     uuid not null references class(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  status       waitlist_status not null default 'waiting',\n  position     integer not null,\n  offered_at   timestamptz,\n  offer_expires_at timestamptz,      -- reserved for automatic offers\n  responded_at timestamptz,\n  note         text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\ncreate unique index waitlist_one_live_entry\n  on waitlist_entry (class_id, student_id)\n  where status in ('waiting', 'offered') and deleted_at is null;\n\ncreate table enquiry (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  stage         enquiry_stage not null default 'enquiry',\n  -- Free-text until the prospect becomes a real Family/Student record.\n  contact_name  text not null,\n  contact_email text,\n  contact_phone text,\n  child_name    text,\n  child_dob     date,\n  interest_class_id uuid references class(id) on delete set null,\n  interest_style_id uuid references dance_style(id) on delete set null,\n  source        text,\n  family_id     uuid references family(id) on delete set null,\n  student_id    uuid references student(id) on delete set null,\n  enrolment_id  uuid references enrolment(id) on delete set null,\n  closed_reason text,\n  next_action_on date,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  created_by    uuid references user_account(id) on delete set null,\n  deleted_at    timestamptz\n);\n\nalter table trial add constraint trial_enquiry_fk\n  foreign key (enquiry_id) references enquiry(id) on delete cascade;\n\ncreate table attendance_record (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  session_id   uuid not null references class_session(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  status       attendance_status not null,\n  reason       text,\n  reported_by_guardian boolean not null default false,\n  marked_by    uuid references user_account(id) on delete set null,\n  marked_at    timestamptz not null default now(),\n  -- Set by the client when a register is taken offline; lets a later sync\n  -- resolve conflicts by intent rather than by whichever write landed last.\n  client_marked_at timestamptz,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz,\n  unique (session_id, student_id)\n);\n"},{name:"0005_billing_comms.sql",sql:"-- ============================================================================\n-- 0005 · Billing ledger, communications, notifications, audit\n-- ----------------------------------------------------------------------------\n-- Billing is modelled in full but not implemented in this iteration (deferred\n-- by agreement). The shape matters now because family balance, invoice items\n-- and refunds are painful to retrofit. No card data is stored anywhere: the\n-- payment table holds a provider reference only.\n-- ============================================================================\n\ncreate table invoice (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  family_id     uuid not null references family(id) on delete restrict,\n  term_id       uuid references term(id) on delete set null,\n  number        text not null,\n  status        invoice_status not null default 'draft',\n  issued_on     date,\n  due_on        date,\n  subtotal_minor bigint not null default 0,\n  discount_minor bigint not null default 0,\n  total_minor    bigint not null default 0,\n  paid_minor     bigint not null default 0,\n  note          text,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  created_by    uuid references user_account(id) on delete set null,\n  deleted_at    timestamptz,\n  unique (studio_id, number)\n);\n\ncreate table invoice_item (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  invoice_id   uuid not null references invoice(id) on delete cascade,\n  student_id   uuid references student(id) on delete set null,\n  class_id     uuid references class(id) on delete set null,\n  kind         charge_kind not null default 'tuition',\n  description  text not null,\n  quantity     numeric(8,2) not null default 1 check (quantity > 0),\n  unit_minor   integer not null check (unit_minor >= 0),\n  discount_minor integer not null default 0 check (discount_minor >= 0),\n  total_minor  bigint generated always as\n                 (round(quantity * unit_minor)::bigint - discount_minor) stored,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\ncreate table payment (\n  id            uuid primary key default gen_random_uuid(),\n  studio_id     uuid not null references studio(id) on delete cascade,\n  family_id     uuid not null references family(id) on delete restrict,\n  invoice_id    uuid references invoice(id) on delete set null,\n  amount_minor  bigint not null,\n  method        text not null default 'card',\n  -- Provider handle only. Never a PAN, never a CVC, never a raw token.\n  provider      text,\n  provider_ref  text,\n  failure_code  text,\n  succeeded_at  timestamptz,\n  refunded_minor bigint not null default 0,\n  created_at    timestamptz not null default now(),\n  updated_at    timestamptz not null default now(),\n  deleted_at    timestamptz\n);\n\n-- ── Communications ─────────────────────────────────────────────────────────\ncreate table communication (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  kind         comm_kind not null default 'direct',\n  channel      comm_channel not null default 'in_app',\n  family_id    uuid references family(id) on delete cascade,\n  class_id     uuid references class(id) on delete cascade,\n  subject      text,\n  body         text not null,\n  sent_by      uuid references user_account(id) on delete set null,\n  sent_at      timestamptz not null default now(),\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz,\n  -- A direct message needs a family; a class broadcast needs a class.\n  check ((kind = 'direct' and family_id is not null)\n      or (kind = 'class_broadcast' and class_id is not null)\n      or (kind = 'studio_announcement'))\n);\n\ncreate table communication_read (\n  id            uuid primary key default gen_random_uuid(),\n  communication_id uuid not null references communication(id) on delete cascade,\n  user_id       uuid not null references user_account(id) on delete cascade,\n  read_at       timestamptz not null default now(),\n  unique (communication_id, user_id)\n);\n\ncreate table communication_template (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  name        text not null,\n  subject     text,\n  body        text not null,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate table notification (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  user_id     uuid not null references user_account(id) on delete cascade,\n  kind        text not null,\n  title       text not null,\n  body        text,\n  href        text,\n  read_at     timestamptz,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\n-- ── Audit ──────────────────────────────────────────────────────────────────\n-- Append only. No update or delete policy exists for any role, so the trail\n-- cannot be rewritten from the application at all.\ncreate table audit_log (\n  id          bigserial primary key,\n  studio_id   uuid references studio(id) on delete set null,\n  actor_id    uuid references user_account(id) on delete set null,\n  action      text not null,\n  entity      text not null,\n  entity_id   uuid,\n  summary     text,\n  at          timestamptz not null default now()\n);\n"},{name:"0006_rls.sql",sql:"-- ============================================================================\n-- 0006 · Row level security\n-- ----------------------------------------------------------------------------\n-- Model\n--   * every query runs as the `authenticated` role, never as a table owner\n--   * FORCE row level security so even the owning role is subject to policy —\n--     without it the browser demo (which owns its own database) would silently\n--     bypass every rule here and prove nothing\n--   * access resolves through membership; there is no \"current studio\" global,\n--     so a user with two studios cannot leak one into the other\n--   * helper functions are SECURITY DEFINER with a pinned search_path. They\n--     read only the caller's own rows, and exist so a policy is one indexed\n--     lookup rather than a correlated join evaluated per row\n-- ============================================================================\n\n-- NOTE ON `for all` WRITE POLICIES\n-- Permissive policies are OR-ed, and `for all` covers SELECT too. A write\n-- policy whose USING clause omitted `deleted_at is null` therefore re-exposed\n-- soft-deleted rows through the back door, regardless of what the read policy\n-- said. USING is evaluated against the OLD row, so adding the condition here\n-- closes that hole while still allowing a row to be soft-deleted.\n-- (A RESTRICTIVE select policy looks tidier but cannot be used: Postgres\n-- applies it to the NEW row on UPDATE, which makes soft deletion impossible.)\n\ncreate or replace function app.memberships()\n  returns table (studio_id uuid, role app_role)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select m.studio_id, m.role\n    from membership m\n   where m.user_id = auth.uid() and m.deleted_at is null\n$$;\n\ncreate or replace function app.studio_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select distinct studio_id from app.memberships()\n$$;\n\ncreate or replace function app.has_role(p_studio uuid, variadic p_roles app_role[])\n  returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from app.memberships() m\n                  where m.studio_id = p_studio and m.role = any(p_roles))\n$$;\n\ncreate or replace function app.is_admin(p_studio uuid) returns boolean\n  language sql stable as $$ select app.has_role(p_studio, 'owner', 'admin') $$;\n\ncreate or replace function app.is_staff(p_studio uuid) returns boolean\n  language sql stable as $$ select app.has_role(p_studio, 'owner', 'admin', 'teacher') $$;\n\n-- Families this user is a guardian of.\ncreate or replace function app.guardian_family_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select g.family_id from guardian g\n   where g.user_id = auth.uid() and g.deleted_at is null\n$$;\n\n-- Classes this user teaches or assists.\ncreate or replace function app.teacher_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id from class c\n    join staff_member s on s.id in (c.teacher_id, c.assistant_id)\n   where s.user_id = auth.uid() and s.deleted_at is null and c.deleted_at is null\n$$;\n\n-- Students a teacher may legitimately see: enrolled in, or trialling, one of\n-- their classes. Nothing wider.\ncreate or replace function app.teacher_student_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select e.student_id from enrolment e\n   where e.class_id in (select app.teacher_class_ids())\n     and e.status = 'active' and e.deleted_at is null\n  union\n  select t.student_id from trial t\n   where t.class_id in (select app.teacher_class_ids())\n     and t.student_id is not null and t.deleted_at is null\n     and t.status in ('booked', 'attended')\n$$;\n\n-- Students in the current user's own family.\ncreate or replace function app.guardian_student_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id from student s\n   where s.family_id in (select app.guardian_family_ids()) and s.deleted_at is null\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Enable + force RLS on every tenant table\n-- ---------------------------------------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array[\n    'studio','user_account','membership','location','room','staff_member',\n    'family','guardian','student','medical_record','emergency_contact','consent_record',\n    'term','term_break','dance_style','level','class','class_session',\n    'enrolment','trial','waitlist_entry','enquiry','attendance_record',\n    'invoice','invoice_item','payment','communication','communication_read',\n    'communication_template','notification','audit_log'\n  ] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n  end loop;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Studio-wide reference data: readable by any member, writable by admins.\n-- ---------------------------------------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['location','room','term','term_break','dance_style',\n                           'level','communication_template'] loop\n    execute format($f$\n      create policy %1$s_read on %1$I for select\n        using (deleted_at is null and studio_id in (select app.studio_ids()));\n      create policy %1$s_write on %1$I for all\n        using (deleted_at is null and studio_id in (select app.studio_ids()) and app.is_admin(studio_id))\n        with check (studio_id in (select app.studio_ids()) and app.is_admin(studio_id));\n    $f$, t);\n  end loop;\nend $$;\n\n-- ── Studio, users, membership ──────────────────────────────────────────────\ncreate policy studio_read on studio for select\n  using (deleted_at is null and id in (select app.studio_ids()));\ncreate policy studio_write on studio for update\n  using (app.has_role(id, 'owner')) with check (app.has_role(id, 'owner'));\n\n-- A user always sees their own record; staff see other users in their studio.\ncreate policy user_self on user_account for select\n  using (deleted_at is null and (\n    id = auth.uid()\n    or exists (select 1 from membership m\n                where m.user_id = user_account.id and m.deleted_at is null\n                  and app.is_staff(m.studio_id))));\ncreate policy user_self_update on user_account for update\n  using (id = auth.uid()) with check (id = auth.uid());\n\ncreate policy membership_read on membership for select\n  using (deleted_at is null and (user_id = auth.uid() or app.is_admin(studio_id)));\ncreate policy membership_write on membership for all\n  using (deleted_at is null and app.has_role(studio_id, 'owner')) with check (app.has_role(studio_id, 'owner'));\n\ncreate policy staff_read on staff_member for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and app.is_staff(studio_id));\ncreate policy staff_write on staff_member for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\n-- ── Families and students ──────────────────────────────────────────────────\ncreate policy family_read on family for select\n  using (deleted_at is null and (\n    (app.is_admin(studio_id))\n    or id in (select app.guardian_family_ids())));\ncreate policy family_admin_write on family for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy family_guardian_update on family for update\n  using (id in (select app.guardian_family_ids()))\n  with check (id in (select app.guardian_family_ids()));\n\ncreate policy guardian_read on guardian for select\n  using (deleted_at is null and (\n    app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\ncreate policy guardian_admin_write on guardian for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy guardian_self_update on guardian for update\n  using (family_id in (select app.guardian_family_ids()))\n  with check (family_id in (select app.guardian_family_ids()));\n\n-- Teachers see a student only through a class they actually teach.\ncreate policy student_read on student for select\n  using (deleted_at is null and (\n    app.is_admin(studio_id)\n    or (app.has_role(studio_id, 'teacher') and id in (select app.teacher_student_ids()))\n    or family_id in (select app.guardian_family_ids())));\ncreate policy student_admin_write on student for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\ncreate policy emergency_read on emergency_contact for select\n  using (deleted_at is null and (\n    app.is_admin(studio_id)\n    or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()))\n    or student_id in (select app.guardian_student_ids())));\ncreate policy emergency_write on emergency_contact for all\n  using (deleted_at is null and (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())))\n  with check (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()));\n\n-- Health data. Deliberately NOT readable by teachers through this table —\n-- they get the narrow safety brief view below instead.\ncreate policy medical_read on medical_record for select\n  using (deleted_at is null and (\n    app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())));\ncreate policy medical_write on medical_record for all\n  using (deleted_at is null and (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())))\n  with check (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()));\n\ncreate policy consent_read on consent_record for select\n  using (deleted_at is null and (\n    app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())));\ncreate policy consent_write on consent_record for all\n  using (deleted_at is null and (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())))\n  with check (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()));\n"},{name:"0007_rls_operations.sql",sql:"-- ============================================================================\n-- 0007 · RLS for scheduling, enrolment, attendance, billing, comms\n-- ============================================================================\n\n-- NOTE ON `for all` WRITE POLICIES\n-- Permissive policies are OR-ed, and `for all` covers SELECT too. A write\n-- policy whose USING clause omitted `deleted_at is null` therefore re-exposed\n-- soft-deleted rows through the back door, regardless of what the read policy\n-- said. USING is evaluated against the OLD row, so adding the condition here\n-- closes that hole while still allowing a row to be soft-deleted.\n-- (A RESTRICTIVE select policy looks tidier but cannot be used: Postgres\n-- applies it to the NEW row on UPDATE, which makes soft deletion impossible.)\n\n-- ── Classes and sessions ───────────────────────────────────────────────────\n-- Guardians see a class if their child is in it, trialling it, waitlisted for\n-- it, or if it is publicly listed (so they can browse and book a trial).\ncreate policy class_read on class for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_staff(studio_id)\n    or visibility = 'public'\n    or exists (select 1 from enrolment e\n                where e.class_id = class.id and e.deleted_at is null\n                  and e.student_id in (select app.guardian_student_ids()))));\ncreate policy class_write on class for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\ncreate policy session_read on class_session for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or class_id in (select app.teacher_class_ids())\n    or exists (select 1 from enrolment e\n                where e.class_id = class_session.class_id and e.deleted_at is null\n                  and e.student_id in (select app.guardian_student_ids()))\n    or exists (select 1 from trial t\n                where t.session_id = class_session.id and t.deleted_at is null\n                  and t.student_id in (select app.guardian_student_ids()))));\ncreate policy session_admin_write on class_session for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n-- A teacher may annotate or close their own session, not create or delete one.\ncreate policy session_teacher_update on class_session for update\n  using (class_id in (select app.teacher_class_ids()))\n  with check (class_id in (select app.teacher_class_ids()));\n\n-- ── Enrolment, trials, waitlists, enquiries ────────────────────────────────\ncreate policy enrolment_read on enrolment for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or class_id in (select app.teacher_class_ids())\n    or student_id in (select app.guardian_student_ids())));\ncreate policy enrolment_write on enrolment for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\ncreate policy trial_read on trial for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or class_id in (select app.teacher_class_ids())\n    or student_id in (select app.guardian_student_ids())));\ncreate policy trial_admin_write on trial for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n-- A guardian may request a trial for their own child.\ncreate policy trial_guardian_insert on trial for insert\n  with check (student_id in (select app.guardian_student_ids())\n              and status in ('requested', 'booked'));\n\ncreate policy waitlist_read on waitlist_entry for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or class_id in (select app.teacher_class_ids())\n    or student_id in (select app.guardian_student_ids())));\ncreate policy waitlist_admin_write on waitlist_entry for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy waitlist_guardian_insert on waitlist_entry for insert\n  with check (student_id in (select app.guardian_student_ids()) and status = 'waiting');\n\ncreate policy enquiry_rw on enquiry for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\n-- ── Attendance ─────────────────────────────────────────────────────────────\n-- Teachers write registers for their own classes. Guardians may read their own\n-- child's attendance but never write it — reporting an absence in advance goes\n-- through a request, not a direct register edit.\ncreate policy attendance_read on attendance_record for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or exists (select 1 from class_session cs\n                where cs.id = attendance_record.session_id\n                  and cs.class_id in (select app.teacher_class_ids()))\n    or student_id in (select app.guardian_student_ids())));\ncreate policy attendance_admin_write on attendance_record for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy attendance_teacher_write on attendance_record for all\n  using (deleted_at is null and exists (select 1 from class_session cs\n                  where cs.id = attendance_record.session_id\n                    and cs.class_id in (select app.teacher_class_ids())))\n  with check (exists (select 1 from class_session cs\n                       where cs.id = attendance_record.session_id\n                         and cs.class_id in (select app.teacher_class_ids())));\n\n-- ── Billing. Guardians read their own; only admins write. ──────────────────\ncreate policy invoice_read on invoice for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\ncreate policy invoice_write on invoice for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\ncreate policy invoice_item_read on invoice_item for select\n  using (deleted_at is null and (\n    app.is_admin(studio_id)\n    or exists (select 1 from invoice i where i.id = invoice_item.invoice_id\n                and i.family_id in (select app.guardian_family_ids()))));\ncreate policy invoice_item_write on invoice_item for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\ncreate policy payment_read on payment for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\ncreate policy payment_write on payment for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\n-- ── Communications and notifications ───────────────────────────────────────\ncreate policy comm_read on communication for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_staff(studio_id)\n    or kind = 'studio_announcement'\n    or family_id in (select app.guardian_family_ids())\n    or (kind = 'class_broadcast' and exists (\n          select 1 from enrolment e where e.class_id = communication.class_id\n            and e.deleted_at is null\n            and e.student_id in (select app.guardian_student_ids())))));\ncreate policy comm_staff_write on communication for all\n  using (deleted_at is null and app.is_staff(studio_id)) with check (app.is_staff(studio_id));\ncreate policy comm_guardian_insert on communication for insert\n  with check (kind = 'direct' and family_id in (select app.guardian_family_ids()));\n\ncreate policy comm_read_marker on communication_read for all\n  using (user_id = auth.uid()) with check (user_id = auth.uid());\n\ncreate policy notification_own on notification for select\n  using (deleted_at is null and user_id = auth.uid());\ncreate policy notification_own_update on notification for update\n  using (user_id = auth.uid()) with check (user_id = auth.uid());\n\n-- ── Audit log: readable by owners, insertable by anyone acting, never\n--    updatable or deletable by any role. ─────────────────────────────────────\ncreate policy audit_read on audit_log for select\n  using (studio_id is not null and app.has_role(studio_id, 'owner'));\ncreate policy audit_insert on audit_log for insert\n  with check (studio_id in (select app.studio_ids()));\n\n-- ---------------------------------------------------------------------------\n-- The teacher's safety brief.\n-- A SECURITY DEFINER view: teachers cannot read medical_record directly, but\n-- may see the few fields needed to keep a child safe in the room, and only for\n-- children in their own classes. Diagnoses, medication lists and doctor\n-- details are not exposed here — data minimisation in practice, not in prose.\n-- ---------------------------------------------------------------------------\ncreate view student_safety_brief\n  with (security_invoker = false) as\nselect s.id            as student_id,\n       s.studio_id,\n       s.first_name,\n       s.last_name,\n       m.allergies,\n       m.action_plan,\n       m.requires_alert,\n       (select ec.full_name from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_name,\n       (select ec.phone from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_phone\n  from student s\n  left join medical_record m on m.student_id = s.id and m.deleted_at is null\n where s.deleted_at is null\n   and (app.is_admin(s.studio_id)\n        or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))\n        or s.id in (select app.guardian_student_ids()));\n\ngrant select on student_safety_brief to authenticated;\ngrant select, insert, update, delete on all tables in schema public to authenticated;\ngrant usage, select on all sequences in schema public to authenticated;\nrevoke insert, update, delete on audit_log from authenticated;\ngrant insert on audit_log to authenticated;\n\n-- The trusted role used by migrations, seeds and future server-side jobs.\n-- BYPASSRLS removes the policies but not the grants, so it needs both.\ngrant select, insert, update, delete on all tables in schema public to service_role;\ngrant usage, select on all sequences in schema public to service_role;\ngrant select on student_safety_brief to service_role;\n"},{name:"0008_logic.sql",sql:"-- ============================================================================\n-- 0008 · Business rules enforced in the database\n-- ----------------------------------------------------------------------------\n-- Capacity, waitlist ordering and the audit trail live here rather than only\n-- in application code. A rule that matters is a rule that must hold no matter\n-- which client wrote the row.\n-- ============================================================================\n\n-- Counting must see every row, not the caller's RLS-filtered slice, or a class\n-- would appear to have space simply because the reader cannot see who is in it.\ncreate or replace function app.class_enrolled_count(p_class uuid) returns integer\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select count(*)::int from enrolment\n   where class_id = p_class and status = 'active' and deleted_at is null\n$$;\n\ncreate or replace function app.class_waitlist_count(p_class uuid) returns integer\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select count(*)::int from waitlist_entry\n   where class_id = p_class and status in ('waiting','offered') and deleted_at is null\n$$;\n\ncreate or replace function app.enforce_capacity() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cap integer; taken integer;\nbegin\n  if new.status <> 'active' or new.deleted_at is not null then return new; end if;\n  if tg_op = 'UPDATE' and old.status = 'active' and old.class_id = new.class_id then\n    return new;                              -- already counted, not a new place\n  end if;\n  select capacity into cap from class where id = new.class_id;\n  if cap is null then return new; end if;\n  select count(*) into taken from enrolment\n   where class_id = new.class_id and status = 'active' and deleted_at is null\n     and id <> new.id;\n  if taken >= cap then\n    raise exception 'CLASS_FULL: class % is at capacity (%/%)', new.class_id, taken, cap\n      using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\n\ncreate trigger enrolment_capacity\n  before insert or update on enrolment\n  for each row execute function app.enforce_capacity();\n\n-- Waitlist positions are assigned by the database so two simultaneous joins\n-- cannot both claim position 4.\ncreate or replace function app.assign_waitlist_position() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.position is null or new.position = 0 then\n    select coalesce(max(position), 0) + 1 into new.position\n      from waitlist_entry\n     where class_id = new.class_id and deleted_at is null;\n  end if;\n  return new;\nend $$;\n\ncreate trigger waitlist_position\n  before insert on waitlist_entry\n  for each row execute function app.assign_waitlist_position();\n\n-- ---------------------------------------------------------------------------\n-- Session generation. Produces one class_session per matching date in the\n-- term, skipping breaks. Times are built in the studio's own timezone so an\n-- 18:00 class stays at 18:00 across a daylight-saving change.\n-- ---------------------------------------------------------------------------\ncreate or replace function app.generate_class_sessions(p_class uuid)\n  returns integer\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  c record; tz text; made integer := 0; d date;\nbegin\n  select cl.*, t.starts_on, t.ends_on into c\n    from class cl join term t on t.id = cl.term_id\n   where cl.id = p_class and cl.deleted_at is null;\n  if not found then return 0; end if;\n\n  select timezone into tz from studio where id = c.studio_id;\n\n  for d in\n    select gs::date from generate_series(c.starts_on, c.ends_on, interval '1 day') gs\n     where extract(dow from gs) = c.day_of_week\n       and not exists (select 1 from term_break b\n                        where b.term_id = c.term_id and b.deleted_at is null\n                          and gs::date between b.starts_on and b.ends_on)\n  loop\n    insert into class_session (studio_id, class_id, starts_at, ends_at)\n    values (\n      c.studio_id, c.id,\n      ((d + c.start_time) at time zone tz),\n      ((d + c.start_time + make_interval(mins => c.duration_min)) at time zone tz)\n    )\n    on conflict do nothing;\n    made := made + 1;\n  end loop;\n  return made;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- updated_at on every table that has the column\n-- ---------------------------------------------------------------------------\ndo $$\ndeclare t text;\nbegin\n  for t in select table_name from information_schema.columns\n            where table_schema = 'public' and column_name = 'updated_at'\n  loop\n    execute format(\n      'create trigger %1$s_touch before update on %1$I\n         for each row execute function app.touch_updated_at()', t);\n  end loop;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Audit trail on the tables where \"who changed this, and when\" actually\n-- matters: health data, consent, enrolment, payments and staff access.\n-- ---------------------------------------------------------------------------\ncreate or replace function app.write_audit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare rec record; sid uuid;\nbegin\n  rec := coalesce(new, old);\n  begin sid := rec.studio_id; exception when others then sid := null; end;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), lower(tg_op), tg_table_name, rec.id,\n          case tg_op when 'DELETE' then 'removed' when 'INSERT' then 'created'\n                     else 'updated' end);\n  return rec;\nend $$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['medical_record','consent_record','enrolment',\n                           'payment','membership','staff_member'] loop\n    execute format(\n      'create trigger %1$s_audit after insert or update or delete on %1$I\n         for each row execute function app.write_audit()', t);\n  end loop;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Soft deletion\n-- ---------------------------------------------------------------------------\n-- Under FORCE row level security Postgres requires the row produced by an\n-- UPDATE to still satisfy the table's SELECT policies. Since those policies\n-- hide `deleted_at is not null`, a plain `update ... set deleted_at = now()`\n-- is rejected: the writer would no longer be able to see what they just wrote.\n--\n-- The tempting fix is to stop hiding deleted rows in the policy and filter in\n-- application queries instead — which moves a security guarantee out of the\n-- database and into whichever query someone writes next. Instead deletion goes\n-- through one authorised, audited entry point. The caller's rights are checked\n-- explicitly here precisely because SECURITY DEFINER bypasses RLS.\ncreate or replace function app.soft_delete(p_table text, p_id uuid)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid;\n  allowed constant text[] := array[\n    'family','guardian','student','emergency_contact','consent_record','medical_record',\n    'location','room','staff_member','term','term_break','dance_style','level',\n    'class','class_session','enrolment','trial','waitlist_entry','enquiry',\n    'invoice','invoice_item','communication','communication_template','notification'];\nbegin\n  if not (p_table = any(allowed)) then\n    raise exception 'SOFT_DELETE_UNSUPPORTED: %', p_table using errcode = 'feature_not_supported';\n  end if;\n\n  execute format('select studio_id from %I where id = $1 and deleted_at is null', p_table)\n    into sid using p_id;\n  if sid is null then return false; end if;         -- absent or already deleted\n\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: soft delete requires owner or admin' using errcode = 'insufficient_privilege';\n  end if;\n\n  execute format('update %I set deleted_at = now() where id = $1', p_table) using p_id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'soft_delete', p_table, p_id, 'soft deleted');\n  return true;\nend $$;\n\nrevoke all on function app.soft_delete(text, uuid) from public;\ngrant execute on function app.soft_delete(text, uuid) to authenticated, service_role;\n"},{name:"0009_indexes.sql",sql:'-- ============================================================================\n-- 0009 · Indexes\n-- ----------------------------------------------------------------------------\n-- Every RLS policy filters on studio_id, so it leads most composite indexes.\n-- Partial indexes exclude soft-deleted rows, which is what every query wants.\n-- ============================================================================\ncreate index membership_user       on membership (user_id) where deleted_at is null;\ncreate index membership_studio     on membership (studio_id, role) where deleted_at is null;\ncreate index location_studio       on location (studio_id) where deleted_at is null;\ncreate index room_location         on room (location_id) where deleted_at is null;\ncreate index staff_studio          on staff_member (studio_id, status) where deleted_at is null;\ncreate index staff_user            on staff_member (user_id) where deleted_at is null;\n\ncreate index family_studio         on family (studio_id) where deleted_at is null;\ncreate index guardian_family       on guardian (family_id) where deleted_at is null;\ncreate index guardian_user         on guardian (user_id) where deleted_at is null;\ncreate index student_studio        on student (studio_id) where deleted_at is null;\ncreate index student_family        on student (family_id) where deleted_at is null;\ncreate index student_name          on student (studio_id, last_name, first_name) where deleted_at is null;\ncreate index emergency_student     on emergency_contact (student_id) where deleted_at is null;\ncreate index consent_student       on consent_record (student_id) where deleted_at is null;\n\ncreate index term_studio           on term (studio_id, starts_on) where deleted_at is null;\ncreate index class_studio          on class (studio_id, day_of_week, start_time) where deleted_at is null;\ncreate index class_term            on class (term_id) where deleted_at is null;\ncreate index class_teacher         on class (teacher_id) where deleted_at is null;\ncreate index class_assistant       on class (assistant_id) where deleted_at is null;\ncreate index session_class_time    on class_session (class_id, starts_at) where deleted_at is null;\n-- Drives "today" for owner and teacher, the single hottest query in the app.\ncreate index session_studio_time   on class_session (studio_id, starts_at) where deleted_at is null;\n\ncreate index enrolment_class       on enrolment (class_id, status) where deleted_at is null;\ncreate index enrolment_student     on enrolment (student_id, status) where deleted_at is null;\ncreate index trial_class           on trial (class_id, status) where deleted_at is null;\ncreate index trial_session         on trial (session_id) where deleted_at is null;\ncreate index trial_student         on trial (student_id) where deleted_at is null;\ncreate index waitlist_class        on waitlist_entry (class_id, status, position) where deleted_at is null;\ncreate index enquiry_studio_stage  on enquiry (studio_id, stage) where deleted_at is null;\n\ncreate index attendance_session    on attendance_record (session_id) where deleted_at is null;\ncreate index attendance_student    on attendance_record (student_id, marked_at desc) where deleted_at is null;\n\ncreate index invoice_family        on invoice (family_id, status) where deleted_at is null;\ncreate index invoice_studio_status on invoice (studio_id, status, due_on) where deleted_at is null;\ncreate index invoice_item_invoice  on invoice_item (invoice_id) where deleted_at is null;\ncreate index payment_family        on payment (family_id) where deleted_at is null;\n\ncreate index comm_studio_sent      on communication (studio_id, sent_at desc) where deleted_at is null;\ncreate index comm_family           on communication (family_id, sent_at desc) where deleted_at is null;\ncreate index notification_user     on notification (user_id, created_at desc) where deleted_at is null and read_at is null;\ncreate index audit_studio_at       on audit_log (studio_id, at desc);\n\n-- Email is matched case-insensitively; a functional unique index does the job\n-- that citext would, without depending on an extension being installed.\ncreate unique index user_account_email_unique on user_account (lower(email));\ncreate index guardian_email on guardian (lower(email)) where deleted_at is null;\ncreate index staff_email on staff_member (lower(email)) where deleted_at is null;\n'},{name:"0010_hubs.sql",sql:"-- ============================================================================\n-- 0010 · Student and Parent hubs\n-- ----------------------------------------------------------------------------\n-- Adds the fourth role for real, plus the things a studio actually shares with\n-- families: resources, feedback, events and requests.\n--\n-- The child-safety decisions are made here rather than in the interface:\n--   * a student login requires an age threshold AND a named guardian approval\n--   * feedback is invisible until a teacher deliberately shares it, and can be\n--     shared with a guardian without being shared with the child\n--   * a student can see their own allergies but never the full medical record\n-- ============================================================================\n\ncreate type resource_kind    as enum ('video', 'audio', 'document', 'link');\ncreate type resource_scope   as enum ('studio', 'class', 'level', 'student');\ncreate type assessment_level as enum ('not_started', 'developing', 'secure', 'mastered');\ncreate type event_kind       as enum ('competition', 'show', 'exam', 'workshop',\n                                      'private_lesson', 'rehearsal', 'social');\ncreate type event_status     as enum ('draft', 'published', 'cancelled', 'completed');\ncreate type participant_status as enum ('invited', 'requested', 'confirmed',\n                                        'declined', 'waitlisted', 'withdrawn');\ncreate type request_kind     as enum ('question', 'private_lesson', 'medical_update',\n                                      'event_interest', 'absence', 'other');\ncreate type request_status   as enum ('open', 'in_progress', 'answered', 'closed');\n\n-- ── Student logins ─────────────────────────────────────────────────────────\nalter table studio\n  add column student_login_min_age smallint not null default 13\n    check (student_login_min_age between 0 and 18);\n\nalter table student\n  add column user_id uuid references user_account(id) on delete set null,\n  add column login_enabled boolean not null default false,\n  add column login_approved_by uuid references user_account(id) on delete set null,\n  add column login_approved_at timestamptz;\n\ncreate unique index student_user_unique on student (user_id) where user_id is not null;\n\n-- A child's account cannot be switched on by the child, by a teacher, or by a\n-- mistake in application code. The database requires an approving guardian and\n-- an age at or above the studio's own threshold.\ncreate or replace function app.check_student_login() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare min_age smallint; age_years integer;\nbegin\n  if not new.login_enabled then\n    return new;\n  end if;\n  if new.user_id is null then\n    raise exception 'STUDENT_LOGIN_NO_ACCOUNT: enable a login only once an account exists'\n      using errcode = 'check_violation';\n  end if;\n  if new.login_approved_by is null then\n    raise exception 'STUDENT_LOGIN_UNAPPROVED: a guardian must approve this login'\n      using errcode = 'check_violation';\n  end if;\n  select student_login_min_age into min_age from studio where id = new.studio_id;\n  age_years := extract(year from age(current_date, new.date_of_birth));\n  if age_years < min_age then\n    raise exception 'STUDENT_LOGIN_TOO_YOUNG: % is % and the studio requires %',\n      new.first_name, age_years, min_age using errcode = 'check_violation';\n  end if;\n  if new.login_approved_at is null then new.login_approved_at := now(); end if;\n  return new;\nend $$;\n\ncreate trigger student_login_guard\n  before insert or update on student\n  for each row execute function app.check_student_login();\n\n-- ── Resources: videos, music tracks, documents, links ──────────────────────\ncreate table resource (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  kind         resource_kind not null,\n  title        text not null,\n  description  text,\n  category     text,                      -- 'Exam music', 'Technique', 'Uniform'…\n  -- Content is a link today. storage_path is reserved for uploaded files so\n  -- adding Supabase Storage later needs no migration and no change to policy.\n  url          text,\n  storage_path text,\n  poster_url   text,\n  duration_sec integer check (duration_sec is null or duration_sec > 0),\n  visible_to_students  boolean not null default true,\n  visible_to_guardians boolean not null default true,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  created_by   uuid references user_account(id) on delete set null,\n  deleted_at   timestamptz,\n  check (url is not null or storage_path is not null)\n);\n\n-- Who a resource is for. No rows means the whole studio.\ncreate table resource_assignment (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  resource_id uuid not null references resource(id) on delete cascade,\n  scope       resource_scope not null,\n  class_id    uuid references class(id) on delete cascade,\n  level_id    uuid references level(id) on delete cascade,\n  student_id  uuid references student(id) on delete cascade,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  check ((scope = 'studio')\n      or (scope = 'class'   and class_id   is not null)\n      or (scope = 'level'   and level_id   is not null)\n      or (scope = 'student' and student_id is not null))\n);\n\n-- ── Feedback and progress ──────────────────────────────────────────────────\ncreate table feedback_note (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  class_id     uuid references class(id) on delete set null,\n  session_id   uuid references class_session(id) on delete set null,\n  author_id    uuid references staff_member(id) on delete set null,\n  headline     text,\n  going_well   text,\n  work_on      text,\n  private_note text,                      -- staff only, never shared with anyone\n  -- Nothing is visible to a family until a teacher decides it is. A note can\n  -- also be shared with a guardian but held back from a younger child.\n  shared_at         timestamptz,\n  share_with_student  boolean not null default true,\n  share_with_guardian boolean not null default true,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\ncreate table skill_assessment (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  feedback_id  uuid references feedback_note(id) on delete set null,\n  dance_style_id uuid references dance_style(id) on delete set null,\n  skill        text not null,\n  level        assessment_level not null default 'not_started',\n  assessed_by  uuid references staff_member(id) on delete set null,\n  assessed_on  date not null default current_date,\n  note         text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\n-- ── Events: competitions, shows, exams, privates ───────────────────────────\ncreate table studio_event (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  kind         event_kind not null,\n  status       event_status not null default 'published',\n  title        text not null,\n  description  text,\n  starts_at    timestamptz not null,\n  ends_at      timestamptz,\n  location_id  uuid references location(id) on delete set null,\n  venue        text,\n  teacher_id   uuid references staff_member(id) on delete set null,\n  student_id   uuid references student(id) on delete cascade,   -- privates only\n  cost_minor   integer check (cost_minor is null or cost_minor >= 0),\n  capacity     smallint check (capacity is null or capacity > 0),\n  -- Families may ask; the studio still decides. Nothing reaches the diary\n  -- without staff confirming it.\n  requests_open boolean not null default true,\n  entries_close_on date,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  created_by   uuid references user_account(id) on delete set null,\n  deleted_at   timestamptz,\n  check (ends_at is null or ends_at >= starts_at)\n);\n\ncreate table event_participant (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  event_id     uuid not null references studio_event(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  status       participant_status not null default 'requested',\n  requested_by uuid references user_account(id) on delete set null,\n  decided_by   uuid references user_account(id) on delete set null,\n  decided_at   timestamptz,\n  note         text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz,\n  unique (event_id, student_id)\n);\n\n-- ── Requests: a family or student asking the studio something ──────────────\ncreate table studio_request (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  family_id    uuid references family(id) on delete cascade,\n  student_id   uuid references student(id) on delete set null,\n  event_id     uuid references studio_event(id) on delete set null,\n  kind         request_kind not null default 'question',\n  status       request_status not null default 'open',\n  subject      text not null,\n  body         text not null,\n  raised_by    uuid references user_account(id) on delete set null,\n  answered_by  uuid references user_account(id) on delete set null,\n  answered_at  timestamptz,\n  answer       text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\n-- ============================================================================\n-- Row level security for the hubs\n-- ============================================================================\n\n-- The student behind the current login, if any.\ncreate or replace function app.student_self_id() returns uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id from student s\n   where s.user_id = auth.uid() and s.login_enabled and s.deleted_at is null\n   limit 1\n$$;\n\n/* Students a teacher may see, extended to cover event participants — a\n   teacher taking a competition group needs those students even if they are\n   not on one of their weekly registers. */\ncreate or replace function app.teacher_event_student_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select ep.student_id\n    from event_participant ep\n    join studio_event ev on ev.id = ep.event_id\n    join staff_member sm on sm.id = ev.teacher_id\n   where sm.user_id = auth.uid() and ep.deleted_at is null\n     and ep.status in ('confirmed', 'invited')\n$$;\n\n/* Resources reaching a given student: studio-wide, or assigned to a class they\n   are in, a level they study at, or to them by name. */\ncreate or replace function app.resource_ids_for_student(p_student uuid) returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select r.id from resource r\n   where r.deleted_at is null\n     and not exists (select 1 from resource_assignment a\n                      where a.resource_id = r.id and a.deleted_at is null)\n  union\n  select a.resource_id from resource_assignment a\n   where a.deleted_at is null and (\n     a.scope = 'studio'\n     or (a.scope = 'student' and a.student_id = p_student)\n     or (a.scope = 'class' and a.class_id in (\n           select e.class_id from enrolment e\n            where e.student_id = p_student and e.status = 'active' and e.deleted_at is null))\n     or (a.scope = 'level' and a.level_id in (\n           select c.level_id from enrolment e join class c on c.id = e.class_id\n            where e.student_id = p_student and e.status = 'active' and e.deleted_at is null)))\n$$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['resource','resource_assignment','feedback_note','skill_assessment',\n                           'studio_event','event_participant','studio_request'] loop\n    execute format('alter table %I enable row level security', t);\n    execute format('alter table %I force row level security', t);\n  end loop;\nend $$;\n\n-- ── Students: their own record, and nobody else's ──────────────────────────\ncreate policy student_self_read on student for select\n  using (deleted_at is null and id = app.student_self_id());\n\n-- ── Resources ──────────────────────────────────────────────────────────────\ncreate policy resource_staff on resource for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\ncreate policy resource_teacher_read on resource for select\n  using (deleted_at is null and app.has_role(studio_id, 'teacher'));\ncreate policy resource_student_read on resource for select\n  using (deleted_at is null and visible_to_students\n         and id in (select app.resource_ids_for_student(app.student_self_id())));\ncreate policy resource_guardian_read on resource for select\n  using (deleted_at is null and visible_to_guardians\n         and exists (select 1 from unnest(array(select app.guardian_student_ids())) as g(sid)\n                      where id in (select app.resource_ids_for_student(g.sid))));\n\ncreate policy assignment_staff on resource_assignment for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\ncreate policy assignment_read on resource_assignment for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()));\n\n-- ── Feedback ───────────────────────────────────────────────────────────────\n-- Staff write it. Nothing reaches a family until shared_at is set, and the two\n-- share flags let a teacher tell a parent something without telling the child.\ncreate policy feedback_admin on feedback_note for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\ncreate policy feedback_teacher on feedback_note for all\n  using (deleted_at is null and app.has_role(studio_id, 'teacher')\n         and (student_id in (select app.teacher_student_ids())\n              or student_id in (select app.teacher_event_student_ids())))\n  with check (app.has_role(studio_id, 'teacher')\n              and (student_id in (select app.teacher_student_ids())\n                   or student_id in (select app.teacher_event_student_ids())));\ncreate policy feedback_student_read on feedback_note for select\n  using (deleted_at is null and shared_at is not null and share_with_student\n         and student_id = app.student_self_id());\ncreate policy feedback_guardian_read on feedback_note for select\n  using (deleted_at is null and shared_at is not null and share_with_guardian\n         and student_id in (select app.guardian_student_ids()));\n\ncreate policy assessment_staff on skill_assessment for all\n  using (deleted_at is null and app.is_staff(studio_id))\n  with check (app.is_staff(studio_id));\ncreate policy assessment_student_read on skill_assessment for select\n  using (deleted_at is null and student_id = app.student_self_id());\ncreate policy assessment_guardian_read on skill_assessment for select\n  using (deleted_at is null and student_id in (select app.guardian_student_ids()));\n\n-- ── Events ─────────────────────────────────────────────────────────────────\n-- A private lesson belongs to one student, so only that family and the\n-- assigned teacher see it. Everything else that is published is studio-wide.\ncreate policy event_staff on studio_event for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\ncreate policy event_teacher_read on studio_event for select\n  using (deleted_at is null and app.has_role(studio_id, 'teacher'));\ncreate policy event_family_read on studio_event for select\n  using (deleted_at is null and status = 'published' and (\n    (student_id is null and (\n        app.student_self_id() is not null\n        or exists (select 1 from student s where s.family_id in (select app.guardian_family_ids())\n                    and s.deleted_at is null)))\n    or student_id = app.student_self_id()\n    or student_id in (select app.guardian_student_ids())));\n\ncreate policy participant_staff on event_participant for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\ncreate policy participant_teacher_read on event_participant for select\n  using (deleted_at is null and app.has_role(studio_id, 'teacher'));\ncreate policy participant_family_read on event_participant for select\n  using (deleted_at is null and (student_id = app.student_self_id()\n                                 or student_id in (select app.guardian_student_ids())));\n-- A family may ask to take part. They cannot confirm their own place.\ncreate policy participant_family_request on event_participant for insert\n  with check (status = 'requested'\n              and (student_id = app.student_self_id()\n                   or student_id in (select app.guardian_student_ids())));\ncreate policy participant_family_withdraw on event_participant for update\n  using (student_id = app.student_self_id() or student_id in (select app.guardian_student_ids()))\n  with check (status in ('requested', 'withdrawn', 'declined'));\n\n-- ── Requests ───────────────────────────────────────────────────────────────\ncreate policy request_staff on studio_request for all\n  using (deleted_at is null and app.is_staff(studio_id))\n  with check (app.is_staff(studio_id));\ncreate policy request_family_read on studio_request for select\n  using (deleted_at is null and (family_id in (select app.guardian_family_ids())\n                                 or student_id = app.student_self_id()));\ncreate policy request_family_raise on studio_request for insert\n  with check (status = 'open' and (family_id in (select app.guardian_family_ids())\n                                   or student_id = app.student_self_id()));\n\n-- ── The safety brief now serves the student too ────────────────────────────\n-- A thirteen-year-old should be able to see their own allergy information.\n-- The full medical record stays closed to them, exactly as for a teacher.\ncreate or replace view student_safety_brief\n  with (security_invoker = false) as\nselect s.id as student_id, s.studio_id, s.first_name, s.last_name,\n       m.allergies, m.action_plan, m.requires_alert,\n       (select ec.full_name from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_name,\n       (select ec.phone from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_phone\n  from student s\n  left join medical_record m on m.student_id = s.id and m.deleted_at is null\n where s.deleted_at is null\n   and (app.is_admin(s.studio_id)\n        or (app.has_role(s.studio_id, 'teacher')\n            and (s.id in (select app.teacher_student_ids())\n                 or s.id in (select app.teacher_event_student_ids())))\n        or s.id in (select app.guardian_student_ids())\n        or s.id = app.student_self_id());\n\n-- Grant on the new tables by name. A blanket `on all tables in schema public`\n-- here silently re-granted update and delete on audit_log, undoing the\n-- append-only guarantee set up in 0007 — a test caught it, but the lesson is\n-- that a broad grant in a later migration quietly reopens earlier revokes.\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['resource','resource_assignment','feedback_note','skill_assessment',\n                           'studio_event','event_participant','studio_request'] loop\n    execute format('grant select, insert, update, delete on %I to authenticated, service_role', t);\n  end loop;\nend $$;\n\ngrant select on student_safety_brief to authenticated, service_role;\n\n-- Belt and braces: whatever any migration granted, the audit trail stays\n-- append-only for everyone who is not the trusted server role.\nrevoke update, delete on audit_log from authenticated;\n\n-- ── Indexes ────────────────────────────────────────────────────────────────\ncreate index resource_studio      on resource (studio_id, kind) where deleted_at is null;\ncreate index assignment_resource  on resource_assignment (resource_id) where deleted_at is null;\ncreate index assignment_class     on resource_assignment (class_id) where deleted_at is null;\ncreate index assignment_student   on resource_assignment (student_id) where deleted_at is null;\ncreate index feedback_student     on feedback_note (student_id, created_at desc) where deleted_at is null;\ncreate index feedback_shared      on feedback_note (studio_id, shared_at desc) where deleted_at is null;\ncreate index assessment_student   on skill_assessment (student_id, assessed_on desc) where deleted_at is null;\ncreate index event_studio_time    on studio_event (studio_id, starts_at) where deleted_at is null;\ncreate index event_student        on studio_event (student_id, starts_at) where deleted_at is null;\ncreate index participant_event    on event_participant (event_id, status) where deleted_at is null;\ncreate index participant_student  on event_participant (student_id) where deleted_at is null;\ncreate index request_studio       on studio_request (studio_id, status, created_at desc) where deleted_at is null;\ncreate index request_family       on studio_request (family_id, created_at desc) where deleted_at is null;\n"},{name:"0011_student_reads.sql",sql:"-- ============================================================================\n-- 0011 · What a student may read\n-- ----------------------------------------------------------------------------\n-- 0010 gave the student role a policy on `student` and on the hub tables, but\n-- not on the ordinary operational tables their own timetable is built from.\n-- The result was a student who could see their feedback and their library and\n-- had no classes at all — the query joined enrolment and class_session, and\n-- both were closed to them.\n--\n-- Each policy below is scoped to the signed-in student's own rows. A student\n-- gains no view of anybody else: no other child, no family, no billing.\n-- ============================================================================\n\ncreate policy enrolment_student_read on enrolment for select\n  using (deleted_at is null and student_id = app.student_self_id());\n\ncreate policy class_student_read on class for select\n  using (deleted_at is null and id in (\n    select e.class_id from enrolment e\n     where e.student_id = app.student_self_id()\n       and e.status = 'active' and e.deleted_at is null));\n\ncreate policy session_student_read on class_session for select\n  using (deleted_at is null and class_id in (\n    select e.class_id from enrolment e\n     where e.student_id = app.student_self_id()\n       and e.status = 'active' and e.deleted_at is null));\n\ncreate policy attendance_student_read on attendance_record for select\n  using (deleted_at is null and student_id = app.student_self_id());\n\n-- Teacher names appear on a student's timetable. Only what is needed to say\n-- who is taking the class — the staff table's contact details are not exposed\n-- to students by any query, and this policy grants read on the row, so the\n-- repositories select display_name and nothing more.\ncreate policy staff_student_read on staff_member for select\n  using (deleted_at is null and status = 'active'\n         and app.student_self_id() is not null\n         and studio_id in (select app.studio_ids()));\n\n-- Studio-wide announcements, and broadcasts to a class they are actually in.\ncreate policy comm_student_read on communication for select\n  using (deleted_at is null and app.student_self_id() is not null and (\n    kind = 'studio_announcement'\n    or (kind = 'class_broadcast' and class_id in (\n          select e.class_id from enrolment e\n           where e.student_id = app.student_self_id()\n             and e.status = 'active' and e.deleted_at is null))));\n\n-- A student may see their own trial and waiting-list entries.\ncreate policy trial_student_read on trial for select\n  using (deleted_at is null and student_id = app.student_self_id());\ncreate policy waitlist_student_read on waitlist_entry for select\n  using (deleted_at is null and student_id = app.student_self_id());\n"},{name:"0012_resource_files.sql",sql:"-- ============================================================================\n-- 0012 · Uploaded files, and teachers owning their own class resources\n-- ----------------------------------------------------------------------------\n-- Two changes.\n--\n-- 1. Teachers can create resources for the classes they teach. Until now only\n--    an owner or admin could, which made the whole library an admin chore —\n--    exactly the wrong person to be uploading last night's routine video.\n--\n-- 2. A resource can be an uploaded file rather than a link. The bytes live in\n--    resource_file, behind a storage adapter (see src/lib/storage.ts), so the\n--    browser demo stores them in Postgres and a hosted deployment can put them\n--    in Supabase Storage without a schema change: resource.storage_path is the\n--    handle either way.\n-- ============================================================================\n\ncreate table resource_file (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  resource_id  uuid not null unique references resource(id) on delete cascade,\n  file_name    text not null,\n  mime_type    text not null,\n  size_bytes   integer not null check (size_bytes > 0),\n  bytes        bytea not null,\n  uploaded_by  uuid references user_account(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\n\ncreate index resource_file_resource on resource_file (resource_id) where deleted_at is null;\n\nalter table resource_file enable row level security;\nalter table resource_file force row level security;\n\n-- The file inherits the visibility of the resource it belongs to. The EXISTS\n-- runs under the caller's own policies on `resource`, so there is exactly one\n-- place where \"who may see this\" is decided.\ncreate policy file_read on resource_file for select\n  using (deleted_at is null\n         and exists (select 1 from resource r where r.id = resource_file.resource_id));\n\ncreate policy file_write on resource_file for all\n  using (deleted_at is null and app.is_staff(studio_id)\n         and exists (select 1 from resource r where r.id = resource_file.resource_id))\n  with check (app.is_staff(studio_id)\n              and exists (select 1 from resource r where r.id = resource_file.resource_id));\n\n-- ── Teachers may build the library for their own classes ───────────────────\ncreate policy resource_teacher_create on resource for insert\n  with check (app.has_role(studio_id, 'teacher') and created_by = auth.uid());\n\n-- Only what they put there themselves. A teacher cannot edit the studio's\n-- uniform guide, or another teacher's exam music.\ncreate policy resource_teacher_manage on resource for update\n  using (deleted_at is null and app.has_role(studio_id, 'teacher') and created_by = auth.uid())\n  with check (app.has_role(studio_id, 'teacher') and created_by = auth.uid());\n\ncreate policy resource_teacher_delete on resource for delete\n  using (app.has_role(studio_id, 'teacher') and created_by = auth.uid());\n\n-- ...and may attach them to classes they actually teach, and nowhere else.\ncreate policy assignment_teacher_write on resource_assignment for insert\n  with check (app.has_role(studio_id, 'teacher')\n              and scope = 'class'\n              and class_id in (select app.teacher_class_ids()));\n\ncreate policy assignment_teacher_delete on resource_assignment for delete\n  using (app.has_role(studio_id, 'teacher')\n         and class_id in (select app.teacher_class_ids())\n         and exists (select 1 from resource r\n                      where r.id = resource_assignment.resource_id and r.created_by = auth.uid()));\n\ngrant select, insert, update, delete on resource_file to authenticated, service_role;\n\n-- ── Two constraints that assumed a resource was always a link ──────────────\n-- A resource created for an upload has neither a url nor a storage_path until\n-- the bytes land a statement later, which the original check forbade. What\n-- actually matters is narrower: a link has to point somewhere.\nalter table resource drop constraint resource_check;\nalter table resource add constraint resource_has_target\n  check (kind <> 'link' or url is not null);\n\n-- A parent could not see who teaches their child's class: staff_member was\n-- readable by staff and, since 0011, by students — but never by guardians.\n-- Same shape as the student rule, and the repositories select display_name\n-- and nothing else.\ncreate policy staff_guardian_read on staff_member for select\n  using (deleted_at is null and status = 'active'\n         and studio_id in (select app.studio_ids())\n         and exists (select 1 from guardian g\n                      where g.user_id = auth.uid() and g.deleted_at is null));\n\n-- ── Retiring a resource ────────────────────────────────────────────────────\n-- app.soft_delete deliberately requires owner or admin, and a teacher taking\n-- back last week's video is not that. This is the narrow exception, written as\n-- its own function rather than as a hole in the general one — and it clears\n-- the assignments and the bytes at the same time, which the generic version\n-- would have left behind.\ncreate or replace function app.retire_resource(p_id uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; author uuid;\nbegin\n  select studio_id, created_by into sid, author\n    from resource where id = p_id and deleted_at is null;\n  if sid is null then return false; end if;            -- absent or already gone\n\n  if not (app.is_admin(sid)\n          or (app.has_role(sid, 'teacher') and author = auth.uid())) then\n    raise exception 'FORBIDDEN: only the office, or whoever added it, may remove a resource'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update resource set deleted_at = now(), updated_at = now() where id = p_id;\n  update resource_assignment set deleted_at = now(), updated_at = now()\n   where resource_id = p_id and deleted_at is null;\n  update resource_file set deleted_at = now(), updated_at = now()\n   where resource_id = p_id and deleted_at is null;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'soft_delete', 'resource', p_id, 'resource retired');\n  return true;\nend $$;\n\nrevoke all on function app.retire_resource(uuid) from public;\ngrant execute on function app.retire_resource(uuid) to authenticated, service_role;\n"},{name:"0013_scheduling_and_notices.sql",sql:"-- ============================================================================\n-- 0013 · Admins build the timetable, teachers run their own room\n-- ----------------------------------------------------------------------------\n-- Three changes, all of them narrowing or completing something that was\n-- already half-present in the schema.\n--\n-- 1. Sessions can be regenerated safely. app.generate_class_sessions already\n--    said `on conflict do nothing`, but nothing conflicted: there was no\n--    unique constraint, so editing a class's day or time and regenerating\n--    would have doubled up every session.\n--\n-- 2. A teacher may broadcast to their own classes. Until now `comm_staff_write`\n--    was `for all` with `app.is_staff`, which let any teacher send a direct\n--    message to any family in the studio — far wider than the job needs.\n--\n-- 3. A teacher may write the register's notes and close it. They could already\n--    update their own sessions; this makes the intent explicit and gives the\n--    close a single, auditable path.\n-- ============================================================================\n\n-- ── 1. One session per class per start ─────────────────────────────────────\n-- Dedupe first: a database seeded before this index existed may hold repeats.\ndelete from class_session a\n using class_session b\n where a.class_id = b.class_id and a.starts_at = b.starts_at and a.id > b.id\n   and a.deleted_at is null and b.deleted_at is null;\n\ncreate unique index session_class_start_unique\n  on class_session (class_id, starts_at) where deleted_at is null;\n\n-- Regenerating after a class moves: retire the sessions nobody has touched and\n-- rebuild from the class's current day and time. A session with a register\n-- already taken is left alone — attendance is a record of what happened, and\n-- moving next term's slot must not rewrite last week's.\ncreate or replace function app.reschedule_class(p_class uuid) returns integer\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; removed integer;\nbegin\n  select studio_id into sid from class where id = p_class and deleted_at is null;\n  if sid is null then return 0; end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may reschedule a class'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  with gone as (\n    update class_session cs set deleted_at = now(), updated_at = now()\n     where cs.class_id = p_class and cs.deleted_at is null\n       and cs.starts_at > now()\n       and not exists (select 1 from attendance_record ar\n                        where ar.session_id = cs.id and ar.deleted_at is null)\n    returning 1)\n  select count(*)::int into removed from gone;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'reschedule', 'class', p_class,\n          format('%s future sessions rebuilt', removed));\n\n  return app.generate_class_sessions(p_class) - removed;\nend $$;\n\nrevoke all on function app.reschedule_class(uuid) from public;\ngrant execute on function app.reschedule_class(uuid) to authenticated, service_role;\n\n-- ── 2. Who may send what ───────────────────────────────────────────────────\ndrop policy comm_staff_write on communication;\n\n-- The office sends anything: announcements, class broadcasts, direct messages.\ncreate policy comm_admin_write on communication for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\n\n-- A teacher sends one kind of thing to one set of people: a notice to a class\n-- they actually teach. Not a studio announcement, and not a message to a\n-- family — a conversation with a parent belongs to the office.\ncreate policy comm_teacher_read on communication for select\n  using (deleted_at is null and app.has_role(studio_id, 'teacher')\n         and (kind = 'studio_announcement'\n              or (kind = 'class_broadcast' and class_id in (select app.teacher_class_ids()))));\n\ncreate policy comm_teacher_broadcast on communication for insert\n  with check (app.has_role(studio_id, 'teacher')\n              and kind = 'class_broadcast'\n              and class_id in (select app.teacher_class_ids())\n              and sent_by = auth.uid());\n\n-- Their own notice, while it is still theirs to correct.\ncreate policy comm_teacher_amend on communication for update\n  using (deleted_at is null and app.has_role(studio_id, 'teacher')\n         and kind = 'class_broadcast' and sent_by = auth.uid()\n         and class_id in (select app.teacher_class_ids()))\n  with check (kind = 'class_broadcast' and sent_by = auth.uid()\n              and class_id in (select app.teacher_class_ids()));\n\n-- Withdrawing a notice. Same shape as retiring a resource: the author, or the\n-- office, and it leaves a trail.\ncreate or replace function app.withdraw_notice(p_id uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; author uuid; k comm_kind;\nbegin\n  select studio_id, sent_by, kind into sid, author, k\n    from communication where id = p_id and deleted_at is null;\n  if sid is null then return false; end if;\n\n  if not (app.is_admin(sid)\n          or (k = 'class_broadcast' and app.has_role(sid, 'teacher') and author = auth.uid())) then\n    raise exception 'FORBIDDEN: only the office, or whoever sent it, may withdraw a notice'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update communication set deleted_at = now(), updated_at = now() where id = p_id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'withdraw', 'communication', p_id, 'notice withdrawn');\n  return true;\nend $$;\n\nrevoke all on function app.withdraw_notice(uuid) from public;\ngrant execute on function app.withdraw_notice(uuid) to authenticated, service_role;\n\n-- ── 3. Closing a register ──────────────────────────────────────────────────\n-- Done as a function so \"closed\" always means the same thing: every enrolled\n-- dancer accounted for, and a timestamp that says who decided that and when.\ncreate or replace function app.close_register(p_session uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid; unmarked integer;\nbegin\n  select cs.studio_id, cs.class_id into sid, cid\n    from class_session cs where cs.id = p_session and cs.deleted_at is null;\n  if sid is null then return false; end if;\n\n  if not (app.is_admin(sid) or cid in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n\n  select count(*)::int into unmarked\n    from enrolment e\n   where e.class_id = cid and e.status = 'active' and e.deleted_at is null\n     and not exists (select 1 from attendance_record ar\n                      where ar.session_id = p_session and ar.student_id = e.student_id\n                        and ar.deleted_at is null);\n  if unmarked > 0 then\n    raise exception 'REGISTER_INCOMPLETE: % still unmarked', unmarked\n      using errcode = 'check_violation';\n  end if;\n\n  update class_session set register_closed_at = now(), updated_at = now() where id = p_session;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'close_register', 'class_session', p_session, 'register closed');\n  return true;\nend $$;\n\nrevoke all on function app.close_register(uuid) from public;\ngrant execute on function app.close_register(uuid) to authenticated, service_role;\n"},{name:"0014_setup_guards.sql",sql:"-- ============================================================================\n-- 0014 · Removing setup rows safely\n-- ----------------------------------------------------------------------------\n-- Admins could already write locations, rooms, terms, breaks, styles and\n-- levels — migration 0006 gave every reference table an is_admin `for all`\n-- policy. What was missing was a safe way to remove one.\n--\n-- app.soft_delete would happily retire a room that twelve classes are taught\n-- in. The class rows keep pointing at it, the timetable still renders it, and\n-- the studio is left with a room that exists everywhere except in its own\n-- settings. A studio's setup is referenced by its operations, so removal has\n-- to ask what depends on it first.\n-- ============================================================================\n\ncreate or replace function app.retire_setup(p_table text, p_id uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid;\n  used integer := 0;\n  what text;\n  allowed constant text[] := array['location','room','term','term_break','dance_style','level'];\nbegin\n  if not (p_table = any(allowed)) then\n    raise exception 'RETIRE_UNSUPPORTED: %', p_table using errcode = 'feature_not_supported';\n  end if;\n\n  execute format('select studio_id from %I where id = $1 and deleted_at is null', p_table)\n    into sid using p_id;\n  if sid is null then return false; end if;               -- absent or already gone\n\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may change studio setup'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  -- What still points at this row. A term_break is the one thing nothing\n  -- depends on: it is only ever read while generating sessions.\n  case p_table\n    when 'location' then\n      select count(*)::int into used from class\n       where location_id = p_id and deleted_at is null;\n      what := 'class';\n      if used = 0 then\n        select count(*)::int into used from room where location_id = p_id and deleted_at is null;\n        what := 'room';\n      end if;\n    when 'room' then\n      select count(*)::int into used from class where room_id = p_id and deleted_at is null;\n      what := 'class';\n    when 'term' then\n      select count(*)::int into used from class where term_id = p_id and deleted_at is null;\n      what := 'class';\n    when 'dance_style' then\n      select count(*)::int into used from class where dance_style_id = p_id and deleted_at is null;\n      what := 'class';\n    when 'level' then\n      select count(*)::int into used from class where level_id = p_id and deleted_at is null;\n      what := 'class';\n    else used := 0;\n  end case;\n\n  if used > 0 then\n    raise exception 'IN_USE: % % still use this', used, what\n      using errcode = 'foreign_key_violation';\n  end if;\n\n  execute format('update %I set deleted_at = now(), updated_at = now() where id = $1', p_table)\n    using p_id;\n\n  -- Retiring a term takes its breaks with it; they mean nothing on their own.\n  if p_table = 'term' then\n    update term_break set deleted_at = now(), updated_at = now()\n     where term_id = p_id and deleted_at is null;\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'retire', p_table, p_id, 'setup row retired');\n  return true;\nend $$;\n\nrevoke all on function app.retire_setup(text, uuid) from public;\ngrant execute on function app.retire_setup(text, uuid) to authenticated, service_role;\n"},{name:"0015_pipeline.sql",sql:"-- ============================================================================\n-- 0015 · Moving people through the pipeline\n-- ----------------------------------------------------------------------------\n-- Enrolling, trialling and waiting are each more than one row. Accepting a\n-- waiting-list place means creating an enrolment AND closing the entry;\n-- converting a trial means creating an enrolment AND marking the trial AND\n-- advancing the enquiry. Half of any of those is a studio that has taken a\n-- child's place without recording it, or recorded it twice.\n--\n-- So they live here, as functions, in one transaction each — and the offer\n-- that follows a withdrawal happens whether the place was given up through\n-- this app, an import, or a future parent-facing cancellation.\n-- ============================================================================\n\n-- ── Withdrawing, and what it frees ─────────────────────────────────────────\n-- Returns the id of the waiting-list entry that was offered the place, if any.\ncreate or replace function app.withdraw_enrolment(p_id uuid, p_reason text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid; offered uuid;\nbegin\n  select studio_id, class_id into sid, cid\n    from enrolment where id = p_id and status = 'active' and deleted_at is null;\n  if sid is null then return null; end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may withdraw a place'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update enrolment\n     set status = 'left', ended_on = current_date,\n         note = coalesce(nullif(btrim(p_reason), ''), note), updated_at = now()\n   where id = p_id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'withdraw', 'enrolment', p_id, coalesce(p_reason, 'place given up'));\n\n  -- A place has just come free. Offer it to whoever has waited longest, rather\n  -- than leaving it for somebody to notice.\n  select id into offered from waitlist_entry\n   where class_id = cid and status = 'waiting' and deleted_at is null\n   order by position limit 1;\n\n  if offered is not null then\n    perform app.offer_waitlist_place(offered);\n  end if;\n  return offered;\nend $$;\n\n-- ── Offering a waiting-list place ──────────────────────────────────────────\ncreate or replace function app.offer_waitlist_place(p_id uuid, p_days integer default 3)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from waitlist_entry\n   where id = p_id and status = 'waiting' and deleted_at is null;\n  if sid is null then return false; end if;\n\n  update waitlist_entry\n     set status = 'offered', offered_at = now(),\n         offer_expires_at = now() + make_interval(days => greatest(p_days, 1)),\n         updated_at = now()\n   where id = p_id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'offer', 'waitlist_entry', p_id,\n          format('place offered, expires in %s days', greatest(p_days, 1)));\n  return true;\nend $$;\n\n-- ── Accepting one ──────────────────────────────────────────────────────────\n-- The enrolment insert passes through app.enforce_capacity, so a place offered\n-- twice by mistake still cannot put a thirteenth child in a class of twelve.\ncreate or replace function app.accept_waitlist_place(p_id uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare w record; new_id uuid;\nbegin\n  select * into w from waitlist_entry\n   where id = p_id and status in ('waiting','offered') and deleted_at is null;\n  if not found then return null; end if;\n  if not app.is_admin(w.studio_id) then\n    raise exception 'FORBIDDEN: only the office may accept a place'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  insert into enrolment (studio_id, class_id, student_id, status, started_on, created_by, note)\n  values (w.studio_id, w.class_id, w.student_id, 'active', current_date, auth.uid(),\n          'From the waiting list')\n  returning id into new_id;\n\n  update waitlist_entry\n     set status = 'accepted', responded_at = now(), updated_at = now()\n   where id = p_id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (w.studio_id, auth.uid(), 'accept', 'waitlist_entry', p_id, 'place taken up');\n  return new_id;\nend $$;\n\ncreate or replace function app.decline_waitlist_place(p_id uuid, p_note text default null)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid; nxt uuid;\nbegin\n  select studio_id, class_id into sid, cid from waitlist_entry\n   where id = p_id and status in ('waiting','offered') and deleted_at is null;\n  if sid is null then return false; end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may close a waiting-list entry'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update waitlist_entry\n     set status = 'declined', responded_at = now(),\n         note = coalesce(nullif(btrim(p_note), ''), note), updated_at = now()\n   where id = p_id;\n\n  -- The place is free again; pass it down the list.\n  select id into nxt from waitlist_entry\n   where class_id = cid and status = 'waiting' and deleted_at is null\n   order by position limit 1;\n  if nxt is not null and app.class_enrolled_count(cid) <\n       (select capacity from class where id = cid) then\n    perform app.offer_waitlist_place(nxt);\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'decline', 'waitlist_entry', p_id, 'place declined');\n  return true;\nend $$;\n\n-- ── Trials ─────────────────────────────────────────────────────────────────\n-- A converted trial becomes an enrolment, and drags its enquiry along with it,\n-- so the funnel cannot show a child as both \"trial attended\" and enrolled.\n--\n-- Most trials arrive from an enquiry and have no child record yet: the studio\n-- knows a name, a date of birth and a parent's phone number, nothing more.\n-- Converting one therefore has to create the family, the guardian and the\n-- child before it can enrol anybody. Doing that here rather than in the UI is\n-- what stops a half-finished conversion — a family with no child, or a child\n-- with no place — from ever existing.\ncreate or replace function app.convert_trial(p_id uuid, p_note text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  t record; e record; new_id uuid; sid_student uuid; fam uuid;\nbegin\n  select * into t from trial where id = p_id and deleted_at is null;\n  if not found then return null; end if;\n  if not app.is_admin(t.studio_id) then\n    raise exception 'FORBIDDEN: only the office may convert a trial'\n      using errcode = 'insufficient_privilege';\n  end if;\n  if t.status = 'converted' then\n    raise exception 'ALREADY_CONVERTED: this trial has already become an enrolment'\n      using errcode = 'check_violation';\n  end if;\n\n  sid_student := t.student_id;\n\n  if sid_student is null then\n    if t.enquiry_id is null then\n      raise exception 'NO_STUDENT: this trial has no child record and no enquiry to build one from'\n        using errcode = 'check_violation';\n    end if;\n    select * into e from enquiry where id = t.enquiry_id and deleted_at is null;\n    if not found or e.child_name is null or e.child_dob is null then\n      raise exception 'NO_CHILD_DETAILS: the enquiry has no child name and date of birth'\n        using errcode = 'check_violation';\n    end if;\n\n    -- The family takes its name from the contact's surname where there is one.\n    insert into family (studio_id, name, created_by)\n    values (t.studio_id,\n            'The ' || coalesce(nullif(split_part(btrim(e.contact_name), ' ',\n                        array_length(string_to_array(btrim(e.contact_name), ' '), 1)), ''),\n                        btrim(e.contact_name)) || ' family',\n            auth.uid())\n    returning id into fam;\n\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary)\n    values (t.studio_id, fam, e.contact_name, e.contact_email, e.contact_phone, true);\n\n    insert into student (studio_id, family_id, first_name, last_name, date_of_birth, created_by)\n    values (t.studio_id, fam,\n            split_part(btrim(e.child_name), ' ', 1),\n            coalesce(nullif(substr(btrim(e.child_name),\n                       length(split_part(btrim(e.child_name), ' ', 1)) + 2), ''), '—'),\n            e.child_dob, auth.uid())\n    returning id into sid_student;\n\n    update trial set student_id = sid_student where id = p_id;\n  end if;\n\n  insert into enrolment (studio_id, class_id, student_id, status, started_on, created_by, note)\n  values (t.studio_id, t.class_id, sid_student, 'active', current_date, auth.uid(),\n          coalesce(nullif(btrim(p_note), ''), 'Converted from a trial'))\n  returning id into new_id;\n\n  update trial set status = 'converted',\n                   outcome_note = coalesce(nullif(btrim(p_note), ''), outcome_note),\n                   updated_at = now()\n   where id = p_id;\n\n  if t.enquiry_id is not null then\n    update enquiry set stage = 'enrolled', updated_at = now() where id = t.enquiry_id;\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (t.studio_id, auth.uid(), 'convert', 'trial', p_id, 'trial became an enrolment');\n  return new_id;\nend $$;\n\n-- Marking a trial attended or missed keeps the enquiry's stage honest too.\ncreate or replace function app.record_trial_outcome(p_id uuid, p_status text, p_note text default null)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t record;\nbegin\n  if p_status not in ('attended', 'missed', 'cancelled') then\n    raise exception 'BAD_OUTCOME: %', p_status using errcode = 'check_violation';\n  end if;\n  select * into t from trial where id = p_id and deleted_at is null;\n  if not found then return false; end if;\n  if not app.is_admin(t.studio_id) then\n    raise exception 'FORBIDDEN: only the office may record a trial outcome'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update trial\n     set status = p_status::trial_status,\n         attended_at = case when p_status = 'attended' then now() else attended_at end,\n         outcome_note = coalesce(nullif(btrim(p_note), ''), outcome_note),\n         updated_at = now()\n   where id = p_id;\n\n  if t.enquiry_id is not null then\n    update enquiry\n       set stage = (case p_status when 'attended' then 'trial_attended'\n                                  when 'missed'   then 'trial_missed'\n                                  else 'closed_lost' end)::enquiry_stage,\n           updated_at = now()\n     where id = t.enquiry_id;\n  end if;\n  return true;\nend $$;\n\ndo $$\ndeclare f text;\nbegin\n  foreach f in array array[\n    'withdraw_enrolment(uuid, text)', 'offer_waitlist_place(uuid, integer)',\n    'accept_waitlist_place(uuid)', 'decline_waitlist_place(uuid, text)',\n    'convert_trial(uuid, text)', 'record_trial_outcome(uuid, text, text)'] loop\n    execute format('revoke all on function app.%s from public', f);\n    execute format('grant execute on function app.%s to authenticated, service_role', f);\n  end loop;\nend $$;\n"},{name:"0016_billing.sql",sql:"-- ============================================================================\n-- 0016 · The family ledger, made to add up\n-- ----------------------------------------------------------------------------\n-- 0005 gave billing its shape. This gives it arithmetic. Until now an invoice\n-- total, the amount paid against it and a family's balance were three numbers\n-- written independently by whoever inserted the row — so nothing stopped them\n-- disagreeing. Here they are derived, in the database, from the rows that\n-- justify them:\n--\n--   invoice.subtotal   = sum of its live items\n--   invoice.total      = subtotal − invoice-level discount (never below zero)\n--   invoice.paid       = sum of its succeeded payments, net of refunds\n--   invoice.status     = follows from total and paid, unless draft or void\n--   family.balance     = what open invoices still want − credit held on account\n--\n-- Money held on account (a payment not tied to an invoice, or a goodwill\n-- credit) is drawn down by `account` allocation rows, oldest invoice first.\n-- Nothing is ever edited to make the sums work: every movement is a row.\n--\n-- No card data is stored. A card payment arrives from the provider's webhook\n-- as a provider name and reference (see docs/PAYMENTS.md).\n-- ============================================================================\n\nalter table invoice add column voided_at   timestamptz;\nalter table invoice add column void_reason text;\n\n-- What a payment row may be. `account` is an internal transfer: credit the\n-- family already holds, allocated to an invoice. `credit` is goodwill credit\n-- the studio grants. Neither moves real money.\nalter table payment add constraint payment_method_known\n  check (method in ('card', 'direct_debit', 'bank_transfer', 'cash', 'credit', 'account'));\nalter table payment add constraint payment_amount_positive check (amount_minor > 0);\nalter table payment add constraint payment_refund_bounded\n  check (refunded_minor >= 0 and refunded_minor <= amount_minor);\nalter table payment add column note text;\nalter table payment add column recorded_by uuid references user_account(id) on delete set null;\n\ncreate index payment_invoice  on payment (invoice_id) where deleted_at is null;\ncreate index payment_unallocated on payment (family_id)\n  where deleted_at is null and invoice_id is null;\n\n-- ── Derivation ─────────────────────────────────────────────────────────────\n-- A BEFORE trigger owns total and status, so they are right however the row\n-- was written — by a function below, an import, or a provider webhook.\ncreate or replace function app.invoice_derive() returns trigger\n  language plpgsql as $$\ndeclare had_refund boolean;\nbegin\n  new.total_minor := greatest(new.subtotal_minor - new.discount_minor, 0);\n  if new.status in ('draft', 'void') then return new; end if;\n\n  if new.paid_minor >= new.total_minor then\n    new.status := 'paid';\n  elsif new.paid_minor > 0 then\n    new.status := 'part_paid';\n  else\n    select exists (select 1 from payment p where p.invoice_id = new.id\n                     and p.deleted_at is null and p.refunded_minor > 0)\n      into had_refund;\n    new.status := case when had_refund then 'refunded' else 'issued' end;\n  end if;\n  return new;\nend $$;\n\ncreate trigger invoice_derive before insert or update on invoice\n  for each row execute function app.invoice_derive();\n\n-- What the family holds on account and has not yet allocated.\ncreate or replace function app.family_available_credit(p_family uuid) returns bigint\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce((select sum(amount_minor - refunded_minor) from payment\n                    where family_id = p_family and invoice_id is null\n                      and succeeded_at is not null and deleted_at is null), 0)\n       - coalesce((select sum(amount_minor - refunded_minor) from payment\n                    where family_id = p_family and invoice_id is not null and method = 'account'\n                      and succeeded_at is not null and deleted_at is null), 0)\n$$;\n\ncreate or replace function app.recalc_family_balance(p_family uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  update family f set balance_minor =\n      coalesce((select sum(i.total_minor - i.paid_minor) from invoice i\n                 where i.family_id = p_family and i.deleted_at is null\n                   and i.status in ('issued', 'part_paid', 'refunded')), 0)\n    - app.family_available_credit(p_family),\n    updated_at = now()\n   where f.id = p_family;\nend $$;\n\ncreate or replace function app.recalc_invoice(p_invoice uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  update invoice i set\n    subtotal_minor = coalesce((select sum(it.total_minor) from invoice_item it\n                                where it.invoice_id = i.id and it.deleted_at is null), 0),\n    paid_minor     = coalesce((select sum(p.amount_minor - p.refunded_minor) from payment p\n                                where p.invoice_id = i.id and p.deleted_at is null\n                                  and p.succeeded_at is not null), 0),\n    updated_at = now()\n   where i.id = p_invoice;\nend $$;\n\ncreate or replace function app.on_invoice_item_change() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.recalc_invoice(coalesce(new.invoice_id, old.invoice_id));\n  if tg_op = 'UPDATE' and new.invoice_id is distinct from old.invoice_id then\n    perform app.recalc_invoice(old.invoice_id);\n  end if;\n  return null;\nend $$;\n\ncreate trigger invoice_item_recalc after insert or update or delete on invoice_item\n  for each row execute function app.on_invoice_item_change();\n\ncreate or replace function app.on_payment_change() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r payment;\nbegin\n  r := coalesce(new, old);\n  if r.invoice_id is not null then perform app.recalc_invoice(r.invoice_id); end if;\n  if tg_op = 'UPDATE' and old.invoice_id is distinct from new.invoice_id and old.invoice_id is not null then\n    perform app.recalc_invoice(old.invoice_id);\n  end if;\n  -- Unallocated money changes the balance without touching any invoice.\n  perform app.recalc_family_balance(r.family_id);\n  return null;\nend $$;\n\ncreate trigger payment_recalc after insert or update or delete on payment\n  for each row execute function app.on_payment_change();\n\ncreate or replace function app.on_invoice_change() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if tg_op = 'INSERT'\n     or new.total_minor  is distinct from old.total_minor\n     or new.paid_minor   is distinct from old.paid_minor\n     or new.status       is distinct from old.status\n     or new.deleted_at   is distinct from old.deleted_at then\n    perform app.recalc_family_balance(new.family_id);\n  end if;\n  return null;\nend $$;\n\ncreate trigger invoice_balance after insert or update on invoice\n  for each row execute function app.on_invoice_change();\n\n-- ── Guard ──────────────────────────────────────────────────────────────────\ncreate or replace function app.require_admin(p_studio uuid) returns void\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if p_studio is null or not app.is_admin(p_studio) then\n    raise exception 'FORBIDDEN: only the studio office may change billing'\n      using errcode = 'insufficient_privilege';\n  end if;\nend $$;\n\n-- ── Allocating credit ──────────────────────────────────────────────────────\n-- Draws the family's credit down against its open invoices, oldest due first.\n-- Returns what was allocated. Called after any money lands on account.\ncreate or replace function app.allocate_account_credit(p_family uuid) returns bigint\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; avail bigint; inv record; take bigint; total bigint := 0;\nbegin\n  select studio_id into sid from family where id = p_family and deleted_at is null;\n  perform app.require_admin(sid);\n  avail := app.family_available_credit(p_family);\n  for inv in\n    select id, total_minor - paid_minor as owed from invoice\n     where family_id = p_family and deleted_at is null\n       and status in ('issued', 'part_paid', 'refunded') and total_minor > paid_minor\n     order by due_on nulls last, issued_on, number\n  loop\n    exit when avail <= 0;\n    take := least(avail, inv.owed);\n    insert into payment (studio_id, family_id, invoice_id, amount_minor, method,\n                         provider, succeeded_at, note, recorded_by)\n    values (sid, p_family, inv.id, take, 'account', 'ledger', now(),\n            'Credit on account applied', auth.uid());\n    avail := avail - take; total := total + take;\n  end loop;\n  return total;\nend $$;\n\n-- ── Creating an invoice ────────────────────────────────────────────────────\n-- p_items: [{kind, description, quantity, unit_minor, discount_minor?,\n--            student_id?, class_id?}]\ncreate or replace function app.create_invoice(\n  p_family uuid, p_items jsonb, p_due date default null, p_note text default null,\n  p_discount_minor bigint default 0, p_issue boolean default true, p_term uuid default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; inv uuid; num text; it jsonb; n int := 0;\nbegin\n  select studio_id into sid from family where id = p_family and deleted_at is null;\n  perform app.require_admin(sid);\n\n  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then\n    raise exception 'INVALID: an invoice needs at least one line' using errcode = 'check_violation';\n  end if;\n  if coalesce(p_discount_minor, 0) < 0 then\n    raise exception 'INVALID: a discount cannot be negative' using errcode = 'check_violation';\n  end if;\n\n  -- Sequential per studio. The advisory lock stops two people raising\n  -- invoices at the same moment from being handed the same number.\n  perform pg_advisory_xact_lock(hashtext('invoice-number:' || sid::text));\n  select 'INV-' || lpad((coalesce(max(nullif(regexp_replace(number, '\\D', '', 'g'), '')::int), 1000) + 1)::text, 4, '0')\n    into num from invoice where studio_id = sid;\n\n  insert into invoice (studio_id, family_id, term_id, number, status, issued_on, due_on,\n                       discount_minor, note, created_by)\n  values (sid, p_family, p_term, num, case when p_issue then 'issued' else 'draft' end::invoice_status,\n          case when p_issue then current_date end,\n          coalesce(p_due, current_date + 14), coalesce(p_discount_minor, 0),\n          nullif(btrim(p_note), ''), auth.uid())\n  returning id into inv;\n\n  for it in select * from jsonb_array_elements(p_items) loop\n    n := n + 1;\n    if coalesce(btrim(it->>'description'), '') = '' then\n      raise exception 'INVALID: line % needs a description', n using errcode = 'check_violation';\n    end if;\n    -- A line about a child must be about a child in this family.\n    if it->>'student_id' is not null and not exists (\n         select 1 from student s where s.id = (it->>'student_id')::uuid\n            and s.family_id = p_family and s.deleted_at is null) then\n      raise exception 'INVALID: line % names a student outside this family', n\n        using errcode = 'check_violation';\n    end if;\n    insert into invoice_item (studio_id, invoice_id, student_id, class_id, kind, description,\n                              quantity, unit_minor, discount_minor)\n    values (sid, inv, (it->>'student_id')::uuid, (it->>'class_id')::uuid,\n            coalesce(it->>'kind', 'other')::charge_kind, btrim(it->>'description'),\n            coalesce((it->>'quantity')::numeric, 1), (it->>'unit_minor')::int,\n            coalesce((it->>'discount_minor')::int, 0));\n  end loop;\n\n  if exists (select 1 from invoice_item where invoice_id = inv and total_minor < 0) then\n    raise exception 'INVALID: a line discount is larger than the line' using errcode = 'check_violation';\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'create', 'invoice', inv, num);\n\n  if p_issue then perform app.allocate_account_credit(p_family); end if;\n  return inv;\nend $$;\n\ncreate or replace function app.issue_invoice(p_invoice uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; fam uuid;\nbegin\n  select studio_id, family_id into sid, fam from invoice\n   where id = p_invoice and status = 'draft' and deleted_at is null;\n  if sid is null then\n    raise exception 'INVALID: only a draft invoice can be issued' using errcode = 'check_violation';\n  end if;\n  perform app.require_admin(sid);\n  update invoice set status = 'issued', issued_on = current_date where id = p_invoice;\n  perform app.allocate_account_credit(fam);\nend $$;\n\n-- Voiding is for an invoice raised in error. One that has been paid against is\n-- refunded instead, so the money trail stays intact.\ncreate or replace function app.void_invoice(p_invoice uuid, p_reason text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; paid bigint; num text;\nbegin\n  select studio_id, paid_minor, number into sid, paid, num from invoice\n   where id = p_invoice and deleted_at is null and status <> 'void';\n  if sid is null then raise exception 'NOT_FOUND: invoice' using errcode = 'no_data_found'; end if;\n  perform app.require_admin(sid);\n  if paid > 0 then\n    raise exception 'INVALID: this invoice has payments against it — refund them first'\n      using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'INVALID: say why the invoice is being voided' using errcode = 'check_violation';\n  end if;\n  update invoice set status = 'void', voided_at = now(), void_reason = btrim(p_reason)\n   where id = p_invoice;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'void', 'invoice', p_invoice, num || ': ' || btrim(p_reason));\nend $$;\n\n-- ── Recording money the studio received itself ─────────────────────────────\n-- Bank transfer and cash. Card money only ever arrives from the provider.\n-- Without an invoice, or beyond what the invoice still wants, the money goes\n-- on account and is allocated to the oldest open invoices.\ncreate or replace function app.record_payment(\n  p_family uuid, p_amount_minor bigint, p_method text,\n  p_invoice uuid default null, p_note text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; owed bigint; pid uuid;\nbegin\n  select studio_id into sid from family where id = p_family and deleted_at is null;\n  perform app.require_admin(sid);\n  if p_method not in ('bank_transfer', 'cash', 'credit') then\n    raise exception 'INVALID: record bank transfers, cash or a credit here — card payments come from the provider'\n      using errcode = 'check_violation';\n  end if;\n  if coalesce(p_amount_minor, 0) <= 0 then\n    raise exception 'INVALID: the amount must be more than zero' using errcode = 'check_violation';\n  end if;\n  if p_method = 'credit' and p_invoice is not null then\n    raise exception 'INVALID: a credit is held on account, not against one invoice'\n      using errcode = 'check_violation';\n  end if;\n\n  if p_invoice is not null then\n    select total_minor - paid_minor into owed from invoice\n     where id = p_invoice and family_id = p_family and deleted_at is null\n       and status in ('issued', 'part_paid', 'refunded');\n    if owed is null then\n      raise exception 'INVALID: that invoice is not open for this family' using errcode = 'check_violation';\n    end if;\n    if p_amount_minor > owed then\n      raise exception 'INVALID: that is more than the % still owed on this invoice', owed\n        using errcode = 'check_violation';\n    end if;\n  end if;\n\n  insert into payment (studio_id, family_id, invoice_id, amount_minor, method, provider,\n                       succeeded_at, note, recorded_by)\n  values (sid, p_family, p_invoice, p_amount_minor, p_method, 'manual', now(),\n          nullif(btrim(p_note), ''), auth.uid())\n  returning id into pid;\n\n  if p_invoice is null then perform app.allocate_account_credit(p_family); end if;\n  return pid;\nend $$;\n\n-- ── Refunds ────────────────────────────────────────────────────────────────\n-- Money the studio took itself, it can hand back here. A card refund is made\n-- through the provider, whose webhook then writes refunded_minor — so the\n-- ledger can never claim a refund the bank has not made.\ncreate or replace function app.refund_payment(p_payment uuid, p_amount_minor bigint, p_reason text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p payment; left_ bigint;\nbegin\n  select * into p from payment where id = p_payment and deleted_at is null and succeeded_at is not null;\n  if p.id is null then raise exception 'NOT_FOUND: payment' using errcode = 'no_data_found'; end if;\n  perform app.require_admin(p.studio_id);\n  if p.method in ('card', 'direct_debit') then\n    raise exception 'INVALID: card and direct debit refunds are made with the payment provider'\n      using errcode = 'check_violation';\n  end if;\n  if p.method in ('account', 'credit') then\n    raise exception 'INVALID: credit is not money that can be refunded' using errcode = 'check_violation';\n  end if;\n  left_ := p.amount_minor - p.refunded_minor;\n  if coalesce(p_amount_minor, 0) <= 0 or p_amount_minor > left_ then\n    raise exception 'INVALID: a refund must be between 1p and the % not already refunded', left_\n      using errcode = 'check_violation';\n  end if;\n  -- Money on account that has already been allocated to invoices is no longer\n  -- the family's to take back.\n  if p.invoice_id is null and p_amount_minor > app.family_available_credit(p.family_id) then\n    raise exception 'INVALID: that money has already been applied to invoices' using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'INVALID: say why the payment is being refunded' using errcode = 'check_violation';\n  end if;\n  update payment set refunded_minor = refunded_minor + p_amount_minor,\n                     note = concat_ws(' · ', note, 'Refunded: ' || btrim(p_reason))\n   where id = p_payment;\nend $$;\n\ngrant execute on function app.create_invoice(uuid, jsonb, date, text, bigint, boolean, uuid),\n                          app.issue_invoice(uuid), app.void_invoice(uuid, text),\n                          app.record_payment(uuid, bigint, text, uuid, text),\n                          app.refund_payment(uuid, bigint, text),\n                          app.allocate_account_credit(uuid),\n                          app.family_available_credit(uuid) to authenticated;\n\n-- The internals are not entry points.\nrevoke execute on function app.recalc_invoice(uuid), app.recalc_family_balance(uuid)\n  from public, authenticated, anon;\n\n-- Bring rows written before this migration into line with the rules.\ndo $$ declare r record; begin\n  for r in select id from invoice loop perform app.recalc_invoice(r.id); end loop;\n  for r in select id from family loop perform app.recalc_family_balance(r.id); end loop;\nend $$;\n\n-- ── The payment provider's entry point ─────────────────────────────────────\n-- Called by the webhook handler running as service_role — never by a user.\n-- Idempotent on (provider, provider_ref): providers retry webhooks, and the\n-- same event arriving twice must not take a family's money twice.\ncreate unique index payment_provider_ref on payment (provider, provider_ref)\n  where provider_ref is not null and deleted_at is null;\n\ncreate or replace function app.apply_provider_event(\n  p_provider text, p_ref text, p_invoice uuid, p_amount_minor bigint,\n  p_outcome text, p_failure_code text default null, p_refunded_minor bigint default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare inv invoice; pid uuid;\nbegin\n  if p_outcome not in ('succeeded', 'failed', 'refunded') then\n    raise exception 'INVALID: unknown outcome %', p_outcome;\n  end if;\n  select * into inv from invoice where id = p_invoice and deleted_at is null;\n  if inv.id is null then raise exception 'NOT_FOUND: invoice %', p_invoice; end if;\n\n  select id into pid from payment where provider = p_provider and provider_ref = p_ref\n                                      and deleted_at is null;\n  if pid is null then\n    insert into payment (studio_id, family_id, invoice_id, amount_minor, method, provider,\n                         provider_ref, failure_code, succeeded_at)\n    values (inv.studio_id, inv.family_id, inv.id, p_amount_minor, 'card', p_provider, p_ref,\n            case when p_outcome = 'failed' then coalesce(p_failure_code, 'failed') end,\n            case when p_outcome <> 'failed' then now() end)\n    returning id into pid;\n  elsif p_outcome = 'succeeded' then\n    update payment set succeeded_at = coalesce(succeeded_at, now()), failure_code = null where id = pid;\n  elsif p_outcome = 'failed' then\n    update payment set failure_code = coalesce(p_failure_code, 'failed') where id = pid and succeeded_at is null;\n  end if;\n\n  if p_outcome = 'refunded' then\n    -- The provider reports the cumulative refunded amount, so this is a set,\n    -- not an increment: replaying the event changes nothing.\n    update payment set refunded_minor = least(coalesce(p_refunded_minor, amount_minor), amount_minor)\n     where id = pid;\n  end if;\n  return pid;\nend $$;\n\nrevoke execute on function app.apply_provider_event(text, text, uuid, bigint, text, text, bigint)\n  from public, authenticated, anon;\ngrant execute on function app.apply_provider_event(text, text, uuid, bigint, text, text, bigint)\n  to service_role;\n"},{name:"0017_inbox_notifications.sql",sql:"-- ============================================================================\n-- 0017 · Conversations with families, and the notification centre\n-- ----------------------------------------------------------------------------\n-- 1. Close a leak. `comm_read` (0007) granted every member of staff read\n--    access to every communication. 0013 added a narrower teacher policy but\n--    left the broad one in place, and permissive policies are OR-ed — so a\n--    teacher could still read every family's direct messages, payment\n--    reminders included. Direct conversations belong to the office.\n--\n-- 2. A message knows which way it travelled. `inbound` is set by the\n--    database from who is sending, and `sent_by` is always the caller: a\n--    client cannot write a message that claims to be from someone else.\n--\n-- 3. Notifications are written by the database when something happens, not\n--    by whichever screen happened to cause it. Nobody is notified of their\n--    own action.\n-- ============================================================================\n\n-- ── 1. Who reads what ──────────────────────────────────────────────────────\ndrop policy comm_read on communication;\ncreate policy comm_read on communication for select\n  using (deleted_at is null and studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or kind = 'studio_announcement'\n    or family_id in (select app.guardian_family_ids())\n    or (kind = 'class_broadcast' and exists (\n          select 1 from enrolment e where e.class_id = communication.class_id\n            and e.deleted_at is null and e.status = 'active'\n            and e.student_id in (select app.guardian_student_ids())))));\n\n-- A guardian writes only into their own family's conversation. The studio is\n-- taken from the family by the trigger below, so it cannot be pointed at a\n-- different tenant either.\ndrop policy comm_guardian_insert on communication;\ncreate policy comm_guardian_insert on communication for insert\n  with check (kind = 'direct' and family_id in (select app.guardian_family_ids()));\n\n-- ── 2. Direction and authorship ────────────────────────────────────────────\nalter table communication add column inbound boolean not null default false;\n\ncreate or replace function app.communication_stamp() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.family_id is not null then\n    select studio_id into new.studio_id from family where id = new.family_id;\n  end if;\n  -- service_role is a trusted server job (an import, a webhook) and may\n  -- write on someone's behalf. Everyone else writes as themselves. (The\n  -- automation runner sends as the studio by running without a user — see\n  -- app.run_automations.)\n  if auth.uid() is not null and current_setting('role', true) is distinct from 'service_role' then\n    if new.sent_by is not null and new.sent_by <> auth.uid() then\n      raise exception 'FORBIDDEN: a message is sent as yourself' using errcode = 'insufficient_privilege';\n    end if;\n    new.sent_by := auth.uid();\n    new.inbound := not app.is_staff(new.studio_id);\n  end if;\n  if coalesce(btrim(new.body), '') = '' then\n    raise exception 'INVALID: a message needs something in it' using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\n\ncreate trigger communication_stamp before insert on communication\n  for each row execute function app.communication_stamp();\n\ncreate index comm_inbound on communication (studio_id, sent_at desc)\n  where deleted_at is null and inbound;\n\n-- Marking read is per person. One call marks a whole conversation.\ncreate or replace function app.mark_read(p_ids uuid[]) returns integer\n  language plpgsql security invoker set search_path = public, app, pg_temp as $$\ndeclare n integer;\nbegin\n  insert into communication_read (communication_id, user_id)\n  select c.id, auth.uid() from communication c where c.id = any(p_ids)\n  on conflict (communication_id, user_id) do nothing;\n  get diagnostics n = row_count;\n  return n;\nend $$;\ngrant execute on function app.mark_read(uuid[]) to authenticated;\n\n-- ── 3. Notifications ───────────────────────────────────────────────────────\ncreate or replace function app.notify_user(\n  p_studio uuid, p_user uuid, p_kind text, p_title text, p_body text, p_href text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if p_user is null or p_user is not distinct from auth.uid() then return; end if;\n  -- A bulk import or the demo seed sets app.quiet so that loading a studio's\n  -- history does not bury the owner in notifications about the past. It is\n  -- honoured only without a signed-in user: anyone can set a session\n  -- setting, so a user must not be able to silence what they do.\n  if auth.uid() is null and current_setting('app.quiet', true) = 'on' then return; end if;\n  insert into notification (studio_id, user_id, kind, title, body, href)\n  values (p_studio, p_user, p_kind, p_title, p_body, p_href);\nend $$;\n\ncreate or replace function app.notify_admins(\n  p_studio uuid, p_kind text, p_title text, p_body text, p_href text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare u uuid;\nbegin\n  for u in select distinct m.user_id from membership m\n            where m.studio_id = p_studio and m.role in ('owner', 'admin') and m.deleted_at is null\n  loop\n    perform app.notify_user(p_studio, u, p_kind, p_title, p_body, p_href);\n  end loop;\nend $$;\n\ncreate or replace function app.notify_family(\n  p_family uuid, p_kind text, p_title text, p_body text, p_href text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g record;\nbegin\n  for g in select studio_id, user_id from guardian\n            where family_id = p_family and user_id is not null and deleted_at is null\n  loop\n    perform app.notify_user(g.studio_id, g.user_id, p_kind, p_title, p_body, p_href);\n  end loop;\nend $$;\n\nrevoke execute on function app.notify_user(uuid, uuid, text, text, text, text),\n                           app.notify_admins(uuid, text, text, text, text),\n                           app.notify_family(uuid, text, text, text, text)\n  from public, authenticated, anon;\n\n-- A message from a family\ncreate or replace function app.on_communication_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare fam text;\nbegin\n  if new.inbound and new.family_id is not null then\n    select name into fam from family where id = new.family_id;\n    perform app.notify_admins(new.studio_id, 'message', 'Message from the ' || fam,\n      coalesce(new.subject, left(new.body, 120)), '/inbox?family=' || new.family_id);\n  elsif not new.inbound and new.kind = 'direct' then\n    perform app.notify_family(new.family_id, 'message',\n      coalesce(new.subject, 'New message from the studio'), left(new.body, 120), '/family/messages');\n  end if;\n  return null;\nend $$;\ncreate trigger communication_notify after insert on communication\n  for each row execute function app.on_communication_notify();\n\n-- A new enquiry or trial\ncreate or replace function app.on_enquiry_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.notify_admins(new.studio_id, 'new_enquiry',\n    'New enquiry' || coalesce(' for ' || new.child_name, ''),\n    'From ' || new.contact_name || coalesce(' · via ' || new.source, ''), '/enrolment');\n  return null;\nend $$;\ncreate trigger enquiry_notify after insert on enquiry\n  for each row execute function app.on_enquiry_notify();\n\ncreate or replace function app.on_trial_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cname text; child text; teacher uuid;\nbegin\n  select c.name, sm.user_id into cname, teacher\n    from class c left join staff_member sm on sm.id = c.teacher_id where c.id = new.class_id;\n  select first_name into child from student where id = new.student_id;\n  perform app.notify_admins(new.studio_id, 'new_trial', 'Trial booked: ' || cname,\n    coalesce(child, 'A new child') || ' is coming to try a class.', '/enrolment');\n  perform app.notify_user(new.studio_id, teacher, 'new_trial', 'Trial in ' || cname,\n    coalesce(child, 'A new child') || ' is joining for a trial.', '/teach');\n  return null;\nend $$;\ncreate trigger trial_notify after insert on trial\n  for each row execute function app.on_trial_notify();\n\n-- A new place taken. The class teacher hears too: it is their room.\ncreate or replace function app.on_enrolment_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cname text; child text; teacher uuid;\nbegin\n  if new.status <> 'active' then return null; end if;\n  select c.name, sm.user_id into cname, teacher\n    from class c left join staff_member sm on sm.id = c.teacher_id where c.id = new.class_id;\n  select first_name || ' ' || last_name into child from student where id = new.student_id;\n  perform app.notify_admins(new.studio_id, 'new_enrolment', child || ' joined ' || cname,\n    null, '/classes?id=' || new.class_id);\n  perform app.notify_user(new.studio_id, teacher, 'new_enrolment', 'New in ' || cname,\n    child || ' joins your class.', '/teach');\n  return null;\nend $$;\ncreate trigger enrolment_notify after insert on enrolment\n  for each row execute function app.on_enrolment_notify();\n\n-- A card that did not go through\ncreate or replace function app.on_payment_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare fam text;\nbegin\n  if new.failure_code is null or new.succeeded_at is not null then return null; end if;\n  if tg_op = 'UPDATE' and old.failure_code is not null then return null; end if;\n  select name into fam from family where id = new.family_id;\n  perform app.notify_admins(new.studio_id, 'payment_failed', 'Payment failed: ' || fam,\n    replace(new.failure_code, '_', ' '),\n    '/billing' || coalesce('?id=' || new.invoice_id, ''));\n  perform app.notify_family(new.family_id, 'payment_failed', 'A payment did not go through',\n    'Your card was declined. You can see what is owed in Payments.', '/family/payments');\n  return null;\nend $$;\ncreate trigger payment_notify after insert or update of failure_code on payment\n  for each row execute function app.on_payment_notify();\n\n-- A waiting-list place offered\ncreate or replace function app.on_waitlist_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cname text; child text; fam uuid;\nbegin\n  if new.status <> 'offered' or old.status = 'offered' then return null; end if;\n  select name into cname from class where id = new.class_id;\n  select first_name, family_id into child, fam from student where id = new.student_id;\n  perform app.notify_family(fam, 'waitlist_offer', 'A place in ' || cname,\n    'We can hold it for ' || child || coalesce(' until ' || to_char(new.offer_expires_at, 'FMDay FMDD FMMonth'), '') || '.',\n    '/family');\n  perform app.notify_admins(new.studio_id, 'waitlist_offer', 'Place offered in ' || cname,\n    child || ' was next on the waiting list.', '/classes?id=' || new.class_id);\n  return null;\nend $$;\ncreate trigger waitlist_notify after update of status on waitlist_entry\n  for each row execute function app.on_waitlist_notify();\n\n-- Health details changed by a family. The notification says that it changed,\n-- never what it says: notifications are not the place for health data.\ncreate or replace function app.on_medical_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare child text;\nbegin\n  if auth.uid() is null or app.is_staff(new.studio_id) then return null; end if;\n  select first_name || ' ' || last_name into child from student where id = new.student_id;\n  perform app.notify_admins(new.studio_id, 'medical_updated', 'Medical details updated',\n    'A guardian updated ' || child || '’s health information.', '/people?tab=students&id=' || new.student_id);\n  return null;\nend $$;\ncreate trigger medical_notify after insert or update on medical_record\n  for each row execute function app.on_medical_notify();\n\n-- A class handed to a different teacher\ncreate or replace function app.on_class_teacher_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare who uuid;\nbegin\n  if new.teacher_id is not distinct from old.teacher_id or new.teacher_id is null then return null; end if;\n  select user_id into who from staff_member where id = new.teacher_id;\n  perform app.notify_user(new.studio_id, who, 'teacher_changed', 'You are now teaching ' || new.name,\n    to_char(new.start_time, 'HH24:MI') || ' on ' ||\n    (array['Sundays','Mondays','Tuesdays','Wednesdays','Thursdays','Fridays','Saturdays'])[new.day_of_week + 1],\n    '/teach');\n  return null;\nend $$;\ncreate trigger class_teacher_notify after update of teacher_id on class\n  for each row execute function app.on_class_teacher_notify();\n\n-- A request from a family\ncreate or replace function app.on_request_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.notify_admins(new.studio_id, 'request', new.subject, left(new.body, 120), '/requests');\n  return null;\nend $$;\ncreate trigger request_notify after insert on studio_request\n  for each row execute function app.on_request_notify();\n\n-- Reading and clearing your own notifications\ncreate or replace function app.mark_notifications_read(p_ids uuid[] default null) returns integer\n  language plpgsql security invoker set search_path = public, app, pg_temp as $$\ndeclare n integer;\nbegin\n  update notification set read_at = now()\n   where user_id = auth.uid() and read_at is null\n     and (p_ids is null or id = any(p_ids));\n  get diagnostics n = row_count;\n  return n;\nend $$;\ngrant execute on function app.mark_notifications_read(uuid[]) to authenticated;\n\ncreate index notification_user_all on notification (user_id, created_at desc) where deleted_at is null;\n\n-- Who a message is from, as the reader should see it. Staff names are shown\n-- to anyone in the studio (families know their teachers). A guardian's name\n-- is shown only to the office and to their own family — so this function\n-- cannot be used to look people up.\ncreate or replace function app.sender_name(p_user uuid, p_studio uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(\n    (select sm.display_name from staff_member sm\n      where sm.user_id = p_user and sm.studio_id = p_studio and sm.deleted_at is null limit 1),\n    (select g.full_name from guardian g\n      where g.user_id = p_user and g.studio_id = p_studio and g.deleted_at is null\n        and (app.is_admin(p_studio) or g.family_id in (select app.guardian_family_ids()))\n      limit 1),\n    -- Office staff who do not teach have no staff_member row.\n    (select u.full_name from user_account u\n      where u.id = p_user and exists (select 1 from membership m where m.user_id = u.id\n        and m.studio_id = p_studio and m.role in ('owner', 'admin') and m.deleted_at is null)))\n  where p_studio in (select app.studio_ids())\n$$;\ngrant execute on function app.sender_name(uuid, uuid) to authenticated;\n"},{name:"0018_automations.sql",sql:"-- ============================================================================\n-- 0018 · Automations: the messages a studio sends on a schedule\n-- ----------------------------------------------------------------------------\n-- A trial confirmation, a 48-hour reminder, a same-day reminder, a follow-up\n-- after the class, a note when a trial was missed, a waiting-list offer. Each\n-- is a RULE (which event, which template, on or off) evaluated by ONE runner.\n--\n-- Adding a new automation is adding an `event` value and one branch in\n-- app.automation_candidates — the runner, idempotency, rendering, history\n-- and the screen do not change.\n--\n-- The runner is idempotent: automation_run is unique on (rule, subject), so\n-- running it every five minutes from a scheduler, or pressing \"Run now\" twice,\n-- never sends the same family the same message twice.\n-- ============================================================================\n\ncreate table automation_rule (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  event        text not null check (event in (\n                 'trial_booked', 'trial_reminder_48h', 'trial_reminder_same_day',\n                 'trial_attended', 'trial_missed', 'waitlist_offer')),\n  template_id  uuid references communication_template(id) on delete set null,\n  enabled      boolean not null default true,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  created_by   uuid references user_account(id) on delete set null,\n  deleted_at   timestamptz,\n  unique (studio_id, event)\n);\n\ncreate table automation_run (\n  id               uuid primary key default gen_random_uuid(),\n  studio_id        uuid not null references studio(id) on delete cascade,\n  rule_id          uuid not null references automation_rule(id) on delete cascade,\n  subject_id       uuid not null,            -- the trial or waiting-list entry\n  family_id        uuid references family(id) on delete set null,\n  communication_id uuid references communication(id) on delete set null,\n  ran_at           timestamptz not null default now(),\n  unique (rule_id, subject_id)\n);\n\ncreate index automation_run_studio on automation_run (studio_id, ran_at desc);\n\n-- Messages to people who have no account yet (a prospect booking a first\n-- trial) can only go by email or text. They wait here for a delivery\n-- provider. Nothing in this build sends them; the screen says so.\ncreate table outbound_message (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  channel      comm_channel not null check (channel in ('email', 'sms')),\n  to_name      text,\n  to_address   text not null,\n  subject      text,\n  body         text not null,\n  enquiry_id   uuid references enquiry(id) on delete set null,\n  status       text not null default 'queued' check (status in ('queued', 'sent', 'failed', 'cancelled')),\n  provider_ref text,\n  error        text,\n  created_at   timestamptz not null default now(),\n  sent_at      timestamptz\n);\ncreate index outbound_queued on outbound_message (studio_id, created_at) where status = 'queued';\nalter table outbound_message enable row level security;\nalter table outbound_message force row level security;\ncreate policy outbound_read on outbound_message for select using (app.is_admin(studio_id));\ngrant select on outbound_message to authenticated;\ngrant all on outbound_message to service_role;\n\nalter table automation_run add column outbound_id uuid references outbound_message(id) on delete set null;\n\nalter table automation_rule enable row level security;\nalter table automation_rule force row level security;\nalter table automation_run  enable row level security;\nalter table automation_run  force row level security;\n\ncreate policy automation_rule_read on automation_rule for select\n  using (deleted_at is null and app.is_admin(studio_id));\ncreate policy automation_rule_write on automation_rule for update\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy automation_run_read on automation_run for select\n  using (app.is_admin(studio_id));\n\ngrant select, update on automation_rule to authenticated;\ngrant select on automation_run to authenticated;\ngrant all on automation_rule, automation_run to service_role;\n\ncreate trigger automation_rule_touch before update on automation_rule\n  for each row execute function app.touch_updated_at();\n\n-- ── What each rule would act on right now ──────────────────────────────────\n-- One row per (rule, subject) that is due and has not been sent.\ncreate or replace function app.automation_candidates(p_studio uuid, p_now timestamptz default now())\n  returns table (rule_id uuid, event text, subject_id uuid, family_id uuid, student_id uuid,\n                 class_id uuid, starts_at timestamptz, expires_at timestamptz,\n                 contact_name text, contact_email text, child_name text, enquiry_id uuid)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with tz as (select timezone from studio where id = p_studio),\n  trials as (\n    -- A trial is either for a child already on the books (in-app) or for a\n    -- prospect known only through their enquiry (email). Neither: skipped.\n    select t.id, t.status, t.attended_at, t.created_at, t.class_id, t.student_id,\n           s.family_id, cs.starts_at, e.contact_name, e.contact_email, e.child_name, e.id as enquiry_id\n      from trial t\n      left join student s on s.id = t.student_id and s.deleted_at is null\n      left join enquiry e on e.id = t.enquiry_id and e.deleted_at is null\n      left join class_session cs on cs.id = t.session_id\n     where t.studio_id = p_studio and t.deleted_at is null\n       and (s.family_id is not null or e.contact_email is not null)\n  )\n  select r.id, r.event, x.subject_id, x.family_id, x.student_id, x.class_id, x.starts_at, x.expires_at,\n         x.contact_name, x.contact_email, x.child_name, x.enquiry_id\n    from automation_rule r\n    cross join lateral (\n      -- Confirmation: booked, and the class has not happened yet.\n      select t.id as subject_id, t.family_id, t.student_id, t.class_id, t.starts_at, null::timestamptz as expires_at,\n             t.contact_name, t.contact_email, t.child_name, t.enquiry_id\n        from trials t\n       where r.event = 'trial_booked' and t.status = 'booked' and t.starts_at > p_now\n      union all\n      -- 48 hours before, but not if the booking was made inside that window.\n      select t.id, t.family_id, t.student_id, t.class_id, t.starts_at, null,\n             t.contact_name, t.contact_email, t.child_name, t.enquiry_id\n        from trials t\n       where r.event = 'trial_reminder_48h' and t.status = 'booked'\n         and p_now >= t.starts_at - interval '48 hours' and p_now < t.starts_at - interval '12 hours'\n         and t.created_at < t.starts_at - interval '48 hours'\n      union all\n      -- The morning of the class.\n      select t.id, t.family_id, t.student_id, t.class_id, t.starts_at, null,\n             t.contact_name, t.contact_email, t.child_name, t.enquiry_id\n        from trials t, tz\n       where r.event = 'trial_reminder_same_day' and t.status = 'booked'\n         and (t.starts_at at time zone tz.timezone)::date = (p_now at time zone tz.timezone)::date\n         and p_now < t.starts_at\n      union all\n      -- After the class, while it is still fresh — not weeks later.\n      select t.id, t.family_id, t.student_id, t.class_id, t.starts_at, null,\n             t.contact_name, t.contact_email, t.child_name, t.enquiry_id\n        from trials t\n       where r.event = 'trial_attended' and t.status = 'attended'\n         and coalesce(t.attended_at, t.starts_at) > p_now - interval '7 days'\n      union all\n      select t.id, t.family_id, t.student_id, t.class_id, t.starts_at, null,\n             t.contact_name, t.contact_email, t.child_name, t.enquiry_id\n        from trials t\n       where r.event = 'trial_missed' and t.status = 'missed'\n         and t.starts_at > p_now - interval '7 days'\n      union all\n      select w.id, s.family_id, w.student_id, w.class_id, null, w.offer_expires_at,\n             null, null, null, null\n        from waitlist_entry w join student s on s.id = w.student_id and s.deleted_at is null\n       where r.event = 'waitlist_offer' and w.studio_id = p_studio and w.deleted_at is null\n         and w.status = 'offered' and (w.offer_expires_at is null or w.offer_expires_at > p_now)\n    ) x\n   where r.studio_id = p_studio and r.enabled and r.deleted_at is null\n     and r.template_id is not null\n     and not exists (select 1 from automation_run ar where ar.rule_id = r.id and ar.subject_id = x.subject_id)\n$$;\n\n-- Fill a template for one family. Unknown placeholders are left visible\n-- rather than silently blanked, so a broken template is noticed.\ncreate or replace function app.render_template(\n  p_text text, p_family uuid, p_student uuid, p_class uuid,\n  p_starts timestamptz, p_expires timestamptz, p_tz text,\n  p_guardian text default null, p_child text default null)\n  returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select replace(replace(replace(replace(replace(replace(coalesce(p_text, ''),\n    '{{guardian_name}}', coalesce((select split_part(full_name, ' ', 1) from guardian\n                                    where family_id = p_family and deleted_at is null\n                                    order by is_primary desc limit 1),\n                                  split_part(p_guardian, ' ', 1), 'there')),\n    '{{child_name}}',   coalesce((select first_name from student where id = p_student),\n                                 split_part(p_child, ' ', 1), 'your child')),\n    '{{class_name}}',   coalesce((select name from class where id = p_class), 'class')),\n    '{{session_date}}', coalesce(to_char(p_starts at time zone p_tz, 'FMDay FMDD FMMonth'), '')),\n    '{{session_time}}', coalesce(to_char(p_starts at time zone p_tz, 'HH24:MI'), '')),\n    '{{expires_at}}',   coalesce(to_char(p_expires at time zone p_tz, 'FMDay FMDD FMMonth'), 'the end of the week'))\n$$;\n\n-- ── Expiring offers, and passing the place on ──────────────────────────────\ncreate or replace function app.expire_waitlist_offers(p_studio uuid, p_now timestamptz default now())\n  returns integer\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare e record; n integer := 0; next_id uuid;\nbegin\n  for e in select id, class_id from waitlist_entry\n            where studio_id = p_studio and status = 'offered' and deleted_at is null\n              and offer_expires_at is not null and offer_expires_at <= p_now\n  loop\n    update waitlist_entry set status = 'expired', responded_at = p_now where id = e.id;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (p_studio, auth.uid(), 'expire', 'waitlist_entry', e.id, 'offer lapsed unanswered');\n    n := n + 1;\n    -- The place is still free: offer it to whoever is next, if the class has room.\n    if app.class_enrolled_count(e.class_id) < (select capacity from class where id = e.class_id) then\n      select id into next_id from waitlist_entry\n       where class_id = e.class_id and status = 'waiting' and deleted_at is null\n       order by position limit 1;\n      if next_id is not null then perform app.offer_waitlist_place(next_id); end if;\n    end if;\n  end loop;\n  return n;\nend $$;\n\n-- ── The runner ─────────────────────────────────────────────────────────────\n-- Called by a scheduler (as service_role) or by the office (\"Run now\").\ncreate or replace function app.run_automations(p_studio uuid, p_now timestamptz default now())\n  returns integer\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c record; tpl record; tz text; cid uuid; oid uuid; sent integer := 0;\n        caller text := coalesce(current_setting('request.jwt.claims', true), '');\nbegin\n  if current_setting('role', true) is distinct from 'service_role' and not app.is_admin(p_studio) then\n    raise exception 'FORBIDDEN: only the office runs automations' using errcode = 'insufficient_privilege';\n  end if;\n  select timezone into tz from studio where id = p_studio;\n\n  perform app.expire_waitlist_offers(p_studio, p_now);\n\n  for c in select * from app.automation_candidates(p_studio, p_now) loop\n    select t.subject, t.body into tpl\n      from automation_rule r join communication_template t on t.id = r.template_id and t.deleted_at is null\n     where r.id = c.rule_id;\n    continue when tpl.body is null;\n\n    if c.family_id is not null then\n      -- Sent by the studio, not by whoever pressed Run: drop the caller's\n      -- identity for this one insert. (Clearing claims can only ever take\n      -- privileges away, so this is not something a user could abuse.)\n      perform set_config('request.jwt.claims', '', true);\n      insert into communication (studio_id, kind, channel, family_id, subject, body, inbound)\n      values (p_studio, 'direct', 'in_app', c.family_id,\n              app.render_template(tpl.subject, c.family_id, c.student_id, c.class_id, c.starts_at, c.expires_at, tz),\n              app.render_template(tpl.body,    c.family_id, c.student_id, c.class_id, c.starts_at, c.expires_at, tz),\n              false)\n      returning id into cid;\n      perform set_config('request.jwt.claims', caller, true);\n      oid := null;\n      -- A family nobody has logged in to yet (typically one that has only\n      -- booked a trial) will not see an in-app message: email it as well.\n      if not exists (select 1 from guardian g where g.family_id = c.family_id and g.user_id is not null and g.deleted_at is null) then\n        insert into outbound_message (studio_id, channel, to_name, to_address, subject, body)\n        select p_studio, 'email', g.full_name, g.email,\n               app.render_template(tpl.subject, c.family_id, c.student_id, c.class_id, c.starts_at, c.expires_at, tz),\n               app.render_template(tpl.body,    c.family_id, c.student_id, c.class_id, c.starts_at, c.expires_at, tz)\n          from guardian g where g.family_id = c.family_id and g.email is not null and g.deleted_at is null\n         order by g.is_primary desc limit 1\n        returning id into oid;\n      end if;\n      insert into automation_run (studio_id, rule_id, subject_id, family_id, communication_id, outbound_id, ran_at)\n      values (p_studio, c.rule_id, c.subject_id, c.family_id, cid, oid, p_now)\n      on conflict (rule_id, subject_id) do nothing;\n    else\n      insert into outbound_message (studio_id, channel, to_name, to_address, subject, body, enquiry_id)\n      values (p_studio, 'email', c.contact_name, c.contact_email,\n              app.render_template(tpl.subject, null, null, c.class_id, c.starts_at, c.expires_at, tz, c.contact_name, c.child_name),\n              app.render_template(tpl.body,    null, null, c.class_id, c.starts_at, c.expires_at, tz, c.contact_name, c.child_name),\n              c.enquiry_id)\n      returning id into oid;\n      insert into automation_run (studio_id, rule_id, subject_id, outbound_id, ran_at)\n      values (p_studio, c.rule_id, c.subject_id, oid, p_now)\n      on conflict (rule_id, subject_id) do nothing;\n    end if;\n    sent := sent + 1;\n  end loop;\n  return sent;\nend $$;\n\nrevoke execute on function app.automation_candidates(uuid, timestamptz),\n                           app.render_template(text, uuid, uuid, uuid, timestamptz, timestamptz, text, text, text),\n                           app.expire_waitlist_offers(uuid, timestamptz)\n  from public, anon;\nrevoke execute on function app.render_template(text, uuid, uuid, uuid, timestamptz, timestamptz, text, text, text),\n                           app.expire_waitlist_offers(uuid, timestamptz)\n  from authenticated;\n-- Candidates are readable by the office so the screen can say what is due;\n-- the function itself checks nothing, so it only answers for admins.\ncreate or replace function app.automation_due(p_studio uuid)\n  returns table (rule_id uuid, due integer)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select rule_id, count(*)::int from app.automation_candidates(p_studio)\n   where app.is_admin(p_studio) group by rule_id\n$$;\nrevoke execute on function app.automation_candidates(uuid, timestamptz) from authenticated;\ngrant execute on function app.automation_due(uuid), app.run_automations(uuid, timestamptz) to authenticated;\ngrant execute on function app.run_automations(uuid, timestamptz) to service_role;\n"},{name:"0019_platform.sql",sql:"-- ============================================================================\n-- 0019 · The platform: many dance schools, one operator\n-- ----------------------------------------------------------------------------\n-- Swayvo is sold to many schools. This adds the layer above them:\n--\n--   platform_admin   people who run Swayvo itself\n--   plan             what a school pays for, and its limits\n--   studio.status    trialling · active · past_due · suspended · cancelled\n--   studio_invitation  how anyone joins a school — owner, admin, teacher,\n--                    parent or student — by a single-use link\n--   support_access_grant / support_session\n--                    how Swayvo staff see inside a school: only when its owner\n--                    has granted it, only for a limited time, only read-only,\n--                    never health records, and always on the school's record\n--\n-- Two principles carry the design:\n--\n-- 1. Swayvo staff are not studio members. Being a platform admin grants no\n--    access to any school's families or children. The console reads\n--    account-level facts through app.platform_* functions, which return\n--    counts, plan and owner contact — never a child.\n--\n-- 2. \"Read-only\" is enforced by Postgres, not by hiding buttons. Reads run in\n--    READ ONLY transactions (see lib/db/client.ts). Support access and a\n--    suspended school's memberships exist only inside such a transaction, so\n--    there is no write path for them to use — the database would refuse it\n--    even if the application tried.\n-- ============================================================================\n\n-- ── Who runs Swayvo ─────────────────────────────────────────────────────────\ncreate table platform_admin (\n  user_id     uuid primary key references user_account(id) on delete cascade,\n  role        text not null default 'support' check (role in ('super_admin', 'support')),\n  created_at  timestamptz not null default now()\n);\n\ncreate or replace function app.is_platform_admin() returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from platform_admin where user_id = auth.uid())\n$$;\ncreate or replace function app.is_platform_super() returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from platform_admin where user_id = auth.uid() and role = 'super_admin')\n$$;\n\n-- ── Plans ──────────────────────────────────────────────────────────────────\ncreate table plan (\n  id             uuid primary key default gen_random_uuid(),\n  code           text not null unique check (code ~ '^[a-z][a-z0-9_]*$'),\n  name           text not null,\n  price_minor    integer not null default 0 check (price_minor >= 0),   -- per month\n  max_students   integer check (max_students > 0),                      -- null = unlimited\n  max_locations  integer check (max_locations > 0),\n  max_staff      integer check (max_staff > 0),\n  is_trial       boolean not null default false,\n  active         boolean not null default true,\n  sort           smallint not null default 0,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now()\n);\ncreate trigger plan_touch before update on plan for each row execute function app.touch_updated_at();\n\nalter table studio\n  add column plan_id         uuid references plan(id) on delete restrict,\n  add column status          text not null default 'active'\n                               check (status in ('trialling', 'active', 'past_due', 'suspended', 'cancelled')),\n  add column trial_ends_on   date,\n  add column status_reason   text,\n  add column suspended_at    timestamptz,\n  add column cancelled_at    timestamptz,\n  add column data_deletion_due_on date,\n  add column created_by      uuid references user_account(id) on delete set null;\n\n-- ── Read-only when suspended or cancelled ──────────────────────────────────\n-- A school that cannot write: suspended (unpaid) or cancelled (leaving, data\n-- awaiting deletion). Its people can still sign in and read — and the owner\n-- can export everything — but nothing changes.\ncreate or replace function app.in_read_only_tx() returns boolean\n  language sql stable as $$ select current_setting('transaction_read_only') = 'on' $$;\n\ncreate or replace function app.studio_writable(p_studio uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select app.in_read_only_tx()\n      or exists (select 1 from studio where id = p_studio and deleted_at is null\n                   and status in ('trialling', 'active', 'past_due'))\n$$;\n\n-- ── Support access ─────────────────────────────────────────────────────────\ncreate table support_access_grant (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  granted_by   uuid references user_account(id) on delete set null,\n  reason       text not null check (length(btrim(reason)) >= 3),\n  expires_at   timestamptz not null,\n  revoked_at   timestamptz,\n  revoked_by   uuid references user_account(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  check (expires_at > created_at),\n  check (expires_at <= created_at + interval '7 days')\n);\ncreate index support_grant_live on support_access_grant (studio_id, expires_at) where revoked_at is null;\n\n-- Which school a Swayvo admin is currently looking at. One at a time, so the\n-- app's queries — which rely on RLS, not on a studio filter — never mix two.\ncreate table support_session (\n  user_id     uuid primary key references user_account(id) on delete cascade,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  grant_id    uuid not null references support_access_grant(id) on delete cascade,\n  started_at  timestamptz not null default now()\n);\n\ncreate or replace function app.support_studio_id() returns uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select ss.studio_id\n    from support_session ss\n    join support_access_grant g on g.id = ss.grant_id\n   where ss.user_id = auth.uid()\n     and app.in_read_only_tx()\n     and g.revoked_at is null and g.expires_at > now()\n     and exists (select 1 from platform_admin p where p.user_id = auth.uid())\n$$;\n\ncreate or replace function app.is_support_viewer(p_studio uuid) returns boolean\n  language sql stable as $$ select app.support_studio_id() is not distinct from p_studio $$;\n\n-- ── Membership resolution, now status- and support-aware ───────────────────\n-- Every policy resolves through these, so changing them here changes the\n-- whole permission model at once.\ncreate or replace function app.memberships()\n  returns table (studio_id uuid, role app_role)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select m.studio_id, m.role\n    from membership m\n   where m.user_id = auth.uid() and m.deleted_at is null and app.studio_writable(m.studio_id)\n  union\n  -- Swayvo support sees a school as an administrator would, read-only.\n  select app.support_studio_id(), 'admin'::app_role\n   where app.support_studio_id() is not null\n$$;\n\ncreate or replace function app.guardian_family_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select g.family_id from guardian g\n   where g.user_id = auth.uid() and g.deleted_at is null and app.studio_writable(g.studio_id)\n$$;\n\ncreate or replace function app.teacher_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id from class c\n    join staff_member s on s.id in (c.teacher_id, c.assistant_id)\n   where s.user_id = auth.uid() and s.deleted_at is null and c.deleted_at is null\n     and app.studio_writable(c.studio_id)\n$$;\n\ncreate or replace function app.student_self_id() returns uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id from student s\n   where s.user_id = auth.uid() and s.login_enabled and s.deleted_at is null\n     and app.studio_writable(s.studio_id)\n   limit 1\n$$;\n\n-- Health records are the one thing support never sees, grant or no grant.\ndrop policy medical_read on medical_record;\ncreate policy medical_read on medical_record for select\n  using (deleted_at is null and not app.is_support_viewer(studio_id) and (\n    app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())));\n-- The write policy is `for all`, which covers SELECT too — it must say the\n-- same, or it would quietly re-open what the read policy closes.\ndrop policy medical_write on medical_record;\ncreate policy medical_write on medical_record for all\n  using (deleted_at is null and not app.is_support_viewer(studio_id) and (\n    app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())))\n  with check (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()));\n\n-- Erasing a school deletes thousands of rows; auditing each one against a\n-- studio that is itself being deleted would fail. Rows whose school no\n-- longer exists are not audited individually; the erasure is recorded once,\n-- as a whole (see platform_purge_studio). No session flag is involved: any\n-- user can set a session flag, and none may switch auditing off.\ncreate or replace function app.write_audit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare rec record; sid uuid;\nbegin\n  rec := coalesce(new, old);\n  begin sid := rec.studio_id; exception when others then sid := null; end;\n  if sid is not null and not exists (select 1 from studio where id = sid) then return rec; end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), lower(tg_op), tg_table_name, rec.id,\n          case tg_op when 'DELETE' then 'removed' when 'INSERT' then 'created'\n                     else 'updated' end);\n  return rec;\nend $$;\n\n-- ── Plan limits ────────────────────────────────────────────────────────────\ncreate or replace function app.enforce_plan_limit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p plan; used integer; cap integer; what text;\nbegin\n  if new.deleted_at is not null then return new; end if;\n  select pl.* into p from studio s join plan pl on pl.id = s.plan_id where s.id = new.studio_id;\n  if p.id is null then return new; end if;\n  case tg_table_name\n    when 'student' then\n      cap := p.max_students; what := 'students';\n      select count(*) into used from student where studio_id = new.studio_id and deleted_at is null;\n    when 'location' then\n      cap := p.max_locations; what := 'locations';\n      select count(*) into used from location where studio_id = new.studio_id and deleted_at is null;\n    when 'staff_member' then\n      cap := p.max_staff; what := 'staff';\n      select count(*) into used from staff_member where studio_id = new.studio_id and deleted_at is null;\n  end case;\n  if cap is not null and used >= cap then\n    raise exception 'PLAN_LIMIT: The % plan includes up to % %. Ask Swayvo to move you to a larger plan.',\n      p.name, cap, what using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\n\ncreate trigger student_plan_limit before insert on student\n  for each row execute function app.enforce_plan_limit();\ncreate trigger location_plan_limit before insert on location\n  for each row execute function app.enforce_plan_limit();\ncreate trigger staff_plan_limit before insert on staff_member\n  for each row execute function app.enforce_plan_limit();\n\n-- ── Invitations ────────────────────────────────────────────────────────────\n-- The link holds a random token; the database keeps only its hash, so a copy\n-- of the table is not a set of working invitations.\ncreate table studio_invitation (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  email        text not null check (email ~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$'),\n  full_name    text,\n  role         app_role not null,\n  family_id    uuid references family(id) on delete cascade,\n  student_id   uuid references student(id) on delete cascade,\n  token_hash   text not null unique,\n  invited_by   uuid references user_account(id) on delete set null,\n  expires_at   timestamptz not null default now() + interval '14 days',\n  accepted_at  timestamptz,\n  accepted_by  uuid references user_account(id) on delete set null,\n  revoked_at   timestamptz,\n  created_at   timestamptz not null default now(),\n  check (role <> 'guardian' or family_id is not null),\n  check (role <> 'student' or student_id is not null)\n);\ncreate index invitation_studio on studio_invitation (studio_id, created_at desc);\n\ncreate or replace function app.hash_token(p_token text) returns text\n  language sql immutable as $$ select encode(sha256(convert_to(p_token, 'UTF8')), 'hex') $$;\n\ncreate or replace function app.new_token() returns text\n  language sql volatile as $$\n  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')\n$$;\n\n-- ── Tables' row level security ─────────────────────────────────────────────\nalter table platform_admin       enable row level security;\nalter table platform_admin       force  row level security;\nalter table plan                 enable row level security;\nalter table plan                 force  row level security;\nalter table support_access_grant enable row level security;\nalter table support_access_grant force  row level security;\nalter table support_session      enable row level security;\nalter table support_session      force  row level security;\nalter table studio_invitation    enable row level security;\nalter table studio_invitation    force  row level security;\n\ncreate policy platform_admin_read on platform_admin for select using (app.is_platform_admin());\ncreate policy plan_read on plan for select using (auth.uid() is not null);\ncreate policy plan_write on plan for update using (app.is_platform_super()) with check (app.is_platform_super());\n\n-- A school sees its own grants; Swayvo sees every grant (that one exists is\n-- account-level information — it is what lets support open the view).\ncreate policy support_grant_read on support_access_grant for select\n  using (app.has_role(studio_id, 'owner', 'admin') or app.is_platform_admin());\ncreate policy support_session_own on support_session for select using (user_id = auth.uid());\n\ncreate policy invitation_read on studio_invitation for select\n  using (app.is_admin(studio_id) or app.is_platform_admin());\n\n-- Swayvo sees the account row of every school (name, status, plan, contact),\n-- which is what the console lists. Nothing below the studio row.\ncreate policy studio_platform_read on studio for select using (app.is_platform_admin());\n\ngrant select on platform_admin, plan, support_access_grant, support_session, studio_invitation to authenticated;\ngrant update on plan to authenticated;\ngrant all on platform_admin, plan, support_access_grant, support_session, studio_invitation to service_role;\n\n-- ── The console's view of a school: account facts, never children ──────────\ncreate or replace function app.platform_studios()\n  returns table (\n    id uuid, name text, slug text, status text, status_reason text, plan_code text, plan_name text,\n    price_minor integer, max_students integer, max_locations integer, max_staff integer,\n    trial_ends_on date, data_deletion_due_on date, created_at timestamptz,\n    students integer, families integer, locations integer, staff integer,\n    owners integer, admins integer, teachers integer, guardians integer, student_logins integer,\n    owner_names text, owner_emails text, pending_invites integer,\n    support_until timestamptz, last_activity timestamptz)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id, s.name, s.slug, s.status, s.status_reason, p.code, p.name, p.price_minor,\n         p.max_students, p.max_locations, p.max_staff, s.trial_ends_on, s.data_deletion_due_on, s.created_at,\n         (select count(*)::int from student x where x.studio_id = s.id and x.deleted_at is null),\n         (select count(*)::int from family x where x.studio_id = s.id and x.deleted_at is null),\n         (select count(*)::int from location x where x.studio_id = s.id and x.deleted_at is null),\n         (select count(*)::int from staff_member x where x.studio_id = s.id and x.deleted_at is null),\n         (select count(*)::int from membership m where m.studio_id = s.id and m.deleted_at is null and m.role = 'owner'),\n         (select count(*)::int from membership m where m.studio_id = s.id and m.deleted_at is null and m.role = 'admin'),\n         (select count(*)::int from membership m where m.studio_id = s.id and m.deleted_at is null and m.role = 'teacher'),\n         (select count(*)::int from membership m where m.studio_id = s.id and m.deleted_at is null and m.role = 'guardian'),\n         (select count(*)::int from membership m where m.studio_id = s.id and m.deleted_at is null and m.role = 'student'),\n         (select string_agg(u.full_name, ', ' order by u.full_name) from membership m join user_account u on u.id = m.user_id\n           where m.studio_id = s.id and m.deleted_at is null and m.role = 'owner'),\n         (select string_agg(u.email, ', ' order by u.full_name) from membership m join user_account u on u.id = m.user_id\n           where m.studio_id = s.id and m.deleted_at is null and m.role = 'owner'),\n         (select count(*)::int from studio_invitation i where i.studio_id = s.id\n            and i.accepted_at is null and i.revoked_at is null and i.expires_at > now()),\n         (select max(g.expires_at) from support_access_grant g where g.studio_id = s.id\n            and g.revoked_at is null and g.expires_at > now()),\n         (select max(a.at) from audit_log a where a.studio_id = s.id)\n    from studio s left join plan p on p.id = s.plan_id\n   where s.deleted_at is null and app.is_platform_admin()\n   order by s.created_at desc\n$$;\n\n-- Account history for the console: what happened to the account, by whom.\ncreate or replace function app.platform_events(p_studio uuid)\n  returns table (at timestamptz, action text, summary text, actor text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select a.at, a.action, a.summary, u.full_name\n    from audit_log a left join user_account u on u.id = a.actor_id\n   where a.studio_id = p_studio and a.entity in ('studio', 'studio_invitation', 'support_access_grant', 'support_session', 'membership')\n     -- Decisions about the account, not the row-level trail every insert leaves.\n     and a.action not in ('insert', 'update', 'delete')\n     and app.is_platform_admin()\n   order by a.at desc limit 30\n$$;\n\n-- Pending invitations for a school, as the console may see them.\ncreate or replace function app.platform_invitations(p_studio uuid)\n  returns table (id uuid, email text, full_name text, role app_role, created_at timestamptz,\n                 expires_at timestamptz, accepted_at timestamptz, revoked_at timestamptz)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select i.id, i.email, i.full_name, i.role, i.created_at, i.expires_at, i.accepted_at, i.revoked_at\n    from studio_invitation i\n   where i.studio_id = p_studio and i.role in ('owner', 'admin') and app.is_platform_admin()\n   order by i.created_at desc\n$$;\n\n-- ── Platform actions ───────────────────────────────────────────────────────\ncreate or replace function app.require_platform_admin() returns void\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_platform_admin() then\n    raise exception 'FORBIDDEN: only Swayvo platform staff can do this' using errcode = 'insufficient_privilege';\n  end if;\nend $$;\n\ncreate or replace function app.platform_log(p_studio uuid, p_action text, p_entity text, p_id uuid, p_summary text)\n  returns void\n  language sql security definer set search_path = public, app, pg_temp as $$\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (p_studio, auth.uid(), p_action, p_entity, p_id, p_summary)\n$$;\n\n-- A new school and an invitation for its owner. Returns the token once —\n-- the only time it exists in the clear.\ncreate or replace function app.platform_create_studio(\n  p_name text, p_owner_name text, p_owner_email text, p_plan_code text, p_trial_days integer default 30)\n  returns table (studio_id uuid, invitation_token text)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare sid uuid; pid uuid; slug_ text; n int := 1; tok text;\nbegin\n  perform app.require_platform_admin();\n  if length(btrim(coalesce(p_name, ''))) < 2 then\n    raise exception 'INVALID: the school needs a name' using errcode = 'check_violation';\n  end if;\n  if length(btrim(coalesce(p_owner_name, ''))) < 2 then\n    raise exception 'INVALID: the owner needs a name' using errcode = 'check_violation';\n  end if;\n  select id into pid from plan where code = p_plan_code and active;\n  if pid is null then raise exception 'INVALID: unknown plan %', p_plan_code using errcode = 'check_violation'; end if;\n  if coalesce(p_trial_days, 0) < 0 or p_trial_days > 90 then\n    raise exception 'INVALID: a trial is between 0 and 90 days' using errcode = 'check_violation';\n  end if;\n\n  slug_ := trim(both '-' from regexp_replace(lower(p_name), '[^a-z0-9]+', '-', 'g'));\n  if slug_ = '' then slug_ := 'school'; end if;\n  while exists (select 1 from studio where slug = case when n = 1 then slug_ else slug_ || '-' || n end) loop\n    n := n + 1;\n  end loop;\n  if n > 1 then slug_ := slug_ || '-' || n; end if;\n\n  insert into studio (name, slug, plan_id, status, trial_ends_on, contact_email, created_by)\n  values (btrim(p_name), slug_, pid,\n          case when p_trial_days > 0 then 'trialling' else 'active' end,\n          case when p_trial_days > 0 then current_date + p_trial_days end,\n          lower(btrim(p_owner_email)), auth.uid())\n  returning id into sid;\n\n  tok := app.new_token();\n  insert into studio_invitation (studio_id, email, full_name, role, token_hash, invited_by)\n  values (sid, lower(btrim(p_owner_email)), btrim(p_owner_name), 'owner', app.hash_token(tok), auth.uid());\n\n  perform app.platform_log(sid, 'create', 'studio', sid, 'School created by Swayvo; owner invited: ' || lower(btrim(p_owner_email)));\n  return query select sid, tok;\nend $$;\n\ncreate or replace function app.platform_set_plan(p_studio uuid, p_plan_code text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare pid uuid; pname text; students_ int; cap int;\nbegin\n  perform app.require_platform_admin();\n  select id, name, max_students into pid, pname, cap from plan where code = p_plan_code and active;\n  if pid is null then raise exception 'INVALID: unknown plan %', p_plan_code using errcode = 'check_violation'; end if;\n  select count(*) into students_ from student where studio_id = p_studio and deleted_at is null;\n  -- Moving down a plan never deletes anything; it just stops new additions.\n  update studio set plan_id = pid, updated_at = now() where id = p_studio;\n  perform app.platform_log(p_studio, 'plan', 'studio', p_studio, 'Plan changed to ' || pname ||\n    case when cap is not null and students_ > cap then format(' (over its %s-student limit: %s)', cap, students_) else '' end);\nend $$;\n\ncreate or replace function app.platform_set_status(p_studio uuid, p_status text, p_reason text default null)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare old_status text;\nbegin\n  perform app.require_platform_admin();\n  select status into old_status from studio where id = p_studio and deleted_at is null;\n  if old_status is null then raise exception 'NOT_FOUND: school' using errcode = 'no_data_found'; end if;\n  if p_status not in ('trialling', 'active', 'past_due', 'suspended', 'cancelled') then\n    raise exception 'INVALID: unknown status %', p_status using errcode = 'check_violation';\n  end if;\n  if p_status in ('suspended', 'cancelled') and length(btrim(coalesce(p_reason, ''))) < 3 then\n    raise exception 'INVALID: say why — the school''s owner will see it' using errcode = 'check_violation';\n  end if;\n  update studio set\n    status = p_status,\n    status_reason = nullif(btrim(coalesce(p_reason, '')), ''),\n    suspended_at = case when p_status = 'suspended' then now() when p_status in ('active','trialling','past_due') then null else suspended_at end,\n    cancelled_at = case when p_status = 'cancelled' then now() when p_status <> 'cancelled' then null else cancelled_at end,\n    -- 30 days to export before data is deleted, as the school's contract will say.\n    data_deletion_due_on = case when p_status = 'cancelled' then current_date + 30 else null end,\n    trial_ends_on = case when p_status = 'trialling' then coalesce(trial_ends_on, current_date + 14) else trial_ends_on end,\n    updated_at = now()\n   where id = p_studio;\n  perform app.platform_log(p_studio, 'status', 'studio', p_studio,\n    old_status || ' → ' || p_status || coalesce(': ' || nullif(btrim(coalesce(p_reason, '')), ''), ''));\nend $$;\n\ncreate or replace function app.platform_extend_trial(p_studio uuid, p_days integer) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.require_platform_admin();\n  if p_days not between 1 and 60 then\n    raise exception 'INVALID: extend by 1 to 60 days' using errcode = 'check_violation';\n  end if;\n  update studio set trial_ends_on = greatest(coalesce(trial_ends_on, current_date), current_date) + p_days,\n                    status = 'trialling', updated_at = now()\n   where id = p_studio and status in ('trialling', 'past_due');\n  if not found then raise exception 'INVALID: only a school on trial can have it extended' using errcode = 'check_violation'; end if;\n  perform app.platform_log(p_studio, 'trial', 'studio', p_studio, format('Trial extended by %s days', p_days));\nend $$;\n\n-- Erasure, once a cancelled school's notice period has passed. Super admins\n-- only, and it takes everything: families, children, health records, money.\ncreate or replace function app.platform_purge_studio(p_studio uuid, p_confirm_name text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s studio;\nbegin\n  if not app.is_platform_super() then\n    raise exception 'FORBIDDEN: only a Swayvo super admin can erase a school' using errcode = 'insufficient_privilege';\n  end if;\n  select * into s from studio where id = p_studio;\n  if s.id is null then raise exception 'NOT_FOUND: school' using errcode = 'no_data_found'; end if;\n  if s.status <> 'cancelled' or s.data_deletion_due_on is null or s.data_deletion_due_on > current_date then\n    raise exception 'INVALID: a school can be erased only once cancelled and its notice period (until %) has passed',\n      coalesce(s.data_deletion_due_on::text, 'not set') using errcode = 'check_violation';\n  end if;\n  if p_confirm_name is distinct from s.name then\n    raise exception 'INVALID: type the school''s name exactly to confirm' using errcode = 'check_violation';\n  end if;\n  -- Children of the studio reference each other with RESTRICT (an invoice\n  -- holds its family); clear the money first so the cascade can run.\n  delete from payment where studio_id = p_studio;\n  delete from invoice_item where studio_id = p_studio;\n  delete from invoice where studio_id = p_studio;\n  delete from attendance_record where studio_id = p_studio;\n  delete from enrolment where studio_id = p_studio;\n  delete from class_session where studio_id = p_studio;\n  delete from class where studio_id = p_studio;\n  delete from student where studio_id = p_studio;\n  delete from studio where id = p_studio;\n  -- The erasure itself is recorded without the school: studio_id is gone.\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (null, auth.uid(), 'purge', 'studio', p_studio, 'School erased after cancellation: ' || s.slug);\nend $$;\n\ncreate or replace function app.platform_set_plan_limits(\n  p_code text, p_name text, p_price_minor integer, p_students integer, p_locations integer, p_staff integer)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_platform_super() then\n    raise exception 'FORBIDDEN: only a Swayvo super admin can change plans' using errcode = 'insufficient_privilege';\n  end if;\n  update plan set name = btrim(p_name), price_minor = p_price_minor, max_students = p_students,\n                  max_locations = p_locations, max_staff = p_staff\n   where code = p_code;\n  if not found then raise exception 'NOT_FOUND: plan %', p_code using errcode = 'no_data_found'; end if;\nend $$;\n\n-- ── Inviting people into a school ──────────────────────────────────────────\n-- Owners invite anyone. Admins invite teachers, parents and students, not\n-- other admins or owners. Swayvo invites owners (and admins) when setting a\n-- school up.\ncreate or replace function app.create_invitation(\n  p_studio uuid, p_email text, p_role app_role, p_full_name text default null,\n  p_family uuid default null, p_student uuid default null)\n  returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare tok text; is_owner boolean; is_admin_ boolean; platform boolean;\nbegin\n  is_owner := app.has_role(p_studio, 'owner');\n  is_admin_ := app.is_admin(p_studio);\n  platform := app.is_platform_admin() and p_role in ('owner', 'admin');\n  if not (is_owner or (is_admin_ and p_role not in ('owner', 'admin')) or platform) then\n    raise exception 'FORBIDDEN: %', case when is_admin_ then 'only an owner can invite owners and administrators'\n                                         else 'only the school office can invite people' end\n      using errcode = 'insufficient_privilege';\n  end if;\n  if not app.studio_writable(p_studio) then\n    raise exception 'FORBIDDEN: this school''s account is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if p_email is null or p_email !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n    raise exception 'INVALID: that does not look like an email address' using errcode = 'check_violation';\n  end if;\n  if p_role = 'guardian' and not exists (select 1 from family where id = p_family and studio_id = p_studio and deleted_at is null) then\n    raise exception 'INVALID: choose the family this parent belongs to' using errcode = 'check_violation';\n  end if;\n  if p_role = 'student' and not exists (select 1 from student where id = p_student and studio_id = p_studio and deleted_at is null) then\n    raise exception 'INVALID: choose the student this login is for' using errcode = 'check_violation';\n  end if;\n  -- One live invitation per person and role: a re-invite replaces the old link.\n  update studio_invitation set revoked_at = now()\n   where studio_id = p_studio and lower(email) = lower(btrim(p_email)) and role = p_role\n     and accepted_at is null and revoked_at is null;\n\n  tok := app.new_token();\n  insert into studio_invitation (studio_id, email, full_name, role, family_id, student_id, token_hash, invited_by)\n  values (p_studio, lower(btrim(p_email)), nullif(btrim(coalesce(p_full_name, '')), ''), p_role,\n          case when p_role = 'guardian' then p_family end, case when p_role = 'student' then p_student end,\n          app.hash_token(tok), auth.uid());\n  perform app.platform_log(p_studio, 'invite', 'studio_invitation', null, p_role || ' invited: ' || lower(btrim(p_email)));\n  return tok;\nend $$;\n\ncreate or replace function app.revoke_invitation(p_id uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare inv studio_invitation;\nbegin\n  select * into inv from studio_invitation where id = p_id;\n  if inv.id is null then raise exception 'NOT_FOUND: invitation' using errcode = 'no_data_found'; end if;\n  if not (app.has_role(inv.studio_id, 'owner')\n          or (app.is_admin(inv.studio_id) and inv.role not in ('owner', 'admin'))\n          or (app.is_platform_admin() and inv.role in ('owner', 'admin'))) then\n    raise exception 'FORBIDDEN: you cannot withdraw this invitation' using errcode = 'insufficient_privilege';\n  end if;\n  update studio_invitation set revoked_at = now() where id = p_id and accepted_at is null;\n  perform app.platform_log(inv.studio_id, 'revoke', 'studio_invitation', p_id, inv.role || ' invitation withdrawn: ' || inv.email);\nend $$;\n\n-- What an invitation link says, before anyone signs in. Only the token's\n-- holder can ask, and the answer is the school's name, the role and whether\n-- the link still works.\ncreate or replace function app.invitation_preview(p_token text)\n  returns table (studio_name text, role app_role, email text, full_name text, family_name text,\n                 student_name text, state text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.name, i.role, i.email, i.full_name, f.name, st.first_name,\n         case when i.accepted_at is not null then 'accepted'\n              when i.revoked_at is not null then 'revoked'\n              when i.expires_at <= now() then 'expired'\n              when s.status in ('suspended', 'cancelled') then 'unavailable'\n              else 'valid' end\n    from studio_invitation i\n    join studio s on s.id = i.studio_id\n    left join family f on f.id = i.family_id\n    left join student st on st.id = i.student_id\n   where i.token_hash = app.hash_token(p_token)\n$$;\n\n-- Accepting. Runs as the person who has just signed in (in production,\n-- Supabase Auth has created their auth user; here, the demo has). When the\n-- session carries an email claim it must match the invitation's.\ncreate or replace function app.accept_invitation(p_token text, p_full_name text)\n  returns table (studio_id uuid, role app_role)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare inv studio_invitation; me uuid := auth.uid(); claimed text := lower(auth.jwt() ->> 'email');\n        nm text := btrim(coalesce(p_full_name, '')); gid uuid; sid_ uuid;\nbegin\n  if me is null then raise exception 'FORBIDDEN: sign in to accept an invitation' using errcode = 'insufficient_privilege'; end if;\n  select * into inv from studio_invitation where token_hash = app.hash_token(p_token) for update;\n  if inv.id is null then raise exception 'INVALID: this invitation link is not valid' using errcode = 'check_violation'; end if;\n  if inv.accepted_at is not null then raise exception 'INVALID: this invitation has already been used' using errcode = 'check_violation'; end if;\n  if inv.revoked_at is not null then raise exception 'INVALID: this invitation was withdrawn' using errcode = 'check_violation'; end if;\n  if inv.expires_at <= now() then raise exception 'INVALID: this invitation has expired — ask for a new one' using errcode = 'check_violation'; end if;\n  if not exists (select 1 from studio s where s.id = inv.studio_id and s.status not in ('suspended', 'cancelled')) then\n    raise exception 'INVALID: this school is not taking new members at the moment' using errcode = 'check_violation';\n  end if;\n  if claimed is not null and claimed <> inv.email then\n    raise exception 'FORBIDDEN: this invitation was sent to %', inv.email using errcode = 'insufficient_privilege';\n  end if;\n  if length(nm) < 2 then nm := coalesce(inv.full_name, split_part(inv.email, '@', 1)); end if;\n\n  insert into user_account (id, email, full_name) values (me, inv.email, nm)\n  on conflict (id) do nothing;\n\n  -- Revive a removed membership rather than duplicating it.\n  update membership set deleted_at = null, updated_at = now()\n   where user_id = me and membership.studio_id = inv.studio_id and membership.role = inv.role;\n  if not found then\n    insert into membership (user_id, studio_id, role) values (me, inv.studio_id, inv.role)\n    on conflict do nothing;\n  end if;\n\n  if inv.role = 'teacher' then\n    -- Link the teacher record the office already made, or make one.\n    update staff_member set user_id = me\n     where id = (select id from staff_member where staff_member.studio_id = inv.studio_id\n                   and lower(email) = inv.email and user_id is null and deleted_at is null limit 1);\n    if not found and not exists (select 1 from staff_member where staff_member.studio_id = inv.studio_id and user_id = me) then\n      insert into staff_member (studio_id, user_id, display_name, email) values (inv.studio_id, me, nm, inv.email);\n    end if;\n  elsif inv.role = 'guardian' then\n    select id into gid from guardian where family_id = inv.family_id and deleted_at is null\n       and user_id is null and lower(email) = inv.email limit 1;\n    if gid is not null then\n      update guardian set user_id = me where id = gid;\n    elsif not exists (select 1 from guardian where family_id = inv.family_id and user_id = me) then\n      insert into guardian (studio_id, family_id, user_id, full_name, email)\n      values (inv.studio_id, inv.family_id, me, nm, inv.email);\n    end if;\n  elsif inv.role = 'student' then\n    -- The account is linked, but a child's login stays off until a guardian\n    -- approves it — unless the invitation came from that child's guardian.\n    update student set user_id = me,\n           login_enabled = exists (select 1 from guardian g where g.family_id = student.family_id\n                                     and g.user_id = inv.invited_by and g.deleted_at is null),\n           login_approved_by = case when exists (select 1 from guardian g where g.family_id = student.family_id\n                                     and g.user_id = inv.invited_by and g.deleted_at is null) then inv.invited_by end\n     where id = inv.student_id;\n  end if;\n\n  update studio_invitation set accepted_at = now(), accepted_by = me where id = inv.id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (inv.studio_id, me, 'accept', 'membership', inv.id, inv.role || ' joined: ' || inv.email);\n  return query select inv.studio_id, inv.role;\nend $$;\n\n-- ── Managing who has access ────────────────────────────────────────────────\ncreate or replace function app.set_member_role(p_membership uuid, p_role app_role) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare m membership;\nbegin\n  select * into m from membership where id = p_membership and deleted_at is null;\n  if m.id is null then raise exception 'NOT_FOUND: member' using errcode = 'no_data_found'; end if;\n  if not app.has_role(m.studio_id, 'owner') then\n    raise exception 'FORBIDDEN: only an owner can change someone''s role' using errcode = 'insufficient_privilege';\n  end if;\n  if m.role not in ('owner', 'admin', 'teacher') or p_role not in ('owner', 'admin', 'teacher') then\n    raise exception 'INVALID: parents and students are linked to a family or child — invite them in that role instead'\n      using errcode = 'check_violation';\n  end if;\n  if m.role = 'owner' and p_role <> 'owner' and\n     (select count(*) from membership where studio_id = m.studio_id and role = 'owner' and deleted_at is null) <= 1 then\n    raise exception 'INVALID: a school must keep at least one owner' using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from membership where user_id = m.user_id and studio_id = m.studio_id and role = p_role\n               and deleted_at is null and id <> m.id) then\n    update membership set deleted_at = now() where id = m.id;\n  else\n    update membership set role = p_role, updated_at = now() where id = m.id;\n  end if;\n  if p_role = 'teacher' and not exists (select 1 from staff_member where studio_id = m.studio_id and user_id = m.user_id and deleted_at is null) then\n    insert into staff_member (studio_id, user_id, display_name, email)\n    select m.studio_id, u.id, u.full_name, u.email from user_account u where u.id = m.user_id;\n  end if;\n  perform app.platform_log(m.studio_id, 'role', 'membership', m.id, m.role || ' → ' || p_role);\nend $$;\n\ncreate or replace function app.remove_member(p_membership uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare m membership;\nbegin\n  select * into m from membership where id = p_membership and deleted_at is null;\n  if m.id is null then raise exception 'NOT_FOUND: member' using errcode = 'no_data_found'; end if;\n  if not (app.has_role(m.studio_id, 'owner') or (app.is_admin(m.studio_id) and m.role in ('teacher', 'guardian', 'student'))) then\n    raise exception 'FORBIDDEN: you cannot remove this person' using errcode = 'insufficient_privilege';\n  end if;\n  if m.role = 'owner' and (select count(*) from membership where studio_id = m.studio_id and role = 'owner' and deleted_at is null) <= 1 then\n    raise exception 'INVALID: a school must keep at least one owner' using errcode = 'check_violation';\n  end if;\n  update membership set deleted_at = now(), updated_at = now() where id = m.id;\n  -- Their records stay (a teacher's registers, a parent's family); only the\n  -- ability to sign in to this school goes.\n  if m.role = 'guardian' then\n    update guardian set user_id = null where studio_id = m.studio_id and user_id = m.user_id;\n  elsif m.role = 'student' then\n    update student set login_enabled = false where studio_id = m.studio_id and user_id = m.user_id;\n  elsif m.role = 'teacher' then\n    update staff_member set user_id = null where studio_id = m.studio_id and user_id = m.user_id;\n  end if;\n  perform app.platform_log(m.studio_id, 'remove', 'membership', m.id, m.role || ' access removed');\nend $$;\n\n-- ── Granting and using support access ──────────────────────────────────────\ncreate or replace function app.grant_support_access(p_studio uuid, p_hours integer, p_reason text) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare gid uuid;\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the school''s owner can let Swayvo support in' using errcode = 'insufficient_privilege';\n  end if;\n  if p_hours not between 1 and 168 then\n    raise exception 'INVALID: access lasts between 1 hour and 7 days' using errcode = 'check_violation';\n  end if;\n  update support_access_grant set revoked_at = now(), revoked_by = auth.uid()\n   where studio_id = p_studio and revoked_at is null and expires_at > now();\n  insert into support_access_grant (studio_id, granted_by, reason, expires_at)\n  values (p_studio, auth.uid(), btrim(p_reason), now() + make_interval(hours => p_hours))\n  returning id into gid;\n  perform app.platform_log(p_studio, 'grant', 'support_access_grant', gid,\n    format('Swayvo support may view the account, read-only, for %s hours: %s', p_hours, btrim(p_reason)));\n  return gid;\nend $$;\n\ncreate or replace function app.revoke_support_access(p_studio uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the school''s owner can change support access' using errcode = 'insufficient_privilege';\n  end if;\n  update support_access_grant set revoked_at = now(), revoked_by = auth.uid()\n   where studio_id = p_studio and revoked_at is null and expires_at > now();\n  delete from support_session where studio_id = p_studio;\n  perform app.platform_log(p_studio, 'revoke', 'support_access_grant', null, 'Support access ended by the owner');\nend $$;\n\ncreate or replace function app.start_support_session(p_studio uuid) returns timestamptz\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g support_access_grant;\nbegin\n  perform app.require_platform_admin();\n  select * into g from support_access_grant\n   where studio_id = p_studio and revoked_at is null and expires_at > now()\n   order by expires_at desc limit 1;\n  if g.id is null then\n    raise exception 'FORBIDDEN: the school''s owner has not granted support access' using errcode = 'insufficient_privilege';\n  end if;\n  insert into support_session (user_id, studio_id, grant_id) values (auth.uid(), p_studio, g.id)\n  on conflict (user_id) do update set studio_id = excluded.studio_id, grant_id = excluded.grant_id, started_at = now();\n  -- On the school's own record, where its owner can see it.\n  perform app.platform_log(p_studio, 'view', 'support_session', g.id, 'Swayvo support opened a read-only view');\n  return g.expires_at;\nend $$;\n\ncreate or replace function app.end_support_session() returns void\n  language sql security definer set search_path = public, app, pg_temp as $$\n  delete from support_session where user_id = auth.uid()\n$$;\n\n-- ── Grants ─────────────────────────────────────────────────────────────────\nrevoke execute on function app.platform_log(uuid, text, text, uuid, text) from public, authenticated, anon;\ngrant execute on function\n  app.is_platform_admin(), app.is_platform_super(), app.platform_studios(), app.platform_events(uuid),\n  app.platform_invitations(uuid),\n  app.platform_create_studio(text, text, text, text, integer), app.platform_set_plan(uuid, text),\n  app.platform_set_status(uuid, text, text), app.platform_extend_trial(uuid, integer),\n  app.platform_purge_studio(uuid, text), app.platform_set_plan_limits(text, text, integer, integer, integer, integer),\n  app.create_invitation(uuid, text, app_role, text, uuid, uuid), app.revoke_invitation(uuid),\n  app.invitation_preview(text), app.accept_invitation(text, text),\n  app.set_member_role(uuid, app_role), app.remove_member(uuid),\n  app.grant_support_access(uuid, integer, text), app.revoke_support_access(uuid),\n  app.start_support_session(uuid), app.end_support_session()\n  to authenticated;\ngrant execute on function app.invitation_preview(text) to anon;\n\n-- ── Plans every installation starts with ───────────────────────────────────\ninsert into plan (code, name, price_minor, max_students, max_locations, max_staff, is_trial, sort) values\n  ('trial',   'Trial',   0,     50,   1,    5,    true,  0),\n  ('starter', 'Starter', 4900,  100,  1,    5,    false, 1),\n  ('studio',  'Studio',  9900,  300,  3,    20,   false, 2),\n  ('academy', 'Academy', 17900, null, null, null, false, 3);\n"},{name:"0020_teacher_medical.sql",sql:"-- ============================================================================\n-- 0020 · What a teacher knows about a child's health\n-- ----------------------------------------------------------------------------\n-- Decision (studio owner, Nov 2026): a teacher in the room needs the whole of\n-- a child's recorded medical need — allergies, conditions, medications and\n-- the emergency plan — not only the allergy line, and needs to see at a\n-- glance which children have one. The family doctor stays with the office.\n--\n-- Still true:\n--   * teachers cannot read medical_record; this view is their only route\n--   * only for children in classes they teach (or trial in, or take to an\n--     event); a student sees their own, a guardian their children's\n--   * Swayvo support never sees any of it, grant or no grant\n--\n-- Changes:\n--   * conditions and medications are now in the brief\n--   * has_medical_need: anything recorded at all, so a teacher sees a marker\n--     for every child with a need; requires_alert stays the \"urgent\" flag\n--   * every emergency contact, in order, with relationship\n--   * photo consent, so a teacher knows whom not to photograph\n-- ============================================================================\n\ncreate or replace view student_safety_brief\n  with (security_invoker = false) as\nselect s.id as student_id,\n       s.studio_id,\n       s.first_name,\n       s.last_name,\n       m.allergies,\n       m.action_plan,\n       m.requires_alert,\n       (select ec.full_name from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_name,\n       (select ec.phone from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_phone,\n       m.conditions,\n       m.medications,\n       coalesce(m.requires_alert, false)\n         or coalesce(nullif(btrim(m.allergies), ''), nullif(btrim(m.conditions), ''),\n                     nullif(btrim(m.medications), ''), nullif(btrim(m.action_plan), '')) is not null\n         as has_medical_need,\n       coalesce((select jsonb_agg(jsonb_build_object(\n                   'name', ec.full_name, 'relationship', ec.relationship, 'phone', ec.phone)\n                   order by ec.priority, ec.created_at)\n                  from emergency_contact ec where ec.student_id = s.id and ec.deleted_at is null),\n                '[]'::jsonb) as emergency_contacts,\n       (select c.granted from consent_record c\n         where c.student_id = s.id and c.kind = 'photography' and c.deleted_at is null\n           and (c.expires_at is null or c.expires_at > now())\n         order by c.granted_at desc limit 1) as photo_consent\n  from student s\n  left join medical_record m on m.student_id = s.id and m.deleted_at is null\n where s.deleted_at is null\n   and not app.is_support_viewer(s.studio_id)\n   and (app.is_admin(s.studio_id)\n        or (app.has_role(s.studio_id, 'teacher')\n            and (s.id in (select app.teacher_student_ids())\n                 or s.id in (select app.teacher_event_student_ids())))\n        or s.id in (select app.guardian_student_ids())\n        or s.id = app.student_self_id());\n\ngrant select on student_safety_brief to authenticated, service_role;\n"},{name:"0021_medical_requests.sql",sql:"-- ============================================================================\n-- 0021 · Acting on a parent's medical update in one step\n-- ----------------------------------------------------------------------------\n-- A parent tells the studio something about their child's health. The office\n-- either acknowledges it, or acknowledges it AND puts it on the child's\n-- record. Doing the second as two separate actions invites the failure that\n-- matters: the parent is told \"done\" and the record never changes, or the\n-- record changes and the parent is never told. So it is one function, one\n-- transaction.\n--\n-- Only the office may do it. Teachers can read requests (0010) but health\n-- records are not theirs to write.\n-- ============================================================================\n\ncreate or replace function app.acknowledge_medical_update(\n  p_request uuid, p_record jsonb default null, p_message text default null, p_student uuid default null)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  r studio_request; kid uuid; child text; msg text;\nbegin\n  select * into r from studio_request where id = p_request and deleted_at is null;\n  if r.id is null then raise exception 'NOT_FOUND: request' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(r.studio_id) then\n    raise exception 'FORBIDDEN: only the studio office can act on medical updates' using errcode = 'insufficient_privilege';\n  end if;\n  if r.kind <> 'medical_update' then\n    raise exception 'INVALID: this is not a medical update' using errcode = 'check_violation';\n  end if;\n  if r.status not in ('open', 'in_progress') then\n    raise exception 'INVALID: this update has already been answered' using errcode = 'check_violation';\n  end if;\n\n  -- Which child. The request usually says; if not, the office chooses one of\n  -- that family's children.\n  kid := coalesce(r.student_id, p_student);\n  if kid is not null and not exists (select 1 from student s where s.id = kid and s.family_id = r.family_id\n                                       and s.studio_id = r.studio_id and s.deleted_at is null) then\n    raise exception 'INVALID: that child is not in this family' using errcode = 'check_violation';\n  end if;\n  select first_name into child from student where id = kid;\n\n  if p_record is not null then\n    if kid is null then\n      raise exception 'INVALID: choose which child this update is about' using errcode = 'check_violation';\n    end if;\n    -- Only the fields the office sent are changed; anything left out stays.\n    insert into medical_record (studio_id, student_id, allergies, conditions, medications, action_plan,\n                                requires_alert, updated_by)\n    values (r.studio_id, kid,\n            nullif(btrim(p_record ->> 'allergies'), ''), nullif(btrim(p_record ->> 'conditions'), ''),\n            nullif(btrim(p_record ->> 'medications'), ''), nullif(btrim(p_record ->> 'action_plan'), ''),\n            coalesce((p_record ->> 'requires_alert')::boolean, false), auth.uid())\n    on conflict (student_id) do update set\n      allergies      = case when p_record ? 'allergies'   then nullif(btrim(p_record ->> 'allergies'), '')   else medical_record.allergies end,\n      conditions     = case when p_record ? 'conditions'  then nullif(btrim(p_record ->> 'conditions'), '')  else medical_record.conditions end,\n      medications    = case when p_record ? 'medications' then nullif(btrim(p_record ->> 'medications'), '') else medical_record.medications end,\n      action_plan    = case when p_record ? 'action_plan' then nullif(btrim(p_record ->> 'action_plan'), '') else medical_record.action_plan end,\n      requires_alert = case when p_record ? 'requires_alert' then (p_record ->> 'requires_alert')::boolean else medical_record.requires_alert end,\n      updated_by = auth.uid(), updated_at = now(), deleted_at = null;\n  end if;\n\n  msg := nullif(btrim(coalesce(p_message, '')), '');\n  if msg is null then\n    msg := case when p_record is not null\n      then 'Thank you — we have updated ' || coalesce(child || '''s', 'your child''s')\n           || ' medical record, and their teachers can now see it.'\n      else 'Thank you — we have received your update' || coalesce(' about ' || child, '')\n           || ' and will add it to their record.' end;\n  end if;\n\n  update studio_request\n     set status = case when p_record is not null then 'closed'::request_status else 'answered'::request_status end,\n         student_id = coalesce(student_id, kid),\n         answer = msg, answered_by = auth.uid(), answered_at = now(), updated_at = now()\n   where id = r.id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (r.studio_id, auth.uid(), case when p_record is not null then 'record' else 'acknowledge' end,\n          'studio_request', r.id,\n          case when p_record is not null then 'Medical update acknowledged and added to the record'\n               else 'Medical update acknowledged' end);\n\n  perform app.notify_family(r.family_id, 'request_answered', 'The studio replied: ' || r.subject,\n                            left(msg, 120), '/family/enquiries');\nend $$;\n\ngrant execute on function app.acknowledge_medical_update(uuid, jsonb, text, uuid) to authenticated;\n"},{name:"0022_branding.sql",sql:"-- ============================================================================\n-- 0022 · A school's own brand\n-- ----------------------------------------------------------------------------\n-- Each school shows its own name, logo and colour to its people, \"powered by\n-- Swayvo\". The owner sets them (studio_write already limits updates to\n-- owners; a suspended school cannot change them).\n--\n-- The logo is stored as a raster image. Uploads are redrawn to PNG in the\n-- browser before saving, so an SVG with script in it never reaches anyone —\n-- and the constraint below refuses anything that is not a PNG, JPEG or WebP\n-- data URL (the demo) or an https URL (file storage, in production).\n-- ============================================================================\n\nalter table studio add column brand_colour text\n  check (brand_colour is null or brand_colour ~ '^#[0-9a-f]{6}$');\n\nalter table studio add constraint studio_logo_safe check (\n  logo_url is null\n  or (logo_url ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' and length(logo_url) <= 400000)\n  or logo_url ~ '^https://');\n"},{name:"0023_operations.sql",sql:"-- ============================================================================\n-- 0023 · The weekly realities: trials, cancellations, cover, moves, contacts\n-- ----------------------------------------------------------------------------\n-- R-005  Every child in a session is on its register. A trial booking always\n--        creates (or links) a child record with an emergency contact.\n-- R-004  Cancel, move or cover ONE session, telling everyone affected.\n-- R-030  Teachers can ask the office for cover.\n-- R-042  Move a student to another class in one step.\n-- R-016  Parents keep their own details and emergency contacts current; the\n--        office is told. Parents cannot re-link logins or move records.\n-- ============================================================================\n\n-- ── Prospects ──────────────────────────────────────────────────────────────\n-- A family that has only booked a trial. It is real enough to hold a child,\n-- an emergency contact and a register line, and becomes an ordinary family\n-- when the trial converts.\nalter table family add column is_prospect boolean not null default false;\n\n-- Make (or find) the child record a trial needs. Used when booking, and to\n-- bring trials booked before this migration into line.\ncreate or replace function app.ensure_trial_student(p_trial uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t trial; e enquiry; fam uuid; kid uuid; last_ text;\nbegin\n  select * into t from trial where id = p_trial;\n  if t.student_id is not null then return t.student_id; end if;\n  if t.enquiry_id is null then return null; end if;\n  select * into e from enquiry where id = t.enquiry_id;\n  if e.child_name is null or e.child_dob is null then return null; end if;\n\n  fam := e.family_id;\n  if fam is null then\n    last_ := nullif(split_part(btrim(e.contact_name), ' ',\n                     array_length(string_to_array(btrim(e.contact_name), ' '), 1)), '');\n    insert into family (studio_id, name, is_prospect)\n    values (t.studio_id, coalesce(last_, btrim(e.contact_name)) || ' family', true)\n    returning id into fam;\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary)\n    values (t.studio_id, fam, e.contact_name, e.contact_email, e.contact_phone, true);\n  end if;\n\n  insert into student (studio_id, family_id, first_name, last_name, date_of_birth)\n  values (t.studio_id, fam, split_part(btrim(e.child_name), ' ', 1),\n          coalesce(nullif(substr(btrim(e.child_name), length(split_part(btrim(e.child_name), ' ', 1)) + 2), ''),\n                   coalesce(last_, '—')),\n          e.child_dob)\n  returning id into kid;\n\n  -- The enquirer is the person to ring until the family says otherwise.\n  if e.contact_phone is not null then\n    insert into emergency_contact (studio_id, student_id, full_name, relationship, phone, priority)\n    values (t.studio_id, kid, e.contact_name, 'Parent/carer', e.contact_phone, 1);\n  end if;\n\n  update trial set student_id = kid where id = t.id;\n  update enquiry set family_id = fam, student_id = kid where id = e.id;\n  return kid;\nend $$;\n\n-- Booking a trial. Either an existing child, or a new one described in\n-- p_child: {first_name, last_name, date_of_birth, contact_name, contact_email,\n-- contact_phone, emergency_name?, emergency_phone?, enquiry_id?}.\ncreate or replace function app.book_trial(p_session uuid, p_student uuid default null, p_child jsonb default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; kid uuid := p_student; fam uuid; tid uuid; enq uuid := (p_child ->> 'enquiry_id')::uuid;\n        ephone text; ename text;\nbegin\n  select s.*, c.trial_price_minor, c.name as class_name into cs\n    from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: that session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then\n    raise exception 'FORBIDDEN: only the office books trials here' using errcode = 'insufficient_privilege';\n  end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: that session is cancelled' using errcode = 'check_violation'; end if;\n\n  if kid is null then\n    if p_child is null or coalesce(btrim(p_child ->> 'first_name'), '') = ''\n       or (p_child ->> 'date_of_birth') is null or coalesce(btrim(p_child ->> 'contact_name'), '') = '' then\n      raise exception 'INVALID: a new child needs a name, date of birth and a parent or carer' using errcode = 'check_violation';\n    end if;\n    ephone := coalesce(nullif(btrim(p_child ->> 'emergency_phone'), ''), nullif(btrim(p_child ->> 'contact_phone'), ''));\n    if ephone is null then\n      raise exception 'INVALID: a phone number to ring in an emergency is needed before a child joins a class'\n        using errcode = 'check_violation';\n    end if;\n    insert into family (studio_id, name, is_prospect, created_by)\n    values (cs.studio_id, coalesce(nullif(btrim(p_child ->> 'last_name'), ''), split_part(p_child ->> 'contact_name', ' ', 2), 'New') || ' family', true, auth.uid())\n    returning id into fam;\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary)\n    values (cs.studio_id, fam, btrim(p_child ->> 'contact_name'), nullif(btrim(p_child ->> 'contact_email'), ''),\n            nullif(btrim(p_child ->> 'contact_phone'), ''), true);\n    insert into student (studio_id, family_id, first_name, last_name, date_of_birth, created_by)\n    values (cs.studio_id, fam, btrim(p_child ->> 'first_name'), coalesce(nullif(btrim(p_child ->> 'last_name'), ''), '—'),\n            (p_child ->> 'date_of_birth')::date, auth.uid())\n    returning id into kid;\n    ename := coalesce(nullif(btrim(p_child ->> 'emergency_name'), ''), btrim(p_child ->> 'contact_name'));\n    insert into emergency_contact (studio_id, student_id, full_name, relationship, phone, priority)\n    values (cs.studio_id, kid, ename, case when ename = btrim(p_child ->> 'contact_name') then 'Parent/carer' end, ephone, 1);\n    if enq is not null then\n      update enquiry set family_id = fam, student_id = kid, stage = 'trial_booked', updated_at = now()\n       where id = enq and studio_id = cs.studio_id;\n    end if;\n  else\n    if not exists (select 1 from student where id = kid and studio_id = cs.studio_id and deleted_at is null) then\n      raise exception 'NOT_FOUND: that child' using errcode = 'no_data_found';\n    end if;\n    if not exists (select 1 from emergency_contact where student_id = kid and deleted_at is null) then\n      raise exception 'INVALID: % has no emergency contact — add one before they join a class',\n        (select first_name from student where id = kid) using errcode = 'check_violation';\n    end if;\n  end if;\n\n  insert into trial (studio_id, class_id, session_id, student_id, enquiry_id, status, price_minor, created_by)\n  values (cs.studio_id, cs.class_id, cs.id, kid, enq, 'booked', cs.trial_price_minor, auth.uid())\n  returning id into tid;\n  return tid;\nend $$;\n\n-- Converting reuses the child the trial already has, and the family stops\n-- being a prospect.\ncreate or replace function app.on_trial_converted() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.status = 'converted' and old.status <> 'converted' and new.student_id is not null then\n    update family set is_prospect = false\n     where id = (select family_id from student where id = new.student_id) and is_prospect;\n  end if;\n  return null;\nend $$;\ncreate trigger trial_converted after update of status on trial\n  for each row execute function app.on_trial_converted();\n\n-- ── One session at a time ──────────────────────────────────────────────────\nalter table class_session add column original_starts_at timestamptz;\nalter table class_session add column changed_at timestamptz;\nalter table class_session add column changed_by uuid references user_account(id) on delete set null;\n\n-- Tell a session's families and teachers what changed. A class notice for\n-- the record, plus a notification each so it is seen.\ncreate or replace function app.announce_session(p_session uuid, p_subject text, p_body text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; fam uuid; u uuid;\nbegin\n  select s.*, c.name, c.teacher_id as class_teacher into cs\n    from class_session s join class c on c.id = s.class_id where s.id = p_session;\n  insert into communication (studio_id, kind, channel, class_id, subject, body)\n  values (cs.studio_id, 'class_broadcast', 'in_app', cs.class_id, p_subject, p_body);\n  for fam in\n    select distinct st.family_id from enrolment e join student st on st.id = e.student_id\n     where e.class_id = cs.class_id and e.status = 'active' and e.deleted_at is null\n    union\n    select distinct st.family_id from trial t join student st on st.id = t.student_id\n     where t.session_id = cs.id and t.status = 'booked' and t.deleted_at is null\n  loop\n    perform app.notify_family(fam, 'schedule_change', p_subject, left(p_body, 140), '/family/schedule');\n  end loop;\n  for u in\n    select distinct sm.user_id from staff_member sm\n     where sm.id in (cs.class_teacher, cs.teacher_id) and sm.user_id is not null\n  loop\n    perform app.notify_user(cs.studio_id, u, 'schedule_change', p_subject, left(p_body, 140), '/teach');\n  end loop;\nend $$;\n\ncreate or replace function app.session_label(p_session uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.name || ' on ' || to_char(s.starts_at at time zone st.timezone, 'FMDay FMDD FMMonth \"at\" HH24:MI')\n    from class_session s join class c on c.id = s.class_id join studio st on st.id = s.studio_id\n   where s.id = p_session\n$$;\n\ncreate or replace function app.cancel_session(p_session uuid, p_reason text, p_message text default null, p_notify boolean default true)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs class_session; lbl text;\nbegin\n  select * into cs from class_session where id = p_session and deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then raise exception 'FORBIDDEN: only the office can cancel a class' using errcode = 'insufficient_privilege'; end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: already cancelled' using errcode = 'check_violation'; end if;\n  if cs.register_closed_at is not null then\n    raise exception 'INVALID: this class has already been taught — its register is closed' using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then raise exception 'INVALID: give a reason' using errcode = 'check_violation'; end if;\n  lbl := app.session_label(p_session);\n  update class_session set status = 'cancelled', cancel_reason = btrim(p_reason),\n         changed_at = now(), changed_by = auth.uid(), updated_at = now() where id = p_session;\n  update trial set status = 'cancelled', outcome_note = 'Session cancelled: ' || btrim(p_reason), updated_at = now()\n   where session_id = p_session and status = 'booked';\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (cs.studio_id, auth.uid(), 'cancel', 'class_session', p_session, lbl || ': ' || btrim(p_reason));\n  if p_notify then\n    perform app.announce_session(p_session, 'Cancelled: ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), 'Sorry — ' || lbl || ' is cancelled (' || btrim(p_reason) || ').'));\n  end if;\nend $$;\n\ncreate or replace function app.move_session(p_session uuid, p_starts timestamptz, p_room uuid default null,\n                                            p_message text default null, p_notify boolean default true)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs class_session; was text; now_ text;\nbegin\n  select * into cs from class_session where id = p_session and deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then raise exception 'FORBIDDEN: only the office can move a class' using errcode = 'insufficient_privilege'; end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: a cancelled class cannot be moved' using errcode = 'check_violation'; end if;\n  if cs.register_closed_at is not null then raise exception 'INVALID: this class has already been taught' using errcode = 'check_violation'; end if;\n  if p_starts is null then raise exception 'INVALID: choose when it moves to' using errcode = 'check_violation'; end if;\n  if p_room is not null and not exists (select 1 from room where id = p_room and studio_id = cs.studio_id and deleted_at is null) then\n    raise exception 'INVALID: unknown room' using errcode = 'check_violation';\n  end if;\n  was := app.session_label(p_session);\n  update class_session set original_starts_at = coalesce(original_starts_at, starts_at),\n         ends_at = p_starts + (ends_at - starts_at), starts_at = p_starts,\n         room_id = coalesce(p_room, room_id), changed_at = now(), changed_by = auth.uid(), updated_at = now()\n   where id = p_session;\n  now_ := app.session_label(p_session);\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (cs.studio_id, auth.uid(), 'move', 'class_session', p_session, was || ' → ' || now_);\n  if p_notify then\n    perform app.announce_session(p_session, 'Moved: ' || now_,\n      coalesce(nullif(btrim(p_message), ''), was || ' has moved to ' || now_ || '.'));\n  end if;\nend $$;\n\ncreate or replace function app.cover_session(p_session uuid, p_teacher uuid, p_message text default null, p_notify_families boolean default false)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; who text; lbl text; u uuid;\nbegin\n  select s.*, c.teacher_id as class_teacher into cs from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then raise exception 'FORBIDDEN: only the office can arrange cover' using errcode = 'insufficient_privilege'; end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: that class is cancelled' using errcode = 'check_violation'; end if;\n  if p_teacher is not null then\n    select display_name, user_id into who, u from staff_member\n     where id = p_teacher and studio_id = cs.studio_id and status = 'active' and deleted_at is null;\n    if who is null then raise exception 'INVALID: choose an active teacher at this school' using errcode = 'check_violation'; end if;\n    if p_teacher = cs.class_teacher then p_teacher := null; end if;   -- back to the usual teacher\n  end if;\n  lbl := app.session_label(p_session);\n  update class_session set teacher_id = p_teacher, changed_at = now(), changed_by = auth.uid(), updated_at = now()\n   where id = p_session;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (cs.studio_id, auth.uid(), 'cover', 'class_session', p_session,\n          lbl || coalesce(': covered by ' || who, ': back to the usual teacher'));\n  -- The covering teacher must hear directly; families only if the office wants.\n  if p_teacher is not null then\n    perform app.notify_user(cs.studio_id, u, 'cover_assigned', 'You are covering ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), 'The register and safety notes for this class are on your Today screen.'), '/teach');\n  end if;\n  if p_notify_families and p_teacher is not null then\n    perform app.announce_session(p_session, 'Cover: ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), who || ' will be teaching ' || lbl || '.'));\n  end if;\n  -- Any open cover request for this session is settled.\n  update studio_request set status = 'answered', answer = coalesce('Covered by ' || who, 'No cover needed'),\n         answered_by = auth.uid(), answered_at = now()\n   where session_id = p_session and status in ('open', 'in_progress');\nend $$;\n\n-- A covering teacher may see that class — around the date they cover it.\n-- (Access is per class in the policies; bounding it in time keeps a one-off\n-- cover from becoming a standing view of someone else's students.)\ncreate or replace function app.teacher_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id from class c\n    join staff_member s on s.id in (c.teacher_id, c.assistant_id)\n   where s.user_id = auth.uid() and s.deleted_at is null and c.deleted_at is null\n     and app.studio_writable(c.studio_id)\n  union\n  select cs.class_id from class_session cs\n    join staff_member s on s.id = cs.teacher_id\n   where s.user_id = auth.uid() and s.deleted_at is null and cs.deleted_at is null\n     and cs.status <> 'cancelled'\n     and cs.starts_at between now() - interval '2 days' and now() + interval '14 days'\n     and app.studio_writable(cs.studio_id)\n$$;\n\n-- ── Cover requests from teachers ───────────────────────────────────────────\nalter table studio_request add column session_id uuid references class_session(id) on delete set null;\n\ncreate or replace function app.request_cover(p_session uuid, p_reason text) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; rid uuid; me uuid;\nbegin\n  select s.*, c.teacher_id as class_teacher into cs from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  select id into me from staff_member where user_id = auth.uid() and studio_id = cs.studio_id and deleted_at is null;\n  if me is null or me <> coalesce(cs.teacher_id, cs.class_teacher) then\n    raise exception 'FORBIDDEN: you can only ask for cover for a class you are teaching' using errcode = 'insufficient_privilege';\n  end if;\n  if cs.starts_at < now() then raise exception 'INVALID: that class has already started' using errcode = 'check_violation'; end if;\n  insert into studio_request (studio_id, session_id, kind, subject, body, raised_by)\n  values (cs.studio_id, p_session, 'other', 'Cover needed: ' || app.session_label(p_session),\n          coalesce(nullif(btrim(p_reason), ''), 'Cover requested.'), auth.uid())\n  returning id into rid;\n  return rid;\nend $$;\n\n-- ── Moving a student between classes ───────────────────────────────────────\ncreate or replace function app.transfer_enrolment(p_enrolment uuid, p_to_class uuid, p_note text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare e enrolment; to_name text; from_name text; new_id uuid;\nbegin\n  select * into e from enrolment where id = p_enrolment and status = 'active' and deleted_at is null;\n  if e.id is null then raise exception 'NOT_FOUND: an active place' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(e.studio_id) then raise exception 'FORBIDDEN: only the office can move a student' using errcode = 'insufficient_privilege'; end if;\n  if p_to_class = e.class_id then raise exception 'INVALID: that is the same class' using errcode = 'check_violation'; end if;\n  select name into to_name from class where id = p_to_class and studio_id = e.studio_id and deleted_at is null;\n  if to_name is null then raise exception 'INVALID: choose a class at this school' using errcode = 'check_violation'; end if;\n  select name into from_name from class where id = e.class_id;\n  -- Join first: if the new class is full, nothing changes.\n  insert into enrolment (studio_id, class_id, student_id, status, started_on, created_by, note)\n  values (e.studio_id, p_to_class, e.student_id, 'active', current_date, auth.uid(),\n          coalesce(nullif(btrim(p_note), ''), 'Moved from ' || from_name))\n  returning id into new_id;\n  perform app.withdraw_enrolment(p_enrolment, 'Moved to ' || to_name);\n  return new_id;\nend $$;\n\n-- ── Parents keeping their details current ──────────────────────────────────\n-- guardian_self_update (0006) lets a parent edit their family's guardian\n-- rows. It must not let them re-link a login, move the row to another family,\n-- or make themselves primary over someone else's objection — only contact\n-- details change.\ncreate or replace function app.guardian_self_edit_guard() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if auth.uid() is null or app.is_admin(old.studio_id) then return new; end if;\n  if new.user_id is distinct from old.user_id or new.family_id is distinct from old.family_id\n     or new.studio_id is distinct from old.studio_id or new.deleted_at is distinct from old.deleted_at then\n    raise exception 'FORBIDDEN: only the office can change who is linked to a family' using errcode = 'insufficient_privilege';\n  end if;\n  return new;\nend $$;\ncreate trigger guardian_self_edit before update on guardian\n  for each row execute function app.guardian_self_edit_guard();\n\n-- The office hears when a family changes contact details.\ncreate or replace function app.on_contact_change() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare fam uuid; fname text; sid uuid;\nbegin\n  if auth.uid() is null or app.is_staff(coalesce(new.studio_id, old.studio_id)) then return null; end if;\n  if tg_table_name = 'guardian' then fam := coalesce(new.family_id, old.family_id);\n  else select family_id into fam from student where id = coalesce(new.student_id, old.student_id); end if;\n  select name, studio_id into fname, sid from family where id = fam;\n  perform app.notify_admins(sid, 'contact_updated', 'Contact details updated',\n    'The ' || fname || ' updated ' || case tg_table_name when 'guardian' then 'their contact details.' else 'an emergency contact.' end,\n    '/people?id=' || fam);\n  return null;\nend $$;\ncreate trigger guardian_contact_notify after update on guardian for each row execute function app.on_contact_change();\ncreate trigger emergency_contact_notify after insert or update on emergency_contact for each row execute function app.on_contact_change();\n\ngrant execute on function app.book_trial(uuid, uuid, jsonb), app.cancel_session(uuid, text, text, boolean),\n  app.move_session(uuid, timestamptz, uuid, text, boolean), app.cover_session(uuid, uuid, text, boolean),\n  app.request_cover(uuid, text), app.transfer_enrolment(uuid, uuid, text), app.session_label(uuid)\n  to authenticated;\nrevoke execute on function app.ensure_trial_student(uuid), app.announce_session(uuid, text, text) from public, authenticated, anon;\ngrant execute on function app.ensure_trial_student(uuid) to service_role;\n\n-- A parent (or the office) removes an emergency contact. Soft delete through a\n-- function because the row would no longer be visible to the caller under RLS.\n-- The last contact cannot be removed: someone must always be reachable.\ncreate or replace function app.remove_emergency_contact(p_contact uuid) returns void\nlanguage plpgsql security definer set search_path = public, pg_temp as $$\ndeclare ec emergency_contact;\nbegin\n  select * into ec from emergency_contact where id = p_contact and deleted_at is null;\n  if ec.id is null or not (app.is_admin(ec.studio_id) or ec.student_id in (select app.guardian_student_ids())) then\n    raise exception 'FORBIDDEN: not your contact' using errcode = '42501';\n  end if;\n  if (select count(*) from emergency_contact where student_id = ec.student_id and deleted_at is null) <= 1 then\n    raise exception 'A child needs at least one emergency contact — add another before removing this one.';\n  end if;\n  update emergency_contact set deleted_at = now(), updated_at = now() where id = p_contact;\n  if not app.is_staff(ec.studio_id) then\n    perform app.notify_admins(ec.studio_id, 'contact_updated', 'Emergency contact removed',\n      ec.full_name || ' was removed as a contact for ' || (select first_name || ' ' || last_name from student where id = ec.student_id), '/people');\n  end if;\nend $$;\nrevoke all on function app.remove_emergency_contact(uuid) from public;\ngrant execute on function app.remove_emergency_contact(uuid) to authenticated;\n"},{name:"0024_billing_runs.sql",sql:"-- ============================================================================\n-- 0024 · Term billing runs and discount rules (R-010, R-011)\n-- ----------------------------------------------------------------------------\n-- A billing run turns the term's enrolments into one draft invoice per family.\n-- The office previews it, raises the drafts, checks them, then issues them all\n-- together. Nothing is charged twice: a child is only billed for a class if no\n-- live invoice line already covers that child in that class this term, so a\n-- second run mid-term picks up new joiners and nothing else.\n--\n-- Discounts are rules, not hand edits:\n--   sibling      the Nth child in a family (and after) gets X% off their classes\n--   multi_class  a child's Nth class (and after) gets X% off\n-- When both apply to a line the larger one is used. They do not stack — a\n-- studio that wants stacking can say so and it is one line to change.\n-- ============================================================================\n\ncreate table discount_rule (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  kind        text not null check (kind in ('sibling', 'multi_class')),\n  from_nth    smallint not null default 2 check (from_nth between 2 and 10),\n  percent     smallint not null default 10 check (percent between 1 and 100),\n  enabled     boolean not null default true,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  unique (studio_id, kind)\n);\n\ncreate table billing_run (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  term_id      uuid not null references term(id) on delete restrict,\n  status       text not null default 'draft' check (status in ('draft', 'issued', 'discarded')),\n  due_on       date not null,\n  invoice_count int not null default 0,\n  total_minor  bigint not null default 0,\n  created_by   uuid references user_account(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  issued_at    timestamptz,\n  issued_by    uuid references user_account(id) on delete set null\n);\n\nalter table invoice add column billing_run_id uuid references billing_run(id) on delete set null;\ncreate index invoice_billing_run_idx on invoice (billing_run_id) where billing_run_id is not null;\n\nalter table discount_rule enable row level security;\nalter table discount_rule force row level security;\nalter table billing_run   enable row level security;\nalter table billing_run   force row level security;\n\ncreate policy discount_rule_read on discount_rule for select\n  using (deleted_at is null and app.is_admin(studio_id));\ncreate policy discount_rule_write on discount_rule for update\n  using (deleted_at is null and app.is_admin(studio_id) and app.studio_writable(studio_id))\n  with check (app.is_admin(studio_id));\ncreate policy billing_run_read on billing_run for select using (app.is_admin(studio_id));\n\ngrant select, update (from_nth, percent, enabled) on discount_rule to authenticated;\ngrant select on billing_run to authenticated;\ngrant all on discount_rule, billing_run to service_role;\n\ncreate trigger discount_rule_touch before update on discount_rule\n  for each row execute function app.touch_updated_at();\n\n-- Every school starts with the two common rules, switched off, so nobody is\n-- discounted until the office decides to.\ncreate or replace function app.default_discount_rules() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  insert into discount_rule (studio_id, kind, from_nth, percent, enabled)\n  values (new.id, 'sibling', 2, 10, false), (new.id, 'multi_class', 3, 15, false)\n  on conflict do nothing;\n  return new;\nend $$;\ncreate trigger studio_default_discounts after insert on studio\n  for each row execute function app.default_discount_rules();\ninsert into discount_rule (studio_id, kind, from_nth, percent, enabled)\n  select id, k.kind, k.n, k.p, false from studio,\n    (values ('sibling', 2, 10), ('multi_class', 3, 15)) k(kind, n, p)\n  on conflict do nothing;\n\n-- ── What a run would raise ─────────────────────────────────────────────────\n-- One row per line. Pure: reads only, writes nothing, so the preview and the\n-- run itself can never disagree.\n--\n-- Pricing by the class's model:\n--   term     the term price; a child who joined after the term began pays for\n--            the sessions left (pro rata by session, rounded to the penny)\n--   monthly  the monthly price × the months the term spans\n--   one_off  the course price\n--   drop_in  nothing — paid class by class\ncreate or replace function app.billing_lines(p_term uuid)\n  returns table (family_id uuid, family_name text, student_id uuid, student_name text,\n                 class_id uuid, class_name text, description text, quantity numeric,\n                 unit_minor int, discount_minor int, discount_reason text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; t term;\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  return query\n  with base as (\n    select f.id fam, f.name fname, s.id stu, s.first_name || ' ' || s.last_name sname,\n           c.id cls, c.name cname, c.pricing,\n           coalesce(e.price_minor, c.price_minor) price, greatest(e.started_on, t.starts_on) from_day,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null\n              and cs.status <> 'cancelled') total_sessions,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null\n              and cs.status <> 'cancelled' and cs.starts_at::date >= greatest(e.started_on, t.starts_on)) left_sessions\n      from enrolment e\n      join class c on c.id = e.class_id and c.deleted_at is null and c.term_id = t.id\n      join student s on s.id = e.student_id and s.deleted_at is null\n      join family f on f.id = s.family_id and f.deleted_at is null and not f.is_prospect\n     where e.deleted_at is null and e.status = 'active' and c.pricing <> 'drop_in'\n       and coalesce(e.price_minor, c.price_minor) > 0\n       -- Already billed this term (a live invoice line for this child and class).\n       and not exists (\n         select 1 from invoice_item ii join invoice i on i.id = ii.invoice_id\n          where ii.student_id = s.id and ii.class_id = c.id and ii.deleted_at is null\n            and i.deleted_at is null and i.status not in ('void', 'refunded') and i.term_id = t.id)\n  ),\n  priced as (\n    select b.*,\n      case b.pricing\n        when 'monthly' then greatest(1, (extract(year from age(t.ends_on, t.starts_on)) * 12\n                                         + extract(month from age(t.ends_on, t.starts_on))\n                                         + case when extract(day from age(t.ends_on, t.starts_on)) > 0 then 1 else 0 end))::numeric\n        else 1::numeric end qty,\n      case when b.pricing = 'term' and b.from_day > t.starts_on and b.total_sessions > 0\n           then round(b.price::numeric * b.left_sessions / b.total_sessions)::int\n           else b.price end unit,\n      case b.pricing\n        when 'term' then case when b.from_day > t.starts_on and b.total_sessions > 0\n                              then format('%s — %s, %s of %s classes from %s', b.cname, t.name, b.left_sessions,\n                                          b.total_sessions, to_char(b.from_day, 'FMDD Mon'))\n                              else b.cname || ' — ' || t.name end\n        when 'monthly' then b.cname || ' — monthly, ' || t.name\n        else b.cname || ' — course fee' end descr\n      from base b\n  ),\n  ranked as (\n    select p.*,\n      -- Siblings: the child with the most tuition counts as the first child.\n      dense_rank() over (partition by p.fam order by child_total desc, p.stu) child_rank,\n      row_number() over (partition by p.stu order by p.unit * p.qty desc, p.cls) class_rank\n      from (select p.*, sum(p.unit * p.qty) over (partition by p.stu) child_total from priced p) p\n  ),\n  rules as (\n    select (select percent from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_n,\n           (select percent from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_n\n  ),\n  disc as (\n    select r.*,\n      case when rules.sib_pct is not null and r.child_rank >= rules.sib_n then rules.sib_pct else 0 end sib,\n      case when rules.mc_pct is not null and r.class_rank >= rules.mc_n then rules.mc_pct else 0 end mc\n      from ranked r, rules\n  )\n  select d.fam, d.fname, d.stu, d.sname, d.cls, d.cname, d.descr, d.qty, d.unit,\n         round(d.unit * d.qty * greatest(d.sib, d.mc) / 100.0)::int,\n         case when greatest(d.sib, d.mc) = 0 then null\n              when d.sib >= d.mc then d.sib || '% sibling discount'\n              else d.mc || '% multi-class discount' end\n    from disc d\n   order by d.fname, d.sname, d.cname;\nend $$;\n\n-- Raise the drafts. One invoice per family, numbered as usual, not yet sent.\ncreate or replace function app.create_billing_run(p_term uuid, p_due date default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; run uuid; fam record; inv uuid; n int := 0; tot bigint := 0;\nbegin\n  select studio_id into sid from term where id = p_term and deleted_at is null;\n  perform app.require_admin(sid);\n  if not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if exists (select 1 from billing_run where term_id = p_term and status = 'draft') then\n    raise exception 'INVALID: there is already a draft run for this term — issue or discard it first'\n      using errcode = 'check_violation';\n  end if;\n\n  insert into billing_run (studio_id, term_id, due_on, created_by)\n  values (sid, p_term, coalesce(p_due, current_date + 14), auth.uid()) returning id into run;\n\n  for fam in\n    select l.family_id, jsonb_agg(jsonb_build_object(\n             'kind', 'tuition', 'description', l.description, 'quantity', l.quantity,\n             'unit_minor', l.unit_minor, 'discount_minor', l.discount_minor,\n             'student_id', l.student_id, 'class_id', l.class_id)) items\n      from app.billing_lines(p_term) l group by l.family_id\n  loop\n    inv := app.create_invoice(fam.family_id, fam.items, coalesce(p_due, current_date + 14),\n                              null, 0, false, p_term);\n    update invoice set billing_run_id = run where id = inv;\n    n := n + 1;\n    tot := tot + (select total_minor from invoice where id = inv);\n  end loop;\n\n  if n = 0 then\n    delete from billing_run where id = run;\n    raise exception 'INVALID: everyone enrolled this term has already been invoiced'\n      using errcode = 'check_violation';\n  end if;\n  update billing_run set invoice_count = n, total_minor = tot where id = run;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'create', 'billing_run', run, n || ' draft invoices');\n  return run;\nend $$;\n\n-- Send them all. Each family's account credit is drawn down as usual.\ncreate or replace function app.issue_billing_run(p_run uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r billing_run; i uuid; n int := 0;\nbegin\n  select * into r from billing_run where id = p_run;\n  perform app.require_admin(r.studio_id);\n  if r.status <> 'draft' then\n    raise exception 'INVALID: this run has already been %', r.status using errcode = 'check_violation';\n  end if;\n  for i in select id from invoice where billing_run_id = p_run and status = 'draft' and deleted_at is null loop\n    perform app.issue_invoice(i);\n    n := n + 1;\n  end loop;\n  update billing_run set status = 'issued', issued_at = now(), issued_by = auth.uid(),\n         invoice_count = n,\n         total_minor = (select coalesce(sum(total_minor), 0) from invoice where billing_run_id = p_run and deleted_at is null)\n   where id = p_run;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (r.studio_id, auth.uid(), 'issue', 'billing_run', p_run, n || ' invoices issued');\n  return n;\nend $$;\n\n-- Throw the drafts away (nothing has been sent, so nothing to void).\ncreate or replace function app.discard_billing_run(p_run uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r billing_run;\nbegin\n  select * into r from billing_run where id = p_run;\n  perform app.require_admin(r.studio_id);\n  if r.status <> 'draft' then\n    raise exception 'INVALID: only a draft run can be discarded' using errcode = 'check_violation';\n  end if;\n  update invoice set deleted_at = now() where billing_run_id = p_run and status = 'draft';\n  update billing_run set status = 'discarded' where id = p_run;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (r.studio_id, auth.uid(), 'delete', 'billing_run', p_run, 'Draft run discarded');\nend $$;\n\nrevoke all on function app.billing_lines(uuid), app.create_billing_run(uuid, date),\n  app.issue_billing_run(uuid), app.discard_billing_run(uuid) from public;\ngrant execute on function app.billing_lines(uuid), app.create_billing_run(uuid, date),\n  app.issue_billing_run(uuid), app.discard_billing_run(uuid) to authenticated;\n"},{name:"0025_term_rollover.sql",sql:"-- ============================================================================\n-- 0025 · Duplicating classes and rolling a term over (R-008)\n-- ----------------------------------------------------------------------------\n-- One function does both: copy these classes into that term. A class copied\n-- into its own term is a duplicate (\"Grade 3 Ballet (copy)\"); copied into the\n-- next term it is the same class carrying on, and its current students can\n-- come with it. Sessions are laid down for the new term, skipping its breaks.\n--\n-- Safe to run twice: a class already carried into a term is not copied again\n-- (copied_from remembers where each class came from), and a child is never\n-- enrolled twice. Re-enrolment respects capacity — longest-standing first —\n-- and reports anyone it could not fit, rather than squeezing them in.\n-- ============================================================================\n\nalter table class add column copied_from uuid references class(id) on delete set null;\ncreate index class_copied_from_idx on class (copied_from) where copied_from is not null;\n\ncreate or replace function app.copy_classes(p_classes uuid[], p_term uuid, p_reenrol boolean default false)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  t term; src class; new_id uuid; n_classes int := 0; n_sessions int := 0; n_enrolled int := 0;\n  n_skipped int := 0; not_fitted jsonb := '[]'::jsonb; e record; free int;\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  if t.id is null then raise exception 'INVALID: no such term' using errcode = 'check_violation'; end if;\n  perform app.require_admin(t.studio_id);\n  if not app.studio_writable(t.studio_id) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n\n  for src in select * from class where id = any(p_classes) and deleted_at is null order by day_of_week, start_time loop\n    if src.studio_id <> t.studio_id then\n      raise exception 'FORBIDDEN: that class belongs to another school' using errcode = 'insufficient_privilege';\n    end if;\n    -- Already carried into this term: leave it be.\n    if src.term_id <> p_term and exists (select 1 from class where copied_from = src.id and term_id = p_term and deleted_at is null) then\n      n_skipped := n_skipped + 1;\n      continue;\n    end if;\n\n    insert into class (studio_id, term_id, dance_style_id, level_id, location_id, room_id, teacher_id,\n                       assistant_id, name, description, day_of_week, start_time, duration_min, capacity,\n                       age_min, age_max, price_minor, pricing, trial_price_minor, trials_enabled,\n                       trial_needs_approval, waitlist_enabled, visibility, prerequisites, created_by, copied_from)\n    values (src.studio_id, p_term, src.dance_style_id, src.level_id, src.location_id, src.room_id, src.teacher_id,\n            src.assistant_id, case when src.term_id = p_term then src.name || ' (copy)' else src.name end,\n            src.description, src.day_of_week, src.start_time, src.duration_min, src.capacity,\n            src.age_min, src.age_max, src.price_minor, src.pricing, src.trial_price_minor, src.trials_enabled,\n            src.trial_needs_approval, src.waitlist_enabled, src.visibility, src.prerequisites, auth.uid(), src.id)\n    returning id into new_id;\n    n_classes := n_classes + 1;\n    n_sessions := n_sessions + app.generate_class_sessions(new_id);\n\n    if p_reenrol and src.term_id <> p_term then\n      free := src.capacity;\n      for e in select en.student_id, en.price_minor, s.first_name || ' ' || s.last_name as name\n                 from enrolment en join student s on s.id = en.student_id and s.deleted_at is null\n                where en.class_id = src.id and en.status = 'active' and en.deleted_at is null\n                order by en.started_on, en.created_at loop\n        if free <= 0 then\n          not_fitted := not_fitted || jsonb_build_object('student', e.name, 'class', src.name);\n          continue;\n        end if;\n        insert into enrolment (studio_id, class_id, student_id, status, started_on, price_minor, note, created_by)\n        values (src.studio_id, new_id, e.student_id, 'active', t.starts_on, e.price_minor,\n                'Carried over from ' || (select name from term where id = src.term_id), auth.uid());\n        free := free - 1;\n        n_enrolled := n_enrolled + 1;\n      end loop;\n    end if;\n  end loop;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (t.studio_id, auth.uid(), 'create', 'term', p_term,\n          format('%s classes copied in, %s students carried over', n_classes, n_enrolled));\n\n  return jsonb_build_object('classes', n_classes, 'sessions', n_sessions, 'enrolled', n_enrolled,\n                            'skipped', n_skipped, 'not_fitted', not_fitted);\nend $$;\n\nrevoke all on function app.copy_classes(uuid[], uuid, boolean) from public;\ngrant execute on function app.copy_classes(uuid[], uuid, boolean) to authenticated;\n"},{name:"0026_self_service.sql",sql:"-- ============================================================================\n-- 0026 · Enquiries and parent self-service (R-014)\n-- ----------------------------------------------------------------------------\n-- Parents can now ask for things without a phone call:\n--   · a place in a class for a child          → the office approves in one tap\n--   · a new child on the account              → the office approves in one tap\n--   · a trial for a child already on the books → booked at once, unless the\n--                                               class says trials need approval\n--   · a waiting-list spot for a full class    → added at once\n-- Prospects can book a trial from the school's public page.\n--\n-- Every parent action is a security-definer function that checks the child is\n-- theirs; parents still cannot write enrolment, student or trial rows directly.\n-- Approvals reuse studio_request, so they arrive in Requests with a\n-- notification exactly like any other request.\n-- ============================================================================\n\nalter table studio_request add column action text check (action in ('join_class', 'add_child', 'trial'));\nalter table studio_request add column class_id uuid references class(id) on delete set null;\nalter table studio_request add column payload jsonb;\n\n-- A class the parent may ask about: live, in a term that has not ended, and\n-- not private unless the child is already in it.\ncreate or replace function app.class_open_to_family(p_class uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from class c join term t on t.id = c.term_id\n                  where c.id = p_class and c.deleted_at is null and t.deleted_at is null\n                    and t.ends_on >= current_date and c.visibility <> 'private');\n$$;\n\ncreate or replace function app.my_child(p_student uuid) returns student\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare s student;\nbegin\n  select * into s from student where id = p_student and deleted_at is null\n     and id in (select app.guardian_student_ids());\n  if s.id is null then\n    raise exception 'FORBIDDEN: that is not your child' using errcode = 'insufficient_privilege';\n  end if;\n  return s;\nend $$;\n\n-- ── A place in a class ─────────────────────────────────────────────────────\ncreate or replace function app.request_class_place(p_student uuid, p_class uuid, p_note text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; c class; rid uuid;\nbegin\n  s := app.my_child(p_student);\n  select * into c from class where id = p_class and studio_id = s.studio_id;\n  if c.id is null or not app.class_open_to_family(p_class) then\n    raise exception 'NOT_FOUND: that class' using errcode = 'no_data_found';\n  end if;\n  if exists (select 1 from enrolment where student_id = s.id and class_id = c.id and status = 'active' and deleted_at is null) then\n    raise exception 'INVALID: % is already in %', s.first_name, c.name using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from studio_request where student_id = s.id and class_id = c.id and action = 'join_class'\n              and status in ('open', 'in_progress') and deleted_at is null) then\n    raise exception 'INVALID: you have already asked for this — the office will be in touch' using errcode = 'check_violation';\n  end if;\n  insert into studio_request (studio_id, family_id, student_id, class_id, kind, action, subject, body, raised_by)\n  values (s.studio_id, s.family_id, s.id, c.id, 'other', 'join_class',\n          'Place for ' || s.first_name || ' in ' || c.name,\n          coalesce(nullif(btrim(p_note), ''), 'Please could ' || s.first_name || ' join ' || c.name || '?'), auth.uid())\n  returning id into rid;\n  return rid;\nend $$;\n\n-- The office says yes: a place if there is one, otherwise the waiting list.\ncreate or replace function app.approve_class_request(p_request uuid, p_message text default null)\n  returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r studio_request; c class; outcome text; msg text;\nbegin\n  select * into r from studio_request where id = p_request and action = 'join_class'\n     and status in ('open', 'in_progress') and deleted_at is null;\n  if r.id is null then raise exception 'INVALID: that request is not waiting' using errcode = 'check_violation'; end if;\n  perform app.require_admin(r.studio_id);\n  select * into c from class where id = r.class_id;\n  if app.class_enrolled_count(c.id) < c.capacity then\n    insert into enrolment (studio_id, class_id, student_id, status, started_on, note, created_by)\n    values (r.studio_id, c.id, r.student_id, 'active', greatest(current_date, (select starts_on from term where id = c.term_id)),\n            'Requested by the family', auth.uid());\n    outcome := 'enrolled';\n    msg := coalesce(nullif(btrim(p_message), ''), 'Good news — there is a place in ' || c.name || '. See you in class!');\n  elsif c.waitlist_enabled then\n    insert into waitlist_entry (studio_id, class_id, student_id, status, position, note)\n    values (r.studio_id, c.id, r.student_id, 'waiting', 0, 'Requested by the family');\n    outcome := 'waitlisted';\n    msg := coalesce(nullif(btrim(p_message), ''), c.name || ' is full just now, so we have put your child on the waiting list. We will be in touch as soon as a place comes up.');\n  else\n    raise exception 'INVALID: % is full and has no waiting list — reply to the family instead', c.name\n      using errcode = 'check_violation';\n  end if;\n  update studio_request set status = 'answered', answer = msg, answered_by = auth.uid(), answered_at = now()\n   where id = r.id;\n  return outcome;\nend $$;\n\n-- ── A new child on the account ─────────────────────────────────────────────\n-- p_child: {first_name, last_name, date_of_birth, emergency_name?, emergency_phone?, notes?}\ncreate or replace function app.request_new_child(p_child jsonb) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g guardian; rid uuid;\nbegin\n  select * into g from guardian where user_id = auth.uid() and deleted_at is null limit 1;\n  if g.id is null then raise exception 'FORBIDDEN: only a parent can add a child' using errcode = 'insufficient_privilege'; end if;\n  if coalesce(btrim(p_child ->> 'first_name'), '') = '' or (p_child ->> 'date_of_birth') is null then\n    raise exception 'INVALID: a name and date of birth are needed' using errcode = 'check_violation';\n  end if;\n  if (p_child ->> 'date_of_birth')::date > current_date or (p_child ->> 'date_of_birth')::date < current_date - interval '100 years' then\n    raise exception 'INVALID: that date of birth does not look right' using errcode = 'check_violation';\n  end if;\n  insert into studio_request (studio_id, family_id, kind, action, subject, body, payload, raised_by)\n  values (g.studio_id, g.family_id, 'other', 'add_child',\n          'New child: ' || btrim(p_child ->> 'first_name') || ' ' || coalesce(btrim(p_child ->> 'last_name'), ''),\n          g.full_name || ' would like to add ' || btrim(p_child ->> 'first_name') || ', born '\n            || to_char((p_child ->> 'date_of_birth')::date, 'FMDD Month YYYY') || '.'\n            || coalesce(E'\\n\\n' || nullif(btrim(p_child ->> 'notes'), ''), ''),\n          p_child, auth.uid())\n  returning id into rid;\n  return rid;\nend $$;\n\ncreate or replace function app.approve_new_child(p_request uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r studio_request; p jsonb; kid uuid; g guardian;\nbegin\n  select * into r from studio_request where id = p_request and action = 'add_child'\n     and status in ('open', 'in_progress') and deleted_at is null;\n  if r.id is null then raise exception 'INVALID: that request is not waiting' using errcode = 'check_violation'; end if;\n  perform app.require_admin(r.studio_id);\n  p := r.payload;\n  insert into student (studio_id, family_id, first_name, last_name, date_of_birth, created_by)\n  values (r.studio_id, r.family_id, btrim(p ->> 'first_name'),\n          coalesce(nullif(btrim(p ->> 'last_name'), ''), (select split_part(name, ' ', 1) from family where id = r.family_id)),\n          (p ->> 'date_of_birth')::date, auth.uid())\n  returning id into kid;\n  -- Someone to ring from day one: the named contact, else the parent who asked.\n  select * into g from guardian where family_id = r.family_id and deleted_at is null\n   order by (user_id = r.raised_by) desc nulls last, is_primary desc limit 1;\n  if coalesce(nullif(btrim(p ->> 'emergency_phone'), ''), g.phone) is not null then\n    insert into emergency_contact (studio_id, student_id, full_name, relationship, phone, priority)\n    values (r.studio_id, kid, coalesce(nullif(btrim(p ->> 'emergency_name'), ''), g.full_name),\n            case when nullif(btrim(p ->> 'emergency_name'), '') is null then 'Parent/carer' end,\n            coalesce(nullif(btrim(p ->> 'emergency_phone'), ''), g.phone), 1);\n  end if;\n  update studio_request set status = 'answered', student_id = kid, answered_by = auth.uid(), answered_at = now(),\n         answer = btrim(p ->> 'first_name') || ' is on your account now. You can book a trial or ask for a class place from their card.'\n   where id = r.id;\n  return kid;\nend $$;\n\n-- ── A trial for a child already on the books ───────────────────────────────\ncreate or replace function app.parent_book_trial(p_session uuid, p_student uuid) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; cs record;\nbegin\n  s := app.my_child(p_student);\n  select x.*, c.name cname, c.trials_enabled, c.trial_needs_approval, c.trial_price_minor, c.capacity\n    into cs from class_session x join class c on c.id = x.class_id\n   where x.id = p_session and x.deleted_at is null and c.studio_id = s.studio_id;\n  if cs.id is null or not app.class_open_to_family(cs.class_id) then\n    raise exception 'NOT_FOUND: that class' using errcode = 'no_data_found';\n  end if;\n  if not cs.trials_enabled then raise exception 'INVALID: % is not taking trials just now', cs.cname using errcode = 'check_violation'; end if;\n  if cs.status <> 'scheduled' or cs.starts_at < now() then\n    raise exception 'INVALID: that session is not open for booking' using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from enrolment where student_id = s.id and class_id = cs.class_id and status = 'active' and deleted_at is null) then\n    raise exception 'INVALID: % is already in %', s.first_name, cs.cname using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from trial where student_id = s.id and class_id = cs.class_id and status in ('booked', 'requested') and deleted_at is null) then\n    raise exception 'INVALID: % already has a trial booked in %', s.first_name, cs.cname using errcode = 'check_violation';\n  end if;\n  if not exists (select 1 from emergency_contact where student_id = s.id and deleted_at is null) then\n    raise exception 'INVALID: add an emergency contact for % first — it is on their card', s.first_name using errcode = 'check_violation';\n  end if;\n  if app.class_enrolled_count(cs.class_id)\n     + (select count(*) from trial where session_id = cs.id and status = 'booked' and deleted_at is null) >= cs.capacity then\n    raise exception 'INVALID: that session is full — try another date' using errcode = 'check_violation';\n  end if;\n  if cs.trial_needs_approval then\n    insert into studio_request (studio_id, family_id, student_id, class_id, kind, action, subject, body, payload, raised_by)\n    values (s.studio_id, s.family_id, s.id, cs.class_id, 'other', 'trial',\n            'Trial for ' || s.first_name || ' in ' || cs.cname,\n            'Asked for ' || to_char(cs.starts_at at time zone (select timezone from studio where id = s.studio_id), 'FMDay DD Month, HH24:MI'),\n            jsonb_build_object('session_id', cs.id), auth.uid());\n    return 'requested';\n  end if;\n  insert into trial (studio_id, class_id, session_id, student_id, status, price_minor, created_by)\n  values (s.studio_id, cs.class_id, cs.id, s.id, 'booked', cs.trial_price_minor, auth.uid());\n  return 'booked';\nend $$;\n\ncreate or replace function app.approve_trial_request(p_request uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r studio_request; tid uuid;\nbegin\n  select * into r from studio_request where id = p_request and action = 'trial'\n     and status in ('open', 'in_progress') and deleted_at is null;\n  if r.id is null then raise exception 'INVALID: that request is not waiting' using errcode = 'check_violation'; end if;\n  perform app.require_admin(r.studio_id);\n  tid := app.book_trial((r.payload ->> 'session_id')::uuid, r.student_id, null);\n  update studio_request set status = 'answered', answered_by = auth.uid(), answered_at = now(),\n         answer = 'The trial is booked — see you there.' where id = r.id;\n  return tid;\nend $$;\n\n-- ── The waiting list for a full class ──────────────────────────────────────\ncreate or replace function app.parent_join_waitlist(p_class uuid, p_student uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; c class; pos int;\nbegin\n  s := app.my_child(p_student);\n  select * into c from class where id = p_class and studio_id = s.studio_id;\n  if c.id is null or not app.class_open_to_family(p_class) then\n    raise exception 'NOT_FOUND: that class' using errcode = 'no_data_found';\n  end if;\n  if not c.waitlist_enabled then raise exception 'INVALID: % does not keep a waiting list', c.name using errcode = 'check_violation'; end if;\n  if app.class_enrolled_count(c.id) < c.capacity then\n    raise exception 'INVALID: % has a place — ask for it instead', c.name using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from waitlist_entry where class_id = c.id and student_id = s.id and status in ('waiting', 'offered') and deleted_at is null) then\n    raise exception 'INVALID: % is already on the list', s.first_name using errcode = 'check_violation';\n  end if;\n  insert into waitlist_entry (studio_id, class_id, student_id, status, position, note)\n  values (s.studio_id, c.id, s.id, 'waiting', 0, 'Joined by the family')\n  returning position into pos;\n  return pos;\nend $$;\n\n-- ── The school's public page ───────────────────────────────────────────────\n-- What a prospect sees: the school, and upcoming sessions with room for a\n-- trial. No names, no numbers beyond \"places left\".\ncreate or replace function app.public_trial_sessions(p_slug text)\n  returns table (studio_name text, session_id uuid, class_name text, style text, starts_at timestamptz,\n                 ends_at timestamptz, age_min smallint, age_max smallint, location text,\n                 trial_price_minor int, places_left int)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select st.name, cs.id, c.name, ds.name, cs.starts_at, cs.ends_at, c.age_min, c.age_max, l.name,\n         c.trial_price_minor,\n         (c.capacity - app.class_enrolled_count(c.id)\n            - (select count(*) from trial t where t.session_id = cs.id and t.status = 'booked' and t.deleted_at is null))::int\n    from studio st\n    join class c on c.studio_id = st.id and c.deleted_at is null and c.visibility = 'public' and c.trials_enabled\n    join class_session cs on cs.class_id = c.id and cs.deleted_at is null and cs.status = 'scheduled'\n         and cs.starts_at between now() + interval '12 hours' and now() + interval '21 days'\n    left join dance_style ds on ds.id = c.dance_style_id\n    left join location l on l.id = c.location_id\n   where st.slug = lower(p_slug) and st.deleted_at is null and app.studio_writable(st.id)\n     and c.capacity - app.class_enrolled_count(c.id)\n         - (select count(*) from trial t where t.session_id = cs.id and t.status = 'booked' and t.deleted_at is null) > 0\n   order by cs.starts_at;\n$$;\n\n-- A prospect books. Creates the enquiry (source 'website') and the trial; the\n-- child gets a record and an emergency contact so they are on the register.\n-- p_form: {contact_name, contact_email, contact_phone, child_name, child_dob, website?}\n-- `website` is a honeypot: people never fill it in, form-filling bots do.\ncreate or replace function app.public_book_trial(p_slug text, p_session uuid, p_form jsonb) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; cs record; enq uuid; tid uuid; dob date;\nbegin\n  select * into st from studio where slug = lower(p_slug) and deleted_at is null;\n  if st.id is null or not app.studio_writable(st.id) then\n    raise exception 'NOT_FOUND: that school' using errcode = 'no_data_found';\n  end if;\n  if coalesce(p_form ->> 'website', '') <> '' then return 'ok'; end if;   -- quietly drop bots\n  if coalesce(btrim(p_form ->> 'contact_name'), '') = '' or coalesce(btrim(p_form ->> 'child_name'), '') = ''\n     or coalesce(btrim(p_form ->> 'contact_phone'), '') = '' or coalesce(p_form ->> 'contact_email', '') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n    raise exception 'INVALID: please give your name, email, a phone number and your child''s name' using errcode = 'check_violation';\n  end if;\n  dob := (p_form ->> 'child_dob')::date;\n  if dob is null or dob > current_date or dob < current_date - interval '100 years' then\n    raise exception 'INVALID: please check your child''s date of birth' using errcode = 'check_violation';\n  end if;\n  select s.id, s.class_id, c.trial_price_minor into cs\n    from app.public_trial_sessions(p_slug) p join class_session s on s.id = p.session_id\n    join class c on c.id = s.class_id where p.session_id = p_session;\n  if cs.id is null then\n    raise exception 'INVALID: that class is full or no longer open for trials — please pick another' using errcode = 'check_violation';\n  end if;\n  -- One booking per email per session, so a double-click is not two trials.\n  if exists (select 1 from trial t join enquiry e on e.id = t.enquiry_id\n              where t.session_id = cs.id and lower(e.contact_email) = lower(btrim(p_form ->> 'contact_email'))\n                and lower(e.child_name) = lower(btrim(p_form ->> 'child_name')) and t.deleted_at is null) then\n    return 'ok';\n  end if;\n  insert into enquiry (studio_id, stage, contact_name, contact_email, contact_phone, child_name, child_dob,\n                       interest_class_id, source)\n  values (st.id, 'trial_booked', btrim(p_form ->> 'contact_name'), lower(btrim(p_form ->> 'contact_email')),\n          btrim(p_form ->> 'contact_phone'), btrim(p_form ->> 'child_name'), dob, cs.class_id, 'website')\n  returning id into enq;\n  insert into trial (studio_id, class_id, session_id, enquiry_id, status, price_minor)\n  values (st.id, cs.class_id, cs.id, enq, 'booked', cs.trial_price_minor)\n  returning id into tid;\n  perform app.ensure_trial_student(tid);\n  return 'ok';\nend $$;\n\nrevoke all on function app.class_open_to_family(uuid), app.my_child(uuid), app.request_class_place(uuid, uuid, text),\n  app.approve_class_request(uuid, text), app.request_new_child(jsonb), app.approve_new_child(uuid),\n  app.parent_book_trial(uuid, uuid), app.approve_trial_request(uuid), app.parent_join_waitlist(uuid, uuid),\n  app.public_trial_sessions(text), app.public_book_trial(text, uuid, jsonb) from public;\ngrant execute on function app.request_class_place(uuid, uuid, text), app.approve_class_request(uuid, text),\n  app.request_new_child(jsonb), app.approve_new_child(uuid), app.parent_book_trial(uuid, uuid),\n  app.approve_trial_request(uuid), app.parent_join_waitlist(uuid, uuid) to authenticated;\ngrant execute on function app.public_trial_sessions(text), app.public_book_trial(text, uuid, jsonb) to authenticated, anon;\ngrant execute on function app.class_open_to_family(uuid) to authenticated;\n\n-- What a parent can do for one child, class by class: already in it, a place\n-- to ask for, a waiting list to join, and the next sessions open for a trial.\ncreate or replace function app.class_options_for_child(p_student uuid)\n  returns table (class_id uuid, name text, style text, day_of_week smallint, start_time time,\n                 age_min smallint, age_max smallint, price_minor int, pricing text, trial_price_minor int,\n                 prerequisites text, enrolled boolean, waiting boolean, asked boolean, trial_booked boolean,\n                 full boolean, waitlist_enabled boolean, trials_enabled boolean, age_fits boolean, trial_sessions jsonb)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare s student; age int;\nbegin\n  s := app.my_child(p_student);\n  age := extract(year from age(current_date, s.date_of_birth));\n  return query\n  select c.id, c.name, ds.name, c.day_of_week, c.start_time, c.age_min, c.age_max, c.price_minor, c.pricing::text,\n         c.trial_price_minor, c.prerequisites,\n         exists (select 1 from enrolment e where e.class_id = c.id and e.student_id = s.id and e.status = 'active' and e.deleted_at is null),\n         exists (select 1 from waitlist_entry w where w.class_id = c.id and w.student_id = s.id and w.status in ('waiting', 'offered') and w.deleted_at is null),\n         exists (select 1 from studio_request r where r.class_id = c.id and r.student_id = s.id and r.status in ('open', 'in_progress') and r.deleted_at is null),\n         exists (select 1 from trial t where t.class_id = c.id and t.student_id = s.id and t.status in ('booked', 'requested') and t.deleted_at is null),\n         app.class_enrolled_count(c.id) >= c.capacity, c.waitlist_enabled, c.trials_enabled,\n         (c.age_min is null or age >= c.age_min) and (c.age_max is null or age <= c.age_max),\n         coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'starts_at', x.starts_at) order by x.starts_at)\n                     from (select cs.id, cs.starts_at from class_session cs\n                            where cs.class_id = c.id and cs.deleted_at is null and cs.status = 'scheduled'\n                              and cs.starts_at > now() + interval '12 hours'\n                              and app.class_enrolled_count(c.id) + (select count(*) from trial t where t.session_id = cs.id\n                                    and t.status = 'booked' and t.deleted_at is null) < c.capacity\n                            order by cs.starts_at limit 3) x), '[]'::jsonb)\n    from class c left join dance_style ds on ds.id = c.dance_style_id\n   where c.studio_id = s.studio_id and app.class_open_to_family(c.id)\n   order by (c.age_min is null or age >= c.age_min) and (c.age_max is null or age <= c.age_max) desc,\n            c.day_of_week, c.start_time;\nend $$;\nrevoke all on function app.class_options_for_child(uuid) from public;\ngrant execute on function app.class_options_for_child(uuid) to authenticated;\n\n-- When the office answers a family's request, the family hears about it.\n-- (Medical updates notify from their own function, so they are left out.)\ncreate or replace function app.on_request_answered() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.status in ('answered', 'closed') and old.status in ('open', 'in_progress')\n     and new.family_id is not null and new.kind <> 'medical_update' and new.answer is not null then\n    perform app.notify_family(new.family_id, 'request_answered', 'The studio replied: ' || new.subject,\n                              left(new.answer, 120), '/family/enquiries');\n  end if;\n  return null;\nend $$;\ncreate trigger request_answered after update of status on studio_request\n  for each row execute function app.on_request_answered();\n\n-- The school's name and look, for its public page. Nothing else.\ncreate or replace function app.public_school(p_slug text)\n  returns table (name text, brand_colour text, logo_url text, open boolean)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.name, s.brand_colour, s.logo_url, app.studio_writable(s.id)\n    from studio s where s.slug = lower(p_slug) and s.deleted_at is null;\n$$;\nrevoke all on function app.public_school(text) from public;\ngrant execute on function app.public_school(text) to authenticated, anon;\n"},{name:"0027_import.sql",sql:"-- ============================================================================\n-- 0027 · Importing families from a spreadsheet (R-013)\n-- ----------------------------------------------------------------------------\n-- One row per child. The browser maps the school's columns onto ours and\n-- sends rows as JSON objects with these keys (all text):\n--   parent_name*, parent_email, parent_phone, second_parent_name,\n--   second_parent_email, second_parent_phone, child_first_name*,\n--   child_last_name, child_dob*, emergency_name, emergency_phone,\n--   allergies, medical_notes, photo_consent, classes (names separated by ; or ,)\n--\n-- Rows are grouped into families by the parent's email (else phone, else\n-- name). A family whose parent email already exists here is added to, not\n-- duplicated (matched by email, else phone); a child already in that family (same name and birthday) is\n-- skipped, so a file can be imported twice safely.\n--\n-- p_commit = false validates only and returns the problems row by row; it\n-- writes nothing. p_commit = true imports everything or nothing: one bad row\n-- and the whole import is refused. Plan limits are enforced by the existing\n-- student trigger, so an import that would pass the plan fails cleanly.\n-- Medical notes are written to the medical record and the import is audited.\n-- ============================================================================\n\ncreate or replace function app.import_families(p_rows jsonb, p_commit boolean default false)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; r jsonb; i int := 0; errs jsonb := '[]'::jsonb; warns jsonb := '[]'::jsonb;\n  fam_key text; fam_id uuid; kid uuid; dob date; cls text; cid uuid;\n  fams jsonb := '{}'::jsonb; n_fam int := 0; n_kid int := 0; n_enrol int := 0; n_skip int := 0; n_med int := 0;\n  existing uuid; adds jsonb := '{}'::jsonb; ecphone text;\nbegin\n  select id into sid from studio where deleted_at is null and app.is_admin(id) limit 1;\n  perform app.require_admin(sid);\n  if p_commit and not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then\n    raise exception 'INVALID: the file has no rows' using errcode = 'check_violation';\n  end if;\n  if jsonb_array_length(p_rows) > 2000 then\n    raise exception 'INVALID: import at most 2,000 rows at a time' using errcode = 'check_violation';\n  end if;\n\n  -- ── Pass 1: check every row; write nothing ──\n  for r in select * from jsonb_array_elements(p_rows) loop\n    i := i + 1;\n    if coalesce(btrim(r ->> 'parent_name'), '') = '' then\n      errs := errs || jsonb_build_object('row', i, 'message', 'No parent name'); end if;\n    if coalesce(btrim(r ->> 'child_first_name'), '') = '' then\n      errs := errs || jsonb_build_object('row', i, 'message', 'No child first name'); end if;\n    begin\n      dob := app.parse_date(r ->> 'child_dob');\n      if dob is null then errs := errs || jsonb_build_object('row', i, 'message', 'No date of birth');\n      elsif dob > current_date or dob < current_date - interval '100 years' then\n        errs := errs || jsonb_build_object('row', i, 'message', 'Date of birth ' || (r ->> 'child_dob') || ' does not look right'); end if;\n    exception when others then\n      errs := errs || jsonb_build_object('row', i, 'message', 'Cannot read the date of birth \"' || (r ->> 'child_dob') || '\" — use DD/MM/YYYY');\n    end;\n    if nullif(btrim(r ->> 'parent_email'), '') is not null and btrim(r ->> 'parent_email') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n      errs := errs || jsonb_build_object('row', i, 'message', 'Email \"' || (r ->> 'parent_email') || '\" is not valid'); end if;\n    if coalesce(nullif(btrim(r ->> 'emergency_phone'), ''), nullif(btrim(r ->> 'parent_phone'), '')) is null then\n      errs := errs || jsonb_build_object('row', i, 'message', 'No phone number to ring in an emergency'); end if;\n    for cls in select btrim(x) from regexp_split_to_table(coalesce(r ->> 'classes', ''), '[;,]') x where btrim(x) <> '' loop\n      select id into cid from class where studio_id = sid and deleted_at is null and lower(name) = lower(cls)\n        order by (select starts_on from term where id = class.term_id) desc limit 1;\n      if cid is null then\n        errs := errs || jsonb_build_object('row', i, 'message', 'No class called \"' || cls || '\"');\n      else\n        adds := jsonb_set(adds, array[cid::text], to_jsonb(coalesce((adds ->> cid::text)::int, 0) + 1));\n      end if;\n    end loop;\n  end loop;\n\n  -- Classes the import would overfill.\n  for cid in select (k)::uuid from jsonb_object_keys(adds) k loop\n    if app.class_enrolled_count(cid) + (adds ->> cid::text)::int > (select capacity from class where id = cid) then\n      warns := warns || jsonb_build_object('message', (select name from class where id = cid) || ' would be over its '\n               || (select capacity from class where id = cid) || ' places — the extra children go on its waiting list');\n    end if;\n  end loop;\n\n  if not p_commit or jsonb_array_length(errs) > 0 then\n    if p_commit then\n      raise exception 'INVALID: % row(s) need fixing before anything is imported', jsonb_array_length(errs)\n        using errcode = 'check_violation';\n    end if;\n    return jsonb_build_object('ok', jsonb_array_length(errs) = 0, 'rows', i, 'errors', errs, 'warnings', warns,\n      'families', (select count(distinct coalesce(nullif(lower(btrim(x ->> 'parent_email')), ''),\n                                                  nullif(regexp_replace(x ->> 'parent_phone', '\\D', '', 'g'), ''),\n                                                  lower(btrim(x ->> 'parent_name'))))\n                     from jsonb_array_elements(p_rows) x));\n  end if;\n\n  -- ── Pass 2: import ──\n  i := 0;\n  for r in select * from jsonb_array_elements(p_rows) loop\n    i := i + 1;\n    fam_key := coalesce(nullif(lower(btrim(r ->> 'parent_email')), ''),\n                        nullif(regexp_replace(r ->> 'parent_phone', '\\D', '', 'g'), ''), lower(btrim(r ->> 'parent_name')));\n    fam_id := (fams ->> fam_key)::uuid;\n    if fam_id is null then\n      -- An existing family: same parent email, else same parent phone number.\n      select g.family_id into fam_id from guardian g where g.studio_id = sid and g.deleted_at is null\n         and ((nullif(lower(btrim(r ->> 'parent_email')), '') is not null and lower(g.email) = lower(btrim(r ->> 'parent_email')))\n           or (length(regexp_replace(coalesce(r ->> 'parent_phone', ''), '\\D', '', 'g')) >= 6\n               and regexp_replace(coalesce(g.phone, ''), '\\D', '', 'g') = regexp_replace(r ->> 'parent_phone', '\\D', '', 'g')))\n       order by (lower(g.email) = lower(btrim(r ->> 'parent_email'))) desc nulls last limit 1;\n      if fam_id is null then\n        insert into family (studio_id, name, created_by)\n        values (sid, coalesce(nullif(btrim(r ->> 'child_last_name'), ''),\n                              regexp_replace(btrim(r ->> 'parent_name'), '^.*\\s', '')) || ' family', auth.uid())\n        returning id into fam_id;\n        insert into guardian (studio_id, family_id, full_name, email, phone, is_primary)\n        values (sid, fam_id, btrim(r ->> 'parent_name'), nullif(lower(btrim(r ->> 'parent_email')), ''),\n                nullif(btrim(r ->> 'parent_phone'), ''), true);\n        if nullif(btrim(r ->> 'second_parent_name'), '') is not null then\n          insert into guardian (studio_id, family_id, full_name, email, phone, is_primary)\n          values (sid, fam_id, btrim(r ->> 'second_parent_name'), nullif(lower(btrim(r ->> 'second_parent_email')), ''),\n                  nullif(btrim(r ->> 'second_parent_phone'), ''), false);\n        end if;\n        n_fam := n_fam + 1;\n      end if;\n      fams := jsonb_set(fams, array[fam_key], to_jsonb(fam_id::text));\n    end if;\n\n    dob := app.parse_date(r ->> 'child_dob');\n    select id into existing from student where family_id = fam_id and deleted_at is null\n       and lower(first_name) = lower(btrim(r ->> 'child_first_name')) and date_of_birth = dob;\n    if existing is not null then n_skip := n_skip + 1; continue; end if;\n\n    insert into student (studio_id, family_id, first_name, last_name, date_of_birth, created_by)\n    values (sid, fam_id, btrim(r ->> 'child_first_name'),\n            coalesce(nullif(btrim(r ->> 'child_last_name'), ''), regexp_replace(btrim(r ->> 'parent_name'), '^.*\\s', '')),\n            dob, auth.uid())\n    returning id into kid;\n    n_kid := n_kid + 1;\n\n    ecphone := coalesce(nullif(btrim(r ->> 'emergency_phone'), ''), btrim(r ->> 'parent_phone'));\n    insert into emergency_contact (studio_id, student_id, full_name, relationship, phone, priority)\n    values (sid, kid, coalesce(nullif(btrim(r ->> 'emergency_name'), ''), btrim(r ->> 'parent_name')),\n            case when nullif(btrim(r ->> 'emergency_name'), '') is null then 'Parent/carer' end, ecphone, 1);\n\n    if nullif(btrim(r ->> 'allergies'), '') is not null or nullif(btrim(r ->> 'medical_notes'), '') is not null then\n      insert into medical_record (studio_id, student_id, allergies, conditions, requires_alert, updated_by)\n      values (sid, kid, nullif(btrim(r ->> 'allergies'), ''), nullif(btrim(r ->> 'medical_notes'), ''),\n              nullif(btrim(r ->> 'allergies'), '') is not null and lower(btrim(r ->> 'allergies')) not in ('none', 'no', 'n/a', 'none known'),\n              auth.uid());\n      n_med := n_med + 1;\n    end if;\n\n    if lower(coalesce(r ->> 'photo_consent', '')) in ('yes', 'y', 'true', '1', 'no', 'n', 'false', '0') then\n      insert into consent_record (studio_id, student_id, kind, granted, granted_by, note)\n      values (sid, kid, 'photography', lower(r ->> 'photo_consent') in ('yes', 'y', 'true', '1'), auth.uid(), 'Imported');\n    end if;\n\n    for cls in select btrim(x) from regexp_split_to_table(coalesce(r ->> 'classes', ''), '[;,]') x where btrim(x) <> '' loop\n      select id into cid from class where studio_id = sid and deleted_at is null and lower(name) = lower(cls)\n        order by (select starts_on from term where id = class.term_id) desc limit 1;\n      if app.class_enrolled_count(cid) < (select capacity from class where id = cid) then\n        insert into enrolment (studio_id, class_id, student_id, status, note, created_by)\n        values (sid, cid, kid, 'active', 'Imported', auth.uid());\n        n_enrol := n_enrol + 1;\n      else\n        insert into waitlist_entry (studio_id, class_id, student_id, status, position, note)\n        values (sid, cid, kid, 'waiting', 0, 'Imported — class was full');\n      end if;\n    end loop;\n  end loop;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'import', 'family', null,\n          format('Imported %s families, %s children (%s with medical notes), %s enrolments; %s already here', n_fam, n_kid, n_med, n_enrol, n_skip));\n\n  return jsonb_build_object('ok', true, 'rows', i, 'families', n_fam, 'children', n_kid, 'enrolled', n_enrol,\n                            'skipped', n_skip, 'medical', n_med, 'errors', '[]'::jsonb, 'warnings', warns);\nend $$;\n\n-- Dates as schools actually type them: 2018-03-14, 14/03/2018, 14-03-2018, 14.3.18.\ncreate or replace function app.parse_date(p text) returns date\n  language plpgsql immutable as $$\ndeclare t text := btrim(coalesce(p, '')); m text[];\nbegin\n  if t = '' then return null; end if;\n  if t ~ '^\\d{4}-\\d{1,2}-\\d{1,2}$' then return t::date; end if;\n  m := regexp_match(t, '^(\\d{1,2})[/.\\-](\\d{1,2})[/.\\-](\\d{2}|\\d{4})$');\n  if m is null then raise exception 'unreadable date'; end if;\n  return make_date(case when length(m[3]) = 2 then\n                     case when m[3]::int > extract(year from current_date)::int % 100 then 1900 else 2000 end + m[3]::int\n                   else m[3]::int end, m[2]::int, m[1]::int);\nend $$;\n\nrevoke all on function app.import_families(jsonb, boolean) from public;\ngrant execute on function app.import_families(jsonb, boolean) to authenticated;\ngrant execute on function app.parse_date(text) to authenticated;\n"},{name:"0028_comms.sql",sql:"-- ============================================================================\n-- 0028 · Communication: who has seen it, what people want to hear about,\n--        teachers writing to families, requests in the conversation, and\n--        messages sent later (R-018, R-019, R-028, R-037)\n-- ============================================================================\n\n-- ── R-018 · Who has seen a message ─────────────────────────────────────────\n-- One row per family the message reached. \"Seen\" means any parent or carer\n-- in that family opened it. Families with nobody signed up cannot see\n-- anything in the app, and say so rather than counting as \"not seen\".\n-- Only the office, or the person who sent it, may ask.\ncreate or replace function app.message_reach(p_comm uuid)\n  returns table (family_id uuid, family_name text, has_login boolean, seen boolean, seen_at timestamptz)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare c communication;\nbegin\n  select * into c from communication where id = p_comm and deleted_at is null;\n  if c.id is null or not (app.is_admin(c.studio_id) or c.sent_by = auth.uid()) then\n    raise exception 'FORBIDDEN: only the sender or the office can see who has read this' using errcode = 'insufficient_privilege';\n  end if;\n  return query\n  with reached as (\n    select f.id, f.name from family f\n     where f.studio_id = c.studio_id and f.deleted_at is null and not f.is_prospect and (\n           (c.kind = 'direct' and f.id = c.family_id)\n        or (c.kind = 'studio_announcement')\n        or (c.kind = 'class_broadcast' and exists (\n              select 1 from enrolment e join student s on s.id = e.student_id\n               where e.class_id = c.class_id and s.family_id = f.id and e.deleted_at is null\n                 and (e.status = 'active' or (e.ended_on is not null and e.ended_on >= c.sent_at::date)))))\n  )\n  select r.id, r.name,\n         exists (select 1 from guardian g where g.family_id = r.id and g.user_id is not null and g.deleted_at is null),\n         exists (select 1 from communication_read cr join guardian g on g.user_id = cr.user_id\n                  where cr.communication_id = c.id and g.family_id = r.id),\n         (select min(cr.read_at) from communication_read cr join guardian g on g.user_id = cr.user_id\n           where cr.communication_id = c.id and g.family_id = r.id)\n    from reached r order by 4, r.name;\nend $$;\n\n-- Nudge everyone who has not opened it yet. Once per message per hour, so a\n-- nervous double-tap does not send two.\ncreate table message_reminder (\n  id uuid primary key default gen_random_uuid(),\n  communication_id uuid not null references communication(id) on delete cascade,\n  sent_by uuid references user_account(id) on delete set null,\n  families int not null,\n  sent_at timestamptz not null default now()\n);\nalter table message_reminder enable row level security;\nalter table message_reminder force row level security;\ncreate policy message_reminder_read on message_reminder for select\n  using (exists (select 1 from communication c where c.id = communication_id and (app.is_admin(c.studio_id) or c.sent_by = auth.uid())));\ngrant select on message_reminder to authenticated;\ngrant all on message_reminder to service_role;\n\ncreate or replace function app.remind_unread(p_comm uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c communication; f record; n int := 0;\nbegin\n  select * into c from communication where id = p_comm and deleted_at is null;\n  if c.id is null or not (app.is_admin(c.studio_id) or c.sent_by = auth.uid()) then\n    raise exception 'FORBIDDEN: only the sender or the office can send a reminder' using errcode = 'insufficient_privilege';\n  end if;\n  if exists (select 1 from message_reminder where communication_id = c.id and sent_at > now() - interval '1 hour') then\n    raise exception 'INVALID: a reminder went less than an hour ago' using errcode = 'check_violation';\n  end if;\n  for f in select * from app.message_reach(p_comm) r where not r.seen and r.has_login loop\n    perform app.notify_family(f.family_id, 'message_reminder', 'Reminder: ' || coalesce(c.subject, 'a message from the studio'),\n                              left(c.body, 120), case when c.kind = 'direct' then '/family/messages' else '/family' end);\n    n := n + 1;\n  end loop;\n  insert into message_reminder (communication_id, sent_by, families) values (c.id, auth.uid(), n);\n  return n;\nend $$;\n\n-- ── R-019 · What each person wants to hear about ───────────────────────────\n-- Categories group the notification kinds. Two can never be switched off\n-- in the app: schedule changes (a cancelled class) and safety (medical and\n-- emergency-contact changes reaching the office).\ncreate or replace function app.notification_category(p_kind text) returns text\n  language sql immutable as $$\n  select case\n    when p_kind in ('message', 'message_reminder', 'request', 'request_answered') then 'messages'\n    when p_kind in ('payment_failed', 'invoice_issued', 'payment_received') then 'payments'\n    when p_kind in ('schedule_change', 'cover_assigned') then 'schedule'\n    when p_kind in ('feedback', 'feedback_published', 'milestone', 'report_shared') then 'progress'\n    when p_kind in ('new_enquiry', 'new_trial', 'new_enrolment', 'waitlist', 'waitlist_offer', 'teacher_changed') then 'enrolment'\n    when p_kind in ('medical_updated', 'contact_updated', 'safeguarding', 'staff_check_due') then 'safety'\n    else 'other' end;\n$$;\n\ncreate table notification_preference (\n  user_id   uuid not null references user_account(id) on delete cascade,\n  category  text not null check (category in ('messages', 'payments', 'schedule', 'progress', 'enrolment', 'safety', 'other')),\n  in_app    boolean not null default true,\n  email     boolean not null default true,\n  updated_at timestamptz not null default now(),\n  primary key (user_id, category),\n  -- What cannot be switched off.\n  check (category not in ('schedule', 'safety') or (in_app and email))\n);\nalter table notification_preference enable row level security;\nalter table notification_preference force row level security;\ncreate policy notification_preference_own on notification_preference for all\n  using (user_id = auth.uid()) with check (user_id = auth.uid());\ngrant select, insert, update, delete on notification_preference to authenticated;\ngrant all on notification_preference to service_role;\n\n-- Quiet hours: when push and email (once connected) wait until morning. The\n-- in-app list is silent anyway, so it is not affected.\nalter table user_account add column quiet_from time;\nalter table user_account add column quiet_to time;\n\ncreate or replace function app.wants(p_user uuid, p_kind text, p_channel text default 'in_app') returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce((select case when p_channel = 'email' then p.email else p.in_app end\n                     from notification_preference p\n                    where p.user_id = p_user and p.category = app.notification_category(p_kind)), true);\n$$;\n\ncreate or replace function app.notify_user(\n  p_studio uuid, p_user uuid, p_kind text, p_title text, p_body text, p_href text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if p_user is null or p_user is not distinct from auth.uid() then return; end if;\n  if auth.uid() is null and current_setting('app.quiet', true) = 'on' then return; end if;\n  if not app.wants(p_user, p_kind, 'in_app') then return; end if;\n  insert into notification (studio_id, user_id, kind, title, body, href)\n  values (p_studio, p_user, p_kind, p_title, p_body, p_href);\nend $$;\nrevoke execute on function app.notify_user(uuid, uuid, text, text, text, text) from public, authenticated, anon;\n\ncreate or replace function app.set_notification_preference(p_category text, p_in_app boolean, p_email boolean) returns void\n  language plpgsql security invoker set search_path = public, app, pg_temp as $$\nbegin\n  if p_category in ('schedule', 'safety') and not (p_in_app and p_email) then\n    raise exception 'INVALID: changes to classes and safety notices cannot be switched off' using errcode = 'check_violation';\n  end if;\n  insert into notification_preference (user_id, category, in_app, email)\n  values (auth.uid(), p_category, p_in_app, p_email)\n  on conflict (user_id, category) do update set in_app = excluded.in_app, email = excluded.email, updated_at = now();\nend $$;\n\ncreate or replace function app.set_quiet_hours(p_from time, p_to time) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if (p_from is null) <> (p_to is null) then\n    raise exception 'INVALID: give both a start and an end, or neither' using errcode = 'check_violation';\n  end if;\n  update user_account set quiet_from = p_from, quiet_to = p_to, updated_at = now() where id = auth.uid();\nend $$;\n\n-- ── R-028 · Teachers write to families; requests live in the conversation ──\n-- A teacher may write to the family of a child they teach. The message sits\n-- in the family's conversation, so the office sees it — there are no private\n-- channels between staff and children's families. Replies come to the office.\nalter table communication add column request_id uuid references studio_request(id) on delete set null;\n\ncreate or replace function app.teacher_message_family(p_student uuid, p_subject text, p_body text) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; mid uuid;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null or not (app.is_admin(s.studio_id)\n       or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))) then\n    raise exception 'FORBIDDEN: you can write to the families of children you teach' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_body), '') = '' then raise exception 'INVALID: a message needs something in it' using errcode = 'check_violation'; end if;\n  insert into communication (studio_id, kind, family_id, subject, body, sent_by)\n  values (s.studio_id, 'direct', s.family_id, coalesce(nullif(btrim(p_subject), ''), 'About ' || s.first_name), btrim(p_body), auth.uid())\n  returning id into mid;\n  return mid;\nend $$;\n\n-- A teacher reads what they sent (and can see it was read); nothing else\n-- in a family's conversation.\ncreate policy comm_teacher_own_direct on communication for select\n  using (deleted_at is null and kind = 'direct' and sent_by = auth.uid());\n\n-- Requests appear in the family's conversation too, so the story of a\n-- medical update and its acknowledgement reads in one place. The copy is\n-- marked with request_id: it is handled in Requests, so it never counts as\n-- an unread message for the office.\ncreate or replace function app.on_request_mirror() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.family_id is null then return null; end if;\n  if tg_op = 'INSERT' and new.raised_by is not null and not app.is_staff(new.studio_id) then\n    insert into communication (studio_id, kind, family_id, subject, body, sent_by, inbound, request_id)\n    values (new.studio_id, 'direct', new.family_id, new.subject, new.body, coalesce(auth.uid(), new.raised_by), true, new.id);\n  elsif tg_op = 'UPDATE' and new.answer is not null and new.answer is distinct from old.answer then\n    insert into communication (studio_id, kind, family_id, subject, body, sent_by, inbound, request_id)\n    values (new.studio_id, 'direct', new.family_id, 'Re: ' || new.subject, new.answer, coalesce(auth.uid(), new.answered_by), false, new.id);\n  end if;\n  return null;\nend $$;\ncreate trigger request_mirror after insert or update of answer on studio_request\n  for each row execute function app.on_request_mirror();\n\n-- The mirror must not notify twice: the request already notified the office,\n-- and the answer already notified the family.\ncreate or replace function app.on_communication_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare fam text;\nbegin\n  if new.request_id is not null or new.sent_at > now() + interval '1 minute' then return null; end if;\n  if new.inbound and new.family_id is not null then\n    select name into fam from family where id = new.family_id;\n    perform app.notify_admins(new.studio_id, 'message', 'Message from the ' || fam,\n      coalesce(new.subject, left(new.body, 120)), '/inbox?family=' || new.family_id);\n  elsif not new.inbound and new.kind = 'direct' then\n    perform app.notify_family(new.family_id, 'message',\n      coalesce(new.subject, 'New message from the studio'), left(new.body, 120), '/family/messages');\n  end if;\n  return null;\nend $$;\n\n-- The stamp trigger normally forces sent_by to the caller; the mirror writes\n-- as the parent who raised the request (or the person who answered), so it\n-- runs with no user and is trusted. Allow that one path explicitly.\ncreate or replace function app.communication_stamp() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.family_id is not null then\n    select studio_id into new.studio_id from family where id = new.family_id;\n  end if;\n  if pg_trigger_depth() > 1 and new.request_id is not null then\n    null;   -- written by app.on_request_mirror as the caller (see there)\n  elsif auth.uid() is not null and current_setting('role', true) is distinct from 'service_role' then\n    if new.sent_by is not null and new.sent_by <> auth.uid() then\n      raise exception 'FORBIDDEN: a message is sent as yourself' using errcode = 'insufficient_privilege';\n    end if;\n    new.sent_by := auth.uid();\n    new.inbound := not app.is_staff(new.studio_id);\n  end if;\n  if coalesce(btrim(new.body), '') = '' then\n    raise exception 'INVALID: a message needs something in it' using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\n\n-- ── R-037 · Send later ─────────────────────────────────────────────────────\n-- A message with sent_at in the future is scheduled. Until then only the\n-- office and its author can see it; a restrictive policy applies on top of\n-- every read policy, so no other path can reveal it early.\ncreate policy comm_not_before_time on communication as restrictive for select\n  using (sent_at <= now() or app.is_admin(studio_id) or sent_by = auth.uid());\n\ncreate table scheduled_release (\n  communication_id uuid primary key references communication(id) on delete cascade,\n  released_at timestamptz not null default now()\n);\nalter table scheduled_release enable row level security;\nalter table scheduled_release force row level security;\ngrant all on scheduled_release to service_role;\n\n-- Tell people about scheduled messages whose time has come. Called by the\n-- automation runner and whenever the office opens the app; idempotent.\ncreate or replace function app.release_scheduled(p_studio uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c communication; n int := 0; u uuid;\nbegin\n  if not app.is_staff(p_studio) and auth.uid() is not null then return 0; end if;\n  for c in select * from communication x where x.studio_id = p_studio and x.deleted_at is null\n             and x.sent_at <= now() and x.sent_at > x.created_at + interval '1 minute'\n             and not exists (select 1 from scheduled_release r where r.communication_id = x.id) loop\n    insert into scheduled_release (communication_id) values (c.id);\n    if c.kind = 'direct' and not c.inbound then\n      perform app.notify_family(c.family_id, 'message', coalesce(c.subject, 'New message from the studio'), left(c.body, 120), '/family/messages');\n    elsif c.kind = 'class_broadcast' then\n      for u in select distinct g.user_id from enrolment e join student s on s.id = e.student_id\n                 join guardian g on g.family_id = s.family_id and g.user_id is not null and g.deleted_at is null\n                where e.class_id = c.class_id and e.status = 'active' and e.deleted_at is null loop\n        perform app.notify_user(c.studio_id, u, 'message', coalesce(c.subject, 'A notice from your class'), left(c.body, 120), '/family');\n      end loop;\n    elsif c.kind = 'studio_announcement' then\n      for u in select distinct g.user_id from guardian g join family f on f.id = g.family_id and not f.is_prospect\n                where g.studio_id = c.studio_id and g.user_id is not null and g.deleted_at is null loop\n        perform app.notify_user(c.studio_id, u, 'message', coalesce(c.subject, 'News from the studio'), left(c.body, 120), '/family');\n      end loop;\n    end if;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- Scheduling is a staff thing, and only into the future.\ncreate or replace function app.check_schedule() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.sent_at > now() + interval '1 minute' then\n    if not app.is_staff(new.studio_id) and auth.uid() is not null then new.sent_at := now(); end if;\n    if new.sent_at > now() + interval '60 days' then\n      raise exception 'INVALID: schedule a message at most 60 days ahead' using errcode = 'check_violation';\n    end if;\n  elsif new.sent_at < now() - interval '1 minute' and auth.uid() is not null then\n    new.sent_at := now();\n  end if;\n  return new;\nend $$;\ncreate trigger communication_schedule before insert on communication\n  for each row execute function app.check_schedule();\n\nrevoke all on function app.message_reach(uuid), app.remind_unread(uuid), app.teacher_message_family(uuid, text, text),\n  app.release_scheduled(uuid), app.set_quiet_hours(time, time) from public;\ngrant execute on function app.message_reach(uuid), app.remind_unread(uuid), app.teacher_message_family(uuid, text, text),\n  app.release_scheduled(uuid), app.set_notification_preference(text, boolean, boolean), app.set_quiet_hours(time, time),\n  app.notification_category(text) to authenticated;\n"},{name:"0029_progress.sql",sql:"-- ============================================================================\n-- 0029 · Progress: skills, quick class feedback, term reports, a timeline,\n--        goals, reflections and milestones (R-020 – R-026)\n-- ----------------------------------------------------------------------------\n-- Principles kept throughout:\n--   · Nothing reaches a family until a teacher shares it.\n--   · Teachers record for the children they teach, not the whole school.\n--   · Celebrate without pressure: milestones count what a child has done,\n--     never what they missed, and nobody is ranked against anyone else.\n-- ============================================================================\n\n-- ── R-020 · Skill frameworks ───────────────────────────────────────────────\ncreate table skill_framework (\n  id             uuid primary key default gen_random_uuid(),\n  studio_id      uuid not null references studio(id) on delete cascade,\n  dance_style_id uuid references dance_style(id) on delete cascade,\n  level_id       uuid references level(id) on delete set null,\n  name           text not null,\n  exam_board     text,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now(),\n  deleted_at     timestamptz\n);\ncreate table framework_skill (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  framework_id uuid not null references skill_framework(id) on delete cascade,\n  name         text not null,\n  description  text,\n  position     smallint not null default 0,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\nalter table skill_assessment add column skill_id uuid references framework_skill(id) on delete set null;\ncreate index skill_assessment_student_idx on skill_assessment (student_id, skill_id, assessed_on desc);\n\nalter table skill_framework enable row level security;  alter table skill_framework force row level security;\nalter table framework_skill enable row level security;  alter table framework_skill force row level security;\ncreate policy framework_read on skill_framework for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy framework_admin on skill_framework for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy framework_skill_read on framework_skill for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy framework_skill_admin on framework_skill for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ngrant select, insert, update on skill_framework, framework_skill to authenticated;\ngrant all on skill_framework, framework_skill to service_role;\n\n-- Teachers assess the children they teach; the office anyone. (0010 let any\n-- member of staff write any child's assessment.)\ndrop policy assessment_staff on skill_assessment;\ncreate policy assessment_admin on skill_assessment for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy assessment_teacher_read on skill_assessment for select\n  using (deleted_at is null and app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()));\n\n-- Sensible starting frameworks, one per style, for the school to edit.\ncreate or replace function app.ensure_frameworks(p_studio uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare ds record; fw uuid; n int := 0; skills text[]; i int;\nbegin\n  for ds in select * from dance_style d where d.studio_id = p_studio and d.deleted_at is null\n             and not exists (select 1 from skill_framework f where f.dance_style_id = d.id and f.deleted_at is null) loop\n    skills := case\n      when ds.name ilike '%ballet%' then array['Posture and placement', 'Turnout', 'Pointed feet', 'Pliés', 'Port de bras', 'Pirouettes', 'Allegro', 'Musicality', 'Performance']\n      when ds.name ilike '%tap%' then array['Shuffles', 'Flaps', 'Paradiddles', 'Time steps', 'Rhythm and timing', 'Clarity of sounds', 'Performance']\n      when ds.name ilike '%street%' or ds.name ilike '%hip%' then array['Grooves', 'Isolations', 'Footwork', 'Freestyle', 'Remembering choreography', 'Musicality', 'Performance']\n      when ds.name ilike '%jazz%' then array['Isolations', 'Kicks', 'Turns', 'Leaps', 'Flexibility', 'Style', 'Performance']\n      when ds.name ilike '%contemporary%' or ds.name ilike '%modern%' then array['Floorwork', 'Contraction and release', 'Spirals', 'Balance', 'Travelling', 'Musicality', 'Performance']\n      else array['Technique', 'Musicality', 'Remembering choreography', 'Performance'] end;\n    insert into skill_framework (studio_id, dance_style_id, name) values (p_studio, ds.id, ds.name || ' skills') returning id into fw;\n    for i in 1 .. array_length(skills, 1) loop\n      insert into framework_skill (studio_id, framework_id, name, position) values (p_studio, fw, skills[i], i);\n    end loop;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\nselect app.ensure_frameworks(id) from studio;\n\n-- Record a level. A new row each time, so the timeline can show the change.\ncreate or replace function app.record_skill(p_student uuid, p_skill uuid, p_level assessment_level,\n                                            p_note text default null, p_feedback uuid default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; k record; aid uuid; staff uuid;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null or not (app.is_admin(s.studio_id)\n       or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))) then\n    raise exception 'FORBIDDEN: you record skills for children you teach' using errcode = 'insufficient_privilege';\n  end if;\n  select fs.id, fs.name, f.dance_style_id into k from framework_skill fs join skill_framework f on f.id = fs.framework_id\n   where fs.id = p_skill and fs.studio_id = s.studio_id and fs.deleted_at is null;\n  if k.id is null then raise exception 'NOT_FOUND: that skill' using errcode = 'no_data_found'; end if;\n  select id into staff from staff_member where user_id = auth.uid() and studio_id = s.studio_id and deleted_at is null limit 1;\n  -- Same skill, same level, same day: nothing new to say.\n  if exists (select 1 from skill_assessment a where a.student_id = s.id and a.skill_id = k.id and a.deleted_at is null\n              and a.assessed_on = current_date and a.level = p_level) then\n    return null;\n  end if;\n  insert into skill_assessment (studio_id, student_id, feedback_id, dance_style_id, skill, skill_id, level, assessed_by, assessed_on, note)\n  values (s.studio_id, s.id, p_feedback, k.dance_style_id, k.name, k.id, p_level, staff, current_date, nullif(btrim(p_note), ''))\n  returning id into aid;\n  return aid;\nend $$;\n\n-- A child's current level in each skill of the styles they dance, with the\n-- level before it. Anyone who may see the child may ask.\ncreate or replace function app.can_see_student(p_student uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from student s where s.id = p_student and s.deleted_at is null and (\n    app.is_admin(s.studio_id) or s.id = app.student_self_id() or s.id in (select app.guardian_student_ids())\n    or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))));\n$$;\n\ncreate or replace function app.student_skills(p_student uuid)\n  returns table (framework_id uuid, framework text, skill_id uuid, skill text, ord smallint,\n                 level assessment_level, assessed_on date, previous assessment_level)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.can_see_student(p_student) then return; end if;\n  return query\n  with mine as (select distinct c.dance_style_id from enrolment e join class c on c.id = e.class_id\n                 where e.student_id = p_student and e.status = 'active' and e.deleted_at is null)\n  select f.id, f.name, fs.id, fs.name, fs.position, l.level, l.assessed_on,\n         (select a.level from skill_assessment a where a.student_id = p_student and a.skill_id = fs.id and a.deleted_at is null\n           order by a.assessed_on desc, a.created_at desc offset 1 limit 1)\n    from skill_framework f join framework_skill fs on fs.framework_id = f.id and fs.deleted_at is null\n    left join lateral (select a.level, a.assessed_on from skill_assessment a\n                        where a.student_id = p_student and a.skill_id = fs.id and a.deleted_at is null\n                        order by a.assessed_on desc, a.created_at desc limit 1) l on true\n   where f.deleted_at is null and f.dance_style_id in (select dance_style_id from mine)\n   order by f.name, fs.position;\nend $$;\n\n-- ── R-021 · Class feedback in minutes ──────────────────────────────────────\n-- Quick phrases the school chooses, in two kinds.\ncreate table feedback_chip (\n  id         uuid primary key default gen_random_uuid(),\n  studio_id  uuid not null references studio(id) on delete cascade,\n  kind       text not null check (kind in ('going_well', 'work_on')),\n  label      text not null,\n  position   smallint not null default 0,\n  deleted_at timestamptz\n);\nalter table feedback_chip enable row level security; alter table feedback_chip force row level security;\ncreate policy chip_read on feedback_chip for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy chip_admin on feedback_chip for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ngrant select, insert, update on feedback_chip to authenticated;\ngrant all on feedback_chip to service_role;\n\ncreate or replace function app.ensure_chips(p_studio uuid) returns void\n  language sql security definer set search_path = public, app, pg_temp as $$\n  insert into feedback_chip (studio_id, kind, label, position)\n  select p_studio, k, l, n from (values\n    ('going_well', 'Great focus', 1), ('going_well', 'Lovely posture', 2), ('going_well', 'Brilliant timing', 3),\n    ('going_well', 'Remembered the routine', 4), ('going_well', 'Big improvement', 5), ('going_well', 'Kind to others', 6),\n    ('work_on', 'Pointed feet', 1), ('work_on', 'Listening to the music', 2), ('work_on', 'Practise at home', 3),\n    ('work_on', 'Spotting in turns', 4), ('work_on', 'Using the whole space', 5), ('work_on', 'Confidence', 6)) v(k, l, n)\n  where not exists (select 1 from feedback_chip c where c.studio_id = p_studio);\n$$;\nselect app.ensure_chips(id) from studio;\n\n-- Save a whole class's feedback at once. p_items: [{student_id, going_well:[..],\n-- work_on:[..], note?, private_note?, skills?: [{skill_id, level}]}]. Drafts\n-- unless p_share; a teacher can share later from the same screen.\ncreate or replace function app.save_class_feedback(p_session uuid, p_items jsonb, p_share boolean default false)\n  returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; it jsonb; sk jsonb; fid uuid; staff uuid; n int := 0; gw text; wo text;\nbegin\n  select x.id, x.class_id, c.studio_id into cs from class_session x join class c on c.id = x.class_id where x.id = p_session;\n  if cs.id is null or not (app.is_admin(cs.studio_id) or cs.class_id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  select id into staff from staff_member where user_id = auth.uid() and studio_id = cs.studio_id and deleted_at is null limit 1;\n  for it in select * from jsonb_array_elements(p_items) loop\n    if not exists (select 1 from enrolment e where e.class_id = cs.class_id and e.student_id = (it ->> 'student_id')::uuid and e.deleted_at is null)\n       and not exists (select 1 from trial t where t.session_id = cs.id and t.student_id = (it ->> 'student_id')::uuid) then\n      raise exception 'INVALID: a child in the list is not in this class' using errcode = 'check_violation';\n    end if;\n    gw := nullif(concat_ws('. ', nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(it -> 'going_well', '[]'))), ', '), ''),\n                                 nullif(btrim(it ->> 'note'), '')), '');\n    wo := nullif(array_to_string(array(select jsonb_array_elements_text(coalesce(it -> 'work_on', '[]'))), ', '), '');\n    if gw is null and wo is null and coalesce(jsonb_array_length(it -> 'skills'), 0) = 0 then continue; end if;\n    -- One note per child per session: saving again updates the draft.\n    select id into fid from feedback_note where session_id = cs.id and student_id = (it ->> 'student_id')::uuid and deleted_at is null;\n    if fid is null then\n      insert into feedback_note (studio_id, student_id, class_id, session_id, author_id, headline, going_well, work_on, private_note, shared_at)\n      values (cs.studio_id, (it ->> 'student_id')::uuid, cs.class_id, cs.id, staff,\n              (select name from class where id = cs.class_id), gw, wo, nullif(btrim(it ->> 'private_note'), ''),\n              case when p_share then now() end)\n      returning id into fid;\n    else\n      update feedback_note set going_well = gw, work_on = wo, private_note = nullif(btrim(it ->> 'private_note'), ''),\n             shared_at = case when p_share then coalesce(shared_at, now()) else shared_at end, updated_at = now()\n       where id = fid;\n    end if;\n    for sk in select * from jsonb_array_elements(coalesce(it -> 'skills', '[]')) loop\n      perform app.record_skill((it ->> 'student_id')::uuid, (sk ->> 'skill_id')::uuid, (sk ->> 'level')::assessment_level, null, fid);\n    end loop;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\ncreate or replace function app.share_session_feedback(p_session uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; n int;\nbegin\n  select x.id, x.class_id, c.studio_id into cs from class_session x join class c on c.id = x.class_id where x.id = p_session;\n  if cs.id is null or not (app.is_admin(cs.studio_id) or cs.class_id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  update feedback_note set shared_at = now() where session_id = p_session and shared_at is null and deleted_at is null;\n  get diagnostics n = row_count;\n  return n;\nend $$;\n\n-- Families hear when feedback is shared with them.\ncreate or replace function app.on_feedback_shared() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student;\nbegin\n  if new.shared_at is not null and (tg_op = 'INSERT' or old.shared_at is null) then\n    select * into s from student where id = new.student_id;\n    if new.share_with_guardian then\n      perform app.notify_family(s.family_id, 'feedback_published', 'Feedback for ' || s.first_name,\n                                coalesce(left(new.going_well, 120), 'From ' || coalesce(new.headline, 'class')), '/family/feedback');\n    end if;\n    if new.share_with_student and s.user_id is not null and s.login_enabled then\n      perform app.notify_user(s.studio_id, s.user_id, 'feedback_published', 'New feedback from your teacher',\n                              coalesce(left(new.going_well, 120), ''), '/learn/feedback');\n    end if;\n  end if;\n  return null;\nend $$;\ncreate trigger feedback_shared after insert or update of shared_at on feedback_note\n  for each row execute function app.on_feedback_shared();\n\n-- ── R-022 · Term reports ───────────────────────────────────────────────────\ncreate table progress_report (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  term_id     uuid not null references term(id) on delete cascade,\n  class_id    uuid references class(id) on delete set null,\n  summary     jsonb not null,          -- what the term's notes and skills say, assembled\n  comment     text,                    -- the teacher's own words\n  status      text not null default 'draft' check (status in ('draft', 'shared')),\n  author_id   uuid references staff_member(id) on delete set null,\n  shared_at   timestamptz,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  unique (student_id, term_id, class_id)\n);\nalter table progress_report enable row level security; alter table progress_report force row level security;\ncreate policy report_admin on progress_report for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy report_teacher on progress_report for all\n  using (deleted_at is null and app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()))\n  with check (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()));\ncreate policy report_family_read on progress_report for select\n  using (deleted_at is null and status = 'shared' and (student_id in (select app.guardian_student_ids()) or student_id = app.student_self_id()));\ngrant select, update on progress_report to authenticated;\ngrant all on progress_report to service_role;\n\n-- Draft one report per child in a class for its term, from the term's shared\n-- and unshared notes, chips and skill changes. Existing drafts are refreshed;\n-- shared reports are left alone.\ncreate or replace function app.draft_class_reports(p_class uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class; t term; s record; summary jsonb; staff uuid; n int := 0;\nbegin\n  select * into c from class where id = p_class and deleted_at is null;\n  if c.id is null or not (app.is_admin(c.studio_id) or c.id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  select * into t from term where id = c.term_id;\n  select id into staff from staff_member where user_id = auth.uid() and studio_id = c.studio_id and deleted_at is null limit 1;\n  for s in select st.* from enrolment e join student st on st.id = e.student_id and st.deleted_at is null\n            where e.class_id = c.id and e.status = 'active' and e.deleted_at is null loop\n    summary := jsonb_build_object(\n      'attendance', (select jsonb_build_object('present', count(*) filter (where a.status in ('present', 'late')), 'of', count(*))\n                       from attendance_record a join class_session cs on cs.id = a.session_id\n                      where a.student_id = s.id and cs.class_id = c.id and a.deleted_at is null),\n      'going_well', (select coalesce(jsonb_agg(distinct x), '[]') from feedback_note f,\n                       lateral regexp_split_to_table(coalesce(f.going_well, ''), '[,.]\\s*') x\n                      where f.student_id = s.id and f.class_id = c.id and f.deleted_at is null and btrim(x) <> ''\n                        and f.created_at >= t.starts_on),\n      'work_on', (select coalesce(jsonb_agg(distinct x), '[]') from feedback_note f,\n                    lateral regexp_split_to_table(coalesce(f.work_on, ''), ',\\s*') x\n                   where f.student_id = s.id and f.class_id = c.id and f.deleted_at is null and btrim(x) <> ''\n                     and f.created_at >= t.starts_on),\n      'skills', (select coalesce(jsonb_agg(jsonb_build_object('skill', k.skill, 'level', k.level, 'from', k.from_level) order by k.position), '[]')\n                   from (select fs.name skill, fs.position,\n                                (select a.level from skill_assessment a where a.student_id = s.id and a.skill_id = fs.id and a.deleted_at is null\n                                  order by a.assessed_on desc, a.created_at desc limit 1) level,\n                                (select a.level from skill_assessment a where a.student_id = s.id and a.skill_id = fs.id and a.deleted_at is null\n                                    and a.assessed_on < t.starts_on order by a.assessed_on desc limit 1) from_level\n                           from skill_framework f join framework_skill fs on fs.framework_id = f.id and fs.deleted_at is null\n                          where f.dance_style_id = c.dance_style_id and f.deleted_at is null) k\n                  where k.level is not null));\n    insert into progress_report (studio_id, student_id, term_id, class_id, summary, author_id)\n    values (c.studio_id, s.id, t.id, c.id, summary, staff)\n    on conflict (student_id, term_id, class_id) do update set summary = excluded.summary, updated_at = now()\n      where progress_report.status = 'draft';\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\ncreate or replace function app.share_reports(p_ids uuid[]) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r progress_report; n int := 0;\nbegin\n  for r in select * from progress_report where id = any(p_ids) and status = 'draft' and deleted_at is null loop\n    if not (app.is_admin(r.studio_id) or (app.has_role(r.studio_id, 'teacher') and r.student_id in (select app.teacher_student_ids()))) then\n      raise exception 'FORBIDDEN: not your student' using errcode = 'insufficient_privilege';\n    end if;\n    update progress_report set status = 'shared', shared_at = now(), updated_at = now() where id = r.id;\n    perform app.notify_family((select family_id from student where id = r.student_id), 'report_shared',\n      'Term report for ' || (select first_name from student where id = r.student_id), coalesce(left(r.comment, 120), ''), '/family/feedback');\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- ── R-024 · Goals ──────────────────────────────────────────────────────────\ncreate table student_goal (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  term_id     uuid references term(id) on delete set null,\n  text        text not null check (length(btrim(text)) between 3 and 200),\n  status      text not null default 'proposed' check (status in ('proposed', 'agreed', 'achieved', 'dropped')),\n  proposed_by uuid references user_account(id) on delete set null,\n  agreed_by   uuid references user_account(id) on delete set null,\n  review_note text,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\nalter table student_goal enable row level security; alter table student_goal force row level security;\ncreate policy goal_staff on student_goal for all\n  using (deleted_at is null and (app.is_admin(studio_id) or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()))))\n  with check (app.is_admin(studio_id) or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids())));\ncreate policy goal_student on student_goal for select using (deleted_at is null and student_id = app.student_self_id());\ncreate policy goal_student_propose on student_goal for insert\n  with check (student_id = app.student_self_id() and status = 'proposed' and proposed_by = auth.uid());\ncreate policy goal_family_read on student_goal for select\n  using (deleted_at is null and status <> 'proposed' and student_id in (select app.guardian_student_ids()));\ngrant select, insert, update on student_goal to authenticated;\ngrant all on student_goal to service_role;\n\ncreate or replace function app.goal_stamp() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if tg_op = 'INSERT' then\n    select studio_id into new.studio_id from student where id = new.student_id;\n    new.proposed_by := coalesce(auth.uid(), new.proposed_by);\n    new.term_id := coalesce(new.term_id, (select t.id from term t where t.studio_id = new.studio_id\n                                            and current_date between t.starts_on and t.ends_on and t.deleted_at is null limit 1));\n    if (select count(*) from student_goal g where g.student_id = new.student_id and g.term_id is not distinct from new.term_id\n          and g.status in ('proposed', 'agreed') and g.deleted_at is null) >= 2 then\n      raise exception 'INVALID: two goals a term is plenty — finish or drop one first' using errcode = 'check_violation';\n    end if;\n  end if;\n  if new.status = 'agreed' and (tg_op = 'INSERT' or old.status <> 'agreed') then new.agreed_by := auth.uid(); end if;\n  return new;\nend $$;\ncreate trigger goal_stamp before insert or update on student_goal for each row execute function app.goal_stamp();\n\n-- ── R-025 · Reflections ────────────────────────────────────────────────────\n-- For students thirteen and over. Seen by the student and their teachers only\n-- — not parents, not other students. A worrying reflection is something a\n-- teacher acts on through safeguarding (0030), never by sharing it here.\ncreate table student_reflection (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  session_id  uuid references class_session(id) on delete set null,\n  mood        smallint not null check (mood between 1 and 5),\n  text        text check (text is null or length(text) <= 280),\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\nalter table student_reflection enable row level security; alter table student_reflection force row level security;\ncreate policy reflection_student on student_reflection for select using (deleted_at is null and student_id = app.student_self_id());\ncreate policy reflection_teacher on student_reflection for select\n  using (deleted_at is null and app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()));\ngrant select on student_reflection to authenticated;\ngrant all on student_reflection to service_role;\n\ncreate or replace function app.add_reflection(p_session uuid, p_mood int, p_text text default null) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; rid uuid;\nbegin\n  select * into s from student where id = app.student_self_id();\n  if s.id is null then raise exception 'FORBIDDEN: reflections are for students' using errcode = 'insufficient_privilege'; end if;\n  if extract(year from age(current_date, s.date_of_birth)) < 13 then\n    raise exception 'INVALID: reflections are for students aged 13 and over' using errcode = 'check_violation';\n  end if;\n  if p_session is not null and not exists (select 1 from attendance_record a where a.session_id = p_session and a.student_id = s.id\n                                             and a.status in ('present', 'late') and a.deleted_at is null) then\n    raise exception 'INVALID: reflect on a class you were at' using errcode = 'check_violation';\n  end if;\n  insert into student_reflection (studio_id, student_id, session_id, mood, text)\n  values (s.studio_id, s.id, p_session, p_mood, nullif(btrim(p_text), '')) returning id into rid;\n  return rid;\nend $$;\n\n-- ── R-026 · Milestones ─────────────────────────────────────────────────────\ncreate table milestone (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  kind        text not null,      -- first_class, classes_10, classes_25, …, one_year, first_show, exam\n  title       text not null,\n  reached_on  date not null default current_date,\n  unique (student_id, kind)\n);\nalter table milestone enable row level security; alter table milestone force row level security;\ncreate policy milestone_read on milestone for select using (\n  app.is_admin(studio_id) or student_id = app.student_self_id() or student_id in (select app.guardian_student_ids())\n  or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids())));\ngrant select on milestone to authenticated;\ngrant all on milestone to service_role;\n\ncreate or replace function app.award_milestone(p_student uuid, p_kind text, p_title text, p_on date default current_date) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; mid uuid;\nbegin\n  select * into s from student where id = p_student;\n  insert into milestone (studio_id, student_id, kind, title, reached_on) values (s.studio_id, s.id, p_kind, p_title, p_on)\n  on conflict (student_id, kind) do nothing returning id into mid;\n  if mid is not null and p_on >= current_date - 1 then\n    perform app.notify_family(s.family_id, 'milestone', s.first_name || ': ' || p_title, 'Well done!', '/family/feedback');\n    if s.user_id is not null and s.login_enabled then\n      perform app.notify_user(s.studio_id, s.user_id, 'milestone', p_title, 'Well done!', '/learn');\n    end if;\n  end if;\nend $$;\n\n-- Counting classes attended. Absences never take anything away.\ncreate or replace function app.on_attendance_milestone() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare n int; first_day date; d date;\nbegin\n  if new.status not in ('present', 'late') or new.deleted_at is not null then return null; end if;\n  -- Count up to and including this class, so a register entered late (or a\n  -- history loaded in one go) still awards each milestone on the right day.\n  select cs.starts_at::date into d from class_session cs where cs.id = new.session_id;\n  select count(*), min(cs.starts_at::date) into n, first_day from attendance_record a join class_session cs on cs.id = a.session_id\n   where a.student_id = new.student_id and a.status in ('present', 'late') and a.deleted_at is null\n     and cs.starts_at <= (select starts_at from class_session where id = new.session_id);\n  if n = 1 then perform app.award_milestone(new.student_id, 'first_class', 'First class', d); end if;\n  if n in (10, 25, 50, 100, 200, 300, 500) then\n    perform app.award_milestone(new.student_id, 'classes_' || n, n || ' classes', d);\n  end if;\n  if first_day <= d - interval '1 year' then\n    perform app.award_milestone(new.student_id, 'one_year', 'One year of dancing', d);\n  end if;\n  return null;\nend $$;\ncreate trigger attendance_milestone after insert or update of status on attendance_record\n  for each row execute function app.on_attendance_milestone();\n\n-- Shows and exams, once they have happened.\ncreate or replace function app.award_event_milestones(p_studio uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p record; n int := 0;\nbegin\n  for p in select ep.student_id, e.kind, e.title, e.starts_at::date d from event_participant ep\n             join studio_event e on e.id = ep.event_id and e.deleted_at is null and e.starts_at < now()\n            where ep.studio_id = p_studio and ep.status = 'confirmed' and ep.deleted_at is null and e.kind in ('show', 'exam', 'competition')\n            order by e.starts_at loop\n    perform app.award_milestone(p.student_id, case p.kind when 'show' then 'first_show' when 'exam' then 'first_exam' else 'first_competition' end,\n      case p.kind when 'show' then 'First show: ' when 'exam' then 'First exam: ' else 'First competition: ' end || p.title, p.d);\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- New styles get a starting framework; new schools get the starting phrases.\ncreate or replace function app.on_style_added() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin perform app.ensure_frameworks(new.studio_id); return null; end $$;\ncreate trigger style_framework after insert on dance_style for each row execute function app.on_style_added();\ncreate or replace function app.on_studio_chips() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin perform app.ensure_chips(new.id); return null; end $$;\ncreate trigger studio_chips after insert on studio for each row execute function app.on_studio_chips();\n\n-- ── R-023 · One timeline ───────────────────────────────────────────────────\n-- Everything about a child's progress in date order. Security invoker: each\n-- branch is filtered by the caller's own access, so a parent sees shared\n-- feedback and never a draft, and a student never sees what was kept from them.\ncreate or replace function app.student_timeline(p_student uuid)\n  returns table (at timestamptz, kind text, title text, detail text, level text, previous text)\n  language sql stable security invoker set search_path = public, app, pg_temp as $$\n  select a.assessed_on::timestamptz, 'skill', a.skill, a.note, a.level::text,\n         (select b.level::text from skill_assessment b where b.student_id = a.student_id and b.skill_id = a.skill_id and b.deleted_at is null\n            and (b.assessed_on, b.created_at) < (a.assessed_on, a.created_at) order by b.assessed_on desc, b.created_at desc limit 1)\n    from skill_assessment a where a.student_id = p_student and a.deleted_at is null\n  union all\n  select coalesce(f.shared_at, f.created_at), 'feedback', coalesce(f.headline, 'Feedback'),\n         concat_ws(' · ', nullif(f.going_well, ''), case when f.work_on is not null then 'Next: ' || f.work_on end), null, null\n    from feedback_note f where f.student_id = p_student and f.deleted_at is null\n  union all\n  select m.reached_on::timestamptz, 'milestone', m.title, null, null, null from milestone m where m.student_id = p_student\n  union all\n  select g.updated_at, 'goal', g.text, g.status, null, null from student_goal g where g.student_id = p_student and g.deleted_at is null\n  union all\n  select r.shared_at, 'report', 'Term report', r.comment, null, null from progress_report r\n   where r.student_id = p_student and r.deleted_at is null and r.status = 'shared'\n  order by 1 desc;\n$$;\n\n-- Soft delete now covers the progress settings too (RLS hides a deleted row\n-- from its own update, so removal goes through this checked function).\ncreate or replace function app.soft_delete(p_table text, p_id uuid)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid;\n  allowed constant text[] := array[\n    'family','guardian','student','emergency_contact','consent_record','medical_record',\n    'location','room','staff_member','term','term_break','dance_style','level',\n    'class','class_session','enrolment','trial','waitlist_entry','enquiry',\n    'invoice','invoice_item','communication','communication_template','notification',\n    'skill_framework','framework_skill','feedback_chip'];\nbegin\n  if not (p_table = any(allowed)) then\n    raise exception 'SOFT_DELETE_UNSUPPORTED: %', p_table using errcode = 'feature_not_supported';\n  end if;\n\n  execute format('select studio_id from %I where id = $1 and deleted_at is null', p_table)\n    into sid using p_id;\n  if sid is null then return false; end if;         -- absent or already deleted\n\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: soft delete requires owner or admin' using errcode = 'insufficient_privilege';\n  end if;\n\n  execute format('update %I set deleted_at = now() where id = $1', p_table) using p_id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'soft_delete', p_table, p_id, 'soft deleted');\n  return true;\nend $$;\n\nrevoke all on function app.ensure_frameworks(uuid), app.ensure_chips(uuid), app.award_milestone(uuid, text, text, date),\n  app.award_event_milestones(uuid) from public;\ngrant execute on function app.ensure_frameworks(uuid), app.ensure_chips(uuid), app.award_event_milestones(uuid) to service_role;\ngrant execute on function app.record_skill(uuid, uuid, assessment_level, text, uuid), app.student_skills(uuid),\n  app.save_class_feedback(uuid, jsonb, boolean), app.share_session_feedback(uuid), app.draft_class_reports(uuid),\n  app.share_reports(uuid[]), app.add_reflection(uuid, int, text), app.student_timeline(uuid) to authenticated;\n"},{name:"0030_safeguarding.sql",sql:"-- ============================================================================\n-- 0030 · Safeguarding concerns, staff checks and leaver retention\n--        (R-033, R-035, R-041)\n-- ============================================================================\n\n-- ── R-033 · Safeguarding concern log ───────────────────────────────────────\n-- Any member of staff can raise a concern. Only the owner and the school's\n-- Designated Safeguarding Lead can read the log, and every time they do it is\n-- recorded. The tables have no read policy at all: the only way in is through\n-- the functions below, which check who is asking and write the access log.\nalter table studio add column dsl_user_id uuid references user_account(id) on delete set null;\n\ncreate table safeguarding_concern (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid references student(id) on delete set null,\n  raised_by   uuid references user_account(id) on delete set null,\n  category    text not null check (category in ('wellbeing', 'injury', 'disclosure', 'behaviour', 'attendance', 'online', 'other')),\n  summary     text not null check (length(btrim(summary)) >= 10),\n  immediate_risk boolean not null default false,\n  status      text not null default 'open' check (status in ('open', 'monitoring', 'referred', 'closed')),\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now()\n);\ncreate table safeguarding_action (\n  id          uuid primary key default gen_random_uuid(),\n  concern_id  uuid not null references safeguarding_concern(id) on delete cascade,\n  by_user     uuid references user_account(id) on delete set null,\n  note        text not null,\n  status_to   text,\n  at          timestamptz not null default now()\n);\ncreate table safeguarding_access (\n  id          bigserial primary key,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  user_id     uuid references user_account(id) on delete set null,\n  concern_id  uuid references safeguarding_concern(id) on delete cascade,\n  what        text not null,\n  at          timestamptz not null default now()\n);\nalter table safeguarding_concern enable row level security; alter table safeguarding_concern force row level security;\nalter table safeguarding_action  enable row level security; alter table safeguarding_action  force row level security;\nalter table safeguarding_access  enable row level security; alter table safeguarding_access  force row level security;\ngrant all on safeguarding_concern, safeguarding_action, safeguarding_access to service_role;\n\ncreate or replace function app.is_safeguarding_lead(p_studio uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select auth.uid() is not null and (app.has_role(p_studio, 'owner')\n    or exists (select 1 from studio s where s.id = p_studio and s.dsl_user_id = auth.uid() and app.is_staff(p_studio)));\n$$;\n\ncreate or replace function app.raise_concern(p_student uuid, p_category text, p_summary text, p_immediate boolean default false)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid; u uuid;\nbegin\n  select studio_id into sid from student where id = p_student and deleted_at is null;\n  if sid is null or not app.is_staff(sid) then\n    raise exception 'FORBIDDEN: staff raise concerns about children at their school' using errcode = 'insufficient_privilege';\n  end if;\n  insert into safeguarding_concern (studio_id, student_id, raised_by, category, summary, immediate_risk)\n  values (sid, p_student, auth.uid(), p_category, btrim(p_summary), coalesce(p_immediate, false)) returning id into cid;\n  -- The lead and the owner hear at once; the notification names no child.\n  for u in select distinct x from (select s.dsl_user_id x from studio s where s.id = sid\n                                   union select m.user_id from membership m where m.studio_id = sid and m.role = 'owner' and m.deleted_at is null) y\n            where x is not null loop\n    perform app.notify_user(sid, u, 'safeguarding', case when p_immediate then 'URGENT safeguarding concern raised' else 'Safeguarding concern raised' end,\n                            'Open the safeguarding log to read it.', '/safeguarding');\n  end loop;\n  return cid;\nend $$;\n\ncreate or replace function app.safeguarding_log(p_studio uuid)\n  returns table (id uuid, student_name text, category text, summary text, immediate_risk boolean, status text,\n                 raised_by text, created_at timestamptz, actions int)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_safeguarding_lead(p_studio) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner can read concerns' using errcode = 'insufficient_privilege';\n  end if;\n  insert into safeguarding_access (studio_id, user_id, what) values (p_studio, auth.uid(), 'viewed the log');\n  return query\n  select c.id, s.first_name || ' ' || s.last_name, c.category, c.summary, c.immediate_risk, c.status,\n         coalesce(u.full_name, 'Unknown'), c.created_at, (select count(*)::int from safeguarding_action a where a.concern_id = c.id)\n    from safeguarding_concern c left join student s on s.id = c.student_id left join user_account u on u.id = c.raised_by\n   where c.studio_id = p_studio order by (c.status = 'closed'), c.immediate_risk desc, c.created_at desc;\nend $$;\n\ncreate or replace function app.safeguarding_actions(p_concern uuid)\n  returns table (note text, status_to text, by_name text, at timestamptz)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from safeguarding_concern where id = p_concern;\n  if sid is null or not app.is_safeguarding_lead(sid) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner can read concerns' using errcode = 'insufficient_privilege';\n  end if;\n  insert into safeguarding_access (studio_id, user_id, concern_id, what) values (sid, auth.uid(), p_concern, 'opened a concern');\n  return query select a.note, a.status_to, coalesce(u.full_name, 'Unknown'), a.at\n    from safeguarding_action a left join user_account u on u.id = a.by_user where a.concern_id = p_concern order by a.at;\nend $$;\n\ncreate or replace function app.safeguarding_act(p_concern uuid, p_note text, p_status text default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from safeguarding_concern where id = p_concern;\n  if sid is null or not app.is_safeguarding_lead(sid) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner act on concerns' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_note), '') = '' then raise exception 'INVALID: record what was done' using errcode = 'check_violation'; end if;\n  insert into safeguarding_action (concern_id, by_user, note, status_to) values (p_concern, auth.uid(), btrim(p_note), p_status);\n  if p_status is not null then update safeguarding_concern set status = p_status, updated_at = now() where id = p_concern; end if;\n  insert into safeguarding_access (studio_id, user_id, concern_id, what) values (sid, auth.uid(), p_concern, 'recorded an action');\nend $$;\n\ncreate or replace function app.safeguarding_access_log(p_studio uuid)\n  returns table (who text, what text, concern uuid, at timestamptz)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the owner reviews who has read the log' using errcode = 'insufficient_privilege';\n  end if;\n  return query select coalesce(u.full_name, 'Unknown'), a.what, a.concern_id, a.at from safeguarding_access a\n    left join user_account u on u.id = a.user_id where a.studio_id = p_studio order by a.at desc limit 200;\nend $$;\n\ncreate or replace function app.set_safeguarding_lead(p_user uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select m.studio_id into sid from membership m where m.user_id = auth.uid() and m.role = 'owner' and m.deleted_at is null limit 1;\n  if sid is null then raise exception 'FORBIDDEN: only the owner names the safeguarding lead' using errcode = 'insufficient_privilege'; end if;\n  if p_user is not null and not exists (select 1 from membership m where m.user_id = p_user and m.studio_id = sid\n                                          and m.role in ('owner', 'admin', 'teacher') and m.deleted_at is null) then\n    raise exception 'INVALID: the lead must be a member of staff' using errcode = 'check_violation';\n  end if;\n  update studio set dsl_user_id = p_user, updated_at = now() where id = sid;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'update', 'studio', sid, 'Safeguarding lead changed');\nend $$;\n\n-- ── R-035 · Staff checks ───────────────────────────────────────────────────\n-- DBS, safeguarding training and first aid, with expiry dates. Owner only: a\n-- certificate number is sensitive. The owner hears 30 days before anything\n-- runs out, once per check.\ncreate table staff_check (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  staff_id    uuid not null references staff_member(id) on delete cascade,\n  kind        text not null check (kind in ('dbs', 'safeguarding_training', 'first_aid', 'other')),\n  reference   text,\n  checked_on  date not null,\n  expires_on  date,\n  note        text,\n  reminded_at timestamptz,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  check (expires_on is null or expires_on >= checked_on)\n);\nalter table staff_check enable row level security; alter table staff_check force row level security;\ncreate policy staff_check_owner on staff_check for all\n  using (deleted_at is null and app.has_role(studio_id, 'owner')) with check (app.has_role(studio_id, 'owner'));\ngrant select, insert, update on staff_check to authenticated;\ngrant all on staff_check to service_role;\n\ncreate or replace function app.staff_check_stamp() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  select studio_id into new.studio_id from staff_member where id = new.staff_id;\n  if tg_op = 'UPDATE' and new.expires_on is distinct from old.expires_on then new.reminded_at := null; end if;\n  return new;\nend $$;\ncreate trigger staff_check_stamp before insert or update on staff_check for each row execute function app.staff_check_stamp();\n\n-- Called by the office's open app (and by the scheduler, once hosted).\ncreate or replace function app.remind_staff_checks(p_studio uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c record; n int := 0; u uuid;\nbegin\n  if auth.uid() is not null and not app.is_staff(p_studio) then return 0; end if;\n  for c in select k.*, sm.display_name from staff_check k join staff_member sm on sm.id = k.staff_id and sm.deleted_at is null and sm.status = 'active'\n            where k.studio_id = p_studio and k.deleted_at is null and k.reminded_at is null\n              and k.expires_on is not null and k.expires_on <= current_date + 30\n              and not exists (select 1 from staff_check newer where newer.staff_id = k.staff_id and newer.kind = k.kind\n                                and newer.deleted_at is null and newer.checked_on > k.checked_on) loop\n    for u in select m.user_id from membership m where m.studio_id = p_studio and m.role = 'owner' and m.deleted_at is null loop\n      perform app.notify_user(p_studio, u, 'staff_check_due',\n        case when c.expires_on < current_date then 'Expired: ' else 'Due soon: ' end || c.display_name || '’s ' ||\n        replace(case c.kind when 'dbs' then 'DBS check' else c.kind end, '_', ' '),\n        'Expires ' || to_char(c.expires_on, 'FMDD Month YYYY'), '/people?tab=staff');\n    end loop;\n    update staff_check set reminded_at = now() where id = c.id;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- ── R-041 · Keeping leavers' data only as long as needed ───────────────────\n-- A leaver is a child with no live enrolment, waiting-list place or trial,\n-- whose last class ended some time ago. Periods are per school, with\n-- defaults to confirm with the school's own adviser:\n--   medical record deleted          12 months after leaving\n--   child's details anonymised      36 months after leaving\n--   family financial records kept   72 months (six years) after the last invoice\ncreate table retention_policy (\n  studio_id         uuid primary key references studio(id) on delete cascade,\n  medical_months    smallint not null default 12 check (medical_months between 1 and 120),\n  personal_months   smallint not null default 36 check (personal_months between 6 and 240),\n  financial_months  smallint not null default 72 check (financial_months between 12 and 240),\n  last_run_at       timestamptz,\n  updated_at        timestamptz not null default now()\n);\nalter table retention_policy enable row level security; alter table retention_policy force row level security;\ncreate policy retention_owner on retention_policy for all\n  using (app.has_role(studio_id, 'owner')) with check (app.has_role(studio_id, 'owner'));\ncreate policy retention_admin_read on retention_policy for select using (app.is_admin(studio_id));\ngrant select, insert, update on retention_policy to authenticated;\ngrant all on retention_policy to service_role;\ninsert into retention_policy (studio_id) select id from studio on conflict do nothing;\ncreate or replace function app.on_studio_retention() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin insert into retention_policy (studio_id) values (new.id) on conflict do nothing; return null; end $$;\ncreate trigger studio_retention after insert on studio for each row execute function app.on_studio_retention();\n\ncreate or replace function app.leaver_since(p_student uuid) returns date\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case when exists (select 1 from enrolment e where e.student_id = p_student and e.status = 'active' and e.deleted_at is null)\n                or exists (select 1 from waitlist_entry w where w.student_id = p_student and w.status in ('waiting', 'offered') and w.deleted_at is null)\n                or exists (select 1 from trial t where t.student_id = p_student and t.status in ('booked', 'requested') and t.deleted_at is null)\n              then null\n              else coalesce((select max(coalesce(e.ended_on, e.updated_at::date)) from enrolment e where e.student_id = p_student),\n                            (select max(t.created_at::date) from trial t where t.student_id = p_student),\n                            (select created_at::date from student where id = p_student)) end;\n$$;\n\n-- What a run would do (p_apply = false), or does it. Each step is audited.\ncreate or replace function app.apply_retention(p_studio uuid, p_apply boolean default false)\n  returns table (step text, student_id uuid, who text, left_on date)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare pol retention_policy; r record;\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the owner runs data retention' using errcode = 'insufficient_privilege';\n  end if;\n  select * into pol from retention_policy where studio_id = p_studio;\n  for r in select s.id, s.first_name || ' ' || s.last_name as who, app.leaver_since(s.id) as since,\n                  exists (select 1 from medical_record m where m.student_id = s.id and m.deleted_at is null) as has_medical,\n                  s.first_name = 'Former' as anonymised\n             from student s where s.studio_id = p_studio and s.deleted_at is null loop\n    continue when r.since is null;\n    if r.has_medical and r.since < current_date - make_interval(months => pol.medical_months) then\n      step := 'medical'; student_id := r.id; who := r.who; left_on := r.since; return next;\n      if p_apply then\n        delete from medical_record where medical_record.student_id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'medical_record', r.id, 'Medical record deleted: left ' || r.since);\n      end if;\n    end if;\n    if not r.anonymised and r.since < current_date - make_interval(months => pol.personal_months) then\n      step := 'anonymise'; student_id := r.id; who := r.who; left_on := r.since; return next;\n      if p_apply then\n        delete from emergency_contact where emergency_contact.student_id = r.id;\n        delete from consent_record where consent_record.student_id = r.id;\n        delete from student_reflection where student_reflection.student_id = r.id;\n        update feedback_note set private_note = null, going_well = null, work_on = null where feedback_note.student_id = r.id;\n        update student set first_name = 'Former', last_name = 'student',\n               date_of_birth = make_date(extract(year from date_of_birth)::int, 1, 1), user_id = null, login_enabled = false,\n               updated_at = now() where id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'student', r.id, 'Details anonymised: left ' || r.since);\n      end if;\n    end if;\n  end loop;\n  if p_apply then update retention_policy set last_run_at = now() where studio_id = p_studio; end if;\nend $$;\n\nrevoke all on function app.is_safeguarding_lead(uuid), app.raise_concern(uuid, text, text, boolean), app.safeguarding_log(uuid),\n  app.safeguarding_actions(uuid), app.safeguarding_act(uuid, text, text), app.safeguarding_access_log(uuid),\n  app.set_safeguarding_lead(uuid), app.remind_staff_checks(uuid), app.leaver_since(uuid), app.apply_retention(uuid, boolean) from public;\ngrant execute on function app.is_safeguarding_lead(uuid), app.raise_concern(uuid, text, text, boolean), app.safeguarding_log(uuid),\n  app.safeguarding_actions(uuid), app.safeguarding_act(uuid, text, text), app.safeguarding_access_log(uuid),\n  app.set_safeguarding_lead(uuid), app.remind_staff_checks(uuid), app.apply_retention(uuid, boolean) to authenticated;\n"},{name:"0031_events.sql",sql:"-- ============================================================================\n-- 0031 · Shows and events, run from the office (R-015)\n-- ----------------------------------------------------------------------------\n-- The office creates a show (or exam, competition, workshop), invites whole\n-- classes, and families accept or decline. Rehearsals hang off the show and\n-- appear in families' and teachers' diaries. Routines give the running order,\n-- with a costume note and who dances in each. Chaperones are listed against\n-- the event. Fees are billed in one step to every confirmed dancer's family,\n-- once each.\n-- ============================================================================\n\nalter table studio_event add column parent_event_id uuid references studio_event(id) on delete cascade;\nalter table event_participant add column invited_class_id uuid references class(id) on delete set null;\nalter table invoice_item add column event_id uuid references studio_event(id) on delete set null;\n\ncreate table event_routine (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  event_id    uuid not null references studio_event(id) on delete cascade,\n  class_id    uuid references class(id) on delete set null,\n  title       text not null,\n  position    smallint not null default 0,\n  costume     text,\n  music       text,\n  notes       text,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\ncreate table routine_dancer (\n  routine_id  uuid not null references event_routine(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  primary key (routine_id, student_id)\n);\ncreate table event_chaperone (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  event_id    uuid not null references studio_event(id) on delete cascade,\n  name        text not null,\n  phone       text,\n  role        text,\n  checked     boolean not null default false,     -- DBS or equivalent seen by the office\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\nalter table event_routine enable row level security;   alter table event_routine force row level security;\nalter table routine_dancer enable row level security;  alter table routine_dancer force row level security;\nalter table event_chaperone enable row level security; alter table event_chaperone force row level security;\n\ncreate policy routine_admin on event_routine for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy routine_read on event_routine for select using (deleted_at is null and studio_id in (select app.studio_ids())\n  and exists (select 1 from studio_event e where e.id = event_id and e.deleted_at is null and (e.status = 'published' or app.is_staff(e.studio_id))));\ncreate policy dancer_admin on routine_dancer for all\n  using (exists (select 1 from event_routine r where r.id = routine_id and app.is_admin(r.studio_id)))\n  with check (exists (select 1 from event_routine r where r.id = routine_id and app.is_admin(r.studio_id)));\ncreate policy dancer_read on routine_dancer for select\n  using (student_id in (select app.guardian_student_ids()) or student_id = app.student_self_id()\n         or exists (select 1 from event_routine r where r.id = routine_id and app.is_staff(r.studio_id)));\n-- Chaperone phone numbers are for the office and the teachers on the day.\ncreate policy chaperone_staff on event_chaperone for select using (deleted_at is null and app.is_staff(studio_id));\ncreate policy chaperone_admin on event_chaperone for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n\ngrant select, insert, update, delete on event_routine, routine_dancer, event_chaperone to authenticated;\ngrant all on event_routine, routine_dancer, event_chaperone to service_role;\n\ncreate or replace function app.stamp_event_child() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin select studio_id into new.studio_id from studio_event where id = new.event_id; return new; end $$;\ncreate trigger routine_stamp before insert on event_routine for each row execute function app.stamp_event_child();\ncreate trigger chaperone_stamp before insert on event_chaperone for each row execute function app.stamp_event_child();\n\n-- Invite whole classes. Families are told; each child appears as \"invited\".\ncreate or replace function app.invite_classes(p_event uuid, p_classes uuid[]) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare ev studio_event; n int := 0; r record; fam uuid;\nbegin\n  select * into ev from studio_event where id = p_event and deleted_at is null;\n  perform app.require_admin(ev.studio_id);\n  for r in select distinct on (e.student_id) e.student_id, e.class_id, s.family_id, s.first_name\n             from enrolment e join student s on s.id = e.student_id and s.deleted_at is null\n            where e.class_id = any(p_classes) and e.status = 'active' and e.deleted_at is null\n              and exists (select 1 from class c where c.id = e.class_id and c.studio_id = ev.studio_id) loop\n    insert into event_participant (studio_id, event_id, student_id, status, invited_class_id, decided_by, decided_at)\n    values (ev.studio_id, ev.id, r.student_id, 'invited', r.class_id, auth.uid(), now())\n    on conflict (event_id, student_id) do nothing;\n    if found then\n      n := n + 1;\n      perform app.notify_family(r.family_id, 'event_invite', r.first_name || ' is invited: ' || ev.title,\n        to_char(ev.starts_at, 'FMDay DD Month') || coalesce(' · ' || ev.venue, ''), '/family/events');\n    end if;\n  end loop;\n  return n;\nend $$;\n\n-- A family answers an invitation.\ncreate or replace function app.answer_invitation(p_participant uuid, p_yes boolean) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p event_participant;\nbegin\n  select * into p from event_participant where id = p_participant and deleted_at is null;\n  if p.id is null or p.student_id not in (select app.guardian_student_ids()) then\n    raise exception 'FORBIDDEN: not your child' using errcode = 'insufficient_privilege';\n  end if;\n  if p.status <> 'invited' then raise exception 'INVALID: that invitation has already been answered' using errcode = 'check_violation'; end if;\n  update event_participant set status = case when p_yes then 'confirmed' else 'declined' end::participant_status,\n         decided_at = now(), updated_at = now() where id = p.id;\n  return case when p_yes then 'confirmed' else 'declined' end;\nend $$;\n\n-- Bill every confirmed dancer's family the event fee, once.\ncreate or replace function app.bill_event(p_event uuid, p_due date default null) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare ev studio_event; f record; inv uuid; n int := 0;\nbegin\n  select * into ev from studio_event where id = p_event and deleted_at is null;\n  perform app.require_admin(ev.studio_id);\n  if coalesce(ev.cost_minor, 0) = 0 then raise exception 'INVALID: this event has no fee' using errcode = 'check_violation'; end if;\n  for f in select s.family_id, jsonb_agg(jsonb_build_object('kind', case ev.kind when 'exam' then 'exam_fee' when 'show' then 'show_fee' else 'workshop' end,\n                    'description', ev.title || ' — ' || s.first_name, 'quantity', 1, 'unit_minor', ev.cost_minor, 'student_id', s.id)) items,\n                  array_agg(s.id) kids\n             from event_participant p join student s on s.id = p.student_id\n            where p.event_id = ev.id and p.status = 'confirmed' and p.deleted_at is null\n              and not exists (select 1 from invoice_item ii join invoice i on i.id = ii.invoice_id\n                               where ii.event_id = ev.id and ii.student_id = s.id and ii.deleted_at is null\n                                 and i.deleted_at is null and i.status not in ('void', 'refunded'))\n            group by s.family_id loop\n    inv := app.create_invoice(f.family_id, f.items, coalesce(p_due, (ev.starts_at::date - 7), current_date + 14), null, 0, true, null);\n    update invoice_item set event_id = ev.id where invoice_id = inv;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- Rehearsals in the diary: a family sees those of shows their child is in;\n-- a teacher those of shows their classes are invited to.\ncreate or replace function app.my_rehearsals(p_from timestamptz, p_to timestamptz)\n  returns table (id uuid, title text, show_title text, starts_at timestamptz, ends_at timestamptz, venue text, child text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select r.id, r.title, sh.title, r.starts_at, r.ends_at, coalesce(r.venue, sh.venue),\n         (select string_agg(distinct s.first_name, ' & ') from event_participant p join student s on s.id = p.student_id\n           where p.event_id = sh.id and p.status = 'confirmed' and p.deleted_at is null and s.id in (select app.guardian_student_ids()))\n    from studio_event r join studio_event sh on sh.id = r.parent_event_id and sh.deleted_at is null\n   where r.deleted_at is null and r.status = 'published' and r.starts_at >= p_from and r.starts_at < p_to\n     and (exists (select 1 from event_participant p where p.event_id = sh.id and p.status = 'confirmed' and p.deleted_at is null\n                   and (p.student_id in (select app.guardian_student_ids()) or p.student_id = app.student_self_id()))\n       or exists (select 1 from event_participant p where p.event_id = sh.id and p.invited_class_id in (select app.teacher_class_ids()))\n       or app.is_admin(r.studio_id))\n   order by r.starts_at;\n$$;\n\nrevoke all on function app.invite_classes(uuid, uuid[]), app.answer_invitation(uuid, boolean), app.bill_event(uuid, date),\n  app.my_rehearsals(timestamptz, timestamptz) from public;\ngrant execute on function app.invite_classes(uuid, uuid[]), app.answer_invitation(uuid, boolean), app.bill_event(uuid, date),\n  app.my_rehearsals(timestamptz, timestamptz) to authenticated;\n"},{name:"0032_school_switch.sql",sql:"-- ============================================================================\n-- 0032 · People in more than one school (R-031)\n-- ----------------------------------------------------------------------------\n-- A teacher who works at two schools, or a parent with children at two, uses\n-- one login. The app sends which school they are looking at; every access\n-- helper then narrows to it, so no screen can mix one school's data into\n-- another's — however a query is written.\n--\n-- This is a filter, never a grant: app.in_scope() can only ever remove\n-- schools from what a person may already see. Sending another school's id\n-- simply shows nothing, because the person has no membership there.\n-- In production the selection travels as the x-barre-studio request header.\n-- ============================================================================\n\ncreate or replace function app.selected_studio() returns uuid\n  language plpgsql stable as $$\ndeclare v text;\nbegin\n  v := coalesce(auth.jwt() ->> 'studio',\n                nullif(current_setting('request.headers', true), '')::json ->> 'x-barre-studio');\n  if v is null or v = '' then return null; end if;\n  return v::uuid;\nexception when others then return null;\nend $$;\n\ncreate or replace function app.in_scope(p_studio uuid) returns boolean\n  language sql stable as $$ select app.selected_studio() is null or app.selected_studio() = p_studio $$;\n\ncreate or replace function app.memberships()\n  returns table (studio_id uuid, role app_role)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select m.studio_id, m.role\n    from membership m\n   where m.user_id = auth.uid() and m.deleted_at is null and app.studio_writable(m.studio_id) and app.in_scope(m.studio_id)\n  union\n  select app.support_studio_id(), 'admin'::app_role\n   where app.support_studio_id() is not null\n$$;\n\ncreate or replace function app.guardian_family_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select g.family_id from guardian g\n   where g.user_id = auth.uid() and g.deleted_at is null and app.studio_writable(g.studio_id) and app.in_scope(g.studio_id)\n$$;\n\ncreate or replace function app.teacher_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id from class c\n    join staff_member s on s.id in (c.teacher_id, c.assistant_id)\n   where s.user_id = auth.uid() and s.deleted_at is null and c.deleted_at is null\n     and app.studio_writable(c.studio_id) and app.in_scope(c.studio_id)\n  union\n  select cs.class_id from class_session cs\n    join staff_member s on s.id = cs.teacher_id\n   where s.user_id = auth.uid() and s.deleted_at is null and cs.deleted_at is null\n     and cs.status <> 'cancelled'\n     and cs.starts_at between now() - interval '2 days' and now() + interval '14 days'\n     and app.studio_writable(cs.studio_id) and app.in_scope(cs.studio_id)\n$$;\n\ncreate or replace function app.student_self_id() returns uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id from student s\n   where s.user_id = auth.uid() and s.login_enabled and s.deleted_at is null\n     and app.studio_writable(s.studio_id) and app.in_scope(s.studio_id)\n   limit 1\n$$;\n\n-- Every school a person belongs to, whatever is selected: for the switcher.\ncreate or replace function app.my_schools()\n  returns table (studio_id uuid, name text, logo_url text, brand_colour text, roles text[], since timestamptz)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id, s.name, s.logo_url, s.brand_colour, array_agg(distinct r order by r), min(x.since)\n    from (select m.studio_id, m.role::text r, m.created_at since from membership m where m.user_id = auth.uid() and m.deleted_at is null\n          union select g.studio_id, 'guardian', g.created_at from guardian g where g.user_id = auth.uid() and g.deleted_at is null\n          union select st.studio_id, 'student', st.created_at from student st where st.user_id = auth.uid() and st.login_enabled and st.deleted_at is null) x\n    join studio s on s.id = x.studio_id and s.deleted_at is null and app.studio_writable(s.id)\n   group by s.id order by min(x.since), s.name;\n$$;\ngrant execute on function app.my_schools(), app.selected_studio(), app.in_scope(uuid) to authenticated;\n"},{name:"0033_dropin_credit.sql",sql:"-- ============================================================================\n-- 0033 · Drop-in classes, class packs, adult learners (R-034), and credit\n--        when the school cancels a class\n-- ----------------------------------------------------------------------------\n-- Pay-as-you-go classes ('drop_in' pricing) are booked a session at a time.\n-- A booking is paid from a class pack if the dancer has one with classes\n-- left, otherwise it is invoiced at the class price. Card payment for those\n-- invoices arrives through the payments module once it is connected\n-- (docs/PAYMENTS.md); until then the family pays on their account.\n--\n-- An adult learner is simply a family whose dancer is the parent: the same\n-- screens serve them, and the public page lets an adult book for themselves.\n-- ============================================================================\n\ncreate or replace function app.allocate_account_credit_internal(p_family uuid) returns bigint\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; avail bigint; inv record; take bigint; total bigint := 0;\nbegin\n  select studio_id into sid from family where id = p_family and deleted_at is null;\n  avail := app.family_available_credit(p_family);\n  for inv in\n    select id, total_minor - paid_minor as owed from invoice\n     where family_id = p_family and deleted_at is null\n       and status in ('issued', 'part_paid', 'refunded') and total_minor > paid_minor\n     order by due_on nulls last, issued_on, number\n  loop\n    exit when avail <= 0;\n    take := least(avail, inv.owed);\n    insert into payment (studio_id, family_id, invoice_id, amount_minor, method,\n                         provider, succeeded_at, note, recorded_by)\n    values (sid, p_family, inv.id, take, 'account', 'ledger', now(),\n            'Credit on account applied', auth.uid());\n    avail := avail - take; total := total + take;\n  end loop;\n  return total;\nend $$;\nrevoke all on function app.allocate_account_credit_internal(uuid) from public, authenticated, anon;\n\n-- Invoices raised by the system on a family's behalf (a drop-in, a pack):\n-- the same as app.create_invoice without the office check. Never granted to\n-- users; only callable from the checked functions below.\ncreate or replace function app.create_invoice_internal(\n  p_family uuid, p_items jsonb, p_due date default null, p_note text default null,\n  p_discount_minor bigint default 0, p_issue boolean default true, p_term uuid default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; inv uuid; num text; it jsonb; n int := 0;\nbegin\n  select studio_id into sid from family where id = p_family and deleted_at is null;\n\n  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then\n    raise exception 'INVALID: an invoice needs at least one line' using errcode = 'check_violation';\n  end if;\n  if coalesce(p_discount_minor, 0) < 0 then\n    raise exception 'INVALID: a discount cannot be negative' using errcode = 'check_violation';\n  end if;\n\n  -- Sequential per studio. The advisory lock stops two people raising\n  -- invoices at the same moment from being handed the same number.\n  perform pg_advisory_xact_lock(hashtext('invoice-number:' || sid::text));\n  select 'INV-' || lpad((coalesce(max(nullif(regexp_replace(number, '\\D', '', 'g'), '')::int), 1000) + 1)::text, 4, '0')\n    into num from invoice where studio_id = sid;\n\n  insert into invoice (studio_id, family_id, term_id, number, status, issued_on, due_on,\n                       discount_minor, note, created_by)\n  values (sid, p_family, p_term, num, case when p_issue then 'issued' else 'draft' end::invoice_status,\n          case when p_issue then current_date end,\n          coalesce(p_due, current_date + 14), coalesce(p_discount_minor, 0),\n          nullif(btrim(p_note), ''), auth.uid())\n  returning id into inv;\n\n  for it in select * from jsonb_array_elements(p_items) loop\n    n := n + 1;\n    if coalesce(btrim(it->>'description'), '') = '' then\n      raise exception 'INVALID: line % needs a description', n using errcode = 'check_violation';\n    end if;\n    -- A line about a child must be about a child in this family.\n    if it->>'student_id' is not null and not exists (\n         select 1 from student s where s.id = (it->>'student_id')::uuid\n            and s.family_id = p_family and s.deleted_at is null) then\n      raise exception 'INVALID: line % names a student outside this family', n\n        using errcode = 'check_violation';\n    end if;\n    insert into invoice_item (studio_id, invoice_id, student_id, class_id, kind, description,\n                              quantity, unit_minor, discount_minor)\n    values (sid, inv, (it->>'student_id')::uuid, (it->>'class_id')::uuid,\n            coalesce(it->>'kind', 'other')::charge_kind, btrim(it->>'description'),\n            coalesce((it->>'quantity')::numeric, 1), (it->>'unit_minor')::int,\n            coalesce((it->>'discount_minor')::int, 0));\n  end loop;\n\n  if exists (select 1 from invoice_item where invoice_id = inv and total_minor < 0) then\n    raise exception 'INVALID: a line discount is larger than the line' using errcode = 'check_violation';\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'create', 'invoice', inv, num);\n\n  if p_issue then perform app.allocate_account_credit_internal(p_family); end if;\n  return inv;\nend $$;\nrevoke all on function app.create_invoice_internal(uuid, jsonb, date, text, bigint, boolean, uuid) from public, authenticated, anon;\n\n-- ── Packs ──────────────────────────────────────────────────────────────────\ncreate table class_pack (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  name        text not null,\n  classes     smallint not null check (classes between 1 and 100),\n  price_minor integer not null check (price_minor >= 0),\n  valid_days  smallint not null default 90 check (valid_days between 7 and 730),\n  active      boolean not null default true,\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\ncreate table pack_purchase (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  pack_id     uuid not null references class_pack(id) on delete restrict,\n  family_id   uuid not null references family(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  remaining   smallint not null check (remaining >= 0),\n  expires_on  date not null,\n  invoice_id  uuid references invoice(id) on delete set null,\n  created_at  timestamptz not null default now()\n);\ncreate table drop_in_booking (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  session_id  uuid not null references class_session(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  status      text not null default 'booked' check (status in ('booked', 'cancelled')),\n  pack_purchase_id uuid references pack_purchase(id) on delete set null,\n  invoice_id  uuid references invoice(id) on delete set null,\n  price_minor integer not null default 0,\n  booked_by   uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now(),\n  cancelled_at timestamptz\n);\ncreate unique index drop_in_once on drop_in_booking (session_id, student_id) where status = 'booked';\n\nalter table class_pack enable row level security;      alter table class_pack force row level security;\nalter table pack_purchase enable row level security;   alter table pack_purchase force row level security;\nalter table drop_in_booking enable row level security; alter table drop_in_booking force row level security;\ncreate policy pack_read on class_pack for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy pack_admin on class_pack for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy purchase_read on pack_purchase for select\n  using (app.is_admin(studio_id) or family_id in (select app.guardian_family_ids()));\ncreate policy dropin_read on drop_in_booking for select\n  using (app.is_admin(studio_id) or student_id in (select app.guardian_student_ids())\n         or (app.has_role(studio_id, 'teacher') and session_id in (select id from class_session where class_id in (select app.teacher_class_ids()))));\ngrant select, insert, update on class_pack to authenticated;\ngrant select on pack_purchase, drop_in_booking to authenticated;\ngrant all on class_pack, pack_purchase, drop_in_booking to service_role;\n\n-- Teachers see drop-in dancers in their classes, as they do trialists.\ncreate or replace function app.teacher_student_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select e.student_id from enrolment e\n   where e.class_id in (select app.teacher_class_ids()) and e.status = 'active' and e.deleted_at is null\n  union\n  select t.student_id from trial t\n   where t.class_id in (select app.teacher_class_ids()) and t.student_id is not null and t.deleted_at is null\n     and t.status in ('booked', 'attended')\n  union\n  select d.student_id from drop_in_booking d join class_session cs on cs.id = d.session_id\n   where cs.class_id in (select app.teacher_class_ids()) and d.status = 'booked'\n     and cs.starts_at > now() - interval '30 days'\n$$;\n\n-- Places taken in one session: the enrolled, plus trials and drop-ins for it.\ncreate or replace function app.session_taken(p_session uuid) returns int\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select app.class_enrolled_count(cs.class_id)\n       + (select count(*)::int from trial t where t.session_id = cs.id and t.status = 'booked' and t.deleted_at is null)\n       + (select count(*)::int from drop_in_booking d where d.session_id = cs.id and d.status = 'booked')\n    from class_session cs where cs.id = p_session;\n$$;\n\ncreate or replace function app.buy_pack(p_pack uuid, p_student uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare k class_pack; s student; inv uuid; pid uuid;\nbegin\n  select * into k from class_pack where id = p_pack and active and deleted_at is null;\n  select * into s from student where id = p_student and deleted_at is null;\n  if k.id is null or s.id is null or s.studio_id <> k.studio_id then raise exception 'NOT_FOUND: that pack' using errcode = 'no_data_found'; end if;\n  if not (s.id in (select app.guardian_student_ids()) or app.is_admin(s.studio_id)) then\n    raise exception 'FORBIDDEN: not your dancer' using errcode = 'insufficient_privilege';\n  end if;\n  inv := app.create_invoice_internal(s.family_id, jsonb_build_array(jsonb_build_object('kind', 'other', 'description', k.name || ' — ' || s.first_name,\n           'quantity', 1, 'unit_minor', k.price_minor, 'student_id', s.id)), current_date + 7, null, 0, true, null);\n  insert into pack_purchase (studio_id, pack_id, family_id, student_id, remaining, expires_on, invoice_id)\n  values (s.studio_id, k.id, s.family_id, s.id, k.classes, current_date + k.valid_days, inv) returning id into pid;\n  return pid;\nend $$;\n\n-- Book one drop-in session. Uses a pack if there is one, else invoices.\ncreate or replace function app.book_drop_in(p_session uuid, p_student uuid) returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not exists (select 1 from student s where s.id = p_student and s.deleted_at is null\n                   and (s.id in (select app.guardian_student_ids()) or app.is_admin(s.studio_id))) then\n    raise exception 'FORBIDDEN: not your dancer' using errcode = 'insufficient_privilege';\n  end if;\n  return app.book_drop_in_unchecked(p_session, p_student);\nend $$;\n\n-- The booking itself; callers have already checked who may book.\ncreate or replace function app.book_drop_in_unchecked(p_session uuid, p_student uuid) returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; s student; pk pack_purchase; inv uuid; bid uuid;\nbegin\n  select x.*, c.name cname, c.price_minor, c.pricing, c.capacity, c.studio_id sid into cs\n    from class_session x join class c on c.id = x.class_id where x.id = p_session and x.deleted_at is null;\n  select * into s from student where id = p_student and deleted_at is null;\n  if cs.id is null or s.id is null or s.studio_id <> cs.sid then raise exception 'NOT_FOUND: that class' using errcode = 'no_data_found'; end if;\n  if cs.pricing <> 'drop_in' then raise exception 'INVALID: % is booked by the term, not class by class', cs.cname using errcode = 'check_violation'; end if;\n  if cs.status <> 'scheduled' or cs.starts_at < now() then raise exception 'INVALID: that class is not open for booking' using errcode = 'check_violation'; end if;\n  if app.session_taken(cs.id) >= cs.capacity then raise exception 'INVALID: that class is full — try another date' using errcode = 'check_violation'; end if;\n  if exists (select 1 from drop_in_booking where session_id = cs.id and student_id = s.id and status = 'booked') then\n    raise exception 'INVALID: % is already booked in', s.first_name using errcode = 'check_violation';\n  end if;\n  if not exists (select 1 from emergency_contact where student_id = s.id and deleted_at is null) then\n    raise exception 'INVALID: add an emergency contact for % first', s.first_name using errcode = 'check_violation';\n  end if;\n  select * into pk from pack_purchase where student_id = s.id and remaining > 0 and expires_on >= cs.starts_at::date\n   order by expires_on limit 1 for update;\n  if pk.id is not null then\n    update pack_purchase set remaining = remaining - 1 where id = pk.id;\n  elsif cs.price_minor > 0 then\n    inv := app.create_invoice_internal(s.family_id, jsonb_build_array(jsonb_build_object('kind', 'tuition',\n             'description', cs.cname || ' — ' || to_char(cs.starts_at, 'FMDD Mon') || ' — ' || s.first_name,\n             'quantity', 1, 'unit_minor', cs.price_minor, 'student_id', s.id, 'class_id', cs.class_id)), cs.starts_at::date, null, 0, true, null);\n  end if;\n  insert into drop_in_booking (studio_id, session_id, student_id, pack_purchase_id, invoice_id, price_minor, booked_by)\n  values (s.studio_id, cs.id, s.id, pk.id, inv, case when pk.id is null then cs.price_minor else 0 end, auth.uid())\n  returning id into bid;\n  return jsonb_build_object('id', bid, 'paid_with', case when pk.id is not null then 'pack' when inv is not null then 'invoice' else 'free' end,\n                            'pack_left', case when pk.id is not null then pk.remaining - 1 end);\nend $$;\n\n-- Cancel a drop-in more than 24 hours ahead: the pack class comes back, or\n-- the invoice is voided. Later than that, the place is still released.\ncreate or replace function app.cancel_drop_in(p_booking uuid) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare b drop_in_booking; starts timestamptz; refunded boolean := false;\nbegin\n  select * into b from drop_in_booking where id = p_booking and status = 'booked';\n  if b.id is null then raise exception 'INVALID: that booking is not live' using errcode = 'check_violation'; end if;\n  if not (b.student_id in (select app.guardian_student_ids()) or app.is_admin(b.studio_id)) then\n    raise exception 'FORBIDDEN: not your booking' using errcode = 'insufficient_privilege';\n  end if;\n  select starts_at into starts from class_session where id = b.session_id;\n  update drop_in_booking set status = 'cancelled', cancelled_at = now() where id = b.id;\n  if starts > now() + interval '24 hours' then\n    if b.pack_purchase_id is not null then\n      update pack_purchase set remaining = remaining + 1 where id = b.pack_purchase_id; refunded := true;\n    elsif b.invoice_id is not null and (select paid_minor from invoice where id = b.invoice_id) = 0 then\n      update invoice set status = 'void', voided_at = now(), void_reason = 'Drop-in cancelled in good time' where id = b.invoice_id;\n      perform app.recalc_family_balance((select family_id from invoice where id = b.invoice_id));\n      refunded := true;\n    end if;\n  end if;\n  return case when refunded then 'refunded' else 'released' end;\nend $$;\n\n-- Drop-in sessions open to book, for a family's dancer (or anyone, publicly).\ncreate or replace function app.drop_in_sessions(p_studio uuid, p_days int default 21)\n  returns table (session_id uuid, class_name text, style text, starts_at timestamptz, ends_at timestamptz,\n                 price_minor int, places_left int, age_min smallint, age_max smallint)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select cs.id, c.name, ds.name, cs.starts_at, cs.ends_at, c.price_minor, (c.capacity - app.session_taken(cs.id))::int, c.age_min, c.age_max\n    from class c join class_session cs on cs.class_id = c.id and cs.deleted_at is null and cs.status = 'scheduled'\n    left join dance_style ds on ds.id = c.dance_style_id\n   where c.studio_id = p_studio and c.deleted_at is null and c.pricing = 'drop_in' and c.visibility <> 'private'\n     and cs.starts_at between now() + interval '1 hour' and now() + make_interval(days => p_days)\n     and app.session_taken(cs.id) < c.capacity\n   order by cs.starts_at;\n$$;\n\n-- An adult books their own first class from the public page: they are both\n-- the family and the dancer.\ncreate or replace function app.public_adult_drop_in(p_slug text, p_session uuid, p_form jsonb) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; fam uuid; kid uuid; r jsonb;\nbegin\n  select * into st from studio where slug = lower(p_slug) and deleted_at is null;\n  if st.id is null or not app.studio_writable(st.id) then raise exception 'NOT_FOUND: that school' using errcode = 'no_data_found'; end if;\n  if coalesce(p_form ->> 'website', '') <> '' then return 'ok'; end if;\n  if coalesce(btrim(p_form ->> 'name'), '') = '' or coalesce(btrim(p_form ->> 'phone'), '') = ''\n     or coalesce(p_form ->> 'email', '') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' or coalesce(btrim(p_form ->> 'emergency_phone'), '') = '' then\n    raise exception 'INVALID: please give your name, email, phone and someone to ring in an emergency' using errcode = 'check_violation';\n  end if;\n  if not exists (select 1 from app.drop_in_sessions(st.id) d where d.session_id = p_session) then\n    raise exception 'INVALID: that class is full or no longer open — please pick another' using errcode = 'check_violation';\n  end if;\n  select g.family_id into fam from guardian g where g.studio_id = st.id and lower(g.email) = lower(btrim(p_form ->> 'email')) and g.deleted_at is null limit 1;\n  if fam is null then\n    insert into family (studio_id, name) values (st.id, regexp_replace(btrim(p_form ->> 'name'), '^.*\\s', '') || ' (adult)') returning id into fam;\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary, relationship)\n    values (st.id, fam, btrim(p_form ->> 'name'), lower(btrim(p_form ->> 'email')), btrim(p_form ->> 'phone'), true, 'Self');\n    insert into student (studio_id, family_id, first_name, last_name, date_of_birth)\n    values (st.id, fam, split_part(btrim(p_form ->> 'name'), ' ', 1),\n            coalesce(nullif(regexp_replace(btrim(p_form ->> 'name'), '^\\S+\\s*', ''), ''), '—'),\n            coalesce((p_form ->> 'date_of_birth')::date, current_date - interval '30 years')) returning id into kid;\n    insert into emergency_contact (studio_id, student_id, full_name, phone, priority)\n    values (st.id, kid, coalesce(nullif(btrim(p_form ->> 'emergency_name'), ''), 'Emergency contact'), btrim(p_form ->> 'emergency_phone'), 1);\n  else\n    select id into kid from student where family_id = fam and deleted_at is null order by created_at limit 1;\n  end if;\n  r := app.book_drop_in_unchecked(p_session, kid);\n  return 'ok';\nend $$;\n\n-- ── Credit when the school cancels a class ─────────────────────────────────\n-- Off by default; when on, every family with a child enrolled in a term- or\n-- month-priced class gets that class's per-session value back as account\n-- credit, once per child per cancelled session. Drop-ins are refunded by\n-- cancelling the booking instead.\nalter table studio add column credit_cancelled_classes boolean not null default false;\ncreate table session_credit (\n  session_id uuid not null references class_session(id) on delete cascade,\n  student_id uuid not null references student(id) on delete cascade,\n  payment_id uuid references payment(id) on delete set null,\n  amount_minor integer not null,\n  primary key (session_id, student_id)\n);\nalter table session_credit enable row level security; alter table session_credit force row level security;\ncreate policy session_credit_read on session_credit for select using (\n  exists (select 1 from class_session cs where cs.id = session_id and app.is_admin(cs.studio_id)) or student_id in (select app.guardian_student_ids()));\ngrant select on session_credit to authenticated;\ngrant all on session_credit to service_role;\n\ncreate or replace function app.on_session_cancelled_credit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class; per int; e record; pay uuid;\nbegin\n  if new.status <> 'cancelled' or old.status = 'cancelled' then return null; end if;\n  if not (select credit_cancelled_classes from studio where id = new.studio_id) then return null; end if;\n  select * into c from class where id = new.class_id;\n  if c.pricing not in ('term', 'monthly') then return null; end if;\n  per := case c.pricing\n    when 'term' then round(c.price_minor::numeric / greatest(1, (select count(*) from class_session x where x.class_id = c.id and x.deleted_at is null)))::int\n    else round(c.price_minor::numeric * 12 / 52)::int end;\n  if per <= 0 then return null; end if;\n  for e in select s.id, s.family_id, s.first_name, coalesce(en.price_minor, c.price_minor) price from enrolment en join student s on s.id = en.student_id\n            where en.class_id = c.id and en.status = 'active' and en.deleted_at is null loop\n    continue when exists (select 1 from session_credit where session_id = new.id and student_id = e.id);\n    insert into payment (studio_id, family_id, amount_minor, method, succeeded_at, note, recorded_by)\n    values (new.studio_id, e.family_id, per, 'credit', now(),\n            'Credit: ' || c.name || ' cancelled ' || to_char(new.starts_at, 'FMDD Mon') || ' (' || e.first_name || ')', auth.uid())\n    returning id into pay;\n    insert into session_credit (session_id, student_id, payment_id, amount_minor) values (new.id, e.id, pay, per);\n    perform app.allocate_account_credit(e.family_id);\n    perform app.recalc_family_balance(e.family_id);\n  end loop;\n  return null;\nend $$;\ncreate trigger session_cancelled_credit after update of status on class_session\n  for each row execute function app.on_session_cancelled_credit();\n\nrevoke all on function app.buy_pack(uuid, uuid), app.book_drop_in(uuid, uuid), app.cancel_drop_in(uuid),\n  app.drop_in_sessions(uuid, int), app.public_adult_drop_in(text, uuid, jsonb), app.session_taken(uuid) from public;\nrevoke all on function app.book_drop_in_unchecked(uuid, uuid) from public, authenticated, anon;\ngrant execute on function app.buy_pack(uuid, uuid), app.book_drop_in(uuid, uuid), app.cancel_drop_in(uuid),\n  app.drop_in_sessions(uuid, int), app.session_taken(uuid) to authenticated, service_role;\ngrant execute on function app.drop_in_sessions(uuid, int) to anon;\ngrant execute on function app.public_adult_drop_in(text, uuid, jsonb) to authenticated, anon;\n\n-- A family sees the sessions it has booked into, as it does its enrolled ones.\ncreate or replace function app.my_drop_in_session_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select d.session_id from drop_in_booking d where d.status = 'booked'\n     and (d.student_id in (select app.guardian_student_ids()) or d.student_id = app.student_self_id());\n$$;\ngrant execute on function app.my_drop_in_session_ids() to authenticated;\ncreate policy session_dropin_read on class_session for select\n  using (deleted_at is null and id in (select app.my_drop_in_session_ids()));\n\ncreate or replace function app.public_drop_in_sessions(p_slug text)\n  returns table (session_id uuid, class_name text, style text, starts_at timestamptz, ends_at timestamptz,\n                 price_minor int, places_left int, age_min smallint, age_max smallint)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select d.* from studio s, app.drop_in_sessions(s.id) d\n   where s.slug = lower(p_slug) and s.deleted_at is null and app.studio_writable(s.id);\n$$;\ngrant execute on function app.public_drop_in_sessions(text) to authenticated, anon;\n"},{name:"0034_delivery.sql",sql:"-- ============================================================================\n-- 0034 · Delivering email and text (R-003), and the server's clock (R-002)\n-- ----------------------------------------------------------------------------\n-- The queue was already there (0018). This adds what a delivery worker needs:\n--   · claiming a batch safely, so two workers never send the same message\n--   · retries with back-off, and a final 'failed' after five attempts\n--   · quiet hours: a message for someone in their quiet hours waits\n--   · email copies of notifications, for people who asked for email in their\n--     preferences (0028)\n-- and one function the hosted scheduler calls every few minutes.\n--\n-- The worker itself (scripts/deliver.mts) talks to the provider. Which\n-- provider is configuration: Postmark, Resend or Twilio, chosen by\n-- environment variables, or 'log' to print instead of sending.\n-- ============================================================================\n\nalter table outbound_message add column user_id uuid references user_account(id) on delete set null;\nalter table outbound_message add column attempts smallint not null default 0;\nalter table outbound_message add column not_before timestamptz not null default now();\nalter table outbound_message add column claimed_until timestamptz;\nalter table outbound_message add column notification_id uuid references notification(id) on delete set null;\ncreate index outbound_due on outbound_message (not_before) where status = 'queued';\n\n-- When a user's quiet hours end, in the school's time zone.\ncreate or replace function app.after_quiet(p_user uuid, p_studio uuid, p_at timestamptz default now()) returns timestamptz\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare u user_account; tz text; local_t time; local_d date;\nbegin\n  select * into u from user_account where id = p_user;\n  if u.id is null or u.quiet_from is null or u.quiet_to is null then return p_at; end if;\n  select coalesce(timezone, 'Europe/London') into tz from studio where id = p_studio;\n  local_t := (p_at at time zone tz)::time;\n  local_d := (p_at at time zone tz)::date;\n  if u.quiet_from < u.quiet_to then                         -- e.g. 13:00–14:00\n    if local_t >= u.quiet_from and local_t < u.quiet_to then return (local_d + u.quiet_to) at time zone tz; end if;\n  else                                                       -- e.g. 21:00–07:00, across midnight\n    if local_t >= u.quiet_from then return (local_d + 1 + u.quiet_to) at time zone tz; end if;\n    if local_t < u.quiet_to then return (local_d + u.quiet_to) at time zone tz; end if;\n  end if;\n  return p_at;\nend $$;\n\n-- Email copies of notifications, for those who asked. Safety and schedule\n-- notices always go (they cannot be switched off), and ignore quiet hours\n-- only when they are about a class today.\ncreate or replace function app.on_notification_email() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare u user_account; urgent boolean;\nbegin\n  if current_setting('app.quiet', true) = 'on' then return null; end if;\n  select * into u from user_account where id = new.user_id and deleted_at is null;\n  if u.id is null or coalesce(u.email, '') !~ '@' then return null; end if;\n  if not app.wants(new.user_id, new.kind, 'email') then return null; end if;\n  urgent := new.kind in ('schedule_change', 'safeguarding') and new.title ~* '^(cancelled|urgent)';\n  insert into outbound_message (studio_id, channel, to_name, to_address, subject, body, user_id, notification_id, not_before)\n  values (new.studio_id, 'email', u.full_name, u.email, new.title,\n          coalesce(new.body, '') || E'\\n\\nOpen Swayvo to see more.', u.id, new.id,\n          case when urgent then now() else app.after_quiet(u.id, new.studio_id) end);\n  return null;\nend $$;\ncreate trigger notification_email after insert on notification for each row execute function app.on_notification_email();\n\n-- The worker claims a batch: due, queued, not claimed by someone else.\ncreate or replace function app.claim_outbound(p_limit int default 50, p_lease interval default '5 minutes')\n  returns setof outbound_message\n  language sql security definer set search_path = public, app, pg_temp as $$\n  update outbound_message o set claimed_until = now() + p_lease, attempts = o.attempts + 1\n   where o.id in (select id from outbound_message\n                   where status = 'queued' and not_before <= now() and (claimed_until is null or claimed_until < now())\n                   order by not_before limit p_limit for update skip locked)\n  returning o.*;\n$$;\n\ncreate or replace function app.outbound_result(p_id uuid, p_ok boolean, p_ref text default null, p_error text default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare m outbound_message;\nbegin\n  select * into m from outbound_message where id = p_id;\n  if p_ok then\n    update outbound_message set status = 'sent', sent_at = now(), provider_ref = p_ref, error = null, claimed_until = null where id = p_id;\n  elsif m.attempts >= 5 then\n    update outbound_message set status = 'failed', error = p_error, claimed_until = null where id = p_id;\n  else\n    -- 1, 4, 9, 16 minutes.\n    update outbound_message set error = p_error, claimed_until = null,\n           not_before = now() + make_interval(mins => m.attempts * m.attempts) where id = p_id;\n  end if;\nend $$;\n\n-- Everything time-driven, for every school, in one call. The hosted\n-- scheduler runs it every five minutes; it is safe to run more often.\ncreate or replace function app.tick() returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s record; auto int := 0; released int := 0; checks int := 0;\nbegin\n  for s in select id from studio where deleted_at is null and app.studio_writable(id) loop\n    auto := auto + coalesce(app.run_automations(s.id), 0);\n    released := released + app.release_scheduled(s.id);\n    checks := checks + app.remind_staff_checks(s.id);\n    perform app.award_event_milestones(s.id);\n  end loop;\n  return jsonb_build_object('automations', auto, 'released', released, 'staff_checks', checks, 'at', now());\nend $$;\n\nrevoke all on function app.after_quiet(uuid, uuid, timestamptz), app.claim_outbound(int, interval),\n  app.outbound_result(uuid, boolean, text, text), app.tick() from public, authenticated, anon;\ngrant execute on function app.claim_outbound(int, interval), app.outbound_result(uuid, boolean, text, text), app.tick() to service_role;\n"},{name:"0035_push.sql",sql:"-- ============================================================================\n-- 0035 · Phone notifications (R-017)\n-- ----------------------------------------------------------------------------\n-- A device that accepts notifications stores its push subscription here. When\n-- a notification is written, each of the person's devices gets a push queued\n-- in outbound_message (channel 'push'), sent by the worker with the\n-- server's VAPID key. Push follows the in-app preference and quiet hours,\n-- except same-day cancellations and urgent safeguarding notices.\n-- ============================================================================\ncreate table push_subscription (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references user_account(id) on delete cascade,\n  endpoint   text not null unique check (endpoint ~ '^https://'),\n  p256dh     text not null,\n  auth       text not null,\n  user_agent text,\n  created_at timestamptz not null default now(),\n  last_ok_at timestamptz\n);\nalter table push_subscription enable row level security; alter table push_subscription force row level security;\ncreate policy push_own on push_subscription for all using (user_id = auth.uid()) with check (user_id = auth.uid());\ngrant select, insert, delete on push_subscription to authenticated;\ngrant all on push_subscription to service_role;\n\ncreate or replace function app.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_agent text default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if auth.uid() is null then raise exception 'FORBIDDEN: sign in first' using errcode = 'insufficient_privilege'; end if;\n  insert into push_subscription (user_id, endpoint, p256dh, auth, user_agent)\n  values (auth.uid(), p_endpoint, p_p256dh, p_auth, left(p_agent, 200))\n  on conflict (endpoint) do update set user_id = auth.uid(), p256dh = excluded.p256dh, auth = excluded.auth;\nend $$;\ngrant execute on function app.save_push_subscription(text, text, text, text) to authenticated;\n\ncreate or replace function app.on_notification_push() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p push_subscription; urgent boolean; at timestamptz;\nbegin\n  if current_setting('app.quiet', true) = 'on' then return null; end if;\n  urgent := new.kind in ('schedule_change', 'safeguarding') and new.title ~* '^(cancelled|urgent)';\n  at := case when urgent then now() else app.after_quiet(new.user_id, new.studio_id) end;\n  for p in select * from push_subscription where user_id = new.user_id loop\n    insert into outbound_message (studio_id, channel, to_address, subject, body, user_id, notification_id, not_before)\n    values (new.studio_id, 'push', p.endpoint, new.title,\n            json_build_object('title', new.title, 'body', coalesce(new.body, ''), 'href', coalesce(new.href, ''), 'tag', new.kind)::text,\n            new.user_id, new.id, at);\n  end loop;\n  return null;\nend $$;\ncreate trigger notification_push after insert on notification for each row execute function app.on_notification_push();\n\nalter table outbound_message drop constraint if exists outbound_message_channel_check;\nalter table outbound_message add constraint outbound_message_channel_check check (channel in ('email', 'sms', 'push'));\n\n-- The worker reads the keys for a push it is about to send.\ncreate or replace function app.push_keys(p_endpoint text) returns table (p256dh text, auth text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select p256dh, auth from push_subscription where endpoint = p_endpoint;\n$$;\nrevoke all on function app.push_keys(text) from public, authenticated, anon;\ngrant execute on function app.push_keys(text) to service_role;\n"},{name:"0036_pilot.sql",sql:"-- ============================================================================\n-- 0036 · Pilot schools and activation (R-040)\n-- ----------------------------------------------------------------------------\n-- What the platform team needs to run a pilot: which schools are in it, and\n-- how far each has got with the things that predict a school staying —\n-- set up, families in, registers taken weekly, parents signed in, invoices\n-- sent, messages flowing. Counts only, never names: a school's people are the\n-- school's data (0019).\n-- ============================================================================\n\nalter table studio add column pilot_cohort text;\nalter table studio add column pilot_started_on date;\nalter table studio add column pilot_notes text;\n\ncreate or replace function app.platform_activation()\n  returns table (id uuid, name text, status text, pilot_cohort text, pilot_started_on date, days_in int,\n                 classes int, families int, parents_signed_in_pct int, registers_7d int, registers_28d int,\n                 invoices_sent int, messages_28d int, feedback_shared_28d int,\n                 setup_done boolean, families_in boolean, registers_weekly boolean, parents_on boolean,\n                 billing_on boolean, talking boolean, score int, stuck_on text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.require_platform_admin();\n  return query\n  with base as (\n    select s.id, s.name, s.status, s.pilot_cohort, s.pilot_started_on,\n           (current_date - coalesce(s.pilot_started_on, s.created_at::date))::int days_in,\n           (select count(*)::int from class c where c.studio_id = s.id and c.deleted_at is null) classes,\n           (select count(*)::int from family f where f.studio_id = s.id and f.deleted_at is null and not f.is_prospect) families,\n           (select round(100.0 * count(*) filter (where exists (select 1 from guardian g where g.family_id = f.id and g.user_id is not null and g.deleted_at is null))\n                    / nullif(count(*), 0))::int\n              from family f where f.studio_id = s.id and f.deleted_at is null and not f.is_prospect) parents_pct,\n           (select count(*)::int from class_session cs where cs.studio_id = s.id and cs.register_closed_at > now() - interval '7 days') reg7,\n           (select count(*)::int from class_session cs where cs.studio_id = s.id and cs.register_closed_at > now() - interval '28 days') reg28,\n           (select count(*)::int from invoice i where i.studio_id = s.id and i.deleted_at is null and i.status <> 'draft') invoices,\n           (select count(*)::int from communication c where c.studio_id = s.id and c.deleted_at is null and c.sent_at > now() - interval '28 days') msgs,\n           (select count(*)::int from feedback_note f where f.studio_id = s.id and f.shared_at > now() - interval '28 days') fb\n      from studio s where s.deleted_at is null\n  ), flags as (\n    select b.*, b.classes >= 3 setup, b.families >= 10 fam, b.reg7 >= 1 and b.reg28 >= 4 reg,\n           coalesce(b.parents_pct, 0) >= 50 parents, b.invoices >= 1 billing, b.msgs >= 4 talk\n      from base b\n  )\n  select f.id, f.name, f.status, f.pilot_cohort, f.pilot_started_on, f.days_in, f.classes, f.families, f.parents_pct,\n         f.reg7, f.reg28, f.invoices, f.msgs, f.fb, f.setup, f.fam, f.reg, f.parents, f.billing, f.talk,\n         (f.setup::int + f.fam::int + f.reg::int + f.parents::int + f.billing::int + f.talk::int) * 100 / 6,\n         case when not f.setup then 'Setting up classes' when not f.fam then 'Bringing families in'\n              when not f.reg then 'Taking registers each week' when not f.parents then 'Getting parents signed in'\n              when not f.billing then 'Sending invoices' when not f.talk then 'Messaging families' end\n    from flags f\n   order by f.pilot_cohort nulls last, f.name;\nend $$;\n\ncreate or replace function app.platform_set_pilot(p_studio uuid, p_cohort text, p_started date, p_notes text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.require_platform_admin();\n  update studio set pilot_cohort = nullif(btrim(p_cohort), ''), pilot_started_on = case when nullif(btrim(p_cohort), '') is null then null else coalesce(p_started, current_date) end,\n         pilot_notes = nullif(btrim(p_notes), ''), updated_at = now() where id = p_studio;\nend $$;\n\nrevoke all on function app.platform_activation(), app.platform_set_pilot(uuid, text, date, text) from public;\ngrant execute on function app.platform_activation(), app.platform_set_pilot(uuid, text, date, text) to authenticated;\n"},{name:"0037_themes.sql",sql:"-- ============================================================================\n-- 0037 · School themes: Classic or Urban, then the school's own colours\n-- ============================================================================\nalter table studio add column theme text not null default 'classic' check (theme in ('classic', 'urban'));\nalter table studio add column brand_secondary text check (brand_secondary is null or brand_secondary ~ '^#[0-9a-f]{6}$');\n\n-- The public page shows the school in its own theme too.\ndrop function if exists app.public_school(text);\ncreate function app.public_school(p_slug text)\n  returns table (name text, brand_colour text, logo_url text, open boolean, theme text, brand_secondary text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.name, s.brand_colour, s.logo_url, app.studio_writable(s.id), s.theme, s.brand_secondary\n    from studio s where s.slug = lower(p_slug) and s.deleted_at is null;\n$$;\nrevoke all on function app.public_school(text) from public;\ngrant execute on function app.public_school(text) to authenticated, anon;\n\n-- The switcher shows each school's look.\ndrop function if exists app.my_schools();\ncreate function app.my_schools()\n  returns table (studio_id uuid, name text, logo_url text, brand_colour text, roles text[], since timestamptz, theme text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id, s.name, s.logo_url, s.brand_colour, array_agg(distinct r order by r), min(x.since), s.theme\n    from (select m.studio_id, m.role::text r, m.created_at since from membership m where m.user_id = auth.uid() and m.deleted_at is null\n          union select g.studio_id, 'guardian', g.created_at from guardian g where g.user_id = auth.uid() and g.deleted_at is null\n          union select st.studio_id, 'student', st.created_at from student st where st.user_id = auth.uid() and st.login_enabled and st.deleted_at is null) x\n    join studio s on s.id = x.studio_id and s.deleted_at is null and app.studio_writable(s.id)\n   group by s.id order by min(x.since), s.name;\n$$;\ngrant execute on function app.my_schools() to authenticated;\n"},{name:"0038_column_guards.sql",sql:"-- ============================================================================\n-- 0038 · Column guards found by the second expert review (R-045, R-046)\n-- ----------------------------------------------------------------------------\n-- Row policies decide WHICH rows a person may update; they say nothing about\n-- WHICH COLUMNS. Two tables let people change columns that are not theirs:\n--\n--   studio  an owner could change their own plan, status, trial end and\n--           deletion date (R-045)\n--   family  a parent could overwrite the family's stored balance (R-046)\n--\n-- The guards below are SECURITY INVOKER on purpose. When a person updates a\n-- row directly, current_user is 'authenticated' and the guard applies. When\n-- a trusted database function does it (a platform action, a balance\n-- recalculation after a payment), current_user is that function's owner and\n-- the change goes through. So the rules live in the functions, as intended.\n-- ============================================================================\n\ncreate or replace function app.guard_studio_columns() returns trigger\n  language plpgsql security invoker set search_path = public, app, pg_temp as $$\nbegin\n  if current_user = 'authenticated' and (\n       new.id is distinct from old.id or new.slug is distinct from old.slug\n    or new.plan_id is distinct from old.plan_id or new.status is distinct from old.status\n    or new.status_reason is distinct from old.status_reason or new.trial_ends_on is distinct from old.trial_ends_on\n    or new.suspended_at is distinct from old.suspended_at or new.cancelled_at is distinct from old.cancelled_at\n    or new.data_deletion_due_on is distinct from old.data_deletion_due_on or new.currency is distinct from old.currency\n    or new.pilot_cohort is distinct from old.pilot_cohort or new.pilot_started_on is distinct from old.pilot_started_on\n    or new.pilot_notes is distinct from old.pilot_notes\n    or new.created_at is distinct from old.created_at or new.created_by is distinct from old.created_by\n    or new.deleted_at is distinct from old.deleted_at) then\n    raise exception 'FORBIDDEN: plan, account status and dates are managed by Swayvo' using errcode = 'insufficient_privilege';\n  end if;\n  return new;\nend $$;\ncreate trigger studio_column_guard before update on studio\n  for each row execute function app.guard_studio_columns();\n\ncreate or replace function app.guard_family_columns() returns trigger\n  language plpgsql security invoker set search_path = public, app, pg_temp as $$\nbegin\n  if current_user = 'authenticated' then\n    -- Nobody writes the balance directly: it is derived from invoices and payments.\n    if new.balance_minor is distinct from old.balance_minor then\n      raise exception 'FORBIDDEN: the balance is worked out from invoices and payments' using errcode = 'insufficient_privilege';\n    end if;\n    if not app.is_admin(old.studio_id) and (\n         new.studio_id is distinct from old.studio_id or new.is_prospect is distinct from old.is_prospect\n      or new.deleted_at is distinct from old.deleted_at or new.created_at is distinct from old.created_at) then\n      raise exception 'FORBIDDEN: only the office can change that' using errcode = 'insufficient_privilege';\n    end if;\n  end if;\n  return new;\nend $$;\ncreate trigger family_column_guard before update on family\n  for each row execute function app.guard_family_columns();\n"},{name:"0039_billing_periods.sql",sql:"-- ============================================================================\n-- 0039 · Monthly billing runs, family discounts, aged debt (R-050, R-056, R-055)\n-- ----------------------------------------------------------------------------\n-- Billing runs now cover a period: the term, or one month of it.\n--   · A term run bills term-priced and course-priced classes.\n--   · A month run bills monthly-priced classes for that month only, pro rata\n--     by sessions for a child who joins part-way through the month.\n-- Each line records the period it covers, so re-running a period raises\n-- nothing new — exactly as term runs already behaved.\n--\n-- Family discounts sit alongside the school-wide rules: a bursary or staff\n-- rate as a percentage (applied after the sibling/multi-class rule) or a\n-- fixed amount off each invoice. A bursary is shown to the family simply as\n-- \"Discount\", never with its reason.\n-- ============================================================================\n\nalter table invoice_item add column period_start date;\nalter table billing_run add column period_month date;\n\ncreate table family_discount (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  family_id   uuid not null references family(id) on delete cascade,\n  kind        text not null check (kind in ('percent', 'fixed')),\n  amount      integer not null check (amount > 0),            -- percent (1–100) or pence per invoice\n  reason      text not null check (reason in ('bursary', 'staff', 'loyalty', 'other')),\n  note        text,                                            -- office only\n  starts_on   date not null default current_date,\n  ends_on     date,\n  created_by  uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz,\n  check (kind <> 'percent' or amount <= 100),\n  check (ends_on is null or ends_on >= starts_on)\n);\nalter table family_discount enable row level security; alter table family_discount force row level security;\ncreate policy family_discount_admin on family_discount for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ngrant select, insert, update on family_discount to authenticated;\ngrant all on family_discount to service_role;\ncreate or replace function app.stamp_family_discount() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin select studio_id into new.studio_id from family where id = new.family_id; new.created_by := coalesce(new.created_by, auth.uid()); return new; end $$;\ncreate trigger family_discount_stamp before insert on family_discount for each row execute function app.stamp_family_discount();\n\n-- The discount a family has during a period (one of each kind at most counts).\ncreate or replace function app.family_discounts_on(p_family uuid, p_from date, p_to date)\n  returns table (pct int, fixed int)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(max(amount) filter (where kind = 'percent'), 0)::int, coalesce(max(amount) filter (where kind = 'fixed'), 0)::int\n    from family_discount where family_id = p_family and deleted_at is null\n     and starts_on <= p_to and (ends_on is null or ends_on >= p_from);\n$$;\n\ndrop function if exists app.billing_lines(uuid);\ncreate function app.billing_lines(p_term uuid, p_month date default null)\n  returns table (family_id uuid, family_name text, student_id uuid, student_name text,\n                 class_id uuid, class_name text, description text, quantity numeric,\n                 unit_minor int, discount_minor int, discount_reason text, period_start date)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; t term; m0 date; m1 date; pstart date;\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  if p_month is not null then\n    m0 := greatest(date_trunc('month', p_month)::date, t.starts_on);\n    m1 := least((date_trunc('month', p_month) + interval '1 month - 1 day')::date, t.ends_on);\n    if m0 > m1 then raise exception 'INVALID: that month is outside the term' using errcode = 'check_violation'; end if;\n    pstart := date_trunc('month', p_month)::date;\n  else\n    m0 := t.starts_on; m1 := t.ends_on; pstart := t.starts_on;\n  end if;\n  return query\n  with base as (\n    select f.id fam, f.name fname, s.id stu, s.first_name || ' ' || s.last_name sname,\n           c.id cls, c.name cname, c.pricing,\n           coalesce(e.price_minor, c.price_minor) price, greatest(e.started_on, m0) from_day,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null and cs.status <> 'cancelled'\n              and cs.starts_at::date between m0 and m1) total_sessions,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null and cs.status <> 'cancelled'\n              and cs.starts_at::date between greatest(e.started_on, m0) and m1) left_sessions\n      from enrolment e\n      join class c on c.id = e.class_id and c.deleted_at is null and c.term_id = t.id\n      join student s on s.id = e.student_id and s.deleted_at is null\n      join family f on f.id = s.family_id and f.deleted_at is null and not f.is_prospect\n     where e.deleted_at is null and e.status = 'active' and e.started_on <= m1\n       and coalesce(e.price_minor, c.price_minor) > 0\n       and (case when p_month is null then c.pricing in ('term', 'one_off') else c.pricing = 'monthly' end)\n       -- Already billed for this period.\n       and not exists (\n         select 1 from invoice_item ii join invoice i on i.id = ii.invoice_id\n          where ii.student_id = s.id and ii.class_id = c.id and ii.deleted_at is null\n            and i.deleted_at is null and i.status not in ('void', 'refunded') and i.term_id = t.id\n            and (p_month is null or ii.period_start = pstart))\n  ),\n  priced as (\n    select b.*, 1::numeric qty,\n      case when b.pricing in ('term', 'monthly') and b.from_day > m0 and b.total_sessions > 0\n           then round(b.price::numeric * b.left_sessions / b.total_sessions)::int else b.price end unit,\n      case when b.pricing = 'one_off' then b.cname || ' — course fee'\n           when b.from_day > m0 and b.total_sessions > 0\n             then format('%s — %s, %s of %s classes from %s', b.cname,\n                         case when p_month is null then t.name else to_char(pstart, 'FMMonth YYYY') end,\n                         b.left_sessions, b.total_sessions, to_char(b.from_day, 'FMDD Mon'))\n           else b.cname || ' — ' || case when p_month is null then t.name else to_char(pstart, 'FMMonth YYYY') end end descr\n      from base b\n  ),\n  ranked as (\n    select p.*,\n      dense_rank() over (partition by p.fam order by child_total desc, p.stu) child_rank,\n      row_number() over (partition by p.stu order by p.unit * p.qty desc, p.cls) class_rank\n      from (select p.*, sum(p.unit * p.qty) over (partition by p.stu) child_total from priced p) p\n  ),\n  rules as (\n    select (select percent from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_n,\n           (select percent from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_n\n  ),\n  disc as (\n    select r.*,\n      case when rules.sib_pct is not null and r.child_rank >= rules.sib_n then rules.sib_pct else 0 end sib,\n      case when rules.mc_pct is not null and r.class_rank >= rules.mc_n then rules.mc_pct else 0 end mc,\n      (select fd.pct from app.family_discounts_on(r.fam, m0, m1) fd) fam_pct\n      from ranked r, rules\n  )\n  select d.fam, d.fname, d.stu, d.sname, d.cls, d.cname, d.descr, d.qty, d.unit,\n         -- The rule first, then the family's own percentage on what remains.\n         round(d.unit * d.qty * (1 - (1 - greatest(d.sib, d.mc) / 100.0) * (1 - d.fam_pct / 100.0)))::int,\n         nullif(concat_ws(' + ',\n           case when greatest(d.sib, d.mc) = 0 then null\n                when d.sib >= d.mc then d.sib || '% sibling discount' else d.mc || '% multi-class discount' end,\n           case when d.fam_pct > 0 then d.fam_pct || '% discount' end), ''),\n         pstart\n    from disc d\n   order by d.fname, d.sname, d.cname;\nend $$;\n\ndrop function if exists app.create_billing_run(uuid, date);\ncreate function app.create_billing_run(p_term uuid, p_due date default null, p_month date default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; run uuid; fam record; inv uuid; n int := 0; tot bigint := 0; fixed int; pm date := date_trunc('month', p_month)::date; t term;\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  if not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if exists (select 1 from billing_run where term_id = p_term and status = 'draft' and period_month is not distinct from pm) then\n    raise exception 'INVALID: there is already a draft run for this period — issue or discard it first' using errcode = 'check_violation';\n  end if;\n  insert into billing_run (studio_id, term_id, due_on, created_by, period_month)\n  values (sid, p_term, coalesce(p_due, current_date + 14), auth.uid(), pm) returning id into run;\n\n  for fam in\n    select l.family_id, jsonb_agg(jsonb_build_object(\n             'kind', 'tuition', 'description', l.description, 'quantity', l.quantity,\n             'unit_minor', l.unit_minor, 'discount_minor', l.discount_minor,\n             'student_id', l.student_id, 'class_id', l.class_id)) items, min(l.period_start) ps\n      from app.billing_lines(p_term, pm) l group by l.family_id\n  loop\n    select fd.fixed into fixed from app.family_discounts_on(fam.family_id, coalesce(pm, t.starts_on),\n                                                         coalesce((pm + interval '1 month - 1 day')::date, t.ends_on)) fd;\n    inv := app.create_invoice(fam.family_id, fam.items, coalesce(p_due, current_date + 14), null,\n                              least(coalesce(fixed, 0), (select sum((x ->> 'unit_minor')::int * (x ->> 'quantity')::numeric - (x ->> 'discount_minor')::int)\n                                                          from jsonb_array_elements(fam.items) x)::int),\n                              false, p_term);\n    update invoice set billing_run_id = run where id = inv;\n    update invoice_item set period_start = fam.ps where invoice_id = inv;\n    n := n + 1;\n    tot := tot + (select total_minor from invoice where id = inv);\n  end loop;\n  if n = 0 then\n    delete from billing_run where id = run;\n    raise exception 'INVALID: everyone has already been invoiced for this period' using errcode = 'check_violation';\n  end if;\n  update billing_run set invoice_count = n, total_minor = tot where id = run;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'create', 'billing_run', run, n || ' draft invoices' || coalesce(' for ' || to_char(pm, 'FMMonth YYYY'), ''));\n  return run;\nend $$;\n\n-- Who owes what, by how long it has been owed (R-055).\ncreate or replace function app.aged_debt(p_studio uuid)\n  returns table (family_id uuid, family_name text, current_minor bigint, d31_60 bigint, d61_90 bigint, d90_plus bigint, total bigint)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.require_admin(p_studio);\n  return query\n  select f.id, f.name,\n         coalesce(sum(i.total_minor - i.paid_minor) filter (where current_date - i.due_on <= 30), 0)::bigint,\n         coalesce(sum(i.total_minor - i.paid_minor) filter (where current_date - i.due_on between 31 and 60), 0)::bigint,\n         coalesce(sum(i.total_minor - i.paid_minor) filter (where current_date - i.due_on between 61 and 90), 0)::bigint,\n         coalesce(sum(i.total_minor - i.paid_minor) filter (where current_date - i.due_on > 90), 0)::bigint,\n         sum(i.total_minor - i.paid_minor)::bigint\n    from invoice i join family f on f.id = i.family_id\n   where i.studio_id = p_studio and i.deleted_at is null and i.status in ('issued', 'part_paid', 'refunded')\n     and i.total_minor > i.paid_minor\n   group by f.id, f.name order by 7 desc;\nend $$;\n\nrevoke all on function app.billing_lines(uuid, date), app.create_billing_run(uuid, date, date), app.aged_debt(uuid),\n  app.family_discounts_on(uuid, date, date) from public;\ngrant execute on function app.billing_lines(uuid, date), app.create_billing_run(uuid, date, date), app.aged_debt(uuid) to authenticated;\n"},{name:"0040_public_safety_retention.sql",sql:"-- ============================================================================\n-- 0040 · Public forms, pay before use, retention completeness\n--        (R-048, R-049, R-052)\n-- ----------------------------------------------------------------------------\n-- Public forms\n--   · The form must confirm the visitor has read who collects their data and\n--     why (the school's privacy notice, linked from the form). Contact for\n--     news and offers is a separate, unticked choice.\n--   · A submission log limits each email and each network address to five\n--     public bookings an hour, and each school to 100. The hosted server\n--     route that fronts these functions passes the caller's address as\n--     `_ip`; the browser's own value is overwritten there.\n--\n-- Pay before use (school setting, off by default)\n--   · A class pack can be used once its invoice is paid, or while the family\n--     owes no more than the school's \"on account\" limit.\n--   · A drop-in with no pack needs the same: within the limit, or paid first.\n--   · A public adult booking is held for 30 minutes against its invoice and\n--     confirmed when the invoice is paid; an unpaid hold lapses.\n--\n-- Retention\n--   · Prospects: enquiries with no activity for 90 days (school-adjustable),\n--     and the prospect records made for their trials, are removed.\n--   · Financial: once every child in a family has been anonymised and the\n--     newest invoice is older than the financial period, the family and\n--     guardian names and contact details are replaced; amounts stay.\n--   · Closed safeguarding concerns: kept until the school sets a period from\n--     its safeguarding policy (often until the child is 25); then deleted.\n-- ============================================================================\n\n-- ── Public forms ───────────────────────────────────────────────────────────\nalter table studio add column privacy_notice_url text\n  check (privacy_notice_url is null or privacy_notice_url ~ '^https?://');\nalter table enquiry add column marketing_consent boolean not null default false;\nalter table guardian add column marketing_consent boolean not null default false;\n\ncreate table public_submission (\n  id         bigint generated always as identity primary key,\n  studio_id  uuid not null references studio(id) on delete cascade,\n  kind       text not null,\n  email      text,\n  ip         text,\n  at         timestamptz not null default now()\n);\ncreate index public_submission_recent on public_submission (studio_id, at);\nalter table public_submission enable row level security; alter table public_submission force row level security;\ngrant all on public_submission to service_role;   -- no user reads it\n\ncreate or replace function app.public_guard(p_studio uuid, p_kind text, p_form jsonb) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare em text := lower(btrim(p_form ->> 'contact_email')); v_ip text := nullif(btrim(p_form ->> '_ip'), '');\nbegin\n  em := coalesce(em, lower(btrim(p_form ->> 'email')));\n  if coalesce(p_form ->> 'privacy_ack', '') not in ('true', 't', 'yes', 'on') then\n    raise exception 'INVALID: please confirm you have read how the school uses your details' using errcode = 'check_violation';\n  end if;\n  delete from public_submission where at < now() - interval '1 day';\n  if (select count(*) from public_submission ps where ps.studio_id = p_studio and ps.at > now() - interval '1 hour'\n        and ((em is not null and ps.email = em) or (v_ip is not null and ps.ip = v_ip))) >= 5\n     or (select count(*) from public_submission where studio_id = p_studio and at > now() - interval '1 hour') >= 100 then\n    raise exception 'RATE_LIMITED: too many bookings in a short time — please try again later or call the school'\n      using errcode = 'check_violation';\n  end if;\n  insert into public_submission (studio_id, kind, email, ip) values (p_studio, p_kind, em, v_ip);\nend $$;\nrevoke all on function app.public_guard(uuid, text, jsonb) from public, authenticated, anon;\n\ndrop function if exists app.public_school(text);\ncreate function app.public_school(p_slug text)\n  returns table (name text, brand_colour text, logo_url text, open boolean, theme text, brand_secondary text, privacy_notice_url text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.name, s.brand_colour, s.logo_url, app.studio_writable(s.id), s.theme, s.brand_secondary, s.privacy_notice_url\n    from studio s where s.slug = lower(p_slug) and s.deleted_at is null;\n$$;\nrevoke all on function app.public_school(text) from public;\ngrant execute on function app.public_school(text) to authenticated, anon;\n\ncreate or replace function app.public_book_trial(p_slug text, p_session uuid, p_form jsonb) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; cs record; enq uuid; tid uuid; dob date;\nbegin\n  select * into st from studio where slug = lower(p_slug) and deleted_at is null;\n  if st.id is null or not app.studio_writable(st.id) then\n    raise exception 'NOT_FOUND: that school' using errcode = 'no_data_found';\n  end if;\n  if coalesce(p_form ->> 'website', '') <> '' then return 'ok'; end if;   -- quietly drop bots\n  if coalesce(btrim(p_form ->> 'contact_name'), '') = '' or coalesce(btrim(p_form ->> 'child_name'), '') = ''\n     or coalesce(btrim(p_form ->> 'contact_phone'), '') = '' or coalesce(p_form ->> 'contact_email', '') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n    raise exception 'INVALID: please give your name, email, a phone number and your child''s name' using errcode = 'check_violation';\n  end if;\n  dob := (p_form ->> 'child_dob')::date;\n  if dob is null or dob > current_date or dob < current_date - interval '100 years' then\n    raise exception 'INVALID: please check your child''s date of birth' using errcode = 'check_violation';\n  end if;\n  select s.id, s.class_id, c.trial_price_minor into cs\n    from app.public_trial_sessions(p_slug) p join class_session s on s.id = p.session_id\n    join class c on c.id = s.class_id where p.session_id = p_session;\n  if cs.id is null then\n    raise exception 'INVALID: that class is full or no longer open for trials — please pick another' using errcode = 'check_violation';\n  end if;\n  -- One booking per email per session, so a double-click is not two trials.\n  if exists (select 1 from trial t join enquiry e on e.id = t.enquiry_id\n              where t.session_id = cs.id and lower(e.contact_email) = lower(btrim(p_form ->> 'contact_email'))\n                and lower(e.child_name) = lower(btrim(p_form ->> 'child_name')) and t.deleted_at is null) then\n    return 'ok';\n  end if;\n  perform app.public_guard(st.id, 'trial', p_form);\n  insert into enquiry (studio_id, stage, contact_name, contact_email, contact_phone, child_name, child_dob,\n                       interest_class_id, source, marketing_consent)\n  values (st.id, 'trial_booked', btrim(p_form ->> 'contact_name'), lower(btrim(p_form ->> 'contact_email')),\n          btrim(p_form ->> 'contact_phone'), btrim(p_form ->> 'child_name'), dob, cs.class_id, 'website',\n          coalesce(p_form ->> 'marketing', '') in ('true', 't', 'yes', 'on'))\n  returning id into enq;\n  insert into trial (studio_id, class_id, session_id, enquiry_id, status, price_minor)\n  values (st.id, cs.class_id, cs.id, enq, 'booked', cs.trial_price_minor)\n  returning id into tid;\n  perform app.ensure_trial_student(tid);\n  return 'ok';\nend $$;\n\n-- ── Pay before use ─────────────────────────────────────────────────────────\nalter table studio add column pay_before_use boolean not null default false;\nalter table studio add column account_limit_minor integer not null default 0 check (account_limit_minor >= 0);\n\nalter table drop_in_booking drop constraint drop_in_booking_status_check;\nalter table drop_in_booking add constraint drop_in_booking_status_check check (status in ('booked', 'held', 'cancelled'));\nalter table drop_in_booking add column held_until timestamptz;\ndrop index drop_in_once;\ncreate unique index drop_in_once on drop_in_booking (session_id, student_id) where status in ('booked', 'held');\n\ncreate or replace function app.family_owed(p_family uuid) returns bigint\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(sum(total_minor - paid_minor), 0)::bigint from invoice\n   where family_id = p_family and deleted_at is null and status in ('issued', 'part_paid') and total_minor > paid_minor;\n$$;\n\n-- May this family take something worth p_extra now and pay later?\ncreate or replace function app.on_account_ok(p_family uuid, p_extra bigint) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select not st.pay_before_use or app.family_owed(f.id) + p_extra <= st.account_limit_minor\n    from family f join studio st on st.id = f.studio_id where f.id = p_family;\n$$;\n\n-- Lapsed holds give their place back and their invoice is voided.\ncreate or replace function app.expire_held_drop_ins() returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare b record; n int := 0;\nbegin\n  for b in update drop_in_booking set status = 'cancelled', cancelled_at = now()\n            where status = 'held' and held_until < now() returning invoice_id loop\n    n := n + 1;\n    if b.invoice_id is not null then\n      update invoice set status = 'void', voided_at = now(), void_reason = 'Unpaid booking hold lapsed'\n       where id = b.invoice_id and paid_minor = 0 and status = 'issued';\n      perform app.recalc_family_balance((select family_id from invoice where id = b.invoice_id));\n    end if;\n  end loop;\n  return n;\nend $$;\n\ncreate or replace function app.session_taken(p_session uuid) returns int\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select app.class_enrolled_count(cs.class_id)\n       + (select count(*)::int from trial t where t.session_id = cs.id and t.status = 'booked' and t.deleted_at is null)\n       + (select count(*)::int from drop_in_booking d where d.session_id = cs.id\n            and (d.status = 'booked' or (d.status = 'held' and d.held_until > now())))\n    from class_session cs where cs.id = p_session;\n$$;\n\n-- p_hold: a public booking that waits for payment instead of being refused.\ndrop function if exists app.book_drop_in_unchecked(uuid, uuid);\ncreate function app.book_drop_in_unchecked(p_session uuid, p_student uuid, p_hold boolean default false) returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; s student; pk pack_purchase; inv uuid; bid uuid; held boolean := false;\nbegin\n  perform app.expire_held_drop_ins();\n  select x.*, c.name cname, c.price_minor, c.pricing, c.capacity, c.studio_id sid into cs\n    from class_session x join class c on c.id = x.class_id where x.id = p_session and x.deleted_at is null;\n  select * into s from student where id = p_student and deleted_at is null;\n  if cs.id is null or s.id is null or s.studio_id <> cs.sid then raise exception 'NOT_FOUND: that class' using errcode = 'no_data_found'; end if;\n  if cs.pricing <> 'drop_in' then raise exception 'INVALID: % is booked by the term, not class by class', cs.cname using errcode = 'check_violation'; end if;\n  if cs.status <> 'scheduled' or cs.starts_at < now() then raise exception 'INVALID: that class is not open for booking' using errcode = 'check_violation'; end if;\n  if app.session_taken(cs.id) >= cs.capacity then raise exception 'INVALID: that class is full — try another date' using errcode = 'check_violation'; end if;\n  if exists (select 1 from drop_in_booking where session_id = cs.id and student_id = s.id and status in ('booked', 'held')) then\n    raise exception 'INVALID: % is already booked in', s.first_name using errcode = 'check_violation';\n  end if;\n  if not exists (select 1 from emergency_contact where student_id = s.id and deleted_at is null) then\n    raise exception 'INVALID: add an emergency contact for % first', s.first_name using errcode = 'check_violation';\n  end if;\n  -- A pack counts once paid, or while the family is within its limit.\n  select p.* into pk from pack_purchase p left join invoice i on i.id = p.invoice_id\n   where p.student_id = s.id and p.remaining > 0 and p.expires_on >= cs.starts_at::date\n     and (i.id is null or i.status = 'paid' or app.on_account_ok(s.family_id, 0))\n   order by p.expires_on limit 1 for update of p;\n  if pk.id is not null then\n    update pack_purchase set remaining = remaining - 1 where id = pk.id;\n  elsif cs.price_minor > 0 then\n    if not app.on_account_ok(s.family_id, cs.price_minor) then\n      if not p_hold then\n        raise exception 'INVALID: PAY_FIRST: please settle what is owed before booking more classes on account' using errcode = 'check_violation';\n      end if;\n      held := true;\n    end if;\n    inv := app.create_invoice_internal(s.family_id, jsonb_build_array(jsonb_build_object('kind', 'tuition',\n             'description', cs.cname || ' — ' || to_char(cs.starts_at, 'FMDD Mon') || ' — ' || s.first_name,\n             'quantity', 1, 'unit_minor', cs.price_minor, 'student_id', s.id, 'class_id', cs.class_id)),\n             case when held then current_date else cs.starts_at::date end, null, 0, true, null);\n  end if;\n  insert into drop_in_booking (studio_id, session_id, student_id, pack_purchase_id, invoice_id, price_minor, booked_by, status, held_until)\n  values (s.studio_id, cs.id, s.id, pk.id, inv, case when pk.id is null then cs.price_minor else 0 end, auth.uid(),\n          case when held then 'held' else 'booked' end, case when held then now() + interval '30 minutes' end)\n  returning id into bid;\n  return jsonb_build_object('id', bid, 'paid_with', case when held then 'hold' when pk.id is not null then 'pack' when inv is not null then 'invoice' else 'free' end,\n                            'invoice_id', inv, 'pack_left', case when pk.id is not null then pk.remaining - 1 end);\nend $$;\nrevoke all on function app.book_drop_in_unchecked(uuid, uuid, boolean) from public, authenticated, anon;\n\ncreate or replace function app.book_drop_in(p_session uuid, p_student uuid) returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not exists (select 1 from student s where s.id = p_student and s.deleted_at is null\n                   and (s.id in (select app.guardian_student_ids()) or app.is_admin(s.studio_id))) then\n    raise exception 'FORBIDDEN: not your dancer' using errcode = 'insufficient_privilege';\n  end if;\n  return app.book_drop_in_unchecked(p_session, p_student, false);\nend $$;\n\n-- Paying the invoice confirms a held place.\ncreate or replace function app.on_invoice_paid_confirm_hold() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.status = 'paid' and old.status <> 'paid' then\n    update drop_in_booking set status = 'booked', held_until = null where invoice_id = new.id and status = 'held';\n  end if;\n  return null;\nend $$;\ncreate trigger invoice_paid_confirm_hold after update of status on invoice\n  for each row execute function app.on_invoice_paid_confirm_hold();\n\ncreate or replace function app.public_adult_drop_in(p_slug text, p_session uuid, p_form jsonb) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; fam uuid; kid uuid; r jsonb;\nbegin\n  select * into st from studio where slug = lower(p_slug) and deleted_at is null;\n  if st.id is null or not app.studio_writable(st.id) then raise exception 'NOT_FOUND: that school' using errcode = 'no_data_found'; end if;\n  if coalesce(p_form ->> 'website', '') <> '' then return 'ok'; end if;\n  if coalesce(btrim(p_form ->> 'name'), '') = '' or coalesce(btrim(p_form ->> 'phone'), '') = ''\n     or coalesce(p_form ->> 'email', '') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' or coalesce(btrim(p_form ->> 'emergency_phone'), '') = '' then\n    raise exception 'INVALID: please give your name, email, phone and someone to ring in an emergency' using errcode = 'check_violation';\n  end if;\n  if not exists (select 1 from app.drop_in_sessions(st.id) d where d.session_id = p_session) then\n    raise exception 'INVALID: that class is full or no longer open — please pick another' using errcode = 'check_violation';\n  end if;\n  perform app.public_guard(st.id, 'drop_in', p_form);\n  select g.family_id into fam from guardian g where g.studio_id = st.id and lower(g.email) = lower(btrim(p_form ->> 'email')) and g.deleted_at is null limit 1;\n  if fam is null then\n    insert into family (studio_id, name) values (st.id, regexp_replace(btrim(p_form ->> 'name'), '^.*\\s', '') || ' (adult)') returning id into fam;\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary, relationship, marketing_consent)\n    values (st.id, fam, btrim(p_form ->> 'name'), lower(btrim(p_form ->> 'email')), btrim(p_form ->> 'phone'), true, 'Self',\n            coalesce(p_form ->> 'marketing', '') in ('true', 't', 'yes', 'on'));\n    insert into student (studio_id, family_id, first_name, last_name, date_of_birth)\n    values (st.id, fam, split_part(btrim(p_form ->> 'name'), ' ', 1),\n            coalesce(nullif(regexp_replace(btrim(p_form ->> 'name'), '^\\S+\\s*', ''), ''), '—'),\n            coalesce((p_form ->> 'date_of_birth')::date, current_date - interval '30 years')) returning id into kid;\n    insert into emergency_contact (studio_id, student_id, full_name, phone, priority)\n    values (st.id, kid, coalesce(nullif(btrim(p_form ->> 'emergency_name'), ''), 'Emergency contact'), btrim(p_form ->> 'emergency_phone'), 1);\n  else\n    select id into kid from student where family_id = fam and deleted_at is null order by created_at limit 1;\n  end if;\n  r := app.book_drop_in_unchecked(p_session, kid, true);\n  return case when r ->> 'paid_with' = 'hold' then 'held' else 'ok' end;\nend $$;\n\n-- ── Retention ──────────────────────────────────────────────────────────────\nalter table retention_policy add column prospect_days smallint not null default 90 check (prospect_days between 30 and 730);\nalter table retention_policy add column concern_months smallint check (concern_months is null or concern_months between 12 and 600);\n\ndrop function if exists app.apply_retention(uuid, boolean);\ncreate function app.apply_retention(p_studio uuid, p_apply boolean default false)\n  returns table (step text, student_id uuid, who text, left_on date)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare pol retention_policy; r record;\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the owner runs data retention' using errcode = 'insufficient_privilege';\n  end if;\n  select * into pol from retention_policy where studio_id = p_studio;\n  for r in select s.id, s.first_name || ' ' || s.last_name as who, app.leaver_since(s.id) as since,\n                  exists (select 1 from medical_record m where m.student_id = s.id and m.deleted_at is null) as has_medical,\n                  s.first_name = 'Former' as anonymised\n             from student s join family f on f.id = s.family_id\n            where s.studio_id = p_studio and s.deleted_at is null and not f.is_prospect loop\n    continue when r.since is null;\n    if r.has_medical and r.since < current_date - make_interval(months => pol.medical_months) then\n      step := 'medical'; student_id := r.id; who := r.who; left_on := r.since; return next;\n      if p_apply then\n        delete from medical_record where medical_record.student_id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'medical_record', r.id, 'Medical record deleted: left ' || r.since);\n      end if;\n    end if;\n    if not r.anonymised and r.since < current_date - make_interval(months => pol.personal_months) then\n      step := 'anonymise'; student_id := r.id; who := r.who; left_on := r.since; return next;\n      if p_apply then\n        delete from emergency_contact where emergency_contact.student_id = r.id;\n        delete from consent_record where consent_record.student_id = r.id;\n        delete from student_reflection where student_reflection.student_id = r.id;\n        update feedback_note set private_note = null, going_well = null, work_on = null where feedback_note.student_id = r.id;\n        update student set first_name = 'Former', last_name = 'student',\n               date_of_birth = make_date(extract(year from date_of_birth)::int, 1, 1), user_id = null, login_enabled = false,\n               updated_at = now() where id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'student', r.id, 'Details anonymised: left ' || r.since);\n      end if;\n    end if;\n  end loop;\n\n  -- Prospects who never went further.\n  for r in select e.id, e.child_name, e.contact_name, greatest(e.updated_at, (select max(cs.starts_at) from trial t\n                  join class_session cs on cs.id = t.session_id where t.enquiry_id = e.id))::date last_seen\n             from enquiry e where e.studio_id = p_studio and e.deleted_at is null and e.stage <> 'enrolled' loop\n    continue when r.last_seen >= current_date - pol.prospect_days;\n    step := 'prospect'; student_id := null; who := coalesce(r.child_name, r.contact_name); left_on := r.last_seen; return next;\n    if p_apply then\n      delete from enquiry where id = r.id;\n      insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n      values (p_studio, auth.uid(), 'retention', 'enquiry', r.id, 'Enquiry removed: no activity since ' || r.last_seen);\n    end if;\n  end loop;\n  for r in select f.id, f.name, f.created_at::date made from family f\n            where f.studio_id = p_studio and f.deleted_at is null and f.is_prospect\n              and f.created_at < now() - make_interval(days => pol.prospect_days)\n              and not exists (select 1 from student s join trial t on t.student_id = s.id join class_session cs on cs.id = t.session_id\n                               where s.family_id = f.id and cs.starts_at > now() - make_interval(days => pol.prospect_days))\n              and not exists (select 1 from invoice i where i.family_id = f.id and i.deleted_at is null) loop\n    step := 'prospect'; student_id := null; who := r.name; left_on := r.made; return next;\n    if p_apply then\n      delete from emergency_contact where emergency_contact.student_id in (select id from student where family_id = r.id);\n      delete from medical_record where medical_record.student_id in (select id from student where family_id = r.id);\n      update student set first_name = 'Former', last_name = 'prospect', date_of_birth = make_date(extract(year from date_of_birth)::int, 1, 1),\n             deleted_at = now() where family_id = r.id;\n      update guardian set full_name = 'Former prospect', email = null, phone = null, user_id = null, deleted_at = now() where family_id = r.id;\n      update family set name = 'Former prospect', address_line1 = null, address_line2 = null, city = null, postcode = null,\n             notes = null, deleted_at = now() where id = r.id;\n      insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n      values (p_studio, auth.uid(), 'retention', 'family', r.id, 'Prospect record removed');\n    end if;\n  end loop;\n\n  -- Families whose children have all been anonymised and whose last invoice\n  -- is past the financial period.\n  for r in select f.id, f.name, (select max(coalesce(i.issued_on, i.created_at::date)) from invoice i where i.family_id = f.id) last_inv\n             from family f where f.studio_id = p_studio and f.deleted_at is null and not f.is_prospect and f.name <> 'Former family'\n              and exists (select 1 from student s where s.family_id = f.id)\n              and not exists (select 1 from student s where s.family_id = f.id and s.deleted_at is null and s.first_name <> 'Former') loop\n    continue when r.last_inv is not null and r.last_inv >= current_date - make_interval(months => pol.financial_months);\n    step := 'financial'; student_id := null; who := r.name; left_on := r.last_inv; return next;\n    if p_apply then\n      update guardian set full_name = 'Former guardian', email = null, phone = null, user_id = null where family_id = r.id;\n      update family set name = 'Former family', address_line1 = null, address_line2 = null, city = null, postcode = null, notes = null\n       where id = r.id;\n      insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n      values (p_studio, auth.uid(), 'retention', 'family', r.id, 'Family details anonymised; invoices kept');\n    end if;\n  end loop;\n\n  -- Closed safeguarding concerns, once the school has set a period.\n  if pol.concern_months is not null then\n    for r in select c.id, c.updated_at::date closed from safeguarding_concern c\n              where c.studio_id = p_studio and c.status = 'closed'\n                and c.updated_at < now() - make_interval(months => pol.concern_months) loop\n      step := 'concern'; student_id := null; who := 'Closed concern'; left_on := r.closed; return next;\n      if p_apply then\n        delete from safeguarding_concern where id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'safeguarding_concern', r.id, 'Closed concern deleted: closed ' || r.closed);\n      end if;\n    end loop;\n  end if;\n\n  if p_apply then update retention_policy set last_run_at = now() where studio_id = p_studio; end if;\nend $$;\n\ncreate or replace function app.tick() returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s record; auto int := 0; released int := 0; checks int := 0; holds int;\nbegin\n  holds := app.expire_held_drop_ins();\n  for s in select id from studio where deleted_at is null and app.studio_writable(id) loop\n    auto := auto + coalesce(app.run_automations(s.id), 0);\n    released := released + app.release_scheduled(s.id);\n    checks := checks + app.remind_staff_checks(s.id);\n    perform app.award_event_milestones(s.id);\n  end loop;\n  return jsonb_build_object('automations', auto, 'released', released, 'staff_checks', checks, 'holds_lapsed', holds, 'at', now());\nend $$;\n\nrevoke all on function app.family_owed(uuid), app.on_account_ok(uuid, bigint), app.expire_held_drop_ins(), app.apply_retention(uuid, boolean) from public;\nrevoke all on function app.expire_held_drop_ins() from authenticated, anon;\ngrant execute on function app.family_owed(uuid), app.on_account_ok(uuid, bigint) to authenticated;\ngrant execute on function app.apply_retention(uuid, boolean) to authenticated;\ngrant execute on function app.expire_held_drop_ins() to service_role;\n"},{name:"0041_threads_scope_digest_feed.sql",sql:"-- ============================================================================\n-- 0041 · Teacher threads, notifications per school, daily digest, calendar\n--        subscription (R-054, R-051, R-037, R-036)\n-- ----------------------------------------------------------------------------\n-- Teacher threads: a family replying to a teacher's message marks it as a\n-- reply. The teacher who wrote the original reads that reply (and can answer\n-- it); the office reads everything in the family's conversation as before.\n-- There is still no private channel: every message sits in the family's\n-- conversation with the studio.\n--\n-- Notifications follow the chosen school. People in two schools see a count\n-- for the other one instead, and switch to read it.\n--\n-- Digest: someone who prefers fewer emails gets one a day, at 5pm school\n-- time, listing what is new. Urgent notices (a class cancelled today, a\n-- safeguarding alert) still go straight away.\n--\n-- Calendar: each person can make a private subscription link. The link\n-- carries a random token, not who they are; making a new link retires the\n-- old one. The hosted server renders the feed (server/calendar-feed.mts)\n-- from app.calendar_feed().\n-- ============================================================================\n\n-- ── Teacher threads ────────────────────────────────────────────────────────\nalter table communication add column reply_to uuid references communication(id) on delete set null;\ncreate index communication_reply_to on communication (reply_to) where reply_to is not null;\n\n-- Messages a teacher wrote, through any number of replies, stay theirs to read.\ncreate or replace function app.my_thread_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with recursive t(id) as (\n    select c.id from communication c where c.kind = 'direct' and c.sent_by = auth.uid() and c.deleted_at is null\n       and app.in_scope(c.studio_id) and app.is_staff(c.studio_id)\n    union\n    select c.id from communication c join t on c.reply_to = t.id where c.deleted_at is null\n  )\n  select id from t;\n$$;\ncreate policy comm_teacher_thread on communication for select\n  using (deleted_at is null and kind = 'direct' and id in (select app.my_thread_ids()));\n\n-- The threads, with the family's name (teachers cannot read the family table).\ncreate or replace function app.my_threads()\n  returns table (id uuid, reply_to uuid, family_id uuid, family_name text, subject text, body text,\n                 sent_at timestamptz, inbound boolean, sender text, mine boolean)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id, c.reply_to, c.family_id, f.name, c.subject, c.body, c.sent_at, c.inbound,\n         app.sender_name(c.sent_by, c.studio_id), c.sent_by = auth.uid()\n    from communication c join family f on f.id = c.family_id\n   where c.id in (select app.my_thread_ids()) order by c.sent_at;\n$$;\n\n-- A family's reply must answer a message in their own conversation.\ncreate or replace function app.check_reply_to() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.reply_to is null then return new; end if;\n  if not exists (select 1 from communication p where p.id = new.reply_to and p.family_id is not distinct from new.family_id and p.kind = 'direct') then\n    raise exception 'INVALID: that reply does not belong to this conversation' using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\ncreate trigger communication_reply_check before insert on communication for each row execute function app.check_reply_to();\n\n-- The teacher hears about a reply.\ncreate or replace function app.on_reply_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p communication; fam text;\nbegin\n  if new.reply_to is null or not new.inbound then return null; end if;\n  select * into p from communication where id = new.reply_to;\n  if p.sent_by is null or not app.is_staff_user(p.sent_by, p.studio_id) or app.is_admin_user(p.sent_by, p.studio_id) then return null; end if;\n  select name into fam from family where id = new.family_id;\n  insert into notification (studio_id, user_id, kind, title, body, href)\n  values (new.studio_id, p.sent_by, 'message', 'Reply from the ' || coalesce(fam, 'family'), left(new.body, 140), '/teach/messages');\n  return null;\nend $$;\ncreate trigger communication_reply_notify after insert on communication for each row execute function app.on_reply_notify();\n\ncreate or replace function app.is_staff_user(p_user uuid, p_studio uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from membership m where m.user_id = p_user and m.studio_id = p_studio and m.deleted_at is null\n                   and m.role in ('owner', 'admin', 'teacher'));\n$$;\ncreate or replace function app.is_admin_user(p_user uuid, p_studio uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from membership m where m.user_id = p_user and m.studio_id = p_studio and m.deleted_at is null\n                   and m.role in ('owner', 'admin'));\n$$;\n\n-- A teacher answers a reply in the same thread.\ncreate or replace function app.teacher_reply(p_to uuid, p_body text) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r communication; mid uuid;\nbegin\n  select * into r from communication where id = p_to and deleted_at is null;\n  if r.id is null or not (r.id in (select app.my_thread_ids())) or not app.is_staff(r.studio_id) then\n    raise exception 'FORBIDDEN: you can answer replies to your own messages' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_body), '') = '' then raise exception 'INVALID: a message needs something in it' using errcode = 'check_violation'; end if;\n  insert into communication (studio_id, kind, family_id, subject, body, sent_by, reply_to)\n  values (r.studio_id, 'direct', r.family_id, case when r.subject is null then null when r.subject ~ '^Re: ' then r.subject else 'Re: ' || r.subject end,\n          btrim(p_body), auth.uid(), r.id)\n  returning id into mid;\n  return mid;\nend $$;\n\n-- ── Notifications follow the chosen school ─────────────────────────────────\ndrop policy notification_own on notification;\ncreate policy notification_own on notification for select\n  using (deleted_at is null and user_id = auth.uid() and app.in_scope(studio_id));\ndrop policy notification_own_update on notification;\ncreate policy notification_own_update on notification for update\n  using (user_id = auth.uid() and app.in_scope(studio_id)) with check (user_id = auth.uid());\n\ncreate or replace function app.other_school_notifications()\n  returns table (studio_id uuid, name text, unread int)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select n.studio_id, s.name, count(*)::int from notification n join studio s on s.id = n.studio_id\n   where n.user_id = auth.uid() and n.deleted_at is null and n.read_at is null and not app.in_scope(n.studio_id)\n   group by n.studio_id, s.name order by s.name;\n$$;\n\n-- ── Daily digest ───────────────────────────────────────────────────────────\nalter table user_account add column email_digest boolean not null default false;\nalter table user_account add column last_digest_at timestamptz;\n\ncreate or replace function app.set_email_digest(p_on boolean) returns void\n  language sql security definer set search_path = public, app, pg_temp as $$\n  update user_account set email_digest = p_on, last_digest_at = coalesce(last_digest_at, now()) where id = auth.uid();\n$$;\n\ncreate or replace function app.on_notification_email() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare u user_account; urgent boolean;\nbegin\n  if current_setting('app.quiet', true) = 'on' then return null; end if;\n  select * into u from user_account where id = new.user_id and deleted_at is null;\n  if u.id is null or coalesce(u.email, '') !~ '@' then return null; end if;\n  if not app.wants(new.user_id, new.kind, 'email') then return null; end if;\n  urgent := new.kind in ('schedule_change', 'safeguarding') and new.title ~* '^(cancelled|urgent)';\n  if u.email_digest and not urgent then return null; end if;      -- waits for the day's digest\n  insert into outbound_message (studio_id, channel, to_name, to_address, subject, body, user_id, notification_id, not_before)\n  values (new.studio_id, 'email', u.full_name, u.email, new.title,\n          coalesce(new.body, '') || E'\\n\\nOpen Swayvo to see more.', u.id, new.id,\n          case when urgent then now() else app.after_quiet(u.id, new.studio_id) end);\n  return null;\nend $$;\n\n-- One email per person per school per day, from 5pm school time, listing\n-- what arrived since the last one and is still unread.\ncreate or replace function app.send_digests() returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r record; n int := 0;\nbegin\n  for r in\n    select u.id, u.full_name, u.email, x.studio_id, st.name school,\n           string_agg('• ' || x.title || coalesce(' — ' || left(x.body, 120), ''), E'\\n' order by x.created_at) lines, count(*) k\n      from user_account u\n      join notification x on x.user_id = u.id and x.deleted_at is null and x.read_at is null\n                          and x.created_at > coalesce(u.last_digest_at, now() - interval '1 day')\n      join studio st on st.id = x.studio_id\n     where u.email_digest and u.deleted_at is null and coalesce(u.email, '') ~ '@'\n       and (now() at time zone coalesce(st.timezone, 'Europe/London'))::time >= time '17:00'\n       and coalesce((u.last_digest_at at time zone coalesce(st.timezone, 'Europe/London'))::date, date '2000-01-01')\n           < (now() at time zone coalesce(st.timezone, 'Europe/London'))::date\n       and app.wants(u.id, x.kind, 'email')\n     group by u.id, u.full_name, u.email, x.studio_id, st.name\n  loop\n    insert into outbound_message (studio_id, channel, to_name, to_address, subject, body, user_id, not_before)\n    values (r.studio_id, 'email', r.full_name, r.email, r.school || ': ' || r.k || ' update' || case when r.k = 1 then '' else 's' end || ' today',\n            'Here is what is new today:' || E'\\n\\n' || r.lines || E'\\n\\nOpen Swayvo to see more. You chose one email a day; change this in your notification settings.',\n            r.id, app.after_quiet(r.id, r.studio_id));\n    update user_account set last_digest_at = now() where id = r.id;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\ncreate or replace function app.tick() returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s record; auto int := 0; released int := 0; checks int := 0; holds int; digests int;\nbegin\n  holds := app.expire_held_drop_ins();\n  for s in select id from studio where deleted_at is null and app.studio_writable(id) loop\n    auto := auto + coalesce(app.run_automations(s.id), 0);\n    released := released + app.release_scheduled(s.id);\n    checks := checks + app.remind_staff_checks(s.id);\n    perform app.award_event_milestones(s.id);\n  end loop;\n  digests := app.send_digests();\n  return jsonb_build_object('automations', auto, 'released', released, 'staff_checks', checks,\n                            'holds_lapsed', holds, 'digests', digests, 'at', now());\nend $$;\n\n-- ── Calendar subscription ─────────────────────────────────────────────────\ncreate table calendar_token (\n  token      text primary key,\n  user_id    uuid not null references user_account(id) on delete cascade,\n  studio_id  uuid not null references studio(id) on delete cascade,\n  role       text not null,\n  created_at timestamptz not null default now(),\n  revoked_at timestamptz,\n  last_used_at timestamptz\n);\ncreate unique index calendar_token_live on calendar_token (user_id, studio_id) where revoked_at is null;\nalter table calendar_token enable row level security; alter table calendar_token force row level security;\ncreate policy calendar_token_own on calendar_token for select using (user_id = auth.uid() and revoked_at is null);\ngrant select on calendar_token to authenticated;\ngrant all on calendar_token to service_role;\n\n-- A new link (and the old one stops working).\ncreate or replace function app.issue_calendar_token(p_studio uuid) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare tok text; r text;\nbegin\n  r := case when app.is_staff(p_studio) then 'staff'\n            when exists (select 1 from guardian g where g.user_id = auth.uid() and g.studio_id = p_studio and g.deleted_at is null) then 'guardian'\n            when exists (select 1 from student s where s.user_id = auth.uid() and s.studio_id = p_studio and s.deleted_at is null) then 'student' end;\n  if auth.uid() is null or r is null then raise exception 'FORBIDDEN: not a member of that school' using errcode = 'insufficient_privilege'; end if;\n  update calendar_token set revoked_at = now() where user_id = auth.uid() and studio_id = p_studio and revoked_at is null;\n  tok := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');\n  insert into calendar_token (token, user_id, studio_id, role) values (tok, auth.uid(), p_studio, r);\n  return tok;\nend $$;\n\ncreate or replace function app.revoke_calendar_token(p_studio uuid) returns void\n  language sql security definer set search_path = public, app, pg_temp as $$\n  update calendar_token set revoked_at = now() where user_id = auth.uid() and studio_id = p_studio and revoked_at is null;\n$$;\n\n-- The feed: the next 120 days and the last 14, cancellations included so a\n-- calendar app can mark them. Only ever what that person could see in the app.\ncreate or replace function app.calendar_feed(p_token text)\n  returns table (uid text, title text, starts_at timestamptz, ends_at timestamptz, location text, status text, description text, calendar_name text)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t calendar_token; sname text;\nbegin\n  select * into t from calendar_token where token = p_token and revoked_at is null;\n  if t.token is null then raise exception 'NOT_FOUND: that calendar link has been replaced or turned off' using errcode = 'no_data_found'; end if;\n  update calendar_token set last_used_at = now() where token = p_token;\n  select name into sname from studio where id = t.studio_id;\n  return query\n  with mine as (\n    -- Staff: classes they teach or cover.\n    select cs.id sid, null::text who from class_session cs join class c on c.id = cs.class_id\n      join staff_member sm on sm.id = coalesce(cs.teacher_id, c.teacher_id)\n     where t.role = 'staff' and sm.user_id = t.user_id and c.studio_id = t.studio_id\n    union\n    -- Families: each child's classes, and their drop-ins.\n    select cs.id, s.first_name from class_session cs join enrolment e on e.class_id = cs.class_id and e.status = 'active' and e.deleted_at is null\n      join student s on s.id = e.student_id and s.deleted_at is null\n      join guardian g on g.family_id = s.family_id and g.user_id = t.user_id and g.deleted_at is null\n     where t.role = 'guardian' and s.studio_id = t.studio_id\n    union\n    select d.session_id, s.first_name from drop_in_booking d join student s on s.id = d.student_id\n      join guardian g on g.family_id = s.family_id and g.user_id = t.user_id and g.deleted_at is null\n     where t.role = 'guardian' and d.status = 'booked' and s.studio_id = t.studio_id\n    union\n    select cs.id, null from class_session cs join enrolment e on e.class_id = cs.class_id and e.status = 'active' and e.deleted_at is null\n      join student s on s.id = e.student_id and s.user_id = t.user_id and s.deleted_at is null\n     where t.role = 'student' and s.studio_id = t.studio_id\n  )\n  select cs.id::text || '@sanaa', c.name || coalesce(' — ' || string_agg(distinct m.who, ', '), ''),\n         cs.starts_at, cs.ends_at, coalesce(r.name || ', ', '') || coalesce(l.name, ''),\n         case when cs.status = 'cancelled' then 'CANCELLED' else 'CONFIRMED' end,\n         case when cs.status = 'cancelled' then 'This class is cancelled.' else null end, sname\n    from mine m join class_session cs on cs.id = m.sid and cs.deleted_at is null\n    join class c on c.id = cs.class_id\n    left join room r on r.id = coalesce(cs.room_id, c.room_id)\n    left join location l on l.id = c.location_id\n   where cs.starts_at between now() - interval '14 days' and now() + interval '120 days'\n   group by cs.id, c.name, cs.starts_at, cs.ends_at, r.name, l.name, cs.status\n   order by cs.starts_at;\nend $$;\n\nrevoke all on function app.my_thread_ids(), app.my_threads(), app.teacher_reply(uuid, text), app.other_school_notifications(),\n  app.set_email_digest(boolean), app.send_digests(), app.issue_calendar_token(uuid), app.revoke_calendar_token(uuid),\n  app.calendar_feed(text), app.is_staff_user(uuid, uuid), app.is_admin_user(uuid, uuid) from public;\ngrant execute on function app.my_thread_ids(), app.my_threads(), app.teacher_reply(uuid, text), app.other_school_notifications(),\n  app.set_email_digest(boolean), app.issue_calendar_token(uuid), app.revoke_calendar_token(uuid) to authenticated;\ngrant execute on function app.calendar_feed(text) to anon, authenticated, service_role;\ngrant execute on function app.send_digests() to service_role;\n"},{name:"0042_exams_events_practice.sql",sql:"-- ============================================================================\n-- 0042 · Exams, show depth, practice (R-058, R-057, R-059)\n-- ----------------------------------------------------------------------------\n-- Exams: a school records an exam session (board, date, venue, fee) and\n-- enters children for a grade. Grade names are typed by the school — no\n-- syllabus text is copied. Results arrive as a band (pass, merit,\n-- distinction…) and an optional mark; a pass becomes a milestone. Fees go\n-- on the family's account in one step.\n--\n-- Shows: costume items with each dancer's size and where the costume is;\n-- a register for rehearsals with medical markers; a printable programme that\n-- names a child only with their family's photography consent; and audience\n-- tickets, which families book against an invoice (card payment comes with\n-- the payments module).\n--\n-- Practice: a student (or their parent) logs practice; their teachers see a\n-- weekly total. A teacher or the office can attach a demonstration link to a\n-- skill. Students never upload video.\n-- ============================================================================\n\n-- ── Exams ──────────────────────────────────────────────────────────────────\ncreate table exam_session (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  board       text not null,                         -- RAD, ISTD, IDTA, BTDA, or the school's own\n  title       text not null,\n  exam_on     date not null,\n  venue       text,\n  entries_close_on date,\n  created_by  uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\ncreate table exam_entry (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  session_id  uuid not null references exam_session(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  grade       text not null,                         -- \"Grade 3\", \"Intermediate Foundation\"…\n  framework_id uuid references skill_framework(id) on delete set null,\n  fee_minor   integer not null default 0 check (fee_minor >= 0),\n  status      text not null default 'entered' check (status in ('entered', 'withdrawn', 'sat')),\n  result      text check (result is null or result in ('distinction', 'merit', 'pass', 'commended', 'highly_commended', 'not_yet')),\n  mark        smallint check (mark is null or mark between 0 and 100),\n  certificate_received boolean not null default false,\n  invoice_id  uuid references invoice(id) on delete set null,\n  entered_by  uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now(),\n  unique (session_id, student_id, grade)\n);\nalter table exam_session enable row level security; alter table exam_session force row level security;\nalter table exam_entry enable row level security;   alter table exam_entry force row level security;\ncreate policy exam_session_read on exam_session for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy exam_session_admin on exam_session for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy exam_entry_read on exam_entry for select using (\n  app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()) or student_id = app.student_self_id()\n  or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids())));\ngrant select, insert, update on exam_session to authenticated;\ngrant select on exam_entry to authenticated;\ngrant all on exam_session, exam_entry to service_role;\ncreate or replace function app.stamp_exam_session() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin new.created_by := coalesce(new.created_by, auth.uid()); return new; end $$;\ncreate trigger exam_session_stamp before insert on exam_session for each row execute function app.stamp_exam_session();\n\n-- Teachers enter children they teach; the office anyone.\ncreate or replace function app.enter_exam(p_session uuid, p_student uuid, p_grade text, p_fee int default 0, p_framework uuid default null) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare x exam_session; s student; eid uuid;\nbegin\n  select * into x from exam_session where id = p_session and deleted_at is null;\n  select * into s from student where id = p_student and deleted_at is null;\n  if x.id is null or s.id is null or s.studio_id <> x.studio_id then raise exception 'NOT_FOUND: that exam' using errcode = 'no_data_found'; end if;\n  if not (app.is_admin(x.studio_id) or (app.has_role(x.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))) then\n    raise exception 'FORBIDDEN: you can enter children you teach' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_grade), '') = '' then raise exception 'INVALID: which grade?' using errcode = 'check_violation'; end if;\n  if x.entries_close_on is not null and x.entries_close_on < current_date and not app.is_admin(x.studio_id) then\n    raise exception 'INVALID: entries for this exam have closed — ask the office' using errcode = 'check_violation';\n  end if;\n  insert into exam_entry (studio_id, session_id, student_id, grade, fee_minor, framework_id, entered_by)\n  values (x.studio_id, x.id, s.id, btrim(p_grade), greatest(coalesce(p_fee, 0), 0), p_framework, auth.uid())\n  on conflict (session_id, student_id, grade) do update set status = 'entered' returning id into eid;\n  perform app.notify_family(s.family_id, 'milestone', s.first_name || ' is entered for ' || x.board || ' ' || btrim(p_grade),\n                            to_char(x.exam_on, 'FMDay DD FMMonth') || coalesce(' at ' || x.venue, ''), '/family/children');\n  return eid;\nend $$;\n\ncreate or replace function app.exam_result(p_entry uuid, p_result text, p_mark int default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare e exam_entry; x exam_session; s student;\nbegin\n  select * into e from exam_entry where id = p_entry;\n  select * into x from exam_session where id = e.session_id;\n  select * into s from student where id = e.student_id;\n  if e.id is null or not (app.is_admin(e.studio_id) or (app.has_role(e.studio_id, 'teacher') and e.student_id in (select app.teacher_student_ids()))) then\n    raise exception 'FORBIDDEN: not your student' using errcode = 'insufficient_privilege';\n  end if;\n  update exam_entry set result = p_result, mark = p_mark, status = 'sat' where id = e.id;\n  if p_result is not null and p_result <> 'not_yet' then\n    perform app.award_milestone(s.id, 'exam:' || lower(x.board) || ':' || lower(e.grade),\n      x.board || ' ' || e.grade || ' — ' || initcap(replace(p_result, '_', ' ')), x.exam_on);\n  end if;\nend $$;\n\ncreate or replace function app.withdraw_exam(p_entry uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare e exam_entry;\nbegin\n  select * into e from exam_entry where id = p_entry;\n  if e.id is null or not (app.is_admin(e.studio_id) or (app.has_role(e.studio_id, 'teacher') and e.student_id in (select app.teacher_student_ids()))) then\n    raise exception 'FORBIDDEN: not your student' using errcode = 'insufficient_privilege';\n  end if;\n  update exam_entry set status = 'withdrawn' where id = e.id;\nend $$;\n\n-- One invoice per family for the session's fees, once each.\ncreate or replace function app.bill_exam(p_session uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare x exam_session; f record; inv uuid; n int := 0;\nbegin\n  select * into x from exam_session where id = p_session;\n  perform app.require_admin(x.studio_id);\n  for f in select s.family_id, jsonb_agg(jsonb_build_object('kind', 'exam_fee', 'description', x.board || ' ' || e.grade || ' — ' || s.first_name,\n                    'quantity', 1, 'unit_minor', e.fee_minor, 'student_id', s.id)) items, array_agg(e.id) ids\n             from exam_entry e join student s on s.id = e.student_id\n            where e.session_id = x.id and e.status <> 'withdrawn' and e.invoice_id is null and e.fee_minor > 0\n            group by s.family_id loop\n    inv := app.create_invoice(f.family_id, f.items, greatest(coalesce(x.entries_close_on, current_date + 14), current_date + 7), null, 0, true, null);\n    update exam_entry set invoice_id = inv where id = any(f.ids);\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- ── Shows: costumes ────────────────────────────────────────────────────────\ncreate table costume_item (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  event_id    uuid not null references studio_event(id) on delete cascade,\n  routine_id  uuid references event_routine(id) on delete cascade,\n  name        text not null,\n  sizes       text[] not null default array['Age 3–4', 'Age 5–6', 'Age 7–8', 'Age 9–10', 'Age 11–12', 'Age 13+', 'Adult S', 'Adult M', 'Adult L'],\n  price_minor integer not null default 0 check (price_minor >= 0),\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\ncreate table costume_order (\n  item_id     uuid not null references costume_item(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  size        text,\n  status      text not null default 'needed' check (status in ('needed', 'ordered', 'arrived', 'given', 'returned')),\n  note        text,\n  updated_at  timestamptz not null default now(),\n  primary key (item_id, student_id)\n);\nalter table costume_item enable row level security;  alter table costume_item force row level security;\nalter table costume_order enable row level security; alter table costume_order force row level security;\ncreate policy costume_item_read on costume_item for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy costume_item_admin on costume_item for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy costume_order_read on costume_order for select using (\n  student_id in (select app.guardian_student_ids())\n  or exists (select 1 from costume_item i where i.id = item_id and app.is_staff(i.studio_id)));\ncreate policy costume_order_admin on costume_order for all\n  using (exists (select 1 from costume_item i where i.id = item_id and app.is_admin(i.studio_id)))\n  with check (exists (select 1 from costume_item i where i.id = item_id and app.is_admin(i.studio_id)));\ngrant select, insert, update on costume_item to authenticated;\ngrant select, insert, update, delete on costume_order to authenticated;\ngrant all on costume_item, costume_order to service_role;\ncreate trigger costume_item_stamp before insert on costume_item for each row execute function app.stamp_event_child();\n\n-- Who needs what: every dancer in the routine (or, with no routine, every\n-- confirmed dancer in the show) gets a line.\ncreate or replace function app.costume_list(p_event uuid)\n  returns table (item_id uuid, item text, routine text, student_id uuid, dancer text, size text, status text, sizes text[])\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare ev studio_event;\nbegin\n  select * into ev from studio_event where id = p_event;\n  if not app.is_staff(ev.studio_id) then raise exception 'FORBIDDEN: staff only' using errcode = 'insufficient_privilege'; end if;\n  return query\n  select i.id, i.name, r.title, s.id, s.first_name || ' ' || s.last_name, o.size, coalesce(o.status, 'needed'), i.sizes\n    from costume_item i\n    left join event_routine r on r.id = i.routine_id\n    join student s on s.id in (\n      select rd.student_id from routine_dancer rd where rd.routine_id = i.routine_id\n      union select p.student_id from event_participant p where i.routine_id is null and p.event_id = i.event_id\n             and p.status = 'confirmed' and p.deleted_at is null)\n    left join costume_order o on o.item_id = i.id and o.student_id = s.id\n   where i.event_id = p_event and i.deleted_at is null\n   order by i.name, s.first_name, s.last_name;\nend $$;\n\n-- A parent gives their child's size; the office tracks the rest.\ncreate or replace function app.set_costume_size(p_item uuid, p_student uuid, p_size text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare i costume_item;\nbegin\n  select * into i from costume_item where id = p_item and deleted_at is null;\n  if i.id is null or not (p_student in (select app.guardian_student_ids()) or app.is_admin(i.studio_id)) then\n    raise exception 'FORBIDDEN: not your dancer' using errcode = 'insufficient_privilege';\n  end if;\n  if p_size is not null and not (p_size = any(i.sizes)) then raise exception 'INVALID: choose one of the sizes listed' using errcode = 'check_violation'; end if;\n  insert into costume_order (item_id, student_id, size) values (i.id, p_student, p_size)\n  on conflict (item_id, student_id) do update set size = excluded.size, updated_at = now();\nend $$;\n\n-- ── Shows: rehearsal registers ─────────────────────────────────────────────\ncreate table rehearsal_attendance (\n  rehearsal_id uuid not null references studio_event(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  status       attendance_status not null,\n  marked_by    uuid references user_account(id) on delete set null,\n  marked_at    timestamptz not null default now(),\n  primary key (rehearsal_id, student_id)\n);\nalter table rehearsal_attendance enable row level security; alter table rehearsal_attendance force row level security;\ncreate policy rehearsal_attendance_read on rehearsal_attendance for select using (\n  student_id in (select app.guardian_student_ids())\n  or exists (select 1 from studio_event e where e.id = rehearsal_id and app.is_staff(e.studio_id)));\ngrant select on rehearsal_attendance to authenticated;\ngrant all on rehearsal_attendance to service_role;\n\ncreate or replace function app.rehearsal_register(p_rehearsal uuid)\n  returns table (student_id uuid, first_name text, last_name text, routines text, status attendance_status,\n                 has_medical boolean, requires_alert boolean)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare r studio_event;\nbegin\n  select * into r from studio_event where id = p_rehearsal and parent_event_id is not null and deleted_at is null;\n  if r.id is null then raise exception 'NOT_FOUND: that rehearsal' using errcode = 'no_data_found'; end if;\n  if not app.is_staff(r.studio_id) then raise exception 'FORBIDDEN: staff only' using errcode = 'insufficient_privilege'; end if;\n  return query\n  select s.id, coalesce(s.preferred_name, s.first_name), s.last_name,\n         (select string_agg(rt.title, ', ' order by rt.position) from event_routine rt join routine_dancer rd on rd.routine_id = rt.id\n           where rt.event_id = r.parent_event_id and rd.student_id = s.id and rt.deleted_at is null),\n         ra.status,\n         exists (select 1 from medical_record m where m.student_id = s.id and m.deleted_at is null),\n         coalesce((select bool_or(m.requires_alert) from medical_record m where m.student_id = s.id and m.deleted_at is null), false)\n    from event_participant p join student s on s.id = p.student_id and s.deleted_at is null\n    left join rehearsal_attendance ra on ra.rehearsal_id = r.id and ra.student_id = s.id\n   where p.event_id = r.parent_event_id and p.status = 'confirmed' and p.deleted_at is null\n   order by s.first_name, s.last_name;\nend $$;\n\ncreate or replace function app.mark_rehearsal(p_rehearsal uuid, p_student uuid, p_status attendance_status) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r studio_event;\nbegin\n  select * into r from studio_event where id = p_rehearsal and parent_event_id is not null;\n  if r.id is null or not app.is_staff(r.studio_id) then raise exception 'FORBIDDEN: staff only' using errcode = 'insufficient_privilege'; end if;\n  if not exists (select 1 from event_participant p where p.event_id = r.parent_event_id and p.student_id = p_student and p.status = 'confirmed') then\n    raise exception 'INVALID: that dancer is not in this show' using errcode = 'check_violation';\n  end if;\n  insert into rehearsal_attendance (rehearsal_id, student_id, status, marked_by) values (r.id, p_student, p_status, auth.uid())\n  on conflict (rehearsal_id, student_id) do update set status = excluded.status, marked_by = excluded.marked_by, marked_at = now();\nend $$;\n\n-- ── Shows: programme ───────────────────────────────────────────────────────\n-- Names appear only with photography consent (the school's proxy for being\n-- identified at a public performance); otherwise the routine says how many\n-- other dancers are in it.\ncreate or replace function app.event_programme(p_event uuid)\n  returns table (running_order smallint, routine text, class_name text, dancers text, unnamed int)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare ev studio_event;\nbegin\n  select * into ev from studio_event where id = p_event and deleted_at is null;\n  if ev.id is null or not app.is_staff(ev.studio_id) then raise exception 'FORBIDDEN: staff only' using errcode = 'insufficient_privilege'; end if;\n  return query\n  select r.position, r.title, c.name,\n         string_agg(coalesce(s.preferred_name, s.first_name) || ' ' || left(s.last_name, 1) || '.', ', ' order by s.first_name)\n           filter (where app.has_consent(s.id, 'photography')),\n         (count(s.id) filter (where not app.has_consent(s.id, 'photography')))::int\n    from event_routine r left join class c on c.id = r.class_id\n    left join routine_dancer rd on rd.routine_id = r.id\n    left join student s on s.id = rd.student_id and s.deleted_at is null\n   where r.event_id = ev.id and r.deleted_at is null\n   group by r.id, r.position, r.title, c.name\n   order by r.position, r.title;\nend $$;\n\ncreate or replace function app.has_consent(p_student uuid, p_kind consent_kind) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce((select c.granted from consent_record c where c.student_id = p_student and c.kind = p_kind\n                    order by c.created_at desc limit 1), false);\n$$;\n\n-- ── Shows: audience tickets ────────────────────────────────────────────────\ncreate table ticket_type (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  event_id    uuid not null references studio_event(id) on delete cascade,\n  name        text not null,                         -- \"Adult\", \"Child\", \"Matinee — adult\"\n  price_minor integer not null check (price_minor >= 0),\n  capacity    integer check (capacity is null or capacity > 0),\n  per_family_max smallint not null default 6 check (per_family_max between 1 and 50),\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\ncreate table ticket_booking (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  ticket_type_id uuid not null references ticket_type(id) on delete cascade,\n  family_id   uuid not null references family(id) on delete cascade,\n  quantity    smallint not null check (quantity > 0),\n  invoice_id  uuid references invoice(id) on delete set null,\n  status      text not null default 'booked' check (status in ('booked', 'cancelled')),\n  booked_by   uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now()\n);\nalter table ticket_type enable row level security;    alter table ticket_type force row level security;\nalter table ticket_booking enable row level security; alter table ticket_booking force row level security;\ncreate policy ticket_type_read on ticket_type for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy ticket_type_admin on ticket_type for all using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy ticket_booking_read on ticket_booking for select using (app.is_admin(studio_id) or family_id in (select app.guardian_family_ids()));\ngrant select, insert, update on ticket_type to authenticated;\ngrant select on ticket_booking to authenticated;\ngrant all on ticket_type, ticket_booking to service_role;\ncreate trigger ticket_type_stamp before insert on ticket_type for each row execute function app.stamp_event_child();\n\ncreate or replace function app.tickets_left(p_type uuid) returns int\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case when t.capacity is null then null\n              else t.capacity - coalesce((select sum(quantity) from ticket_booking b where b.ticket_type_id = t.id and b.status = 'booked'), 0) end::int\n    from ticket_type t where t.id = p_type;\n$$;\n\ncreate or replace function app.book_tickets(p_type uuid, p_quantity int) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t ticket_type; ev studio_event; fam uuid; had int; bid uuid; inv uuid;\nbegin\n  select * into t from ticket_type where id = p_type and deleted_at is null for update;\n  select * into ev from studio_event where id = t.event_id and deleted_at is null;\n  if t.id is null or ev.id is null or ev.starts_at < now() then raise exception 'INVALID: tickets for this show are not on sale' using errcode = 'check_violation'; end if;\n  select g.family_id into fam from guardian g where g.user_id = auth.uid() and g.studio_id = t.studio_id and g.deleted_at is null limit 1;\n  if fam is null then raise exception 'FORBIDDEN: tickets are booked by families of the school' using errcode = 'insufficient_privilege'; end if;\n  if coalesce(p_quantity, 0) < 1 then raise exception 'INVALID: how many tickets?' using errcode = 'check_violation'; end if;\n  select coalesce(sum(quantity), 0) into had from ticket_booking where ticket_type_id = t.id and family_id = fam and status = 'booked';\n  if had + p_quantity > t.per_family_max then\n    raise exception 'INVALID: up to % % tickets per family', t.per_family_max, lower(t.name) using errcode = 'check_violation';\n  end if;\n  if app.tickets_left(t.id) is not null and app.tickets_left(t.id) < p_quantity then\n    raise exception 'INVALID: only % left', app.tickets_left(t.id) using errcode = 'check_violation';\n  end if;\n  if t.price_minor > 0 then\n    inv := app.create_invoice_internal(fam, jsonb_build_array(jsonb_build_object('kind', 'show_fee',\n             'description', ev.title || ' — ' || p_quantity || ' × ' || t.name || ' ticket' || case when p_quantity = 1 then '' else 's' end,\n             'quantity', p_quantity, 'unit_minor', t.price_minor, 'event_id', ev.id)), least(ev.starts_at::date, current_date + 7), null, 0, true, null);\n  end if;\n  insert into ticket_booking (studio_id, ticket_type_id, family_id, quantity, invoice_id, booked_by)\n  values (t.studio_id, t.id, fam, p_quantity, inv, auth.uid()) returning id into bid;\n  return bid;\nend $$;\n\n-- ── Practice and demonstrations ────────────────────────────────────────────\nalter table framework_skill add column demo_url text check (demo_url is null or demo_url ~ '^https://');\n\ncreate table practice_log (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  student_id  uuid not null references student(id) on delete cascade,\n  practised_on date not null default current_date,\n  minutes     smallint not null check (minutes between 1 and 600),\n  what        text check (what is null or length(what) <= 200),\n  logged_by   uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now(),\n  check (practised_on <= current_date + 1)\n);\ncreate index practice_student on practice_log (student_id, practised_on desc);\nalter table practice_log enable row level security; alter table practice_log force row level security;\ncreate policy practice_read on practice_log for select using (\n  student_id = app.student_self_id() or student_id in (select app.guardian_student_ids()) or app.is_admin(studio_id)\n  or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids())));\ncreate policy practice_own_delete on practice_log for delete using (logged_by = auth.uid());\ngrant select, delete on practice_log to authenticated;\ngrant all on practice_log to service_role;\n\ncreate or replace function app.log_practice(p_student uuid, p_minutes int, p_what text default null, p_on date default current_date) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; pid uuid;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null or not (s.id = app.student_self_id() or s.id in (select app.guardian_student_ids())) then\n    raise exception 'FORBIDDEN: log practice for yourself or your own child' using errcode = 'insufficient_privilege';\n  end if;\n  insert into practice_log (studio_id, student_id, practised_on, minutes, what, logged_by)\n  values (s.studio_id, s.id, coalesce(p_on, current_date), p_minutes, nullif(btrim(p_what), ''), auth.uid()) returning id into pid;\n  return pid;\nend $$;\n\n-- Weekly totals for the children a teacher teaches (or the office: all).\ncreate or replace function app.practice_weekly(p_weeks int default 4)\n  returns table (student_id uuid, student_name text, week_start date, minutes int, sessions int)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id, s.first_name || ' ' || s.last_name, date_trunc('week', p.practised_on)::date, sum(p.minutes)::int, count(*)::int\n    from practice_log p join student s on s.id = p.student_id\n   where p.practised_on >= date_trunc('week', current_date)::date - (greatest(p_weeks, 1) - 1) * 7\n     and app.in_scope(p.studio_id)\n     and (app.is_admin(p.studio_id) or (app.has_role(p.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))\n          or s.id = app.student_self_id() or s.id in (select app.guardian_student_ids()))\n   group by s.id, s.first_name, s.last_name, 3\n   order by 3 desc, 2;\n$$;\n\n-- Teachers set a demonstration link on a skill in a framework they teach.\ncreate or replace function app.set_skill_demo(p_skill uuid, p_url text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare k framework_skill;\nbegin\n  select * into k from framework_skill where id = p_skill and deleted_at is null;\n  if k.id is null or not app.is_staff(k.studio_id) then raise exception 'FORBIDDEN: staff only' using errcode = 'insufficient_privilege'; end if;\n  if p_url is not null and p_url !~ '^https://' then raise exception 'INVALID: use a secure link (https://)' using errcode = 'check_violation'; end if;\n  update framework_skill set demo_url = nullif(btrim(p_url), ''), updated_at = now() where id = k.id;\nend $$;\n\nrevoke all on function app.enter_exam(uuid, uuid, text, int, uuid), app.exam_result(uuid, text, int), app.withdraw_exam(uuid),\n  app.bill_exam(uuid), app.costume_list(uuid), app.set_costume_size(uuid, uuid, text), app.rehearsal_register(uuid),\n  app.mark_rehearsal(uuid, uuid, attendance_status), app.event_programme(uuid), app.has_consent(uuid, consent_kind),\n  app.tickets_left(uuid), app.book_tickets(uuid, int), app.log_practice(uuid, int, text, date), app.practice_weekly(int),\n  app.set_skill_demo(uuid, text) from public;\ngrant execute on function app.enter_exam(uuid, uuid, text, int, uuid), app.exam_result(uuid, text, int), app.withdraw_exam(uuid),\n  app.bill_exam(uuid), app.costume_list(uuid), app.set_costume_size(uuid, uuid, text), app.rehearsal_register(uuid),\n  app.mark_rehearsal(uuid, uuid, attendance_status), app.event_programme(uuid), app.tickets_left(uuid), app.book_tickets(uuid, int),\n  app.log_practice(uuid, int, text, date), app.practice_weekly(int), app.set_skill_demo(uuid, text) to authenticated;\n"},{name:"0043_school_imagery.sql",sql:"-- ============================================================================\n-- 0043 · School imagery: a hero photo and a light logo (R-060)\n-- ----------------------------------------------------------------------------\n-- A hero photo for the public page and the family and student home screens,\n-- and an optional light version of the logo for the dark Urban style. Both\n-- are redrawn and compressed on the owner's device before they are stored,\n-- exactly as the logo is (0022), so only pixels are kept.\n-- ============================================================================\nalter table studio add column hero_url text check (\n  hero_url is null\n  or (hero_url ~ '^data:image/(jpeg|webp);base64,[A-Za-z0-9+/=]+$' and length(hero_url) <= 700000)\n  or hero_url ~ '^https://');\nalter table studio add column logo_light_url text check (\n  logo_light_url is null\n  or (logo_light_url ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' and length(logo_light_url) <= 400000)\n  or logo_light_url ~ '^https://');\n\ndrop function if exists app.public_school(text);\ncreate function app.public_school(p_slug text)\n  returns table (name text, brand_colour text, logo_url text, open boolean, theme text, brand_secondary text,\n                 privacy_notice_url text, hero_url text, logo_light_url text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.name, s.brand_colour, s.logo_url, app.studio_writable(s.id), s.theme, s.brand_secondary, s.privacy_notice_url,\n         s.hero_url, s.logo_light_url\n    from studio s where s.slug = lower(p_slug) and s.deleted_at is null;\n$$;\nrevoke all on function app.public_school(text) from public;\ngrant execute on function app.public_school(text) to authenticated, anon;\n"},{name:"0044_office_fixes.sql",sql:"-- ============================================================================\n-- 0044 · Office fixes from the end-user panel review\n-- ----------------------------------------------------------------------------\n--   UR-18  enquiry → trial → enrolment stay linked\n--   UR-19  waiting-list offers never promise more places than exist\n--   UR-35  a readable history of changes, and of who opened health records\n--   UR-39  a plan limit becomes a request to upgrade, not an error\n--   UR-53  onboarding knows whether a school holds sample data (UR-11)\n--   UR-54  trial outcomes wait for the trial (D9)\n--   UR-57  duplicate families found, merged with a full trail, and undone\n-- ============================================================================\n\n-- ── Settings ───────────────────────────────────────────────────────────────\n-- How long a family has to answer a waiting-list offer before it passes on.\nalter table studio add column waitlist_offer_days integer not null default 3\n  check (waitlist_offer_days between 1 and 30);\n-- True only for a school created with the demo's sample records.\nalter table studio add column sample_data boolean not null default false;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-19 · Waiting-list offers respect capacity\n-- ════════════════════════════════════════════════════════════════════════════\n-- A place is free when nobody holds it: not an active enrolment, and not an\n-- offer still waiting for an answer. Lapsed offers no longer hold a place even\n-- before the automation run marks them expired.\ncreate or replace function app.class_live_offers(p_class uuid, p_except uuid default null) returns integer\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select count(*)::int from waitlist_entry\n   where class_id = p_class and status = 'offered' and deleted_at is null\n     and (offer_expires_at is null or offer_expires_at > now())\n     and (p_except is null or id <> p_except)\n$$;\n\ncreate or replace function app.class_free_places(p_class uuid) returns integer\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce((select capacity from class where id = p_class), 0)\n         - app.class_enrolled_count(p_class) - app.class_live_offers(p_class)\n$$;\n\n-- Offering: only into a free place, for the school's chosen number of days.\ncreate or replace function app.offer_waitlist_place(p_id uuid, p_days integer default null)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare w record; days integer; out_now integer;\nbegin\n  select * into w from waitlist_entry\n   where id = p_id and status = 'waiting' and deleted_at is null;\n  if w.id is null then return false; end if;\n  if auth.uid() is not null and not app.is_admin(w.studio_id) then\n    raise exception 'FORBIDDEN: only the office may offer a place' using errcode = 'insufficient_privilege';\n  end if;\n  if app.class_free_places(w.class_id) <= 0 then\n    out_now := app.class_live_offers(w.class_id);\n    raise exception 'NO_FREE_PLACE: There is no free place to offer%.',\n      case when out_now = 1 then ' — 1 offer is already out'\n           when out_now > 1 then format(' — %s offers are already out', out_now)\n           else ': the class is full' end\n      using errcode = 'check_violation';\n  end if;\n  days := greatest(1, coalesce(p_days, (select waitlist_offer_days from studio where id = w.studio_id), 3));\n\n  update waitlist_entry\n     set status = 'offered', offered_at = now(),\n         offer_expires_at = now() + make_interval(days => days), updated_at = now()\n   where id = p_id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (w.studio_id, auth.uid(), 'offer', 'waitlist_entry', p_id,\n          format('place offered, expires in %s days', days));\n  return true;\nend $$;\n\n-- Offer the next free place, if there is one. Returns the entry offered.\ncreate or replace function app.offer_next_place(p_class uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare nxt uuid;\nbegin\n  if app.class_free_places(p_class) <= 0 then return null; end if;\n  select id into nxt from waitlist_entry\n   where class_id = p_class and status = 'waiting' and deleted_at is null\n   order by position limit 1;\n  if nxt is not null then perform app.offer_waitlist_place(nxt); end if;\n  return nxt;\nend $$;\n\ncreate or replace function app.withdraw_enrolment(p_id uuid, p_reason text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid;\nbegin\n  select studio_id, class_id into sid, cid\n    from enrolment where id = p_id and status = 'active' and deleted_at is null;\n  if sid is null then return null; end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may withdraw a place'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update enrolment\n     set status = 'left', ended_on = current_date,\n         note = coalesce(nullif(btrim(p_reason), ''), note), updated_at = now()\n   where id = p_id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'withdraw', 'enrolment', p_id, coalesce(p_reason, 'place given up'));\n\n  -- Offered only if the freed place is not already promised to someone.\n  return app.offer_next_place(cid);\nend $$;\n\n-- Taking a place: an offered family always fits, because its offer held the\n-- place. Taking one without an offer needs a place nobody else is holding.\ncreate or replace function app.accept_waitlist_place(p_id uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare w record; new_id uuid; held boolean;\nbegin\n  select * into w from waitlist_entry\n   where id = p_id and status in ('waiting','offered') and deleted_at is null;\n  if not found then return null; end if;\n  if not app.is_admin(w.studio_id) then\n    raise exception 'FORBIDDEN: only the office may accept a place'\n      using errcode = 'insufficient_privilege';\n  end if;\n  held := w.status = 'offered' and (w.offer_expires_at is null or w.offer_expires_at > now());\n  if not held and app.class_free_places(w.class_id) <= 0 then\n    raise exception 'NO_FREE_PLACE: There is no free place%.',\n      case when app.class_live_offers(w.class_id) > 0 then ' — the free places are held by families with an offer'\n           else ': the class is full' end\n      using errcode = 'check_violation';\n  end if;\n\n  insert into enrolment (studio_id, class_id, student_id, status, started_on, created_by, note)\n  values (w.studio_id, w.class_id, w.student_id, 'active', current_date, auth.uid(), 'From the waiting list')\n  returning id into new_id;\n\n  update waitlist_entry set status = 'accepted', responded_at = now(), updated_at = now() where id = p_id;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (w.studio_id, auth.uid(), 'accept', 'waitlist_entry', p_id, 'place taken up');\n  return new_id;\nend $$;\n\ncreate or replace function app.decline_waitlist_place(p_id uuid, p_note text default null)\n  returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid;\nbegin\n  select studio_id, class_id into sid, cid from waitlist_entry\n   where id = p_id and status in ('waiting','offered') and deleted_at is null;\n  if sid is null then return false; end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may close a waiting-list entry'\n      using errcode = 'insufficient_privilege';\n  end if;\n\n  update waitlist_entry\n     set status = 'declined', responded_at = now(),\n         note = coalesce(nullif(btrim(p_note), ''), note), updated_at = now()\n   where id = p_id;\n\n  perform app.offer_next_place(cid);\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'decline', 'waitlist_entry', p_id, 'place declined');\n  return true;\nend $$;\n\ncreate or replace function app.expire_waitlist_offers(p_studio uuid, p_now timestamptz default now())\n  returns integer\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare e record; n integer := 0;\nbegin\n  for e in select id, class_id from waitlist_entry\n            where studio_id = p_studio and status = 'offered' and deleted_at is null\n              and offer_expires_at is not null and offer_expires_at <= p_now\n  loop\n    update waitlist_entry set status = 'expired', responded_at = p_now where id = e.id;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (p_studio, auth.uid(), 'expire', 'waitlist_entry', e.id, 'offer lapsed unanswered');\n    n := n + 1;\n    perform app.offer_next_place(e.class_id);\n  end loop;\n  return n;\nend $$;\n\n-- A place held by an offer cannot be taken by a direct enrolment either, so\n-- the family that was offered it can always take it up.\ncreate or replace function app.enforce_capacity() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cap integer; taken integer; held integer;\nbegin\n  if new.status <> 'active' or new.deleted_at is not null then return new; end if;\n  if tg_op = 'UPDATE' and old.status = 'active' and old.class_id = new.class_id then\n    return new;\n  end if;\n  select capacity into cap from class where id = new.class_id;\n  if cap is null then return new; end if;\n  select count(*) into taken from enrolment\n   where class_id = new.class_id and status = 'active' and deleted_at is null and id <> new.id;\n  select count(*) into held from waitlist_entry\n   where class_id = new.class_id and status = 'offered' and deleted_at is null\n     and (offer_expires_at is null or offer_expires_at > now())\n     and student_id <> new.student_id;\n  if taken + held >= cap then\n    raise exception 'CLASS_FULL: class % is at capacity (%/%)%', new.class_id, taken + held, cap,\n      case when held > 0 then format(', %s held by an offer', held) else '' end\n      using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\n\n-- Who may be added to a class's waiting list, or enrolled: not already in it,\n-- not already waiting, with their age and whether it suits the class.\ncreate or replace function app.class_candidates(p_class uuid)\n  returns table (id uuid, first_name text, last_name text, date_of_birth date, family_name text,\n                 age integer, in_range boolean, enrolled boolean, waiting boolean)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id, s.first_name, s.last_name, s.date_of_birth, f.name,\n         extract(year from age(current_date, s.date_of_birth))::int,\n         (c.age_min is null or extract(year from age(current_date, s.date_of_birth)) >= c.age_min)\n           and (c.age_max is null or extract(year from age(current_date, s.date_of_birth)) <= c.age_max),\n         exists (select 1 from enrolment e where e.student_id = s.id and e.class_id = c.id\n                   and e.status = 'active' and e.deleted_at is null),\n         exists (select 1 from waitlist_entry w where w.student_id = s.id and w.class_id = c.id\n                   and w.status in ('waiting','offered') and w.deleted_at is null)\n    from class c\n    join student s on s.studio_id = c.studio_id and s.deleted_at is null and s.left_on is null\n    join family f on f.id = s.family_id and f.deleted_at is null\n   where c.id = p_class and app.is_admin(c.studio_id)\n   order by s.last_name, s.first_name\n$$;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-18 · Enquiry → trial → enrolment\n-- ════════════════════════════════════════════════════════════════════════════\n-- Booking a trial now carries its enquiry whichever child it is for, moves the\n-- enquiry to \"Trial booked\", and refuses a second live trial for one enquiry.\ncreate or replace function app.book_trial(p_session uuid, p_student uuid default null, p_child jsonb default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; kid uuid := p_student; fam uuid; tid uuid; enq uuid := nullif(p_child ->> 'enquiry_id', '')::uuid;\n        ephone text; ename text;\nbegin\n  select s.*, c.trial_price_minor, c.name as class_name into cs\n    from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: that session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then\n    raise exception 'FORBIDDEN: only the office books trials here' using errcode = 'insufficient_privilege';\n  end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: that session is cancelled' using errcode = 'check_violation'; end if;\n\n  if enq is not null then\n    if not exists (select 1 from enquiry where id = enq and studio_id = cs.studio_id and deleted_at is null) then\n      raise exception 'NOT_FOUND: that enquiry' using errcode = 'no_data_found';\n    end if;\n    if exists (select 1 from trial where enquiry_id = enq and deleted_at is null and status in ('requested','booked')) then\n      raise exception 'ALREADY_BOOKED: this enquiry already has a trial booked' using errcode = 'check_violation';\n    end if;\n  end if;\n\n  if kid is null then\n    if p_child is null or coalesce(btrim(p_child ->> 'first_name'), '') = ''\n       or (p_child ->> 'date_of_birth') is null or coalesce(btrim(p_child ->> 'contact_name'), '') = '' then\n      raise exception 'INVALID: a new child needs a name, date of birth and a parent or carer' using errcode = 'check_violation';\n    end if;\n    ephone := coalesce(nullif(btrim(p_child ->> 'emergency_phone'), ''), nullif(btrim(p_child ->> 'contact_phone'), ''));\n    if ephone is null then\n      raise exception 'INVALID: a phone number to ring in an emergency is needed before a child joins a class'\n        using errcode = 'check_violation';\n    end if;\n    insert into family (studio_id, name, is_prospect, created_by)\n    values (cs.studio_id, coalesce(nullif(btrim(p_child ->> 'last_name'), ''), split_part(p_child ->> 'contact_name', ' ', 2), 'New') || ' family', true, auth.uid())\n    returning id into fam;\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary)\n    values (cs.studio_id, fam, btrim(p_child ->> 'contact_name'), nullif(btrim(p_child ->> 'contact_email'), ''),\n            nullif(btrim(p_child ->> 'contact_phone'), ''), true);\n    insert into student (studio_id, family_id, first_name, last_name, date_of_birth, created_by)\n    values (cs.studio_id, fam, btrim(p_child ->> 'first_name'), coalesce(nullif(btrim(p_child ->> 'last_name'), ''), '—'),\n            (p_child ->> 'date_of_birth')::date, auth.uid())\n    returning id into kid;\n    ename := coalesce(nullif(btrim(p_child ->> 'emergency_name'), ''), btrim(p_child ->> 'contact_name'));\n    insert into emergency_contact (studio_id, student_id, full_name, relationship, phone, priority)\n    values (cs.studio_id, kid, ename, case when ename = btrim(p_child ->> 'contact_name') then 'Parent/carer' end, ephone, 1);\n  else\n    if not exists (select 1 from student where id = kid and studio_id = cs.studio_id and deleted_at is null) then\n      raise exception 'NOT_FOUND: that child' using errcode = 'no_data_found';\n    end if;\n    if not exists (select 1 from emergency_contact where student_id = kid and deleted_at is null) then\n      raise exception 'INVALID: % has no emergency contact — add one before they join a class',\n        (select first_name from student where id = kid) using errcode = 'check_violation';\n    end if;\n    select family_id into fam from student where id = kid;\n  end if;\n\n  if enq is not null then\n    update enquiry set family_id = coalesce(family_id, fam), student_id = coalesce(student_id, kid),\n                       interest_class_id = coalesce(interest_class_id, cs.class_id),\n                       stage = 'trial_booked', updated_at = now()\n     where id = enq;\n  end if;\n\n  insert into trial (studio_id, class_id, session_id, student_id, enquiry_id, status, price_minor, created_by)\n  values (cs.studio_id, cs.class_id, cs.id, kid, enq, 'booked', cs.trial_price_minor, auth.uid())\n  returning id into tid;\n  return tid;\nend $$;\n\n-- ── UR-54 (D9) · An outcome waits for the trial ────────────────────────────\n-- \"Came\", \"No show\" and \"Joining\" describe a class that has happened. Before\n-- the session starts, only cancelling is possible. Checked on the row itself,\n-- so every path (record_trial_outcome, convert_trial, a future one) obeys it.\ncreate or replace function app.guard_trial_outcome_time() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare starts timestamptz;\nbegin\n  if new.status is distinct from old.status\n     and new.status in ('attended', 'missed', 'converted')\n     and old.status in ('requested', 'booked')\n     and new.session_id is not null then\n    select starts_at into starts from class_session where id = new.session_id;\n    if starts is not null and starts > now() then\n      raise exception 'TOO_EARLY: The trial is on %. Record how it went after the class.',\n        to_char(starts at time zone coalesce((select timezone from studio where id = new.studio_id), 'Europe/London'),\n                'FMDay FMDD FMMonth')\n        using errcode = 'check_violation';\n    end if;\n  end if;\n  return new;\nend $$;\ncreate trigger trial_outcome_time before update of status on trial\n  for each row execute function app.guard_trial_outcome_time();\n\n-- A trial that is cancelled or comes to nothing closes its enquiry with a reason.\ncreate or replace function app.close_enquiry(p_id uuid, p_reason text) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from enquiry where id = p_id and deleted_at is null;\n  if sid is null then return false; end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may close an enquiry' using errcode = 'insufficient_privilege';\n  end if;\n  update enquiry set stage = 'closed_lost', closed_reason = nullif(btrim(p_reason), ''), updated_at = now()\n   where id = p_id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'close', 'enquiry', p_id, coalesce('closed: ' || nullif(btrim(p_reason), ''), 'closed'));\n  return true;\nend $$;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-35 · History of changes and of health-record reads\n-- ════════════════════════════════════════════════════════════════════════════\n-- The trail now says which fields changed (never their values: the log holds\n-- ids and names of columns, as SECURITY.md promises), and skips a write that\n-- changed nothing but timestamps. A soft delete is logged by app.soft_delete.\ncreate or replace function app.write_audit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare rec record; sid uuid; changed text;\nbegin\n  rec := coalesce(new, old);\n  begin sid := rec.studio_id; exception when others then sid := null; end;\n  if sid is not null and not exists (select 1 from studio where id = sid) then return rec; end if;\n  if tg_op = 'UPDATE' then\n    select string_agg(n.key, ', ' order by n.key) into changed\n      from jsonb_each(to_jsonb(new)) n\n     where n.value is distinct from (to_jsonb(old) -> n.key)\n       and n.key not in ('updated_at', 'updated_by', 'deleted_at', 'balance_minor');\n    if changed is null then return rec; end if;\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), lower(tg_op), tg_table_name, rec.id,\n          case tg_op when 'DELETE' then 'removed' when 'INSERT' then 'created'\n                     else 'changed ' || changed end);\n  return rec;\nend $$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['family', 'guardian', 'student', 'emergency_contact', 'studio', 'class'] loop\n    execute format('drop trigger if exists %1$s_audit on %1$I', t);\n    execute format(\n      'create trigger %1$s_audit after insert or update or delete on %1$I\n         for each row execute function app.write_audit()', t);\n  end loop;\nend $$;\n\n-- Opening a child's full medical record, as the owner or an administrator,\n-- leaves a \"viewed\" entry. Teachers' safety briefs are not logged here: they\n-- are the point of the brief. One entry per person, child and hour.\ncreate or replace function app.log_medical_view(p_student uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from student where id = p_student and deleted_at is null;\n  if sid is null or auth.uid() is null or not app.is_admin(sid) then return false; end if;\n  if exists (select 1 from audit_log where actor_id = auth.uid() and entity = 'student' and entity_id = p_student\n               and action = 'view_medical' and at > now() - interval '1 hour') then\n    return false;\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'view_medical', 'student', p_student, 'opened the medical record');\n  return true;\nend $$;\n\n-- A name for whatever a log row is about, worked out at read time.\ncreate or replace function app.audit_record_label(p_entity text, p_id uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case p_entity\n    when 'family'            then (select name from family where id = p_id)\n    when 'student'           then (select first_name || ' ' || last_name from student where id = p_id)\n    when 'guardian'          then (select g.full_name || ' (' || f.name || ')' from guardian g join family f on f.id = g.family_id where g.id = p_id)\n    when 'emergency_contact' then (select 'Emergency contact for ' || s.first_name || ' ' || s.last_name\n                                     from emergency_contact e join student s on s.id = e.student_id where e.id = p_id)\n    when 'medical_record'    then (select 'Medical record of ' || s.first_name || ' ' || s.last_name\n                                     from medical_record m join student s on s.id = m.student_id where m.id = p_id)\n    when 'consent_record'    then (select 'Consent for ' || s.first_name || ' ' || s.last_name\n                                     from consent_record c join student s on s.id = c.student_id where c.id = p_id)\n    when 'enrolment'         then (select s.first_name || ' ' || s.last_name || ' in ' || c.name\n                                     from enrolment e join student s on s.id = e.student_id join class c on c.id = e.class_id where e.id = p_id)\n    when 'invoice'           then (select number from invoice where id = p_id)\n    when 'payment'           then (select 'Payment from ' || f.name from payment p join family f on f.id = p.family_id where p.id = p_id)\n    when 'class'             then (select name from class where id = p_id)\n    when 'studio'            then 'School settings'\n    when 'membership'        then (select 'Access for ' || u.full_name from membership m join user_account u on u.id = m.user_id where m.id = p_id)\n    when 'staff_member'      then (select display_name from staff_member where id = p_id)\n    when 'enquiry'           then (select 'Enquiry from ' || contact_name from enquiry where id = p_id)\n    when 'waitlist_entry'    then (select 'Waiting list: ' || s.first_name || ' ' || s.last_name\n                                     from waitlist_entry w join student s on s.id = w.student_id where w.id = p_id)\n    else null end\n$$;\n\n-- The school's history, for the owner: filter by who, by kind of record, by\n-- a word in the record's name, and by date.\ncreate or replace function app.audit_history(p_actor uuid default null, p_entity text default null,\n                                             p_text text default null, p_from date default null,\n                                             p_to date default null, p_limit integer default 200)\n  returns table (id bigint, at timestamptz, actor_id uuid, actor text, action text, entity text,\n                 entity_id uuid, record_label text, summary text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select * from (\n    select a.id, a.at, a.actor_id,\n           coalesce(u.full_name, case when a.actor_id is null then 'Swayvo (automatic)' else 'Former staff' end) as actor,\n           a.action, a.entity, a.entity_id, app.audit_record_label(a.entity, a.entity_id) as record_label, a.summary\n      from audit_log a left join user_account u on u.id = a.actor_id\n     where a.studio_id in (select m.studio_id from app.memberships() m where m.role = 'owner')\n       and (p_actor is null or a.actor_id = p_actor)\n       and (p_entity is null or a.entity = p_entity)\n       and (p_from is null or a.at >= p_from)\n       and (p_to is null or a.at < p_to + 1)\n     order by a.at desc, a.id desc\n     limit 2000) h\n   where p_text is null or btrim(p_text) = '' or lower(coalesce(h.record_label, '')) like '%' || lower(btrim(p_text)) || '%'\n   limit greatest(1, least(coalesce(p_limit, 200), 1000))\n$$;\n\n-- One record's history, for the office: a family with its guardians and\n-- children, or a child with their health record, contacts and places. Reads of\n-- health records are shown to the owner only.\ncreate or replace function app.record_history(p_entity text, p_id uuid)\n  returns table (id bigint, at timestamptz, actor text, action text, entity text, record_label text, summary text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare sid uuid; is_owner boolean; ids uuid[];\nbegin\n  if p_entity = 'family' then\n    select studio_id into sid from family where family.id = p_id;\n    ids := array[p_id]\n      || coalesce((select array_agg(g.id) from guardian g where g.family_id = p_id), '{}')\n      || coalesce((select array_agg(s.id) from student s where s.family_id = p_id), '{}')\n      || coalesce((select array_agg(i.id) from invoice i where i.family_id = p_id), '{}')\n      || coalesce((select array_agg(p.id) from payment p where p.family_id = p_id), '{}');\n  elsif p_entity = 'student' then\n    select studio_id into sid from student where student.id = p_id;\n    ids := array[p_id]\n      || coalesce((select array_agg(m.id) from medical_record m where m.student_id = p_id), '{}')\n      || coalesce((select array_agg(e.id) from emergency_contact e where e.student_id = p_id), '{}')\n      || coalesce((select array_agg(c.id) from consent_record c where c.student_id = p_id), '{}')\n      || coalesce((select array_agg(e.id) from enrolment e where e.student_id = p_id), '{}');\n  else\n    raise exception 'INVALID: history is kept for families and students' using errcode = 'check_violation';\n  end if;\n  if sid is null or not app.is_admin(sid) then return; end if;\n  is_owner := app.has_role(sid, 'owner');\n  return query\n    select a.id, a.at,\n           coalesce(u.full_name, case when a.actor_id is null then 'Swayvo (automatic)' else 'Former staff' end),\n           a.action, a.entity, app.audit_record_label(a.entity, a.entity_id), a.summary\n      from audit_log a left join user_account u on u.id = a.actor_id\n     where a.studio_id = sid and a.entity_id = any(ids)\n       and (is_owner or a.action <> 'view_medical')\n     order by a.at desc, a.id desc\n     limit 200;\nend $$;\n\n-- People who appear in the owner's history, for the filter.\ncreate or replace function app.audit_actors()\n  returns table (id uuid, name text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select distinct u.id, u.full_name from audit_log a join user_account u on u.id = a.actor_id\n   where a.studio_id in (select m.studio_id from app.memberships() m where m.role = 'owner')\n   order by u.full_name\n$$;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-39 · Asking to upgrade\n-- ════════════════════════════════════════════════════════════════════════════\n-- Recorded on the school's account history, which the platform console reads\n-- (app.platform_events shows every account decision). Once a day is enough.\ncreate or replace function app.request_plan_upgrade(p_reason text) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select m.studio_id into sid from app.memberships() m where m.role in ('owner', 'admin') limit 1;\n  if sid is null then\n    raise exception 'FORBIDDEN: only the office can ask for a larger plan' using errcode = 'insufficient_privilege';\n  end if;\n  if exists (select 1 from audit_log where studio_id = sid and action = 'upgrade_request' and at > now() - interval '1 day') then\n    return false;\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'upgrade_request', 'studio', sid,\n          'Asked for a larger plan: ' || coalesce(nullif(btrim(p_reason), ''), 'plan limit reached'));\n  return true;\nend $$;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-57 · Duplicate families\n-- ════════════════════════════════════════════════════════════════════════════\n-- Likely duplicates: the same guardian email or phone in two families, a child\n-- of the same first name and birthday, or simply the same family name.\ncreate or replace function app.family_duplicates()\n  returns table (keep_id uuid, keep_name text, other_id uuid, other_name text, reason text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with mine as (select f.* from family f where f.deleted_at is null and app.is_admin(f.studio_id)),\n  g as (select g.family_id, lower(btrim(g.email)) as email,\n               nullif(right(regexp_replace(coalesce(g.phone, ''), '\\D', '', 'g'), 10), '') as phone\n          from guardian g join mine on mine.id = g.family_id where g.deleted_at is null),\n  pairs as (\n    select a.family_id as x, b.family_id as y, 'Same email: ' || a.email as reason\n      from g a join g b on a.email = b.email and a.family_id < b.family_id where a.email is not null and a.email <> ''\n    union all\n    select a.family_id, b.family_id, 'Same phone number'\n      from g a join g b on a.phone = b.phone and a.family_id < b.family_id where a.phone is not null and length(a.phone) >= 7\n    union all\n    select s1.family_id, s2.family_id, 'A child called ' || s1.first_name || ' with the same birthday'\n      from student s1 join student s2 on s1.family_id < s2.family_id and s1.studio_id = s2.studio_id\n       and lower(s1.first_name) = lower(s2.first_name) and s1.date_of_birth = s2.date_of_birth\n      join mine f1 on f1.id = s1.family_id join mine f2 on f2.id = s2.family_id\n     where s1.deleted_at is null and s2.deleted_at is null\n    union all\n    select f1.id, f2.id, 'Same family name'\n      from mine f1 join mine f2 on f1.id < f2.id and f1.studio_id = f2.studio_id\n       and lower(btrim(f1.name)) = lower(btrim(f2.name))\n  ),\n  grouped as (select x, y, string_agg(distinct reason, '; ') as reason from pairs group by x, y)\n  -- Keep the older record: it is the one invoices and logins most likely point at.\n  select case when fx.created_at <= fy.created_at then fx.id else fy.id end,\n         case when fx.created_at <= fy.created_at then fx.name else fy.name end,\n         case when fx.created_at <= fy.created_at then fy.id else fx.id end,\n         case when fx.created_at <= fy.created_at then fy.name else fx.name end,\n         g.reason\n    from grouped g join mine fx on fx.id = g.x join mine fy on fy.id = g.y\n   where fx.studio_id = fy.studio_id\n   order by 2\n$$;\n\n-- Every row a merge moved, so it can be put back.\ncreate table family_merge (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  kept_id     uuid not null references family(id) on delete cascade,\n  merged_id   uuid not null references family(id) on delete cascade,\n  moved       jsonb not null default '{}'::jsonb,   -- { table: [ids] }\n  merged_by   uuid references user_account(id) on delete set null,\n  merged_at   timestamptz not null default now(),\n  undone_at   timestamptz,\n  undone_by   uuid references user_account(id) on delete set null\n);\nalter table family_merge enable row level security;\nalter table family_merge force row level security;\ncreate policy family_merge_read on family_merge for select using (app.is_admin(studio_id));\ngrant select on family_merge to authenticated;\ngrant all on family_merge to service_role;\n\n-- What a merge would move, without moving it.\ncreate or replace function app.family_merge_preview(p_keep uuid, p_merge uuid)\n  returns table (tbl text, n integer)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare t text; sid uuid; c integer;\nbegin\n  select studio_id into sid from family where id = p_merge and deleted_at is null;\n  if sid is null or not app.is_admin(sid)\n     or not exists (select 1 from family where id = p_keep and studio_id = sid and deleted_at is null) then\n    raise exception 'FORBIDDEN: choose two families at your school' using errcode = 'insufficient_privilege';\n  end if;\n  for t in select table_name from information_schema.columns\n            where table_schema = 'public' and column_name = 'family_id' and table_name <> 'family_merge'\n            order by table_name loop\n    execute format('select count(*)::int from %I where family_id = $1', t) into c using p_merge;\n    if c > 0 then tbl := t; n := c; return next; end if;\n  end loop;\nend $$;\n\ncreate or replace function app.merge_families(p_keep uuid, p_merge uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t text; sid uuid; moved jsonb := '{}'::jsonb; ids jsonb; mid uuid; kname text; mname text;\nbegin\n  if p_keep = p_merge then raise exception 'INVALID: choose two different families' using errcode = 'check_violation'; end if;\n  select studio_id, name into sid, mname from family where id = p_merge and deleted_at is null;\n  select name into kname from family where id = p_keep and studio_id = sid and deleted_at is null;\n  if sid is null or kname is null then\n    raise exception 'NOT_FOUND: both families must exist at the same school' using errcode = 'no_data_found';\n  end if;\n  if not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office may merge families' using errcode = 'insufficient_privilege';\n  end if;\n\n  for t in select table_name from information_schema.columns\n            where table_schema = 'public' and column_name = 'family_id' and table_name <> 'family_merge'\n            order by table_name loop\n    execute format('with m as (update %I set family_id = $1 where family_id = $2 returning id)\n                    select coalesce(jsonb_agg(id), ''[]''::jsonb) from m', t)\n      into ids using p_keep, p_merge;\n    if jsonb_array_length(ids) > 0 then moved := moved || jsonb_build_object(t, ids); end if;\n  end loop;\n\n  -- One main contact is enough; the kept family's stays.\n  if exists (select 1 from guardian where family_id = p_keep and is_primary and deleted_at is null\n               and id::text not in (select jsonb_array_elements_text(coalesce(moved -> 'guardian', '[]')))) then\n    update guardian set is_primary = false\n     where id::text in (select jsonb_array_elements_text(coalesce(moved -> 'guardian', '[]'))) and is_primary;\n  end if;\n\n  update family set deleted_at = now(),\n         notes = concat_ws(E'\\n', notes, 'Merged into ' || kname || ' on ' || to_char(now(), 'DD Mon YYYY'))\n   where id = p_merge;\n  update family set is_prospect = false where id = p_keep and is_prospect\n     and exists (select 1 from family where id = p_merge and not is_prospect);\n  perform app.recalc_family_balance(p_keep);\n\n  insert into family_merge (studio_id, kept_id, merged_id, moved, merged_by)\n  values (sid, p_keep, p_merge, moved, auth.uid()) returning id into mid;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'merge', 'family', p_keep, format('merged %s into this family (%s records moved)', mname,\n          (select coalesce(sum(jsonb_array_length(v)), 0) from jsonb_each(moved) e(k, v))));\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'merge', 'family', p_merge, 'merged into ' || kname);\n  return mid;\nend $$;\n\n-- Undo, within 30 days: the merged family comes back with exactly the rows that\n-- were moved. Anything created since stays with the family that was kept.\ncreate or replace function app.undo_family_merge(p_merge uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare m family_merge; t text; ids jsonb;\nbegin\n  select * into m from family_merge where id = p_merge;\n  if m.id is null then raise exception 'NOT_FOUND: that merge' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(m.studio_id) then\n    raise exception 'FORBIDDEN: only the office may undo a merge' using errcode = 'insufficient_privilege';\n  end if;\n  if m.undone_at is not null then return false; end if;\n  if m.merged_at < now() - interval '30 days' then\n    raise exception 'TOO_LATE: a merge can be undone for 30 days' using errcode = 'check_violation';\n  end if;\n  update family set deleted_at = null,\n         notes = nullif(regexp_replace(coalesce(notes, ''), E'\\\\n?Merged into [^\\\\n]*$', ''), '')\n   where id = m.merged_id;\n  for t, ids in select key, value from jsonb_each(m.moved) loop\n    execute format('update %I set family_id = $1 where family_id = $2 and id::text in (select jsonb_array_elements_text($3))', t)\n      using m.merged_id, m.kept_id, ids;\n  end loop;\n  perform app.recalc_family_balance(m.kept_id);\n  perform app.recalc_family_balance(m.merged_id);\n  update family_merge set undone_at = now(), undone_by = auth.uid() where id = p_merge;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (m.studio_id, auth.uid(), 'unmerge', 'family', m.merged_id, 'merge undone: records returned to this family');\n  return true;\nend $$;\n\n-- ── Grants ─────────────────────────────────────────────────────────────────\ndo $$\ndeclare f text;\nbegin\n  foreach f in array array[\n    'class_live_offers(uuid, uuid)', 'class_free_places(uuid)', 'offer_waitlist_place(uuid, integer)',\n    'offer_next_place(uuid)', 'withdraw_enrolment(uuid, text)', 'accept_waitlist_place(uuid)',\n    'decline_waitlist_place(uuid, text)', 'class_candidates(uuid)', 'book_trial(uuid, uuid, jsonb)',\n    'close_enquiry(uuid, text)', 'log_medical_view(uuid)', 'audit_record_label(text, uuid)',\n    'audit_history(uuid, text, text, date, date, integer)', 'record_history(text, uuid)', 'audit_actors()',\n    'request_plan_upgrade(text)', 'family_duplicates()', 'family_merge_preview(uuid, uuid)',\n    'merge_families(uuid, uuid)', 'undo_family_merge(uuid)'] loop\n    execute format('revoke all on function app.%s from public', f);\n    execute format('grant execute on function app.%s to authenticated, service_role', f);\n  end loop;\nend $$;\n"},{name:"0045_billing_fixes.sql",sql:"-- ============================================================================\n-- 0045 · Billing integrity, payment instructions, money notifications\n--        (panel review: UR-10, UR-22, UR-23, UR-24, UR-46)\n-- ----------------------------------------------------------------------------\n-- 1. Credit notes. A refund on an invoice no longer turns a settled invoice\n--    into debt: it issues a credit note that lowers what the invoice charges,\n--    and records the money going back as a refund. A credit note can instead\n--    be kept as credit on the family's account. Every refund is now a row,\n--    so a family statement can list it with its date.\n-- 2. Billing runs refuse to bill a family twice for a period. Invoices whose\n--    lines name the class are still matched line by line (so a mid-term\n--    joiner is billed); any other tuition invoice for the period — imported,\n--    hand-made — skips the whole family, unless the office overrides it for\n--    that family with a reason.\n-- 3. Ending a family discount works. It used to soft-delete the row, which\n--    the row-level policy then hid from its own RETURNING clause, so the\n--    update failed. Ending now stamps ended_at and keeps the history.\n-- 4. Goodwill credit has an entry point with a reason, and is logged.\n-- 5. The school's bank details, so families can actually pay by transfer,\n--    and a family reference for paying several invoices at once.\n-- 6. Families hear about money in the app: a new invoice, a payment\n--    received, an invoice due in three days, and a confirmed event place.\n-- 7. A confirmed private lesson with a price raises a draft invoice, and\n--    families can see everything coming up, with its state.\n-- 8. Payment reminders to many overdue families at once, one per family,\n--    each logged.\n-- ============================================================================\n\n-- Formatting money in messages written by the database.\ncreate or replace function app.gbp(p_minor bigint) returns text\n  language sql immutable as $$ select '£' || to_char(coalesce(p_minor, 0) / 100.0, 'FM999,999,990.00') $$;\n\n-- ── 1. Credit notes and refunds ─────────────────────────────────────────────\ncreate table credit_note (\n  id             uuid primary key default gen_random_uuid(),\n  studio_id      uuid not null references studio(id) on delete cascade,\n  family_id      uuid not null references family(id) on delete restrict,\n  invoice_id     uuid not null references invoice(id) on delete restrict,\n  number         text not null,\n  amount_minor   bigint not null check (amount_minor > 0),\n  reason         text not null,\n  -- Where the value went: off what the invoice still wanted, back to the\n  -- family as money, or held on their account for the next invoice.\n  applied_minor  bigint not null default 0,\n  refunded_minor bigint not null default 0,\n  account_minor  bigint not null default 0,\n  created_by     uuid references user_account(id) on delete set null,\n  created_at     timestamptz not null default now(),\n  unique (studio_id, number),\n  check (applied_minor + refunded_minor + account_minor = amount_minor)\n);\ncreate index credit_note_invoice on credit_note (invoice_id);\ncreate index credit_note_family on credit_note (family_id);\n\ncreate table refund (\n  id             uuid primary key default gen_random_uuid(),\n  studio_id      uuid not null references studio(id) on delete cascade,\n  family_id      uuid not null references family(id) on delete restrict,\n  payment_id     uuid not null references payment(id) on delete restrict,\n  credit_note_id uuid references credit_note(id) on delete set null,\n  amount_minor   bigint not null check (amount_minor > 0),\n  reason         text not null,\n  created_by     uuid references user_account(id) on delete set null,\n  created_at     timestamptz not null default now()\n);\ncreate index refund_family on refund (family_id);\ncreate index refund_payment on refund (payment_id);\n\n-- The credit a credit note puts against an invoice (or on account) is a\n-- `credit` payment row, as goodwill credit always was; this says which note.\nalter table payment add column credit_note_id uuid references credit_note(id) on delete set null;\n\nalter table credit_note enable row level security; alter table credit_note force row level security;\nalter table refund      enable row level security; alter table refund      force row level security;\ncreate policy credit_note_read on credit_note for select\n  using (studio_id in (select app.studio_ids()) and (app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\ncreate policy refund_read on refund for select\n  using (studio_id in (select app.studio_ids()) and (app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\n-- Written only by the functions below.\ngrant select on credit_note, refund to authenticated;\ngrant all on credit_note, refund to service_role;\n\n-- Hand money back from an invoice's transfer and cash payments (newest\n-- first, or the one named first). Card money goes back through the provider.\ncreate or replace function app.refund_from_invoice(p_invoice uuid, p_amount bigint, p_reason text,\n                                                   p_credit_note uuid, p_first uuid default null)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p record; left_ bigint := p_amount; take bigint; avail bigint;\nbegin\n  select coalesce(sum(amount_minor - refunded_minor), 0) into avail from payment\n   where invoice_id = p_invoice and deleted_at is null and succeeded_at is not null\n     and method in ('bank_transfer', 'cash');\n  if avail < p_amount then\n    raise exception 'INVALID: only % of this invoice was paid by transfer or cash, so only that can be handed back here — keep the rest as credit, or refund a card through the payment provider', app.gbp(avail)\n      using errcode = 'check_violation';\n  end if;\n  for p in select * from payment\n            where invoice_id = p_invoice and deleted_at is null and succeeded_at is not null\n              and method in ('bank_transfer', 'cash') and amount_minor > refunded_minor\n            order by (id = p_first) desc nulls last, created_at desc\n  loop\n    exit when left_ <= 0;\n    take := least(left_, p.amount_minor - p.refunded_minor);\n    update payment set refunded_minor = refunded_minor + take,\n                       note = concat_ws(' · ', note, 'Refunded ' || app.gbp(take) || ': ' || btrim(p_reason))\n     where id = p.id;\n    insert into refund (studio_id, family_id, payment_id, credit_note_id, amount_minor, reason, created_by)\n    values (p.studio_id, p.family_id, p.id, p_credit_note, take, btrim(p_reason), auth.uid());\n    left_ := left_ - take;\n  end loop;\nend $$;\nrevoke all on function app.refund_from_invoice(uuid, bigint, text, uuid, uuid) from public, authenticated, anon;\n\n-- p_settle: 'refund' — the whole amount comes off the invoice and goes back\n--           to the family as money;\n--           'account' — it comes off what the invoice still wants, and any\n--           rest is held on the family's account for their next invoices.\ncreate or replace function app.credit_note_internal(p_invoice uuid, p_amount bigint, p_reason text,\n                                                    p_settle text, p_refund_first uuid default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare inv invoice; credited bigint; owed bigint; applied bigint; rest bigint; num text; cn uuid;\nbegin\n  select * into inv from invoice where id = p_invoice and deleted_at is null;\n  if inv.id is null then raise exception 'NOT_FOUND: invoice' using errcode = 'no_data_found'; end if;\n  if inv.status in ('draft', 'void') then\n    raise exception 'INVALID: a credit note is for an issued invoice — change or void a draft instead'\n      using errcode = 'check_violation';\n  end if;\n  if p_settle not in ('refund', 'account') then\n    raise exception 'INVALID: say whether the money goes back or stays as credit' using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'INVALID: say why the family is being credited' using errcode = 'check_violation';\n  end if;\n  select coalesce(sum(amount_minor), 0) into credited from credit_note where invoice_id = inv.id;\n  if coalesce(p_amount, 0) <= 0 or p_amount > inv.total_minor - credited then\n    raise exception 'INVALID: at most % can be credited on this invoice', app.gbp(greatest(inv.total_minor - credited, 0))\n      using errcode = 'check_violation';\n  end if;\n\n  owed := greatest(inv.total_minor - inv.paid_minor, 0);\n  applied := case when p_settle = 'refund' then 0 else least(p_amount, owed) end;\n  rest := p_amount - applied;\n\n  perform pg_advisory_xact_lock(hashtext('credit-note-number:' || inv.studio_id::text));\n  select 'CN-' || lpad((coalesce(max(nullif(regexp_replace(number, '\\D', '', 'g'), '')::int), 1000) + 1)::text, 4, '0')\n    into num from credit_note where studio_id = inv.studio_id;\n\n  insert into credit_note (studio_id, family_id, invoice_id, number, amount_minor, reason,\n                           applied_minor, refunded_minor, account_minor, created_by)\n  values (inv.studio_id, inv.family_id, inv.id, num, p_amount, btrim(p_reason),\n          applied, case when p_settle = 'refund' then rest else 0 end,\n          case when p_settle = 'account' then rest else 0 end, auth.uid())\n  returning id into cn;\n\n  -- The credit itself. Against the invoice it lowers what is owed; held on\n  -- account it waits for the next invoice.\n  if p_settle = 'refund' or applied > 0 then\n    insert into payment (studio_id, family_id, invoice_id, amount_minor, method, provider, succeeded_at,\n                         note, recorded_by, credit_note_id)\n    values (inv.studio_id, inv.family_id, inv.id, case when p_settle = 'refund' then p_amount else applied end,\n            'credit', 'ledger', now(), num || ': ' || btrim(p_reason), auth.uid(), cn);\n  end if;\n  if p_settle = 'account' and rest > 0 then\n    insert into payment (studio_id, family_id, invoice_id, amount_minor, method, provider, succeeded_at,\n                         note, recorded_by, credit_note_id)\n    values (inv.studio_id, inv.family_id, null, rest, 'credit', 'ledger', now(),\n            num || ' (' || inv.number || '): ' || btrim(p_reason), auth.uid(), cn);\n  end if;\n  -- The money that goes back.\n  if p_settle = 'refund' then\n    perform app.refund_from_invoice(inv.id, p_amount, p_reason, cn, p_refund_first);\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (inv.studio_id, auth.uid(), 'credit', 'invoice', inv.id,\n          num || ' on ' || inv.number || ', ' || app.gbp(p_amount)\n          || case when p_settle = 'refund' then ' refunded' else ' as credit' end || ': ' || btrim(p_reason));\n\n  if p_settle = 'account' and rest > 0 then perform app.allocate_account_credit_internal(inv.family_id); end if;\n  return cn;\nend $$;\nrevoke all on function app.credit_note_internal(uuid, bigint, text, text, uuid) from public, authenticated, anon;\n\ncreate or replace function app.issue_credit_note(p_invoice uuid, p_amount bigint, p_reason text, p_settle text default 'account')\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  perform app.require_admin((select studio_id from invoice where id = p_invoice));\n  return app.credit_note_internal(p_invoice, p_amount, p_reason, p_settle);\nend $$;\n\n-- Refunds. On an invoice, handing money back means the family was charged\n-- less: a credit note, and the invoice stays settled (p_mode 'credit_note',\n-- the default). An overpayment is simply handed back. 'mistake' is for a\n-- payment recorded in error: it is reversed and the invoice is owed again.\ndrop function if exists app.refund_payment(uuid, bigint, text);\ncreate function app.refund_payment(p_payment uuid, p_amount_minor bigint, p_reason text,\n                                   p_mode text default 'credit_note')\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p payment; left_ bigint; inv invoice; over bigint; plain bigint;\nbegin\n  select * into p from payment where id = p_payment and deleted_at is null and succeeded_at is not null;\n  if p.id is null then raise exception 'NOT_FOUND: payment' using errcode = 'no_data_found'; end if;\n  perform app.require_admin(p.studio_id);\n  if p.method in ('card', 'direct_debit') then\n    raise exception 'INVALID: card and direct debit refunds are made with the payment provider'\n      using errcode = 'check_violation';\n  end if;\n  if p.method in ('account', 'credit') then\n    raise exception 'INVALID: credit is not money that can be refunded' using errcode = 'check_violation';\n  end if;\n  if p_mode not in ('credit_note', 'mistake') then\n    raise exception 'INVALID: unknown kind of refund' using errcode = 'check_violation';\n  end if;\n  left_ := p.amount_minor - p.refunded_minor;\n  if coalesce(p_amount_minor, 0) <= 0 or p_amount_minor > left_ then\n    raise exception 'INVALID: a refund must be between 1p and the % not already refunded', app.gbp(left_)\n      using errcode = 'check_violation';\n  end if;\n  if p.invoice_id is null and p_amount_minor > app.family_available_credit(p.family_id) then\n    raise exception 'INVALID: that money has already been applied to invoices' using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'INVALID: say why the payment is being refunded' using errcode = 'check_violation';\n  end if;\n\n  if p.invoice_id is not null and p_mode = 'credit_note' then\n    select * into inv from invoice where id = p.invoice_id;\n    over := greatest(inv.paid_minor - inv.total_minor, 0);\n    plain := least(p_amount_minor, over);\n  else\n    plain := p_amount_minor;\n  end if;\n\n  if plain > 0 then\n    update payment set refunded_minor = refunded_minor + plain,\n                       note = concat_ws(' · ', note, 'Refunded ' || app.gbp(plain) || ': ' || btrim(p_reason))\n     where id = p_payment;\n    insert into refund (studio_id, family_id, payment_id, amount_minor, reason, created_by)\n    values (p.studio_id, p.family_id, p.id, plain, btrim(p_reason), auth.uid());\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (p.studio_id, auth.uid(), 'refund', 'payment', p.id,\n            app.gbp(plain) || case when p_mode = 'mistake' then ' reversed (recorded by mistake): ' else ' refunded: ' end || btrim(p_reason));\n  end if;\n  if p_amount_minor > plain then\n    perform app.credit_note_internal(p.invoice_id, p_amount_minor - plain, p_reason, 'refund', p.id);\n  end if;\nend $$;\n\n-- ── 4. Goodwill credit, with a reason, logged ───────────────────────────────\ncreate or replace function app.add_family_credit(p_family uuid, p_amount_minor bigint, p_reason text)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; pid uuid;\nbegin\n  select studio_id into sid from family where id = p_family and deleted_at is null;\n  perform app.require_admin(sid);\n  if coalesce(btrim(p_reason), '') = '' then\n    raise exception 'INVALID: say why the family is being given credit' using errcode = 'check_violation';\n  end if;\n  pid := app.record_payment(p_family, p_amount_minor, 'credit', null, btrim(p_reason));\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'credit', 'family', p_family, app.gbp(p_amount_minor) || ' credit: ' || btrim(p_reason));\n  return pid;\nend $$;\n\ngrant execute on function app.issue_credit_note(uuid, bigint, text, text),\n                          app.refund_payment(uuid, bigint, text, text),\n                          app.add_family_credit(uuid, bigint, text) to authenticated;\n\n-- ── 2. Billing runs: one bill per family per period ────────────────────────\n-- Live invoices for a period that the line-by-line check cannot see. For a\n-- term: any invoice raised for that term (term_id) outside a billing run —\n-- hand-made, imported, an opening balance that includes the term's fees —\n-- and, with no term, tuition invoices whose lines name no class, dated from\n-- four weeks before the term to its end (an opening balance with no term is\n-- not counted). For a month: lines\n-- that say they cover that month, or undated invoices from that month whose\n-- line names the month.\ncreate or replace function app.billing_period_invoices(p_term uuid, p_month date default null)\n  returns table (family_id uuid, invoice_ids uuid[], numbers text, total_minor bigint)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with w as (\n    select t.id, t.studio_id,\n           case when p_month is null then t.starts_on - 28 else date_trunc('month', p_month)::date end w0,\n           case when p_month is null then t.ends_on else (date_trunc('month', p_month) + interval '1 month - 1 day')::date end w1,\n           date_trunc('month', p_month)::date pm,\n           to_char(p_month, 'FMMonth') mname\n      from term t where t.id = p_term and t.deleted_at is null)\n  select i.family_id, array_agg(i.id order by i.number), string_agg(i.number, ', ' order by i.number),\n         sum(i.total_minor)::bigint\n    from invoice i, w\n   where i.studio_id = w.studio_id and i.deleted_at is null and i.status <> 'void'\n     and (\n       -- Any invoice the office (or an import) raised for this very term,\n       -- other than one from a billing run, which is matched line by line.\n       (p_month is null and i.term_id = w.id and i.billing_run_id is null)\n     or exists (\n       select 1 from invoice_item ii\n        where ii.invoice_id = i.id and ii.deleted_at is null and ii.class_id is null\n          and ii.kind in ('tuition', 'term_fee')\n          and case\n                when p_month is null then\n                  ii.period_start is null and (\n                    i.term_id = w.id\n                    or (i.term_id is null and coalesce(i.issued_on, i.due_on, i.created_at::date) between w.w0 and w.w1\n                      -- An opening balance with no term does not cover the term.\n                      and coalesce(i.note, '') not ilike 'Opening balance%'))\n                else\n                  ii.period_start = w.pm\n                  or (ii.period_start is null and i.term_id is null\n                      and coalesce(i.issued_on, i.due_on, i.created_at::date) between w.w0 and w.w1\n                      and ii.description ilike '%' || w.mname || '%')\n              end))\n   group by i.family_id\n$$;\nrevoke all on function app.billing_period_invoices(uuid, date) from public, authenticated, anon;\n\n-- As 0039, with families already billed for the period left out unless the\n-- office includes them (p_include).\ndrop function if exists app.billing_lines(uuid, date);\ncreate function app.billing_lines(p_term uuid, p_month date default null, p_include uuid[] default null)\n  returns table (family_id uuid, family_name text, student_id uuid, student_name text,\n                 class_id uuid, class_name text, description text, quantity numeric,\n                 unit_minor int, discount_minor int, discount_reason text, period_start date)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; t term; m0 date; m1 date; pstart date; skip uuid[];\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  if p_month is not null then\n    m0 := greatest(date_trunc('month', p_month)::date, t.starts_on);\n    m1 := least((date_trunc('month', p_month) + interval '1 month - 1 day')::date, t.ends_on);\n    if m0 > m1 then raise exception 'INVALID: that month is outside the term' using errcode = 'check_violation'; end if;\n    pstart := date_trunc('month', p_month)::date;\n  else\n    m0 := t.starts_on; m1 := t.ends_on; pstart := t.starts_on;\n  end if;\n  skip := array(select g.family_id from app.billing_period_invoices(p_term, p_month) g\n                 where not (g.family_id = any(coalesce(p_include, '{}'::uuid[]))));\n  return query\n  with base as (\n    select f.id fam, f.name fname, s.id stu, s.first_name || ' ' || s.last_name sname,\n           c.id cls, c.name cname, c.pricing,\n           coalesce(e.price_minor, c.price_minor) price, greatest(e.started_on, m0) from_day,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null and cs.status <> 'cancelled'\n              and cs.starts_at::date between m0 and m1) total_sessions,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null and cs.status <> 'cancelled'\n              and cs.starts_at::date between greatest(e.started_on, m0) and m1) left_sessions\n      from enrolment e\n      join class c on c.id = e.class_id and c.deleted_at is null and c.term_id = t.id\n      join student s on s.id = e.student_id and s.deleted_at is null\n      join family f on f.id = s.family_id and f.deleted_at is null and not f.is_prospect\n     where e.deleted_at is null and e.status = 'active' and e.started_on <= m1\n       and coalesce(e.price_minor, c.price_minor) > 0\n       and (case when p_month is null then c.pricing in ('term', 'one_off') else c.pricing = 'monthly' end)\n       -- Already billed for this period by an invoice that does not name the class.\n       and not (f.id = any(skip))\n       -- Already billed for this period (a live invoice line for this child and class).\n       and not exists (\n         select 1 from invoice_item ii join invoice i on i.id = ii.invoice_id\n          where ii.student_id = s.id and ii.class_id = c.id and ii.deleted_at is null\n            and i.deleted_at is null and i.status not in ('void', 'refunded') and i.term_id = t.id\n            and (p_month is null or ii.period_start = pstart))\n  ),\n  priced as (\n    select b.*, 1::numeric qty,\n      case when b.pricing in ('term', 'monthly') and b.from_day > m0 and b.total_sessions > 0\n           then round(b.price::numeric * b.left_sessions / b.total_sessions)::int else b.price end unit,\n      case when b.pricing = 'one_off' then b.cname || ' — course fee'\n           when b.from_day > m0 and b.total_sessions > 0\n             then format('%s — %s, %s of %s classes from %s', b.cname,\n                         case when p_month is null then t.name else to_char(pstart, 'FMMonth YYYY') end,\n                         b.left_sessions, b.total_sessions, to_char(b.from_day, 'FMDD Mon'))\n           else b.cname || ' — ' || case when p_month is null then t.name else to_char(pstart, 'FMMonth YYYY') end end descr\n      from base b\n  ),\n  ranked as (\n    select p.*,\n      dense_rank() over (partition by p.fam order by child_total desc, p.stu) child_rank,\n      row_number() over (partition by p.stu order by p.unit * p.qty desc, p.cls) class_rank\n      from (select p.*, sum(p.unit * p.qty) over (partition by p.stu) child_total from priced p) p\n  ),\n  rules as (\n    select (select percent from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_n,\n           (select percent from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_n\n  ),\n  disc as (\n    select r.*,\n      case when rules.sib_pct is not null and r.child_rank >= rules.sib_n then rules.sib_pct else 0 end sib,\n      case when rules.mc_pct is not null and r.class_rank >= rules.mc_n then rules.mc_pct else 0 end mc,\n      (select fd.pct from app.family_discounts_on(r.fam, m0, m1) fd) fam_pct\n      from ranked r, rules\n  )\n  select d.fam, d.fname, d.stu, d.sname, d.cls, d.cname, d.descr, d.qty, d.unit,\n         round(d.unit * d.qty * (1 - (1 - greatest(d.sib, d.mc) / 100.0) * (1 - d.fam_pct / 100.0)))::int,\n         nullif(concat_ws(' + ',\n           case when greatest(d.sib, d.mc) = 0 then null\n                when d.sib >= d.mc then d.sib || '% sibling discount' else d.mc || '% multi-class discount' end,\n           case when d.fam_pct > 0 then d.fam_pct || '% discount' end), ''),\n         pstart\n    from disc d\n   order by d.fname, d.sname, d.cname;\nend $$;\n\n-- Who the run leaves out, what they were already billed, and what the run\n-- would raise for them if included anyway.\ncreate or replace function app.billing_skipped(p_term uuid, p_month date default null)\n  returns table (family_id uuid, family_name text, invoices text, invoice_ids uuid[],\n                 billed_minor bigint, would_raise_minor bigint)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare g uuid[];\nbegin\n  perform app.require_admin((select studio_id from term where id = p_term));\n  g := array(select x.family_id from app.billing_period_invoices(p_term, p_month) x);\n  return query\n  select b.family_id, f.name, b.numbers, b.invoice_ids, b.total_minor, l.amt\n    from app.billing_period_invoices(p_term, p_month) b\n    join family f on f.id = b.family_id\n    join (select l.family_id, sum(round(l.quantity * l.unit_minor) - l.discount_minor)::bigint amt\n            from app.billing_lines(p_term, p_month, g) l where l.family_id = any(g) group by l.family_id) l\n      on l.family_id = b.family_id\n   order by f.name;\nend $$;\n\ndrop function if exists app.create_billing_run(uuid, date, date);\ncreate function app.create_billing_run(p_term uuid, p_due date default null, p_month date default null,\n                                       p_include uuid[] default null, p_reason text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; run uuid; fam record; inv uuid; n int := 0; tot bigint := 0; fixed int;\n        pm date := date_trunc('month', p_month)::date; t term; inc uuid[]; o record;\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  if not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if exists (select 1 from billing_run where term_id = p_term and status = 'draft' and period_month is not distinct from pm) then\n    raise exception 'INVALID: there is already a draft run for this period — issue or discard it first' using errcode = 'check_violation';\n  end if;\n  -- Only families that really were skipped count as overrides.\n  inc := array(select g.family_id from app.billing_period_invoices(p_term, pm) g\n                where g.family_id = any(coalesce(p_include, '{}'::uuid[])));\n  if cardinality(inc) > 0 and length(coalesce(btrim(p_reason), '')) < 3 then\n    raise exception 'INVALID: say why these families should be billed again for this period' using errcode = 'check_violation';\n  end if;\n\n  insert into billing_run (studio_id, term_id, due_on, created_by, period_month)\n  values (sid, p_term, coalesce(p_due, current_date + 14), auth.uid(), pm) returning id into run;\n\n  for fam in\n    select l.family_id, jsonb_agg(jsonb_build_object(\n             'kind', 'tuition', 'description', l.description, 'quantity', l.quantity,\n             'unit_minor', l.unit_minor, 'discount_minor', l.discount_minor,\n             'student_id', l.student_id, 'class_id', l.class_id)) items, min(l.period_start) ps\n      from app.billing_lines(p_term, pm, inc) l group by l.family_id\n  loop\n    select fd.fixed into fixed from app.family_discounts_on(fam.family_id, coalesce(pm, t.starts_on),\n                                                         coalesce((pm + interval '1 month - 1 day')::date, t.ends_on)) fd;\n    inv := app.create_invoice(fam.family_id, fam.items, coalesce(p_due, current_date + 14), null,\n                              least(coalesce(fixed, 0), (select sum((x ->> 'unit_minor')::int * (x ->> 'quantity')::numeric - (x ->> 'discount_minor')::int)\n                                                          from jsonb_array_elements(fam.items) x)::int),\n                              false, p_term);\n    update invoice set billing_run_id = run where id = inv;\n    update invoice_item set period_start = fam.ps where invoice_id = inv;\n    n := n + 1;\n    tot := tot + (select total_minor from invoice where id = inv);\n  end loop;\n  if n = 0 then\n    delete from billing_run where id = run;\n    raise exception 'INVALID: everyone has already been invoiced for this period' using errcode = 'check_violation';\n  end if;\n  update billing_run set invoice_count = n, total_minor = tot where id = run;\n  for o in select g.family_id, g.numbers from app.billing_period_invoices(p_term, pm) g where g.family_id = any(inc) loop\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (sid, auth.uid(), 'override', 'family', o.family_id,\n            'Billed again for ' || coalesce(to_char(pm, 'FMMonth YYYY'), t.name) || ' despite ' || o.numbers || ': ' || btrim(p_reason));\n  end loop;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'create', 'billing_run', run, n || ' draft invoices' || coalesce(' for ' || to_char(pm, 'FMMonth YYYY'), ''));\n  return run;\nend $$;\n\nrevoke all on function app.billing_lines(uuid, date, uuid[]), app.billing_skipped(uuid, date),\n  app.create_billing_run(uuid, date, date, uuid[], text) from public;\ngrant execute on function app.billing_lines(uuid, date, uuid[]), app.billing_skipped(uuid, date),\n  app.create_billing_run(uuid, date, date, uuid[], text) to authenticated;\n\n-- ── 3. Ending a family discount ─────────────────────────────────────────────\nalter table family_discount add column ended_at timestamptz;\nalter table family_discount add column ended_by uuid references user_account(id) on delete set null;\n\n-- An ended discount applies to no run from then on, whatever its dates said.\ncreate or replace function app.family_discounts_on(p_family uuid, p_from date, p_to date)\n  returns table (pct int, fixed int)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(max(amount) filter (where kind = 'percent'), 0)::int, coalesce(max(amount) filter (where kind = 'fixed'), 0)::int\n    from family_discount where family_id = p_family and deleted_at is null and ended_at is null\n     and starts_on <= p_to and (ends_on is null or ends_on >= p_from);\n$$;\n\ncreate or replace function app.end_family_discount(p_id uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare d family_discount; fam text;\nbegin\n  select * into d from family_discount where id = p_id and deleted_at is null;\n  if d.id is null then raise exception 'NOT_FOUND: that discount' using errcode = 'no_data_found'; end if;\n  perform app.require_admin(d.studio_id);\n  if d.ended_at is not null then\n    raise exception 'INVALID: that discount has already ended' using errcode = 'check_violation';\n  end if;\n  update family_discount\n     set ended_at = now(), ended_by = auth.uid(),\n         ends_on = greatest(starts_on, least(coalesce(ends_on, current_date), current_date))\n   where id = p_id;\n  select name into fam from family where id = d.family_id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (d.studio_id, auth.uid(), 'end', 'family_discount', d.id,\n          fam || ': ' || case when d.kind = 'percent' then d.amount || '%' else app.gbp(d.amount) end || ' discount ended');\nend $$;\nrevoke all on function app.end_family_discount(uuid) from public;\ngrant execute on function app.end_family_discount(uuid) to authenticated;\n\n-- ── 5. Paying by bank transfer ──────────────────────────────────────────────\ncreate table studio_bank_details (\n  studio_id      uuid primary key references studio(id) on delete cascade,\n  payee_name     text not null check (length(btrim(payee_name)) between 2 and 140),\n  sort_code      text not null check (sort_code ~ '^\\d{2}-\\d{2}-\\d{2}$'),\n  account_number text not null check (account_number ~ '^\\d{8}$'),\n  iban           text check (iban is null or iban ~ '^[A-Z]{2}\\d{2}[A-Z0-9]{11,30}$'),\n  updated_by     uuid references user_account(id) on delete set null,\n  updated_at     timestamptz not null default now()\n);\nalter table studio_bank_details enable row level security; alter table studio_bank_details force row level security;\n-- Everyone at the school may read them: families need them to pay.\ncreate policy bank_details_read on studio_bank_details for select using (studio_id in (select app.studio_ids()));\ngrant select on studio_bank_details to authenticated;\ngrant all on studio_bank_details to service_role;\n\n-- Only the owner changes where the money goes.\ncreate or replace function app.set_bank_details(p_studio uuid, p_payee text, p_sort_code text,\n                                                p_account text, p_iban text default null)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sc text := regexp_replace(coalesce(p_sort_code, ''), '\\D', '', 'g');\n        acc text := regexp_replace(coalesce(p_account, ''), '\\D', '', 'g');\n        ib text := nullif(upper(regexp_replace(coalesce(p_iban, ''), '\\s', '', 'g')), '');\nbegin\n  if p_studio is null or not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the studio owner can change the bank details' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_payee), '') = '' and sc = '' and acc = '' and ib is null then\n    delete from studio_bank_details where studio_id = p_studio;\n  else\n    if length(coalesce(btrim(p_payee), '')) < 2 then\n      raise exception 'INVALID: enter the name on the account' using errcode = 'check_violation';\n    end if;\n    if length(sc) <> 6 then raise exception 'INVALID: a sort code has six digits' using errcode = 'check_violation'; end if;\n    if length(acc) <> 8 then raise exception 'INVALID: an account number has eight digits' using errcode = 'check_violation'; end if;\n    if ib is not null and ib !~ '^[A-Z]{2}\\d{2}[A-Z0-9]{11,30}$' then\n      raise exception 'INVALID: that IBAN does not look right' using errcode = 'check_violation';\n    end if;\n    insert into studio_bank_details (studio_id, payee_name, sort_code, account_number, iban, updated_by, updated_at)\n    values (p_studio, btrim(p_payee), substr(sc, 1, 2) || '-' || substr(sc, 3, 2) || '-' || substr(sc, 5, 2), acc, ib, auth.uid(), now())\n    on conflict (studio_id) do update set payee_name = excluded.payee_name, sort_code = excluded.sort_code,\n      account_number = excluded.account_number, iban = excluded.iban, updated_by = excluded.updated_by, updated_at = now();\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (p_studio, auth.uid(), 'update', 'studio', p_studio, 'Bank details for payments changed');\nend $$;\nrevoke all on function app.set_bank_details(uuid, text, text, text, text) from public;\ngrant execute on function app.set_bank_details(uuid, text, text, text, text) to authenticated;\n\n-- One reference for paying several invoices at once: the family's name and\n-- the end of its id, short enough for any banking app (UK limit 18).\ncreate or replace function app.payment_reference(p_name text, p_id uuid) returns text\n  language sql immutable as $$\n  select coalesce(nullif(upper(left(regexp_replace(regexp_replace(coalesce(p_name, ''), '\\s+family\\s*$', '', 'i'), '[^A-Za-z]', '', 'g'), 10)), ''), 'FAMILY')\n         || '-' || upper(right(replace(p_id::text, '-', ''), 4))\n$$;\n\n-- ── 6. Notifications about money and places ─────────────────────────────────\n-- What has already been announced, so nothing is said twice.\ncreate table invoice_notice (\n  invoice_id uuid not null references invoice(id) on delete cascade,\n  kind       text not null check (kind in ('issued', 'due_soon')),\n  sent_at    timestamptz not null default now(),\n  primary key (invoice_id, kind)\n);\nalter table invoice_notice enable row level security; alter table invoice_notice force row level security;\ngrant all on invoice_notice to service_role;\n\n-- A new invoice. Deferred to the end of the transaction, so the lines (and\n-- any credit taken off) are in place when the total is read. Invoices dated\n-- in the past (an import, the demo history) are not announced.\ncreate or replace function app.on_invoice_issued_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare i invoice; what text;\nbegin\n  select * into i from invoice where id = new.id;\n  if i.id is null or i.deleted_at is not null or i.status not in ('issued', 'part_paid', 'paid') then return null; end if;\n  if coalesce(i.issued_on, current_date) < current_date - 1 then return null; end if;\n  insert into invoice_notice (invoice_id, kind) values (i.id, 'issued') on conflict do nothing;\n  if not found then return null; end if;\n  select string_agg(description, ', ' order by created_at) into what from invoice_item\n   where invoice_id = i.id and deleted_at is null;\n  perform app.notify_family(i.family_id, 'invoice_issued',\n    'New invoice ' || i.number || ' ' || app.gbp(i.total_minor)\n      || case when i.status = 'paid' then ', paid from your credit' else ' due ' || to_char(i.due_on, 'FMDD Mon') end,\n    left(what, 140), '/family/payments');\n  return null;\nend $$;\ncreate constraint trigger invoice_issued_notify after insert or update of status on invoice\n  deferrable initially deferred\n  for each row execute function app.on_invoice_issued_notify();\n\n-- Money received (not credit moving about inside the ledger).\ncreate or replace function app.on_payment_received_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare num text;\nbegin\n  if new.succeeded_at is null or new.method not in ('card', 'direct_debit', 'bank_transfer', 'cash') then return null; end if;\n  if tg_op = 'UPDATE' and old.succeeded_at is not null then return null; end if;\n  select number into num from invoice where id = new.invoice_id;\n  perform app.notify_family(new.family_id, 'payment_received', 'Payment received: ' || app.gbp(new.amount_minor),\n    case when num is not null then 'Paid towards ' || num || '. Thank you.' else 'Held on your account for your next invoice. Thank you.' end,\n    '/family/payments');\n  return null;\nend $$;\ncreate trigger payment_received_notify after insert or update of succeeded_at on payment\n  for each row execute function app.on_payment_received_notify();\n\n-- Invoices due within three days. Each invoice is mentioned once. A family\n-- calling it hears about their own invoices (the bell is where they look);\n-- the office, or a scheduled job (no user), covers the whole school.\n-- Unlike app.notify_family this does not skip the caller: they are asking.\ncreate or replace function app.notify_invoices_due(p_studio uuid default null) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r record; g record; n int := 0;\nbegin\n  for r in select i.* from invoice i\n            where i.deleted_at is null and i.status in ('issued', 'part_paid') and i.total_minor > i.paid_minor\n              and i.due_on between current_date and current_date + 3\n              and (p_studio is null or i.studio_id = p_studio)\n              and (auth.uid() is null or app.is_admin(i.studio_id) or i.family_id in (select app.guardian_family_ids()))\n              and not exists (select 1 from invoice_notice x where x.invoice_id = i.id and x.kind = 'due_soon')\n  loop\n    insert into invoice_notice (invoice_id, kind) values (r.id, 'due_soon');\n    for g in select gu.studio_id, gu.user_id from guardian gu\n              where gu.family_id = r.family_id and gu.user_id is not null and gu.deleted_at is null loop\n      continue when not app.wants(g.user_id, 'invoice_issued', 'in_app');\n      insert into notification (studio_id, user_id, kind, title, body, href)\n      values (g.studio_id, g.user_id, 'invoice_issued',\n              r.number || ' is due ' || case when r.due_on = current_date then 'today' when r.due_on = current_date + 1 then 'tomorrow'\n                                             else 'on ' || to_char(r.due_on, 'FMDay DD Mon') end,\n              app.gbp(r.total_minor - r.paid_minor) || ' to pay. Bank details are in Payments.', '/family/payments');\n    end loop;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\nrevoke all on function app.notify_invoices_due(uuid) from public;\ngrant execute on function app.notify_invoices_due(uuid) to authenticated, service_role;\n\n-- A place confirmed for an event, competition or show.\ncreate or replace function app.on_participant_confirmed_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare ev studio_event; s student;\nbegin\n  if new.status <> 'confirmed' or new.deleted_at is not null then return null; end if;\n  if tg_op = 'UPDATE' and old.status = 'confirmed' then return null; end if;\n  select * into ev from studio_event where id = new.event_id;\n  select * into s from student where id = new.student_id;\n  if ev.id is null or s.id is null or ev.starts_at < now() then return null; end if;\n  perform app.notify_family(s.family_id, 'event_invite', s.first_name || '’s place is confirmed: ' || ev.title,\n    to_char(ev.starts_at, 'FMDay DD FMMonth') || coalesce(' · ' || ev.venue, '')\n      || case when coalesce(ev.cost_minor, 0) > 0 then ' · fee ' || app.gbp(ev.cost_minor) else '' end,\n    '/family/events');\n  return null;\nend $$;\ncreate trigger participant_confirmed_notify after insert or update of status on event_participant\n  for each row execute function app.on_participant_confirmed_notify();\n\n-- ── 7. Private lessons are charged, and families see what is coming ────────\n-- A confirmed (published) private lesson with a price raises a draft invoice\n-- for the office to check and send. A changed price updates the draft; a\n-- cancelled lesson takes its draft away. Anything already sent is left to\n-- the office (a credit note).\ncreate or replace function app.on_private_lesson_charge() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; it record; inv uuid; descr text;\nbegin\n  if new.kind <> 'private_lesson' or new.student_id is null then return null; end if;\n  -- Loading history (an import, the demo) raises nothing.\n  if auth.uid() is null and current_setting('app.quiet', true) = 'on' then return null; end if;\n  select * into s from student where id = new.student_id;\n  descr := 'Private lesson — ' || s.first_name || ', ' || to_char(new.starts_at, 'FMDy DD Mon');\n  select ii.id, ii.invoice_id, i.status into it from invoice_item ii join invoice i on i.id = ii.invoice_id\n   where ii.event_id = new.id and ii.deleted_at is null and i.deleted_at is null and i.status <> 'void'\n   order by i.created_at desc limit 1;\n\n  if new.status = 'published' and new.deleted_at is null and coalesce(new.cost_minor, 0) > 0 then\n    if it.id is null then\n      inv := app.create_invoice_internal(s.family_id, jsonb_build_array(jsonb_build_object(\n               'kind', 'private_lesson', 'description', descr, 'quantity', 1,\n               'unit_minor', new.cost_minor, 'student_id', s.id)),\n             greatest(new.starts_at::date, current_date + 7), null, 0, false, null);\n      update invoice_item set event_id = new.id where invoice_id = inv;\n    elsif it.status = 'draft' then\n      update invoice_item set unit_minor = new.cost_minor, description = descr where id = it.id;\n    end if;\n  elsif it.id is not null and it.status = 'draft' then\n    update invoice set deleted_at = now() where id = it.invoice_id and status = 'draft';\n  end if;\n  return null;\nend $$;\ncreate trigger private_lesson_charge after insert or update of status, cost_minor, starts_at, deleted_at on studio_event\n  for each row execute function app.on_private_lesson_charge();\n\n-- Everything a family can expect to pay soon, per child, with its state:\n-- 'expected' (nothing sent yet), 'invoiced' or 'paid'.\ncreate or replace function app.upcoming_costs(p_family uuid default null)\n  returns table (family_id uuid, student_id uuid, child text, kind text, title text, due_on date,\n                 amount_minor bigint, state text, invoice_number text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare fams uuid[]; nt term; cur term; nm date := (date_trunc('month', current_date) + interval '1 month')::date;\nbegin\n  if p_family is not null then\n    if not (p_family in (select app.guardian_family_ids())\n            or app.is_admin((select f.studio_id from family f where f.id = p_family))) then\n      raise exception 'FORBIDDEN: not your family' using errcode = 'insufficient_privilege';\n    end if;\n    fams := array[p_family];\n  else\n    fams := array(select app.guardian_family_ids());\n  end if;\n\n  return query\n  with kids as (\n    select s.id, s.family_id, s.first_name, s.studio_id from student s\n     where s.family_id = any(fams) and s.deleted_at is null\n  ),\n  inv_state as (\n    -- The state of an invoice line, by what it is for.\n    select ii.student_id, ii.event_id, ii.class_id, ii.period_start, i.term_id, i.number, i.due_on, i.status\n      from invoice_item ii join invoice i on i.id = ii.invoice_id\n     where ii.deleted_at is null and i.deleted_at is null and i.status <> 'void'\n       and i.family_id = any(fams)\n  ),\n  nxt as (\n    select t.* from term t where t.deleted_at is null and t.starts_on > current_date\n       and t.studio_id in (select k.studio_id from kids k)\n     order by t.starts_on limit 1\n  ),\n  items as (\n    -- Next term's fees: classes already set up for it, or an estimate from\n    -- this term's term-priced classes.\n    select k.family_id, k.id sid, k.first_name, 'term'::text kd,\n           c.name || ' — ' || t.name title, t.starts_on d, coalesce(e.price_minor, c.price_minor)::bigint amt,\n           x.status st, x.number num\n      from kids k join enrolment e on e.student_id = k.id and e.deleted_at is null and e.status = 'active'\n      join class c on c.id = e.class_id and c.deleted_at is null and c.pricing in ('term', 'one_off')\n      join nxt t on t.id = c.term_id\n      left join lateral (select s.status, s.number from inv_state s where s.student_id = k.id and s.class_id = c.id\n                          and s.term_id = t.id order by s.status = 'paid' desc limit 1) x on true\n     where coalesce(e.price_minor, c.price_minor) > 0\n    union all\n    select k.family_id, k.id, k.first_name, 'term',\n           coalesce((select t.name from nxt t), 'Next term') || ' fees (estimate)',\n           (select t.starts_on from nxt t),\n           sum(coalesce(e.price_minor, c.price_minor))::bigint, null, null\n      from kids k join enrolment e on e.student_id = k.id and e.deleted_at is null and e.status = 'active'\n      join class c on c.id = e.class_id and c.deleted_at is null and c.pricing = 'term'\n      join term t on t.id = c.term_id and current_date between t.starts_on and t.ends_on\n     where not exists (select 1 from enrolment e2 join class c2 on c2.id = e2.class_id join nxt n on n.id = c2.term_id\n                        where e2.student_id = k.id and e2.deleted_at is null)\n     group by k.family_id, k.id, k.first_name\n    union all\n    -- Next month's fee for monthly classes.\n    select k.family_id, k.id, k.first_name, 'month', c.name || ' — ' || to_char(nm, 'FMMonth'), nm,\n           coalesce(e.price_minor, c.price_minor)::bigint, x.status, x.number\n      from kids k join enrolment e on e.student_id = k.id and e.deleted_at is null and e.status = 'active'\n      join class c on c.id = e.class_id and c.deleted_at is null and c.pricing = 'monthly'\n      join term t on t.id = c.term_id and nm between t.starts_on and t.ends_on\n      left join lateral (select s.status, s.number from inv_state s where s.student_id = k.id and s.class_id = c.id\n                          and s.period_start = nm limit 1) x on true\n     where coalesce(e.price_minor, c.price_minor) > 0\n    union all\n    -- Confirmed events, competitions and shows with a fee.\n    select k.family_id, k.id, k.first_name, ev.kind::text, ev.title, coalesce(x.due_on, ev.starts_at::date),\n           ev.cost_minor::bigint, x.status, x.number\n      from kids k join event_participant p on p.student_id = k.id and p.status = 'confirmed' and p.deleted_at is null\n      join studio_event ev on ev.id = p.event_id and ev.deleted_at is null and ev.status <> 'cancelled'\n      left join lateral (select s.status, s.number, s.due_on from inv_state s where s.event_id = ev.id and s.student_id = k.id\n                          order by s.status = 'paid' desc limit 1) x on true\n     where coalesce(ev.cost_minor, 0) > 0 and ev.kind <> 'private_lesson'\n       and (ev.starts_at >= current_date or (x.status is not null and x.status <> 'paid'))\n    union all\n    -- Private lessons.\n    select k.family_id, k.id, k.first_name, 'private_lesson', 'Private lesson', coalesce(x.due_on, ev.starts_at::date),\n           ev.cost_minor::bigint, x.status, x.number\n      from kids k join studio_event ev on ev.student_id = k.id and ev.kind = 'private_lesson'\n                   and ev.deleted_at is null and ev.status = 'published'\n      left join lateral (select s.status, s.number, s.due_on from inv_state s where s.event_id = ev.id\n                          order by s.status = 'paid' desc limit 1) x on true\n     where coalesce(ev.cost_minor, 0) > 0\n       and (ev.starts_at >= current_date or (x.status is not null and x.status not in ('paid', 'draft')))\n    union all\n    -- Exams entered.\n    select k.family_id, k.id, k.first_name, 'exam', x0.board || ' ' || en.grade || ' exam', coalesce(i.due_on, x0.exam_on),\n           en.fee_minor::bigint, i.status, i.number\n      from kids k join exam_entry en on en.student_id = k.id and en.status = 'entered' and en.fee_minor > 0\n      join exam_session x0 on x0.id = en.session_id and x0.deleted_at is null\n      left join invoice i on i.id = en.invoice_id and i.deleted_at is null and i.status <> 'void'\n     where x0.exam_on >= current_date or (i.status is not null and i.status <> 'paid')\n    union all\n    -- Costumes for upcoming shows (the office collects these separately).\n    select k.family_id, k.id, k.first_name, 'costume', ci.name || ' — ' || ev.title, ev.starts_at::date,\n           ci.price_minor::bigint, null, null\n      from kids k join costume_order co on co.student_id = k.id and co.status <> 'returned'\n      join costume_item ci on ci.id = co.item_id and ci.deleted_at is null and ci.price_minor > 0\n      join studio_event ev on ev.id = ci.event_id and ev.deleted_at is null and ev.starts_at >= current_date\n  )\n  select r.family_id, r.sid, r.first_name, r.kd, r.title, r.d, r.amt,\n         case when r.st = 'paid' then 'paid' when r.st in ('issued', 'part_paid', 'refunded') then 'invoiced' else 'expected' end,\n         case when r.st in ('issued', 'part_paid', 'refunded', 'paid') then r.num end\n    from items r\n   order by r.first_name, r.d nulls last, r.title;\nend $$;\nrevoke all on function app.upcoming_costs(uuid) from public;\ngrant execute on function app.upcoming_costs(uuid) to authenticated;\n\n-- ── 8. Payment reminders, many families at once ─────────────────────────────\n-- The same words for everyone, filled in per family from what they owe:\n-- {{guardian_name}}, {{amount}}, {{invoice_number}}, {{due_date}}.\ncreate or replace function app.fill_payment_reminder(p_family uuid, p_text text) returns text\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare f family; who text; amt bigint; nums text; due date;\nbegin\n  select * into f from family where id = p_family and deleted_at is null;\n  perform app.require_admin(f.studio_id);\n  select split_part(full_name, ' ', 1) into who from guardian\n   where family_id = p_family and deleted_at is null order by is_primary desc, created_at limit 1;\n  select sum(total_minor - paid_minor), string_agg(number, ', ' order by due_on, number), min(due_on)\n    into amt, nums, due from invoice\n   where family_id = p_family and deleted_at is null and status in ('issued', 'part_paid', 'refunded')\n     and total_minor > paid_minor and due_on < current_date;\n  if amt is null then\n    select sum(total_minor - paid_minor), string_agg(number, ', ' order by due_on, number), min(due_on)\n      into amt, nums, due from invoice\n     where family_id = p_family and deleted_at is null and status in ('issued', 'part_paid', 'refunded')\n       and total_minor > paid_minor;\n  end if;\n  return replace(replace(replace(replace(coalesce(p_text, ''),\n           '{{guardian_name}}', coalesce(who, 'there')),\n           '{{amount}}', app.gbp(coalesce(amt, 0))),\n           '{{invoice_number}}', coalesce(nums, '')),\n           '{{due_date}}', coalesce(to_char(due, 'FMDD Mon'), ''));\nend $$;\n\ncreate or replace function app.send_payment_reminders(p_families uuid[], p_subject text, p_body text) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare fid uuid; f family; n int := 0; subj text; body text; cid uuid; owed bigint;\nbegin\n  if length(coalesce(btrim(p_body), '')) < 10 or coalesce(btrim(p_subject), '') = '' then\n    raise exception 'INVALID: a reminder needs a subject and a message' using errcode = 'check_violation';\n  end if;\n  foreach fid in array coalesce(p_families, '{}'::uuid[]) loop\n    select * into f from family where id = fid and deleted_at is null;\n    continue when f.id is null;\n    perform app.require_admin(f.studio_id);\n    select sum(total_minor - paid_minor) into owed from invoice\n     where family_id = fid and deleted_at is null and status in ('issued', 'part_paid', 'refunded') and total_minor > paid_minor;\n    continue when coalesce(owed, 0) <= 0;\n    subj := app.fill_payment_reminder(fid, p_subject);\n    body := app.fill_payment_reminder(fid, p_body);\n    insert into communication (studio_id, kind, channel, family_id, subject, body, sent_by)\n    values (f.studio_id, 'direct', 'in_app', fid, subj, body, auth.uid()) returning id into cid;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (f.studio_id, auth.uid(), 'remind', 'family', fid, 'Payment reminder, ' || app.gbp(owed) || ' owed');\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n-- When the family was last sent one (the audit trail itself is the owner's).\ncreate or replace function app.last_payment_reminder(p_family uuid) returns timestamptz\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select max(a.at) from audit_log a join family f on f.id = a.entity_id\n   where a.entity = 'family' and a.entity_id = p_family and a.action = 'remind' and app.is_admin(f.studio_id)\n$$;\n\nrevoke all on function app.fill_payment_reminder(uuid, text), app.send_payment_reminders(uuid[], text, text),\n  app.last_payment_reminder(uuid) from public;\ngrant execute on function app.fill_payment_reminder(uuid, text), app.send_payment_reminders(uuid[], text, text),\n  app.last_payment_reminder(uuid) to authenticated;\n"},{name:"0046_family_fixes.sql",sql:"-- ============================================================================\n-- 0046 · Family fixes from the end-user panel review\n-- ----------------------------------------------------------------------------\n--   UR-03  Invitations link the guardian record the office already holds.\n--   UR-05  A guardian edits only their own row, and only contact fields.\n--   UR-06  A public adult drop-in books the adult, never a child; every\n--          booking path enforces the class's age limits.\n--   UR-16  Parents approve, or switch off, a teenager's own login; the\n--          school sets the minimum age (13–18).\n--   UR-17  Shared care: each guardian's messages to the studio are private\n--          to them and the office; the office can restrict what a guardian\n--          sees; each child has a collection list the teacher sees.\n--   UR-21  Adult participants: a student row flagged as adult, linked to the\n--          guardian row that is the same person. They sign in as that\n--          guardian and use the family screens for their own bookings.\n--   UR-54  Out-of-age class requests are refused with a clear reason.\n-- ============================================================================\n\n-- ── Columns ────────────────────────────────────────────────────────────────\nalter table student add column is_adult boolean not null default false;\n-- The guardian row that is this same person (an adult participant).\nalter table student add column self_guardian_id uuid references guardian(id) on delete set null;\n-- Who last switched a teenager's login off, and when (UR-16).\nalter table student add column login_switched_off_by uuid references user_account(id) on delete set null;\nalter table student add column login_switched_off_at timestamptz;\ncreate unique index student_self_guardian_unique on student (self_guardian_id)\n  where self_guardian_id is not null and deleted_at is null;\n\n-- How a booking arrived, for the office (UR-06).\nalter table drop_in_booking add column source_note text;\n\n-- A direct message that belongs to one guardian's conversation with the\n-- studio (UR-17). Null means the whole family sees it, as before.\nalter table communication add column private_to uuid references user_account(id) on delete set null;\n\n-- ── UR-06 · Age limits on every booking path ───────────────────────────────\ncreate or replace function app.age_label(p_min smallint, p_max smallint) returns text\n  language sql immutable as $$\n  select case when p_min is not null and p_max is not null then 'ages ' || p_min || '–' || p_max\n              when p_min is not null then 'ages ' || p_min || ' and over'\n              else 'ages up to ' || p_max end\n$$;\n\n-- Raises when a person of this date of birth is outside the class's range on\n-- the given day. Ages are whole years, as on the timetable.\n--\n-- p_office: the school office may place a child just outside a children's\n-- range on purpose (moving up early, an imported history), but nobody puts\n-- an under-18 into an adult class, or an adult into a children's class.\ncreate or replace function app.check_class_age(p_class uuid, p_dob date, p_on date, p_name text, p_office boolean default false)\n  returns void\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare c class; yrs int;\nbegin\n  select * into c from class where id = p_class;\n  if c.id is null or (c.age_min is null and c.age_max is null) or p_dob is null then return; end if;\n  yrs := extract(year from age(coalesce(p_on, current_date), p_dob));\n  if p_office and not ((c.age_min >= 18 and yrs < 18) or (c.age_max < 18 and yrs >= 18)) then return; end if;\n  if (c.age_min is not null and yrs < c.age_min) or (c.age_max is not null and yrs > c.age_max) then\n    raise exception 'INVALID: % is %, and % is for %', coalesce(p_name, 'This dancer'), yrs, c.name,\n      app.age_label(c.age_min, c.age_max) using errcode = 'check_violation';\n  end if;\nend $$;\n\n-- One trigger for enrolments, waiting lists, trials and drop-ins: every path,\n-- whichever function or screen it comes from. Trusted server jobs\n-- (service_role: the seed) are exempt; families, the public, students and\n-- teachers are held to the class's range; the office to the adult boundary.\ncreate or replace function app.enforce_class_age() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; on_day date; cls uuid; dob date; nm text;\nbegin\n  if coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon') then return new; end if;\n  if tg_table_name <> 'drop_in_booking' then cls := new.class_id; end if;\n  if tg_table_name = 'enrolment' then\n    if new.status <> 'active' then return new; end if;\n    if tg_op = 'UPDATE' and new.class_id = old.class_id and new.student_id = old.student_id and old.status = 'active' then\n      return new;\n    end if;\n    on_day := greatest(coalesce(new.started_on, current_date), current_date);\n  elsif tg_table_name = 'waitlist_entry' then\n    if new.status not in ('waiting', 'offered') then return new; end if;\n    if tg_op = 'UPDATE' and new.class_id = old.class_id and new.student_id = old.student_id then return new; end if;\n    on_day := current_date;\n  elsif tg_table_name = 'trial' then\n    if new.status not in ('requested', 'booked') then return new; end if;\n    if tg_op = 'UPDATE' and new.class_id = old.class_id and new.student_id is not distinct from old.student_id\n       and new.session_id is not distinct from old.session_id then return new; end if;\n    select starts_at::date into on_day from class_session where id = new.session_id;\n  else -- drop_in_booking\n    if new.status not in ('booked', 'held') then return new; end if;\n    select cs.class_id, cs.starts_at::date into cls, on_day from class_session cs where cs.id = new.session_id;\n  end if;\n  if tg_table_name = 'trial' and new.student_id is null then\n    select e.child_dob, e.child_name into dob, nm from enquiry e where e.id = new.enquiry_id;\n  else\n    select * into s from student where id = new.student_id;\n    dob := s.date_of_birth; nm := s.first_name;\n  end if;\n  perform app.check_class_age(cls, dob, on_day, nm, app.is_admin((select studio_id from class where id = cls)));\n  return new;\nend $$;\n\ncreate trigger enrolment_age_check before insert or update of class_id, student_id, status on enrolment\n  for each row execute function app.enforce_class_age();\ncreate trigger waitlist_age_check before insert or update of class_id, student_id on waitlist_entry\n  for each row execute function app.enforce_class_age();\ncreate trigger trial_age_check before insert or update of class_id, student_id, session_id on trial\n  for each row execute function app.enforce_class_age();\ncreate trigger drop_in_age_check before insert on drop_in_booking\n  for each row execute function app.enforce_class_age();\n\n-- A request for a place is refused up front, with the same words (UR-54).\ncreate or replace function app.request_class_place(p_student uuid, p_class uuid, p_note text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; c class; rid uuid;\nbegin\n  s := app.my_child(p_student);\n  select * into c from class where id = p_class and studio_id = s.studio_id;\n  if c.id is null or not app.class_open_to_family(p_class) then\n    raise exception 'NOT_FOUND: that class' using errcode = 'no_data_found';\n  end if;\n  perform app.check_class_age(c.id, s.date_of_birth, current_date, s.first_name);\n  if exists (select 1 from enrolment where student_id = s.id and class_id = c.id and status = 'active' and deleted_at is null) then\n    raise exception 'INVALID: % is already in %', s.first_name, c.name using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from studio_request where student_id = s.id and class_id = c.id and action = 'join_class'\n              and status in ('open', 'in_progress') and deleted_at is null) then\n    raise exception 'INVALID: you have already asked for this — the office will be in touch' using errcode = 'check_violation';\n  end if;\n  insert into studio_request (studio_id, family_id, student_id, class_id, kind, action, subject, body, raised_by)\n  values (s.studio_id, s.family_id, s.id, c.id, 'other', 'join_class',\n          'Place for ' || s.first_name || ' in ' || c.name,\n          coalesce(nullif(btrim(p_note), ''), 'Please could ' || s.first_name || ' join ' || c.name || '?'), auth.uid())\n  returning id into rid;\n  return rid;\nend $$;\n\n-- ── UR-06 / UR-21 · The public adult drop-in books the adult ───────────────\n-- The adult participant for a guardian row: reuse it, or make it.\ncreate or replace function app.adult_participant_for(p_guardian uuid, p_dob date, p_emergency_name text, p_emergency_phone text)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g guardian; kid uuid; nm text;\nbegin\n  select * into g from guardian where id = p_guardian and deleted_at is null;\n  if g.id is null then raise exception 'NOT_FOUND: guardian' using errcode = 'no_data_found'; end if;\n  select id into kid from student where self_guardian_id = g.id and deleted_at is null;\n  if kid is not null then\n    if p_dob is not null then\n      update student set date_of_birth = p_dob where id = kid and date_of_birth is distinct from p_dob;\n    end if;\n    return kid;\n  end if;\n  nm := btrim(g.full_name);\n  insert into student (studio_id, family_id, first_name, last_name, date_of_birth, is_adult, self_guardian_id)\n  values (g.studio_id, g.family_id, split_part(nm, ' ', 1),\n          coalesce(nullif(regexp_replace(nm, '^\\S+\\s*', ''), ''), '—'),\n          -- An adult who did not give a date of birth has confirmed they are\n          -- 18 or over; the record says so without inventing a birthday.\n          coalesce(p_dob, make_date(extract(year from current_date)::int - 18, 1, 1)), true, g.id)\n  returning id into kid;\n  if coalesce(btrim(p_emergency_phone), '') <> '' then\n    insert into emergency_contact (studio_id, student_id, full_name, phone, priority)\n    values (g.studio_id, kid, coalesce(nullif(btrim(p_emergency_name), ''), 'Emergency contact'), btrim(p_emergency_phone), 1);\n  end if;\n  return kid;\nend $$;\nrevoke all on function app.adult_participant_for(uuid, date, text, text) from public, authenticated, anon;\n\ncreate or replace function app.public_adult_drop_in(p_slug text, p_session uuid, p_form jsonb) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; fam uuid; gid uuid; kid uuid; r jsonb; em text; dob date; famname text; cls class;\nbegin\n  select * into st from studio where slug = lower(p_slug) and deleted_at is null;\n  if st.id is null or not app.studio_writable(st.id) then raise exception 'NOT_FOUND: that school' using errcode = 'no_data_found'; end if;\n  if coalesce(p_form ->> 'website', '') <> '' then return 'ok'; end if;\n  if coalesce(btrim(p_form ->> 'name'), '') = '' or coalesce(btrim(p_form ->> 'phone'), '') = ''\n     or coalesce(p_form ->> 'email', '') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' or coalesce(btrim(p_form ->> 'emergency_phone'), '') = '' then\n    raise exception 'INVALID: please give your name, email, phone and someone to ring in an emergency' using errcode = 'check_violation';\n  end if;\n  if not exists (select 1 from app.drop_in_sessions(st.id) d where d.session_id = p_session) then\n    raise exception 'INVALID: that class is full or no longer open — please pick another' using errcode = 'check_violation';\n  end if;\n  select c.* into cls from class c join class_session cs on cs.class_id = c.id where cs.id = p_session;\n  begin\n    dob := nullif(p_form ->> 'date_of_birth', '')::date;\n  exception when others then\n    raise exception 'INVALID: please check your date of birth' using errcode = 'check_violation';\n  end;\n  if dob is not null and (dob > current_date or dob < current_date - interval '110 years') then\n    raise exception 'INVALID: please check your date of birth' using errcode = 'check_violation';\n  end if;\n  -- An adult class needs a date of birth or a plain \"I am 18 or over\".\n  if coalesce(cls.age_min, 0) >= 18 and dob is null\n     and coalesce(p_form ->> 'adult_confirm', '') not in ('true', 't', 'yes', 'on') then\n    raise exception 'INVALID: please confirm you are 18 or over — this class is for adults' using errcode = 'check_violation';\n  end if;\n  perform app.public_guard(st.id, 'drop_in', p_form);\n  em := lower(btrim(p_form ->> 'email'));\n  -- The person is identified by their email. Prefer the row whose name also\n  -- matches, so two adults sharing an address are kept apart.\n  select g.id, g.family_id into gid, fam from guardian g\n   where g.studio_id = st.id and lower(btrim(g.email)) = em and g.deleted_at is null\n   order by (lower(btrim(g.full_name)) = lower(btrim(p_form ->> 'name'))) desc, g.created_at limit 1;\n  if gid is null then\n    insert into family (studio_id, name) values (st.id, regexp_replace(btrim(p_form ->> 'name'), '^.*\\s', '') || ' (adult)') returning id into fam;\n    insert into guardian (studio_id, family_id, full_name, email, phone, is_primary, relationship, marketing_consent)\n    values (st.id, fam, btrim(p_form ->> 'name'), em, btrim(p_form ->> 'phone'), true, 'Self',\n            coalesce(p_form ->> 'marketing', '') in ('true', 't', 'yes', 'on'))\n    returning id into gid;\n  else\n    select name into famname from family where id = fam;\n  end if;\n  -- Never a child: the adult's own participant record.\n  kid := app.adult_participant_for(gid, dob, p_form ->> 'emergency_name', p_form ->> 'emergency_phone');\n  r := app.book_drop_in_unchecked(p_session, kid, true);\n  update drop_in_booking set source_note = 'Booked by public form'\n         || case when famname is not null then '; matched to existing family ' || famname else '' end\n   where id = (r ->> 'id')::uuid;\n  if famname is not null then\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (st.id, null, 'book', 'drop_in_booking', (r ->> 'id')::uuid,\n            'Public adult drop-in for ' || btrim(p_form ->> 'name') || ' matched to existing family ' || famname);\n  end if;\n  return case when r ->> 'paid_with' = 'hold' then 'held' else 'ok' end;\nend $$;\ngrant execute on function app.public_adult_drop_in(text, uuid, jsonb) to anon, authenticated;\n\n-- ── UR-05 · Guardians edit only their own row ──────────────────────────────\ndrop policy if exists guardian_self_update on guardian;\ncreate policy guardian_self_update on guardian for update\n  using (deleted_at is null and user_id = auth.uid())\n  with check (user_id = auth.uid());\n\n-- Linking fields and the office's own fields are the office's. SECURITY\n-- INVOKER, like the column guards in 0038: a person updating a row directly\n-- runs as 'authenticated' and is checked here. A trusted function runs as its\n-- owner and may change contact fields, but linking a login to a row is still\n-- allowed only inside app.accept_invitation, for the person accepting, on an\n-- unlinked row whose family and email match an invitation they accepted in\n-- this very transaction (UR-03).\ncreate or replace function app.guardian_self_edit_guard() returns trigger\n  language plpgsql security invoker set search_path = public, app, pg_temp as $$\ndeclare me uuid := auth.uid();\nbegin\n  if me is null or app.is_admin(old.studio_id) then return new; end if;\n  if new.user_id is distinct from old.user_id then\n    if old.user_id is null and new.user_id = me\n       and current_user <> 'authenticated'\n       and current_setting('app.accepting_invitation', true) = old.id::text\n       and new.family_id = old.family_id and new.studio_id = old.studio_id\n       and new.deleted_at is not distinct from old.deleted_at\n       and exists (select 1 from studio_invitation i\n                    where i.accepted_by = me and i.accepted_at = now() and i.studio_id = old.studio_id\n                      and i.email = lower(btrim(old.email))\n                      and (i.family_id = old.family_id\n                           or exists (select 1 from student s where s.id = i.student_id and s.family_id = old.family_id))) then\n      return new;\n    end if;\n    raise exception 'FORBIDDEN: only the office can change who is linked to a family' using errcode = 'insufficient_privilege';\n  end if;\n  if new.family_id is distinct from old.family_id or new.studio_id is distinct from old.studio_id\n     or new.deleted_at is distinct from old.deleted_at then\n    raise exception 'FORBIDDEN: only the office can change who is linked to a family' using errcode = 'insufficient_privilege';\n  end if;\n  if current_user = 'authenticated' and (new.is_primary is distinct from old.is_primary\n     or new.receives_billing is distinct from old.receives_billing\n     or new.relationship is distinct from old.relationship) then\n    raise exception 'FORBIDDEN: only the office can change the main contact, who receives invoices or a relationship'\n      using errcode = 'insufficient_privilege';\n  end if;\n  return new;\nend $$;\n\n-- \"Ask the office to change\" another guardian's details (UR-05).\ncreate or replace function app.ask_to_change_guardian(p_guardian uuid, p_body text) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g guardian; rid uuid;\nbegin\n  select * into g from guardian where id = p_guardian and deleted_at is null\n     and family_id in (select app.guardian_family_ids());\n  if g.id is null then raise exception 'FORBIDDEN: that is not someone in your family' using errcode = 'insufficient_privilege'; end if;\n  if coalesce(btrim(p_body), '') = '' then\n    raise exception 'INVALID: say what should change' using errcode = 'check_violation';\n  end if;\n  insert into studio_request (studio_id, family_id, kind, subject, body, raised_by)\n  values (g.studio_id, g.family_id, 'other', 'Change details for ' || g.full_name, btrim(p_body), auth.uid())\n  returning id into rid;\n  return rid;\nend $$;\ngrant execute on function app.ask_to_change_guardian(uuid, text) to authenticated;\n\n-- ── UR-03 / UR-16 / UR-21 · Accepting an invitation ────────────────────────\n-- Links the guardian row for an invitation's family and email, or makes one.\n-- Refuses rather than guesses: two unlinked rows with the same email, a row\n-- already linked to someone else, or an email that belongs to another family.\n-- p_dry: check only (run before anything is written, so the person sees the\n-- reason rather than a clash further on).\ncreate or replace function app.link_invited_guardian(p_inv studio_invitation, p_family uuid, p_me uuid, p_name text,\n                                                     p_dry boolean default false)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare gid uuid; n_free int; n_taken int; n_other int;\nbegin\n  select id into gid from guardian where family_id = p_family and user_id = p_me and deleted_at is null limit 1;\n  if gid is not null then return gid; end if;\n  select count(*) filter (where family_id = p_family and user_id is null),\n         count(*) filter (where family_id = p_family and user_id is not null),\n         count(*) filter (where family_id <> p_family)\n    into n_free, n_taken, n_other\n    from guardian where studio_id = p_inv.studio_id and deleted_at is null and lower(btrim(email)) = p_inv.email;\n  if n_free > 1 then\n    raise exception 'INVALID: the school has two records with this email in the family — ask the office to merge them, then try again'\n      using errcode = 'check_violation';\n  elsif p_dry and (n_free = 1 or (n_taken = 0 and n_other = 0)) then\n    return null;\n  elsif n_free = 1 then\n    select id into gid from guardian where family_id = p_family and user_id is null and deleted_at is null\n       and lower(btrim(email)) = p_inv.email;\n    perform set_config('app.accepting_invitation', gid::text, true);\n    update guardian set user_id = p_me, updated_at = now() where id = gid;\n    perform set_config('app.accepting_invitation', '', true);\n  elsif n_taken > 0 then\n    raise exception 'INVALID: this person already has an account — ask the office' using errcode = 'check_violation';\n  elsif n_other > 0 then\n    raise exception 'INVALID: this email belongs to a parent in another family at this school — ask the office to check the invitation'\n      using errcode = 'check_violation';\n  else\n    insert into guardian (studio_id, family_id, user_id, full_name, email)\n    values (p_inv.studio_id, p_family, p_me, p_name, p_inv.email) returning id into gid;\n  end if;\n  return gid;\nend $$;\nrevoke all on function app.link_invited_guardian(studio_invitation, uuid, uuid, text, boolean) from public, authenticated, anon;\n\ncreate or replace function app.accept_invitation(p_token text, p_full_name text)\n  returns table (studio_id uuid, role app_role)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare inv studio_invitation; me uuid := auth.uid(); claimed text := lower(auth.jwt() ->> 'email');\n        nm text := btrim(coalesce(p_full_name, '')); gid uuid; s student; eff app_role; adult boolean := false;\n        by_guardian boolean;\nbegin\n  if me is null then raise exception 'FORBIDDEN: sign in to accept an invitation' using errcode = 'insufficient_privilege'; end if;\n  select * into inv from studio_invitation where token_hash = app.hash_token(p_token) for update;\n  if inv.id is null then raise exception 'INVALID: this invitation link is not valid' using errcode = 'check_violation'; end if;\n  if inv.accepted_at is not null then raise exception 'INVALID: this invitation has already been used' using errcode = 'check_violation'; end if;\n  if inv.revoked_at is not null then raise exception 'INVALID: this invitation was withdrawn' using errcode = 'check_violation'; end if;\n  if inv.expires_at <= now() then raise exception 'INVALID: this invitation has expired — ask for a new one' using errcode = 'check_violation'; end if;\n  if not exists (select 1 from studio s where s.id = inv.studio_id and s.status not in ('suspended', 'cancelled')) then\n    raise exception 'INVALID: this school is not taking new members at the moment' using errcode = 'check_violation';\n  end if;\n  if claimed is not null and claimed <> inv.email then\n    raise exception 'FORBIDDEN: this invitation was sent to %', inv.email using errcode = 'insufficient_privilege';\n  end if;\n  if length(nm) < 2 then nm := coalesce(inv.full_name, split_part(inv.email, '@', 1)); end if;\n\n  eff := inv.role;\n  if inv.role = 'student' then\n    select * into s from student where id = inv.student_id and deleted_at is null;\n    if s.id is null then raise exception 'INVALID: this login is for a student who is no longer on the books' using errcode = 'check_violation'; end if;\n    if s.user_id is not null and s.user_id <> me then\n      raise exception 'INVALID: this person already has an account — ask the office' using errcode = 'check_violation';\n    end if;\n    -- An adult manages their own account: no guardian approval, and they use\n    -- the family screens for their bookings and payments (UR-21).\n    adult := s.is_adult or extract(year from age(current_date, s.date_of_birth)) >= 18;\n    if adult then eff := 'guardian'; end if;\n  end if;\n\n  if inv.role = 'guardian' then\n    perform app.link_invited_guardian(inv, inv.family_id, me, nm, true);\n  elsif adult and (s.self_guardian_id is null or exists (select 1 from guardian where id = s.self_guardian_id\n                     and (deleted_at is not null or (user_id is not null and user_id <> me)))) then\n    perform app.link_invited_guardian(inv, s.family_id, me, nm, true);\n  end if;\n\n  insert into user_account (id, email, full_name) values (me, inv.email, nm)\n  on conflict (id) do nothing;\n\n  -- Revive a removed membership rather than duplicating it.\n  update membership set deleted_at = null, updated_at = now()\n   where user_id = me and membership.studio_id = inv.studio_id and membership.role = eff;\n  if not found then\n    insert into membership (user_id, studio_id, role) values (me, inv.studio_id, eff)\n    on conflict do nothing;\n  end if;\n\n  -- Marked accepted before any linking, so the guardian guard can see that\n  -- this transaction is accepting this invitation (UR-03).\n  update studio_invitation set accepted_at = now(), accepted_by = me where id = inv.id;\n\n  if inv.role = 'teacher' then\n    update staff_member set user_id = me\n     where id = (select id from staff_member where staff_member.studio_id = inv.studio_id\n                   and lower(email) = inv.email and user_id is null and deleted_at is null limit 1);\n    if not found and not exists (select 1 from staff_member where staff_member.studio_id = inv.studio_id and user_id = me) then\n      insert into staff_member (studio_id, user_id, display_name, email) values (inv.studio_id, me, nm, inv.email);\n    end if;\n  elsif inv.role = 'guardian' then\n    perform app.link_invited_guardian(inv, inv.family_id, me, nm);\n  elsif inv.role = 'student' and adult then\n    gid := s.self_guardian_id;\n    if gid is null or exists (select 1 from guardian where id = gid and (deleted_at is not null or (user_id is not null and user_id <> me))) then\n      gid := app.link_invited_guardian(inv, s.family_id, me, nm);\n    elsif exists (select 1 from guardian where id = gid and user_id is null) then\n      perform set_config('app.accepting_invitation', gid::text, true);\n      update guardian set user_id = me, updated_at = now() where id = gid;\n      perform set_config('app.accepting_invitation', '', true);\n    end if;\n    update student set user_id = me, is_adult = true, self_guardian_id = gid, login_enabled = true,\n           login_approved_by = me, login_approved_at = now(), login_switched_off_by = null, login_switched_off_at = null\n     where id = s.id;\n  elsif inv.role = 'student' then\n    -- A child's login stays off until a guardian approves it — unless the\n    -- invitation came from that child's guardian.\n    by_guardian := exists (select 1 from guardian g where g.family_id = s.family_id\n                             and g.user_id = inv.invited_by and g.deleted_at is null);\n    update student set user_id = me, login_enabled = by_guardian,\n           login_approved_by = case when by_guardian then inv.invited_by end,\n           login_approved_at = case when by_guardian then now() end,\n           login_switched_off_by = null, login_switched_off_at = null\n     where id = s.id;\n    if not by_guardian then\n      perform app.notify_family(s.family_id, 'student_login', s.first_name || ' is waiting for your approval',\n        s.first_name || ' has accepted the school''s invitation. Their login stays off until you approve it.', '/family/children');\n    end if;\n  end if;\n\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (inv.studio_id, me, 'accept', 'membership', inv.id, inv.role || ' joined: ' || inv.email);\n  return query select inv.studio_id, eff;\nend $$;\n\n-- ── UR-16 · Teenagers' own logins ──────────────────────────────────────────\n-- Each child's login, for their guardians.\n--   too_young  below the school's minimum age\n--   none       no login and no invitation\n--   invited    an invitation is out, not yet accepted\n--   pending    accepted; waiting for a guardian to approve\n--   on         approved and working\n--   off        a guardian switched it off\ncreate or replace function app.my_children_logins()\n  returns table (student_id uuid, first_name text, age int, min_age int, state text, email text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id, s.first_name, extract(year from age(current_date, s.date_of_birth))::int, st.student_login_min_age::int,\n         case when s.login_enabled then 'on'\n              when s.user_id is not null and s.login_switched_off_at is not null then 'off'\n              when s.user_id is not null then 'pending'\n              when extract(year from age(current_date, s.date_of_birth)) < st.student_login_min_age then 'too_young'\n              when exists (select 1 from studio_invitation i where i.student_id = s.id and i.accepted_at is null\n                             and i.revoked_at is null and i.expires_at > now()) then 'invited'\n              else 'none' end,\n         coalesce((select u.email from user_account u where u.id = s.user_id),\n                  (select i.email from studio_invitation i where i.student_id = s.id and i.accepted_at is null\n                     and i.revoked_at is null and i.expires_at > now() order by i.created_at desc limit 1))\n    from student s join studio st on st.id = s.studio_id\n   where s.id in (select app.guardian_student_ids()) and not s.is_adult and s.deleted_at is null\n   order by s.date_of_birth\n$$;\ngrant execute on function app.my_children_logins() to authenticated;\n\n-- Turning on needs one guardian; either guardian (or the office) may turn\n-- it off, and the student's access ends at once (app.student_self_id).\ncreate or replace function app.set_student_login(p_student uuid, p_on boolean) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; mine boolean;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  mine := s.id is not null and s.id in (select app.guardian_student_ids());\n  if s.id is null or not (mine or (not p_on and app.is_admin(s.studio_id))) then\n    raise exception 'FORBIDDEN: only a parent or carer can decide this' using errcode = 'insufficient_privilege';\n  end if;\n  if s.is_adult then raise exception 'INVALID: an adult manages their own login' using errcode = 'check_violation'; end if;\n  if p_on then\n    if s.user_id is null then\n      raise exception 'INVALID: % has not accepted an invitation yet — invite them first', s.first_name using errcode = 'check_violation';\n    end if;\n    update student set login_enabled = true, login_approved_by = auth.uid(), login_approved_at = now(),\n           login_switched_off_by = null, login_switched_off_at = null, updated_at = now()\n     where id = s.id;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (s.studio_id, auth.uid(), 'approve', 'student_login', s.id, 'Login approved for ' || s.first_name);\n    return 'on';\n  end if;\n  update student set login_enabled = false, login_approved_by = null, login_approved_at = null,\n         login_switched_off_by = auth.uid(), login_switched_off_at = now(), updated_at = now()\n   where id = s.id;\n  -- An invitation not yet used is withdrawn too.\n  update studio_invitation set revoked_at = now() where student_id = s.id and accepted_at is null and revoked_at is null;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (s.studio_id, auth.uid(), 'switch_off', 'student_login', s.id, 'Login switched off for ' || s.first_name);\n  perform app.notify_family(s.family_id, 'student_login', s.first_name || '’s login is off',\n    'A parent or carer switched off ' || s.first_name || '’s own login.', '/family/children');\n  return 'off';\nend $$;\ngrant execute on function app.set_student_login(uuid, boolean) to authenticated;\n\n-- A guardian invites their own child: the login works as soon as it is\n-- accepted, because the inviter is the approving guardian.\ncreate or replace function app.guardian_invite_student(p_student uuid, p_email text) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; tok text; em text := lower(btrim(coalesce(p_email, ''))); min_age int;\nbegin\n  s := app.my_child(p_student);\n  if s.is_adult then raise exception 'INVALID: an adult manages their own login' using errcode = 'check_violation'; end if;\n  select student_login_min_age into min_age from studio where id = s.studio_id;\n  if extract(year from age(current_date, s.date_of_birth)) < min_age then\n    raise exception 'INVALID: the school gives students their own login from age %', min_age using errcode = 'check_violation';\n  end if;\n  if em !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n    raise exception 'INVALID: that does not look like an email address' using errcode = 'check_violation';\n  end if;\n  if s.user_id is not null then\n    raise exception 'INVALID: % already has a login — switch it on or off instead', s.first_name using errcode = 'check_violation';\n  end if;\n  update studio_invitation set revoked_at = now()\n   where student_id = s.id and accepted_at is null and revoked_at is null;\n  tok := app.new_token();\n  insert into studio_invitation (studio_id, email, full_name, role, student_id, token_hash, invited_by)\n  values (s.studio_id, em, s.first_name || ' ' || s.last_name, 'student', s.id, app.hash_token(tok), auth.uid());\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (s.studio_id, auth.uid(), 'invite', 'studio_invitation', s.id, 'Student login invited by a parent: ' || em);\n  return tok;\nend $$;\ngrant execute on function app.guardian_invite_student(uuid, text) to authenticated;\n\n-- The school's minimum age for a student's own login (13–18).\ncreate or replace function app.set_student_login_min_age(p_studio uuid, p_age int) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only an owner can change this' using errcode = 'insufficient_privilege';\n  end if;\n  if p_age is null or p_age < 13 or p_age > 18 then\n    raise exception 'INVALID: choose an age from 13 to 18' using errcode = 'check_violation';\n  end if;\n  update studio set student_login_min_age = p_age, updated_at = now() where id = p_studio;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (p_studio, auth.uid(), 'update', 'studio', p_studio, 'Student logins from age ' || p_age);\nend $$;\ngrant execute on function app.set_student_login_min_age(uuid, int) to authenticated;\n\n-- ── UR-17 · Message privacy ────────────────────────────────────────────────\n-- A guardian's own message, a reply in their thread, and the mirror of a\n-- request they raised belong to that guardian. Runs after communication_stamp\n-- (trigger names fire in order), so sent_by and inbound are final.\ncreate or replace function app.communication_privacy() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare raiser uuid; parent_private uuid;\nbegin\n  if new.kind <> 'direct' or new.family_id is null then new.private_to := null; return new; end if;\n  -- Only the office (or a trusted job) addresses a message to one guardian.\n  if new.private_to is not null and auth.uid() is not null and not app.is_staff(new.studio_id)\n     and coalesce(current_setting('role', true), 'none') in ('authenticated', 'anon') then\n    new.private_to := null;\n  end if;\n  if new.private_to is not null and not exists (select 1 from guardian g where g.family_id = new.family_id\n                                                  and g.user_id = new.private_to and g.deleted_at is null) then\n    new.private_to := null;\n  end if;\n  if new.inbound and new.sent_by is not null and exists (select 1 from guardian g where g.family_id = new.family_id\n                                                           and g.user_id = new.sent_by and g.deleted_at is null) then\n    new.private_to := new.sent_by;\n  elsif new.private_to is null and new.reply_to is not null then\n    select private_to into parent_private from communication where id = new.reply_to;\n    new.private_to := parent_private;\n  elsif new.private_to is null and new.request_id is not null then\n    select r.raised_by into raiser from studio_request r where r.id = new.request_id;\n    if raiser is not null and exists (select 1 from guardian g where g.family_id = new.family_id\n                                        and g.user_id = raiser and g.deleted_at is null) then\n      new.private_to := raiser;\n    end if;\n  end if;\n  return new;\nend $$;\ncreate trigger communication_to_guardian before insert on communication\n  for each row execute function app.communication_privacy();\n\ncreate policy comm_guardian_private on communication as restrictive for select\n  using (private_to is null or private_to = auth.uid() or app.is_staff(studio_id));\n\n-- Requests a guardian raised are theirs and the office's, like messages.\ncreate or replace function app.other_guardian_user_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select g2.user_id from guardian g join guardian g2 on g2.family_id = g.family_id\n   where g.user_id = auth.uid() and g.deleted_at is null and g2.deleted_at is null\n     and g2.user_id is not null and g2.user_id <> auth.uid() and not app.is_staff(g.studio_id)\n$$;\ncreate policy request_guardian_private on studio_request as restrictive for select\n  using (raised_by is null or raised_by not in (select app.other_guardian_user_ids()));\n\n-- A private message notifies only its guardian.\ncreate or replace function app.on_communication_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare fam text;\nbegin\n  if new.request_id is not null or new.sent_at > now() + interval '1 minute' then return null; end if;\n  if new.inbound and new.family_id is not null then\n    select name into fam from family where id = new.family_id;\n    perform app.notify_admins(new.studio_id, 'message', 'Message from the ' || fam,\n      coalesce(new.subject, left(new.body, 120)), '/inbox?family=' || new.family_id);\n  elsif not new.inbound and new.kind = 'direct' and new.private_to is not null then\n    if not exists (select 1 from guardian g left join guardian_access a on a.guardian_id = g.id\n                    where g.family_id = new.family_id and g.user_id = new.private_to and g.deleted_at is null\n                      and a.may_contact is false) then\n      perform app.notify_user(new.studio_id, new.private_to, 'message',\n        coalesce(new.subject, 'New message from the studio'), left(new.body, 120), '/family/messages');\n    end if;\n  elsif not new.inbound and new.kind = 'direct' then\n    perform app.notify_family(new.family_id, 'message',\n      coalesce(new.subject, 'New message from the studio'), left(new.body, 120), '/family/messages');\n  end if;\n  return null;\nend $$;\n\n-- ── UR-17 · Office-set restrictions per guardian ───────────────────────────\ncreate table guardian_access (\n  guardian_id  uuid primary key references guardian(id) on delete cascade,\n  studio_id    uuid not null references studio(id) on delete cascade,\n  see_schedule boolean not null default true,\n  see_payments boolean not null default true,\n  see_feedback boolean not null default true,\n  see_medical  boolean not null default true,\n  may_contact  boolean not null default true,\n  may_collect  boolean not null default true,\n  -- e.g. the court order behind a restriction. Read by the safeguarding lead only.\n  dsl_note     text,\n  updated_by   uuid references user_account(id) on delete set null,\n  updated_at   timestamptz not null default now()\n);\nalter table guardian_access enable row level security;\nalter table guardian_access force row level security;\n-- No direct policies: read and written through the functions below, so the\n-- note never reaches anyone but the safeguarding lead.\ngrant select, insert, update, delete on guardian_access to service_role;\n\ncreate or replace function app.set_guardian_access(p_guardian uuid, p_flags jsonb, p_note text default null)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g guardian; dsl boolean;\nbegin\n  select * into g from guardian where id = p_guardian and deleted_at is null;\n  if g.id is null or not app.is_admin(g.studio_id) then\n    raise exception 'FORBIDDEN: only the office can set what a guardian sees' using errcode = 'insufficient_privilege';\n  end if;\n  dsl := app.is_safeguarding_lead(g.studio_id);\n  insert into guardian_access (guardian_id, studio_id) values (g.id, g.studio_id) on conflict (guardian_id) do nothing;\n  update guardian_access set\n    see_schedule = coalesce((p_flags ->> 'see_schedule')::boolean, see_schedule),\n    see_payments = coalesce((p_flags ->> 'see_payments')::boolean, see_payments),\n    see_feedback = coalesce((p_flags ->> 'see_feedback')::boolean, see_feedback),\n    see_medical  = coalesce((p_flags ->> 'see_medical')::boolean, see_medical),\n    may_contact  = coalesce((p_flags ->> 'may_contact')::boolean, may_contact),\n    may_collect  = coalesce((p_flags ->> 'may_collect')::boolean, may_collect),\n    dsl_note     = case when dsl and p_note is not null then nullif(btrim(p_note), '') else dsl_note end,\n    updated_by   = auth.uid(), updated_at = now()\n   where guardian_id = g.id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (g.studio_id, auth.uid(), 'update', 'guardian_access', g.id, 'Access set for ' || g.full_name);\nend $$;\ngrant execute on function app.set_guardian_access(uuid, jsonb, text) to authenticated;\n\n-- For the office: the flags, and the note when the reader is the DSL.\ncreate or replace function app.guardian_access_for(p_guardian uuid)\n  returns table (see_schedule boolean, see_payments boolean, see_feedback boolean, see_medical boolean,\n                 may_contact boolean, may_collect boolean, has_note boolean, dsl_note text, can_note boolean)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(a.see_schedule, true), coalesce(a.see_payments, true), coalesce(a.see_feedback, true),\n         coalesce(a.see_medical, true), coalesce(a.may_contact, true), coalesce(a.may_collect, true),\n         a.dsl_note is not null,\n         case when app.is_safeguarding_lead(g.studio_id) then a.dsl_note end,\n         app.is_safeguarding_lead(g.studio_id)\n    from guardian g left join guardian_access a on a.guardian_id = g.id\n   where g.id = p_guardian and g.deleted_at is null and app.is_admin(g.studio_id)\n$$;\ngrant execute on function app.guardian_access_for(uuid) to authenticated;\n\n-- For the guardian: what this account may see (no note).\ncreate or replace function app.my_access()\n  returns table (see_schedule boolean, see_payments boolean, see_feedback boolean, see_medical boolean)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(bool_and(a.see_schedule), true), coalesce(bool_and(a.see_payments), true),\n         coalesce(bool_and(a.see_feedback), true), coalesce(bool_and(a.see_medical), true)\n    from guardian g left join guardian_access a on a.guardian_id = g.id\n   where g.user_id = auth.uid() and g.deleted_at is null and app.in_scope(g.studio_id)\n$$;\ngrant execute on function app.my_access() to authenticated;\n\n-- Families and students this caller is a restricted guardian of, per area.\ncreate or replace function app.denied_family_ids(p_what text) returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select g.family_id from guardian g join guardian_access a on a.guardian_id = g.id\n   where g.user_id = auth.uid() and g.deleted_at is null and not app.is_staff(g.studio_id)\n     and case p_what when 'schedule' then not a.see_schedule when 'payments' then not a.see_payments\n                     when 'feedback' then not a.see_feedback when 'medical' then not a.see_medical else false end\n$$;\ncreate or replace function app.denied_student_ids(p_what text) returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id from student s where s.family_id in (select app.denied_family_ids(p_what))\n$$;\ncreate or replace function app.denied_invoice_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select i.id from invoice i where i.family_id in (select app.denied_family_ids('payments'))\n$$;\ngrant execute on function app.denied_family_ids(text), app.denied_student_ids(text), app.denied_invoice_ids() to authenticated;\n\n-- Restrictive policies sit on top of every read policy, whoever owns it, so\n-- a restriction holds on every path. Defaults (no row) restrict nothing.\ncreate policy invoice_guardian_access on invoice as restrictive for select\n  using (family_id is null or family_id not in (select app.denied_family_ids('payments')));\ncreate policy payment_guardian_access on payment as restrictive for select\n  using (family_id is null or family_id not in (select app.denied_family_ids('payments')));\ncreate policy invoice_item_guardian_access on invoice_item as restrictive for select\n  using (invoice_id not in (select app.denied_invoice_ids()));\ncreate policy medical_guardian_access on medical_record as restrictive for select\n  using (student_id not in (select app.denied_student_ids('medical')));\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['feedback_note', 'skill_assessment', 'progress_report', 'milestone'] loop\n    execute format('create policy %I on %I as restrictive for select using (student_id not in (select app.denied_student_ids(''feedback'')))',\n                   t || '_guardian_access', t);\n  end loop;\n  foreach t in array array['enrolment', 'waitlist_entry', 'drop_in_booking', 'attendance_record'] loop\n    execute format('create policy %I on %I as restrictive for select using (student_id not in (select app.denied_student_ids(''schedule'')))',\n                   t || '_guardian_access', t);\n  end loop;\nend $$;\ncreate policy trial_guardian_access on trial as restrictive for select\n  using (student_id is null or student_id not in (select app.denied_student_ids('schedule')));\n\n-- \"May not be contacted\": the studio's notifications skip them.\ncreate or replace function app.notify_family(\n  p_family uuid, p_kind text, p_title text, p_body text, p_href text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g record;\nbegin\n  for g in select gd.studio_id, gd.user_id from guardian gd left join guardian_access a on a.guardian_id = gd.id\n            where gd.family_id = p_family and gd.user_id is not null and gd.deleted_at is null\n              and a.may_contact is not false\n  loop\n    perform app.notify_user(g.studio_id, g.user_id, p_kind, p_title, p_body, p_href);\n  end loop;\nend $$;\nrevoke execute on function app.notify_family(uuid, text, text, text, text) from public, authenticated, anon;\n\n-- ── UR-17 · Who may collect each child ─────────────────────────────────────\ncreate table collection_permission (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  full_name    text not null check (length(btrim(full_name)) > 1),\n  relationship text,\n  phone        text,\n  allowed      boolean not null default true,\n  added_by     uuid references user_account(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now(),\n  deleted_at   timestamptz\n);\ncreate index collection_student on collection_permission (student_id) where deleted_at is null;\nalter table collection_permission enable row level security;\nalter table collection_permission force row level security;\ngrant select, insert, update, delete on collection_permission to authenticated, service_role;\n\ncreate policy collection_admin on collection_permission for all\n  using (deleted_at is null and app.is_admin(studio_id)) with check (app.is_admin(studio_id));\n-- Parents keep the list of people who may collect. A \"may not collect\" entry\n-- is the office's, and parents do not see it.\ncreate policy collection_guardian_read on collection_permission for select\n  using (deleted_at is null and allowed and student_id in (select app.guardian_student_ids()));\ncreate policy collection_guardian_write on collection_permission for insert\n  with check (allowed and student_id in (select app.guardian_student_ids()));\ncreate policy collection_guardian_update on collection_permission for update\n  using (deleted_at is null and allowed and student_id in (select app.guardian_student_ids()))\n  with check (allowed and student_id in (select app.guardian_student_ids()));\n\ncreate or replace function app.collection_stamp() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  select studio_id into new.studio_id from student where id = new.student_id;\n  if tg_op = 'INSERT' then new.added_by := coalesce(auth.uid(), new.added_by); end if;\n  new.updated_at := now();\n  return new;\nend $$;\ncreate trigger collection_stamp before insert or update on collection_permission\n  for each row execute function app.collection_stamp();\n\ncreate or replace function app.remove_collection_person(p_id uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c collection_permission;\nbegin\n  select * into c from collection_permission where id = p_id and deleted_at is null;\n  if c.id is null or not (app.is_admin(c.studio_id) or (c.allowed and c.student_id in (select app.guardian_student_ids()))) then\n    raise exception 'FORBIDDEN: not yours to remove' using errcode = 'insufficient_privilege';\n  end if;\n  update collection_permission set deleted_at = now() where id = c.id;\nend $$;\ngrant execute on function app.remove_collection_person(uuid) to authenticated;\n\n-- The collection list for the register brief: names and whether they may\n-- collect, never the reason. Guardians who may not collect are listed too.\n-- Staff who can see the child get both lists; a guardian gets \"may collect\".\ncreate or replace function app.collection_brief(p_student uuid) returns jsonb\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare s student; staff boolean;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null then return '[]'::jsonb; end if;\n  staff := app.is_admin(s.studio_id) or (app.has_role(s.studio_id, 'teacher')\n           and (s.id in (select app.teacher_student_ids()) or s.id in (select app.teacher_event_student_ids())));\n  if not staff and s.id not in (select app.guardian_student_ids()) then return '[]'::jsonb; end if;\n  return coalesce((\n    select jsonb_agg(jsonb_build_object('name', x.name, 'relationship', x.relationship, 'allowed', x.allowed)\n                     order by x.allowed desc, x.name)\n      from (select c.full_name as name, c.relationship, c.allowed from collection_permission c\n             where c.student_id = s.id and c.deleted_at is null and (c.allowed or staff)\n            union all\n            select g.full_name, g.relationship, false from guardian g join guardian_access a on a.guardian_id = g.id\n             where staff and g.family_id = s.family_id and g.deleted_at is null and not a.may_collect) x), '[]'::jsonb);\nend $$;\ngrant execute on function app.collection_brief(uuid) to authenticated;\n\ngrant execute on function app.check_class_age(uuid, date, date, text, boolean), app.age_label(smallint, smallint) to authenticated, anon;\n"},{name:"0047_safeguarding_fixes.sql",sql:"-- ============================================================================\n-- 0047 · Safeguarding fixes from the end-user panel review\n--   UR-08  consent: capture, withdrawal and history; most restrictive wins\n--   UR-09  office and DSL raise concerns, about a child, an adult or staff\n--   UR-12  retention legal hold for safeguarding records\n--   UR-28  the access log counts each opening once\n--   UR-29  a DSL/owner-only safeguarding export, itself logged\n--   UR-38  family data requests (\"ask to delete\")\n--   UR-41  staff checks readable by admin and DSL; gaps on Today\n--   UR-58  absence as a welfare signal, opt-in per child by the DSL\n--\n-- Note: new enum values ('video', 'data_request') may not be used as literals\n-- in this file outside plpgsql bodies, because the migration runs as one\n-- transaction and Postgres refuses a value added in the same transaction.\n-- Kinds are therefore passed around as text and cast when written.\n-- ============================================================================\n\n-- ── UR-08 · Consent with history ───────────────────────────────────────────\nalter type consent_kind add value if not exists 'video';\n\n-- One row per change, never overwritten: the unique (student, kind) pair\n-- made history impossible, so it goes. \"Current\" is always derived.\ndo $$ declare c text; begin\n  for c in select conname from pg_constraint where conrelid = 'consent_record'::regclass and contype = 'u' loop\n    execute format('alter table consent_record drop constraint %I', c);\n  end loop;\nend $$;\nalter table consent_record add column source text check (source in ('family', 'office', 'paper', 'import'));\ncreate index consent_student_kind on consent_record (student_id, kind, granted_at desc) where deleted_at is null;\n\n-- Direct writes are for the office only (corrections, imports). Families\n-- change consent through app.set_consent, which keeps the history and alerts\n-- the office when guardians disagree.\ndrop policy if exists consent_write on consent_record;\ncreate policy consent_admin_write on consent_record for all\n  using (deleted_at is null and app.is_admin(studio_id))\n  with check (app.is_admin(studio_id));\n\n-- The current state of one consent for one child.\n--   * Every row recorded by the office (on paper, at import, at the desk) is\n--     the school's settled position and supersedes what came before.\n--   * After it, each guardian's own latest choice counts. If any guardian has\n--     withdrawn, consent is withdrawn (most restrictive), and if guardians\n--     differ the state is \"disputed\" so the office can follow it up.\n--   * No rows at all: null, shown as \"Not recorded\" and treated as no consent.\n-- Internal: callable only from other definer functions.\ncreate or replace function app.consent_effective(p_student uuid, p_kind text)\n  returns table (granted boolean, disputed boolean, changed_at timestamptz)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare fam uuid; o_granted boolean; o_at timestamptz; v record; n_yes int := 0; n_no int := 0; latest timestamptz;\nbegin\n  select s.family_id into fam from student s where s.id = p_student;\n  select c.granted, c.granted_at into o_granted, o_at from consent_record c\n   where c.student_id = p_student and c.kind::text = p_kind and c.deleted_at is null\n     and (c.expires_at is null or c.expires_at > now())\n     and (c.granted_by is null or c.granted_by not in\n            (select g.user_id from guardian g where g.family_id = fam and g.user_id is not null and g.deleted_at is null))\n   order by c.granted_at desc, c.created_at desc limit 1;\n  for v in select distinct on (c.granted_by) c.granted_by, c.granted, c.granted_at from consent_record c\n            where c.student_id = p_student and c.kind::text = p_kind and c.deleted_at is null\n              and (c.expires_at is null or c.expires_at > now())\n              and c.granted_by in (select g.user_id from guardian g where g.family_id = fam and g.user_id is not null and g.deleted_at is null)\n              and c.granted_at > coalesce(o_at, '-infinity'::timestamptz)\n            order by c.granted_by, c.granted_at desc, c.created_at desc loop\n    if v.granted then n_yes := n_yes + 1; else n_no := n_no + 1; end if;\n    latest := greatest(latest, v.granted_at);\n  end loop;\n  if n_yes + n_no = 0 then\n    granted := o_granted; disputed := false; changed_at := o_at;\n  else\n    granted := n_no = 0; disputed := n_yes > 0 and n_no > 0; changed_at := latest;\n  end if;\n  return next;\nend $$;\n\n-- Who may know a child's consent: the office, the child's guardians, the\n-- child, and a teacher of the child (the same people as the safety brief).\ncreate or replace function app.can_see_consent(p_student uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from student s where s.id = p_student and s.deleted_at is null\n                   and not app.is_support_viewer(s.studio_id)\n                   and (app.is_admin(s.studio_id)\n                        or p_student in (select app.guardian_student_ids())\n                        or p_student = app.student_self_id()\n                        or (app.has_role(s.studio_id, 'teacher')\n                            and (p_student in (select app.teacher_student_ids())\n                                 or p_student in (select app.teacher_event_student_ids())))));\n$$;\n\ncreate or replace function app.consent_now(p_student uuid, p_kind text) returns boolean\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.can_see_consent(p_student) then return null; end if;\n  return (select e.granted from app.consent_effective(p_student, p_kind) e);\nend $$;\n\n-- The kinds a family manages in the app. Schools may rename them later.\ncreate or replace function app.consent_kinds() returns text[]\n  language sql immutable as $$ select array['photography', 'video', 'social_media'] $$;\n\ncreate or replace function app.consents(p_student uuid)\n  returns table (kind text, granted boolean, disputed boolean, changed_at timestamptz)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare k text;\nbegin\n  if not app.can_see_consent(p_student) then return; end if;\n  foreach k in array app.consent_kinds() loop\n    kind := k;\n    select e.granted, e.disputed, e.changed_at into granted, disputed, changed_at from app.consent_effective(p_student, k) e;\n    return next;\n  end loop;\nend $$;\n\n-- Every change, newest first, with who made it. Office and the family only.\ncreate or replace function app.consent_history(p_student uuid)\n  returns table (kind text, granted boolean, at timestamptz, by_name text, source text, note text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select s.studio_id into sid from student s where s.id = p_student and s.deleted_at is null;\n  if sid is null or app.is_support_viewer(sid) or not (app.is_admin(sid) or p_student in (select app.guardian_student_ids())\n                                                       or p_student is not distinct from app.student_self_id()) then\n    return;\n  end if;\n  return query\n  select c.kind::text, c.granted, c.granted_at, coalesce(u.full_name, case when c.source = 'import' or c.note = 'Imported' then 'Import' else 'The school' end),\n         coalesce(c.source, case when c.note = 'Imported' then 'import' else 'office' end), c.note\n    from consent_record c left join user_account u on u.id = c.granted_by\n   where c.student_id = p_student and c.deleted_at is null\n   order by c.granted_at desc, c.created_at desc;\nend $$;\n\n-- A guardian (in the app) or the office (in person, on paper) records a\n-- choice. Each call adds a row; withdrawal takes effect at once.\ncreate or replace function app.set_consent(p_student uuid, p_kind text, p_granted boolean, p_note text default null, p_paper boolean default false)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st record; src text; before_ record; after_ record; label text;\nbegin\n  select s.id, s.studio_id, s.first_name, s.last_name into st from student s where s.id = p_student and s.deleted_at is null;\n  if st.id is null then raise exception 'FORBIDDEN: not your child' using errcode = 'insufficient_privilege'; end if;\n  if p_student in (select app.guardian_student_ids()) then src := 'family';\n  elsif app.is_admin(st.studio_id) and not app.is_support_viewer(st.studio_id) then src := case when p_paper then 'paper' else 'office' end;\n  else raise exception 'FORBIDDEN: only the child''s guardians or the office record consent' using errcode = 'insufficient_privilege';\n  end if;\n  if p_granted is null then raise exception 'INVALID: say whether consent is given' using errcode = 'check_violation'; end if;\n  if not (p_kind = any(app.consent_kinds())) then raise exception 'INVALID: unknown consent' using errcode = 'check_violation'; end if;\n  select * into before_ from app.consent_effective(p_student, p_kind);\n  insert into consent_record (studio_id, student_id, kind, granted, granted_by, granted_at, note, source)\n  values (st.studio_id, p_student, p_kind::consent_kind, p_granted, auth.uid(), clock_timestamp(), nullif(btrim(p_note), ''), src);\n  select * into after_ from app.consent_effective(p_student, p_kind);\n  label := case p_kind when 'photography' then 'Photo' when 'video' then 'Video' else 'Social media' end;\n  if after_.disputed and not coalesce(before_.disputed, false) then\n    perform app.notify_admins(st.studio_id, 'consent', 'Guardians disagree: ' || lower(label) || ' consent for ' || st.first_name,\n      'The most restrictive choice applies until you settle it with the family.', '/people?tab=students');\n  elsif src = 'family' and after_.granted is distinct from before_.granted then\n    perform app.notify_admins(st.studio_id, 'consent',\n      label || ' consent ' || case when after_.granted then 'given' else 'withdrawn' end || ' for ' || st.first_name || ' ' || st.last_name,\n      'Teachers see the change on their next load.', '/people?tab=students');\n  end if;\nend $$;\n\n-- What a teacher sees changes only in how photo consent is worked out: the\n-- latest settled state, most restrictive when guardians differ. Columns are\n-- unchanged (the suite asserts them).\ncreate or replace view student_safety_brief\n  with (security_invoker = false) as\nselect s.id as student_id,\n       s.studio_id,\n       s.first_name,\n       s.last_name,\n       m.allergies,\n       m.action_plan,\n       m.requires_alert,\n       (select ec.full_name from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_name,\n       (select ec.phone from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_phone,\n       m.conditions,\n       m.medications,\n       coalesce(m.requires_alert, false)\n         or coalesce(nullif(btrim(m.allergies), ''), nullif(btrim(m.conditions), ''),\n                     nullif(btrim(m.medications), ''), nullif(btrim(m.action_plan), '')) is not null\n         as has_medical_need,\n       coalesce((select jsonb_agg(jsonb_build_object(\n                   'name', ec.full_name, 'relationship', ec.relationship, 'phone', ec.phone)\n                   order by ec.priority, ec.created_at)\n                  from emergency_contact ec where ec.student_id = s.id and ec.deleted_at is null),\n                '[]'::jsonb) as emergency_contacts,\n       app.consent_now(s.id, 'photography') as photo_consent\n  from student s\n  left join medical_record m on m.student_id = s.id and m.deleted_at is null\n where s.deleted_at is null\n   and not app.is_support_viewer(s.studio_id)\n   and (app.is_admin(s.studio_id)\n        or (app.has_role(s.studio_id, 'teacher')\n            and (s.id in (select app.teacher_student_ids())\n                 or s.id in (select app.teacher_event_student_ids())))\n        or s.id in (select app.guardian_student_ids())\n        or s.id = app.student_self_id());\ngrant select on student_safety_brief to authenticated, service_role;\n\n-- Show programmes follow the same rule.\ncreate or replace function app.has_consent(p_student uuid, p_kind consent_kind) returns boolean\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  return coalesce((select e.granted from app.consent_effective(p_student, p_kind::text) e), false);\nend $$;\n\n-- ── UR-09 · Concerns from anyone on the staff, about anyone ────────────────\nalter table safeguarding_concern add column subject_kind text not null default 'child'\n  check (subject_kind in ('child', 'adult', 'staff'));\nalter table safeguarding_concern add column subject_staff_id uuid references staff_member(id) on delete set null;\nalter table safeguarding_concern add column subject_text text;\nalter table safeguarding_concern add column allegation boolean not null default false;\ndo $$ declare c text; begin\n  for c in select conname from pg_constraint where conrelid = 'safeguarding_concern'::regclass and contype = 'c'\n              and pg_get_constraintdef(oid) like '%category%' loop\n    execute format('alter table safeguarding_concern drop constraint %I', c);\n  end loop;\nend $$;\nalter table safeguarding_concern add constraint safeguarding_concern_category_check\n  check (category in ('wellbeing', 'injury', 'disclosure', 'behaviour', 'attendance', 'online', 'allegation', 'other'));\nalter table safeguarding_access add column opening uuid;\ncreate index safeguarding_access_opening on safeguarding_access (user_id, opening) where opening is not null;\n\n-- The lead and the owner read concerns, except one about themselves: an\n-- allegation is never visible to the member of staff it concerns, whatever\n-- their role.\ncreate or replace function app.can_read_concern(p_concern uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from safeguarding_concern c\n                  where c.id = p_concern and app.is_safeguarding_lead(c.studio_id)\n                    and not exists (select 1 from staff_member sm where sm.id = c.subject_staff_id and sm.user_id = auth.uid()));\n$$;\n\ncreate or replace function app.raise_concern_about(\n  p_studio uuid, p_subject_kind text, p_student uuid, p_staff uuid, p_subject_text text,\n  p_category text, p_summary text, p_immediate boolean default false) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid; u uuid; subject_user uuid; is_alleg boolean := false; t text;\nbegin\n  if p_subject_kind = 'child' then\n    select studio_id into sid from student where id = p_student and deleted_at is null;\n  elsif p_subject_kind = 'staff' then\n    select studio_id, user_id into sid, subject_user from staff_member where id = p_staff and deleted_at is null;\n    is_alleg := true;\n  elsif p_subject_kind = 'adult' then\n    sid := p_studio;\n    if length(btrim(coalesce(p_subject_text, ''))) < 2 then\n      raise exception 'INVALID: say who the concern is about' using errcode = 'check_violation';\n    end if;\n  else\n    raise exception 'INVALID: unknown subject' using errcode = 'check_violation';\n  end if;\n  if sid is null or not app.is_staff(sid) then\n    raise exception 'FORBIDDEN: staff raise concerns at their own school' using errcode = 'insufficient_privilege';\n  end if;\n  insert into safeguarding_concern (studio_id, student_id, raised_by, category, summary, immediate_risk,\n                                    subject_kind, subject_staff_id, subject_text, allegation)\n  values (sid, case when p_subject_kind = 'child' then p_student end, auth.uid(),\n          case when is_alleg and coalesce(p_category, 'other') in ('other', 'wellbeing') then 'allegation' else coalesce(p_category, 'other') end,\n          btrim(p_summary), coalesce(p_immediate, false),\n          p_subject_kind, case when p_subject_kind = 'staff' then p_staff end, nullif(btrim(p_subject_text), ''), is_alleg)\n  returning id into cid;\n  insert into safeguarding_access (studio_id, user_id, concern_id, what) values (sid, auth.uid(), cid, 'raised a concern');\n  t := case when is_alleg then 'Allegation about a member of staff: follow the LADO process'\n            when p_immediate then 'URGENT safeguarding concern raised' else 'Safeguarding concern raised' end;\n  if is_alleg and p_immediate then t := 'URGENT allegation about a member of staff: follow the LADO process'; end if;\n  -- The lead and the owners hear at once; the notification names nobody. The\n  -- subject of an allegation is never told, so a lead who is the subject is\n  -- skipped and it goes to the owner.\n  for u in select distinct x from (select s.dsl_user_id x from studio s where s.id = sid\n                                   union select m.user_id from membership m where m.studio_id = sid and m.role = 'owner' and m.deleted_at is null) y\n            where x is not null and x is distinct from subject_user loop\n    perform app.notify_user(sid, u, 'safeguarding', t, 'Open the safeguarding log to read it.', '/safeguarding');\n  end loop;\n  return cid;\nend $$;\n\ncreate or replace function app.raise_concern(p_student uuid, p_category text, p_summary text, p_immediate boolean default false)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  return app.raise_concern_about(null, 'child', p_student, null, null, p_category, p_summary, p_immediate);\nend $$;\n\n-- The log. p_opening identifies one look at the page: re-reading the list\n-- after an action (same opening) is not a new look (UR-28).\ndrop function if exists app.safeguarding_log(uuid);\ncreate function app.safeguarding_log(p_studio uuid, p_opening uuid default null)\n  returns table (id uuid, student_name text, category text, summary text, immediate_risk boolean, status text,\n                 raised_by text, created_at timestamptz, actions int, subject_kind text, subject_name text,\n                 allegation boolean, student_id uuid)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_safeguarding_lead(p_studio) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner can read concerns' using errcode = 'insufficient_privilege';\n  end if;\n  if p_opening is null or not exists (select 1 from safeguarding_access a where a.user_id = auth.uid() and a.opening = p_opening\n                                                                          and a.what = 'viewed the log') then\n    insert into safeguarding_access (studio_id, user_id, what, opening) values (p_studio, auth.uid(), 'viewed the log', p_opening);\n  end if;\n  return query\n  select c.id, s.first_name || ' ' || s.last_name, c.category, c.summary, c.immediate_risk, c.status,\n         coalesce(u.full_name, 'Unknown'), c.created_at, (select count(*)::int from safeguarding_action a where a.concern_id = c.id),\n         c.subject_kind,\n         case c.subject_kind when 'child' then s.first_name || ' ' || s.last_name\n                             when 'staff' then coalesce(sm.display_name, c.subject_text, 'Member of staff')\n                             else coalesce(c.subject_text, 'An adult') end,\n         c.allegation, c.student_id\n    from safeguarding_concern c left join student s on s.id = c.student_id left join user_account u on u.id = c.raised_by\n    left join staff_member sm on sm.id = c.subject_staff_id\n   where c.studio_id = p_studio\n     and (sm.user_id is null or sm.user_id <> auth.uid())\n   order by (c.status = 'closed'), c.immediate_risk desc, c.created_at desc;\nend $$;\n\n-- Opening a concern is logged once per opening (UR-28). The one-argument\n-- form logs every call, as before.\ndrop function if exists app.safeguarding_actions(uuid);\ncreate function app.safeguarding_actions(p_concern uuid, p_opening uuid default null)\n  returns table (note text, status_to text, by_name text, at timestamptz)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select c.studio_id into sid from safeguarding_concern c where c.id = p_concern;\n  if sid is null or not app.can_read_concern(p_concern) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner can read concerns' using errcode = 'insufficient_privilege';\n  end if;\n  if p_opening is null or not exists (select 1 from safeguarding_access a where a.user_id = auth.uid() and a.opening = p_opening\n                                                                          and a.concern_id = p_concern) then\n    insert into safeguarding_access (studio_id, user_id, concern_id, what, opening) values (sid, auth.uid(), p_concern, 'opened a concern', p_opening);\n  end if;\n  return query select a.note, a.status_to, coalesce(u.full_name, 'Unknown'), a.at\n    from safeguarding_action a left join user_account u on u.id = a.by_user where a.concern_id = p_concern order by a.at;\nend $$;\n\ncreate or replace function app.safeguarding_act(p_concern uuid, p_note text, p_status text default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from safeguarding_concern where id = p_concern;\n  if sid is null or not app.can_read_concern(p_concern) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner act on concerns' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_note), '') = '' then raise exception 'INVALID: record what was done' using errcode = 'check_violation'; end if;\n  insert into safeguarding_action (concern_id, by_user, note, status_to) values (p_concern, auth.uid(), btrim(p_note), p_status);\n  if p_status is not null then update safeguarding_concern set status = p_status, updated_at = now() where id = p_concern; end if;\n  insert into safeguarding_access (studio_id, user_id, concern_id, what) values (sid, auth.uid(), p_concern, 'recorded an action');\nend $$;\n\n-- Who has looked: now for the lead as well as the owner, so each sees the\n-- other's reads. Rows about a concern the viewer may not read are left out.\ncreate or replace function app.safeguarding_access_log(p_studio uuid)\n  returns table (who text, what text, concern uuid, at timestamptz)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_safeguarding_lead(p_studio) then\n    raise exception 'FORBIDDEN: only the owner and the safeguarding lead review who has read the log' using errcode = 'insufficient_privilege';\n  end if;\n  return query select coalesce(u.full_name, 'Unknown'), a.what, a.concern_id, a.at from safeguarding_access a\n    left join user_account u on u.id = a.user_id\n   where a.studio_id = p_studio and (a.concern_id is null or app.can_read_concern(a.concern_id))\n   order by a.at desc, a.id desc limit 500;\nend $$;\n\n-- Children a lead can pick for a hold or an absence watch (a lead may be a\n-- teacher, who otherwise sees only their own students).\ncreate or replace function app.safeguarding_students(p_studio uuid)\n  returns table (id uuid, name text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_safeguarding_lead(p_studio) then return; end if;\n  return query select s.id, s.first_name || ' ' || s.last_name from student s\n   where s.studio_id = p_studio and s.deleted_at is null and s.first_name <> 'Former' order by s.last_name, s.first_name;\nend $$;\n\n-- ── UR-12 · Legal hold ─────────────────────────────────────────────────────\ncreate table safeguarding_hold (\n  student_id  uuid primary key references student(id) on delete cascade,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  reason      text not null check (length(btrim(reason)) >= 3),\n  set_by      uuid references user_account(id) on delete set null,\n  set_at      timestamptz not null default now()\n);\nalter table safeguarding_hold enable row level security; alter table safeguarding_hold force row level security;\ngrant all on safeguarding_hold to service_role;\n\ncreate or replace function app.set_safeguarding_hold(p_student uuid, p_reason text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from student where id = p_student and deleted_at is null;\n  if sid is null or not app.is_safeguarding_lead(sid) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner set a hold' using errcode = 'insufficient_privilege';\n  end if;\n  insert into safeguarding_hold (student_id, studio_id, reason, set_by) values (p_student, sid, btrim(p_reason), auth.uid())\n  on conflict (student_id) do update set reason = excluded.reason, set_by = excluded.set_by, set_at = now();\n  insert into safeguarding_access (studio_id, user_id, what) values (sid, auth.uid(), 'placed a legal hold');\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'update', 'safeguarding_hold', p_student, 'Legal hold placed');\nend $$;\n\ncreate or replace function app.release_safeguarding_hold(p_student uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from safeguarding_hold where student_id = p_student;\n  if sid is null then return; end if;\n  if not app.is_safeguarding_lead(sid) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner release a hold' using errcode = 'insufficient_privilege';\n  end if;\n  delete from safeguarding_hold where student_id = p_student;\n  insert into safeguarding_access (studio_id, user_id, what) values (sid, auth.uid(), 'released a legal hold');\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'update', 'safeguarding_hold', p_student, 'Legal hold released');\nend $$;\n\ncreate or replace function app.safeguarding_holds(p_studio uuid)\n  returns table (student_id uuid, name text, reason text, set_by text, set_at timestamptz)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_safeguarding_lead(p_studio) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner see holds' using errcode = 'insufficient_privilege';\n  end if;\n  return query select h.student_id, s.first_name || ' ' || s.last_name, h.reason, coalesce(u.full_name, 'Unknown'), h.set_at\n    from safeguarding_hold h join student s on s.id = h.student_id left join user_account u on u.id = h.set_by\n   where h.studio_id = p_studio order by h.set_at desc;\nend $$;\n\n-- Why a child's details must not be anonymised yet; null when nothing holds\n-- them. Internal.\ncreate or replace function app.retention_hold_reason(p_student uuid, p_concern_months smallint) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case\n    when exists (select 1 from safeguarding_hold h where h.student_id = p_student) then 'Legal hold set by the safeguarding lead'\n    when exists (select 1 from safeguarding_concern c where c.student_id = p_student and c.status <> 'closed') then 'Safeguarding concern still open'\n    when exists (select 1 from safeguarding_concern c where c.student_id = p_student and c.status = 'closed'\n                   and (p_concern_months is null or c.updated_at >= now() - make_interval(months => p_concern_months)))\n      then 'Safeguarding record still kept'\n  end;\n$$;\n\n-- As 0040, plus: a held child is listed with the reason and not anonymised;\n-- a prospect family with a held child is not removed; a closed concern about\n-- a child under an explicit hold is not deleted.\ndrop function if exists app.apply_retention(uuid, boolean);\ncreate function app.apply_retention(p_studio uuid, p_apply boolean default false)\n  returns table (step text, student_id uuid, who text, left_on date, reason text)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare pol retention_policy; r record; held text;\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the owner runs data retention' using errcode = 'insufficient_privilege';\n  end if;\n  select * into pol from retention_policy where studio_id = p_studio;\n  for r in select s.id, s.first_name || ' ' || s.last_name as who, app.leaver_since(s.id) as since,\n                  exists (select 1 from medical_record m where m.student_id = s.id and m.deleted_at is null) as has_medical,\n                  s.first_name = 'Former' as anonymised\n             from student s join family f on f.id = s.family_id\n            where s.studio_id = p_studio and s.deleted_at is null and not f.is_prospect loop\n    continue when r.since is null;\n    reason := null;\n    if r.has_medical and r.since < current_date - make_interval(months => pol.medical_months) then\n      step := 'medical'; student_id := r.id; who := r.who; left_on := r.since; return next;\n      if p_apply then\n        delete from medical_record where medical_record.student_id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'medical_record', r.id, 'Medical record deleted: left ' || r.since);\n      end if;\n    end if;\n    if not r.anonymised and r.since < current_date - make_interval(months => pol.personal_months) then\n      held := app.retention_hold_reason(r.id, pol.concern_months);\n      if held is not null then\n        step := 'held'; student_id := r.id; who := r.who; left_on := r.since; reason := held; return next;\n        reason := null;\n        continue;\n      end if;\n      step := 'anonymise'; student_id := r.id; who := r.who; left_on := r.since; return next;\n      if p_apply then\n        delete from emergency_contact where emergency_contact.student_id = r.id;\n        delete from consent_record where consent_record.student_id = r.id;\n        delete from student_reflection where student_reflection.student_id = r.id;\n        delete from welfare_watch where welfare_watch.student_id = r.id;\n        update feedback_note set private_note = null, going_well = null, work_on = null where feedback_note.student_id = r.id;\n        update student set first_name = 'Former', last_name = 'student',\n               date_of_birth = make_date(extract(year from date_of_birth)::int, 1, 1), user_id = null, login_enabled = false,\n               updated_at = now() where id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'student', r.id, 'Details anonymised: left ' || r.since);\n      end if;\n    end if;\n  end loop;\n  reason := null;\n\n  for r in select e.id, e.child_name, e.contact_name, greatest(e.updated_at, (select max(cs.starts_at) from trial t\n                  join class_session cs on cs.id = t.session_id where t.enquiry_id = e.id))::date last_seen\n             from enquiry e where e.studio_id = p_studio and e.deleted_at is null and e.stage <> 'enrolled' loop\n    continue when r.last_seen >= current_date - pol.prospect_days;\n    step := 'prospect'; student_id := null; who := coalesce(r.child_name, r.contact_name); left_on := r.last_seen; return next;\n    if p_apply then\n      delete from enquiry where id = r.id;\n      insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n      values (p_studio, auth.uid(), 'retention', 'enquiry', r.id, 'Enquiry removed: no activity since ' || r.last_seen);\n    end if;\n  end loop;\n  for r in select f.id, f.name, f.created_at::date made from family f\n            where f.studio_id = p_studio and f.deleted_at is null and f.is_prospect\n              and f.created_at < now() - make_interval(days => pol.prospect_days)\n              and not exists (select 1 from student s join trial t on t.student_id = s.id join class_session cs on cs.id = t.session_id\n                               where s.family_id = f.id and cs.starts_at > now() - make_interval(days => pol.prospect_days))\n              and not exists (select 1 from invoice i where i.family_id = f.id and i.deleted_at is null)\n              and not exists (select 1 from student s where s.family_id = f.id\n                                and app.retention_hold_reason(s.id, pol.concern_months) is not null) loop\n    step := 'prospect'; student_id := null; who := r.name; left_on := r.made; return next;\n    if p_apply then\n      delete from emergency_contact where emergency_contact.student_id in (select id from student where family_id = r.id);\n      delete from medical_record where medical_record.student_id in (select id from student where family_id = r.id);\n      update student set first_name = 'Former', last_name = 'prospect', date_of_birth = make_date(extract(year from date_of_birth)::int, 1, 1),\n             deleted_at = now() where family_id = r.id;\n      update guardian set full_name = 'Former prospect', email = null, phone = null, user_id = null, deleted_at = now() where family_id = r.id;\n      update family set name = 'Former prospect', address_line1 = null, address_line2 = null, city = null, postcode = null,\n             notes = null, deleted_at = now() where id = r.id;\n      insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n      values (p_studio, auth.uid(), 'retention', 'family', r.id, 'Prospect record removed');\n    end if;\n  end loop;\n\n  for r in select f.id, f.name, (select max(coalesce(i.issued_on, i.created_at::date)) from invoice i where i.family_id = f.id) last_inv\n             from family f where f.studio_id = p_studio and f.deleted_at is null and not f.is_prospect and f.name <> 'Former family'\n              and exists (select 1 from student s where s.family_id = f.id)\n              and not exists (select 1 from student s where s.family_id = f.id and s.deleted_at is null and s.first_name <> 'Former') loop\n    continue when r.last_inv is not null and r.last_inv >= current_date - make_interval(months => pol.financial_months);\n    step := 'financial'; student_id := null; who := r.name; left_on := r.last_inv; return next;\n    if p_apply then\n      update guardian set full_name = 'Former guardian', email = null, phone = null, user_id = null where family_id = r.id;\n      update family set name = 'Former family', address_line1 = null, address_line2 = null, city = null, postcode = null, notes = null\n       where id = r.id;\n      insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n      values (p_studio, auth.uid(), 'retention', 'family', r.id, 'Family details anonymised; invoices kept');\n    end if;\n  end loop;\n\n  if pol.concern_months is not null then\n    for r in select c.id, c.updated_at::date closed from safeguarding_concern c\n              where c.studio_id = p_studio and c.status = 'closed'\n                and c.updated_at < now() - make_interval(months => pol.concern_months)\n                and not exists (select 1 from safeguarding_hold h where h.student_id = c.student_id) loop\n      step := 'concern'; student_id := null; who := 'Closed concern'; left_on := r.closed; return next;\n      if p_apply then\n        delete from safeguarding_concern where id = r.id;\n        insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n        values (p_studio, auth.uid(), 'retention', 'safeguarding_concern', r.id, 'Closed concern deleted: closed ' || r.closed);\n      end if;\n    end loop;\n  end if;\n\n  if p_apply then update retention_policy set last_run_at = now() where studio_id = p_studio; end if;\nend $$;\n\n-- ── UR-41 · Staff checks for the lead and the office ───────────────────────\n-- The owner still records them; admins and the lead can read them.\ncreate policy staff_check_read on staff_check for select\n  using (deleted_at is null and (app.is_admin(studio_id) or app.is_safeguarding_lead(studio_id)));\n\n-- Each active member of staff, their current DBS and anything due within 30\n-- days. issue is null when nothing needs doing. Owner, admin and lead.\ncreate or replace function app.staff_check_summary(p_studio uuid)\n  returns table (staff_id uuid, name text, dbs_expires date, issue text, due date)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not (app.is_admin(p_studio) or app.is_safeguarding_lead(p_studio)) then return; end if;\n  return query\n  with latest as (\n    select distinct on (k.staff_id, k.kind) k.staff_id, k.kind, k.checked_on, k.expires_on\n      from staff_check k where k.studio_id = p_studio and k.deleted_at is null\n     order by k.staff_id, k.kind, k.checked_on desc, k.created_at desc)\n  select sm.id, sm.display_name, d.expires_on,\n         case when d.staff_id is null then 'No DBS on file'\n              when d.expires_on is not null and d.expires_on < current_date then 'DBS expired'\n              when soon.kind is not null then\n                case when soon.expires_on < current_date then 'Expired: ' else 'Expires soon: ' end ||\n                case soon.kind when 'dbs' then 'DBS' when 'safeguarding_training' then 'safeguarding training'\n                               when 'first_aid' then 'first aid' else 'a check' end\n         end,\n         coalesce(case when d.expires_on < current_date then d.expires_on end, soon.expires_on)\n    from staff_member sm\n    left join latest d on d.staff_id = sm.id and d.kind = 'dbs'\n    left join lateral (select l.kind, l.expires_on from latest l where l.staff_id = sm.id and l.expires_on is not null\n                         and l.expires_on <= current_date + 30 order by l.expires_on limit 1) soon on true\n   where sm.studio_id = p_studio and sm.deleted_at is null and sm.status = 'active'\n   order by (d.staff_id is null) desc, coalesce(soon.expires_on, d.expires_on) nulls last, sm.display_name;\nend $$;\n\n-- The reminder now reaches the lead as well as the owner.\ncreate or replace function app.remind_staff_checks(p_studio uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c record; n int := 0; u uuid;\nbegin\n  if auth.uid() is not null and not app.is_staff(p_studio) then return 0; end if;\n  for c in select k.*, sm.display_name from staff_check k join staff_member sm on sm.id = k.staff_id and sm.deleted_at is null and sm.status = 'active'\n            where k.studio_id = p_studio and k.deleted_at is null and k.reminded_at is null\n              and k.expires_on is not null and k.expires_on <= current_date + 30\n              and not exists (select 1 from staff_check newer where newer.staff_id = k.staff_id and newer.kind = k.kind\n                                and newer.deleted_at is null and newer.checked_on > k.checked_on) loop\n    for u in select distinct x from (select m.user_id x from membership m where m.studio_id = p_studio and m.role = 'owner' and m.deleted_at is null\n                                     union select s.dsl_user_id from studio s where s.id = p_studio) y where x is not null loop\n      perform app.notify_user(p_studio, u, 'staff_check_due',\n        case when c.expires_on < current_date then 'Expired: ' else 'Due soon: ' end || c.display_name || '’s ' ||\n        replace(case c.kind when 'dbs' then 'DBS check' else c.kind end, '_', ' '),\n        'Expires ' || to_char(c.expires_on, 'FMDD Month YYYY'), '/people?tab=staff');\n    end loop;\n    update staff_check set reminded_at = now() where id = c.id;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- ── UR-58 · Absence as a welfare signal ────────────────────────────────────\n-- Opt-in per child, by the lead: only watched children are looked at.\ncreate table welfare_watch (\n  student_id  uuid primary key references student(id) on delete cascade,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  note        text,\n  set_by      uuid references user_account(id) on delete set null,\n  set_at      timestamptz not null default now()\n);\nalter table welfare_watch enable row level security; alter table welfare_watch force row level security;\ngrant all on welfare_watch to service_role;\n\ncreate or replace function app.set_welfare_watch(p_student uuid, p_on boolean, p_note text default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from student where id = p_student and deleted_at is null;\n  if sid is null or not app.is_safeguarding_lead(sid) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner watch attendance' using errcode = 'insufficient_privilege';\n  end if;\n  if p_on then\n    insert into welfare_watch (student_id, studio_id, note, set_by) values (p_student, sid, nullif(btrim(p_note), ''), auth.uid())\n    on conflict (student_id) do update set note = excluded.note;\n    insert into safeguarding_access (studio_id, user_id, what) values (sid, auth.uid(), 'started watching a child’s attendance');\n  else\n    delete from welfare_watch where student_id = p_student;\n    insert into safeguarding_access (studio_id, user_id, what) values (sid, auth.uid(), 'stopped watching a child’s attendance');\n  end if;\nend $$;\n\n-- For each watched child: how many of their most recent sessions in a row\n-- were missed without explanation ('absent'; 'excused' breaks the run).\ncreate or replace function app.welfare_absences(p_studio uuid)\n  returns table (student_id uuid, name text, note text, streak int, last_absent date, last_present date)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_safeguarding_lead(p_studio) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner see this' using errcode = 'insufficient_privilege';\n  end if;\n  return query\n  select w.student_id, s.first_name || ' ' || s.last_name, w.note,\n         coalesce((select count(*)::int from (\n                     select ar.status, row_number() over (order by cs.starts_at desc) rn\n                       from attendance_record ar join class_session cs on cs.id = ar.session_id and cs.deleted_at is null\n                      where ar.student_id = w.student_id and ar.deleted_at is null and cs.starts_at < now()) m\n                   where m.status = 'absent'\n                     and m.rn < coalesce((select min(m2.rn) from (\n                            select ar.status, row_number() over (order by cs.starts_at desc) rn\n                              from attendance_record ar join class_session cs on cs.id = ar.session_id and cs.deleted_at is null\n                             where ar.student_id = w.student_id and ar.deleted_at is null and cs.starts_at < now()) m2\n                          where m2.status <> 'absent'), 2147483647)), 0),\n         (select max(cs.starts_at)::date from attendance_record ar join class_session cs on cs.id = ar.session_id\n           where ar.student_id = w.student_id and ar.deleted_at is null and ar.status = 'absent'),\n         (select max(cs.starts_at)::date from attendance_record ar join class_session cs on cs.id = ar.session_id\n           where ar.student_id = w.student_id and ar.deleted_at is null and ar.status in ('present', 'late'))\n    from welfare_watch w join student s on s.id = w.student_id and s.deleted_at is null\n   where w.studio_id = p_studio\n   order by 4 desc, 2;\nend $$;\n\n-- ── UR-29 · Safeguarding export ────────────────────────────────────────────\n-- For the lead and the owner only; an admin who is not the lead is refused.\n-- The export is itself recorded in the access log and the audit trail.\ncreate or replace function app.safeguarding_export(p_studio uuid) returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare out jsonb;\nbegin\n  if not app.is_safeguarding_lead(p_studio) then\n    raise exception 'FORBIDDEN: only the safeguarding lead and the owner export safeguarding records' using errcode = 'insufficient_privilege';\n  end if;\n  insert into safeguarding_access (studio_id, user_id, what) values (p_studio, auth.uid(), 'exported the safeguarding record');\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (p_studio, auth.uid(), 'export', 'safeguarding', p_studio, 'Safeguarding record exported');\n  select jsonb_build_object(\n    'exported_at', now(),\n    'exported_by', (select full_name from user_account where id = auth.uid()),\n    'concerns', coalesce((select jsonb_agg(jsonb_build_object(\n        'id', c.id, 'created_at', c.created_at, 'status', c.status, 'category', c.category, 'immediate_risk', c.immediate_risk,\n        'subject_kind', c.subject_kind, 'allegation', c.allegation,\n        'child', case when s.id is not null then s.first_name || ' ' || s.last_name end, 'child_id', c.student_id,\n        'staff_member', sm.display_name, 'subject_text', c.subject_text,\n        'summary', c.summary, 'raised_by', ru.full_name,\n        'actions', coalesce((select jsonb_agg(jsonb_build_object('at', a.at, 'by', au.full_name, 'note', a.note, 'status_to', a.status_to) order by a.at)\n                               from safeguarding_action a left join user_account au on au.id = a.by_user where a.concern_id = c.id), '[]'::jsonb))\n        order by c.created_at)\n      from safeguarding_concern c left join student s on s.id = c.student_id left join staff_member sm on sm.id = c.subject_staff_id\n      left join user_account ru on ru.id = c.raised_by\n     where c.studio_id = p_studio and (sm.user_id is null or sm.user_id <> auth.uid())), '[]'::jsonb),\n    'staff_checks', coalesce((select jsonb_agg(jsonb_build_object('staff_member', sm.display_name, 'kind', k.kind, 'reference', k.reference,\n        'checked_on', k.checked_on, 'expires_on', k.expires_on, 'note', k.note) order by sm.display_name, k.checked_on)\n      from staff_check k join staff_member sm on sm.id = k.staff_id where k.studio_id = p_studio and k.deleted_at is null), '[]'::jsonb),\n    'legal_holds', coalesce((select jsonb_agg(jsonb_build_object('child', s.first_name || ' ' || s.last_name, 'reason', h.reason, 'set_at', h.set_at))\n      from safeguarding_hold h join student s on s.id = h.student_id where h.studio_id = p_studio), '[]'::jsonb),\n    'access_log', coalesce((select jsonb_agg(jsonb_build_object('at', a.at, 'who', u.full_name, 'what', a.what, 'concern_id', a.concern_id) order by a.at, a.id)\n      from safeguarding_access a left join user_account u on u.id = a.user_id\n     where a.studio_id = p_studio and (a.concern_id is null or app.can_read_concern(a.concern_id))), '[]'::jsonb),\n    'audit_log', coalesce((select jsonb_agg(jsonb_build_object('at', l.at, 'who', u.full_name, 'action', l.action, 'entity', l.entity,\n        'entity_id', l.entity_id, 'summary', l.summary) order by l.at, l.id)\n      from audit_log l left join user_account u on u.id = l.actor_id where l.studio_id = p_studio), '[]'::jsonb)\n  ) into out;\n  return out;\nend $$;\n\n-- ── UR-38 · \"Ask to delete\" ────────────────────────────────────────────────\nalter type request_kind add value if not exists 'data_request';\n\ncreate or replace function app.request_family_erasure(p_note text default null) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare f record; rid uuid;\nbegin\n  select fm.id, fm.studio_id into f from family fm where fm.id in (select app.guardian_family_ids()) and fm.deleted_at is null limit 1;\n  if f.id is null then raise exception 'FORBIDDEN: only a parent or carer can ask' using errcode = 'insufficient_privilege'; end if;\n  insert into studio_request (studio_id, family_id, kind, subject, body, raised_by)\n  values (f.studio_id, f.id, 'data_request'::text::request_kind, 'Please delete our family’s data',\n          coalesce(nullif(btrim(p_note), '') || E'\\n\\n', '') ||\n          'Asked from the Privacy page. Reply within one month. Some records must be kept for a set time (invoices for six years; '\n          || 'safeguarding records as the school’s policy requires); everything else should be deleted or anonymised.',\n          auth.uid())\n  returning id into rid;\n  perform app.notify_admins(f.studio_id, 'request', 'A family asked for their data to be deleted', 'Reply within one month.', '/requests');\n  return rid;\nend $$;\n\n-- ── Grants ─────────────────────────────────────────────────────────────────\nrevoke all on function app.consent_effective(uuid, text), app.retention_hold_reason(uuid, smallint) from public;\nrevoke all on function app.can_see_consent(uuid), app.consent_now(uuid, text), app.consents(uuid), app.consent_history(uuid),\n  app.set_consent(uuid, text, boolean, text, boolean), app.has_consent(uuid, consent_kind),\n  app.can_read_concern(uuid), app.raise_concern_about(uuid, text, uuid, uuid, text, text, text, boolean), app.raise_concern(uuid, text, text, boolean),\n  app.safeguarding_log(uuid, uuid), app.safeguarding_actions(uuid, uuid), app.safeguarding_act(uuid, text, text), app.safeguarding_access_log(uuid),\n  app.safeguarding_students(uuid), app.set_safeguarding_hold(uuid, text), app.release_safeguarding_hold(uuid), app.safeguarding_holds(uuid),\n  app.apply_retention(uuid, boolean), app.staff_check_summary(uuid), app.remind_staff_checks(uuid),\n  app.set_welfare_watch(uuid, boolean, text), app.welfare_absences(uuid), app.safeguarding_export(uuid), app.request_family_erasure(text) from public;\ngrant execute on function app.can_see_consent(uuid), app.consent_now(uuid, text), app.consent_kinds(), app.consents(uuid), app.consent_history(uuid),\n  app.set_consent(uuid, text, boolean, text, boolean), app.has_consent(uuid, consent_kind),\n  app.can_read_concern(uuid), app.raise_concern_about(uuid, text, uuid, uuid, text, text, text, boolean), app.raise_concern(uuid, text, text, boolean),\n  app.safeguarding_log(uuid, uuid), app.safeguarding_actions(uuid, uuid), app.safeguarding_act(uuid, text, text), app.safeguarding_access_log(uuid),\n  app.safeguarding_students(uuid), app.set_safeguarding_hold(uuid, text), app.release_safeguarding_hold(uuid), app.safeguarding_holds(uuid),\n  app.apply_retention(uuid, boolean), app.staff_check_summary(uuid), app.remind_staff_checks(uuid),\n  app.set_welfare_watch(uuid, boolean, text), app.welfare_absences(uuid), app.safeguarding_export(uuid), app.request_family_erasure(text) to authenticated;\n"},{name:"0048_register_fixes.sql",sql:"-- ============================================================================\n-- 0048 · Register fixes from the end-user panel (UR-04, UR-07, UR-27, UR-36,\n--        UR-37, UR-49, UR-54, UR-56)\n-- ----------------------------------------------------------------------------\n--  1. School settings: register window, travel between sites, make-ups.\n--  2. Marks know what kind of mark they are, so a late \"mark the rest\" can\n--     never overwrite a mark someone actually made (UR-04).\n--  3. Registers can be changed only around the class; the office amends\n--     later with a reason (UR-37).\n--  4. Absence reports reach the session and the register (UR-07), and\n--     students of 13 and over can report their own (UR-49).\n--  5. Cancelling tells booked trial families before their trial is cancelled,\n--     and asks the office to rebook (UR-36). Students hear about\n--     cancellations and cover in their own bell (UR-49).\n--  6. Cover: a clash check with travel time, a handover note, and access to\n--     the children only on the day (UR-27).\n--  7. Make-up offers after a cancellation or a reported absence (UR-56).\n--  8. Small things: a session's state for a stale link, attendance \"this\n--     term\" (UR-54).\n-- ============================================================================\n\n-- ── 1. Settings ────────────────────────────────────────────────────────────\nalter table studio add column register_opens_before_min smallint not null default 30\n  check (register_opens_before_min between 0 and 720);\nalter table studio add column register_edit_days smallint not null default 7\n  check (register_edit_days between 0 and 60);\nalter table studio add column cover_travel_min smallint not null default 20\n  check (cover_travel_min between 0 and 240);\n-- off: no make-ups offered · cancelled: when the school cancels a class ·\n-- cancelled_and_absence: also when a family reports an absence in advance.\nalter table studio add column makeup_policy text not null default 'off'\n  check (makeup_policy in ('off', 'cancelled', 'cancelled_and_absence'));\nalter table studio add column makeup_window_days smallint not null default 28\n  check (makeup_window_days between 1 and 120);\n\n-- ── 2. What kind of mark ───────────────────────────────────────────────────\n-- explicit: a teacher or the office tapped this child · reported: the family\n-- said in advance · rest: \"Mark the rest here\". An explicit mark beats the\n-- others whatever the clocks say; between marks of the same kind the later\n-- device time wins (MARK_ATTENDANCE in lib/repos/teaching.ts).\nalter table attendance_record add column mark_kind text not null default 'explicit'\n  check (mark_kind in ('explicit', 'reported', 'rest'));\n\ncreate or replace function app.mark_rank(p_kind text) returns int\n  language sql immutable as $$\n  select case p_kind when 'rest' then 0 when 'reported' then 1 else 2 end\n$$;\ngrant execute on function app.mark_rank(text) to authenticated, service_role, anon;\n\n-- ── 3. The register window ─────────────────────────────────────────────────\ncreate or replace function app.register_window(p_session uuid)\n  returns table (opens_at timestamptz, closes_at timestamptz, state text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select cs.starts_at - make_interval(mins => st.register_opens_before_min),\n         cs.ends_at + make_interval(days => st.register_edit_days),\n         case when now() < cs.starts_at - make_interval(mins => st.register_opens_before_min) then 'early'\n              when now() > cs.ends_at + make_interval(days => st.register_edit_days) then 'late'\n              else 'open' end\n    from class_session cs join studio st on st.id = cs.studio_id\n   where cs.id = p_session\n$$;\nrevoke all on function app.register_window(uuid) from public;\ngrant execute on function app.register_window(uuid) to authenticated, service_role;\n\n-- Writes outside the window are refused, for teachers and the office alike.\n-- The office amends through app.amend_attendance, which records why.\n-- Advance absence reports (mark_kind 'reported', before the class) and work\n-- with no signed-in user or as the service role (the seed, imports, server\n-- jobs) are not register-taking.\ncreate or replace function app.guard_register_window() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare w record;\nbegin\n  if auth.uid() is null or current_setting('role', true) = 'service_role' then return new; end if;\n  -- Anyone else who may not write this register is refused by the policies.\n  if not (app.is_admin(new.studio_id) or exists (select 1 from class_session cs where cs.id = new.session_id\n            and cs.class_id in (select app.teacher_class_ids()))) and new.mark_kind <> 'reported' then\n    return new;\n  end if;\n  select * into w from app.register_window(new.session_id);\n  if w.state is null or w.state = 'open' then return new; end if;\n  if new.mark_kind = 'reported' and w.state = 'early' then return new; end if;\n  if app.is_admin(new.studio_id) and coalesce(current_setting('app.amend_reason', true), '') <> '' then return new; end if;\n  if w.state = 'early' then\n    raise exception 'REGISTER_LOCKED: this register opens at % — % minutes before the class',\n      to_char(w.opens_at at time zone (select timezone from studio where id = new.studio_id), 'HH24:MI \"on\" FMDay FMDD FMMonth'),\n      (select register_opens_before_min from studio where id = new.studio_id)\n      using errcode = 'check_violation';\n  end if;\n  raise exception 'REGISTER_LOCKED: this register can no longer be changed — ask the office to amend it'\n    using errcode = 'check_violation';\nend $$;\ncreate trigger attendance_window_guard before insert or update on attendance_record\n  for each row execute function app.guard_register_window();\n\n-- The office changes an old register, saying why. Audited.\ncreate or replace function app.amend_attendance(p_session uuid, p_student uuid, p_status attendance_status, p_reason text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; lbl text;\nbegin\n  select studio_id into sid from class_session where id = p_session and deleted_at is null;\n  if sid is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(sid) then raise exception 'FORBIDDEN: only the office can amend a register' using errcode = 'insufficient_privilege'; end if;\n  if coalesce(btrim(p_reason), '') = '' then raise exception 'INVALID: say why the register is being amended' using errcode = 'check_violation'; end if;\n  perform set_config('app.amend_reason', btrim(p_reason), true);\n  insert into attendance_record (studio_id, session_id, student_id, status, marked_by, client_marked_at, mark_kind)\n  values (sid, p_session, p_student, p_status, auth.uid(), now(), 'explicit')\n  on conflict (session_id, student_id) do update\n    set status = excluded.status, reason = null, marked_by = excluded.marked_by, marked_at = now(),\n        client_marked_at = excluded.client_marked_at, mark_kind = 'explicit', reported_by_guardian = false,\n        updated_at = now();\n  perform set_config('app.amend_reason', '', true);\n  lbl := app.session_label(p_session);\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'amend_register', 'class_session', p_session,\n          lbl || ': ' || (select first_name || ' ' || last_name from student where id = p_student)\n              || ' → ' || p_status::text || ' (' || btrim(p_reason) || ')');\nend $$;\nrevoke all on function app.amend_attendance(uuid, uuid, attendance_status, text) from public;\ngrant execute on function app.amend_attendance(uuid, uuid, attendance_status, text) to authenticated, service_role;\n\n-- Closing follows the same window for teachers.\ncreate or replace function app.close_register(p_session uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; cid uuid; unmarked integer; w record;\nbegin\n  select cs.studio_id, cs.class_id into sid, cid\n    from class_session cs where cs.id = p_session and cs.deleted_at is null;\n  if sid is null then return false; end if;\n\n  if not (app.is_admin(sid) or cid in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  select * into w from app.register_window(p_session);\n  if w.state <> 'open' and not app.is_admin(sid) then\n    raise exception 'REGISTER_LOCKED: %', case w.state when 'early' then 'this class has not started yet'\n      else 'this register can no longer be changed — ask the office' end using errcode = 'check_violation';\n  end if;\n\n  select count(*)::int into unmarked\n    from enrolment e\n   where e.class_id = cid and e.status = 'active' and e.deleted_at is null\n     and not exists (select 1 from attendance_record ar\n                      where ar.session_id = p_session and ar.student_id = e.student_id\n                        and ar.deleted_at is null);\n  if unmarked > 0 then\n    raise exception 'REGISTER_INCOMPLETE: % still unmarked', unmarked\n      using errcode = 'check_violation';\n  end if;\n\n  update class_session set register_closed_at = now(), updated_at = now() where id = p_session;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'close_register', 'class_session', p_session, 'register closed');\n  return true;\nend $$;\n\n-- ── 4. Absence reports ─────────────────────────────────────────────────────\ncreate table absence_report (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  session_id   uuid not null references class_session(id) on delete cascade,\n  note         text,\n  reporter     text not null check (reporter in ('guardian', 'student')),\n  reported_by  uuid references user_account(id) on delete set null,\n  status       text not null default 'active' check (status in ('active', 'withdrawn')),\n  communication_id uuid references communication(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  withdrawn_at timestamptz\n);\ncreate unique index absence_report_once on absence_report (session_id, student_id) where status = 'active';\ncreate index absence_report_student on absence_report (student_id, created_at desc);\nalter table absence_report enable row level security;\nalter table absence_report force row level security;\n-- Read: the office, the class's teachers (cover on the day), the child's own\n-- guardians and the student. Writes go through the functions below.\ncreate policy absence_report_read on absence_report for select using (\n  studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id)\n    or exists (select 1 from class_session cs where cs.id = absence_report.session_id\n                 and cs.class_id in (select app.teacher_class_ids()))\n    or student_id in (select app.guardian_student_ids())\n    or student_id = app.student_self_id()));\ngrant select on absence_report to authenticated;\ngrant all on absence_report to service_role;\n\n-- Who may report for a child: their own guardians, or the student when 13+.\ncreate or replace function app.may_report_absence(p_student uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case\n    when p_student in (select app.guardian_student_ids()) then 'guardian'\n    when p_student = app.student_self_id()\n         and extract(year from age(current_date, (select date_of_birth from student where id = p_student))) >= 13 then 'student'\n  end\n$$;\ngrant execute on function app.may_report_absence(uuid) to authenticated;\n\n-- The child's own classes still to come: enrolled classes, a booked trial,\n-- drop-ins and make-ups. Only these days can be reported.\ncreate or replace function app.absence_options(p_student uuid, p_days int default 42)\n  returns table (session_id uuid, class_name text, starts_at timestamptz, ends_at timestamptz,\n                 report_id uuid, note text, withdrawable boolean)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if app.may_report_absence(p_student) is null then\n    raise exception 'FORBIDDEN: only a child''s own family can report an absence' using errcode = 'insufficient_privilege';\n  end if;\n  return query\n  with mine as (\n    select cs.id from class_session cs\n      join enrolment e on e.class_id = cs.class_id and e.student_id = p_student and e.status = 'active' and e.deleted_at is null\n    union select t.session_id from trial t where t.student_id = p_student and t.status = 'booked' and t.deleted_at is null and t.session_id is not null\n    union select d.session_id from drop_in_booking d where d.student_id = p_student and d.status = 'booked'\n  )\n  select cs.id, c.name, cs.starts_at, cs.ends_at, r.id, r.note, (r.id is not null and cs.starts_at > now())\n    from mine join class_session cs on cs.id = mine.id\n    join class c on c.id = cs.class_id\n    left join absence_report r on r.session_id = cs.id and r.student_id = p_student and r.status = 'active'\n   where cs.deleted_at is null and cs.status = 'scheduled'\n     and cs.starts_at > now() and cs.starts_at < now() + make_interval(days => greatest(1, least(p_days, 180)))\n   order by cs.starts_at;\nend $$;\nrevoke all on function app.absence_options(uuid, int) from public;\ngrant execute on function app.absence_options(uuid, int) to authenticated;\n\n-- One report per session. It pre-marks the register \"excused\" (reported), a\n-- mark the teacher can change on the day; a copy goes to the office inbox.\ncreate or replace function app.report_absence(p_student uuid, p_sessions uuid[], p_note text default null)\n  returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare who text; s student; sess record; n int := 0; days text[] := '{}'; cid uuid; note text; policy text;\nbegin\n  who := app.may_report_absence(p_student);\n  if who is null then\n    raise exception 'FORBIDDEN: only a child''s own family can report an absence' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(array_length(p_sessions, 1), 0) = 0 then\n    raise exception 'INVALID: choose at least one class' using errcode = 'check_violation';\n  end if;\n  select * into s from student where id = p_student;\n  note := nullif(btrim(coalesce(p_note, '')), '');\n  for sess in\n    select cs.id, cs.starts_at, c.name from class_session cs join class c on c.id = cs.class_id\n     where cs.id = any (p_sessions) order by cs.starts_at\n  loop\n    if not exists (select 1 from app.absence_options(p_student, 180) o where o.session_id = sess.id) then\n      raise exception 'INVALID: % on % is not a class % can be reported absent from — it has started, finished or is not theirs. Send a message instead.',\n        sess.name, to_char(sess.starts_at, 'FMDD Mon'), s.first_name using errcode = 'check_violation';\n    end if;\n    insert into absence_report (studio_id, student_id, session_id, note, reporter, reported_by)\n    values (s.studio_id, s.id, sess.id, note, who, auth.uid())\n    on conflict (session_id, student_id) where status = 'active' do update set note = excluded.note;\n    insert into attendance_record (studio_id, session_id, student_id, status, reason, reported_by_guardian,\n                                   marked_by, client_marked_at, mark_kind)\n    values (s.studio_id, sess.id, s.id, 'excused', note, true, auth.uid(), now(), 'reported')\n    on conflict (session_id, student_id) do update\n      set status = 'excused', reason = excluded.reason, reported_by_guardian = true, marked_by = excluded.marked_by,\n          marked_at = now(), client_marked_at = excluded.client_marked_at, mark_kind = 'reported', updated_at = now()\n      where app.mark_rank(attendance_record.mark_kind) <= 1;\n    days := days || (sess.name || ' ' || to_char(sess.starts_at at time zone (select timezone from studio where id = s.studio_id), 'FMDy DD Mon'));\n    n := n + 1;\n  end loop;\n\n  -- The office's copy, in the inbox as before.\n  insert into communication (studio_id, kind, channel, family_id, subject, body, sent_by)\n  values (s.studio_id, 'direct', 'in_app', s.family_id,\n          'Absence: ' || s.first_name || ' — ' || array_to_string(days, ', '),\n          coalesce(note, s.first_name || ' will not be at class.')\n            || case when who = 'student' then E'\\n\\nReported by ' || s.first_name || ' in the student app.' else '' end,\n          auth.uid())\n  returning id into cid;\n  update absence_report set communication_id = cid\n   where student_id = s.id and session_id = any (p_sessions) and status = 'active';\n\n  -- A student's own report also tells their family (UR-49); the office hears\n  -- through the inbox copy above, as for any message from a family.\n  if who = 'student' then\n    perform app.notify_family(s.family_id, 'absence_reported', s.first_name || ' can’t make ' || array_to_string(days, ', '),\n      coalesce(note, 'Reported in the student app.'), '/family/children');\n  end if;\n\n  select makeup_policy into policy from studio where id = s.studio_id;\n  if policy = 'cancelled_and_absence' then\n    perform app.offer_makeup(s.id, x, 'absence') from unnest(p_sessions) x;\n  end if;\n  return n;\nend $$;\nrevoke all on function app.report_absence(uuid, uuid[], text) from public;\ngrant execute on function app.report_absence(uuid, uuid[], text) to authenticated;\n\n-- Changed their mind: allowed until the class starts.\ncreate or replace function app.withdraw_absence(p_report uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r absence_report; starts timestamptz; lbl text;\nbegin\n  select * into r from absence_report where id = p_report and status = 'active';\n  if r.id is null then raise exception 'NOT_FOUND: that report' using errcode = 'no_data_found'; end if;\n  if app.may_report_absence(r.student_id) is null then\n    raise exception 'FORBIDDEN: not your report' using errcode = 'insufficient_privilege';\n  end if;\n  select starts_at into starts from class_session where id = r.session_id;\n  if starts <= now() then\n    raise exception 'INVALID: the class has started, so the teacher has the register now — send the studio a message instead'\n      using errcode = 'check_violation';\n  end if;\n  update absence_report set status = 'withdrawn', withdrawn_at = now() where id = r.id;\n  -- Only the family's pre-mark goes; a mark the teacher made stays.\n  delete from attendance_record where session_id = r.session_id and student_id = r.student_id and mark_kind = 'reported';\n  update makeup_offer set status = 'withdrawn', updated_at = now()\n   where from_session_id = r.session_id and student_id = r.student_id and reason = 'absence' and status = 'open';\n  lbl := app.session_label(r.session_id);\n  insert into communication (studio_id, kind, channel, family_id, subject, body, sent_by, reply_to)\n  select r.studio_id, 'direct', 'in_app', s.family_id, 'Absence withdrawn: ' || s.first_name || ' — ' || lbl,\n         s.first_name || ' will be at ' || lbl || ' after all.', auth.uid(), r.communication_id\n    from student s where s.id = r.student_id;\nend $$;\nrevoke all on function app.withdraw_absence(uuid) from public;\ngrant execute on function app.withdraw_absence(uuid) to authenticated;\n\n-- ── 5. Cancelling: trial families first, then the office rebooks (UR-36) ──\n-- Students with their own login hear about changes too (UR-49).\ncreate or replace function app.announce_session(p_session uuid, p_subject text, p_body text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; fam uuid; u uuid;\nbegin\n  select s.*, c.name, c.teacher_id as class_teacher into cs\n    from class_session s join class c on c.id = s.class_id where s.id = p_session;\n  insert into communication (studio_id, kind, channel, class_id, subject, body)\n  values (cs.studio_id, 'class_broadcast', 'in_app', cs.class_id, p_subject, p_body);\n  for fam in\n    select distinct st.family_id from enrolment e join student st on st.id = e.student_id\n     where e.class_id = cs.class_id and e.status = 'active' and e.deleted_at is null\n    union\n    select distinct st.family_id from trial t join student st on st.id = t.student_id\n     where t.session_id = cs.id and t.status = 'booked' and t.deleted_at is null\n    union\n    select distinct st.family_id from drop_in_booking d join student st on st.id = d.student_id\n     where d.session_id = cs.id and d.status = 'booked'\n  loop\n    perform app.notify_family(fam, 'schedule_change', p_subject, left(p_body, 140), '/family/schedule');\n  end loop;\n  for u in\n    select distinct st.user_id from student st\n     where st.user_id is not null and st.login_enabled and st.deleted_at is null\n       and (st.id in (select e.student_id from enrolment e where e.class_id = cs.class_id and e.status = 'active' and e.deleted_at is null)\n            or st.id in (select d.student_id from drop_in_booking d where d.session_id = cs.id and d.status = 'booked'))\n  loop\n    perform app.notify_user(cs.studio_id, u, 'schedule_change', p_subject, left(p_body, 140), '/learn/timetable');\n  end loop;\n  for u in\n    select distinct sm.user_id from staff_member sm\n     where sm.id in (cs.class_teacher, cs.teacher_id) and sm.user_id is not null\n  loop\n    perform app.notify_user(cs.studio_id, u, 'schedule_change', p_subject, left(p_body, 140), '/teach');\n  end loop;\nend $$;\n\ncreate or replace function app.cancel_session(p_session uuid, p_reason text, p_message text default null, p_notify boolean default true)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs class_session; lbl text; t record;\nbegin\n  select * into cs from class_session where id = p_session and deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then raise exception 'FORBIDDEN: only the office can cancel a class' using errcode = 'insufficient_privilege'; end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: already cancelled' using errcode = 'check_violation'; end if;\n  if cs.register_closed_at is not null then\n    raise exception 'INVALID: this class has already been taught — its register is closed' using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_reason), '') = '' then raise exception 'INVALID: give a reason' using errcode = 'check_violation'; end if;\n  lbl := app.session_label(p_session);\n  -- Tell everyone while the trials are still booked, so trial families are\n  -- among those told (announce_session selects booked trials).\n  if p_notify then\n    perform app.announce_session(p_session, 'Cancelled: ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), 'Sorry — ' || lbl || ' is cancelled (' || btrim(p_reason) || ').'));\n  end if;\n  -- Each trial needs a new date: the office is asked to rebook it.\n  for t in\n    select tr.id, tr.enquiry_id, st.first_name, st.last_name, st.family_id from trial tr join student st on st.id = tr.student_id\n     where tr.session_id = p_session and tr.status = 'booked' and tr.deleted_at is null\n  loop\n    -- A trial family often has no login yet: their copy goes by email.\n    if p_notify then\n      insert into outbound_message (studio_id, channel, to_name, to_address, subject, body, enquiry_id)\n      select cs.studio_id, 'email', g.full_name, g.email, 'Cancelled: ' || lbl,\n             coalesce(nullif(btrim(p_message), ''), 'Sorry — ' || lbl || ' is cancelled (' || btrim(p_reason) || ').')\n               || E'\\n\\nWe will be in touch to find ' || t.first_name || ' another date for their trial.', t.enquiry_id\n        from guardian g\n       where g.family_id = t.family_id and g.deleted_at is null and g.user_id is null and coalesce(g.email, '') ~ '@';\n    end if;\n    perform app.notify_admins(cs.studio_id, 'new_trial', 'Rebook a trial: ' || t.first_name || ' ' || t.last_name,\n      'Their trial at ' || lbl || ' was cancelled (' || btrim(p_reason) || '). Offer another date.', '/enrolment');\n  end loop;\n  update class_session set status = 'cancelled', cancel_reason = btrim(p_reason),\n         changed_at = now(), changed_by = auth.uid(), updated_at = now() where id = p_session;\n  update trial set status = 'cancelled', outcome_note = 'Session cancelled: ' || btrim(p_reason) || ' — to rebook', updated_at = now()\n   where session_id = p_session and status = 'booked';\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (cs.studio_id, auth.uid(), 'cancel', 'class_session', p_session, lbl || ': ' || btrim(p_reason));\nend $$;\n\n-- ── 6. Cover (UR-27) ───────────────────────────────────────────────────────\nalter table class_session add column handover_note text;\n\ncreate or replace function app.my_staff_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select id from staff_member where user_id = auth.uid() and deleted_at is null\n$$;\ngrant execute on function app.my_staff_ids() to authenticated;\n\n-- What the teacher is already doing around this session. Different sites\n-- need travel time between them (studio.cover_travel_min).\ncreate or replace function app.cover_clashes(p_session uuid, p_teacher uuid)\n  returns table (session_id uuid, class_name text, starts_at timestamptz, ends_at timestamptz,\n                 location text, needs_travel boolean)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from class_session where id = p_session;\n  if sid is null or not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office arranges cover' using errcode = 'insufficient_privilege';\n  end if;\n  return query\n  select o.id, c2.name, o.starts_at, o.ends_at, l2.name, (c2.location_id is distinct from c.location_id)\n    from class_session cs\n    join class c on c.id = cs.class_id\n    join studio st on st.id = cs.studio_id\n    join class_session o on o.studio_id = cs.studio_id and o.id <> cs.id and o.deleted_at is null and o.status <> 'cancelled'\n    join class c2 on c2.id = o.class_id and c2.deleted_at is null\n    left join location l2 on l2.id = c2.location_id\n   where cs.id = p_session\n     and (coalesce(o.teacher_id, c2.teacher_id) = p_teacher or c2.assistant_id = p_teacher)\n     and o.starts_at < cs.ends_at + case when c2.location_id is distinct from c.location_id\n                                          then make_interval(mins => st.cover_travel_min) else interval '0' end\n     and o.ends_at + case when c2.location_id is distinct from c.location_id\n                          then make_interval(mins => st.cover_travel_min) else interval '0' end > cs.starts_at\n   order by o.starts_at;\nend $$;\nrevoke all on function app.cover_clashes(uuid, uuid) from public;\ngrant execute on function app.cover_clashes(uuid, uuid) to authenticated, service_role;\n\ndrop function if exists app.cover_session(uuid, uuid, text, boolean);\ncreate function app.cover_session(p_session uuid, p_teacher uuid, p_message text default null,\n                                  p_notify_families boolean default false, p_handover text default null,\n                                  p_override boolean default false)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; who text; lbl text; u uuid; clash record; tz text;\nbegin\n  select s.*, c.teacher_id as class_teacher into cs from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then raise exception 'FORBIDDEN: only the office can arrange cover' using errcode = 'insufficient_privilege'; end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: that class is cancelled' using errcode = 'check_violation'; end if;\n  if p_teacher is not null then\n    select display_name, user_id into who, u from staff_member\n     where id = p_teacher and studio_id = cs.studio_id and status = 'active' and deleted_at is null;\n    if who is null then raise exception 'INVALID: choose an active teacher at this school' using errcode = 'check_violation'; end if;\n    if not p_override then\n      select * into clash from app.cover_clashes(p_session, p_teacher) limit 1;\n      if clash.session_id is not null then\n        tz := (select timezone from studio where id = cs.studio_id);\n        raise exception '%', 'CLASH: ' || who || ' teaches ' || clash.class_name || ' from '\n          || to_char(clash.starts_at at time zone tz, 'HH24:MI') || ' to ' || to_char(clash.ends_at at time zone tz, 'HH24:MI')\n          || coalesce(' at ' || clash.location, '')\n          || case when clash.needs_travel then ', a different site, so there is no time to travel' else '' end\n          using errcode = 'check_violation';\n      end if;\n    end if;\n    if p_teacher = cs.class_teacher then p_teacher := null; end if;   -- back to the usual teacher\n  end if;\n  lbl := app.session_label(p_session);\n  update class_session set teacher_id = p_teacher,\n         handover_note = coalesce(nullif(btrim(p_handover), ''), handover_note),\n         changed_at = now(), changed_by = auth.uid(), updated_at = now()\n   where id = p_session;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (cs.studio_id, auth.uid(), 'cover', 'class_session', p_session,\n          lbl || coalesce(': covered by ' || who, ': back to the usual teacher')\n             || case when p_override then ' (clash accepted)' else '' end);\n  if p_teacher is not null then\n    perform app.notify_user(cs.studio_id, u, 'cover_assigned', 'You are covering ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), 'The register, safety notes and handover are on your Today screen on the day.'), '/teach');\n  end if;\n  if p_notify_families and p_teacher is not null then\n    perform app.announce_session(p_session, 'Cover: ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), who || ' will be teaching ' || lbl || '.'));\n  end if;\n  update studio_request set status = 'answered', answer = coalesce('Covered by ' || who, 'No cover needed'),\n         answered_by = auth.uid(), answered_at = now()\n   where session_id = p_session and status in ('open', 'in_progress');\nend $$;\nrevoke all on function app.cover_session(uuid, uuid, text, boolean, text, boolean) from public;\ngrant execute on function app.cover_session(uuid, uuid, text, boolean, text, boolean) to authenticated, service_role;\n\n-- A teacher asking for cover can leave the handover with the request.\ndrop function if exists app.request_cover(uuid, text);\ncreate function app.request_cover(p_session uuid, p_reason text, p_handover text default null) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; rid uuid; me uuid;\nbegin\n  select s.*, c.teacher_id as class_teacher into cs from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  select id into me from staff_member where user_id = auth.uid() and studio_id = cs.studio_id and deleted_at is null;\n  if me is null or me <> coalesce(cs.teacher_id, cs.class_teacher) then\n    raise exception 'FORBIDDEN: you can only ask for cover for a class you are teaching' using errcode = 'insufficient_privilege';\n  end if;\n  if cs.starts_at < now() then raise exception 'INVALID: that class has already started' using errcode = 'check_violation'; end if;\n  insert into studio_request (studio_id, session_id, kind, subject, body, raised_by)\n  values (cs.studio_id, p_session, 'other', 'Cover needed: ' || app.session_label(p_session),\n          coalesce(nullif(btrim(p_reason), ''), 'Cover requested.')\n            || coalesce(E'\\n\\nHandover: ' || nullif(btrim(p_handover), ''), ''), auth.uid())\n  returning id into rid;\n  if nullif(btrim(p_handover), '') is not null then\n    update class_session set handover_note = btrim(p_handover), updated_at = now() where id = p_session;\n  end if;\n  return rid;\nend $$;\nrevoke all on function app.request_cover(uuid, text, text) from public;\ngrant execute on function app.request_cover(uuid, text, text) to authenticated, service_role;\n\n-- Cover gives the children's details on the session's day only (was two days\n-- before to fourteen after). The covering teacher still sees the session\n-- itself on their timetable ahead of time.\ncreate or replace function app.teacher_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id from class c\n    join staff_member s on s.id in (c.teacher_id, c.assistant_id)\n   where s.user_id = auth.uid() and s.deleted_at is null and c.deleted_at is null\n     and app.studio_writable(c.studio_id) and app.in_scope(c.studio_id)\n  union\n  select cs.class_id from class_session cs\n    join staff_member s on s.id = cs.teacher_id\n    join studio st on st.id = cs.studio_id\n   where s.user_id = auth.uid() and s.deleted_at is null and cs.deleted_at is null\n     and cs.status <> 'cancelled'\n     and (cs.starts_at at time zone st.timezone)::date = (now() at time zone st.timezone)::date\n     and app.studio_writable(cs.studio_id) and app.in_scope(cs.studio_id)\n$$;\n\ncreate policy session_cover_read on class_session for select\n  using (deleted_at is null and teacher_id in (select app.my_staff_ids()) and app.in_scope(studio_id));\n\n-- ── 7. Make-up offers (UR-56) ──────────────────────────────────────────────\n-- Kept small: an offer per child per missed session, booked into a suitable\n-- class with space as a free drop-in. Account credit for cancellations stays\n-- with billing (studio.credit_cancelled_classes); when that is on, it is the\n-- remedy and no make-up is offered for a cancellation.\ncreate table makeup_offer (\n  id               uuid primary key default gen_random_uuid(),\n  studio_id        uuid not null references studio(id) on delete cascade,\n  student_id       uuid not null references student(id) on delete cascade,\n  from_session_id  uuid not null references class_session(id) on delete cascade,\n  reason           text not null check (reason in ('cancelled', 'absence')),\n  status           text not null default 'open' check (status in ('open', 'booked', 'declined', 'withdrawn')),\n  booking_id       uuid references drop_in_booking(id) on delete set null,\n  booked_session_id uuid references class_session(id) on delete set null,\n  expires_on       date not null,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n  unique (from_session_id, student_id)\n);\nalter table makeup_offer enable row level security;\nalter table makeup_offer force row level security;\ncreate policy makeup_offer_read on makeup_offer for select using (\n  studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()) or student_id = app.student_self_id()));\ngrant select on makeup_offer to authenticated;\ngrant all on makeup_offer to service_role;\n\ncreate or replace function app.offer_makeup(p_student uuid, p_from uuid, p_reason text) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; s student; oid uuid; lbl text;\nbegin\n  select x.* into st from studio x join class_session cs on cs.studio_id = x.id where cs.id = p_from;\n  select * into s from student where id = p_student and deleted_at is null;\n  if st.id is null or s.id is null or st.makeup_policy = 'off' then return null; end if;\n  if p_reason = 'absence' and st.makeup_policy <> 'cancelled_and_absence' then return null; end if;\n  insert into makeup_offer (studio_id, student_id, from_session_id, reason, expires_on)\n  values (st.id, s.id, p_from, p_reason, current_date + st.makeup_window_days)\n  on conflict (from_session_id, student_id) do update set status = 'open', reason = excluded.reason, updated_at = now()\n    where makeup_offer.status in ('withdrawn', 'declined')\n  returning id into oid;\n  if oid is not null then\n    lbl := app.session_label(p_from);\n    perform app.notify_family(s.family_id, 'makeup_offer', 'A make-up class for ' || s.first_name,\n      'Instead of ' || lbl || ', choose another class with space by ' || to_char(current_date + st.makeup_window_days, 'FMDD Mon') || '.',\n      '/family');\n  end if;\n  return oid;\nend $$;\nrevoke all on function app.offer_makeup(uuid, uuid, text) from public, authenticated, anon;\n\ncreate or replace function app.on_session_cancelled_makeup() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; e record;\nbegin\n  if new.status <> 'cancelled' or old.status = 'cancelled' then return null; end if;\n  select * into st from studio where id = new.studio_id;\n  if st.makeup_policy = 'off' or st.credit_cancelled_classes then return null; end if;\n  for e in select en.student_id from enrolment en\n            where en.class_id = new.class_id and en.status = 'active' and en.deleted_at is null loop\n    perform app.offer_makeup(e.student_id, new.id, 'cancelled');\n  end loop;\n  return null;\nend $$;\ncreate trigger session_cancelled_makeup after update of status on class_session\n  for each row execute function app.on_session_cancelled_makeup();\n\ncreate or replace function app.may_book_makeup(p_offer uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from makeup_offer o where o.id = p_offer and (\n    app.is_admin(o.studio_id) or o.student_id in (select app.guardian_student_ids()) or o.student_id = app.student_self_id()))\n$$;\n\n-- Suitable: the same dance style, the child's age fits, still to come before\n-- the offer runs out, a place free, and not a class they are already in.\ncreate or replace function app.makeup_options(p_offer uuid)\n  returns table (session_id uuid, class_name text, starts_at timestamptz, location text, spaces int)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare o makeup_offer; src record; dob date;\nbegin\n  if not app.may_book_makeup(p_offer) then\n    raise exception 'FORBIDDEN: not your offer' using errcode = 'insufficient_privilege';\n  end if;\n  select * into o from makeup_offer where id = p_offer;\n  select c.dance_style_id into src from class_session cs join class c on c.id = cs.class_id where cs.id = o.from_session_id;\n  select date_of_birth into dob from student where id = o.student_id;\n  return query\n  select cs.id, c.name, cs.starts_at, l.name, (c.capacity - app.session_taken(cs.id))::int\n    from class_session cs join class c on c.id = cs.class_id and c.deleted_at is null\n    left join location l on l.id = c.location_id\n   where cs.studio_id = o.studio_id and cs.deleted_at is null and cs.status = 'scheduled'\n     and cs.id <> o.from_session_id\n     and cs.starts_at > now() and (cs.starts_at)::date <= o.expires_on\n     and c.dance_style_id is not distinct from src.dance_style_id\n     and (c.age_min is null or extract(year from age(cs.starts_at::date, dob)) >= c.age_min)\n     and (c.age_max is null or extract(year from age(cs.starts_at::date, dob)) <= c.age_max)\n     and app.session_taken(cs.id) < c.capacity\n     and not exists (select 1 from enrolment e where e.class_id = c.id and e.student_id = o.student_id\n                       and e.status = 'active' and e.deleted_at is null)\n     and not exists (select 1 from drop_in_booking d where d.session_id = cs.id and d.student_id = o.student_id\n                       and d.status in ('booked', 'held'))\n   order by cs.starts_at\n   limit 8;\nend $$;\nrevoke all on function app.makeup_options(uuid) from public;\ngrant execute on function app.makeup_options(uuid) to authenticated;\n\ncreate or replace function app.book_makeup(p_offer uuid, p_session uuid) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare o makeup_offer; bid uuid; lbl text; s student;\nbegin\n  if not app.may_book_makeup(p_offer) then\n    raise exception 'FORBIDDEN: not your offer' using errcode = 'insufficient_privilege';\n  end if;\n  select * into o from makeup_offer where id = p_offer for update;\n  if o.status <> 'open' then raise exception 'INVALID: this make-up has already been used' using errcode = 'check_violation'; end if;\n  if o.expires_on < current_date then raise exception 'INVALID: this make-up offer has run out' using errcode = 'check_violation'; end if;\n  if not exists (select 1 from app.makeup_options(p_offer) x where x.session_id = p_session) then\n    raise exception 'INVALID: that class is not open for a make-up — it may have filled' using errcode = 'check_violation';\n  end if;\n  insert into drop_in_booking (studio_id, session_id, student_id, price_minor, booked_by)\n  values (o.studio_id, p_session, o.student_id, 0, auth.uid())\n  returning id into bid;\n  update makeup_offer set status = 'booked', booking_id = bid, booked_session_id = p_session, updated_at = now()\n   where id = o.id;\n  select * into s from student where id = o.student_id;\n  lbl := app.session_label(p_session);\n  perform app.notify_admins(o.studio_id, 'new_enrolment', 'Make-up booked: ' || s.first_name || ' ' || s.last_name,\n    lbl || ', instead of ' || app.session_label(o.from_session_id) || '.', '/schedule');\n  return bid;\nend $$;\nrevoke all on function app.book_makeup(uuid, uuid) from public;\ngrant execute on function app.book_makeup(uuid, uuid) to authenticated;\n\ncreate or replace function app.decline_makeup(p_offer uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.may_book_makeup(p_offer) then\n    raise exception 'FORBIDDEN: not your offer' using errcode = 'insufficient_privilege';\n  end if;\n  update makeup_offer set status = 'declined', updated_at = now() where id = p_offer and status = 'open';\nend $$;\nrevoke all on function app.decline_makeup(uuid) from public;\ngrant execute on function app.decline_makeup(uuid) to authenticated;\n\n-- A make-up booking that is cancelled gives the offer back.\ncreate or replace function app.on_makeup_booking_cancelled() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.status = 'cancelled' and old.status <> 'cancelled' then\n    update makeup_offer set status = 'open', booking_id = null, booked_session_id = null, updated_at = now()\n     where booking_id = new.id and status = 'booked';\n  end if;\n  return null;\nend $$;\ncreate trigger makeup_booking_cancelled after update of status on drop_in_booking\n  for each row execute function app.on_makeup_booking_cancelled();\n\n-- ── 8. Small things (UR-54) ────────────────────────────────────────────────\n-- Why a register link shows nothing: it does not exist, it is someone else's\n-- class, or it is a cover that opens on the day. Says no more than that.\ncreate or replace function app.session_access(p_session uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case\n    when cs.id is null then 'missing'\n    when app.is_admin(cs.studio_id) then 'ok'\n    when not app.in_scope(cs.studio_id) then 'not_yours'\n    when cs.class_id in (select app.teacher_class_ids()) then 'ok'\n    when cs.teacher_id in (select app.my_staff_ids()) then 'cover_later'\n    else 'not_yours' end\n    from (select 1) one\n    left join class_session cs on cs.id = p_session and cs.deleted_at is null\n$$;\nrevoke all on function app.session_access(uuid) from public;\ngrant execute on function app.session_access(uuid) to authenticated;\n\n-- \"This term\": from the start of the term the school is in now (or the most\n-- recent one) to today.\ncreate or replace function app.current_term_start(p_studio uuid) returns date\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select max(starts_on) from term where studio_id = p_studio and deleted_at is null and starts_on <= current_date\n$$;\ngrant execute on function app.current_term_start(uuid) to authenticated;\n"},{name:"0049_progress_fixes.sql",sql:"-- ============================================================================\n-- 0049 · Progress fixes from the end-user panel (UR-25, UR-43, UR-44, UR-45,\n--        UR-48, UR-54 in part, UR-55)\n-- ----------------------------------------------------------------------------\n--   UR-25  feedback keeps its parts (chips, note, own words) so a teacher can\n--          reopen it; saving merges instead of replacing; an edit to shared\n--          feedback is stamped edited_at for families to see.\n--   UR-44  chip sets a teacher owns per class, an under-8 preset with simple\n--          words and stickers, and the class's effective set in one call.\n--   UR-48  a school setting: skill levels reach families at once, or with the\n--          share step (the default).\n--   UR-55  tracking depth per class (notes / notes + skills / full), defaulted\n--          by age band; families can opt a child out of skill tracking.\n--   UR-43  a dated history of every level, and \"to work on\" linked to a\n--          library resource.\n--   UR-45  support notes the office sets, and a support-needs summary for a\n--          teacher's own students. Staff only.\n--   UR-54  trial and drop-in children can receive class feedback; the\n--          notification about feedback opens the child it was about.\n-- ============================================================================\n\n-- ── Tracking depth (UR-55) ─────────────────────────────────────────────────\nalter table class add column tracking_depth text\n  check (tracking_depth is null or tracking_depth in ('notes', 'notes_skills', 'full'));\nalter table student add column skill_tracking_opt_out boolean not null default false;\n\ncreate or replace function app.depth_rank(p_depth text) returns int\n  language sql immutable as $$\n  select case p_depth when 'notes' then 1 when 'notes_skills' then 2 when 'full' then 3 else 3 end\n$$;\n\n-- By age band unless the class says otherwise: up to 8 notes only, up to 12\n-- notes and skills, older (or no upper age) everything.\ncreate or replace function app.age_band_depth(p_age_max int) returns text\n  language sql immutable as $$\n  select case when p_age_max is null then 'full' when p_age_max <= 8 then 'notes'\n              when p_age_max <= 12 then 'notes_skills' else 'full' end\n$$;\n\ncreate or replace function app.class_depth(p_class uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(c.tracking_depth, app.age_band_depth(c.age_max)) from class c where c.id = p_class\n$$;\n\n-- How deeply one child's progress in one style is tracked: the deepest of the\n-- classes they take in it; in a style they no longer take, by their age.\ncreate or replace function app.style_depth(p_student uuid, p_style uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(\n    (select c2.d from (select app.class_depth(c.id) d from enrolment e join class c on c.id = e.class_id\n                        where e.student_id = p_student and e.status = 'active' and e.deleted_at is null\n                          and c.dance_style_id = p_style) c2\n      order by app.depth_rank(c2.d) desc limit 1),\n    (select case when a < 8 then 'notes' when a < 13 then 'notes_skills' else 'full' end\n       from (select extract(year from age(current_date, s.date_of_birth))::int a from student s where s.id = p_student) x))\n$$;\n\ncreate or replace function app.set_class_depth(p_class uuid, p_depth text) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class;\nbegin\n  select * into c from class where id = p_class and deleted_at is null;\n  if c.id is null or not (app.is_admin(c.studio_id) or c.id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  if p_depth is not null and p_depth not in ('notes', 'notes_skills', 'full') then\n    raise exception 'INVALID: tracking is notes, notes_skills or full' using errcode = 'check_violation';\n  end if;\n  update class set tracking_depth = p_depth, updated_at = now() where id = c.id;\n  return app.class_depth(c.id);\nend $$;\n\n-- A family chooses whether their child's skill levels are recorded at all.\n-- Notes and milestones carry on either way.\ncreate or replace function app.set_skill_tracking(p_student uuid, p_tracked boolean) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null or not (app.is_admin(s.studio_id) or s.id in (select app.guardian_student_ids())) then\n    raise exception 'FORBIDDEN: only the family or the office can change this' using errcode = 'insufficient_privilege';\n  end if;\n  update student set skill_tracking_opt_out = not p_tracked, updated_at = now() where id = s.id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (s.studio_id, auth.uid(), 'update', 'student', s.id,\n          case when p_tracked then 'skill tracking switched on' else 'skill tracking switched off by the family' end);\n  return p_tracked;\nend $$;\n\ncreate or replace function app.skills_tracked(p_student uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce((select not s.skill_tracking_opt_out from student s where s.id = p_student), true)\n$$;\n\n-- ── Draft-then-publish skill levels (UR-48) ────────────────────────────────\nalter table studio add column skill_publish text not null default 'with_share'\n  check (skill_publish in ('immediate', 'with_share'));\n-- Everything recorded before this setting existed has already been seen.\nalter table skill_assessment add column published_at timestamptz default now();\n\ncreate or replace function app.set_skill_publish(p_studio uuid, p_mode text) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_admin(p_studio) then\n    raise exception 'FORBIDDEN: a school setting' using errcode = 'insufficient_privilege';\n  end if;\n  update studio set skill_publish = p_mode, updated_at = now() where id = p_studio;\n  return p_mode;\nend $$;\n\n-- Families and students see a level once it is published; staff see drafts.\ndrop policy if exists assessment_student_read on skill_assessment;\ncreate policy assessment_student_read on skill_assessment for select\n  using (deleted_at is null and published_at is not null and student_id = app.student_self_id()\n         and app.skills_tracked(student_id));\ndrop policy if exists assessment_guardian_read on skill_assessment;\ncreate policy assessment_guardian_read on skill_assessment for select\n  using (deleted_at is null and published_at is not null and student_id in (select app.guardian_student_ids())\n         and app.skills_tracked(student_id));\n\ncreate or replace function app.is_student_staff(p_student uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from student s where s.id = p_student and (app.is_admin(s.studio_id)\n    or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))))\n$$;\n\n-- Record a level. Teachers record in the styles they teach; nothing is\n-- recorded for a child whose family opted out, or in a notes-only class.\ncreate or replace function app.record_skill(p_student uuid, p_skill uuid, p_level assessment_level,\n                                            p_note text default null, p_feedback uuid default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; k record; aid uuid; staff uuid; mode text;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null or not (app.is_admin(s.studio_id)\n       or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids()))) then\n    raise exception 'FORBIDDEN: you record skills for children you teach' using errcode = 'insufficient_privilege';\n  end if;\n  select fs.id, fs.name, f.dance_style_id into k from framework_skill fs join skill_framework f on f.id = fs.framework_id\n   where fs.id = p_skill and fs.studio_id = s.studio_id and fs.deleted_at is null;\n  if k.id is null then raise exception 'NOT_FOUND: that skill' using errcode = 'no_data_found'; end if;\n  if s.skill_tracking_opt_out then\n    raise exception 'INVALID: the family has chosen not to have skill levels recorded' using errcode = 'check_violation';\n  end if;\n  if not app.is_admin(s.studio_id) and k.dance_style_id not in\n       (select c.dance_style_id from class c where c.id in (select app.teacher_class_ids()) and c.dance_style_id is not null) then\n    raise exception 'FORBIDDEN: you record skills in the styles you teach' using errcode = 'insufficient_privilege';\n  end if;\n  if app.depth_rank(app.style_depth(s.id, k.dance_style_id)) < 2 then\n    raise exception 'INVALID: this class keeps notes only, not skill levels' using errcode = 'check_violation';\n  end if;\n  select id into staff from staff_member where user_id = auth.uid() and studio_id = s.studio_id and deleted_at is null limit 1;\n  if exists (select 1 from skill_assessment a where a.student_id = s.id and a.skill_id = k.id and a.deleted_at is null\n              and a.assessed_on = current_date and a.level = p_level) then\n    return null;\n  end if;\n  select skill_publish into mode from studio where id = s.studio_id;\n  insert into skill_assessment (studio_id, student_id, feedback_id, dance_style_id, skill, skill_id, level, assessed_by,\n                                assessed_on, note, published_at)\n  values (s.studio_id, s.id, p_feedback, k.dance_style_id, k.name, k.id, p_level, staff, current_date,\n          nullif(btrim(p_note), ''), case when mode = 'immediate' then now() end)\n  returning id into aid;\n  return aid;\nend $$;\n\n-- Share a child's unshared skill changes with their family.\ncreate or replace function app.share_skills(p_student uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare n int;\nbegin\n  if not app.is_student_staff(p_student) then\n    raise exception 'FORBIDDEN: not your student' using errcode = 'insufficient_privilege';\n  end if;\n  update skill_assessment set published_at = now(), updated_at = now()\n   where student_id = p_student and published_at is null and deleted_at is null;\n  get diagnostics n = row_count;\n  return n;\nend $$;\n\n-- A child's current level in each skill of the styles they dance. Teachers\n-- see the styles they teach the child (D11); families see published levels\n-- only, and only where the class tracks skills; nothing if they opted out.\ncreate or replace function app.student_skills(p_student uuid)\n  returns table (framework_id uuid, framework text, skill_id uuid, skill text, ord smallint,\n                 level assessment_level, assessed_on date, previous assessment_level)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare st student; adm boolean; staff boolean;\nbegin\n  if not app.can_see_student(p_student) then return; end if;\n  select * into st from student s where s.id = p_student;\n  if st.skill_tracking_opt_out then return; end if;\n  adm := app.is_admin(st.studio_id);\n  staff := app.is_student_staff(p_student);\n  return query\n  with mine as (select distinct c.dance_style_id from enrolment e join class c on c.id = e.class_id\n                 where e.student_id = p_student and e.status = 'active' and e.deleted_at is null\n                   and app.depth_rank(app.class_depth(c.id)) >= 2\n                   and (adm or not staff or c.id in (select app.teacher_class_ids()))),\n       asm as (select a.skill_id sid, a.level lv, a.assessed_on dt, a.created_at ca from skill_assessment a\n                where a.student_id = p_student and a.deleted_at is null and (staff or a.published_at is not null))\n  select f.id, f.name, fs.id, fs.name, fs.position, l.lv, l.dt,\n         (select b.lv from asm b where b.sid = fs.id order by b.dt desc, b.ca desc offset 1 limit 1)\n    from skill_framework f join framework_skill fs on fs.framework_id = f.id and fs.deleted_at is null\n    left join lateral (select a.lv, a.dt from asm a where a.sid = fs.id order by a.dt desc, a.ca desc limit 1) l on true\n   where f.deleted_at is null and f.dance_style_id in (select m.dance_style_id from mine m)\n   order by f.name, fs.position;\nend $$;\n\n-- Every level ever recorded, dated (UR-43), with the style, whether the child\n-- still dances it (D6: orphaned skills) and how deeply that style is tracked.\ncreate or replace function app.skill_history(p_student uuid)\n  returns table (skill_id uuid, skill text, style_id uuid, style text, level assessment_level, assessed_on date,\n                 current_style boolean, depth text, published boolean)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare st student; staff boolean;\nbegin\n  if not app.can_see_student(p_student) then return; end if;\n  select * into st from student s where s.id = p_student;\n  if st.skill_tracking_opt_out then return; end if;\n  staff := app.is_student_staff(p_student);\n  return query\n  select a.skill_id, coalesce(fs.name, a.skill), a.dance_style_id, ds.name, a.level, a.assessed_on,\n         exists (select 1 from enrolment e join class c on c.id = e.class_id where e.student_id = p_student\n                   and e.status = 'active' and e.deleted_at is null and c.dance_style_id = a.dance_style_id),\n         app.style_depth(p_student, a.dance_style_id), a.published_at is not null\n    from skill_assessment a\n    left join framework_skill fs on fs.id = a.skill_id\n    left join dance_style ds on ds.id = a.dance_style_id\n   where a.student_id = p_student and a.deleted_at is null and (staff or a.published_at is not null)\n     and (staff or app.depth_rank(app.style_depth(p_student, a.dance_style_id)) >= 2)\n   order by a.assessed_on, a.created_at;\nend $$;\n\n-- ── Feedback that keeps its parts (UR-25) ──────────────────────────────────\nalter table feedback_note\n  add column going_well_chips text[],\n  add column work_on_chips    text[],\n  add column note             text,     -- the teacher's own words under \"going well\"\n  add column work_on_note     text,     -- and under \"to work on\"\n  add column edited_at        timestamptz,\n  add column work_on_resource_id uuid references resource(id) on delete set null;\n\n-- Split text written before the parts were kept: \"Chip, Chip. Own words\"\n-- becomes chips and words when every leading phrase is one of the school's.\ncreate or replace function app.split_feedback(p_studio uuid, p_text text, out chips text[], out rest text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare pos int; head text; pieces text[];\nbegin\n  chips := '{}'; rest := null;\n  if p_text is null or btrim(p_text) = '' then return; end if;\n  pos := strpos(p_text, '. ');\n  head := case when pos > 0 then left(p_text, pos - 1) else p_text end;\n  pieces := string_to_array(head, ', ');\n  if pieces <@ array(select fc.label from feedback_chip fc where fc.studio_id = p_studio) then\n    chips := pieces;\n    rest := case when pos > 0 then nullif(btrim(substr(p_text, pos + 2)), '') end;\n  else\n    rest := p_text;\n  end if;\nend $$;\n\ncreate or replace function app.compose_feedback(p_chips text[], p_words text) returns text\n  language sql immutable as $$\n  select nullif(concat_ws('. ', nullif(array_to_string(coalesce(p_chips, '{}'), ', '), ''), nullif(btrim(p_words), '')), '')\n$$;\n\n-- Keeps the parts and the text in step whoever writes the row, and marks an\n-- edit to something a family has already seen.\ncreate or replace function app.feedback_note_parts() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare p record;\nbegin\n  if tg_op = 'INSERT' then\n    if new.going_well_chips is null and new.note is null then\n      select * into p from app.split_feedback(new.studio_id, new.going_well);\n      new.going_well_chips := p.chips; new.note := p.rest;\n    end if;\n    if new.work_on_chips is null and new.work_on_note is null then\n      select * into p from app.split_feedback(new.studio_id, new.work_on);\n      new.work_on_chips := p.chips; new.work_on_note := p.rest;\n    end if;\n    return new;\n  end if;\n  -- A writer that changed the text and not the parts (an older screen, or\n  -- erasure under the retention policy): the parts follow the text.\n  if new.going_well is distinct from old.going_well and new.going_well_chips is not distinct from old.going_well_chips\n     and new.note is not distinct from old.note then\n    select * into p from app.split_feedback(new.studio_id, new.going_well);\n    new.going_well_chips := case when new.going_well is null then null else p.chips end;\n    new.note := p.rest;\n  end if;\n  if new.work_on is distinct from old.work_on and new.work_on_chips is not distinct from old.work_on_chips\n     and new.work_on_note is not distinct from old.work_on_note then\n    select * into p from app.split_feedback(new.studio_id, new.work_on);\n    new.work_on_chips := case when new.work_on is null then null else p.chips end;\n    new.work_on_note := p.rest;\n  end if;\n  if old.shared_at is not null and (new.going_well is distinct from old.going_well or new.work_on is distinct from old.work_on\n       or new.work_on_resource_id is distinct from old.work_on_resource_id) then\n    new.edited_at := now();\n  end if;\n  return new;\nend $$;\ncreate trigger feedback_note_parts before insert or update on feedback_note\n  for each row execute function app.feedback_note_parts();\n\nupdate feedback_note f set going_well_chips = (app.split_feedback(f.studio_id, f.going_well)).chips,\n                           note = (app.split_feedback(f.studio_id, f.going_well)).rest,\n                           work_on_chips = (app.split_feedback(f.studio_id, f.work_on)).chips,\n                           work_on_note = (app.split_feedback(f.studio_id, f.work_on)).rest\n where going_well_chips is null;\n\n-- Who may receive feedback for a session: the enrolled, and anyone trialling\n-- or dropping in to it (D12).\ncreate or replace function app.session_has_student(p_session uuid, p_student uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from class_session cs join enrolment e on e.class_id = cs.class_id and e.deleted_at is null\n                  where cs.id = p_session and e.student_id = p_student)\n      or exists (select 1 from trial t where t.session_id = p_session and t.student_id = p_student and t.deleted_at is null\n                    and t.status in ('booked', 'attended', 'converted'))\n      or exists (select 1 from drop_in_booking d where d.session_id = p_session and d.student_id = p_student and d.status = 'booked')\n$$;\n\n-- Save a class's feedback. p_items: [{student_id, going_well:[..], work_on:[..],\n-- note?, work_on_note?, private_note?, work_on_resource_id?, skills?:[{skill_id, level}],\n-- replace?}]. Without \"replace\" a save MERGES into what is there: chips are\n-- added, never dropped, and new words join the old ones. With \"replace\" (the\n-- screen loaded the saved parts and the teacher edited them) the item is the\n-- whole new state. Keys that are absent leave their column alone.\ncreate or replace function app.save_class_feedback(p_session uuid, p_items jsonb, p_share boolean default false)\n  returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; it jsonb; sk jsonb; f feedback_note; fid uuid; staff uuid; n int := 0; sid uuid;\n        in_gw text[]; in_wo text[]; in_note text; in_wnote text; repl boolean;\n        gw text[]; wo text[]; nt text; wn text; pn text; res uuid; style uuid;\nbegin\n  select x.id, x.class_id, c.studio_id, c.name, c.dance_style_id into cs\n    from class_session x join class c on c.id = x.class_id where x.id = p_session;\n  if cs.id is null or not (app.is_admin(cs.studio_id) or cs.class_id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  select id into staff from staff_member where user_id = auth.uid() and studio_id = cs.studio_id and deleted_at is null limit 1;\n  for it in select * from jsonb_array_elements(p_items) loop\n    sid := (it ->> 'student_id')::uuid;\n    if not app.session_has_student(cs.id, sid) then\n      raise exception 'INVALID: a child in the list is not in this class' using errcode = 'check_violation';\n    end if;\n    in_gw := array(select jsonb_array_elements_text(coalesce(it -> 'going_well', '[]')));\n    in_wo := array(select jsonb_array_elements_text(coalesce(it -> 'work_on', '[]')));\n    in_note := nullif(btrim(it ->> 'note'), '');\n    in_wnote := nullif(btrim(it ->> 'work_on_note'), '');\n    repl := coalesce((it ->> 'replace')::boolean, false);\n    select * into f from feedback_note where session_id = cs.id and student_id = sid and deleted_at is null;\n\n    if f.id is null or repl then\n      gw := in_gw; wo := in_wo; nt := in_note; wn := in_wnote;\n    else\n      gw := coalesce(f.going_well_chips, '{}') || array(select x from unnest(in_gw) x where not x = any(coalesce(f.going_well_chips, '{}')));\n      wo := coalesce(f.work_on_chips, '{}') || array(select x from unnest(in_wo) x where not x = any(coalesce(f.work_on_chips, '{}')));\n      nt := case when in_note is null or in_note = f.note then f.note when f.note is null then in_note\n                 when position(f.note in in_note) = 1 then in_note else f.note || ' ' || in_note end;\n      wn := case when in_wnote is null or in_wnote = f.work_on_note then f.work_on_note when f.work_on_note is null then in_wnote\n                 when position(f.work_on_note in in_wnote) = 1 then in_wnote else f.work_on_note || ' ' || in_wnote end;\n    end if;\n    pn := case when it ? 'private_note' then nullif(btrim(it ->> 'private_note'), '') else f.private_note end;\n    res := case when it ? 'work_on_resource_id' then nullif(it ->> 'work_on_resource_id', '')::uuid else f.work_on_resource_id end;\n\n    if f.id is null and coalesce(array_length(gw, 1), 0) = 0 and coalesce(array_length(wo, 1), 0) = 0 and nt is null and wn is null\n       and coalesce(jsonb_array_length(it -> 'skills'), 0) = 0 then\n      continue;\n    end if;\n\n    if f.id is null then\n      insert into feedback_note (studio_id, student_id, class_id, session_id, author_id, headline, going_well, work_on,\n                                 going_well_chips, work_on_chips, note, work_on_note, private_note, work_on_resource_id, shared_at)\n      values (cs.studio_id, sid, cs.class_id, cs.id, staff, cs.name, app.compose_feedback(gw, nt), app.compose_feedback(wo, wn),\n              gw, wo, nt, wn, pn, res, case when p_share then now() end)\n      returning id into fid;\n    else\n      fid := f.id;\n      update feedback_note set going_well = app.compose_feedback(gw, nt), work_on = app.compose_feedback(wo, wn),\n             going_well_chips = gw, work_on_chips = wo, note = nt, work_on_note = wn, private_note = pn,\n             work_on_resource_id = res,\n             shared_at = case when p_share then coalesce(shared_at, now()) else shared_at end, updated_at = now()\n       where id = fid;\n    end if;\n    for sk in select * from jsonb_array_elements(coalesce(it -> 'skills', '[]')) loop\n      -- A notes-only class (UR-55), or a family that opted out, records no levels.\n      select f2.dance_style_id into style from framework_skill fs2 join skill_framework f2 on f2.id = fs2.framework_id\n       where fs2.id = (sk ->> 'skill_id')::uuid;\n      if app.skills_tracked(sid) and app.depth_rank(app.style_depth(sid, style)) >= 2 then\n        perform app.record_skill(sid, (sk ->> 'skill_id')::uuid, (sk ->> 'level')::assessment_level, null, fid);\n      end if;\n    end loop;\n    if p_share then\n      update skill_assessment set published_at = now() where feedback_id = fid and published_at is null;\n    end if;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- Sharing a session's feedback also shares the skill levels recorded with it.\ncreate or replace function app.share_session_feedback(p_session uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; n int;\nbegin\n  select x.id, x.class_id, c.studio_id into cs from class_session x join class c on c.id = x.class_id where x.id = p_session;\n  if cs.id is null or not (app.is_admin(cs.studio_id) or cs.class_id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  update feedback_note set shared_at = now() where session_id = p_session and shared_at is null and deleted_at is null;\n  get diagnostics n = row_count;\n  update skill_assessment set published_at = now()\n   where published_at is null and deleted_at is null\n     and feedback_id in (select id from feedback_note where session_id = p_session and deleted_at is null);\n  return n;\nend $$;\n\n-- The notice about feedback opens the child it is about (parents D14).\ncreate or replace function app.on_feedback_shared() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student;\nbegin\n  if new.shared_at is not null and (tg_op = 'INSERT' or old.shared_at is null) then\n    select * into s from student where id = new.student_id;\n    if new.share_with_guardian then\n      perform app.notify_family(s.family_id, 'feedback_published', 'Feedback for ' || s.first_name,\n                                coalesce(left(new.going_well, 120), 'From ' || coalesce(new.headline, 'class')),\n                                '/family/feedback?child=' || s.id);\n    end if;\n    if new.share_with_student and s.user_id is not null and s.login_enabled then\n      perform app.notify_user(s.studio_id, s.user_id, 'feedback_published', 'New feedback from your teacher',\n                              coalesce(left(new.going_well, 120), ''), '/learn/feedback');\n    end if;\n  end if;\n  return null;\nend $$;\n\n-- ── Chip sets (UR-44) ──────────────────────────────────────────────────────\nalter table feedback_chip\n  add column class_id   uuid references class(id) on delete cascade,\n  add column band       text not null default 'standard' check (band in ('standard', 'under_8')),\n  add column sticker    text check (sticker is null or length(sticker) <= 8),\n  add column created_by uuid references user_account(id) on delete set null;\ncreate index feedback_chip_class on feedback_chip (class_id) where deleted_at is null;\n\n-- A teacher keeps their own set for a class they teach.\ndrop policy if exists chip_teacher on feedback_chip;\ncreate policy chip_teacher on feedback_chip for all\n  using (deleted_at is null and class_id in (select app.teacher_class_ids()))\n  with check (class_id in (select app.teacher_class_ids()));\n\n-- Simple words, with a sticker each, for the youngest classes.\ncreate or replace function app.ensure_young_chips(p_studio uuid) returns void\n  language sql security definer set search_path = public, app, pg_temp as $$\n  insert into feedback_chip (studio_id, kind, label, position, band, sticker)\n  select p_studio, k, l, n, 'under_8', st from (values\n    ('going_well', 'Listened beautifully', 1, '👂'), ('going_well', 'Tried something new', 2, '🌱'),\n    ('going_well', 'Lovely pointed toes', 3, '🩰'), ('going_well', 'Kind to friends', 4, '💛'),\n    ('going_well', 'Danced to the music', 5, '🎵'), ('going_well', 'Kept trying', 6, '⭐'),\n    ('work_on', 'Good listening', 1, '👂'), ('work_on', 'Pointy toes', 2, '🦶'),\n    ('work_on', 'Moving to the beat', 3, '🥁'), ('work_on', 'Taking turns', 4, '🤝'),\n    ('work_on', 'Show a grown-up at home', 5, '🏠'), ('work_on', 'Being brave', 6, '🦁')) v(k, l, n, st)\n  where not exists (select 1 from feedback_chip c where c.studio_id = p_studio and c.band = 'under_8' and c.class_id is null);\n$$;\nselect app.ensure_young_chips(id) from studio;\ncreate or replace function app.on_studio_young_chips() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin perform app.ensure_young_chips(new.id); return null; end $$;\ncreate trigger studio_young_chips after insert on studio for each row execute function app.on_studio_young_chips();\n\ncreate or replace function app.class_band(p_class uuid) returns text\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select case when c.age_max is not null and c.age_max <= 8 then 'under_8' else 'standard' end from class c where c.id = p_class\n$$;\n\n-- The phrases for one class: its own set if the teacher made one, otherwise\n-- the school's set for the class's age band.\ncreate or replace function app.class_chips(p_class uuid)\n  returns table (id uuid, kind text, label text, sticker text, chip_position smallint, own boolean)\n  language sql stable security invoker set search_path = public, app, pg_temp as $$\n  select fc.id, fc.kind, fc.label, fc.sticker, fc.position, true from feedback_chip fc\n   where fc.class_id = p_class and fc.deleted_at is null\n  union all\n  select fc.id, fc.kind, fc.label, fc.sticker, fc.position, false from feedback_chip fc\n   where fc.class_id is null and fc.deleted_at is null and fc.band = app.class_band(p_class)\n     and fc.studio_id = (select c.studio_id from class c where c.id = p_class)\n     and not exists (select 1 from feedback_chip o where o.class_id = p_class and o.deleted_at is null)\n  order by 2, 5, 3\n$$;\n\ncreate or replace function app.check_class_teacher(p_class uuid) returns class\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare c class;\nbegin\n  select * into c from class where id = p_class and deleted_at is null;\n  if c.id is null or not (app.is_admin(c.studio_id) or c.id in (select app.teacher_class_ids())) then\n    raise exception 'FORBIDDEN: not your class' using errcode = 'insufficient_privilege';\n  end if;\n  return c;\nend $$;\n\n-- Start a class's own set from what it uses now (does nothing if it has one).\ncreate or replace function app.customise_class_chips(p_class uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class; n int := 0;\nbegin\n  c := app.check_class_teacher(p_class);\n  if exists (select 1 from feedback_chip where class_id = c.id and deleted_at is null) then return 0; end if;\n  insert into feedback_chip (studio_id, class_id, kind, label, position, band, sticker, created_by)\n  select c.studio_id, c.id, fc.kind, fc.label, fc.position, fc.band, fc.sticker, auth.uid() from feedback_chip fc\n   where fc.studio_id = c.studio_id and fc.class_id is null and fc.deleted_at is null and fc.band = app.class_band(c.id);\n  get diagnostics n = row_count;\n  return n;\nend $$;\n\ncreate or replace function app.add_class_chip(p_class uuid, p_kind text, p_label text, p_sticker text default null) returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class; cid uuid;\nbegin\n  c := app.check_class_teacher(p_class);\n  if p_kind not in ('going_well', 'work_on') or length(btrim(coalesce(p_label, ''))) not between 2 and 40 then\n    raise exception 'INVALID: a phrase is 2 to 40 characters' using errcode = 'check_violation';\n  end if;\n  perform app.customise_class_chips(c.id);\n  select id into cid from feedback_chip where class_id = c.id and kind = p_kind and lower(label) = lower(btrim(p_label)) and deleted_at is null;\n  if cid is not null then return cid; end if;\n  insert into feedback_chip (studio_id, class_id, kind, label, position, band, sticker, created_by)\n  values (c.studio_id, c.id, p_kind, btrim(p_label),\n          coalesce((select max(position) + 1 from feedback_chip where class_id = c.id and kind = p_kind and deleted_at is null), 1),\n          app.class_band(c.id), nullif(btrim(p_sticker), ''), auth.uid())\n  returning id into cid;\n  return cid;\nend $$;\n\ncreate or replace function app.remove_class_chip(p_class uuid, p_kind text, p_label text) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class;\nbegin\n  c := app.check_class_teacher(p_class);\n  perform app.customise_class_chips(c.id);\n  update feedback_chip set deleted_at = now()\n   where class_id = c.id and kind = p_kind and label = p_label and deleted_at is null;\n  return found;\nend $$;\n\n-- Back to the school's phrases.\ncreate or replace function app.reset_class_chips(p_class uuid) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class; n int;\nbegin\n  c := app.check_class_teacher(p_class);\n  update feedback_chip set deleted_at = now() where class_id = c.id and deleted_at is null;\n  get diagnostics n = row_count;\n  return n;\nend $$;\n\n-- ── Support needs (UR-45) ──────────────────────────────────────────────────\n-- Set by the office, read by the child's teachers. Never shown to a family\n-- or the child: it is a note for the people teaching them.\ncreate table student_support_note (\n  student_id uuid primary key references student(id) on delete cascade,\n  studio_id  uuid not null references studio(id) on delete cascade,\n  note       text not null check (length(btrim(note)) between 1 and 500),\n  updated_by uuid references user_account(id) on delete set null,\n  updated_at timestamptz not null default now()\n);\nalter table student_support_note enable row level security; alter table student_support_note force row level security;\ncreate policy support_admin on student_support_note for all\n  using (app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy support_teacher_read on student_support_note for select\n  using (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()));\ngrant select on student_support_note to authenticated;\ngrant all on student_support_note to service_role;\n\ncreate or replace function app.set_support_note(p_student uuid, p_note text) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student;\nbegin\n  select * into s from student where id = p_student and deleted_at is null;\n  if s.id is null or not app.is_admin(s.studio_id) then\n    raise exception 'FORBIDDEN: support notes are set by the office' using errcode = 'insufficient_privilege';\n  end if;\n  if nullif(btrim(p_note), '') is null then\n    delete from student_support_note where student_id = s.id;\n  else\n    insert into student_support_note (student_id, studio_id, note, updated_by) values (s.id, s.studio_id, btrim(p_note), auth.uid())\n    on conflict (student_id) do update set note = excluded.note, updated_by = excluded.updated_by, updated_at = now();\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (s.studio_id, auth.uid(), 'update', 'student_support_note', s.id, 'support note updated');\n  return true;\nend $$;\n\n-- For each of the caller's own students (every student, for the office): the\n-- run of absences up to the latest register in the caller's classes, skills\n-- assessed \"not started\", and the office's support note.\ncreate or replace function app.support_needs()\n  returns table (student_id uuid, absence_streak int, last_here date, not_yet int, support_note text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with mine as (\n    select s.id, s.studio_id, app.is_admin(s.studio_id) adm from student s\n     where s.deleted_at is null and app.in_scope(s.studio_id)\n       and (app.is_admin(s.studio_id) or (app.has_role(s.studio_id, 'teacher') and s.id in (select app.teacher_student_ids())))\n  )\n  select m.id,\n         (select count(*)::int from (\n            select a.status, count(*) filter (where a.status in ('present', 'late'))\n                     over (order by cs.starts_at desc rows unbounded preceding) seen\n              from attendance_record a join class_session cs on cs.id = a.session_id\n             where a.student_id = m.id and a.deleted_at is null and cs.starts_at <= now()\n               and (m.adm or cs.class_id in (select app.teacher_class_ids()))) x\n           where x.seen = 0 and x.status in ('absent', 'excused')),\n         (select max(cs.starts_at)::date from attendance_record a join class_session cs on cs.id = a.session_id\n           where a.student_id = m.id and a.deleted_at is null and a.status in ('present', 'late')),\n         (select count(*)::int from (\n            select distinct on (a.skill_id) a.level from skill_assessment a\n             where a.student_id = m.id and a.deleted_at is null and a.skill_id is not null\n             order by a.skill_id, a.assessed_on desc, a.created_at desc) l where l.level = 'not_started'),\n         (select n.note from student_support_note n where n.student_id = m.id)\n    from mine m\n$$;\n\n-- ── Grants ─────────────────────────────────────────────────────────────────\nrevoke all on function app.split_feedback(uuid, text), app.session_has_student(uuid, uuid), app.check_class_teacher(uuid)\n  from public;\ngrant execute on function app.depth_rank(text), app.age_band_depth(int), app.class_depth(uuid), app.style_depth(uuid, uuid),\n  app.set_class_depth(uuid, text), app.set_skill_tracking(uuid, boolean), app.skills_tracked(uuid),\n  app.set_skill_publish(uuid, text), app.is_student_staff(uuid), app.share_skills(uuid), app.skill_history(uuid),\n  app.compose_feedback(text[], text), app.class_band(uuid), app.class_chips(uuid), app.customise_class_chips(uuid),\n  app.add_class_chip(uuid, text, text, text), app.remove_class_chip(uuid, text, text), app.reset_class_chips(uuid),\n  app.set_support_note(uuid, text), app.support_needs() to authenticated;\ngrant execute on function app.split_feedback(uuid, text), app.session_has_student(uuid, uuid), app.check_class_teacher(uuid)\n  to authenticated;\n"},{name:"0050_public_fixes.sql",sql:"-- ============================================================================\n-- 0050 · Public page, one diary, events, owner reports, migration toolkit\n--        (UR-20, UR-42, UR-26, UR-50, UR-33, UR-34, UR-51, UR-32)\n-- ----------------------------------------------------------------------------\n-- Public page (/join)\n--   · Each class can say what level it is in plain words and what to wear or\n--     bring; with its description, ages and ongoing price these reach the\n--     public page through app.public_class_info().\n--   · The school's arrival advice and cancellation policy, and how to reach\n--     it, come from app.public_school_info() (sensible defaults until a\n--     school writes its own).\n--   · A trial booking may carry the child's allergies or medical needs, a\n--     second emergency contact and the family's photo choice. They are\n--     written to the child's medical record, emergency contacts and\n--     consent_record ('photography'), so the teacher's register brief shows\n--     them for the trial exactly as for any other child.\n--\n-- One diary\n--   · app.diary_items(user, from, to): every class, drop-in, rehearsal,\n--     performance, competition, private lesson and exam a person's children\n--     (or the student themselves) are down for, labelled by type. The\n--     family schedule, the student timetable and the calendar feed all read\n--     it, so the three cannot disagree.\n--\n-- Events\n--   · app.event_places(event): places taken and left, counted past RLS, so a\n--     parent sees the true number rather than only their own child.\n--   · app.my_event_status(): each of my children's status on each event.\n--   · Notices can name an event (communication.event_id).\n--   · A simple helper rota: slots with a role, time and number needed;\n--     guardians sign up and withdraw themselves; the office sees who.\n--\n-- Migration toolkit\n--   · app.import_classes(rows, commit): a timetable CSV, all-or-nothing,\n--     re-runnable without duplicates.\n--   · app.import_opening_balances(rows, as_at, commit): per family, a clearly\n--     labelled \"Opening balance\" invoice (money owed) or credit (money held),\n--     once per family per import, so a later billing run does not bill the\n--     same history again.\n-- ============================================================================\n\n-- ── Public page ────────────────────────────────────────────────────────────\nalter table class add column level_note text check (level_note is null or length(level_note) <= 200);\nalter table class add column what_to_bring text check (what_to_bring is null or length(what_to_bring) <= 400);\nalter table studio add column public_arrival_note text check (public_arrival_note is null or length(public_arrival_note) <= 400);\nalter table studio add column public_cancellation_note text check (public_cancellation_note is null or length(public_cancellation_note) <= 600);\n\n-- What a prospect needs to choose a class. Only public classes with a session\n-- in the next three weeks, one row per class name.\ncreate or replace function app.public_class_info(p_slug text)\n  returns table (class_name text, style text, description text, level text, level_note text, what_to_bring text,\n                 age_min smallint, age_max smallint, price_minor int, pricing text, trial_price_minor int,\n                 prerequisites text, location text, address text, postcode text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select distinct on (c.name)\n         c.name, ds.name, c.description, lv.name,\n         coalesce(c.level_note, case when c.prerequisites is null and (lv.name is null or lv.name ~* 'beginner|open|pre|intro|baby|tots|1$')\n                                     then 'No experience needed' end),\n         c.what_to_bring, c.age_min, c.age_max, c.price_minor, c.pricing::text, c.trial_price_minor,\n         c.prerequisites, l.name,\n         nullif(concat_ws(', ', nullif(btrim(l.address_line1), ''), nullif(btrim(l.address_line2), ''), nullif(btrim(l.city), '')), ''),\n         l.postcode\n    from studio st\n    join class c on c.studio_id = st.id and c.deleted_at is null and c.visibility = 'public'\n    join class_session cs on cs.class_id = c.id and cs.deleted_at is null and cs.status = 'scheduled'\n         and cs.starts_at between now() and now() + interval '21 days'\n    left join dance_style ds on ds.id = c.dance_style_id\n    left join level lv on lv.id = c.level_id\n    left join location l on l.id = c.location_id\n   where st.slug = lower(p_slug) and st.deleted_at is null and app.studio_writable(st.id)\n   order by c.name, cs.starts_at;\n$$;\n\ncreate or replace function app.public_school_info(p_slug text)\n  returns table (contact_email text, contact_phone text, arrival_note text, cancellation_note text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.contact_email, s.contact_phone,\n         coalesce(s.public_arrival_note, 'Please arrive 10 minutes early. The teacher will meet you at the door and show you where to change.'),\n         coalesce(s.public_cancellation_note, 'If you can’t come, please let the school know at least 24 hours before, so the place can go to someone else.')\n    from studio s where s.slug = lower(p_slug) and s.deleted_at is null and app.studio_writable(s.id);\n$$;\nrevoke all on function app.public_class_info(text), app.public_school_info(text) from public;\ngrant execute on function app.public_class_info(text), app.public_school_info(text) to authenticated, anon, service_role;\n\n-- The 0040 booking, plus the child's safety details (UR-42).\n-- Extra p_form keys, all optional: allergies, medical, emergency_name,\n-- emergency_phone, emergency_relationship, photo_consent ('true' | 'false').\ncreate or replace function app.public_book_trial(p_slug text, p_session uuid, p_form jsonb) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; cs record; enq uuid; tid uuid; dob date; kid uuid;\n        v_all text := nullif(btrim(p_form ->> 'allergies'), ''); v_med text := nullif(btrim(p_form ->> 'medical'), '');\n        v_en text := nullif(btrim(p_form ->> 'emergency_name'), ''); v_ep text := nullif(btrim(p_form ->> 'emergency_phone'), '');\n        v_photo text := nullif(p_form ->> 'photo_consent', '');\nbegin\n  select * into st from studio where slug = lower(p_slug) and deleted_at is null;\n  if st.id is null or not app.studio_writable(st.id) then\n    raise exception 'NOT_FOUND: that school' using errcode = 'no_data_found';\n  end if;\n  if coalesce(p_form ->> 'website', '') <> '' then return 'ok'; end if;   -- quietly drop bots\n  if coalesce(btrim(p_form ->> 'contact_name'), '') = '' or coalesce(btrim(p_form ->> 'child_name'), '') = ''\n     or coalesce(btrim(p_form ->> 'contact_phone'), '') = '' or coalesce(p_form ->> 'contact_email', '') !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n    raise exception 'INVALID: please give your name, email, a phone number and your child''s name' using errcode = 'check_violation';\n  end if;\n  dob := (p_form ->> 'child_dob')::date;\n  if dob is null or dob > current_date or dob < current_date - interval '100 years' then\n    raise exception 'INVALID: please check your child''s date of birth' using errcode = 'check_violation';\n  end if;\n  if length(coalesce(v_all, '')) > 500 or length(coalesce(v_med, '')) > 1000 or length(coalesce(v_en, '')) > 120 or length(coalesce(v_ep, '')) > 40 then\n    raise exception 'INVALID: please shorten the medical or emergency details' using errcode = 'check_violation';\n  end if;\n  if (v_en is null) <> (v_ep is null) then\n    raise exception 'INVALID: please give both a name and a phone number for the emergency contact' using errcode = 'check_violation';\n  end if;\n  select s.id, s.class_id, c.trial_price_minor into cs\n    from app.public_trial_sessions(p_slug) p join class_session s on s.id = p.session_id\n    join class c on c.id = s.class_id where p.session_id = p_session;\n  if cs.id is null then\n    raise exception 'INVALID: that class is full or no longer open for trials — please pick another' using errcode = 'check_violation';\n  end if;\n  -- One booking per email per session, so a double-click is not two trials.\n  if exists (select 1 from trial t join enquiry e on e.id = t.enquiry_id\n              where t.session_id = cs.id and lower(e.contact_email) = lower(btrim(p_form ->> 'contact_email'))\n                and lower(e.child_name) = lower(btrim(p_form ->> 'child_name')) and t.deleted_at is null) then\n    return 'ok';\n  end if;\n  perform app.public_guard(st.id, 'trial', p_form);\n  insert into enquiry (studio_id, stage, contact_name, contact_email, contact_phone, child_name, child_dob,\n                       interest_class_id, source, marketing_consent)\n  values (st.id, 'trial_booked', btrim(p_form ->> 'contact_name'), lower(btrim(p_form ->> 'contact_email')),\n          btrim(p_form ->> 'contact_phone'), btrim(p_form ->> 'child_name'), dob, cs.class_id, 'website',\n          coalesce(p_form ->> 'marketing', '') in ('true', 't', 'yes', 'on'))\n  returning id into enq;\n  insert into trial (studio_id, class_id, session_id, enquiry_id, status, price_minor)\n  values (st.id, cs.class_id, cs.id, enq, 'booked', cs.trial_price_minor)\n  returning id into tid;\n  kid := app.ensure_trial_student(tid);\n\n  -- The safety details go where the register brief already looks.\n  if kid is not null then\n    if v_all is not null or v_med is not null then\n      insert into medical_record (studio_id, student_id, allergies, conditions)\n      values (st.id, kid, v_all, v_med)\n      on conflict (student_id) do update set allergies = coalesce(excluded.allergies, medical_record.allergies),\n             conditions = coalesce(excluded.conditions, medical_record.conditions), updated_at = now();\n    end if;\n    if v_ep is not null then\n      insert into emergency_contact (studio_id, student_id, full_name, relationship, phone, priority)\n      values (st.id, kid, v_en, coalesce(nullif(btrim(p_form ->> 'emergency_relationship'), ''), 'Emergency contact'), v_ep, 2);\n    end if;\n    if v_photo in ('true', 'false') then\n      insert into consent_record (studio_id, student_id, kind, granted, note)\n      -- Consent is a history (0047): each choice is a new row; the latest wins.\n      values (st.id, kid, 'photography', v_photo = 'true', 'Given on the trial booking form');\n    end if;\n  end if;\n  return 'ok';\nend $$;\n\n-- ── One diary (UR-26) ──────────────────────────────────────────────────────\n-- Not callable directly: it trusts p_user. app.my_diary and app.calendar_feed\n-- are the two ways in.\ncreate or replace function app.diary_items(p_user uuid, p_from timestamptz, p_to timestamptz)\n  returns table (uid text, item_kind text, title text, starts_at timestamptz, ends_at timestamptz,\n                 location text, status text, student_id uuid, child text, class_id uuid, ref_id uuid,\n                 style text, colour text, teacher text, detail text, studio_id uuid)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with kids as (\n    select s.id, s.first_name, s.studio_id from student s\n     where s.deleted_at is null and (\n           s.family_id in (select g.family_id from guardian g where g.user_id = p_user and g.deleted_at is null)\n        or (s.user_id = p_user and s.login_enabled))\n  ),\n  shows as (   -- events each child has a confirmed place on\n    select p.event_id, k.id as kid from event_participant p join kids k on k.id = p.student_id\n     where p.status = 'confirmed' and p.deleted_at is null\n  )\n  -- Classes\n  select cs.id::text, 'class', c.name, cs.starts_at, cs.ends_at,\n         nullif(concat_ws(', ', coalesce(sr.name, r.name), l.name), ''),\n         cs.status::text, k.id, k.first_name, c.id, cs.id, ds.name, ds.colour,\n         coalesce(cover.display_name, tm.display_name), null::text, c.studio_id\n    from kids k\n    join enrolment e on e.student_id = k.id and e.status = 'active' and e.deleted_at is null\n    join class c on c.id = e.class_id\n    join class_session cs on cs.class_id = c.id and cs.deleted_at is null\n    left join dance_style ds on ds.id = c.dance_style_id\n    left join staff_member tm on tm.id = c.teacher_id\n    left join staff_member cover on cover.id = cs.teacher_id\n    left join room r on r.id = c.room_id\n    left join room sr on sr.id = cs.room_id\n    left join location l on l.id = c.location_id\n   where cs.starts_at >= p_from and cs.starts_at < p_to\n  union all\n  -- Drop-ins\n  select cs.id::text, 'class', c.name, cs.starts_at, cs.ends_at,\n         nullif(concat_ws(', ', coalesce(sr.name, r.name), l.name), ''),\n         cs.status::text, k.id, k.first_name, c.id, cs.id, ds.name, ds.colour,\n         coalesce(cover.display_name, tm.display_name), 'Drop-in', c.studio_id\n    from kids k\n    join drop_in_booking d on d.student_id = k.id and d.status = 'booked'\n    join class_session cs on cs.id = d.session_id and cs.deleted_at is null\n    join class c on c.id = cs.class_id\n    left join dance_style ds on ds.id = c.dance_style_id\n    left join staff_member tm on tm.id = c.teacher_id\n    left join staff_member cover on cover.id = cs.teacher_id\n    left join room r on r.id = c.room_id\n    left join room sr on sr.id = cs.room_id\n    left join location l on l.id = c.location_id\n   where cs.starts_at >= p_from and cs.starts_at < p_to\n  union all\n  -- Shows, competitions, workshops, exam days and private lessons with a\n  -- confirmed place\n  select ev.id::text, ev.kind::text, ev.title, ev.starts_at, ev.ends_at,\n         coalesce(ev.venue, l.name), ev.status::text, k.id, k.first_name, null::uuid, ev.id, null, null,\n         tm.display_name, null, ev.studio_id\n    from shows sh join kids k on k.id = sh.kid\n    join studio_event ev on ev.id = sh.event_id and ev.deleted_at is null and ev.parent_event_id is null\n         and ev.status in ('published', 'cancelled')\n    left join location l on l.id = ev.location_id\n    left join staff_member tm on tm.id = ev.teacher_id\n   where ev.starts_at >= p_from and ev.starts_at < p_to\n  union all\n  -- Rehearsals for those shows\n  select r.id::text, 'rehearsal', r.title, r.starts_at, r.ends_at,\n         coalesce(r.venue, sh_ev.venue), r.status::text, k.id, k.first_name, null::uuid, r.id, null, null,\n         null, sh_ev.title, r.studio_id\n    from shows sh join kids k on k.id = sh.kid\n    join studio_event sh_ev on sh_ev.id = sh.event_id and sh_ev.deleted_at is null\n    join studio_event r on r.parent_event_id = sh_ev.id and r.deleted_at is null and r.status in ('published', 'cancelled')\n   where r.starts_at >= p_from and r.starts_at < p_to\n  union all\n  -- Exams entered (a day, not a time: shown from 09:00 in the school's zone)\n  select 'exam-' || en.id::text, 'exam', x.title || ' — ' || en.grade,\n         (x.exam_on + time '09:00') at time zone st.timezone, (x.exam_on + time '17:00') at time zone st.timezone,\n         x.venue, case en.status when 'withdrawn' then 'cancelled' else 'scheduled' end,\n         k.id, k.first_name, null::uuid, x.id, null, null, null,\n         nullif(concat_ws(' · ', x.board, case when en.result is not null then initcap(replace(en.result, '_', ' ')) end), ''),\n         x.studio_id\n    from kids k\n    join exam_entry en on en.student_id = k.id and en.status <> 'withdrawn'\n    join exam_session x on x.id = en.session_id and x.deleted_at is null\n    join studio st on st.id = x.studio_id\n   where (x.exam_on + time '09:00') at time zone st.timezone >= p_from\n     and (x.exam_on + time '09:00') at time zone st.timezone < p_to;\n$$;\nrevoke all on function app.diary_items(uuid, timestamptz, timestamptz) from public, authenticated, anon;\n\ncreate or replace function app.my_diary(p_from timestamptz, p_to timestamptz)\n  returns table (uid text, item_kind text, title text, starts_at timestamptz, ends_at timestamptz,\n                 location text, status text, student_id uuid, child text, class_id uuid, ref_id uuid,\n                 style text, colour text, teacher text, detail text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select d.uid, d.item_kind, d.title, d.starts_at, d.ends_at, d.location, d.status, d.student_id, d.child,\n         d.class_id, d.ref_id, d.style, d.colour, d.teacher, d.detail\n    from app.diary_items(auth.uid(), p_from, p_to) d\n   where auth.uid() is not null and app.studio_writable(d.studio_id) and app.in_scope(d.studio_id)\n   order by d.starts_at, d.child;\n$$;\nrevoke all on function app.my_diary(timestamptz, timestamptz) from public;\ngrant execute on function app.my_diary(timestamptz, timestamptz) to authenticated;\n\n-- The calendar feed: staff unchanged; families and students read the diary.\ncreate or replace function app.calendar_feed(p_token text)\n  returns table (uid text, title text, starts_at timestamptz, ends_at timestamptz, location text, status text, description text, calendar_name text)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t calendar_token; sname text;\nbegin\n  select * into t from calendar_token where token = p_token and revoked_at is null;\n  if t.token is null then raise exception 'NOT_FOUND: that calendar link has been replaced or turned off' using errcode = 'no_data_found'; end if;\n  update calendar_token set last_used_at = now() where token = p_token;\n  select name into sname from studio where id = t.studio_id;\n  if t.role = 'staff' then\n    return query\n    select cs.id::text || '@sanaa', c.name, cs.starts_at, cs.ends_at, coalesce(r.name || ', ', '') || coalesce(l.name, ''),\n           case when cs.status = 'cancelled' then 'CANCELLED' else 'CONFIRMED' end,\n           case when cs.status = 'cancelled' then 'This class is cancelled.' else null end, sname\n      from class_session cs join class c on c.id = cs.class_id\n      join staff_member sm on sm.id = coalesce(cs.teacher_id, c.teacher_id)\n      left join room r on r.id = coalesce(cs.room_id, c.room_id)\n      left join location l on l.id = c.location_id\n     where sm.user_id = t.user_id and c.studio_id = t.studio_id and cs.deleted_at is null\n       and cs.starts_at between now() - interval '14 days' and now() + interval '120 days'\n     order by cs.starts_at;\n    return;\n  end if;\n  return query\n  select d.uid || '@sanaa',\n         case d.item_kind when 'class' then '' when 'rehearsal' then 'Rehearsal: ' when 'exam' then 'Exam: '\n              when 'competition' then 'Competition: ' when 'show' then 'Show: ' when 'private_lesson' then ''\n              else initcap(replace(d.item_kind, '_', ' ')) || ': ' end\n           || d.title || coalesce(' — ' || string_agg(distinct d.child, ', '), ''),\n         d.starts_at, d.ends_at, d.location,\n         case when d.status = 'cancelled' then 'CANCELLED' else 'CONFIRMED' end,\n         case when d.status = 'cancelled' then 'This is cancelled.' else max(d.detail) end, sname\n    from app.diary_items(t.user_id, now() - interval '14 days', now() + interval '120 days') d\n   where d.studio_id = t.studio_id\n   group by d.uid, d.item_kind, d.title, d.starts_at, d.ends_at, d.location, d.status\n   order by d.starts_at;\nend $$;\n\n-- ── Events (UR-50) ─────────────────────────────────────────────────────────\n-- Places taken, counted past RLS: a parent otherwise counts only their own\n-- children and never sees \"full\".\ncreate or replace function app.event_places(p_event uuid) returns int\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select count(*)::int from event_participant p join studio_event e on e.id = p.event_id\n   where p.event_id = p_event and p.status = 'confirmed' and p.deleted_at is null\n     and e.studio_id in (select app.studio_ids());\n$$;\nrevoke all on function app.event_places(uuid) from public;\ngrant execute on function app.event_places(uuid) to authenticated;\n\n-- Notices about an event go to the families of everyone invited or going.\nalter table communication add column event_id uuid references studio_event(id) on delete set null;\ncreate index communication_event on communication (event_id) where event_id is not null;\n\ncreate or replace function app.send_event_notice(p_event uuid, p_subject text, p_body text) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare ev studio_event; n int;\nbegin\n  select * into ev from studio_event where id = p_event and deleted_at is null;\n  if ev.id is null or not app.is_admin(ev.studio_id) then\n    raise exception 'FORBIDDEN: only the office can send event notices' using errcode = 'insufficient_privilege';\n  end if;\n  if coalesce(btrim(p_body), '') = '' then raise exception 'INVALID: write the notice first' using errcode = 'check_violation'; end if;\n  insert into communication (studio_id, kind, channel, family_id, subject, body, sent_by, event_id)\n  select distinct ev.studio_id, 'direct'::comm_kind, 'in_app'::comm_channel, s.family_id,\n         coalesce(nullif(btrim(p_subject), ''), ev.title), btrim(p_body), auth.uid(), ev.id\n    from event_participant p join student s on s.id = p.student_id and s.deleted_at is null\n   where p.event_id = ev.id and p.deleted_at is null and p.status in ('invited', 'confirmed', 'requested');\n  get diagnostics n = row_count;\n  return n;\nend $$;\nrevoke all on function app.send_event_notice(uuid, text, text) from public;\ngrant execute on function app.send_event_notice(uuid, text, text) to authenticated;\n\n-- A helper rota: front of house, backstage, costumes, chaperones…\ncreate table event_helper_slot (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  event_id    uuid not null references studio_event(id) on delete cascade,\n  role        text not null check (length(btrim(role)) between 2 and 80),\n  starts_at   timestamptz,\n  ends_at     timestamptz,\n  needed      smallint not null default 1 check (needed between 1 and 50),\n  note        text check (note is null or length(note) <= 300),\n  created_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\ncreate table event_helper_signup (\n  id          uuid primary key default gen_random_uuid(),\n  slot_id     uuid not null references event_helper_slot(id) on delete cascade,\n  user_id     uuid not null references user_account(id) on delete cascade,\n  name        text not null,\n  phone       text,\n  created_at  timestamptz not null default now(),\n  unique (slot_id, user_id)\n);\nalter table event_helper_slot enable row level security;   alter table event_helper_slot force row level security;\nalter table event_helper_signup enable row level security; alter table event_helper_signup force row level security;\ncreate policy helper_slot_read on event_helper_slot for select using (deleted_at is null and studio_id in (select app.studio_ids()));\ncreate policy helper_slot_admin on event_helper_slot for all using (app.is_admin(studio_id)) with check (app.is_admin(studio_id));\ncreate policy helper_signup_read on event_helper_signup for select using (\n  user_id = auth.uid() or exists (select 1 from event_helper_slot sl where sl.id = slot_id and app.is_staff(sl.studio_id)));\ncreate policy helper_signup_admin on event_helper_signup for delete using (\n  exists (select 1 from event_helper_slot sl where sl.id = slot_id and app.is_admin(sl.studio_id)));\ngrant select, insert, update, delete on event_helper_slot to authenticated;\ngrant select, delete on event_helper_signup to authenticated;\ngrant all on event_helper_slot, event_helper_signup to service_role;\n\n-- Slot fill counts for anyone in the school; names only for staff.\ncreate or replace function app.helper_slots(p_event uuid)\n  returns table (id uuid, role text, starts_at timestamptz, ends_at timestamptz, needed int, note text,\n                 filled int, mine boolean, helpers text)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select sl.id, sl.role, sl.starts_at, sl.ends_at, sl.needed::int, sl.note,\n         (select count(*)::int from event_helper_signup u where u.slot_id = sl.id),\n         exists (select 1 from event_helper_signup u where u.slot_id = sl.id and u.user_id = auth.uid()),\n         case when app.is_staff(sl.studio_id) then\n           (select string_agg(u.name || coalesce(' (' || u.phone || ')', ''), ', ' order by u.created_at)\n              from event_helper_signup u where u.slot_id = sl.id) end\n    from event_helper_slot sl\n   where sl.event_id = p_event and sl.deleted_at is null and sl.studio_id in (select app.studio_ids())\n   order by sl.starts_at nulls first, sl.role;\n$$;\n\n-- A parent signs up (or drops out). Full slots refuse; one sign-up per person.\ncreate or replace function app.volunteer(p_slot uuid, p_on boolean) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sl event_helper_slot; g guardian; taken int;\nbegin\n  select * into sl from event_helper_slot where id = p_slot and deleted_at is null for update;\n  if sl.id is null then raise exception 'NOT_FOUND: that helper slot' using errcode = 'no_data_found'; end if;\n  select * into g from guardian where user_id = auth.uid() and studio_id = sl.studio_id and deleted_at is null\n   order by is_primary desc limit 1;\n  if g.id is null and not app.is_staff(sl.studio_id) then\n    raise exception 'FORBIDDEN: only families and staff of the school can help' using errcode = 'insufficient_privilege';\n  end if;\n  if not p_on then\n    delete from event_helper_signup where slot_id = sl.id and user_id = auth.uid();\n  else\n    select count(*) into taken from event_helper_signup where slot_id = sl.id;\n    if not exists (select 1 from event_helper_signup where slot_id = sl.id and user_id = auth.uid()) then\n      if taken >= sl.needed then raise exception 'INVALID: that slot is already filled — thank you for offering' using errcode = 'check_violation'; end if;\n      insert into event_helper_signup (slot_id, user_id, name, phone)\n      values (sl.id, auth.uid(), coalesce(g.full_name, (select full_name from user_account where id = auth.uid()), 'Helper'), g.phone);\n    end if;\n  end if;\n  return (select count(*)::int from event_helper_signup where slot_id = sl.id);\nend $$;\nrevoke all on function app.helper_slots(uuid), app.volunteer(uuid, boolean) from public;\ngrant execute on function app.helper_slots(uuid), app.volunteer(uuid, boolean) to authenticated;\n\n-- ── Migration toolkit (UR-32) ──────────────────────────────────────────────\n-- Day names as schools type them: Monday, mon, Mon., 1 (Monday) … 0/7 Sunday.\ncreate or replace function app.parse_weekday(p text) returns smallint\n  language sql immutable as $$\n  select case\n    when btrim(coalesce(p, '')) ~ '^[0-7]$' then (btrim(p)::int % 7)::smallint\n    else (array_position(array['su','mo','tu','we','th','fr','sa'], left(lower(btrim(coalesce(p, ''))), 2)) - 1)::smallint end;\n$$;\n\n-- A timetable, one row per class. Keys (all text):\n--   name*, style*, level, day*, time*, duration (minutes, default 60), location,\n--   room, teacher, capacity*, age_min, age_max, price (pounds), pricing\n--   (term | monthly | one_off | drop_in), term (name; default the newest open term)\n-- Styles and rooms that do not exist yet are created (and listed as warnings);\n-- a teacher not on the staff list is left unassigned with a warning. A class\n-- with the same name, term, day and time is already here and is skipped.\ncreate or replace function app.import_classes(p_rows jsonb, p_commit boolean default false)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; r jsonb; i int := 0; errs jsonb := '[]'::jsonb; warns jsonb := '[]'::jsonb;\n  v_day smallint; v_time time; v_dur int; v_cap int; v_amin int; v_amax int; v_price numeric;\n  v_term uuid; v_style uuid; v_level uuid; v_loc uuid; v_room uuid; v_teacher uuid; v_pricing text;\n  cid uuid; n_new int := 0; n_skip int := 0; n_sessions int := 0; made int;\n  new_styles text[] := '{}'; new_rooms text[] := '{}'; no_teacher text[] := '{}';\nbegin\n  select id into sid from studio where deleted_at is null and app.is_admin(id) and app.in_scope(id) limit 1;\n  perform app.require_admin(sid);\n  if p_commit and not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then\n    raise exception 'INVALID: the file has no rows' using errcode = 'check_violation';\n  end if;\n  if jsonb_array_length(p_rows) > 500 then\n    raise exception 'INVALID: import at most 500 classes at a time' using errcode = 'check_violation';\n  end if;\n\n  for pass in 1..2 loop\n    exit when pass = 2 and (not p_commit or jsonb_array_length(errs) > 0);\n    i := 0;\n    for r in select * from jsonb_array_elements(p_rows) loop\n      i := i + 1;\n      if pass = 1 then\n        if coalesce(btrim(r ->> 'name'), '') = '' then errs := errs || jsonb_build_object('row', i, 'message', 'No class name'); end if;\n        if coalesce(btrim(r ->> 'style'), '') = '' then errs := errs || jsonb_build_object('row', i, 'message', 'No dance style'); end if;\n      end if;\n      v_day := app.parse_weekday(r ->> 'day');\n      if v_day is null and pass = 1 then\n        errs := errs || jsonb_build_object('row', i, 'message', 'Cannot read the day \"' || coalesce(r ->> 'day', '') || '\" — use Monday, Tuesday…'); end if;\n      begin v_time := nullif(btrim(r ->> 'time'), '')::time;\n      exception when others then v_time := null; end;\n      if v_time is null and pass = 1 then\n        errs := errs || jsonb_build_object('row', i, 'message', 'Cannot read the time \"' || coalesce(r ->> 'time', '') || '\" — use 17:30'); end if;\n      begin\n        v_dur := coalesce(nullif(btrim(r ->> 'duration'), '')::int, 60);\n        v_cap := nullif(btrim(r ->> 'capacity'), '')::int;\n        v_amin := nullif(btrim(r ->> 'age_min'), '')::int;\n        v_amax := nullif(btrim(r ->> 'age_max'), '')::int;\n        v_price := coalesce(nullif(regexp_replace(coalesce(r ->> 'price', ''), '[£,\\s]', '', 'g'), '')::numeric, 0);\n      exception when others then\n        if pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Duration, places, ages and price must be numbers'); end if;\n        continue;\n      end;\n      if pass = 1 then\n        if v_dur not between 15 and 300 then errs := errs || jsonb_build_object('row', i, 'message', 'Duration must be 15 to 300 minutes'); end if;\n        if v_cap is null or v_cap < 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Places must be 1 or more'); end if;\n        if v_amin is not null and v_amax is not null and v_amax < v_amin then errs := errs || jsonb_build_object('row', i, 'message', 'The oldest age is below the youngest'); end if;\n        if v_price < 0 then errs := errs || jsonb_build_object('row', i, 'message', 'Price cannot be negative'); end if;\n      end if;\n      v_pricing := coalesce(nullif(lower(replace(btrim(r ->> 'pricing'), ' ', '_')), ''), 'term');\n      if v_pricing in ('per_term', 'termly') then v_pricing := 'term'; elsif v_pricing in ('per_month', 'month') then v_pricing := 'monthly';\n      elsif v_pricing in ('drop-in', 'per_class', 'payg') then v_pricing := 'drop_in'; elsif v_pricing in ('course', 'one-off') then v_pricing := 'one_off'; end if;\n      if v_pricing not in ('term', 'monthly', 'one_off', 'drop_in') and pass = 1 then\n        errs := errs || jsonb_build_object('row', i, 'message', 'Pricing \"' || (r ->> 'pricing') || '\" — use term, monthly, one-off or drop-in'); end if;\n\n      v_term := null;\n      if nullif(btrim(r ->> 'term'), '') is not null then\n        select id into v_term from term where studio_id = sid and deleted_at is null and lower(name) = lower(btrim(r ->> 'term'))\n         order by starts_on desc limit 1;\n        if v_term is null and pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'No term called \"' || (r ->> 'term') || '\"'); end if;\n      else\n        select id into v_term from term where studio_id = sid and deleted_at is null and status <> 'archived' order by starts_on desc limit 1;\n        if v_term is null and pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Add a term first, so the classes have dates'); end if;\n      end if;\n\n      v_loc := null;\n      if nullif(btrim(r ->> 'location'), '') is not null then\n        select id into v_loc from location where studio_id = sid and deleted_at is null and lower(name) = lower(btrim(r ->> 'location')) limit 1;\n        if v_loc is null and pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'No location called \"' || (r ->> 'location') || '\" — add it in Studio first'); end if;\n      else\n        select id into v_loc from location where studio_id = sid and deleted_at is null order by created_at limit 1;\n        if v_loc is null and pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Add a location first'); end if;\n      end if;\n\n      select id into v_style from dance_style where studio_id = sid and deleted_at is null and lower(name) = lower(btrim(r ->> 'style')) limit 1;\n      if v_style is null and nullif(btrim(r ->> 'style'), '') is not null and not (initcap(btrim(r ->> 'style')) = any(new_styles)) then\n        new_styles := new_styles || initcap(btrim(r ->> 'style'));\n      end if;\n      select id into v_level from level where studio_id = sid and deleted_at is null and lower(name) = lower(btrim(r ->> 'level')) limit 1;\n      v_room := null;\n      if nullif(btrim(r ->> 'room'), '') is not null and v_loc is not null then\n        select id into v_room from room where location_id = v_loc and deleted_at is null and lower(name) = lower(btrim(r ->> 'room')) limit 1;\n        if v_room is null and not (btrim(r ->> 'room') = any(new_rooms)) then new_rooms := new_rooms || btrim(r ->> 'room'); end if;\n      end if;\n      v_teacher := null;\n      if nullif(btrim(r ->> 'teacher'), '') is not null then\n        select id into v_teacher from staff_member where studio_id = sid and deleted_at is null and lower(display_name) = lower(btrim(r ->> 'teacher')) limit 1;\n        if v_teacher is null and not (btrim(r ->> 'teacher') = any(no_teacher)) then no_teacher := no_teacher || btrim(r ->> 'teacher'); end if;\n      end if;\n\n      if pass = 2 then\n        if exists (select 1 from class where studio_id = sid and deleted_at is null and term_id = v_term\n                     and lower(name) = lower(btrim(r ->> 'name')) and day_of_week = v_day and start_time = v_time) then\n          n_skip := n_skip + 1; continue;\n        end if;\n        if v_style is null then\n          insert into dance_style (studio_id, name) values (sid, initcap(btrim(r ->> 'style'))) returning id into v_style;\n        end if;\n        if v_room is null and nullif(btrim(r ->> 'room'), '') is not null then\n          insert into room (studio_id, location_id, name) values (sid, v_loc, btrim(r ->> 'room')) returning id into v_room;\n        end if;\n        insert into class (studio_id, term_id, dance_style_id, level_id, location_id, room_id, teacher_id, name,\n                           day_of_week, start_time, duration_min, capacity, age_min, age_max, price_minor, pricing, created_by)\n        values (sid, v_term, v_style, v_level, v_loc, v_room, v_teacher, btrim(r ->> 'name'), v_day, v_time, v_dur, v_cap,\n                v_amin, v_amax, round(v_price * 100)::int, v_pricing::pricing_model, auth.uid())\n        returning id into cid;\n        made := app.generate_class_sessions(cid);\n        n_new := n_new + 1; n_sessions := n_sessions + coalesce(made, 0);\n      end if;\n    end loop;\n  end loop;\n\n  if array_length(new_styles, 1) > 0 then warns := warns || jsonb_build_object('message', 'New dance styles will be added: ' || array_to_string(new_styles, ', ')); end if;\n  if array_length(new_rooms, 1) > 0 then warns := warns || jsonb_build_object('message', 'New rooms will be added: ' || array_to_string(new_rooms, ', ')); end if;\n  if array_length(no_teacher, 1) > 0 then warns := warns || jsonb_build_object('message', 'Not on your staff list, so left without a teacher: ' || array_to_string(no_teacher, ', ')); end if;\n\n  if not p_commit or jsonb_array_length(errs) > 0 then\n    if p_commit then\n      raise exception 'INVALID: % row(s) need fixing before anything is imported', jsonb_array_length(errs) using errcode = 'check_violation';\n    end if;\n    return jsonb_build_object('ok', jsonb_array_length(errs) = 0, 'rows', i, 'errors', errs, 'warnings', warns);\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'import', 'class', null, format('Imported %s classes with %s sessions; %s already here', n_new, n_sessions, n_skip));\n  return jsonb_build_object('ok', true, 'rows', i, 'classes', n_new, 'sessions', n_sessions, 'skipped', n_skip,\n                            'errors', '[]'::jsonb, 'warnings', warns);\nend $$;\n\n-- Opening balances. One per family, ever: re-running a file skips families\n-- that already have one.\ncreate table opening_balance (\n  id          uuid primary key default gen_random_uuid(),\n  studio_id   uuid not null references studio(id) on delete cascade,\n  family_id   uuid not null unique references family(id) on delete cascade,\n  as_at       date not null,\n  owed_minor  bigint not null default 0 check (owed_minor >= 0),\n  credit_minor bigint not null default 0 check (credit_minor >= 0),\n  invoice_id  uuid references invoice(id) on delete set null,\n  payment_id  uuid references payment(id) on delete set null,\n  term_id     uuid references term(id) on delete set null,\n  imported_by uuid references user_account(id) on delete set null,\n  created_at  timestamptz not null default now()\n);\nalter table opening_balance enable row level security; alter table opening_balance force row level security;\ncreate policy opening_balance_read on opening_balance for select using (app.is_admin(studio_id));\ngrant select on opening_balance to authenticated;\ngrant all on opening_balance to service_role;\n\n-- Keys (all text): parent_email or family (one of them*), balance (pounds owed;\n-- a negative figure is credit), credit (pounds held, optional).\n-- p_term: when the old system had already billed that term, the term whose\n-- fees are covered — each child's classes that term get a £0 line on the\n-- opening-balance invoice, which is what a billing run looks for when it\n-- decides who has already been billed. Leave it null otherwise.\ncreate or replace function app.import_opening_balances(p_rows jsonb, p_as_at date, p_commit boolean default false, p_term uuid default null)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid; r jsonb; i int := 0; errs jsonb := '[]'::jsonb; warns jsonb := '[]'::jsonb;\n  fam uuid; owed numeric; cred numeric; seen uuid[] := '{}'; inv uuid; pay uuid; items jsonb;\n  n_inv int := 0; n_cred int := 0; n_skip int := 0; total_owed bigint := 0; total_cred bigint := 0; lbl text;\nbegin\n  select id into sid from studio where deleted_at is null and app.is_admin(id) and app.in_scope(id) limit 1;\n  perform app.require_admin(sid);\n  if p_commit and not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if p_as_at is null or p_as_at > current_date then\n    raise exception 'INVALID: give the date the balances are \"as at\" — today or earlier' using errcode = 'check_violation';\n  end if;\n  if p_term is not null and not exists (select 1 from term where id = p_term and studio_id = sid and deleted_at is null) then\n    raise exception 'INVALID: that term is not this school''s' using errcode = 'check_violation';\n  end if;\n  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then\n    raise exception 'INVALID: the file has no rows' using errcode = 'check_violation';\n  end if;\n  lbl := 'Opening balance as at ' || to_char(p_as_at, 'FMDD Mon YYYY');\n\n  for pass in 1..2 loop\n    exit when pass = 2 and (not p_commit or jsonb_array_length(errs) > 0);\n    i := 0; seen := '{}';\n    for r in select * from jsonb_array_elements(p_rows) loop\n      i := i + 1;\n      fam := null;\n      if nullif(btrim(r ->> 'parent_email'), '') is not null then\n        select g.family_id into fam from guardian g join family f on f.id = g.family_id and f.deleted_at is null\n         where g.studio_id = sid and g.deleted_at is null and lower(g.email) = lower(btrim(r ->> 'parent_email')) limit 1;\n      end if;\n      if fam is null and nullif(btrim(r ->> 'family'), '') is not null then\n        select id into fam from family where studio_id = sid and deleted_at is null\n           and (lower(name) = lower(btrim(r ->> 'family')) or lower(name) = lower(btrim(r ->> 'family')) || ' family');\n      end if;\n      begin\n        owed := coalesce(nullif(regexp_replace(coalesce(r ->> 'balance', ''), '[£,\\s]', '', 'g'), '')::numeric, 0);\n        cred := coalesce(nullif(regexp_replace(coalesce(r ->> 'credit', ''), '[£,\\s]', '', 'g'), '')::numeric, 0);\n      exception when others then\n        if pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Balance and credit must be amounts, like 45.00'); end if;\n        continue;\n      end;\n      if owed < 0 then cred := cred - owed; owed := 0; end if;\n      if pass = 1 then\n        if fam is null then\n          errs := errs || jsonb_build_object('row', i, 'message', 'No family with ' ||\n            coalesce('the email \"' || nullif(btrim(r ->> 'parent_email'), '') || '\"', 'the name \"' || coalesce(r ->> 'family', '') || '\"') || ' — import families first');\n        elsif fam = any(seen) then\n          errs := errs || jsonb_build_object('row', i, 'message', 'This family is in the file twice');\n        end if;\n        if cred < 0 then errs := errs || jsonb_build_object('row', i, 'message', 'Credit cannot be negative'); end if;\n        if fam is not null and exists (select 1 from opening_balance where family_id = fam) then\n          warns := warns || jsonb_build_object('message', 'Row ' || i || ': this family already has an opening balance and will be left alone');\n        end if;\n        seen := seen || fam;\n        continue;\n      end if;\n\n      -- pass 2: write\n      if exists (select 1 from opening_balance where family_id = fam) then n_skip := n_skip + 1; continue; end if;\n      inv := null; pay := null;\n      if owed > 0 or p_term is not null then\n        items := jsonb_build_array(jsonb_build_object('kind', 'other', 'description', lbl || ' (brought forward from your previous system)',\n                                                      'unit_minor', round(owed * 100)::int));\n        if p_term is not null then\n          items := items || coalesce((select jsonb_agg(jsonb_build_object('kind', 'tuition', 'student_id', s.id, 'class_id', c.id, 'unit_minor', 0,\n                      'description', c.name || ' — ' || t.name || ' fees, billed in your previous system (' || s.first_name || ')'))\n                     from enrolment e join class c on c.id = e.class_id and c.term_id = p_term and c.deleted_at is null\n                     join term t on t.id = c.term_id\n                     join student s on s.id = e.student_id and s.family_id = fam and s.deleted_at is null\n                    where e.status = 'active' and e.deleted_at is null), '[]'::jsonb);\n        end if;\n        if owed > 0 or jsonb_array_length(items) > 1 then\n          inv := app.create_invoice_internal(fam, items, greatest(current_date, p_as_at + 14), lbl, 0, true, p_term);\n          update invoice set issued_on = p_as_at where id = inv;\n          update invoice_item set period_start = date_trunc('month', p_as_at)::date\n           where invoice_id = inv and class_id is not null\n             and (select pricing from class where id = invoice_item.class_id) = 'monthly';\n          n_inv := n_inv + 1; total_owed := total_owed + round(owed * 100)::bigint;\n        end if;\n      end if;\n      if cred > 0 then\n        insert into payment (studio_id, family_id, amount_minor, method, succeeded_at, note, recorded_by)\n        values (sid, fam, round(cred * 100)::bigint, 'credit', p_as_at::timestamptz, 'Opening credit as at ' || to_char(p_as_at, 'FMDD Mon YYYY') || ' (brought forward)', auth.uid())\n        returning id into pay;\n        perform app.allocate_account_credit_internal(fam);\n        n_cred := n_cred + 1; total_cred := total_cred + round(cred * 100)::bigint;\n      end if;\n      perform app.recalc_family_balance(fam);\n      insert into opening_balance (studio_id, family_id, as_at, owed_minor, credit_minor, invoice_id, payment_id, term_id, imported_by)\n      values (sid, fam, p_as_at, round(owed * 100)::bigint, round(cred * 100)::bigint, inv, pay, p_term, auth.uid());\n    end loop;\n  end loop;\n\n  if not p_commit or jsonb_array_length(errs) > 0 then\n    if p_commit then\n      raise exception 'INVALID: % row(s) need fixing before anything is imported', jsonb_array_length(errs) using errcode = 'check_violation';\n    end if;\n    return jsonb_build_object('ok', jsonb_array_length(errs) = 0, 'rows', i, 'errors', errs, 'warnings', warns);\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'import', 'invoice', null,\n          format('%s: %s families owe £%s, %s hold £%s credit; %s already had one', lbl, n_inv, to_char(total_owed / 100.0, 'FM999999990.00'),\n                 n_cred, to_char(total_cred / 100.0, 'FM999999990.00'), n_skip));\n  return jsonb_build_object('ok', true, 'rows', i, 'invoices', n_inv, 'credits', n_cred, 'skipped', n_skip,\n                            'owed_minor', total_owed, 'credit_minor', total_cred, 'errors', '[]'::jsonb, 'warnings', warns);\nend $$;\n\nrevoke all on function app.import_classes(jsonb, boolean), app.import_opening_balances(jsonb, date, boolean, uuid), app.parse_weekday(text) from public;\ngrant execute on function app.import_classes(jsonb, boolean), app.import_opening_balances(jsonb, date, boolean, uuid), app.parse_weekday(text) to authenticated;\n"},{name:"0051_integration.sql",sql:"-- ============================================================================\n-- 0051 · Joining up the panel-review fixes (0044–0050)\n-- ----------------------------------------------------------------------------\n-- The fixes were built in parallel. This migration connects the pieces that\n-- each stream deliberately left to whoever brought them together:\n--   · the scheduled tick now sends \"invoice due in 3 days\" notices (0045) and\n--     expires waiting-list offers that have run out (0044), so the next family\n--     is offered the place without anyone opening the app.\n-- ============================================================================\n\ncreate or replace function app.tick() returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s record; auto int := 0; released int := 0; checks int := 0; holds int; digests int;\n        due int := 0; offers int := 0; n int;\nbegin\n  holds := app.expire_held_drop_ins();\n  for s in select id from studio where deleted_at is null and app.studio_writable(id) loop\n    auto := auto + coalesce(app.run_automations(s.id), 0);\n    released := released + app.release_scheduled(s.id);\n    checks := checks + app.remind_staff_checks(s.id);\n    perform app.award_event_milestones(s.id);\n    -- Waiting-list offers past their expiry go to the next family (UR-19).\n    begin\n      n := app.expire_waitlist_offers(s.id);\n      offers := offers + coalesce(n, 0);\n    exception when others then null;   -- one school's data must not stop the rest\n    end;\n    due := due + coalesce(app.notify_invoices_due(s.id), 0);\n  end loop;\n  digests := app.send_digests();\n  return jsonb_build_object('automations', auto, 'released', released, 'staff_checks', checks,\n                            'holds_lapsed', holds, 'digests', digests, 'invoices_due', due,\n                            'offers_expired', offers, 'at', now());\nend $$;\n"},{name:"0052_money_fixes.sql",sql:"-- ============================================================================\n-- 0052 · Money follow-ons from the panel review (UR-52, UR-56, UR-17)\n-- ----------------------------------------------------------------------------\n-- 1. Moving a child to another class has an effective date (UR-52). Today by\n--    default; a future date plans the move; a past date (the office only,\n--    back to the start of the current term) records one that already\n--    happened. Registers before the date keep the child in the old class,\n--    from the date in the new one. Billing runs bill each class up to or from\n--    the date, and app.move_preview gives the office a pro-rata note.\n-- 2. Credit for reported absences (UR-56). A school setting, off by default:\n--    when a family reports an absence in advance, the child's enrolled class\n--    is credited on account (its per-session value, or a fixed amount), once\n--    per child per session, and taken back if the report is withdrawn before\n--    the class. A school offers make-ups for absences or credit, not both.\n-- 3. Split billing between guardians (UR-17). Per family, the office chooses:\n--    the whole family as today; one guardian; a percentage split between two;\n--    or each child to a guardian. Billing runs raise one invoice per paying\n--    guardian. A guardian sees only invoices addressed to them (or to the\n--    family); the office sees all. The run guard counts each guardian's share\n--    separately, so a split is never mistaken for billing a family twice.\n-- ============================================================================\n\n-- ── 1. Moves with an effective date (UR-52) ────────────────────────────────\n-- moved_from: on the new place, the place it came from. moved_to: on the old\n-- place, where the child went. A planned move leaves the old place active\n-- with ended_on set to the move date until the date arrives.\nalter table enrolment add column moved_from uuid references enrolment(id) on delete set null;\nalter table enrolment add column moved_to   uuid references enrolment(id) on delete set null;\ncreate index enrolment_moving on enrolment (ended_on) where moved_to is not null and status = 'active';\n\n-- Is this place in the class on this day? Places that never moved keep the\n-- old meaning (active = in the class), so nothing else changes for them.\ncreate or replace function app.enrolment_on(p_status enrolment_status, p_started date, p_ended date,\n                                            p_from uuid, p_to uuid, p_day date) returns boolean\n  language sql immutable as $$\n  select case\n    when p_status = 'active' then (p_from is null or p_started <= p_day)\n                              and (p_to is null or p_ended is null or p_day < p_ended)\n    when p_status = 'left' then p_to is not null and p_ended is not null and p_day < p_ended\n                            and (p_from is null or p_started <= p_day)\n    else false end\n$$;\ngrant execute on function app.enrolment_on(enrolment_status, date, date, uuid, uuid, date) to authenticated, service_role;\n\n-- Teachers keep seeing a child who moved out recently, so the old class's\n-- registers before the move still show them.\ncreate or replace function app.teacher_student_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select e.student_id from enrolment e\n   where e.class_id in (select app.teacher_class_ids()) and e.deleted_at is null\n     and (e.status = 'active' or (e.status = 'left' and e.moved_to is not null and e.ended_on > current_date - 60))\n  union\n  select t.student_id from trial t\n   where t.class_id in (select app.teacher_class_ids()) and t.student_id is not null and t.deleted_at is null\n     and t.status in ('booked', 'attended')\n  union\n  select d.student_id from drop_in_booking d join class_session cs on cs.id = d.session_id\n   where cs.class_id in (select app.teacher_class_ids()) and d.status = 'booked'\n     and cs.starts_at > now() - interval '30 days'\n$$;\n\n-- Planned moves whose day has come: the old place ends and its waiting list\n-- is offered the place. Run by the scheduled tick, and before any new move.\ncreate or replace function app.complete_class_moves(p_studio uuid default null) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r record; n int := 0;\nbegin\n  for r in select e.id, e.studio_id, e.class_id, (select c.name from enrolment x join class c on c.id = x.class_id where x.id = e.moved_to) to_name\n             from enrolment e\n            where e.status = 'active' and e.deleted_at is null and e.moved_to is not null\n              and e.ended_on <= current_date and (p_studio is null or e.studio_id = p_studio)\n            for update of e\n  loop\n    update enrolment set status = 'left', note = 'Moved to ' || coalesce(r.to_name, 'another class'), updated_at = now()\n     where id = r.id;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (r.studio_id, auth.uid(), 'move', 'enrolment', r.id, 'planned move to ' || coalesce(r.to_name, 'another class') || ' took effect');\n    perform app.offer_next_place(r.class_id);\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\nrevoke all on function app.complete_class_moves(uuid) from public, authenticated, anon;\ngrant execute on function app.complete_class_moves(uuid) to service_role;\n\n-- The move itself. p_on: the first day in the new class (default today).\ndrop function if exists app.transfer_enrolment(uuid, uuid, text);\ncreate function app.transfer_enrolment(p_enrolment uuid, p_to_class uuid, p_note text default null, p_on date default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare e enrolment; to_name text; from_name text; new_id uuid; d date := coalesce(p_on, current_date); t0 date;\nbegin\n  select * into e from enrolment where id = p_enrolment and status = 'active' and deleted_at is null;\n  if e.id is null then raise exception 'NOT_FOUND: an active place' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(e.studio_id) then raise exception 'FORBIDDEN: only the office can move a student' using errcode = 'insufficient_privilege'; end if;\n  perform app.complete_class_moves(e.studio_id);\n  select * into e from enrolment where id = p_enrolment for update;\n  if e.status <> 'active' then raise exception 'NOT_FOUND: an active place' using errcode = 'no_data_found'; end if;\n  if e.moved_to is not null then\n    raise exception 'INVALID: a move is already planned for %. Cancel it first.', to_char(e.ended_on, 'FMDD Mon YYYY')\n      using errcode = 'check_violation';\n  end if;\n  if p_to_class = e.class_id then raise exception 'INVALID: that is the same class' using errcode = 'check_violation'; end if;\n  select name into to_name from class where id = p_to_class and studio_id = e.studio_id and deleted_at is null;\n  if to_name is null then raise exception 'INVALID: choose a class at this school' using errcode = 'check_violation'; end if;\n  select name into from_name from class where id = e.class_id;\n  if d > current_date + 366 then\n    raise exception 'INVALID: choose a date within the next year' using errcode = 'check_violation';\n  end if;\n  if d < current_date then\n    t0 := app.current_term_start(e.studio_id);\n    if t0 is null or d < t0 then\n      raise exception 'INVALID: a move can be dated back only to the start of this term%',\n        coalesce(' (' || to_char(t0, 'FMDD Mon') || ')', '') using errcode = 'check_violation';\n    end if;\n    if d < e.started_on then\n      raise exception 'INVALID: they only joined % on %', from_name, to_char(e.started_on, 'FMDD Mon')\n        using errcode = 'check_violation';\n    end if;\n  end if;\n\n  -- Join first: if the new class is full, nothing changes.\n  insert into enrolment (studio_id, class_id, student_id, status, started_on, created_by, note, price_minor, moved_from)\n  values (e.studio_id, p_to_class, e.student_id, 'active', d, auth.uid(),\n          coalesce(nullif(btrim(p_note), ''), 'Moved from ' || from_name), null, e.id)\n  returning id into new_id;\n\n  if d <= current_date then\n    update enrolment set status = 'left', ended_on = d, moved_to = new_id, note = 'Moved to ' || to_name, updated_at = now()\n     where id = e.id;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (e.studio_id, auth.uid(), 'move', 'enrolment', e.id,\n            'moved to ' || to_name || case when d < current_date then ' from ' || to_char(d, 'FMDD Mon') || ' (back-dated)' else '' end);\n    perform app.offer_next_place(e.class_id);\n  else\n    update enrolment set ended_on = d, moved_to = new_id, updated_at = now() where id = e.id;\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (e.studio_id, auth.uid(), 'move', 'enrolment', e.id, 'move to ' || to_name || ' planned for ' || to_char(d, 'FMDD Mon YYYY'));\n  end if;\n  return new_id;\nend $$;\nrevoke all on function app.transfer_enrolment(uuid, uuid, text, date) from public;\ngrant execute on function app.transfer_enrolment(uuid, uuid, text, date) to authenticated;\n\n-- Calling off a planned move (either place may be named).\ncreate or replace function app.cancel_class_move(p_enrolment uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare old_ enrolment;\nbegin\n  select * into old_ from enrolment\n   where (id = p_enrolment or moved_to = p_enrolment) and moved_to is not null and status = 'active' and deleted_at is null\n   limit 1 for update;\n  if old_.id is null then raise exception 'NOT_FOUND: a planned move' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(old_.studio_id) then raise exception 'FORBIDDEN: only the office can change a move' using errcode = 'insufficient_privilege'; end if;\n  if old_.ended_on <= current_date then\n    raise exception 'INVALID: that move has already happened' using errcode = 'check_violation';\n  end if;\n  update enrolment set status = 'cancelled', updated_at = now(), note = concat_ws(' · ', note, 'Planned move called off')\n   where id = old_.moved_to;\n  update enrolment set ended_on = null, moved_to = null, updated_at = now() where id = old_.id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (old_.studio_id, auth.uid(), 'move', 'enrolment', old_.id, 'planned move called off');\n  perform app.offer_next_place((select class_id from enrolment where id = old_.moved_to));\nend $$;\nrevoke all on function app.cancel_class_move(uuid) from public;\ngrant execute on function app.cancel_class_move(uuid) to authenticated;\n\n-- What a move on a given day means for the bill, before it is made: classes\n-- left in each class's term after the date, what is already invoiced for the\n-- old class, and what the next billing run would charge for the new one.\ncreate or replace function app.move_preview(p_enrolment uuid, p_to_class uuid, p_on date default null)\n  returns table (on_day date, earliest date, from_left int, from_total int, from_price_minor int,\n                 from_invoiced_minor bigint, from_unused_minor bigint, to_left int, to_total int,\n                 to_price_minor int, to_charge_minor bigint, from_pricing text, to_pricing text, note text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare e enrolment; fc class; tc class; d date := coalesce(p_on, current_date);\n        fl int; ft int; fp int; finv bigint; fun bigint; tl int; tt int; tch bigint; t0 date; msg text;\nbegin\n  select * into e from enrolment where id = p_enrolment and deleted_at is null;\n  if e.id is null or not app.is_admin(e.studio_id) then\n    raise exception 'FORBIDDEN: only the office can move a student' using errcode = 'insufficient_privilege';\n  end if;\n  select * into fc from class where id = e.class_id;\n  select * into tc from class where id = p_to_class and studio_id = e.studio_id;\n  t0 := greatest(coalesce(app.current_term_start(e.studio_id), current_date), e.started_on);\n  fp := coalesce(e.price_minor, fc.price_minor, 0);\n  select count(*) filter (where cs.starts_at::date >= d), count(*) into fl, ft\n    from class_session cs where cs.class_id = fc.id and cs.deleted_at is null and cs.status <> 'cancelled';\n  select coalesce(sum(ii.total_minor), 0) into finv\n    from invoice_item ii join invoice i on i.id = ii.invoice_id\n   where ii.student_id = e.student_id and ii.class_id = fc.id and ii.deleted_at is null\n     and i.deleted_at is null and i.status not in ('void', 'draft') and i.term_id is not distinct from fc.term_id;\n  fun := case when fc.pricing = 'term' and ft > 0 and finv > 0 then least(finv, round(fp::numeric * fl / ft)::bigint) else 0 end;\n  if tc.id is not null then\n    select count(*) filter (where cs.starts_at::date >= d), count(*) into tl, tt\n      from class_session cs where cs.class_id = tc.id and cs.deleted_at is null and cs.status <> 'cancelled';\n    tch := case when tc.pricing = 'term' and tt > 0 then round(coalesce(tc.price_minor, 0)::numeric * tl / tt)::bigint\n                when tc.pricing in ('one_off', 'monthly') then coalesce(tc.price_minor, 0) else 0 end;\n  end if;\n  msg := case when d > current_date then 'Planned for ' || to_char(d, 'FMDy FMDD Mon') || '. Until then they stay in ' || fc.name || '. '\n              when d < current_date then 'Back-dated to ' || to_char(d, 'FMDy FMDD Mon') || '. Marks already made in ' || fc.name || ' after that stay as they are. '\n              else 'From today. ' end\n      || case when fc.pricing = 'term' and ft > 0 then\n           fl || ' of ' || ft || ' ' || fc.name || ' classes are on or after the date'\n           || case when finv > 0 then '; ' || app.gbp(fun) || ' of the ' || app.gbp(finv) || ' invoiced covers them. Issue a credit note for it if the family should not pay twice. '\n                   else '. Nothing is invoiced for it yet, so the next billing run charges only the classes before the date. ' end\n         else '' end\n      || case when tc.id is null then ''\n              when tc.pricing = 'term' and tt > 0 then\n                'The next billing run charges ' || tc.name || ' pro rata: ' || tl || ' of ' || tt || ' classes, ' || app.gbp(tch) || '.'\n              when tc.pricing = 'monthly' then tc.name || ' is charged monthly from the month of the move.'\n              else '' end;\n  return query select d, t0, fl, ft, fp, finv, fun, coalesce(tl, 0), coalesce(tt, 0), tc.price_minor,\n                      coalesce(tch, 0), fc.pricing::text, tc.pricing::text, btrim(msg);\nend $$;\nrevoke all on function app.move_preview(uuid, uuid, date) from public;\ngrant execute on function app.move_preview(uuid, uuid, date) to authenticated;\n\n-- The tick finishes planned moves whose day has come (as 0051, plus moves).\ncreate or replace function app.tick() returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s record; auto int := 0; released int := 0; checks int := 0; holds int; digests int;\n        due int := 0; offers int := 0; n int; moves int := 0;\nbegin\n  holds := app.expire_held_drop_ins();\n  for s in select id from studio where deleted_at is null and app.studio_writable(id) loop\n    auto := auto + coalesce(app.run_automations(s.id), 0);\n    released := released + app.release_scheduled(s.id);\n    checks := checks + app.remind_staff_checks(s.id);\n    perform app.award_event_milestones(s.id);\n    -- Waiting-list offers past their expiry go to the next family (UR-19).\n    begin\n      n := app.expire_waitlist_offers(s.id);\n      offers := offers + coalesce(n, 0);\n    exception when others then null;   -- one school's data must not stop the rest\n    end;\n    -- Planned class moves whose day has come (UR-52).\n    begin\n      moves := moves + coalesce(app.complete_class_moves(s.id), 0);\n    exception when others then null;\n    end;\n    due := due + coalesce(app.notify_invoices_due(s.id), 0);\n  end loop;\n  digests := app.send_digests();\n  return jsonb_build_object('automations', auto, 'released', released, 'staff_checks', checks,\n                            'holds_lapsed', holds, 'digests', digests, 'invoices_due', due,\n                            'offers_expired', offers, 'moves', moves, 'at', now());\nend $$;\n\n-- ── 3. Split billing between guardians (UR-17) ─────────────────────────────\n-- No row, or mode 'family': invoices go to the family, as today.\n-- 'one': every invoice to guardian_a. 'percent': guardian_a pays percent_a,\n-- guardian_b the rest. 'per_child': each child to the guardian named in\n-- family_billing_child, anyone not named to guardian_a.\n-- Both tables carry an id, as every table with a family_id must for merging\n-- duplicate families (0044).\ncreate table family_billing (\n  id          uuid not null default gen_random_uuid() unique,\n  family_id   uuid primary key references family(id) on delete cascade,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  mode        text not null check (mode in ('family', 'one', 'percent', 'per_child')),\n  guardian_a  uuid references guardian(id) on delete set null,\n  guardian_b  uuid references guardian(id) on delete set null,\n  percent_a   smallint check (percent_a between 1 and 99),\n  updated_by  uuid references user_account(id) on delete set null,\n  updated_at  timestamptz not null default now()\n);\ncreate table family_billing_child (\n  id          uuid not null default gen_random_uuid() unique,\n  student_id  uuid primary key references student(id) on delete cascade,\n  family_id   uuid not null references family(id) on delete cascade,\n  studio_id   uuid not null references studio(id) on delete cascade,\n  guardian_id uuid not null references guardian(id) on delete cascade\n);\n-- Merging two families that both have a setting keeps the kept family's.\ncreate or replace function app.family_billing_merge_guard() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.family_id is distinct from old.family_id\n     and exists (select 1 from family_billing where family_id = new.family_id) then\n    return null;\n  end if;\n  return new;\nend $$;\ncreate trigger family_billing_merge before update of family_id on family_billing\n  for each row execute function app.family_billing_merge_guard();\n\nalter table family_billing enable row level security; alter table family_billing force row level security;\nalter table family_billing_child enable row level security; alter table family_billing_child force row level security;\ncreate policy family_billing_read on family_billing for select\n  using (studio_id in (select app.studio_ids()) and (app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\ncreate policy family_billing_child_read on family_billing_child for select\n  using (studio_id in (select app.studio_ids()) and (app.is_admin(studio_id) or family_id in (select app.guardian_family_ids())));\ngrant select on family_billing, family_billing_child to authenticated;\ngrant all on family_billing, family_billing_child to service_role;\n\n-- Who an invoice is addressed to: null is the whole family.\nalter table invoice add column billed_guardian_id uuid references guardian(id) on delete set null;\ncreate index invoice_billed_guardian on invoice (billed_guardian_id) where billed_guardian_id is not null;\n\n-- Who pays a child's fees, and what share. ord 1 takes the rounded share,\n-- ord 2 the remainder, so the shares always add up to the whole.\ncreate or replace function app.billing_payers(p_family uuid, p_student uuid)\n  returns table (guardian_id uuid, share_pct int, ord int)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with fb as (\n    select b.mode, ga.id ga, gb.id gb, b.percent_a,\n           (select gc.id from family_billing_child x join guardian gc on gc.id = x.guardian_id and gc.deleted_at is null\n             where x.student_id = p_student and gc.family_id = p_family) gchild\n      from family_billing b\n      left join guardian ga on ga.id = b.guardian_a and ga.deleted_at is null and ga.family_id = b.family_id\n      left join guardian gb on gb.id = b.guardian_b and gb.deleted_at is null and gb.family_id = b.family_id\n     where b.family_id = p_family)\n  select null::uuid, 100, 1\n   where not exists (select 1 from fb where fb.mode <> 'family')\n  union all select fb.ga, 100, 1 from fb where fb.mode = 'one'\n  union all select fb.ga, fb.percent_a, 1 from fb where fb.mode = 'percent' and fb.gb is not null\n  union all select fb.gb, 100 - fb.percent_a, 2 from fb where fb.mode = 'percent' and fb.gb is not null\n  union all select fb.ga, 100, 1 from fb where fb.mode = 'percent' and fb.gb is null\n  union all select coalesce(fb.gchild, fb.ga), 100, 1 from fb where fb.mode = 'per_child'\n$$;\nrevoke all on function app.billing_payers(uuid, uuid) from public, authenticated, anon;\n\n-- Has this payer's share of a child's class for the period been billed? A\n-- live invoice to the whole family covers every share; one to a guardian\n-- covers that guardian's share (and a family-wide bill when no split is set).\ncreate or replace function app.billing_share_covered(p_student uuid, p_class uuid, p_term uuid, p_pstart date,\n                                                     p_monthly boolean, p_payer uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (\n    select 1 from invoice_item ii join invoice i on i.id = ii.invoice_id\n     where ii.student_id = p_student and ii.class_id = p_class and ii.deleted_at is null\n       and i.deleted_at is null and i.status not in ('void', 'refunded') and i.term_id = p_term\n       and (not p_monthly or ii.period_start = p_pstart)\n       and (i.billed_guardian_id is null or p_payer is null or i.billed_guardian_id = p_payer))\n$$;\nrevoke all on function app.billing_share_covered(uuid, uuid, uuid, date, boolean, uuid) from public, authenticated, anon;\n\n-- As 0045, with two changes: a place that moves during the period is billed\n-- up to (or from) the move day; and each line is split between the family's\n-- payers, one row per payer whose share is not yet billed.\ndrop function if exists app.billing_lines(uuid, date, uuid[]);\ncreate function app.billing_lines(p_term uuid, p_month date default null, p_include uuid[] default null)\n  returns table (family_id uuid, family_name text, student_id uuid, student_name text,\n                 class_id uuid, class_name text, description text, quantity numeric,\n                 unit_minor int, discount_minor int, discount_reason text, period_start date,\n                 payer_guardian_id uuid, payer_name text, share_pct int)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; t term; m0 date; m1 date; pstart date; skip uuid[];\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  if p_month is not null then\n    m0 := greatest(date_trunc('month', p_month)::date, t.starts_on);\n    m1 := least((date_trunc('month', p_month) + interval '1 month - 1 day')::date, t.ends_on);\n    if m0 > m1 then raise exception 'INVALID: that month is outside the term' using errcode = 'check_violation'; end if;\n    pstart := date_trunc('month', p_month)::date;\n  else\n    m0 := t.starts_on; m1 := t.ends_on; pstart := t.starts_on;\n  end if;\n  skip := array(select g.family_id from app.billing_period_invoices(p_term, p_month) g\n                 where not (g.family_id = any(coalesce(p_include, '{}'::uuid[]))));\n  return query\n  with places as (\n    select e.*, greatest(e.started_on, m0) from_day,\n           case when e.moved_to is not null and e.ended_on is not null then least(m1, e.ended_on - 1) else m1 end to_day\n      from enrolment e\n     where e.deleted_at is null and e.started_on <= m1\n       and (e.status = 'active' or (e.status = 'left' and e.moved_to is not null and e.ended_on > m0))\n  ),\n  base as (\n    select f.id fam, f.name fname, s.id stu, s.first_name || ' ' || s.last_name sname,\n           c.id cls, c.name cname, c.pricing,\n           coalesce(e.price_minor, c.price_minor) price, e.from_day, e.to_day,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null and cs.status <> 'cancelled'\n              and cs.starts_at::date between m0 and m1) total_sessions,\n           (select count(*) from class_session cs where cs.class_id = c.id and cs.deleted_at is null and cs.status <> 'cancelled'\n              and cs.starts_at::date between e.from_day and e.to_day) left_sessions\n      from places e\n      join class c on c.id = e.class_id and c.deleted_at is null and c.term_id = t.id\n      join student s on s.id = e.student_id and s.deleted_at is null\n      join family f on f.id = s.family_id and f.deleted_at is null and not f.is_prospect\n     where e.from_day <= e.to_day\n       and coalesce(e.price_minor, c.price_minor) > 0\n       and (case when p_month is null then c.pricing in ('term', 'one_off') else c.pricing = 'monthly' end)\n       -- Already billed for this period by an invoice that does not name the class.\n       and not (f.id = any(skip))\n       -- Every payer's share already billed (a live invoice line for this child and class).\n       and exists (select 1 from app.billing_payers(f.id, s.id) py\n                    where not app.billing_share_covered(s.id, c.id, t.id, pstart, p_month is not null, py.guardian_id))\n  ),\n  priced as (\n    select b.*, 1::numeric qty,\n      case when b.pricing in ('term', 'monthly') and (b.from_day > m0 or b.to_day < m1) and b.total_sessions > 0\n           then round(b.price::numeric * b.left_sessions / b.total_sessions)::int else b.price end unit,\n      case when b.pricing = 'one_off' then b.cname || ' — course fee'\n           when (b.from_day > m0 or b.to_day < m1) and b.total_sessions > 0\n             then format('%s — %s, %s of %s classes %s', b.cname,\n                         case when p_month is null then t.name else to_char(pstart, 'FMMonth YYYY') end,\n                         b.left_sessions, b.total_sessions,\n                         concat_ws(' ', case when b.from_day > m0 then 'from ' || to_char(b.from_day, 'FMDD Mon') end,\n                                        case when b.to_day < m1 then 'until ' || to_char(b.to_day, 'FMDD Mon') end))\n           else b.cname || ' — ' || case when p_month is null then t.name else to_char(pstart, 'FMMonth YYYY') end end descr\n      from base b\n  ),\n  ranked as (\n    select p.*,\n      dense_rank() over (partition by p.fam order by child_total desc, p.stu) child_rank,\n      row_number() over (partition by p.stu order by p.unit * p.qty desc, p.cls) class_rank\n      from (select p.*, sum(p.unit * p.qty) over (partition by p.stu) child_total from priced p) p\n  ),\n  rules as (\n    select (select percent from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'sibling' and enabled and deleted_at is null) sib_n,\n           (select percent from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_pct,\n           (select from_nth from discount_rule where studio_id = sid and kind = 'multi_class' and enabled and deleted_at is null) mc_n\n  ),\n  disc as (\n    select r.*,\n      case when rules.sib_pct is not null and r.child_rank >= rules.sib_n then rules.sib_pct else 0 end sib,\n      case when rules.mc_pct is not null and r.class_rank >= rules.mc_n then rules.mc_pct else 0 end mc,\n      (select fd.pct from app.family_discounts_on(r.fam, m0, m1) fd) fam_pct\n      from ranked r, rules\n  ),\n  whole as (\n    select d.*,\n           round(d.unit * d.qty * (1 - (1 - greatest(d.sib, d.mc) / 100.0) * (1 - d.fam_pct / 100.0)))::int disc_minor,\n           nullif(concat_ws(' + ',\n             case when greatest(d.sib, d.mc) = 0 then null\n                  when d.sib >= d.mc then d.sib || '% sibling discount' else d.mc || '% multi-class discount' end,\n             case when d.fam_pct > 0 then d.fam_pct || '% discount' end), '') disc_reason\n      from disc d\n  )\n  select w.fam, w.fname, w.stu, w.sname, w.cls, w.cname,\n         case when py.share_pct < 100 then w.descr || ' (' || py.share_pct || '% share)' else w.descr end,\n         w.qty,\n         case when py.ord = 1 then round(w.unit * py.share_pct / 100.0)::int\n              else w.unit - round(w.unit * (100 - py.share_pct) / 100.0)::int end,\n         case when py.ord = 1 then round(w.disc_minor * py.share_pct / 100.0)::int\n              else w.disc_minor - round(w.disc_minor * (100 - py.share_pct) / 100.0)::int end,\n         w.disc_reason, pstart,\n         py.guardian_id, g.full_name, py.share_pct\n    from whole w\n    cross join lateral app.billing_payers(w.fam, w.stu) py\n    left join guardian g on g.id = py.guardian_id\n   where not app.billing_share_covered(w.stu, w.cls, t.id, pstart, p_month is not null, py.guardian_id)\n   order by w.fname, g.full_name nulls first, w.sname, w.cname;\nend $$;\n\n-- One invoice per family and paying guardian. A fixed family discount is\n-- shared between the payers in proportion to what each is billed.\ndrop function if exists app.create_billing_run(uuid, date, date, uuid[], text);\ncreate function app.create_billing_run(p_term uuid, p_due date default null, p_month date default null,\n                                       p_include uuid[] default null, p_reason text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; run uuid; fam record; inv uuid; n int := 0; tot bigint := 0; fixed int; share int;\n        pm date := date_trunc('month', p_month)::date; t term; inc uuid[]; o record;\nbegin\n  select * into t from term where id = p_term and deleted_at is null;\n  sid := t.studio_id;\n  perform app.require_admin(sid);\n  if not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if exists (select 1 from billing_run where term_id = p_term and status = 'draft' and period_month is not distinct from pm) then\n    raise exception 'INVALID: there is already a draft run for this period — issue or discard it first' using errcode = 'check_violation';\n  end if;\n  -- Only families that really were skipped count as overrides.\n  inc := array(select g.family_id from app.billing_period_invoices(p_term, pm) g\n                where g.family_id = any(coalesce(p_include, '{}'::uuid[])));\n  if cardinality(inc) > 0 and length(coalesce(btrim(p_reason), '')) < 3 then\n    raise exception 'INVALID: say why these families should be billed again for this period' using errcode = 'check_violation';\n  end if;\n\n  insert into billing_run (studio_id, term_id, due_on, created_by, period_month)\n  values (sid, p_term, coalesce(p_due, current_date + 14), auth.uid(), pm) returning id into run;\n\n  for fam in\n    select x.*, sum(x.sub) over (partition by x.family_id) fam_sub,\n           sum(x.sub) over (partition by x.family_id order by x.payer_name nulls first, x.payer\n                            rows unbounded preceding) cum_sub\n      from (select l.family_id, l.payer_guardian_id payer, min(l.payer_name) payer_name,\n                   jsonb_agg(jsonb_build_object(\n                     'kind', 'tuition', 'description', l.description, 'quantity', l.quantity,\n                     'unit_minor', l.unit_minor, 'discount_minor', l.discount_minor,\n                     'student_id', l.student_id, 'class_id', l.class_id)) items,\n                   min(l.period_start) ps,\n                   sum(round(l.quantity * l.unit_minor) - l.discount_minor)::bigint sub\n              from app.billing_lines(p_term, pm, inc) l group by l.family_id, l.payer_guardian_id) x\n     order by x.family_id, x.payer_name nulls first\n  loop\n    select fd.fixed into fixed from app.family_discounts_on(fam.family_id, coalesce(pm, t.starts_on),\n                                                         coalesce((pm + interval '1 month - 1 day')::date, t.ends_on)) fd;\n    -- Telescoping shares, so the payers' parts add up to the whole discount.\n    share := case when coalesce(fixed, 0) = 0 or fam.fam_sub <= 0 then 0\n                  else (round(fixed::numeric * fam.cum_sub / fam.fam_sub) - round(fixed::numeric * (fam.cum_sub - fam.sub) / fam.fam_sub))::int end;\n    inv := app.create_invoice(fam.family_id, fam.items, coalesce(p_due, current_date + 14),\n                              case when fam.payer is not null then 'Billed to ' || fam.payer_name end,\n                              least(share, greatest(fam.sub, 0))::int, false, p_term);\n    update invoice set billing_run_id = run, billed_guardian_id = fam.payer where id = inv;\n    update invoice_item set period_start = fam.ps where invoice_id = inv;\n    n := n + 1;\n    tot := tot + (select total_minor from invoice where id = inv);\n  end loop;\n  if n = 0 then\n    delete from billing_run where id = run;\n    raise exception 'INVALID: everyone has already been invoiced for this period' using errcode = 'check_violation';\n  end if;\n  update billing_run set invoice_count = n, total_minor = tot where id = run;\n  for o in select g.family_id, g.numbers from app.billing_period_invoices(p_term, pm) g where g.family_id = any(inc) loop\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (sid, auth.uid(), 'override', 'family', o.family_id,\n            'Billed again for ' || coalesce(to_char(pm, 'FMMonth YYYY'), t.name) || ' despite ' || o.numbers || ': ' || btrim(p_reason));\n  end loop;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'create', 'billing_run', run, n || ' draft invoices' || coalesce(' for ' || to_char(pm, 'FMMonth YYYY'), ''));\n  return run;\nend $$;\n\nrevoke all on function app.billing_lines(uuid, date, uuid[]), app.create_billing_run(uuid, date, date, uuid[], text) from public;\ngrant execute on function app.billing_lines(uuid, date, uuid[]), app.create_billing_run(uuid, date, date, uuid[], text) to authenticated;\n\n-- The office sets how a family's invoices are shared. p_children maps\n-- student id → guardian id for 'per_child'.\ncreate or replace function app.set_family_billing(p_family uuid, p_mode text, p_guardian_a uuid default null,\n                                                  p_guardian_b uuid default null, p_percent_a int default null,\n                                                  p_children jsonb default null) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare f family; k text; v text; summary text;\nbegin\n  select * into f from family where id = p_family and deleted_at is null;\n  if f.id is null then raise exception 'NOT_FOUND: family' using errcode = 'no_data_found'; end if;\n  perform app.require_admin(f.studio_id);\n  if p_mode not in ('family', 'one', 'percent', 'per_child') then\n    raise exception 'INVALID: unknown way of sharing invoices' using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from invoice i join billing_run r on r.id = i.billing_run_id\n              where i.family_id = f.id and r.status = 'draft' and i.deleted_at is null) then\n    raise exception 'INVALID: a draft billing run includes this family — issue or discard it first' using errcode = 'check_violation';\n  end if;\n  if p_mode <> 'family' then\n    if p_guardian_a is null or not exists (select 1 from guardian where id = p_guardian_a and family_id = f.id and deleted_at is null) then\n      raise exception 'INVALID: choose a guardian in this family' using errcode = 'check_violation';\n    end if;\n  end if;\n  if p_mode = 'percent' then\n    if p_guardian_b is null or p_guardian_b = p_guardian_a\n       or not exists (select 1 from guardian where id = p_guardian_b and family_id = f.id and deleted_at is null) then\n      raise exception 'INVALID: choose two different guardians in this family' using errcode = 'check_violation';\n    end if;\n    if p_percent_a is null or p_percent_a not between 1 and 99 then\n      raise exception 'INVALID: the first guardian’s share must be between 1%% and 99%%' using errcode = 'check_violation';\n    end if;\n  end if;\n\n  delete from family_billing_child where family_id = f.id;\n  if p_mode = 'family' then\n    delete from family_billing where family_id = f.id;\n    summary := 'invoices to the whole family';\n  else\n    insert into family_billing (family_id, studio_id, mode, guardian_a, guardian_b, percent_a, updated_by, updated_at)\n    values (f.id, f.studio_id, p_mode, p_guardian_a,\n            case when p_mode = 'percent' then p_guardian_b end,\n            case when p_mode = 'percent' then p_percent_a end, auth.uid(), now())\n    on conflict (family_id) do update\n      set mode = excluded.mode, guardian_a = excluded.guardian_a, guardian_b = excluded.guardian_b,\n          percent_a = excluded.percent_a, updated_by = excluded.updated_by, updated_at = now();\n    if p_mode = 'per_child' and p_children is not null then\n      for k, v in select * from jsonb_each_text(p_children) loop\n        continue when v is null or v = '';\n        if not exists (select 1 from student where id = k::uuid and family_id = f.id and deleted_at is null) then\n          raise exception 'INVALID: that child is not in this family' using errcode = 'check_violation';\n        end if;\n        if not exists (select 1 from guardian where id = v::uuid and family_id = f.id and deleted_at is null) then\n          raise exception 'INVALID: choose a guardian in this family' using errcode = 'check_violation';\n        end if;\n        insert into family_billing_child (student_id, family_id, studio_id, guardian_id) values (k::uuid, f.id, f.studio_id, v::uuid);\n      end loop;\n    end if;\n    summary := case p_mode\n      when 'one' then 'invoices to ' || (select full_name from guardian where id = p_guardian_a)\n      when 'percent' then 'invoices split ' || p_percent_a || '% ' || (select full_name from guardian where id = p_guardian_a)\n                          || ', ' || (100 - p_percent_a) || '% ' || (select full_name from guardian where id = p_guardian_b)\n      else 'invoices per child' end;\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (f.studio_id, auth.uid(), 'update', 'family_billing', f.id, 'Billing: ' || summary);\nend $$;\nrevoke all on function app.set_family_billing(uuid, text, uuid, uuid, int, jsonb) from public;\ngrant execute on function app.set_family_billing(uuid, text, uuid, uuid, int, jsonb) to authenticated;\n\n-- Invoices addressed to another guardian are not this guardian's to see.\n-- Restrictive, so it holds on every read path whatever else allows the row.\ncreate or replace function app.payer_hidden_invoice_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select i.id from invoice i\n   where i.billed_guardian_id is not null\n     and i.family_id in (select app.guardian_family_ids())\n     and not app.is_admin(i.studio_id)\n     and not exists (select 1 from guardian g where g.id = i.billed_guardian_id and g.user_id = auth.uid())\n$$;\ngrant execute on function app.payer_hidden_invoice_ids() to authenticated;\n\ncreate policy invoice_payer_only on invoice as restrictive for select\n  using (billed_guardian_id is null or id not in (select app.payer_hidden_invoice_ids()));\ncreate policy invoice_item_payer_only on invoice_item as restrictive for select\n  using (invoice_id not in (select app.payer_hidden_invoice_ids()));\ncreate policy payment_payer_only on payment as restrictive for select\n  using (invoice_id is null or invoice_id not in (select app.payer_hidden_invoice_ids()));\ncreate policy credit_note_payer_only on credit_note as restrictive for select\n  using (invoice_id not in (select app.payer_hidden_invoice_ids()));\n\n-- Notices about an invoice go to whoever it is addressed to.\ncreate or replace function app.notify_invoice_payer(p_invoice uuid, p_kind text, p_title text, p_body text, p_href text)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare i invoice; g record;\nbegin\n  select * into i from invoice where id = p_invoice;\n  if i.id is null then return; end if;\n  if i.billed_guardian_id is null then\n    perform app.notify_family(i.family_id, p_kind, p_title, p_body, p_href);\n    return;\n  end if;\n  for g in select gd.studio_id, gd.user_id from guardian gd left join guardian_access a on a.guardian_id = gd.id\n            where gd.id = i.billed_guardian_id and gd.user_id is not null and gd.deleted_at is null\n              and a.may_contact is not false loop\n    perform app.notify_user(g.studio_id, g.user_id, p_kind, p_title, p_body, p_href);\n  end loop;\nend $$;\nrevoke all on function app.notify_invoice_payer(uuid, text, text, text, text) from public, authenticated, anon;\n\ncreate or replace function app.on_invoice_issued_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare i invoice; what text;\nbegin\n  select * into i from invoice where id = new.id;\n  if i.id is null or i.deleted_at is not null or i.status not in ('issued', 'part_paid', 'paid') then return null; end if;\n  if coalesce(i.issued_on, current_date) < current_date - 1 then return null; end if;\n  insert into invoice_notice (invoice_id, kind) values (i.id, 'issued') on conflict do nothing;\n  if not found then return null; end if;\n  select string_agg(description, ', ' order by created_at) into what from invoice_item\n   where invoice_id = i.id and deleted_at is null;\n  perform app.notify_invoice_payer(i.id, 'invoice_issued',\n    'New invoice ' || i.number || ' ' || app.gbp(i.total_minor)\n      || case when i.status = 'paid' then ', paid from your credit' else ' due ' || to_char(i.due_on, 'FMDD Mon') end,\n    left(what, 140), '/family/payments');\n  return null;\nend $$;\n\ncreate or replace function app.on_payment_received_notify() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare num text;\nbegin\n  if new.succeeded_at is null or new.method not in ('card', 'direct_debit', 'bank_transfer', 'cash') then return null; end if;\n  if tg_op = 'UPDATE' and old.succeeded_at is not null then return null; end if;\n  select number into num from invoice where id = new.invoice_id;\n  if num is not null then\n    perform app.notify_invoice_payer(new.invoice_id, 'payment_received', 'Payment received: ' || app.gbp(new.amount_minor),\n      'Paid towards ' || num || '. Thank you.', '/family/payments');\n  else\n    perform app.notify_family(new.family_id, 'payment_received', 'Payment received: ' || app.gbp(new.amount_minor),\n      'Held on your account for your next invoice. Thank you.', '/family/payments');\n  end if;\n  return null;\nend $$;\n\ncreate or replace function app.notify_invoices_due(p_studio uuid default null) returns int\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare r record; g record; n int := 0;\nbegin\n  for r in select i.* from invoice i\n            where i.deleted_at is null and i.status in ('issued', 'part_paid') and i.total_minor > i.paid_minor\n              and i.due_on between current_date and current_date + 3\n              and (p_studio is null or i.studio_id = p_studio)\n              and (auth.uid() is null or app.is_admin(i.studio_id) or i.family_id in (select app.guardian_family_ids()))\n              and i.id not in (select app.payer_hidden_invoice_ids())\n              and not exists (select 1 from invoice_notice x where x.invoice_id = i.id and x.kind = 'due_soon')\n  loop\n    insert into invoice_notice (invoice_id, kind) values (r.id, 'due_soon');\n    for g in select gu.studio_id, gu.user_id from guardian gu\n              where gu.family_id = r.family_id and gu.user_id is not null and gu.deleted_at is null\n                and (r.billed_guardian_id is null or gu.id = r.billed_guardian_id) loop\n      continue when not app.wants(g.user_id, 'invoice_issued', 'in_app');\n      insert into notification (studio_id, user_id, kind, title, body, href)\n      values (g.studio_id, g.user_id, 'invoice_issued',\n              r.number || ' is due ' || case when r.due_on = current_date then 'today' when r.due_on = current_date + 1 then 'tomorrow'\n                                             else 'on ' || to_char(r.due_on, 'FMDay DD Mon') end,\n              app.gbp(r.total_minor - r.paid_minor) || ' to pay. Bank details are in Payments.', '/family/payments');\n    end loop;\n    n := n + 1;\n  end loop;\n  return n;\nend $$;\n\n-- ── 2. Credit for reported absences (UR-56) ────────────────────────────────\n-- off: nothing (default) · session: the class's per-session value ·\n-- fixed: absence_credit_fixed_minor.\nalter table studio add column absence_credit text not null default 'off'\n  check (absence_credit in ('off', 'session', 'fixed'));\nalter table studio add column absence_credit_fixed_minor integer not null default 0\n  check (absence_credit_fixed_minor between 0 and 100000);\n\n-- Make-ups for absences or credit, not both: whichever was just chosen wins.\ncreate or replace function app.absence_remedy_one() returns trigger\n  language plpgsql set search_path = public, app, pg_temp as $$\nbegin\n  if new.absence_credit <> 'off' and new.makeup_policy = 'cancelled_and_absence' then\n    if new.absence_credit is distinct from old.absence_credit then\n      new.makeup_policy := 'cancelled';\n    else\n      new.absence_credit := 'off';\n    end if;\n  end if;\n  return new;\nend $$;\ncreate trigger studio_absence_remedy before update of absence_credit, makeup_policy on studio\n  for each row execute function app.absence_remedy_one();\n\ncreate table absence_credit (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  report_id    uuid not null references absence_report(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  session_id   uuid not null references class_session(id) on delete cascade,\n  family_id    uuid not null references family(id) on delete cascade,\n  payment_id   uuid references payment(id) on delete set null,\n  amount_minor integer not null check (amount_minor > 0),\n  status       text not null default 'active' check (status in ('active', 'reversed')),\n  created_at   timestamptz not null default now(),\n  reversed_at  timestamptz\n);\ncreate unique index absence_credit_once on absence_credit (session_id, student_id) where status = 'active';\ncreate index absence_credit_family on absence_credit (family_id, created_at desc);\nalter table absence_credit enable row level security; alter table absence_credit force row level security;\ncreate policy absence_credit_read on absence_credit for select using (\n  studio_id in (select app.studio_ids()) and (\n    app.is_admin(studio_id) or student_id in (select app.guardian_student_ids()) or student_id = app.student_self_id()));\ngrant select on absence_credit to authenticated;\ngrant all on absence_credit to service_role;\n\n-- What a reported absence is worth: the child's place in that class on that\n-- day, priced by the term or month. Trials, drop-ins and make-ups get\n-- nothing (a drop-in is cancelled instead). Null when nothing is due.\ncreate or replace function app.absence_credit_value(p_student uuid, p_session uuid) returns int\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare st studio; cs class_session; c class; price int; per int;\nbegin\n  select * into cs from class_session where id = p_session and deleted_at is null;\n  select * into st from studio where id = cs.studio_id;\n  if cs.id is null or st.absence_credit = 'off' or st.makeup_policy = 'cancelled_and_absence' or cs.status <> 'scheduled' then\n    return null;\n  end if;\n  select * into c from class where id = cs.class_id;\n  if c.pricing not in ('term', 'monthly') then return null; end if;\n  select coalesce(e.price_minor, c.price_minor) into price from enrolment e\n   where e.class_id = c.id and e.student_id = p_student and e.deleted_at is null\n     and app.enrolment_on(e.status, e.started_on, e.ended_on, e.moved_from, e.moved_to, cs.starts_at::date)\n   limit 1;\n  if coalesce(price, 0) <= 0 then return null; end if;\n  if st.absence_credit = 'fixed' then\n    per := least(st.absence_credit_fixed_minor, price);\n  elsif c.pricing = 'term' then\n    per := round(price::numeric / greatest(1, (select count(*) from class_session x where x.class_id = c.id\n                                                   and x.deleted_at is null and x.status <> 'cancelled')))::int;\n  else\n    per := round(price::numeric * 12 / 52)::int;\n  end if;\n  return nullif(per, 0);\nend $$;\ngrant execute on function app.absence_credit_value(uuid, uuid) to authenticated;\n\n-- Take back credit that has already been spent on invoices: the newest\n-- allocations are undone first, so those invoices are owed again.\ncreate or replace function app.unwind_family_credit(p_family uuid) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare need bigint; p record; take bigint;\nbegin\n  need := -app.family_available_credit(p_family);\n  if need <= 0 then return; end if;\n  for p in select * from payment where family_id = p_family and method = 'account' and invoice_id is not null\n                                  and deleted_at is null and succeeded_at is not null\n            order by created_at desc, id desc loop\n    exit when need <= 0;\n    take := least(need, p.amount_minor - p.refunded_minor);\n    continue when take <= 0;\n    if take >= p.amount_minor then\n      update payment set deleted_at = now(), note = concat_ws(' · ', note, 'Credit taken back') where id = p.id;\n    else\n      update payment set amount_minor = amount_minor - take, note = concat_ws(' · ', note, 'Credit taken back: ' || app.gbp(take)) where id = p.id;\n    end if;\n    need := need - take;\n  end loop;\nend $$;\nrevoke all on function app.unwind_family_credit(uuid) from public, authenticated, anon;\n\ncreate or replace function app.on_absence_report_credit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; amt int; pay uuid; lbl text; ac absence_credit;\nbegin\n  if tg_op = 'INSERT' and new.status = 'active' then\n    if exists (select 1 from absence_credit where session_id = new.session_id and student_id = new.student_id and status = 'active')\n       or exists (select 1 from session_credit where session_id = new.session_id and student_id = new.student_id) then\n      return null;\n    end if;\n    amt := app.absence_credit_value(new.student_id, new.session_id);\n    if amt is null then return null; end if;\n    select * into s from student where id = new.student_id;\n    lbl := app.session_label(new.session_id);\n    insert into payment (studio_id, family_id, amount_minor, method, provider, succeeded_at, note, recorded_by)\n    values (new.studio_id, s.family_id, amt, 'credit', 'ledger', now(),\n            'Absence credit: ' || s.first_name || ', ' || lbl, auth.uid())\n    returning id into pay;\n    insert into absence_credit (studio_id, report_id, student_id, session_id, family_id, payment_id, amount_minor)\n    values (new.studio_id, new.id, s.id, new.session_id, s.family_id, pay, amt);\n    perform app.allocate_account_credit_internal(s.family_id);\n    perform app.recalc_family_balance(s.family_id);\n    perform app.notify_family(s.family_id, 'payment_received', app.gbp(amt) || ' credit added',\n      s.first_name || ' is reported absent from ' || lbl || '. The credit comes off your next invoice.', '/family/payments');\n  elsif tg_op = 'UPDATE' and old.status = 'active' and new.status = 'withdrawn' then\n    select * into ac from absence_credit where report_id = new.id and status = 'active';\n    if ac.id is null then return null; end if;\n    update absence_credit set status = 'reversed', reversed_at = now() where id = ac.id;\n    update payment set deleted_at = now(), note = concat_ws(' · ', note, 'Taken back: absence withdrawn') where id = ac.payment_id;\n    perform app.unwind_family_credit(ac.family_id);\n    perform app.recalc_family_balance(ac.family_id);\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (ac.studio_id, auth.uid(), 'credit', 'family', ac.family_id,\n            app.gbp(ac.amount_minor) || ' absence credit taken back: report withdrawn');\n  end if;\n  return null;\nend $$;\ncreate trigger absence_report_credit after insert or update of status on absence_report\n  for each row execute function app.on_absence_report_credit();\n\n-- A cancellation does not credit a child already credited for reporting the\n-- same session absent (as 0033 otherwise).\ncreate or replace function app.on_session_cancelled_credit() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare c class; per int; e record; pay uuid;\nbegin\n  if new.status <> 'cancelled' or old.status = 'cancelled' then return null; end if;\n  if not (select credit_cancelled_classes from studio where id = new.studio_id) then return null; end if;\n  select * into c from class where id = new.class_id;\n  if c.pricing not in ('term', 'monthly') then return null; end if;\n  per := case c.pricing\n    when 'term' then round(c.price_minor::numeric / greatest(1, (select count(*) from class_session x where x.class_id = c.id and x.deleted_at is null)))::int\n    else round(c.price_minor::numeric * 12 / 52)::int end;\n  if per <= 0 then return null; end if;\n  for e in select s.id, s.family_id, s.first_name, coalesce(en.price_minor, c.price_minor) price from enrolment en join student s on s.id = en.student_id\n            where en.class_id = c.id and en.status = 'active' and en.deleted_at is null loop\n    continue when exists (select 1 from session_credit where session_id = new.id and student_id = e.id);\n    continue when exists (select 1 from absence_credit where session_id = new.id and student_id = e.id and status = 'active');\n    insert into payment (studio_id, family_id, amount_minor, method, succeeded_at, note, recorded_by)\n    values (new.studio_id, e.family_id, per, 'credit', now(),\n            'Credit: ' || c.name || ' cancelled ' || to_char(new.starts_at, 'FMDD Mon') || ' (' || e.first_name || ')', auth.uid())\n    returning id into pay;\n    insert into session_credit (session_id, student_id, payment_id, amount_minor) values (new.id, e.id, pay, per);\n    perform app.allocate_account_credit(e.family_id);\n    perform app.recalc_family_balance(e.family_id);\n  end loop;\n  return null;\nend $$;\n\n-- As 0048, with the place's dates (UR-52) and any credit given (UR-56).\ndrop function if exists app.absence_options(uuid, int);\ncreate function app.absence_options(p_student uuid, p_days int default 42)\n  returns table (session_id uuid, class_name text, starts_at timestamptz, ends_at timestamptz,\n                 report_id uuid, note text, withdrawable boolean, credit_minor int)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\nbegin\n  if app.may_report_absence(p_student) is null then\n    raise exception 'FORBIDDEN: only a child''s own family can report an absence' using errcode = 'insufficient_privilege';\n  end if;\n  return query\n  with mine as (\n    select cs.id from class_session cs\n      join enrolment e on e.class_id = cs.class_id and e.student_id = p_student and e.deleted_at is null\n                      and app.enrolment_on(e.status, e.started_on, e.ended_on, e.moved_from, e.moved_to, cs.starts_at::date)\n    union select t.session_id from trial t where t.student_id = p_student and t.status = 'booked' and t.deleted_at is null and t.session_id is not null\n    union select d.session_id from drop_in_booking d where d.student_id = p_student and d.status = 'booked'\n  )\n  select cs.id, c.name, cs.starts_at, cs.ends_at, r.id, r.note, (r.id is not null and cs.starts_at > now()),\n         (select ac.amount_minor from absence_credit ac where ac.session_id = cs.id and ac.student_id = p_student and ac.status = 'active')\n    from mine join class_session cs on cs.id = mine.id\n    join class c on c.id = cs.class_id\n    left join absence_report r on r.session_id = cs.id and r.student_id = p_student and r.status = 'active'\n   where cs.deleted_at is null and cs.status = 'scheduled'\n     and cs.starts_at > now() and cs.starts_at < now() + make_interval(days => greatest(1, least(p_days, 180)))\n   order by cs.starts_at;\nend $$;\nrevoke all on function app.absence_options(uuid, int) from public;\ngrant execute on function app.absence_options(uuid, int) to authenticated;\n"},{name:"0053_accounts_fixes.sql",sql:"-- ============================================================================\n-- 0053 · Accounts: finishing round-1 items (UR-21, UR-08, UR-55, UR-17)\n-- ----------------------------------------------------------------------------\n--   UR-55  \"no own login under 13\" is a database rule, not a default: the\n--          school's minimum age is held to 13–18, and no invitation, account\n--          link or approval can give an under-13 their own login.\n--   UR-17  a guardian the office has restricted from medical details sees\n--          none, on every path: the family screens, the safety brief view,\n--          the privacy download (which reads the same tables), and medical\n--          update requests about the child.\n--   UR-21  an existing parent can \"Book for myself\": their own adult\n--          participant record is made (or reused) without touching their\n--          children. A restriction on a family never hides an adult's own\n--          record from that adult.\n--   UR-08  schools rename consent kinds and edit their plain explanations\n--          (labels only; the kinds stay photography / video / social media),\n--          and a student of 13 or over sees their own consents, read-only.\n-- ============================================================================\n\n-- ── UR-55 · No own login under 13, whatever the setting ────────────────────\ndo $$ declare c text; begin\n  for c in select conname from pg_constraint\n            where conrelid = 'studio'::regclass and contype = 'c'\n              and pg_get_constraintdef(oid) like '%student_login_min_age%' loop\n    execute format('alter table studio drop constraint %I', c);\n  end loop;\nend $$;\nupdate studio set student_login_min_age = 13 where student_login_min_age < 13;\nalter table studio alter column student_login_min_age set default 13;\nalter table studio add constraint studio_student_login_min_age_range\n  check (student_login_min_age between 13 and 18);\n\n-- The guard on the student row. As before (0010) a login needs an account,\n-- an approving guardian and the school's minimum age; now the age floor is 13\n-- regardless, and an under-13 cannot even be linked to an account.\ncreate or replace function app.check_student_login() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare min_age smallint; age_years integer;\nbegin\n  age_years := extract(year from age(current_date, new.date_of_birth));\n  if new.user_id is not null and not coalesce(new.is_adult, false) and age_years < 13\n     and (tg_op = 'INSERT' or old.user_id is distinct from new.user_id or new.login_enabled) then\n    raise exception 'STUDENT_LOGIN_TOO_YOUNG: % is % — students have their own login from 13; until then a parent or carer manages everything',\n      new.first_name, age_years using errcode = 'check_violation';\n  end if;\n  if not new.login_enabled then\n    return new;\n  end if;\n  if new.user_id is null then\n    raise exception 'STUDENT_LOGIN_NO_ACCOUNT: enable a login only once an account exists'\n      using errcode = 'check_violation';\n  end if;\n  if new.login_approved_by is null then\n    raise exception 'STUDENT_LOGIN_UNAPPROVED: a guardian must approve this login'\n      using errcode = 'check_violation';\n  end if;\n  select greatest(coalesce(student_login_min_age, 13), 13) into min_age from studio where id = new.studio_id;\n  if age_years < coalesce(min_age, 13) and not coalesce(new.is_adult, false) then\n    raise exception 'STUDENT_LOGIN_TOO_YOUNG: % is % and the studio requires %',\n      new.first_name, age_years, min_age using errcode = 'check_violation';\n  end if;\n  if new.login_approved_at is null then new.login_approved_at := now(); end if;\n  return new;\nend $$;\n\n-- No invitation to a login for an under-13, from the office or a parent.\ncreate or replace function app.check_student_invitation() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare s student; min_age int;\nbegin\n  if new.role <> 'student' or new.student_id is null then return new; end if;\n  select * into s from student where id = new.student_id;\n  if s.id is null or s.is_adult then return new; end if;\n  select greatest(coalesce(student_login_min_age, 13), 13) into min_age from studio where id = s.studio_id;\n  if extract(year from age(current_date, s.date_of_birth)) < min_age then\n    raise exception 'INVALID: % is under %, so has no login of their own — a parent or carer manages things for them',\n      s.first_name, min_age using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\ndrop trigger if exists studio_invitation_student_age on studio_invitation;\ncreate trigger studio_invitation_student_age before insert on studio_invitation\n  for each row execute function app.check_student_invitation();\n\n-- ── UR-17 / UR-21 · Restrictions never hide an adult's own record ──────────\ncreate or replace function app.denied_student_ids(p_what text) returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select s.id from student s\n   where s.family_id in (select app.denied_family_ids(p_what))\n     and not exists (select 1 from guardian g where g.id = s.self_guardian_id and g.user_id = auth.uid())\n$$;\n\n-- ── UR-17 · Medical restriction on every path ──────────────────────────────\n-- The medical record itself: reading and writing (a restricted guardian\n-- cannot overwrite what they may not see). Replaces the read-only policy\n-- from 0046 with one covering every command.\ndrop policy if exists medical_guardian_access on medical_record;\ncreate policy medical_guardian_access on medical_record as restrictive for all\n  using (student_id not in (select app.denied_student_ids('medical')))\n  with check (student_id not in (select app.denied_student_ids('medical')));\n\n-- Medical update requests about the child, other than the guardian's own.\ndrop policy if exists request_guardian_medical on studio_request;\ncreate policy request_guardian_medical on studio_request as restrictive for select\n  using (kind <> 'medical_update' or student_id is null or raised_by = auth.uid()\n         or student_id not in (select app.denied_student_ids('medical')));\n\n-- The safety brief view runs as its owner, so row level security on\n-- medical_record does not reach it: the guardian path checks the restriction\n-- itself. Columns unchanged from 0047.\ncreate or replace view student_safety_brief\n  with (security_invoker = false) as\nselect s.id as student_id,\n       s.studio_id,\n       s.first_name,\n       s.last_name,\n       m.allergies,\n       m.action_plan,\n       m.requires_alert,\n       (select ec.full_name from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_name,\n       (select ec.phone from emergency_contact ec\n         where ec.student_id = s.id and ec.deleted_at is null\n         order by ec.priority limit 1) as emergency_contact_phone,\n       m.conditions,\n       m.medications,\n       coalesce(m.requires_alert, false)\n         or coalesce(nullif(btrim(m.allergies), ''), nullif(btrim(m.conditions), ''),\n                     nullif(btrim(m.medications), ''), nullif(btrim(m.action_plan), '')) is not null\n         as has_medical_need,\n       coalesce((select jsonb_agg(jsonb_build_object(\n                   'name', ec.full_name, 'relationship', ec.relationship, 'phone', ec.phone)\n                   order by ec.priority, ec.created_at)\n                  from emergency_contact ec where ec.student_id = s.id and ec.deleted_at is null),\n                '[]'::jsonb) as emergency_contacts,\n       app.consent_now(s.id, 'photography') as photo_consent\n  from student s\n  left join medical_record m on m.student_id = s.id and m.deleted_at is null\n where s.deleted_at is null\n   and not app.is_support_viewer(s.studio_id)\n   and (app.is_admin(s.studio_id)\n        or (app.has_role(s.studio_id, 'teacher')\n            and (s.id in (select app.teacher_student_ids())\n                 or s.id in (select app.teacher_event_student_ids())))\n        or (s.id in (select app.guardian_student_ids())\n            and s.id not in (select app.denied_student_ids('medical')))\n        or s.id = app.student_self_id());\ngrant select on student_safety_brief to authenticated, service_role;\n\n-- ── UR-21 · \"Book for myself\" for a parent already on the books ────────────\n-- Makes (or finds) the signed-in guardian's own adult participant record in\n-- their family, with someone to ring in an emergency (bookings need one).\n-- Nothing about their children is read or changed.\ncreate or replace function app.book_for_myself(p_dob date default null, p_adult_confirm boolean default false,\n                                               p_emergency_name text default null, p_emergency_phone text default null)\n  returns uuid\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare g guardian; kid uuid;\nbegin\n  select * into g from guardian\n   where user_id = auth.uid() and deleted_at is null and app.in_scope(studio_id) and app.studio_writable(studio_id)\n   order by created_at limit 1;\n  if g.id is null then\n    raise exception 'FORBIDDEN: only a parent or adult student on the school''s books can book for themselves'\n      using errcode = 'insufficient_privilege';\n  end if;\n  select id into kid from student where self_guardian_id = g.id and deleted_at is null;\n  if kid is null then\n    if p_dob is not null and (p_dob > current_date or p_dob < current_date - interval '110 years') then\n      raise exception 'INVALID: please check your date of birth' using errcode = 'check_violation';\n    end if;\n    if p_dob is not null and extract(year from age(current_date, p_dob)) < 18 then\n      raise exception 'INVALID: booking for yourself is for adults (18 and over)' using errcode = 'check_violation';\n    end if;\n    if p_dob is null and not coalesce(p_adult_confirm, false) then\n      raise exception 'INVALID: please confirm you are 18 or over, or give your date of birth' using errcode = 'check_violation';\n    end if;\n    kid := app.adult_participant_for(g.id, p_dob, p_emergency_name, p_emergency_phone);\n    insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n    values (g.studio_id, auth.uid(), 'create', 'student', kid, g.full_name || ' added themselves as an adult student');\n  elsif coalesce(btrim(p_emergency_phone), '') <> ''\n        and not exists (select 1 from emergency_contact where student_id = kid and deleted_at is null) then\n    insert into emergency_contact (studio_id, student_id, full_name, phone, priority)\n    values (g.studio_id, kid, coalesce(nullif(btrim(p_emergency_name), ''), 'Emergency contact'), btrim(p_emergency_phone), 1);\n  end if;\n  return kid;\nend $$;\nrevoke all on function app.book_for_myself(date, boolean, text, text) from public, anon;\ngrant execute on function app.book_for_myself(date, boolean, text, text) to authenticated;\n\n-- ── UR-08 · Schools name their consents ────────────────────────────────────\ncreate table if not exists consent_label (\n  studio_id   uuid not null references studio(id) on delete cascade,\n  kind        text not null check (kind in ('photography', 'video', 'social_media')),\n  label       text not null check (length(btrim(label)) between 1 and 60),\n  description text check (description is null or length(description) <= 400),\n  updated_by  uuid references user_account(id) on delete set null,\n  updated_at  timestamptz not null default now(),\n  primary key (studio_id, kind)\n);\nalter table consent_label enable row level security;\nalter table consent_label force row level security;\n-- Read and written through the functions below.\ngrant select, insert, update, delete on consent_label to service_role;\n\ncreate or replace function app.default_consent_label(p_kind text, out label text, out description text)\n  language sql immutable as $$\n  select case p_kind when 'photography' then 'Photos' when 'video' then 'Video' else 'Social media and public use' end,\n         case p_kind\n           when 'photography' then 'Photos taken in class or at shows, used by the school (noticeboards, records, programmes).'\n           when 'video' then 'Video recorded in class or at shows, for teaching and for families of the class.'\n           else 'Photos or video on the school’s website, social media, posters or in the press.' end\n$$;\n\n-- The school's words for each kind. Anyone in the school (staff, families,\n-- students) may read them: they are the labels on screens, nothing more.\n-- Which school: the student's, if given; else the one asked for; else the\n-- caller's current school.\ncreate or replace function app.consent_labels(p_studio uuid default null, p_student uuid default null)\n  returns table (kind text, label text, description text, renamed boolean)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare sid uuid; k text;\nbegin\n  if p_student is not null then\n    if not app.can_see_consent(p_student) then return; end if;\n    select s.studio_id into sid from student s where s.id = p_student;\n  elsif p_studio is not null then\n    if p_studio not in (select app.studio_ids())\n       and not exists (select 1 from guardian g where g.user_id = auth.uid() and g.studio_id = p_studio and g.deleted_at is null)\n       and not exists (select 1 from student s where s.id = app.student_self_id() and s.studio_id = p_studio) then\n      return;\n    end if;\n    sid := p_studio;\n  else\n    sid := coalesce((select x from app.studio_ids() x limit 1),\n                    (select g.studio_id from guardian g where g.user_id = auth.uid() and g.deleted_at is null\n                        and app.in_scope(g.studio_id) order by g.created_at limit 1),\n                    (select s.studio_id from student s where s.id = app.student_self_id()));\n    if sid is null then return; end if;\n  end if;\n  foreach k in array app.consent_kinds() loop\n    return query\n    select k, coalesce(l.label, d.label), coalesce(nullif(btrim(l.description), ''), d.description), l.kind is not null\n      from app.default_consent_label(k) d\n      left join consent_label l on l.studio_id = sid and l.kind = k;\n  end loop;\nend $$;\ngrant execute on function app.consent_labels(uuid, uuid), app.default_consent_label(text) to authenticated;\n\n-- The office renames a kind or rewrites its explanation. An empty label goes\n-- back to the standard wording.\ncreate or replace function app.set_consent_label(p_studio uuid, p_kind text, p_label text, p_description text default null)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.is_admin(p_studio) or app.is_support_viewer(p_studio) then\n    raise exception 'FORBIDDEN: only the office can change consent wording' using errcode = 'insufficient_privilege';\n  end if;\n  if not (p_kind = any(app.consent_kinds())) then\n    raise exception 'INVALID: unknown consent' using errcode = 'check_violation';\n  end if;\n  if coalesce(btrim(p_label), '') = '' then\n    delete from consent_label where studio_id = p_studio and kind = p_kind;\n  else\n    if length(btrim(p_label)) > 60 then\n      raise exception 'INVALID: keep the name to 60 characters' using errcode = 'check_violation';\n    end if;\n    if length(coalesce(p_description, '')) > 400 then\n      raise exception 'INVALID: keep the explanation to 400 characters' using errcode = 'check_violation';\n    end if;\n    insert into consent_label (studio_id, kind, label, description, updated_by)\n    values (p_studio, p_kind, btrim(p_label), nullif(btrim(p_description), ''), auth.uid())\n    on conflict (studio_id, kind) do update\n      set label = excluded.label, description = excluded.description, updated_by = auth.uid(), updated_at = now();\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (p_studio, auth.uid(), 'update', 'studio', p_studio,\n          'Consent wording for ' || p_kind || ': ' || coalesce(nullif(btrim(p_label), ''), 'standard'));\nend $$;\ngrant execute on function app.set_consent_label(uuid, text, text, text) to authenticated;\n\n-- set_consent as in 0047; the office alert now uses the school's own name\n-- for the kind when it has one.\ncreate or replace function app.set_consent(p_student uuid, p_kind text, p_granted boolean, p_note text default null, p_paper boolean default false)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare st record; src text; before_ record; after_ record; label text;\nbegin\n  select s.id, s.studio_id, s.first_name, s.last_name into st from student s where s.id = p_student and s.deleted_at is null;\n  if st.id is null then raise exception 'FORBIDDEN: not your child' using errcode = 'insufficient_privilege'; end if;\n  if p_student in (select app.guardian_student_ids()) then src := 'family';\n  elsif app.is_admin(st.studio_id) and not app.is_support_viewer(st.studio_id) then src := case when p_paper then 'paper' else 'office' end;\n  else raise exception 'FORBIDDEN: only the child''s guardians or the office record consent' using errcode = 'insufficient_privilege';\n  end if;\n  if p_granted is null then raise exception 'INVALID: say whether consent is given' using errcode = 'check_violation'; end if;\n  if not (p_kind = any(app.consent_kinds())) then raise exception 'INVALID: unknown consent' using errcode = 'check_violation'; end if;\n  select * into before_ from app.consent_effective(p_student, p_kind);\n  insert into consent_record (studio_id, student_id, kind, granted, granted_by, granted_at, note, source)\n  values (st.studio_id, p_student, p_kind::consent_kind, p_granted, auth.uid(), clock_timestamp(), nullif(btrim(p_note), ''), src);\n  select * into after_ from app.consent_effective(p_student, p_kind);\n  label := coalesce((select l.label from consent_label l where l.studio_id = st.studio_id and l.kind = p_kind),\n                    case p_kind when 'photography' then 'Photo' when 'video' then 'Video' else 'Social media' end);\n  if after_.disputed and not coalesce(before_.disputed, false) then\n    perform app.notify_admins(st.studio_id, 'consent', 'Guardians disagree: ' || lower(label) || ' consent for ' || st.first_name,\n      'The most restrictive choice applies until you settle it with the family.', '/people?tab=students');\n  elsif src = 'family' and after_.granted is distinct from before_.granted then\n    perform app.notify_admins(st.studio_id, 'consent',\n      label || ' consent ' || case when after_.granted then 'given' else 'withdrawn' end || ' for ' || st.first_name || ' ' || st.last_name,\n      'Teachers see the change on their next load.', '/people?tab=students');\n  end if;\nend $$;\n\n-- ── UR-08 · A student of 13+ sees their own consents, read-only ────────────\n-- With who to ask to change them: their parents or carers, then the office.\ncreate or replace function app.my_consents()\n  returns table (kind text, label text, description text, granted boolean, disputed boolean,\n                 changed_at timestamptz, ask text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare s student; who text;\nbegin\n  select * into s from student st where st.id = app.student_self_id();\n  if s.id is null or extract(year from age(current_date, s.date_of_birth)) < 13 then return; end if;\n  select string_agg(g.full_name, ' or ' order by g.is_primary desc, g.full_name) into who\n    from guardian g where g.family_id = s.family_id and g.deleted_at is null\n     and g.id is distinct from s.self_guardian_id;\n  return query\n  select l.kind, l.label, l.description, e.granted, e.disputed, e.changed_at,\n         case when s.is_adult then 'the school office'\n              when who is null then 'your parent or carer, or the school office'\n              else who || ', or the school office' end\n    from app.consent_labels(null, s.id) l\n    cross join lateral app.consent_effective(s.id, l.kind) e;\nend $$;\ngrant execute on function app.my_consents() to authenticated;\n"},{name:"0054_scale_fixes.sql",sql:"-- ============================================================================\n-- 0054 · Multi-site schools and switching schools (round 2: UR-32, UR-33)\n-- ----------------------------------------------------------------------------\n-- UR-33 · Location-scoped roles\n--   An administrator or teacher membership may be limited to one or more\n--   locations (membership_location). Owners are never limited. A school with\n--   one location, or with no limits set, behaves exactly as before.\n--\n--   The design is deny-by-default:\n--     · app.has_role no longer counts a *limited* administrator membership as\n--       'admin'. So app.is_admin(...) is false for them, and every existing\n--       policy, RPC and guard that asks \"is this the office?\" refuses them —\n--       nothing that was written for the whole school leaks to them.\n--     · app.is_staff still counts them, so they keep what every member of\n--       staff has (the staff list, notices to the school, the timetable).\n--     · They then get read access, through new permissive policies, to the\n--       records that belong to their locations: classes and sessions there;\n--       enrolments, trials, waiting lists and registers for those classes; the\n--       children in those classes with their emergency contacts, medical and\n--       consent records; and those children's families, guardians, invoices\n--       and payments. Reports read through the same rules, so they show only\n--       those locations.\n--     · A restrictive policy on class hides classes at other locations from\n--       anyone whose every staff role is limited (scoped teachers included),\n--       except classes they teach, cover, or their own child is in.\n--   What a limited administrator cannot do yet (refused, never half-done):\n--   change records, take payments, run billing, enrol, message families,\n--   import, invite. Those stay with the owner and all-location administrators.\n--\n-- UR-33 · Billing lists by location: SQL in lib/repos/billing.ts (no schema).\n--\n-- UR-32 · History imports, all-or-nothing like the other importers:\n--   · app.import_invoice_history(rows, commit): past invoices, kept apart from\n--     the ledger in imported_invoice — read-only, labelled \"Imported\", never in\n--     balances, aged debt, billing runs or the run guard.\n--   · app.import_attendance_history(rows, commit): counts per child per term.\n--   · app.import_exam_results(rows, commit): past exam results, as sat entries\n--     on exam sessions (so they appear wherever results already appear).\n-- UR-32 · Bulk invitations without email:\n--   · app.bulk_invitations(reissue): a normal 14-day invitation for every\n--     parent and teacher with an email and no login, returned once so the\n--     school can send the links from its own mail tool.\n-- ============================================================================\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-33 · Location-scoped roles\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate table membership_location (\n  membership_id uuid not null references membership(id) on delete cascade,\n  -- restrict, not cascade: losing the last row would silently widen access.\n  location_id   uuid not null references location(id) on delete restrict,\n  studio_id     uuid not null references studio(id) on delete cascade,\n  created_by    uuid references user_account(id) on delete set null,\n  created_at    timestamptz not null default now(),\n  primary key (membership_id, location_id)\n);\ncreate index membership_location_studio on membership_location (studio_id);\n\n-- Only administrators and teachers can be limited, and only to their own\n-- school's locations.\ncreate or replace function app.membership_location_check() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare m membership;\nbegin\n  select * into m from membership where id = new.membership_id;\n  if m.id is null or m.role not in ('admin', 'teacher') then\n    raise exception 'INVALID: only administrators and teachers can be limited to locations' using errcode = 'check_violation';\n  end if;\n  if new.studio_id <> m.studio_id\n     or not exists (select 1 from location l where l.id = new.location_id and l.studio_id = m.studio_id) then\n    raise exception 'INVALID: that location is not this school''s' using errcode = 'check_violation';\n  end if;\n  return new;\nend $$;\ncreate trigger membership_location_check before insert or update on membership_location\n  for each row execute function app.membership_location_check();\n\n-- A change of role, or removing someone, starts them afresh: an owner is\n-- never limited, and a limit chosen for one role is not silently carried to\n-- another.\ncreate or replace function app.membership_scope_reset() returns trigger\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if new.role is distinct from old.role or (new.deleted_at is not null and old.deleted_at is null) then\n    delete from membership_location where membership_id = new.id;\n  end if;\n  return new;\nend $$;\ncreate trigger membership_scope_reset after update on membership\n  for each row execute function app.membership_scope_reset();\n\nalter table membership_location enable row level security;\nalter table membership_location force row level security;\ncreate policy membership_location_read on membership_location for select\n  using (app.is_admin(studio_id)\n         or membership_id in (select id from membership where user_id = auth.uid() and deleted_at is null));\ngrant select on membership_location to authenticated;\ngrant all on membership_location to service_role;\n\n-- The locations a limited administrator membership covers; null when the\n-- caller's administrator role (if any) covers the whole school.\ncreate or replace function app.admin_scope(p_studio uuid) returns uuid[]\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select array_agg(ml.location_id order by ml.location_id)\n    from membership m join membership_location ml on ml.membership_id = m.id\n   where m.user_id = auth.uid() and m.studio_id = p_studio and m.role = 'admin' and m.deleted_at is null\n$$;\n\n-- A limited administrator is not 'admin' to any existing rule.\ncreate or replace function app.has_role(p_studio uuid, variadic p_roles app_role[])\n  returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from app.memberships() m\n                  where m.studio_id = p_studio and m.role = any(p_roles)\n                    and (m.role <> 'admin' or not exists (\n                          select 1 from membership mm join membership_location ml on ml.membership_id = mm.id\n                           where mm.user_id = auth.uid() and mm.studio_id = p_studio\n                             and mm.role = 'admin' and mm.deleted_at is null)))\n$$;\n\n-- A limited administrator: holds an administrator membership that is limited.\ncreate or replace function app.is_scoped_admin(p_studio uuid) returns boolean\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select exists (select 1 from app.memberships() m where m.studio_id = p_studio and m.role = 'admin')\n     and app.admin_scope(p_studio) is not null\n$$;\n\n-- Still a member of staff.\ncreate or replace function app.is_staff(p_studio uuid) returns boolean\n  language sql stable as $$\n  select app.has_role(p_studio, 'owner', 'admin', 'teacher') or app.is_scoped_admin(p_studio)\n$$;\n\n-- Schools where every staff role the caller holds is limited, with the\n-- locations those roles cover between them. A school missing from this list\n-- is not limited for the caller (owner, an unlimited role, or not staff).\ncreate or replace function app.my_location_scope()\n  returns table (studio_id uuid, location_id uuid)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with mine as (\n    select m.id, m.studio_id, m.role,\n           exists (select 1 from membership_location ml where ml.membership_id = m.id) as limited\n      from membership m\n     where m.user_id = auth.uid() and m.deleted_at is null and m.role in ('owner', 'admin', 'teacher')\n       and app.studio_writable(m.studio_id) and app.in_scope(m.studio_id)),\n  limited_schools as (\n    select mine.studio_id from mine group by mine.studio_id having bool_and(mine.limited and mine.role <> 'owner'))\n  select distinct ml.studio_id, ml.location_id\n    from membership_location ml join mine on mine.id = ml.membership_id\n   where mine.studio_id in (select ls.studio_id from limited_schools ls)\n$$;\n\n-- What a limited administrator may read: classes at their locations, the\n-- children in them, and those children's families.\ncreate or replace function app.admin_scope_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select c.id\n    from membership m\n    join membership_location ml on ml.membership_id = m.id\n    join class c on c.studio_id = m.studio_id and c.location_id = ml.location_id and c.deleted_at is null\n   where m.user_id = auth.uid() and m.role = 'admin' and m.deleted_at is null\n     and app.studio_writable(m.studio_id) and app.in_scope(m.studio_id)\n$$;\n\ncreate or replace function app.admin_scope_session_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select cs.id from class_session cs where cs.class_id in (select app.admin_scope_class_ids()) and cs.deleted_at is null\n$$;\n\ncreate or replace function app.admin_scope_student_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select e.student_id from enrolment e\n   where e.class_id in (select app.admin_scope_class_ids()) and e.status = 'active' and e.deleted_at is null\n  union\n  select t.student_id from trial t\n   where t.class_id in (select app.admin_scope_class_ids()) and t.student_id is not null and t.deleted_at is null\n     and t.status in ('requested', 'booked', 'attended')\n  union\n  select w.student_id from waitlist_entry w\n   where w.class_id in (select app.admin_scope_class_ids()) and w.deleted_at is null\n     and w.status in ('waiting', 'offered')\n$$;\n\ncreate or replace function app.admin_scope_family_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select distinct s.family_id from student s\n   where s.id in (select app.admin_scope_student_ids()) and s.deleted_at is null\n$$;\n\ncreate or replace function app.admin_scope_invoice_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select i.id from invoice i where i.family_id in (select app.admin_scope_family_ids()) and i.deleted_at is null\n$$;\n\ngrant execute on function app.admin_scope_session_ids(), app.admin_scope_invoice_ids() to authenticated;\ngrant execute on function app.admin_scope(uuid), app.is_scoped_admin(uuid), app.my_location_scope(),\n  app.admin_scope_class_ids(), app.admin_scope_student_ids(), app.admin_scope_family_ids() to authenticated;\n\n-- ── Classes at other locations are out of sight for limited staff ─────────\n-- Classes a limited person still sees wherever they are: one they cover, or\n-- one their own child is in. Read past RLS so the policy below never\n-- consults another table's policies.\ncreate or replace function app.scope_exempt_class_ids() returns setof uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select cs.class_id from class_session cs\n   where cs.deleted_at is null and cs.teacher_id in (select app.my_staff_ids())\n  union\n  select e.class_id from enrolment e\n   where e.deleted_at is null and e.student_id in (select app.guardian_student_ids())\n$$;\ngrant execute on function app.scope_exempt_class_ids() to authenticated;\n\ncreate policy class_location_scope on class as restrictive for select\n  using (\n    studio_id not in (select s.studio_id from app.my_location_scope() s)\n    or location_id in (select s.location_id from app.my_location_scope() s)\n    or id in (select app.teacher_class_ids())\n    or id in (select app.scope_exempt_class_ids()));\n\n-- ── What a limited administrator reads ─────────────────────────────────────\ncreate policy session_scoped_admin_read on class_session for select\n  using (deleted_at is null and class_id in (select app.admin_scope_class_ids()));\ncreate policy enrolment_scoped_admin_read on enrolment for select\n  using (deleted_at is null and class_id in (select app.admin_scope_class_ids()));\ncreate policy trial_scoped_admin_read on trial for select\n  using (deleted_at is null and class_id in (select app.admin_scope_class_ids()));\ncreate policy waitlist_scoped_admin_read on waitlist_entry for select\n  using (deleted_at is null and class_id in (select app.admin_scope_class_ids()));\ncreate policy attendance_scoped_admin_read on attendance_record for select\n  using (deleted_at is null and session_id in (select app.admin_scope_session_ids()));\ncreate policy student_scoped_admin_read on student for select\n  using (deleted_at is null and id in (select app.admin_scope_student_ids()));\ncreate policy emergency_scoped_admin_read on emergency_contact for select\n  using (deleted_at is null and student_id in (select app.admin_scope_student_ids()));\ncreate policy medical_scoped_admin_read on medical_record for select\n  using (deleted_at is null and student_id in (select app.admin_scope_student_ids()));\ncreate policy consent_scoped_admin_read on consent_record for select\n  using (deleted_at is null and student_id in (select app.admin_scope_student_ids()));\ncreate policy family_scoped_admin_read on family for select\n  using (deleted_at is null and id in (select app.admin_scope_family_ids()));\ncreate policy guardian_scoped_admin_read on guardian for select\n  using (deleted_at is null and family_id in (select app.admin_scope_family_ids()));\ncreate policy invoice_scoped_admin_read on invoice for select\n  using (deleted_at is null and family_id in (select app.admin_scope_family_ids()));\ncreate policy invoice_item_scoped_admin_read on invoice_item for select\n  using (deleted_at is null and invoice_id in (select app.admin_scope_invoice_ids()));\ncreate policy payment_scoped_admin_read on payment for select\n  using (deleted_at is null and family_id in (select app.admin_scope_family_ids()));\n\n-- Opening a child's medical record is logged for a limited administrator too.\ncreate or replace function app.log_medical_view(p_student uuid) returns boolean\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select studio_id into sid from student where id = p_student and deleted_at is null;\n  if sid is null or auth.uid() is null\n     or not (app.is_admin(sid) or p_student in (select app.admin_scope_student_ids())) then\n    return false;\n  end if;\n  if exists (select 1 from audit_log where actor_id = auth.uid() and entity = 'student' and entity_id = p_student\n               and action = 'view_medical' and at > now() - interval '1 hour') then\n    return false;\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'view_medical', 'student', p_student, 'opened the medical record');\n  return true;\nend $$;\n\n-- ── The owner sets the limits ──────────────────────────────────────────────\n-- An empty list (or null) means every location, including ones added later.\ncreate or replace function app.set_member_locations(p_member uuid, p_locations uuid[]) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare m membership; names text; who text;\nbegin\n  select * into m from membership where id = p_member and deleted_at is null;\n  if m.id is null then raise exception 'NOT_FOUND: that person no longer has access' using errcode = 'no_data_found'; end if;\n  if not app.has_role(m.studio_id, 'owner') then\n    raise exception 'FORBIDDEN: only an owner can choose who sees which locations' using errcode = 'insufficient_privilege';\n  end if;\n  if not app.studio_writable(m.studio_id) or app.in_read_only_tx() then\n    raise exception 'FORBIDDEN: this school''s account is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  if m.role not in ('admin', 'teacher') then\n    raise exception 'INVALID: owners always see every location' using errcode = 'check_violation';\n  end if;\n  if exists (select 1 from unnest(coalesce(p_locations, '{}')) x\n              where not exists (select 1 from location l where l.id = x and l.studio_id = m.studio_id and l.deleted_at is null)) then\n    raise exception 'INVALID: that location is not this school''s' using errcode = 'check_violation';\n  end if;\n  delete from membership_location where membership_id = m.id;\n  insert into membership_location (membership_id, location_id, studio_id, created_by)\n  select m.id, x, m.studio_id, auth.uid() from (select distinct unnest(coalesce(p_locations, '{}')) x) d;\n\n  select string_agg(l.name, ', ' order by l.name) into names from location l where l.id = any(coalesce(p_locations, '{}'));\n  select full_name into who from user_account where id = m.user_id;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (m.studio_id, auth.uid(), 'update', 'membership', m.id,\n          coalesce(who, 'Someone') || ' (' || m.role || '): ' || coalesce('only ' || names, 'every location'));\nend $$;\nrevoke all on function app.set_member_locations(uuid, uuid[]) from public;\ngrant execute on function app.set_member_locations(uuid, uuid[]) to authenticated;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-32 · History imports\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- Past invoices from the previous system: a record, not money. They are\n-- never part of the ledger, balances, aged debt or billing runs — the money\n-- still owed comes in once, as the opening balance.\ncreate table imported_invoice (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  family_id    uuid not null references family(id) on delete cascade,\n  number       text not null check (length(number) between 1 and 60),\n  issued_on    date not null,\n  due_on       date,\n  description  text check (description is null or length(description) <= 500),\n  total_minor  bigint not null check (total_minor >= 0),\n  paid_minor   bigint not null default 0 check (paid_minor >= 0),\n  imported_by  uuid references user_account(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  unique (family_id, number)\n);\ncreate index imported_invoice_family on imported_invoice (family_id, issued_on desc);\n\n-- Attendance kept by the previous system: one line per child, term and class.\ncreate table attendance_history (\n  id           uuid primary key default gen_random_uuid(),\n  studio_id    uuid not null references studio(id) on delete cascade,\n  student_id   uuid not null references student(id) on delete cascade,\n  period       text not null check (length(period) between 1 and 80),\n  class_name   text not null default '' check (length(class_name) <= 120),\n  attended     integer not null check (attended >= 0),\n  absent       integer not null default 0 check (absent >= 0),\n  imported_by  uuid references user_account(id) on delete set null,\n  created_at   timestamptz not null default now(),\n  unique (student_id, period, class_name)\n);\ncreate index attendance_history_student on attendance_history (student_id);\n\nalter table exam_session add column imported boolean not null default false;\n\nalter table imported_invoice enable row level security;   alter table imported_invoice force row level security;\nalter table attendance_history enable row level security; alter table attendance_history force row level security;\n-- Read-only for everyone: written only by the importers below.\ncreate policy imported_invoice_read on imported_invoice for select\n  using (app.is_admin(studio_id)\n         or family_id in (select app.guardian_family_ids())\n         or family_id in (select app.admin_scope_family_ids()));\ncreate policy attendance_history_read on attendance_history for select\n  using (app.is_admin(studio_id)\n         or student_id in (select app.guardian_student_ids())\n         or student_id = app.student_self_id()\n         or (app.has_role(studio_id, 'teacher') and student_id in (select app.teacher_student_ids()))\n         or student_id in (select app.admin_scope_student_ids()));\ngrant select on imported_invoice, attendance_history to authenticated;\ngrant all on imported_invoice, attendance_history to service_role;\n\n-- The family a history row belongs to: parent email, else family name.\ncreate or replace function app.import_find_family(p_studio uuid, r jsonb) returns uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(\n    (select g.family_id from guardian g join family f on f.id = g.family_id and f.deleted_at is null\n      where g.studio_id = p_studio and g.deleted_at is null and nullif(btrim(r ->> 'parent_email'), '') is not null\n        and lower(g.email) = lower(btrim(r ->> 'parent_email')) limit 1),\n    (select f.id from family f where f.studio_id = p_studio and f.deleted_at is null and nullif(btrim(r ->> 'family'), '') is not null\n        and (lower(f.name) = lower(btrim(r ->> 'family')) or lower(f.name) = lower(btrim(r ->> 'family')) || ' family')\n      order by f.created_at limit 1))\n$$;\n\n-- The children a history row could mean: first name, and whichever of last\n-- name, date of birth and parent email the file gives. The caller insists on\n-- exactly one.\ncreate or replace function app.import_find_students(p_studio uuid, r jsonb, p_dob date) returns uuid[]\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(array_agg(s.id), '{}') from student s\n   where s.studio_id = p_studio and s.deleted_at is null\n     and lower(s.first_name) = lower(btrim(coalesce(r ->> 'child_first_name', '')))\n     and (nullif(btrim(r ->> 'child_last_name'), '') is null or lower(s.last_name) = lower(btrim(r ->> 'child_last_name')))\n     and (p_dob is null or s.date_of_birth = p_dob)\n     and (nullif(btrim(r ->> 'parent_email'), '') is null or exists (\n           select 1 from guardian g where g.family_id = s.family_id and g.deleted_at is null\n              and lower(g.email) = lower(btrim(r ->> 'parent_email'))))\n$$;\n\n-- One child for a row, or a message saying why not.\ncreate or replace function app.import_student_or_error(p_studio uuid, r jsonb, out student_id uuid, out message text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare dob date; ids uuid[]; who text;\nbegin\n  who := btrim(coalesce(r ->> 'child_first_name', '') || ' ' || coalesce(r ->> 'child_last_name', ''));\n  if coalesce(btrim(r ->> 'child_first_name'), '') = '' then message := 'No child first name'; return; end if;\n  begin\n    dob := app.parse_date(r ->> 'child_dob');\n  exception when others then\n    message := 'Cannot read the date of birth \"' || (r ->> 'child_dob') || '\" — use DD/MM/YYYY'; return;\n  end;\n  ids := app.import_find_students(p_studio, r, dob);\n  if cardinality(ids) = 0 then\n    message := 'No child called ' || who || ' matches — import families first, or check the name and date of birth';\n  elsif cardinality(ids) > 1 then\n    message := 'More than one child called ' || who || ' — add their date of birth or a parent email';\n  else\n    student_id := ids[1];\n  end if;\nend $$;\n\n-- An amount like \"45\", \"£45.00\" or \"1,045.50\", in pence. Null when blank.\ncreate or replace function app.import_money(p text) returns bigint\n  language plpgsql immutable as $$\ndeclare t text := regexp_replace(coalesce(p, ''), '[£,\\s]', '', 'g');\nbegin\n  if t = '' then return null; end if;\n  if t !~ '^-?\\d+(\\.\\d{1,2})?$' then raise exception 'unreadable amount'; end if;\n  return round(t::numeric * 100)::bigint;\nend $$;\n\ncreate or replace function app.import_count(p text) returns integer\n  language plpgsql immutable as $$\ndeclare t text := btrim(coalesce(p, ''));\nbegin\n  if t = '' then return null; end if;\n  if t !~ '^\\d{1,4}$' then raise exception 'unreadable count'; end if;\n  return t::int;\nend $$;\n\n-- The school an import is for: the one the caller runs as owner or\n-- all-location administrator. Refused otherwise.\ncreate or replace function app.import_school(p_commit boolean) returns uuid\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid;\nbegin\n  select id into sid from studio where deleted_at is null and app.is_admin(id) and app.in_scope(id) order by created_at limit 1;\n  if sid is null then\n    raise exception 'FORBIDDEN: only the school office can import' using errcode = 'insufficient_privilege';\n  end if;\n  if p_commit and not app.studio_writable(sid) then\n    raise exception 'FORBIDDEN: this school is read-only' using errcode = 'insufficient_privilege';\n  end if;\n  return sid;\nend $$;\n\ncreate or replace function app.import_rows_ok(p_rows jsonb, p_max int) returns void\n  language plpgsql immutable as $$\nbegin\n  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then\n    raise exception 'INVALID: the file has no rows' using errcode = 'check_violation';\n  end if;\n  if jsonb_array_length(p_rows) > p_max then\n    raise exception 'INVALID: import at most % rows at a time', p_max using errcode = 'check_violation';\n  end if;\nend $$;\n\n-- ── Past invoices ──────────────────────────────────────────────────────────\n-- Keys (text): parent_email or family*, number*, issued_on*, due_on,\n-- description, total*, paid.\ncreate or replace function app.import_invoice_history(p_rows jsonb, p_commit boolean default false)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid := app.import_school(p_commit); r jsonb; i int := 0; errs jsonb := '[]'::jsonb; warns jsonb := '[]'::jsonb;\n  fam uuid; issued date; due date; total bigint; paid bigint; seen text[] := '{}'; k text; num text;\n  n_new int := 0; n_skip int := 0;\nbegin\n  perform app.import_rows_ok(p_rows, 5000);\n  for pass in 1..2 loop\n    exit when pass = 2 and (not p_commit or jsonb_array_length(errs) > 0);\n    i := 0; seen := '{}';\n    for r in select * from jsonb_array_elements(p_rows) loop\n      i := i + 1;\n      fam := app.import_find_family(sid, r);\n      num := btrim(coalesce(r ->> 'number', ''));\n      begin\n        issued := app.parse_date(r ->> 'issued_on');\n        due := app.parse_date(r ->> 'due_on');\n      exception when others then\n        if pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Cannot read a date on this row — use DD/MM/YYYY'); end if;\n        continue;\n      end;\n      begin\n        total := app.import_money(r ->> 'total');\n        paid := coalesce(app.import_money(r ->> 'paid'), 0);\n      exception when others then\n        if pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Total and paid must be amounts, like 45.00'); end if;\n        continue;\n      end;\n      if pass = 1 then\n        if fam is null then\n          errs := errs || jsonb_build_object('row', i, 'message', 'No family with ' ||\n            coalesce('the email \"' || nullif(btrim(r ->> 'parent_email'), '') || '\"', 'the name \"' || coalesce(r ->> 'family', '') || '\"') || ' — import families first');\n        end if;\n        if num = '' then errs := errs || jsonb_build_object('row', i, 'message', 'No invoice number'); end if;\n        if issued is null then errs := errs || jsonb_build_object('row', i, 'message', 'No invoice date');\n        elsif issued > current_date then errs := errs || jsonb_build_object('row', i, 'message', 'The invoice date is in the future'); end if;\n        if total is null then errs := errs || jsonb_build_object('row', i, 'message', 'No total');\n        elsif total < 0 then errs := errs || jsonb_build_object('row', i, 'message', 'The total cannot be negative'); end if;\n        if paid < 0 then errs := errs || jsonb_build_object('row', i, 'message', 'Paid cannot be negative'); end if;\n        k := coalesce(fam::text, '') || '|' || lower(num);\n        if fam is not null and num <> '' then\n          if k = any(seen) then errs := errs || jsonb_build_object('row', i, 'message', 'Invoice ' || num || ' is in the file twice for this family'); end if;\n          seen := seen || k;\n          if exists (select 1 from imported_invoice x where x.family_id = fam and lower(x.number) = lower(num)) then\n            warns := warns || jsonb_build_object('message', 'Row ' || i || ': invoice ' || num || ' is already here and will be left alone');\n          end if;\n        end if;\n        continue;\n      end if;\n      if exists (select 1 from imported_invoice x where x.family_id = fam and lower(x.number) = lower(num)) then\n        n_skip := n_skip + 1; continue;\n      end if;\n      insert into imported_invoice (studio_id, family_id, number, issued_on, due_on, description, total_minor, paid_minor, imported_by)\n      values (sid, fam, num, issued, due, nullif(btrim(coalesce(r ->> 'description', '')), ''), total, paid, auth.uid());\n      n_new := n_new + 1;\n    end loop;\n  end loop;\n\n  if not p_commit or jsonb_array_length(errs) > 0 then\n    if p_commit then\n      raise exception 'INVALID: % row(s) need fixing before anything is imported', jsonb_array_length(errs) using errcode = 'check_violation';\n    end if;\n    return jsonb_build_object('ok', jsonb_array_length(errs) = 0, 'rows', i, 'errors', errs, 'warnings', warns);\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'import', 'invoice', null, format('Imported %s past invoices as history; %s already here', n_new, n_skip));\n  return jsonb_build_object('ok', true, 'rows', i, 'invoices', n_new, 'skipped', n_skip, 'errors', '[]'::jsonb, 'warnings', warns);\nend $$;\n\n-- ── Attendance summaries ───────────────────────────────────────────────────\n-- Keys: child_first_name*, child_last_name, child_dob, parent_email,\n-- period* (a term name), class, attended*, absent.\ncreate or replace function app.import_attendance_history(p_rows jsonb, p_commit boolean default false)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid := app.import_school(p_commit); r jsonb; i int := 0; errs jsonb := '[]'::jsonb; warns jsonb := '[]'::jsonb;\n  found record; att int; abs_ int; per text; cls text; seen text[] := '{}'; k text; n_new int := 0; n_skip int := 0;\nbegin\n  perform app.import_rows_ok(p_rows, 5000);\n  for pass in 1..2 loop\n    exit when pass = 2 and (not p_commit or jsonb_array_length(errs) > 0);\n    i := 0; seen := '{}';\n    for r in select * from jsonb_array_elements(p_rows) loop\n      i := i + 1;\n      found := app.import_student_or_error(sid, r);\n      per := btrim(coalesce(r ->> 'period', ''));\n      cls := btrim(coalesce(r ->> 'class', ''));\n      begin\n        att := app.import_count(r ->> 'attended');\n        abs_ := coalesce(app.import_count(r ->> 'absent'), 0);\n      exception when others then\n        if pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Attended and absent must be whole numbers'); end if;\n        continue;\n      end;\n      if pass = 1 then\n        if found.message is not null then errs := errs || jsonb_build_object('row', i, 'message', found.message); end if;\n        if per = '' then errs := errs || jsonb_build_object('row', i, 'message', 'No term'); end if;\n        if att is null then errs := errs || jsonb_build_object('row', i, 'message', 'No attended count'); end if;\n        if found.student_id is not null and per <> '' then\n          k := found.student_id::text || '|' || lower(per) || '|' || lower(cls);\n          if k = any(seen) then errs := errs || jsonb_build_object('row', i, 'message', 'This child, term and class are in the file twice'); end if;\n          seen := seen || k;\n          if exists (select 1 from attendance_history h where h.student_id = found.student_id\n                       and lower(h.period) = lower(per) and lower(h.class_name) = lower(cls)) then\n            warns := warns || jsonb_build_object('message', 'Row ' || i || ': this term is already here for this child and will be left alone');\n          end if;\n        end if;\n        continue;\n      end if;\n      if exists (select 1 from attendance_history h where h.student_id = found.student_id\n                   and lower(h.period) = lower(per) and lower(h.class_name) = lower(cls)) then\n        n_skip := n_skip + 1; continue;\n      end if;\n      insert into attendance_history (studio_id, student_id, period, class_name, attended, absent, imported_by)\n      values (sid, found.student_id, per, cls, att, abs_, auth.uid());\n      n_new := n_new + 1;\n    end loop;\n  end loop;\n\n  if not p_commit or jsonb_array_length(errs) > 0 then\n    if p_commit then\n      raise exception 'INVALID: % row(s) need fixing before anything is imported', jsonb_array_length(errs) using errcode = 'check_violation';\n    end if;\n    return jsonb_build_object('ok', jsonb_array_length(errs) = 0, 'rows', i, 'errors', errs, 'warnings', warns);\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'import', 'student', null, format('Imported %s attendance summaries; %s already here', n_new, n_skip));\n  return jsonb_build_object('ok', true, 'rows', i, 'records', n_new, 'skipped', n_skip, 'errors', '[]'::jsonb, 'warnings', warns);\nend $$;\n\n-- ── Exam results ───────────────────────────────────────────────────────────\n-- Keys: child_first_name*, child_last_name, child_dob, parent_email, board*,\n-- grade*, exam_date*, result, mark, title.\ncreate or replace function app.import_result(p text) returns text\n  language sql immutable as $$\n  select case regexp_replace(lower(btrim(coalesce(p, ''))), '[^a-z]', '', 'g')\n    when '' then null\n    when 'distinction' then 'distinction' when 'merit' then 'merit' when 'pass' then 'pass'\n    when 'commended' then 'commended' when 'highlycommended' then 'highly_commended'\n    when 'notyet' then 'not_yet' when 'notyetachieved' then 'not_yet' when 'fail' then 'not_yet'\n    else '?' end\n$$;\n\ncreate or replace function app.import_exam_results(p_rows jsonb, p_commit boolean default false)\n  returns jsonb\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare\n  sid uuid := app.import_school(p_commit); r jsonb; i int := 0; errs jsonb := '[]'::jsonb; warns jsonb := '[]'::jsonb;\n  found record; on_ date; res text; mk int; brd text; grd text; sess uuid; seen text[] := '{}'; k text;\n  n_new int := 0; n_skip int := 0; n_sess int := 0;\nbegin\n  perform app.import_rows_ok(p_rows, 5000);\n  for pass in 1..2 loop\n    exit when pass = 2 and (not p_commit or jsonb_array_length(errs) > 0);\n    i := 0; seen := '{}';\n    for r in select * from jsonb_array_elements(p_rows) loop\n      i := i + 1;\n      found := app.import_student_or_error(sid, r);\n      brd := btrim(coalesce(r ->> 'board', ''));\n      grd := btrim(coalesce(r ->> 'grade', ''));\n      res := app.import_result(r ->> 'result');\n      begin\n        on_ := app.parse_date(r ->> 'exam_date');\n        mk := app.import_count(r ->> 'mark');\n      exception when others then\n        if pass = 1 then errs := errs || jsonb_build_object('row', i, 'message', 'Cannot read the exam date or mark on this row'); end if;\n        continue;\n      end;\n      if pass = 1 then\n        if found.message is not null then errs := errs || jsonb_build_object('row', i, 'message', found.message); end if;\n        if brd = '' then errs := errs || jsonb_build_object('row', i, 'message', 'No exam board'); end if;\n        if grd = '' then errs := errs || jsonb_build_object('row', i, 'message', 'No grade'); end if;\n        if on_ is null then errs := errs || jsonb_build_object('row', i, 'message', 'No exam date');\n        elsif on_ > current_date then errs := errs || jsonb_build_object('row', i, 'message', 'The exam date is in the future — results are for exams already taken'); end if;\n        if res = '?' then errs := errs || jsonb_build_object('row', i, 'message',\n          'Result \"' || (r ->> 'result') || '\" is not one of distinction, merit, pass, highly commended, commended or not yet'); end if;\n        if mk is not null and mk > 100 then errs := errs || jsonb_build_object('row', i, 'message', 'A mark is out of 100'); end if;\n        if found.student_id is not null and on_ is not null and grd <> '' then\n          k := found.student_id::text || '|' || lower(brd) || '|' || on_::text || '|' || lower(grd);\n          if k = any(seen) then errs := errs || jsonb_build_object('row', i, 'message', 'This child''s result is in the file twice'); end if;\n          seen := seen || k;\n        end if;\n        continue;\n      end if;\n\n      select id into sess from exam_session where studio_id = sid and deleted_at is null and lower(board) = lower(brd) and exam_on = on_\n        order by created_at limit 1;\n      if sess is null then\n        insert into exam_session (studio_id, board, title, exam_on, created_by, imported)\n        values (sid, brd, coalesce(nullif(btrim(coalesce(r ->> 'title', '')), ''), brd || ' exams'), on_, auth.uid(), true)\n        returning id into sess;\n        n_sess := n_sess + 1;\n      end if;\n      if exists (select 1 from exam_entry e where e.session_id = sess and e.student_id = found.student_id and lower(e.grade) = lower(grd)) then\n        n_skip := n_skip + 1; continue;\n      end if;\n      insert into exam_entry (studio_id, session_id, student_id, grade, status, result, mark, entered_by)\n      values (sid, sess, found.student_id, grd, 'sat', res, mk, auth.uid());\n      n_new := n_new + 1;\n    end loop;\n  end loop;\n\n  if not p_commit or jsonb_array_length(errs) > 0 then\n    if p_commit then\n      raise exception 'INVALID: % row(s) need fixing before anything is imported', jsonb_array_length(errs) using errcode = 'check_violation';\n    end if;\n    return jsonb_build_object('ok', jsonb_array_length(errs) = 0, 'rows', i, 'errors', errs, 'warnings', warns);\n  end if;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'import', 'student', null, format('Imported %s past exam results (%s exam sessions); %s already here', n_new, n_sess, n_skip));\n  return jsonb_build_object('ok', true, 'rows', i, 'results', n_new, 'sessions', n_sess, 'skipped', n_skip, 'errors', '[]'::jsonb, 'warnings', warns);\nend $$;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- UR-32 · Bulk invitation links\n-- ════════════════════════════════════════════════════════════════════════════\n-- Every parent and teacher with an email and no login gets a normal\n-- invitation (14 days, one use). The links come back once — only their hash\n-- is kept — for the school to send from its own mail tool. Someone with a\n-- live invitation keeps it unless p_reissue, which replaces it (the old link\n-- stops working). People without an email are listed, without a link.\ncreate or replace function app.bulk_invitations(p_reissue boolean default false)\n  returns table (role text, full_name text, email text, family_name text, token text, expires_at timestamptz, note text)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\n#variable_conflict use_column\ndeclare sid uuid := app.import_school(true); p record; seen text[] := '{}'; tok text; n int := 0;\nbegin\n  for p in\n    select 'teacher'::text as r, s.display_name as nm, nullif(lower(btrim(s.email)), '') as em, null::uuid as fam, null::text as fam_name, 0 as ord\n      from staff_member s\n     where s.studio_id = sid and s.deleted_at is null and s.user_id is null and s.status = 'active'\n    union all\n    select 'guardian', g.full_name, nullif(lower(btrim(g.email)), ''), g.family_id, f.name, 1\n      from guardian g join family f on f.id = g.family_id and f.deleted_at is null\n     where g.studio_id = sid and g.deleted_at is null and g.user_id is null\n    order by 6, 5, 2\n  loop\n    role := p.r; full_name := p.nm; email := p.em; family_name := p.fam_name; token := null; expires_at := null; note := null;\n    if p.em is null or p.em !~ '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$' then\n      note := 'No email address — add one, then make the links again';\n    elsif (p.r || '|' || p.em) = any(seen) then\n      note := 'Same email as another ' || case when p.r = 'teacher' then 'teacher' else 'parent' end || ' above';\n    elsif not p_reissue and exists (select 1 from studio_invitation i where i.studio_id = sid and lower(i.email) = p.em\n                                      and i.role = p.r::app_role and i.accepted_at is null and i.revoked_at is null and i.expires_at > now()) then\n      note := 'Already invited — the earlier link still works';\n    else\n      tok := app.create_invitation(sid, p.em, p.r::app_role, p.nm, p.fam, null);\n      token := tok;\n      expires_at := (select i.expires_at from studio_invitation i where i.token_hash = app.hash_token(tok));\n      n := n + 1;\n    end if;\n    if p.em is not null then seen := seen || (p.r || '|' || p.em); end if;\n    return next;\n  end loop;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (sid, auth.uid(), 'invite', 'studio_invitation', null, format('Made %s invitation links to send by the school''s own email', n));\nend $$;\n\nrevoke all on function app.import_invoice_history(jsonb, boolean), app.import_attendance_history(jsonb, boolean),\n  app.import_exam_results(jsonb, boolean), app.bulk_invitations(boolean), app.import_find_family(uuid, jsonb),\n  app.import_find_students(uuid, jsonb, date), app.import_student_or_error(uuid, jsonb), app.import_school(boolean) from public;\ngrant execute on function app.import_invoice_history(jsonb, boolean), app.import_attendance_history(jsonb, boolean),\n  app.import_exam_results(jsonb, boolean), app.bulk_invitations(boolean) to authenticated;\ngrant execute on function app.import_money(text), app.import_count(text), app.import_result(text), app.import_rows_ok(jsonb, int) to authenticated;\n"},{name:"0055_agenda.sql",sql:"-- ============================================================================\n-- 0055 · A teacher's own week across schools (UR-47)\n-- ----------------------------------------------------------------------------\n-- DESIGN NOTE\n--\n-- Problem. A teacher who works at two schools (Priya: Northstar and Kestrel)\n-- has one login but sees one school at a time (0032: app.in_scope narrows\n-- every helper to the chosen school). She cannot see her week, nor clashes\n-- between schools, and the office arranging cover cannot see that she is\n-- teaching elsewhere.\n--\n-- Principle kept from 0032. No school's records reach another school. The\n-- only thing that crosses is the teacher's OWN timetable, to the teacher\n-- herself, and at most a \"busy\" time to another school's office.\n--\n-- What crosses, and the one way it crosses:\n--   app.agenda_rows(user, from, to)   internal, never granted. The teacher's\n--       own sessions (teaches, assists, or covers) at every school where she\n--       is an active staff member with a live staff membership. Columns:\n--       session id, school, start, end, class name, site, room, status\n--       (scheduled / moved / cancelled / covered), covering, handover-present\n--       flag, and the school's sharing setting. Nothing about students,\n--       medical needs, attendance, families, or other teachers (a class\n--       covered by someone else says only \"covered\", never by whom).\n--   app.my_agenda(from, to)           granted; the teacher's agenda for at\n--       most 35 days, rows from agenda_rows(auth.uid()) filtered by each\n--       school's sharing setting, with clashes worked out in the database.\n--   app.cover_clashes / cover_session the office's cover check also sees the\n--       teacher's sessions at other schools, as \"busy\" only: no class name,\n--       place, school or session id.\n--   app.calendar_feed                 a staff calendar link can include all\n--       schools (calendar_token.all_schools), with the same filter.\n--\n-- Each school's choice: studio.staff_timetable_sharing, shown when the\n-- teacher is NOT looking at that school (another school is selected in the\n-- switcher, or it is a calendar link made from another school):\n--   'details'  class name, site and room, cancellations and moves;\n--   'times'    (default) only the time, as \"Busy\", with the school's name;\n--   'none'     nothing: the school's sessions are left out of the teacher's\n--              agenda elsewhere and of other schools' cover checks.\n-- Whichever school the teacher is looking at shows in full, as it already\n-- does on her Today screen. With no school chosen and only one school, that\n-- school is \"home\"; with no school chosen and several, every school's\n-- setting applies.\n-- Other schools' cover checks only ever see \"busy\", and only when the\n-- setting is 'details' or 'times'.\n--\n-- Travel: user_account.agenda_travel_min (the teacher's own setting, default\n-- 30): two sessions at different schools clash when they are closer than\n-- that. Within one school, different sites use the school's\n-- cover_travel_min (0048) and the same site needs none.\n--\n-- Opening a row switches the app to that school first (the screen does it),\n-- so every other path still goes through RLS and app.in_scope unchanged.\n-- ============================================================================\n\n-- ── Settings ───────────────────────────────────────────────────────────────\nalter table studio add column staff_timetable_sharing text not null default 'times'\n  check (staff_timetable_sharing in ('details', 'times', 'none'));\nalter table user_account add column agenda_travel_min smallint not null default 30\n  check (agenda_travel_min between 0 and 240);\nalter table calendar_token add column all_schools boolean not null default false;\n\ncreate or replace function app.my_agenda_travel() returns int\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select agenda_travel_min::int from user_account where id = auth.uid() and deleted_at is null\n$$;\n\ncreate or replace function app.set_agenda_travel(p_min int) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if auth.uid() is null then raise exception 'FORBIDDEN: sign in first' using errcode = 'insufficient_privilege'; end if;\n  if p_min is null or p_min < 0 or p_min > 240 then\n    raise exception 'INVALID: travel time is between 0 and 240 minutes' using errcode = 'check_violation';\n  end if;\n  update user_account set agenda_travel_min = p_min where id = auth.uid();\nend $$;\n\n-- The school's choice; owner only.\ncreate or replace function app.set_timetable_sharing(p_studio uuid, p_sharing text) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if not app.has_role(p_studio, 'owner') then\n    raise exception 'FORBIDDEN: only the owner can change this' using errcode = 'insufficient_privilege';\n  end if;\n  if p_sharing is null or p_sharing not in ('details', 'times', 'none') then\n    raise exception 'INVALID: choose details, times or none' using errcode = 'check_violation';\n  end if;\n  update studio set staff_timetable_sharing = p_sharing, updated_at = now() where id = p_studio;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (p_studio, auth.uid(), 'update', 'studio', p_studio,\n          'Staff timetables shown at their other schools: ' ||\n          case p_sharing when 'details' then 'class details' when 'times' then 'busy times only' else 'nothing' end);\nend $$;\n\n-- ── The one cross-school read ─────────────────────────────────────────────\n-- Trusts p_user, so it is never granted: my_agenda, cover_clashes and\n-- calendar_feed are the only ways in.\ncreate or replace function app.agenda_rows(p_user uuid, p_from timestamptz, p_to timestamptz)\n  returns table (session_id uuid, studio_id uuid, school_name text, starts_at timestamptz, ends_at timestamptz,\n                 class_name text, location text, room text, status text, covering boolean, has_handover boolean,\n                 sharing text, location_id uuid, staff_id uuid)\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  with me as (\n    select sm.id, sm.studio_id from staff_member sm\n     where sm.user_id = p_user and sm.deleted_at is null and sm.status = 'active'\n       and app.studio_writable(sm.studio_id)\n       and exists (select 1 from membership m where m.user_id = p_user and m.studio_id = sm.studio_id\n                     and m.deleted_at is null and m.role in ('owner', 'admin', 'teacher'))\n  )\n  select cs.id, cs.studio_id, st.name, cs.starts_at, cs.ends_at, c.name, l.name, coalesce(sr.name, r.name),\n         case when cs.status = 'cancelled' then 'cancelled'\n              when c.teacher_id = me.id and cs.teacher_id is not null and cs.teacher_id <> me.id then 'covered'\n              when cs.status = 'rescheduled' or (cs.original_starts_at is not null and cs.original_starts_at <> cs.starts_at) then 'moved'\n              else 'scheduled' end,\n         (cs.teacher_id = me.id and c.teacher_id is distinct from me.id),\n         nullif(btrim(coalesce(cs.handover_note, '')), '') is not null,\n         st.staff_timetable_sharing, c.location_id, me.id\n    from me\n    join class c on c.studio_id = me.studio_id and c.deleted_at is null\n    join class_session cs on cs.class_id = c.id and cs.deleted_at is null\n    join studio st on st.id = cs.studio_id and st.deleted_at is null\n    left join room r on r.id = c.room_id\n    left join room sr on sr.id = cs.room_id\n    left join location l on l.id = c.location_id\n   where (c.teacher_id = me.id or c.assistant_id = me.id or cs.teacher_id = me.id)\n     and cs.starts_at >= p_from and cs.starts_at < p_to\n$$;\nrevoke all on function app.agenda_rows(uuid, timestamptz, timestamptz) from public, authenticated, anon;\n\n-- The school whose screens the teacher is on: the one chosen, or her only one.\ncreate or replace function app.agenda_home(p_user uuid) returns uuid\n  language sql stable security definer set search_path = public, app, pg_temp as $$\n  select coalesce(app.selected_studio(),\n    (select case when count(distinct sm.studio_id) = 1 then (array_agg(sm.studio_id))[1] end\n       from staff_member sm where sm.user_id = p_user and sm.deleted_at is null and sm.status = 'active'))\n$$;\nrevoke all on function app.agenda_home(uuid) from public, authenticated, anon;\n\n-- The teacher's own agenda, across schools, filtered by each school's choice.\n-- detail: 'full' or 'busy'. clash: overlaps another of her sessions, travel\n-- included; clash_with: the other school(s) involved, null when the clash is\n-- within the same school. Cancelled and covered rows never clash.\ncreate or replace function app.my_agenda(p_from timestamptz, p_to timestamptz)\n  returns table (session_id uuid, studio_id uuid, school_name text, starts_at timestamptz, ends_at timestamptz,\n                 class_name text, location text, room text, status text, covering boolean, has_handover boolean,\n                 detail text, clash boolean, clash_with text)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare me uuid := auth.uid(); home uuid; travel interval;\nbegin\n  if me is null then return; end if;\n  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '35 days' then\n    raise exception 'INVALID: an agenda covers up to 35 days' using errcode = 'check_violation';\n  end if;\n  home := app.agenda_home(me);\n  travel := make_interval(mins => coalesce((select agenda_travel_min from user_account where id = me), 30));\n  return query\n  with a as (\n    select x.*, (x.studio_id = home or x.sharing = 'details') as full_view\n      from app.agenda_rows(me, p_from, p_to) x\n  ),\n  v as (\n    select a.* from a\n     where a.full_view or (a.sharing = 'times' and a.status in ('scheduled', 'moved'))\n  ),\n  live as (select v.* from v where v.status in ('scheduled', 'moved'))\n  select v.session_id, v.studio_id, v.school_name, v.starts_at, v.ends_at,\n         case when v.full_view then v.class_name end,\n         case when v.full_view then v.location end,\n         case when v.full_view then v.room end,\n         case when v.full_view then v.status else 'scheduled' end,\n         v.full_view and v.covering,\n         v.full_view and v.has_handover,\n         case when v.full_view then 'full' else 'busy' end,\n         k.n > 0,\n         k.schools\n    from v\n    left join lateral (\n      select count(*) as n,\n             string_agg(distinct case when o.studio_id <> v.studio_id then o.school_name end, ', ') as schools\n        from live o join studio ost on ost.id = o.studio_id\n       where v.status in ('scheduled', 'moved') and o.session_id <> v.session_id\n         and o.starts_at < v.ends_at + app.agenda_gap(v.studio_id, v.location_id, o.studio_id, o.location_id, ost.cover_travel_min, travel)\n         and o.ends_at + app.agenda_gap(v.studio_id, v.location_id, o.studio_id, o.location_id, ost.cover_travel_min, travel) > v.starts_at\n    ) k on true\n   order by v.starts_at, v.school_name;\nend $$;\n\n-- Time needed between two sessions: none at one site, the school's travel\n-- time between its sites, the teacher's own travel time between schools.\ncreate or replace function app.agenda_gap(a_studio uuid, a_loc uuid, b_studio uuid, b_loc uuid, school_travel smallint, own_travel interval)\n  returns interval language sql immutable as $$\n  select case when a_studio <> b_studio then own_travel\n              when a_loc is distinct from b_loc then make_interval(mins => school_travel)\n              else interval '0' end\n$$;\n\nrevoke all on function app.my_agenda(timestamptz, timestamptz), app.my_agenda_travel(), app.set_agenda_travel(int),\n  app.set_timetable_sharing(uuid, text) from public;\ngrant execute on function app.my_agenda(timestamptz, timestamptz), app.my_agenda_travel(), app.set_agenda_travel(int),\n  app.set_timetable_sharing(uuid, text), app.agenda_gap(uuid, uuid, uuid, uuid, smallint, interval) to authenticated;\n\n-- ── Cover check sees \"busy\" at other schools (extends 0048) ───────────────\n-- Same columns as before. A row from another school has no session id, is\n-- called \"Busy at another school\", has no place, and always needs travel.\ncreate or replace function app.cover_clashes(p_session uuid, p_teacher uuid)\n  returns table (session_id uuid, class_name text, starts_at timestamptz, ends_at timestamptz,\n                 location text, needs_travel boolean)\n  language plpgsql stable security definer set search_path = public, app, pg_temp as $$\ndeclare sid uuid; u uuid; s0 timestamptz; e0 timestamptz; travel interval;\nbegin\n  select cs.studio_id, cs.starts_at, cs.ends_at into sid, s0, e0 from class_session cs where cs.id = p_session;\n  if sid is null or not app.is_admin(sid) then\n    raise exception 'FORBIDDEN: only the office arranges cover' using errcode = 'insufficient_privilege';\n  end if;\n  return query\n  select o.id, c2.name, o.starts_at, o.ends_at, l2.name, (c2.location_id is distinct from c.location_id)\n    from class_session cs\n    join class c on c.id = cs.class_id\n    join studio st on st.id = cs.studio_id\n    join class_session o on o.studio_id = cs.studio_id and o.id <> cs.id and o.deleted_at is null and o.status <> 'cancelled'\n    join class c2 on c2.id = o.class_id and c2.deleted_at is null\n    left join location l2 on l2.id = c2.location_id\n   where cs.id = p_session\n     and (coalesce(o.teacher_id, c2.teacher_id) = p_teacher or c2.assistant_id = p_teacher)\n     and o.starts_at < cs.ends_at + case when c2.location_id is distinct from c.location_id\n                                          then make_interval(mins => st.cover_travel_min) else interval '0' end\n     and o.ends_at + case when c2.location_id is distinct from c.location_id\n                          then make_interval(mins => st.cover_travel_min) else interval '0' end > cs.starts_at\n   order by o.starts_at;\n\n  -- The same person at other schools that share at least their busy times.\n  select sm.user_id into u from staff_member sm where sm.id = p_teacher and sm.studio_id = sid and sm.deleted_at is null;\n  if u is null then return; end if;\n  travel := make_interval(mins => coalesce((select agenda_travel_min from user_account where id = u), 30));\n  return query\n  select null::uuid, 'Busy at another school'::text, x.starts_at, x.ends_at, null::text, true\n    from app.agenda_rows(u, s0 - interval '1 day', e0 + interval '1 day') x\n   where x.studio_id <> sid and x.sharing in ('details', 'times') and x.status in ('scheduled', 'moved')\n     and x.starts_at < e0 + travel and x.ends_at + travel > s0\n   order by x.starts_at;\nend $$;\nrevoke all on function app.cover_clashes(uuid, uuid) from public;\ngrant execute on function app.cover_clashes(uuid, uuid) to authenticated, service_role;\n\n-- cover_session as in 0048; the clash test no longer relies on a session id\n-- (another school's busy time has none) and words that case as busy.\ncreate or replace function app.cover_session(p_session uuid, p_teacher uuid, p_message text default null,\n                                  p_notify_families boolean default false, p_handover text default null,\n                                  p_override boolean default false)\n  returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare cs record; who text; lbl text; u uuid; clash record; tz text;\nbegin\n  select s.*, c.teacher_id as class_teacher into cs from class_session s join class c on c.id = s.class_id\n   where s.id = p_session and s.deleted_at is null;\n  if cs.id is null then raise exception 'NOT_FOUND: session' using errcode = 'no_data_found'; end if;\n  if not app.is_admin(cs.studio_id) then raise exception 'FORBIDDEN: only the office can arrange cover' using errcode = 'insufficient_privilege'; end if;\n  if cs.status = 'cancelled' then raise exception 'INVALID: that class is cancelled' using errcode = 'check_violation'; end if;\n  if p_teacher is not null then\n    select display_name, user_id into who, u from staff_member\n     where id = p_teacher and studio_id = cs.studio_id and status = 'active' and deleted_at is null;\n    if who is null then raise exception 'INVALID: choose an active teacher at this school' using errcode = 'check_violation'; end if;\n    if not p_override then\n      select * into clash from app.cover_clashes(p_session, p_teacher) limit 1;\n      if found then\n        tz := (select timezone from studio where id = cs.studio_id);\n        if clash.session_id is null then\n          raise exception '%', 'CLASH: ' || who || ' is busy at another school from '\n            || to_char(clash.starts_at at time zone tz, 'HH24:MI') || ' to ' || to_char(clash.ends_at at time zone tz, 'HH24:MI')\n            || ', with time to travel'\n            using errcode = 'check_violation';\n        end if;\n        raise exception '%', 'CLASH: ' || who || ' teaches ' || clash.class_name || ' from '\n          || to_char(clash.starts_at at time zone tz, 'HH24:MI') || ' to ' || to_char(clash.ends_at at time zone tz, 'HH24:MI')\n          || coalesce(' at ' || clash.location, '')\n          || case when clash.needs_travel then ', a different site, so there is no time to travel' else '' end\n          using errcode = 'check_violation';\n      end if;\n    end if;\n    if p_teacher = cs.class_teacher then p_teacher := null; end if;   -- back to the usual teacher\n  end if;\n  lbl := app.session_label(p_session);\n  update class_session set teacher_id = p_teacher,\n         handover_note = coalesce(nullif(btrim(p_handover), ''), handover_note),\n         changed_at = now(), changed_by = auth.uid(), updated_at = now()\n   where id = p_session;\n  insert into audit_log (studio_id, actor_id, action, entity, entity_id, summary)\n  values (cs.studio_id, auth.uid(), 'cover', 'class_session', p_session,\n          lbl || coalesce(': covered by ' || who, ': back to the usual teacher')\n             || case when p_override then ' (clash accepted)' else '' end);\n  if p_teacher is not null then\n    perform app.notify_user(cs.studio_id, u, 'cover_assigned', 'You are covering ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), 'The register, safety notes and handover are on your Today screen on the day.'), '/teach');\n  end if;\n  if p_notify_families and p_teacher is not null then\n    perform app.announce_session(p_session, 'Cover: ' || lbl,\n      coalesce(nullif(btrim(p_message), ''), who || ' will be teaching ' || lbl || '.'));\n  end if;\n  update studio_request set status = 'answered', answer = coalesce('Covered by ' || who, 'No cover needed'),\n         answered_by = auth.uid(), answered_at = now()\n   where session_id = p_session and status in ('open', 'in_progress');\nend $$;\nrevoke all on function app.cover_session(uuid, uuid, text, boolean, text, boolean) from public;\ngrant execute on function app.cover_session(uuid, uuid, text, boolean, text, boolean) to authenticated, service_role;\n\n-- ── Calendar link: optionally every school (extends 0041 / 0050) ──────────\n-- A new link keeps the choice the old one had.\ncreate or replace function app.issue_calendar_token(p_studio uuid) returns text\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare tok text; r text; every boolean;\nbegin\n  r := case when app.is_staff(p_studio) then 'staff'\n            when exists (select 1 from guardian g where g.user_id = auth.uid() and g.studio_id = p_studio and g.deleted_at is null) then 'guardian'\n            when exists (select 1 from student s where s.user_id = auth.uid() and s.studio_id = p_studio and s.deleted_at is null) then 'student' end;\n  if auth.uid() is null or r is null then raise exception 'FORBIDDEN: not a member of that school' using errcode = 'insufficient_privilege'; end if;\n  select bool_or(all_schools) into every from calendar_token where user_id = auth.uid() and studio_id = p_studio and revoked_at is null;\n  update calendar_token set revoked_at = now() where user_id = auth.uid() and studio_id = p_studio and revoked_at is null;\n  tok := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');\n  insert into calendar_token (token, user_id, studio_id, role, all_schools)\n  values (tok, auth.uid(), p_studio, r, r = 'staff' and coalesce(every, false));\n  return tok;\nend $$;\n\ncreate or replace function app.set_calendar_all_schools(p_studio uuid, p_on boolean) returns void\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\nbegin\n  if auth.uid() is null or not app.is_staff(p_studio) then\n    raise exception 'FORBIDDEN: only staff calendars can include other schools' using errcode = 'insufficient_privilege';\n  end if;\n  update calendar_token set all_schools = coalesce(p_on, false)\n   where user_id = auth.uid() and studio_id = p_studio and revoked_at is null and role = 'staff';\nend $$;\nrevoke all on function app.set_calendar_all_schools(uuid, boolean) from public;\ngrant execute on function app.set_calendar_all_schools(uuid, boolean) to authenticated;\n\ncreate or replace function app.calendar_feed(p_token text)\n  returns table (uid text, title text, starts_at timestamptz, ends_at timestamptz, location text, status text, description text, calendar_name text)\n  language plpgsql security definer set search_path = public, app, pg_temp as $$\ndeclare t calendar_token; sname text; cname text;\nbegin\n  select * into t from calendar_token where token = p_token and revoked_at is null;\n  if t.token is null then raise exception 'NOT_FOUND: that calendar link has been replaced or turned off' using errcode = 'no_data_found'; end if;\n  update calendar_token set last_used_at = now() where token = p_token;\n  select name into sname from studio where id = t.studio_id;\n  if t.role = 'staff' then\n    cname := case when t.all_schools then 'Teaching, all schools' else sname end;\n    return query\n    select cs.id::text || '@sanaa', c.name, cs.starts_at, cs.ends_at,\n           nullif(concat_ws(', ', r.name, l.name, case when t.all_schools then sname end), ''),\n           case when cs.status = 'cancelled' then 'CANCELLED' else 'CONFIRMED' end,\n           case when cs.status = 'cancelled' then 'This class is cancelled.' else null end, cname\n      from class_session cs join class c on c.id = cs.class_id\n      join staff_member sm on sm.id = coalesce(cs.teacher_id, c.teacher_id)\n      left join room r on r.id = coalesce(cs.room_id, c.room_id)\n      left join location l on l.id = c.location_id\n     where sm.user_id = t.user_id and c.studio_id = t.studio_id and cs.deleted_at is null\n       and cs.starts_at between now() - interval '14 days' and now() + interval '120 days'\n    union all\n    -- Other schools, as each allows: details, or a busy block, or nothing.\n    select x.session_id::text || '@sanaa',\n           case when x.sharing = 'details' then x.class_name else 'Busy' end || ' — ' || x.school_name,\n           x.starts_at, x.ends_at,\n           case when x.sharing = 'details' then nullif(concat_ws(', ', x.room, x.location, x.school_name), '') else x.school_name end,\n           case when x.status = 'cancelled' then 'CANCELLED' else 'CONFIRMED' end,\n           case when x.status = 'cancelled' then 'This class is cancelled.' else null end, cname\n      from app.agenda_rows(t.user_id, now() - interval '14 days', now() + interval '120 days') x\n     where t.all_schools and x.studio_id <> t.studio_id and x.status <> 'covered'\n       and (x.sharing = 'details' or (x.sharing = 'times' and x.status in ('scheduled', 'moved')))\n     order by 3;\n    return;\n  end if;\n  return query\n  select d.uid || '@sanaa',\n         case d.item_kind when 'class' then '' when 'rehearsal' then 'Rehearsal: ' when 'exam' then 'Exam: '\n              when 'competition' then 'Competition: ' when 'show' then 'Show: ' when 'private_lesson' then ''\n              else initcap(replace(d.item_kind, '_', ' ')) || ': ' end\n           || d.title || coalesce(' — ' || string_agg(distinct d.child, ', '), ''),\n         d.starts_at, d.ends_at, d.location,\n         case when d.status = 'cancelled' then 'CANCELLED' else 'CONFIRMED' end,\n         case when d.status = 'cancelled' then 'This is cancelled.' else max(d.detail) end, sname\n    from app.diary_items(t.user_id, now() - interval '14 days', now() + interval '120 days') d\n   where d.studio_id = t.studio_id\n   group by d.uid, d.item_kind, d.title, d.starts_at, d.ends_at, d.location, d.status\n   order by d.starts_at;\nend $$;\n"}]])}]);